\set ON_ERROR_STOP on
set check_function_bodies = off;
set search_path = pg_catalog, public, extensions;

-- private.pay_workbench_draft_expected_effects_v1(uuid,text,text,jsonb,jsonb)
CREATE OR REPLACE FUNCTION private.pay_workbench_draft_expected_effects_v1(p_operation_id uuid, p_phase text, p_mode text, p_effects_json jsonb DEFAULT '[]'::jsonb, p_options_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_mode text := pg_catalog.upper(pg_catalog.btrim(COALESCE(p_mode,'')));
  v_phase text := pg_catalog.upper(pg_catalog.btrim(COALESCE(p_phase,'')));
  v_enabled boolean := false;
  v_batch_id uuid := NULL::uuid;
  v_operation public.banking_pay_operations%ROWTYPE;
  v_registered_count integer := 0;
  v_observed_count integer := 0;
  v_unmatched_count integer := 0;
  v_digest text := NULL::text;
BEGIN
  IF v_mode NOT IN ('REGISTER','ASSERT_COMPLETE','READ')
     OR v_phase NOT IN (
       'INSERT_ITEMS','APPLY_FINANCE_ADJUSTMENTS','FINALISE_RESERVATIONS',
       'CREATE_TIMESHEET_SNAPSHOTS','BUILD_ITEM_BREAKDOWNS'
     )
     OR pg_catalog.jsonb_typeof(COALESCE(p_effects_json,'[]'::jsonb)) <> 'array'
     OR pg_catalog.jsonb_typeof(COALESCE(p_options_json,'{}'::jsonb)) <> 'object' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DRAFT_EXPECTED_EFFECTS_ARGUMENT_INVALID'
      USING ERRCODE='22023';
  END IF;

  SELECT COALESCE(settings_row.banking_pay_draft_expected_effects_v1_enabled,false)
  INTO v_enabled
  FROM public.settings_defaults AS settings_row
  WHERE settings_row.id=1;

  IF COALESCE(v_enabled,false) IS NOT TRUE THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok',true,'enabled',false,'mode',v_mode,'phase',v_phase,
      'registered_count',0,'observed_count',0,'unmatched_count',0
    );
  END IF;

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DRAFT_EXPECTED_EFFECTS_OPERATION_REQUIRED'
      USING ERRCODE='22023';
  END IF;

  SELECT operation_row.*
  INTO v_operation
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id=p_operation_id
  FOR SHARE;

  IF NOT FOUND
     OR pg_catalog.upper(pg_catalog.btrim(COALESCE(v_operation.operation_type,''))) <> 'DRAFT_CREATE'
     OR pg_catalog.upper(pg_catalog.btrim(COALESCE(v_operation.status,''))) NOT IN ('QUEUED','RUNNING','PROCESSING','CLAIMED','IN_PROGRESS')
     OR v_operation.workbench_session_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DRAFT_EXPECTED_EFFECTS_OPERATION_INVALID'
      USING ERRCODE='23514',DETAIL=pg_catalog.jsonb_build_object(
        'operation_id',p_operation_id,'phase',v_phase
      )::text;
  END IF;

  v_batch_id := CASE
    WHEN COALESCE(p_options_json->>'pay_batch_id','')
      ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    THEN (p_options_json->>'pay_batch_id')::uuid
    ELSE v_operation.pay_batch_id
  END;

  IF v_batch_id IS NULL OR NOT EXISTS (
    SELECT 1
    FROM public.banking_pay_operation_candidate_scope AS scope_row
    WHERE scope_row.operation_id=p_operation_id
      AND scope_row.pay_batch_id=v_batch_id
      AND scope_row.status NOT IN ('FAILED','CANCELLED','SUPERSEDED')
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DRAFT_EXPECTED_EFFECTS_BATCH_SCOPE_INVALID'
      USING ERRCODE='23514',DETAIL=pg_catalog.jsonb_build_object(
        'operation_id',p_operation_id,'pay_batch_id',v_batch_id,'phase',v_phase
      )::text;
  END IF;

  CREATE TEMP TABLE IF NOT EXISTS pg_temp._bpay_wb_draft_expected_effect_context_v1(
    operation_id uuid PRIMARY KEY,
    pay_batch_id uuid NOT NULL,
    workbench_session_id uuid NOT NULL,
    phase text NOT NULL,
    backend_pid integer NOT NULL,
    transaction_id bigint NOT NULL,
    registered_at_utc timestamptz NOT NULL,
    expected_effects_json jsonb NOT NULL,
    context_token text NOT NULL
  ) ON COMMIT DROP;

  CREATE TEMP TABLE IF NOT EXISTS pg_temp._bpay_wb_draft_observed_effects_v1(
    operation_id uuid NOT NULL,
    pay_batch_id uuid NOT NULL,
    phase text NOT NULL,
    relation_name text NOT NULL,
    operation text NOT NULL,
    source_id uuid NOT NULL,
    candidate_id uuid NOT NULL,
    timesheet_id uuid NULL,
    before_digest text NULL,
    after_digest text NULL,
    matched boolean NOT NULL,
    observed_at_utc timestamptz NOT NULL,
    PRIMARY KEY(operation_id,phase,relation_name,operation,source_id,candidate_id)
  ) ON COMMIT DROP;

  IF v_mode='REGISTER' THEN
    IF EXISTS (
      SELECT 1
      FROM pg_catalog.jsonb_array_elements(COALESCE(p_effects_json,'[]'::jsonb)) AS effect(value)
      WHERE pg_catalog.jsonb_typeof(effect.value)<>'object'
         OR pg_catalog.upper(pg_catalog.btrim(COALESCE(effect.value->>'operation',''))) NOT IN ('INSERT','UPDATE','DELETE')
         OR pg_catalog.lower(pg_catalog.btrim(COALESCE(effect.value->>'relation_name',''))) NOT IN (
           'pay_batch_items','pay_batch_item_breakdowns','pay_batch_timesheet_snapshots',
           'pay_batch_candidates',
           'pay_advances','pay_finance_case_components','pay_finance_case_events',
           'pay_advance_reservations'
         )
    ) THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_DRAFT_EXPECTED_EFFECTS_DESCRIPTOR_INVALID'
        USING ERRCODE='22023';
    END IF;

    TRUNCATE pg_temp._bpay_wb_draft_expected_effect_context_v1;
    TRUNCATE pg_temp._bpay_wb_draft_observed_effects_v1;

    v_digest := pg_catalog.md5(
      p_operation_id::text||'|'||v_batch_id::text||'|'||v_phase||'|'||
      pg_catalog.pg_backend_pid()::text||'|'||pg_catalog.txid_current()::text||'|'||
      COALESCE(p_effects_json,'[]'::jsonb)::text||'|DRAFT_EXPECTED_EFFECTS_V1'
    );

    INSERT INTO pg_temp._bpay_wb_draft_expected_effect_context_v1(
      operation_id,pay_batch_id,workbench_session_id,phase,backend_pid,
      transaction_id,registered_at_utc,expected_effects_json,context_token
    ) VALUES (
      p_operation_id,v_batch_id,v_operation.workbench_session_id,v_phase,
      pg_catalog.pg_backend_pid(),pg_catalog.txid_current(),pg_catalog.clock_timestamp(),
      COALESCE(p_effects_json,'[]'::jsonb),v_digest
    );

    SELECT pg_catalog.jsonb_array_length(COALESCE(p_effects_json,'[]'::jsonb))
    INTO v_registered_count;

    RETURN pg_catalog.jsonb_build_object(
      'ok',true,'enabled',true,'mode',v_mode,'phase',v_phase,
      'operation_id',p_operation_id,'pay_batch_id',v_batch_id,
      'registered_count',v_registered_count,'context_token',v_digest
    );
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM pg_temp._bpay_wb_draft_expected_effect_context_v1 AS context_row
    WHERE context_row.operation_id=p_operation_id
      AND context_row.pay_batch_id=v_batch_id
      AND context_row.phase=v_phase
      AND context_row.backend_pid=pg_catalog.pg_backend_pid()
      AND context_row.transaction_id=pg_catalog.txid_current()
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DRAFT_EXPECTED_EFFECTS_CONTEXT_MISSING'
      USING ERRCODE='23514';
  END IF;

  SELECT pg_catalog.count(*)::integer,
         pg_catalog.count(*) FILTER (WHERE observed.matched IS NOT TRUE)::integer,
         pg_catalog.md5(COALESCE(pg_catalog.string_agg(
           observed.relation_name||':'||observed.operation||':'||observed.source_id::text||':'||
           observed.candidate_id::text||':'||COALESCE(observed.before_digest,'')||':'||
           COALESCE(observed.after_digest,''),
           '|' ORDER BY observed.relation_name,observed.operation,observed.source_id,observed.candidate_id
         ),''))
  INTO v_observed_count,v_unmatched_count,v_digest
  FROM pg_temp._bpay_wb_draft_observed_effects_v1 AS observed
  WHERE observed.operation_id=p_operation_id AND observed.phase=v_phase;

  IF v_mode='ASSERT_COMPLETE' AND COALESCE(v_unmatched_count,0)>0 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_DRAFT_EXPECTED_EFFECT_MISMATCH'
      USING ERRCODE='23514',DETAIL=pg_catalog.jsonb_build_object(
        'operation_id',p_operation_id,'pay_batch_id',v_batch_id,'phase',v_phase,
        'observed_count',v_observed_count,'unmatched_count',v_unmatched_count
      )::text;
  END IF;

  IF v_mode='ASSERT_COMPLETE' THEN
    UPDATE public.banking_pay_operations AS operation_row
    SET progress_json = COALESCE(operation_row.progress_json,'{}'::jsonb)
      || pg_catalog.jsonb_build_object(
        'draft_expected_effects_v1',
        COALESCE(operation_row.progress_json->'draft_expected_effects_v1','{}'::jsonb)
          || pg_catalog.jsonb_build_object(
            pg_catalog.lower(v_phase),
            pg_catalog.jsonb_build_object(
              'phase',v_phase,
              'observed_count',COALESCE(v_observed_count,0),
              'unmatched_count',COALESCE(v_unmatched_count,0),
              'observed_effect_digest',v_digest,
              'completed',true,
              'completed_at_utc',pg_catalog.clock_timestamp()
            )
          )
      ),
      updated_at_utc=pg_catalog.clock_timestamp()
    WHERE operation_row.id=p_operation_id;
  END IF;

  RETURN pg_catalog.jsonb_build_object(
    'ok',true,'enabled',true,'mode',v_mode,'phase',v_phase,
    'operation_id',p_operation_id,'pay_batch_id',v_batch_id,
    'observed_count',COALESCE(v_observed_count,0),
    'unmatched_count',COALESCE(v_unmatched_count,0),
    'observed_effect_digest',v_digest,
    'context_token',(
      SELECT context_row.context_token
      FROM pg_temp._bpay_wb_draft_expected_effect_context_v1 AS context_row
      WHERE context_row.operation_id=p_operation_id
    )
  );
END;
$function$;

-- private.pay_workbench_draft_finance_item_plan_v1(uuid,jsonb)
CREATE OR REPLACE FUNCTION private.pay_workbench_draft_finance_item_plan_v1(p_operation_id uuid, p_candidate_scope_ids jsonb)
 RETURNS TABLE(operation_id uuid, candidate_scope_id uuid, pay_batch_id uuid, candidate_id uuid, pay_channel text, allocation_source_key text, planned_item_key text, planned_item_type text, finance_case_id uuid, finance_component_id uuid, contribution_amount numeric, planned_item_amount numeric, contribution_count integer, plan_digest text, plan_basis_json jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_scope_count integer := 0;
BEGIN
  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION 'pay_workbench_draft_finance_item_plan_v1: p_operation_id is required';
  END IF;

  IF p_candidate_scope_ids IS NULL OR pg_catalog.jsonb_typeof(p_candidate_scope_ids) <> 'array' THEN
    RAISE EXCEPTION 'pay_workbench_draft_finance_item_plan_v1 requires a JSON array of candidate scope ids';
  END IF;

  v_scope_count := pg_catalog.jsonb_array_length(p_candidate_scope_ids);
  IF v_scope_count = 0 OR v_scope_count > 100 THEN
    RAISE EXCEPTION 'pay_workbench_draft_finance_item_plan_v1 candidate scope count must be between 1 and 100, got %', v_scope_count;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_catalog.jsonb_array_elements_text(p_candidate_scope_ids) AS supplied(scope_id_text)
    WHERE supplied.scope_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) THEN
    RAISE EXCEPTION 'pay_workbench_draft_finance_item_plan_v1 requires candidate scope ids to be UUID strings';
  END IF;

  RETURN QUERY
  WITH scoped_rows AS (
    SELECT allocation_row.*,
           CASE pg_catalog.upper(pg_catalog.btrim(COALESCE(allocation_row.allocation_type, '')))
             WHEN 'OVERPAYMENT_RECOVERY' THEN 'OVERPAYMENT_RECOVERY'
             WHEN 'UNDERPAYMENT_PAYMENT' THEN 'UNDERPAYMENT_PAYMENT'
             WHEN 'MANUAL_DEBT_RECOVERY' THEN 'MANUAL_DEBT_RECOVERY'
             WHEN 'PAYMENT_ADVANCE_REPAYMENT' THEN 'LOAN_REPAYMENT'
             WHEN 'LOAN_REPAYMENT' THEN 'LOAN_REPAYMENT'
             WHEN 'MANUAL_CREDIT_ADJUSTMENT_PAYMENT' THEN 'MANUAL_CREDIT_PAYOUT'
             WHEN 'MANUAL_CREDIT_PAYOUT' THEN 'MANUAL_CREDIT_PAYOUT'
             WHEN 'LOAN_PAYOUT' THEN 'LOAN_PAYOUT'
             ELSE NULL::text
           END AS effective_item_type
    FROM public.banking_pay_operation_candidate_allocation_rows AS allocation_row
    WHERE allocation_row.operation_id = p_operation_id
      AND allocation_row.candidate_scope_id IN (
        SELECT supplied.scope_id_text::uuid
        FROM pg_catalog.jsonb_array_elements_text(p_candidate_scope_ids) AS supplied(scope_id_text)
      )
      AND allocation_row.finance_case_id IS NOT NULL
  ), keyed_rows AS (
    SELECT scoped_row.*,
           scoped_row.operation_source_key AS effective_planned_item_key
    FROM scoped_rows AS scoped_row
    WHERE scoped_row.effective_item_type = 'OVERPAYMENT_RECOVERY'
      AND pg_catalog.round(COALESCE(scoped_row.allocated_amount, 0), 2) <> 0
      AND NULLIF(pg_catalog.btrim(COALESCE(scoped_row.operation_source_key, '')), '') IS NOT NULL
  )
  SELECT
    keyed_row.operation_id,
    keyed_row.candidate_scope_id,
    keyed_row.pay_batch_id,
    keyed_row.candidate_id,
    pg_catalog.upper(pg_catalog.btrim(COALESCE(keyed_row.pay_channel, ''))) AS pay_channel,
    keyed_row.operation_source_key AS allocation_source_key,
    keyed_row.effective_planned_item_key AS planned_item_key,
    keyed_row.effective_item_type AS planned_item_type,
    keyed_row.finance_case_id,
    keyed_row.finance_component_id,
    pg_catalog.round(keyed_row.allocated_amount, 2) AS contribution_amount,
    pg_catalog.round(keyed_row.allocated_amount, 2) AS planned_item_amount,
    1::integer AS contribution_count,
    private.pay_payment_correction_sha256_v1(
      pg_catalog.jsonb_build_object(
        'contract_version', 1,
        'planned_item_key', keyed_row.effective_planned_item_key,
        'planned_item_type', keyed_row.effective_item_type,
        'contribution_amount', pg_catalog.round(keyed_row.allocated_amount, 2),
        'allocation_source_key', keyed_row.operation_source_key,
        'allocation_basis_json', COALESCE(keyed_row.allocation_basis_json, '{}'::jsonb) - 'draft_finance_item_plan'
      )
    ) AS plan_digest,
    COALESCE(keyed_row.allocation_basis_json, '{}'::jsonb) - 'draft_finance_item_plan' AS plan_basis_json
  FROM keyed_rows AS keyed_row
  ORDER BY keyed_row.candidate_id, keyed_row.pay_channel, keyed_row.operation_source_key;
END;
$function$;

-- private.pay_workbench_draft_overlay_remove_page_v1(uuid,uuid,uuid,uuid,integer,integer,uuid,jsonb)
CREATE OR REPLACE FUNCTION private.pay_workbench_draft_overlay_remove_page_v1(p_correction_request_id uuid, p_pay_batch_id uuid, p_session_id uuid, p_after_candidate_id uuid DEFAULT NULL::uuid, p_candidate_limit integer DEFAULT 100, p_finance_row_limit integer DEFAULT 500, p_actor_user_id uuid DEFAULT NULL::uuid, p_options_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_batch public.pay_batches%ROWTYPE;
  v_candidate_count integer := 0;
  v_item_count integer := 0;
  v_reservation_count integer := 0;
  v_last_candidate_id uuid := p_after_candidate_id;
  v_has_more boolean := false;
  v_candidate_ids jsonb := '[]'::jsonb;
  v_item_ids jsonb := '[]'::jsonb;
  v_patch jsonb := '{}'::jsonb;
  v_operation_id uuid := NULL::uuid;
  v_admission jsonb := '{}'::jsonb;
  v_admitted_count integer := 0;
  v_reversion_descriptors jsonb := '[]'::jsonb;
  v_publication jsonb := '{}'::jsonb;
  v_candidate_lock record;
BEGIN
  IF p_correction_request_id IS NULL OR p_pay_batch_id IS NULL OR p_session_id IS NULL
     OR p_candidate_limit IS NULL OR p_candidate_limit<1 OR p_candidate_limit>100
     OR p_finance_row_limit IS NULL OR p_finance_row_limit<1 OR p_finance_row_limit>500
     OR pg_catalog.jsonb_typeof(COALESCE(p_options_json,'{}'::jsonb))<>'object' THEN
    RAISE EXCEPTION 'DRAFT_OVERLAY_FAST_ARGUMENT_INVALID' USING ERRCODE='P0001';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtext('PAYMENT_DRAFT_OVERLAY_FAST_CANCEL'),
    pg_catalog.hashtext(p_pay_batch_id::text)
  );

  SELECT batch_row.* INTO v_batch
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id=p_pay_batch_id
  FOR UPDATE;

  IF NOT FOUND
     OR pg_catalog.upper(pg_catalog.btrim(COALESCE(v_batch.status,''))) NOT IN ('DRAFT','DRAFT_CREATED','CANCELLED')
     OR pg_catalog.upper(pg_catalog.btrim(COALESCE(v_batch.execution_commit_state,'NOT_SUBMITTED'))) <> 'NOT_SUBMITTED'
     OR NULLIF(pg_catalog.btrim(COALESCE(v_batch.execution_commit_ref,'')),'') IS NOT NULL
     OR v_batch.execution_committed_at_utc IS NOT NULL
     OR EXISTS (
       SELECT 1 FROM public.banking_pay_operations AS unsafe_operation
       WHERE unsafe_operation.pay_batch_id=p_pay_batch_id
         AND unsafe_operation.operation_type IN ('PAYMENT_EXECUTE','PAYMENT_SETTLEMENT','REMITTANCE_QUEUE')
         AND unsafe_operation.status IN (
           'QUEUED','RUNNING','PROCESSING','CLAIMED','IN_PROGRESS','COMPLETE','COMPLETED','SUCCEEDED'
         )
     ) THEN
    -- Admission is deliberately before every Draft mutation.  A batch that is
    -- no longer untouched is not a failed cancellation: it must return a typed
    -- fast-route rejection so pay_payment_correction_expand_work can fall
    -- through to the existing frozen financial correction owner.  Provider,
    -- rail, settlement and Policy X checks remain with that safe fallback.
    RETURN pg_catalog.jsonb_build_object(
      'ok',true,
      'status','DRAFT_OVERLAY_FAST_REJECTED',
      'code','DRAFT_OVERLAY_FAST_NOT_UNTOUCHED',
      'pay_batch_id',p_pay_batch_id,
      'fast_route_eligible',false,
      'mutation_applied',false,
      'financial_work_item_count',0,
      'full_build_count',0,
      'reconciliation_count',0,
      'policy_x_authority_scope','POST_DRAFT_FROZEN_FINANCIAL_FALLBACK_REQUIRED'
    );
  END IF;

  SELECT operation_row.id
  INTO v_operation_id
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.operation_type='PAYMENT_CORRECTION'
    AND operation_row.pay_batch_id=p_pay_batch_id
    AND operation_row.input_json->>'correction_request_id'=p_correction_request_id::text
  ORDER BY operation_row.created_at_utc
  LIMIT 1;

  IF v_operation_id IS NULL THEN
    RAISE EXCEPTION 'DRAFT_OVERLAY_FAST_OPERATION_MISSING'
      USING ERRCODE='P0001',DETAIL=pg_catalog.jsonb_build_object(
        'code','DRAFT_OVERLAY_FAST_OPERATION_MISSING','correction_request_id',p_correction_request_id
      )::text;
  END IF;

  DROP TABLE IF EXISTS pg_temp._bpay_draft_overlay_candidate_page;
  CREATE TEMP TABLE pg_temp._bpay_draft_overlay_candidate_page ON COMMIT DROP AS
  SELECT request_candidate.pay_batch_candidate_id,candidate_row.candidate_id
  FROM public.pay_payment_correction_request_candidates AS request_candidate
  JOIN public.pay_batch_candidates AS candidate_row
    ON candidate_row.id=request_candidate.pay_batch_candidate_id
   AND candidate_row.pay_batch_id=p_pay_batch_id
  WHERE request_candidate.correction_request_id=p_correction_request_id
    AND (p_after_candidate_id IS NULL OR candidate_row.candidate_id>p_after_candidate_id)
  ORDER BY candidate_row.candidate_id
  LIMIT p_candidate_limit;

  SELECT pg_catalog.count(*)::integer,
         pg_catalog.max(candidate_page.candidate_id::text)::uuid,
         COALESCE(pg_catalog.jsonb_agg(candidate_page.candidate_id::text
           ORDER BY candidate_page.candidate_id),'[]'::jsonb)
  INTO v_candidate_count,v_last_candidate_id,v_candidate_ids
  FROM pg_temp._bpay_draft_overlay_candidate_page AS candidate_page;

  IF v_candidate_count=0 THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok',true,'status','DRAFT_OVERLAY_FAST_COMPLETE','candidate_count',0,
      'has_more',false,'full_build_count',0,'reconciliation_count',0
    );
  END IF;

  -- Complete the global lock prefix before reading the frozen/live fence.
  FOR v_candidate_lock IN
    SELECT candidate_page.candidate_id
    FROM pg_temp._bpay_draft_overlay_candidate_page AS candidate_page
    ORDER BY candidate_page.candidate_id
  LOOP
    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        public._pay_workbench_candidate_serial_key(v_candidate_lock.candidate_id),
        24062027
      )
    );
  END LOOP;

  v_admission := private.pay_workbench_cancel_reversion_admission_page_v1(
    p_correction_request_id,v_operation_id,p_session_id,ARRAY[]::uuid[],
    pg_catalog.jsonb_build_object(
      'mode','DRAFT_OVERLAY_PREFLIGHT','candidate_ids',v_candidate_ids
    )
  );
  v_admitted_count := COALESCE((v_admission->>'admitted_count')::integer,0);

  IF v_admitted_count IS DISTINCT FROM v_candidate_count THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok',true,'status','DRAFT_OVERLAY_FAST_REJECTED','fast_route_eligible',false,
      'candidate_count',v_candidate_count,'candidate_ids',v_candidate_ids,
      'admission',v_admission,'has_more',false,'full_build_count',0,
      'reconciliation_count',0,'financial_work_item_count',0,
      'policy_x_authority_scope','SAFE_FALLBACK_BEFORE_DRAFT_MUTATION'
    );
  END IF;

  IF (
    SELECT pg_catalog.count(*)
    FROM public.pay_batch_items AS item_row
    JOIN pg_temp._bpay_draft_overlay_candidate_page AS candidate_page
      ON candidate_page.pay_batch_candidate_id=item_row.pay_batch_candidate_id
    WHERE COALESCE(item_row.is_voided,false) IS NOT TRUE
  ) > p_finance_row_limit THEN
    RAISE EXCEPTION 'DRAFT_OVERLAY_FAST_FINANCE_ROW_LIMIT'
      USING ERRCODE='P0001',DETAIL=pg_catalog.jsonb_build_object(
        'code','DRAFT_OVERLAY_FAST_FINANCE_ROW_LIMIT','limit',p_finance_row_limit
      )::text;
  END IF;

  WITH voided AS (
    UPDATE public.pay_batch_items AS item_row
    SET is_voided=true,updated_at=v_now
    FROM pg_temp._bpay_draft_overlay_candidate_page AS candidate_page
    WHERE item_row.pay_batch_candidate_id=candidate_page.pay_batch_candidate_id
      AND COALESCE(item_row.is_voided,false) IS NOT TRUE
    RETURNING item_row.id
  )
  SELECT pg_catalog.count(*)::integer,
         COALESCE(pg_catalog.jsonb_agg(voided.id::text ORDER BY voided.id),'[]'::jsonb)
  INTO v_item_count,v_item_ids FROM voided;

  WITH released AS (
    UPDATE public.pay_advance_reservations AS reservation_row
    SET status='RELEASED',released_at_utc=COALESCE(reservation_row.released_at_utc,v_now),
        released_reason='DRAFT_OVERLAY_FAST_CANCEL',updated_by_user_id=p_actor_user_id
    FROM pg_temp._bpay_draft_overlay_candidate_page AS candidate_page
    WHERE reservation_row.pay_batch_id=p_pay_batch_id
      AND reservation_row.pay_batch_candidate_id=candidate_page.pay_batch_candidate_id
      AND pg_catalog.upper(pg_catalog.btrim(COALESCE(reservation_row.status,'')))='RESERVED'
    RETURNING reservation_row.id
  ) SELECT pg_catalog.count(*)::integer INTO v_reservation_count FROM released;

  UPDATE public.pay_batch_candidates AS candidate_row
  SET gross_preview=0,net_bank_amount=0,debt_created=0,
      loan_repayment_taken=0,overpayment_recovery_taken=0,
      awaiting_net_amount=false,updated_at=v_now
  FROM pg_temp._bpay_draft_overlay_candidate_page AS candidate_page
  WHERE candidate_row.id=candidate_page.pay_batch_candidate_id;

  v_patch := public.pay_workbench_patch_preview_after_batch_mutation(
    p_session_id,p_pay_batch_id,'DRAFT_CANCEL',p_actor_user_id,
    pg_catalog.jsonb_build_object(
      'candidate_ids',v_candidate_ids,
      'changed_pay_batch_item_ids',v_item_ids,
      'defer_complex_enqueue',true,
      'maximum_candidate_count',p_candidate_limit
    )
  );

  IF COALESCE((v_patch->>'ok')::boolean,false) IS NOT TRUE THEN
    RAISE EXCEPTION 'DRAFT_OVERLAY_FAST_WORKBENCH_PATCH_FAILED'
      USING ERRCODE='P0001',DETAIL=pg_catalog.jsonb_build_object(
        'code','DRAFT_OVERLAY_FAST_WORKBENCH_PATCH_FAILED','patch',v_patch
      )::text;
  END IF;

  v_has_more := EXISTS (
    SELECT 1
    FROM public.pay_payment_correction_request_candidates AS request_candidate
    JOIN public.pay_batch_candidates AS candidate_row
      ON candidate_row.id=request_candidate.pay_batch_candidate_id
     AND candidate_row.pay_batch_id=p_pay_batch_id
    WHERE request_candidate.correction_request_id=p_correction_request_id
      AND candidate_row.candidate_id>v_last_candidate_id
  );

  -- Certified cancellation reversion must be the final economic authority in
  -- this transaction.  On the terminal page, apply every request/batch
  -- lifecycle transition first so their ordinary request-owned dirty evidence
  -- is reflected in the live source sequence and generation used below.  The
  -- caller's later APPLIED write is status-idempotent and therefore cannot
  -- create a newer financial-scope transition after publication.
  IF NOT v_has_more THEN
    UPDATE public.pay_payment_correction_requests AS request_row
    SET status='APPLIED',
        applied_at_utc=COALESCE(request_row.applied_at_utc,v_now),
        updated_at_utc=v_now
    WHERE request_row.id=p_correction_request_id;

    UPDATE public.pay_batches AS batch_row
    SET status='CANCELLED',cancelled_at_utc=COALESCE(batch_row.cancelled_at_utc,v_now),
        cancelled_by_user_id=COALESCE(batch_row.cancelled_by_user_id,p_actor_user_id),
        cancel_reason=COALESCE(batch_row.cancel_reason,'DRAFT_OVERLAY_FAST_CANCEL'),
        total_bank_out=0,total_debt_created=0
    WHERE batch_row.id=p_pay_batch_id;
  END IF;

  WITH admitted AS (
    SELECT result_row.value,
           change_counter.seq AS current_source_change_seq,
           change_counter.scope_change_generation AS current_dirty_generation,
           pg_catalog.md5(
             p_correction_request_id::text||':'||(result_row.value->>'candidate_id')||':'||
             v_operation_id::text||':'||change_counter.seq::text||':'||
             change_counter.scope_change_generation::text||':DRAFT_OVERLAY_FAST_V1'
           ) AS run_hash,
           pg_catalog.md5(
             COALESCE(result_row.value->>'post_draft_authority_digest','')||'|'||
             p_correction_request_id::text||'|'||(result_row.value->>'candidate_id')||'|'||
             change_counter.seq::text||'|'||change_counter.scope_change_generation::text||'|'||
             COALESCE(item_proof.item_digest,'')||'|'||COALESCE(reservation_proof.reservation_digest,'')||
             '|DRAFT_OVERLAY_FAST_REVERSION_V1'
           ) AS reversion_digest
    FROM pg_catalog.jsonb_array_elements(
      COALESCE(v_admission->'candidate_results','[]'::jsonb)
    ) AS result_row(value)
    JOIN public.app_change_counters AS change_counter
      ON change_counter.entity_key='pay_candidate:'||(result_row.value->>'candidate_id')
    LEFT JOIN LATERAL (
      SELECT pg_catalog.md5(COALESCE(pg_catalog.string_agg(
        item_row.id::text||':'||COALESCE(item_row.is_voided,false)::text,
        '|' ORDER BY item_row.id
      ),'')) AS item_digest
      FROM public.pay_batch_items AS item_row
      JOIN public.pay_batch_candidates AS batch_candidate
        ON batch_candidate.id=item_row.pay_batch_candidate_id
      WHERE batch_candidate.pay_batch_id=p_pay_batch_id
        AND batch_candidate.candidate_id=(result_row.value->>'candidate_id')::uuid
    ) AS item_proof ON true
    LEFT JOIN LATERAL (
      SELECT pg_catalog.md5(COALESCE(pg_catalog.string_agg(
        reservation_row.id::text||':'||COALESCE(reservation_row.status,''),
        '|' ORDER BY reservation_row.id
      ),'')) AS reservation_digest
      FROM public.pay_advance_reservations AS reservation_row
      JOIN public.pay_batch_candidates AS batch_candidate
        ON batch_candidate.id=reservation_row.pay_batch_candidate_id
      WHERE reservation_row.pay_batch_id=p_pay_batch_id
        AND batch_candidate.candidate_id=(result_row.value->>'candidate_id')::uuid
    ) AS reservation_proof ON true
    WHERE COALESCE((result_row.value->>'admitted')::boolean,false)
  ), descriptors AS (
    SELECT pg_catalog.jsonb_build_object(
      'candidate_id',admitted.value->>'candidate_id',
      'economic_build_id',admitted.value->>'original_economic_build_id',
      'source_build_run_id',pg_catalog.substr(admitted.run_hash,1,8)||'-'||
        pg_catalog.substr(admitted.run_hash,9,4)||'-'||pg_catalog.substr(admitted.run_hash,13,4)||'-'||
        pg_catalog.substr(admitted.run_hash,17,4)||'-'||pg_catalog.substr(admitted.run_hash,21,12),
      'source_change_seq',admitted.current_source_change_seq,
      'source_identity_digest',admitted.value->>'source_identity_digest',
      'session_version',admitted.value->>'session_version',
      'completion_job_id',v_operation_id,
      'refresh_scope_kind','CANDIDATE_FULL_LIVE',
      'publication_options_json',pg_catalog.jsonb_build_object(
        'contract_version',3,'semantic_contract_version','READY_TO_PAY_SEMANTIC_V2',
        'authority_kind','CERTIFIED_CANCELLATION_REVERSION',
        'invocation_kind','CANCELLATION_REVERSION_FINALISE','final_state',
          CASE WHEN COALESCE((admitted.value->>'source_count')::integer,0)=0
            THEN 'SOURCE_EMPTY' ELSE 'READY' END,
        'source_session_id',p_session_id,
        'original_economic_build_id',admitted.value->>'original_economic_build_id',
        'original_source_build_run_id',admitted.value->>'original_source_build_run_id',
        'replay_source_build_run_id',admitted.value->>'replay_source_build_run_id',
        'original_source_publication_id',admitted.value->>'original_source_publication_id',
        'cancellation_request_id',p_correction_request_id,
        'cancellation_operation_id',v_operation_id,
        'pay_batch_id',p_pay_batch_id,
        'cancellation_reversion_run_id',pg_catalog.substr(admitted.run_hash,1,8)||'-'||
          pg_catalog.substr(admitted.run_hash,9,4)||'-'||pg_catalog.substr(admitted.run_hash,13,4)||'-'||
          pg_catalog.substr(admitted.run_hash,17,4)||'-'||pg_catalog.substr(admitted.run_hash,21,12),
        'cancellation_route','DRAFT_OVERLAY_FAST',
        'financial_reversion_digest',admitted.reversion_digest,
        'original_semantic_proof_digest',admitted.value->>'semantic_proof_digest',
        'source_count',admitted.value->>'source_count'
      )
    ) AS descriptor
    FROM admitted
  )
  SELECT COALESCE(pg_catalog.jsonb_agg(descriptors.descriptor
    ORDER BY descriptors.descriptor->>'candidate_id'),'[]'::jsonb)
  INTO v_reversion_descriptors
  FROM descriptors;

  IF pg_catalog.jsonb_array_length(v_reversion_descriptors) IS DISTINCT FROM v_candidate_count THEN
    RAISE EXCEPTION 'DRAFT_OVERLAY_FAST_REVERSION_DESCRIPTOR_MISMATCH'
      USING ERRCODE='P0001',DETAIL=pg_catalog.jsonb_build_object(
        'code','DRAFT_OVERLAY_FAST_REVERSION_DESCRIPTOR_MISMATCH'
      )::text;
  END IF;

  v_publication := private.pay_workbench_publish_certified_source_preview_page_v1(
    p_session_id,v_reversion_descriptors,'{}'::jsonb
  );

  IF COALESCE((v_publication->>'ok')::boolean,false) IS NOT TRUE
     OR COALESCE((v_publication->>'candidate_count')::integer,0) IS DISTINCT FROM v_candidate_count THEN
    RAISE EXCEPTION 'DRAFT_OVERLAY_FAST_REVERSION_PUBLICATION_FAILED'
      USING ERRCODE='P0001',DETAIL=pg_catalog.jsonb_build_object(
        'code','DRAFT_OVERLAY_FAST_REVERSION_PUBLICATION_FAILED'
      )::text;
  END IF;

  RETURN pg_catalog.jsonb_build_object(
    'ok',true,'status',CASE WHEN v_has_more THEN 'DRAFT_OVERLAY_FAST_PAGE' ELSE 'DRAFT_OVERLAY_FAST_COMPLETE' END,
    'candidate_count',v_candidate_count,'voided_item_count',v_item_count,
    'released_reservation_count',v_reservation_count,'candidate_ids',v_candidate_ids,
    'last_candidate_id',v_last_candidate_id,'has_more',v_has_more,
    'fast_route_eligible',true,'admission',v_admission,
    'workbench_patch',v_patch,'reversion_publication',v_publication,
    'financial_work_item_count',0,
    'full_build_count',0,'reconciliation_count',0,
    'policy_x_authority_scope','POST_DRAFT_FROZEN_OVERLAY_REMOVAL'
  );
END;
$function$;

-- private.pay_workbench_exact_import_family_admission_v1(uuid,uuid,uuid[],bigint)
CREATE OR REPLACE FUNCTION private.pay_workbench_exact_import_family_admission_v1(p_session_id uuid, p_candidate_id uuid, p_seed_timesheet_ids uuid[], p_source_change_seq bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_settings public.settings_defaults%ROWTYPE;
  v_seeds uuid[]:=ARRAY[]::uuid[];
  v_family uuid[]:=ARRAY[]::uuid[];
  v_closure jsonb:='{}'::jsonb;
  v_route_count integer:=0;
  v_route text:=NULL::text;
  v_member_count integer:=0;
  v_bad_count integer:=0;
  v_evidence_count integer:=0;
  v_occurrence_count integer:=0;
  v_tsfin_digest text:=NULL::text;
  v_occurrence_digest text:=NULL::text;
BEGIN
  IF p_session_id IS NULL OR p_candidate_id IS NULL OR p_source_change_seq IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('ok',true,'admitted',false,'reason','EXACT_IMPORT_ARGUMENT_REQUIRED');
  END IF;

  SELECT settings_row.* INTO v_settings
  FROM public.settings_defaults AS settings_row WHERE settings_row.id=1;
  IF coalesce(v_settings.banking_pay_workbench_delta_enable_exact_import_family,false) IS NOT TRUE THEN
    RETURN pg_catalog.jsonb_build_object('ok',true,'admitted',false,'reason','EXACT_IMPORT_FAMILY_DISABLED');
  END IF;

  SELECT coalesce(pg_catalog.array_agg(DISTINCT seed ORDER BY seed),ARRAY[]::uuid[])
  INTO v_seeds
  FROM pg_catalog.unnest(coalesce(p_seed_timesheet_ids,ARRAY[]::uuid[])) AS seed
  WHERE seed IS NOT NULL;

  IF coalesce(pg_catalog.array_length(v_seeds,1),0)=0
     OR pg_catalog.array_length(v_seeds,1)>250 THEN
    RETURN pg_catalog.jsonb_build_object('ok',true,'admitted',false,'reason','EXACT_IMPORT_SEED_INVALID');
  END IF;

  v_closure:=public._pay_workbench_refresh_dependency_closure_v1(
    p_candidate_id,v_seeds,ARRAY[]::uuid[],ARRAY[]::uuid[],250,100
  );
  IF coalesce((v_closure->>'coverage_complete')::boolean,false) IS NOT TRUE
     OR coalesce((v_closure->>'requires_full_candidate')::boolean,true) THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok',true,'admitted',false,
      'reason',coalesce(NULLIF(v_closure->>'fallback_reason',''),'EXACT_IMPORT_FAMILY_INCOMPLETE')
    );
  END IF;

  SELECT coalesce(pg_catalog.array_agg(DISTINCT value::uuid ORDER BY value::uuid),ARRAY[]::uuid[])
  INTO v_family
  FROM pg_catalog.jsonb_array_elements_text(
    coalesce(v_closure->'effective_targeted_timesheet_ids','[]'::jsonb)
  ) AS family_value(value)
  WHERE value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

  IF coalesce(pg_catalog.array_length(v_family,1),0)=0
     OR pg_catalog.array_length(v_family,1)>250 THEN
    RETURN pg_catalog.jsonb_build_object('ok',true,'admitted',false,'reason','EXACT_IMPORT_FAMILY_INVALID');
  END IF;

  SELECT pg_catalog.count(*)::integer,
         pg_catalog.count(DISTINCT pg_catalog.upper(contract_row.weekly_timesheet_source::text))::integer,
         pg_catalog.min(pg_catalog.upper(contract_row.weekly_timesheet_source::text))
  INTO v_member_count,v_route_count,v_route
  FROM public.timesheets AS timesheet_row
  JOIN public.contracts AS contract_row ON contract_row.id=timesheet_row.contract_id
  WHERE timesheet_row.timesheet_id=ANY(v_family)
    AND timesheet_row.is_current IS TRUE
    AND contract_row.candidate_id=p_candidate_id
    AND pg_catalog.upper(contract_row.weekly_timesheet_source::text) IN ('NHSP','HEALTHROSTER');

  IF v_member_count<>pg_catalog.array_length(v_family,1) OR v_route_count<>1 THEN
    RETURN pg_catalog.jsonb_build_object('ok',true,'admitted',false,'reason','EXACT_IMPORT_ROUTE_OR_OWNERSHIP_MISMATCH');
  END IF;

  SELECT pg_catalog.count(*)::integer
  INTO v_bad_count
  FROM public.timesheets AS timesheet_row
  JOIN public.timesheets_financials AS financial
    ON financial.timesheet_id=timesheet_row.timesheet_id
   AND financial.is_current IS TRUE
  WHERE timesheet_row.timesheet_id=ANY(v_family)
    AND (
      timesheet_row.correction_id IS NOT NULL
      OR timesheet_row.parent_timesheet_id IS NOT NULL
      OR coalesce(timesheet_row.is_adjustment,false)
      OR coalesce((public._ctms_import_correction_classify_v1(timesheet_row.timesheet_id)
                    ->>'is_import_authoritative_correction')::boolean,false)
      OR (v_route='NHSP' AND (
            pg_catalog.upper(financial.basis::text)<>'NHSP'
            OR financial.nhsp_import_id IS NULL
          ))
      OR (v_route='HEALTHROSTER' AND (
            pg_catalog.upper(financial.basis::text) NOT IN ('HR_VALIDATED','HEALTHROSTER_SELF_BILL')
            OR pg_catalog.jsonb_typeof(coalesce(financial.external_source_rows_json,'[]'::jsonb))<>'array'
          ))
    );

  IF v_bad_count>0 OR (
    SELECT pg_catalog.count(*) FROM public.timesheets_financials AS financial
    WHERE financial.timesheet_id=ANY(v_family) AND financial.is_current IS TRUE
  )<>pg_catalog.array_length(v_family,1) THEN
    RETURN pg_catalog.jsonb_build_object('ok',true,'admitted',false,'reason','EXACT_IMPORT_MEMBER_UNSUPPORTED');
  END IF;

  SELECT pg_catalog.count(*)::integer,
         pg_catalog.encode(extensions.digest(pg_catalog.convert_to(
           coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
             'timesheet_id',financial.timesheet_id,
             'timesheet_version',financial.timesheet_version,
             'basis',financial.basis,
             'nhsp_import_id',financial.nhsp_import_id,
             'external_source_rows_json',financial.external_source_rows_json,
             'actual_schedule_json',financial.actual_schedule_json
           ) ORDER BY financial.timesheet_id)::text,'[]'),'UTF8'),'sha256'),'hex'),
         pg_catalog.encode(extensions.digest(pg_catalog.convert_to(
           coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
             'timesheet_id',financial.timesheet_id,
             'actual_schedule_json',financial.actual_schedule_json
           ) ORDER BY financial.timesheet_id)::text,'[]'),'UTF8'),'sha256'),'hex')
  INTO v_member_count,v_tsfin_digest,v_occurrence_digest
  FROM public.timesheets_financials AS financial
  WHERE financial.timesheet_id=ANY(v_family) AND financial.is_current IS TRUE;

  SELECT pg_catalog.count(DISTINCT family_member.timesheet_id)::integer
  INTO v_evidence_count
  FROM pg_catalog.unnest(v_family) AS family_member(timesheet_id)
  CROSS JOIN LATERAL public.timesheet_import_rows_for_timesheet_current(
    family_member.timesheet_id,false,NULL::uuid,NULL::uuid
  ) AS import_evidence
  WHERE pg_catalog.upper(coalesce(import_evidence.source_system,''))=v_route
    AND pg_catalog.jsonb_typeof(coalesce(import_evidence.rows,'[]'::jsonb))='array'
    AND pg_catalog.jsonb_array_length(coalesce(import_evidence.rows,'[]'::jsonb))>0;

  SELECT coalesce(pg_catalog.sum(
    CASE
      WHEN pg_catalog.jsonb_typeof(coalesce(financial.actual_schedule_json,'[]'::jsonb))='array'
        THEN pg_catalog.jsonb_array_length(coalesce(financial.actual_schedule_json,'[]'::jsonb))
      ELSE 0
    END
  ),0)::integer
  INTO v_occurrence_count
  FROM public.timesheets_financials AS financial
  WHERE financial.timesheet_id=ANY(v_family) AND financial.is_current IS TRUE;

  IF v_evidence_count<pg_catalog.array_length(v_family,1) OR v_occurrence_count<=0 THEN
    RETURN pg_catalog.jsonb_build_object('ok',true,'admitted',false,'reason','EXACT_IMPORT_OCCURRENCE_EVIDENCE_INCOMPLETE');
  END IF;

  RETURN pg_catalog.jsonb_build_object(
    'ok',true,'admitted',true,'reason','EXACT_IMPORT_FAMILY_ADMITTED',
    'family_kind',CASE WHEN v_route='NHSP' THEN 'NHSP_WEEKLY' ELSE 'HEALTHROSTER_WEEKLY' END,
    'family_timesheet_ids',pg_catalog.to_jsonb(v_family),
    'family_count',pg_catalog.array_length(v_family,1),
    'tsfin_revision_digest',v_tsfin_digest,
    'occurrence_count',v_occurrence_count,
    'occurrence_digest',v_occurrence_digest,
    'import_evidence_count',v_evidence_count,
    'source_change_seq',p_source_change_seq
  );
END;
$function$;

-- private.pay_workbench_execution_refresh_owner_proof_page_v1(uuid,uuid,uuid[],text,jsonb)
CREATE OR REPLACE FUNCTION private.pay_workbench_execution_refresh_owner_proof_page_v1(p_execution_operation_id uuid, p_pay_batch_id uuid, p_candidate_ids uuid[], p_mode text DEFAULT 'OBSERVE_ONLY'::text, p_options_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE PARALLEL RESTRICTED SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_mode text:=pg_catalog.upper(pg_catalog.btrim(COALESCE(p_mode,'OBSERVE_ONLY')));
  v_options_version text:=COALESCE(p_options_json->>'contract_version','1');
  v_residual_binding jsonb:=COALESCE(p_options_json->'residual_selection_binding','{}'::jsonb);
  v_residual_page jsonb:='{}'::jsonb;
  v_results jsonb:='[]'::jsonb;
  v_count integer:=0;
BEGIN
  IF p_execution_operation_id IS NULL OR p_pay_batch_id IS NULL
     OR p_candidate_ids IS NULL OR pg_catalog.cardinality(p_candidate_ids)<1
     OR pg_catalog.cardinality(p_candidate_ids)>100
     OR v_mode NOT IN ('OBSERVE_ONLY','PRE_REQUEST','ROUTE_REPLAY')
     OR pg_catalog.jsonb_typeof(COALESCE(p_options_json,'{}'::jsonb))<>'object'
     OR EXISTS (
       SELECT 1
       FROM pg_catalog.jsonb_object_keys(COALESCE(p_options_json,'{}'::jsonb)) AS option_key(key)
       WHERE option_key.key NOT IN (
         'contract_version','expected_chain_digest_by_candidate','expected_owner_by_candidate',
         'expected_parent_proof_digest_by_candidate','residual_selection_binding'
       )
     )
     OR v_options_version NOT IN ('1','2')
     OR pg_catalog.jsonb_typeof(COALESCE(
       p_options_json->'expected_chain_digest_by_candidate','{}'::jsonb
     ))<>'object'
     OR pg_catalog.jsonb_typeof(COALESCE(
       p_options_json->'expected_owner_by_candidate','{}'::jsonb
     ))<>'object'
     OR pg_catalog.jsonb_typeof(COALESCE(
       p_options_json->'expected_parent_proof_digest_by_candidate','{}'::jsonb
     ))<>'object'
     OR (v_options_version='1' AND (
       p_options_json ? 'expected_parent_proof_digest_by_candidate'
       OR p_options_json ? 'residual_selection_binding'
     ))
     OR (v_options_version='2' AND (
       v_mode NOT IN ('PRE_REQUEST','ROUTE_REPLAY')
       OR (SELECT pg_catalog.count(*)
           FROM pg_catalog.jsonb_object_keys(COALESCE(
             p_options_json->'expected_owner_by_candidate','{}'::jsonb
           )))<>0
       OR (v_mode='PRE_REQUEST' AND (SELECT pg_catalog.count(*)
           FROM pg_catalog.jsonb_object_keys(COALESCE(
             p_options_json->'expected_parent_proof_digest_by_candidate','{}'::jsonb
           )))<>0)
       OR (v_mode='ROUTE_REPLAY' AND (
         (SELECT pg_catalog.count(*)
          FROM pg_catalog.jsonb_object_keys(COALESCE(
            p_options_json->'expected_parent_proof_digest_by_candidate','{}'::jsonb
          )))<>pg_catalog.cardinality(p_candidate_ids)
         OR EXISTS (
           SELECT 1
           FROM pg_catalog.jsonb_each_text(COALESCE(
             p_options_json->'expected_parent_proof_digest_by_candidate','{}'::jsonb
           )) AS expected(key,value)
           WHERE expected.value!~'^[0-9a-f]{64}$'
              OR CASE
                WHEN expected.key~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                  THEN NOT ((expected.key)::uuid=ANY(p_candidate_ids))
                ELSE true
              END
         )
       ))
       OR
       pg_catalog.jsonb_typeof(v_residual_binding)<>'object'
       OR EXISTS (
         SELECT 1 FROM pg_catalog.jsonb_object_keys(v_residual_binding) AS binding_key(key)
         WHERE binding_key.key NOT IN (
           'contract_version','boundary','correction_request_id','correction_operation_id',
           'workbench_session_id','workbench_session_version','request_selection_hash',
           'request_plan_hash','expected_selected_anchor_digest_by_candidate'
         )
       )
       OR COALESCE(v_residual_binding->>'contract_version','')
            <>'EXECUTION_RESIDUAL_SELECTION_BINDING_V1'
       OR COALESCE(v_residual_binding->>'boundary','')
            <>'AFTER_REQUEST_PREPARE_BEFORE_REQUEST_START'
       OR COALESCE(v_residual_binding->>'correction_request_id','')
            !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR COALESCE(v_residual_binding->>'correction_operation_id','')
            !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR COALESCE(v_residual_binding->>'workbench_session_id','')
            !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR COALESCE(v_residual_binding->>'workbench_session_version','')!~'^[1-9][0-9]{0,17}$'
       OR COALESCE(v_residual_binding->>'request_selection_hash','')!~'^[0-9a-f]{64}$'
       OR COALESCE(v_residual_binding->>'request_plan_hash','')!~'^[0-9a-f]{64}$'
       OR pg_catalog.jsonb_typeof(COALESCE(
         v_residual_binding->'expected_selected_anchor_digest_by_candidate','{}'::jsonb
       ))<>'object'
     ))
     OR EXISTS (
       SELECT 1 FROM pg_catalog.unnest(p_candidate_ids) AS supplied(candidate_id)
       WHERE supplied.candidate_id IS NULL
     )
     OR (SELECT pg_catalog.count(*) FROM pg_catalog.unnest(p_candidate_ids) AS supplied(candidate_id))
          IS DISTINCT FROM
        (SELECT pg_catalog.count(DISTINCT supplied.candidate_id)
         FROM pg_catalog.unnest(p_candidate_ids) AS supplied(candidate_id)) THEN
    RAISE EXCEPTION 'EXECUTION_REFRESH_OWNER_PROOF_ARGUMENT_INVALID'
      USING ERRCODE='P0001',DETAIL=pg_catalog.jsonb_build_object(
        'code','EXECUTION_REFRESH_OWNER_PROOF_ARGUMENT_INVALID','mode',v_mode
      )::text;
  END IF;

  IF v_options_version='2' THEN
    v_residual_page:=private.pay_workbench_execution_residual_identity_proof_page_v1(
      (v_residual_binding->>'correction_request_id')::uuid,
      (v_residual_binding->>'correction_operation_id')::uuid,
      p_execution_operation_id,p_pay_batch_id,
      (v_residual_binding->>'workbench_session_id')::uuid,
      (v_residual_binding->>'workbench_session_version')::bigint,
      p_candidate_ids,v_residual_binding->>'request_selection_hash',
      v_residual_binding->>'request_plan_hash',
      COALESCE(p_options_json->'expected_chain_digest_by_candidate','{}'::jsonb),
      COALESCE(v_residual_binding->'expected_selected_anchor_digest_by_candidate','{}'::jsonb),
      CASE WHEN v_mode='ROUTE_REPLAY' THEN 'ROUTE_REPLAY' ELSE 'PRE_REQUEST_START' END
    );
  END IF;

  WITH requested AS (
    SELECT supplied.candidate_id,pg_catalog.min(supplied.ordinality)::bigint AS ordinality
    FROM pg_catalog.unnest(p_candidate_ids) WITH ORDINALITY
      AS supplied(candidate_id,ordinality)
    GROUP BY supplied.candidate_id
  ), authority AS (
    SELECT requested.ordinality,requested.candidate_id,
      execution_operation.id AS execution_operation_id,
      execution_operation.status AS execution_operation_status,
      execution_operation.phase AS execution_operation_phase,
      execution_operation.pay_batch_id AS execution_operation_batch_id,
      COALESCE(
        execution_operation.progress_json->'execution_unsent_overlay_chain_v2'->'candidates'
          ->requested.candidate_id::text,
        execution_operation.result_json->'execution_unsent_overlay_chain_v2'->'candidates'
          ->requested.candidate_id::text
      ) AS chain_receipt,
      batch_row.source_workbench_session_id AS session_id,
      batch_row.source_snapshot_run_id,
      batch_row.source_session_version AS session_version,
      pg_catalog.upper(pg_catalog.btrim(COALESCE(batch_row.execution_commit_state,'NOT_SUBMITTED')))
        AS execution_commit_state,
      scope_row.status AS scope_status,scope_row.pending_job_id AS scope_pending_job_id,
      scope_row.dirty AS scope_dirty,
      scope_row.certified_preview_publication_parity_ok AS current_publication_parity,
      scope_row.certified_preview_publication_source_build_run_id AS current_source_build_run_id,
      scope_row.certified_preview_publication_source_publication_id AS current_source_publication_id,
      state_row.status AS candidate_status,state_row.pending_job_id AS state_pending_job_id,
      state_row.source_change_seq AS candidate_state_source_change_seq,
      state_row.session_version AS candidate_state_session_version,
      registry.current_build_id AS registry_current_build_id,
      registry.current_source_change_seq AS registry_source_change_seq,
      registry.dirty_generation AS registry_dirty_generation,
      COALESCE(change_counter.seq,0) AS live_source_change_seq,
      COALESCE(change_counter.scope_change_generation,0) AS live_dirty_generation
    FROM requested
    LEFT JOIN public.banking_pay_operations AS execution_operation
      ON execution_operation.id=p_execution_operation_id
     AND execution_operation.operation_type='PAYMENT_EXECUTE'
     AND execution_operation.pay_batch_id=p_pay_batch_id
    LEFT JOIN public.pay_batches AS batch_row ON batch_row.id=p_pay_batch_id
    LEFT JOIN public.banking_pay_workbench_session_scope AS scope_row
      ON scope_row.session_id=batch_row.source_workbench_session_id
     AND scope_row.candidate_id=requested.candidate_id
    LEFT JOIN public.banking_pay_workbench_session_candidate_state AS state_row
      ON state_row.session_id=batch_row.source_workbench_session_id
     AND state_row.candidate_id=requested.candidate_id
    LEFT JOIN private.banking_pay_workbench_candidate_scope_registry AS registry
      ON registry.candidate_id=requested.candidate_id
    LEFT JOIN public.app_change_counters AS change_counter
      ON change_counter.entity_key='pay_candidate:'||requested.candidate_id::text
  ), owner_groups AS (
    SELECT authority.*,
      owner_build.id AS owner_economic_build_id,
      owner_build.source_build_run_id AS owner_source_build_run_id,
      owner_build.source_job_id AS owner_declared_root_job_id,
      owner_build.source_change_seq AS owner_source_change_seq,
      owner_build.captured_candidate_generation AS owner_dirty_generation,
      owner_build.authority_fingerprint AS owner_authority_fingerprint,
      owner_build.status AS owner_status,owner_build.private_stage AS owner_stage,
      root_job.id AS owner_root_job_id,root_job.payload_json AS owner_root_payload,
      root_context.context_json AS owner_execution_context,
      root_context.context_digest AS owner_context_digest,
      COALESCE(active_jobs.active_job_count,0) AS active_job_count,
      COALESCE(active_jobs.active_job_ids,'[]'::jsonb) AS active_job_ids,
      COALESCE(active_jobs.running_job_count,0) AS running_job_count,
      COALESCE(active_builds.active_economic_owner_count,0) AS active_economic_owner_count,
      COALESCE(active_builds.competing_owner_count,0) AS competing_owner_count,
      source_provenance.expected_owner_source_publication_id,
      COALESCE(source_provenance.current_source_count,0) AS current_source_count,
      COALESCE(source_provenance.original_current_source_count,0)
        AS original_current_source_count,
      COALESCE(source_provenance.owner_current_source_count,0)
        AS owner_current_source_count,
      COALESCE(source_provenance.unexpected_current_source_count,0)
        AS unexpected_current_source_count,
      COALESCE(source_provenance.null_current_publication_count,0)
        AS null_current_publication_count,
      COALESCE(source_provenance.partial_current_publication_count,0)
        AS partial_current_publication_count,
      COALESCE(source_provenance.unexpected_current_publication_count,0)
        AS unexpected_current_publication_count,
      COALESCE(source_provenance.unexpected_current_source_build_run_count,0)
        AS unexpected_current_source_build_run_count,
      COALESCE(source_provenance.duplicate_active_identity_count,0)
        AS duplicate_active_identity_count,
      source_provenance.current_active_identity_digest,
      source_provenance.original_current_source_identity_digest,
      source_provenance.owner_current_source_identity_digest,
      source_provenance.unexpected_current_source_identity_digest,
      source_provenance.canonical_original_source_identity_digest,
      COALESCE(source_provenance.current_source_other_session_version_count,0)
        AS current_source_other_session_version_count,
      CASE
        WHEN COALESCE(source_provenance.current_source_count,0)=0
          THEN 'NO_CURRENT_SOURCE_ROWS'
        WHEN COALESCE(source_provenance.unexpected_current_source_count,0)>0
          THEN 'UNEXPECTED_CURRENT_SOURCE_AUTHORITY'
        WHEN COALESCE(source_provenance.original_current_source_count,0)
             =COALESCE(source_provenance.current_source_count,0)
          THEN 'ORIGINAL_CERTIFIED_RESIDUAL_ONLY'
        WHEN COALESCE(source_provenance.owner_current_source_count,0)
             =COALESCE(source_provenance.current_source_count,0)
          THEN 'EXECUTION_OWNER_PARTIAL_ONLY'
        WHEN COALESCE(source_provenance.original_current_source_count,0)
             +COALESCE(source_provenance.owner_current_source_count,0)
             =COALESCE(source_provenance.current_source_count,0)
          THEN 'MIXED_ORIGINAL_AND_EXECUTION_OWNER'
        ELSE 'UNCLASSIFIED_CURRENT_SOURCE_AUTHORITY'
      END AS observed_source_provenance_shape,
      COALESCE(preview_provenance.ready_preview_count,0) AS ready_preview_count,
      COALESCE(preview_provenance.ready_preview_current_session_version_count,0)
        AS ready_preview_current_session_version_count,
      COALESCE(preview_provenance.ready_preview_other_session_version_count,0)
        AS ready_preview_other_session_version_count,
      preview_provenance.ready_preview_identity_digest,
      COALESCE(parity_provenance.source_minus_preview_count,0)
        AS source_minus_preview_count,
      COALESCE(parity_provenance.preview_minus_source_count,0)
        AS preview_minus_source_count,
      CASE WHEN v_options_version='2' THEN residual.result_json->'frozen_attestation'
        ELSE original_authority.frozen_attestation END AS frozen_attestation,
      CASE WHEN v_options_version='2'
          AND COALESCE(residual.result_json->>'frozen_scope_ordinal','')~'^[1-9][0-9]{0,17}$'
        THEN (residual.result_json->>'frozen_scope_ordinal')::bigint
        ELSE original_authority.frozen_scope_ordinal END AS frozen_scope_ordinal,
      residual.result_count AS residual_candidate_result_count,
      CASE WHEN COALESCE(residual.result_json->>'referenced_scope_count','')~'^[1-9][0-9]{0,8}$'
        THEN (residual.result_json->>'referenced_scope_count')::integer END
        AS referenced_scope_count,
      residual.result_json->>'common_publication_attestation_digest'
        AS common_publication_attestation_digest,
      residual.result_json->>'referenced_scope_set_digest' AS referenced_scope_set_digest,
      scope_pending.economic_build_id AS scope_pending_economic_build_id,
      state_pending.economic_build_id AS state_pending_economic_build_id,
      COALESCE(expected.expected_chain_digest,'') AS expected_chain_digest,
      expected.expected_owner_economic_build_id,
      expected.expected_parent_proof_digest,
      residual.result_json AS residual_identity_authority,
      COALESCE((residual.result_json->>'admitted')::boolean,false)
        AS residual_identity_admitted,
      residual.result_json->>'residual_proof_digest' AS residual_proof_digest,
      EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(COALESCE(authority.chain_receipt->'transitions','[]'::jsonb))
          AS transition_row(value)
        JOIN LATERAL pg_catalog.jsonb_array_elements_text(
          COALESCE(transition_row.value->'context_digests','[]'::jsonb)
        ) AS context_digest(value) ON true
        WHERE context_digest.value=root_context.context_digest
      ) AS context_digest_in_chain
    FROM authority
    LEFT JOIN LATERAL (
      SELECT
        draft_scope.allocation_basis_json->'source_publication_attestation'
          AS frozen_attestation,
        CASE
          WHEN COALESCE(
            draft_scope.allocation_basis_json#>>'{source_publication_attestation,scope_ordinal}',
            ''
          )~'^[0-9]{1,18}$'
          THEN (draft_scope.allocation_basis_json#>>
            '{source_publication_attestation,scope_ordinal}')::bigint
          ELSE NULL::bigint
        END AS frozen_scope_ordinal
      FROM public.banking_pay_operation_candidate_scope AS draft_scope
      WHERE v_options_version='1'
        AND COALESCE(authority.chain_receipt->>'draft_operation_id','')
              ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        AND draft_scope.operation_id=(authority.chain_receipt->>'draft_operation_id')::uuid
        AND draft_scope.pay_batch_id=p_pay_batch_id
        AND draft_scope.candidate_id=authority.candidate_id
        AND draft_scope.status NOT IN ('FAILED','CANCELLED','SUPERSEDED')
      LIMIT 1
    ) AS original_authority ON true
    LEFT JOIN LATERAL (
      SELECT build_row.*
      FROM private.banking_pay_workbench_economic_builds AS build_row
      WHERE build_row.candidate_id=authority.candidate_id
        AND build_row.session_id=authority.session_id
        AND build_row.session_version=authority.session_version
        AND build_row.source_snapshot_run_id=authority.source_snapshot_run_id
        AND build_row.source_change_seq=CASE
          WHEN COALESCE(authority.chain_receipt->>'terminal_source_change_seq','')~'^[0-9]{1,18}$'
          THEN (authority.chain_receipt->>'terminal_source_change_seq')::bigint END
        AND build_row.captured_candidate_generation=CASE
          WHEN COALESCE(authority.chain_receipt->>'terminal_execution_generation','')~'^[0-9]{1,18}$'
          THEN (authority.chain_receipt->>'terminal_execution_generation')::bigint END
        AND pg_catalog.upper(pg_catalog.btrim(COALESCE(build_row.status,''))) IN (
          'COLLECTING','READY_FOR_RECONCILIATION','RECONCILING','RECONCILED',
          'PUBLISHING','BLOCKED_UNVALIDATED_RECONCILIATION_SCALE'
        )
        AND EXISTS (
          SELECT 1 FROM public.banking_pay_workbench_jobs AS active_job
          WHERE active_job.economic_build_id=build_row.id
            AND active_job.status IN ('QUEUED','RUNNING')
        )
      ORDER BY build_row.created_at_utc DESC,build_row.id DESC
      LIMIT 1
    ) AS owner_build ON true
    LEFT JOIN LATERAL (
      WITH expected_publication AS (
        SELECT CASE
          WHEN authority.session_id IS NOT NULL
           AND authority.candidate_id IS NOT NULL
           AND authority.session_version IS NOT NULL
           AND owner_build.source_change_seq IS NOT NULL
           AND owner_build.source_build_run_id IS NOT NULL
          THEN private.pay_workbench_source_publication_identity_v1(
            authority.session_id,authority.candidate_id,authority.session_version,
            owner_build.source_change_seq,owner_build.source_build_run_id
          )
          ELSE NULL::uuid
        END AS owner_source_publication_id
      ), current_rows AS (
        SELECT source_row.*,
          public.pay_workbench_preview_section_from_line_json(source_row.source_row_json)
            AS effective_section,
          COALESCE(
            source_row.source_build_run_id::text
              =authority.chain_receipt->>'original_source_build_run_id'
            AND source_row.source_publication_id::text
              =authority.chain_receipt->>'original_source_publication_id',
            false
          ) AS is_original_source,
          COALESCE(
            source_row.source_build_run_id=owner_build.source_build_run_id
            AND source_row.source_publication_id
              =expected_publication.owner_source_publication_id,
            false
          ) AS is_owner_source,
          pg_catalog.concat_ws('|',
            COALESCE(source_row.source_publication_id::text,''),
            COALESCE(source_row.source_build_run_id::text,''),
            source_row.source_change_seq::text,source_row.session_version::text,
            COALESCE(source_row.timesheet_id::text,'00000000-0000-0000-0000-000000000000'),
            source_row.line_key
          ) AS canonical_active_identity
        FROM public.banking_pay_workbench_candidate_source_lines AS source_row
        CROSS JOIN expected_publication
        WHERE source_row.session_id=authority.session_id
          AND source_row.candidate_id=authority.candidate_id
          AND source_row.status='CURRENT'
      ), duplicate_identities AS (
        SELECT pg_catalog.count(*)::integer AS duplicate_active_identity_count
        FROM (
          SELECT COALESCE(current_rows.timesheet_id,
                   '00000000-0000-0000-0000-000000000000'::uuid),
                 current_rows.line_key
          FROM current_rows
          GROUP BY COALESCE(current_rows.timesheet_id,
                     '00000000-0000-0000-0000-000000000000'::uuid),
                   current_rows.line_key
          HAVING pg_catalog.count(*)>1
        ) AS duplicate_identity
      )
      SELECT expected_publication.owner_source_publication_id
          AS expected_owner_source_publication_id,
        pg_catalog.count(current_rows.id)::integer AS current_source_count,
        pg_catalog.count(*) FILTER (WHERE current_rows.is_original_source)::integer
          AS original_current_source_count,
        pg_catalog.count(*) FILTER (WHERE current_rows.is_owner_source)::integer
          AS owner_current_source_count,
        pg_catalog.count(*) FILTER (
          WHERE NOT current_rows.is_original_source AND NOT current_rows.is_owner_source
        )::integer AS unexpected_current_source_count,
        pg_catalog.count(*) FILTER (
          WHERE current_rows.source_publication_id IS NULL
        )::integer AS null_current_publication_count,
        pg_catalog.count(DISTINCT current_rows.source_publication_id)::integer
          AS partial_current_publication_count,
        pg_catalog.count(DISTINCT current_rows.source_publication_id) FILTER (
          WHERE NOT current_rows.is_original_source AND NOT current_rows.is_owner_source
        )::integer AS unexpected_current_publication_count,
        pg_catalog.count(DISTINCT current_rows.source_build_run_id) FILTER (
          WHERE NOT current_rows.is_original_source AND NOT current_rows.is_owner_source
        )::integer AS unexpected_current_source_build_run_count,
        duplicate_identities.duplicate_active_identity_count,
        pg_catalog.encode(extensions.digest(pg_catalog.convert_to(COALESCE(
          pg_catalog.string_agg(current_rows.canonical_active_identity,'|' ORDER BY
            current_rows.canonical_active_identity),''),'UTF8'),'sha256'),'hex')
          AS current_active_identity_digest,
        pg_catalog.encode(extensions.digest(pg_catalog.convert_to(COALESCE(
          pg_catalog.string_agg(current_rows.canonical_active_identity,'|' ORDER BY
            current_rows.canonical_active_identity) FILTER (
              WHERE current_rows.is_original_source
            ),''),'UTF8'),'sha256'),'hex') AS original_current_source_identity_digest,
        pg_catalog.encode(extensions.digest(pg_catalog.convert_to(COALESCE(
          pg_catalog.string_agg(current_rows.canonical_active_identity,'|' ORDER BY
            current_rows.canonical_active_identity) FILTER (
              WHERE current_rows.is_owner_source
            ),''),'UTF8'),'sha256'),'hex') AS owner_current_source_identity_digest,
        pg_catalog.encode(extensions.digest(pg_catalog.convert_to(COALESCE(
          pg_catalog.string_agg(current_rows.canonical_active_identity,'|' ORDER BY
            current_rows.canonical_active_identity) FILTER (
              WHERE NOT current_rows.is_original_source AND NOT current_rows.is_owner_source
            ),''),'UTF8'),'sha256'),'hex') AS unexpected_current_source_identity_digest,
        pg_catalog.md5(COALESCE(pg_catalog.string_agg(
          current_rows.effective_section||E'\x1f'||current_rows.line_key||E'\x1f'||
            current_rows.source_ordinal::text,E'\x1e'
          ORDER BY current_rows.source_ordinal,current_rows.effective_section,
            current_rows.line_key
        ) FILTER (WHERE current_rows.is_original_source),''))
          AS canonical_original_source_identity_digest,
        pg_catalog.count(*) FILTER (
          WHERE current_rows.session_version IS DISTINCT FROM authority.session_version
        )::integer AS current_source_other_session_version_count
      FROM expected_publication
      LEFT JOIN current_rows ON true
      CROSS JOIN duplicate_identities
      GROUP BY expected_publication.owner_source_publication_id,
               duplicate_identities.duplicate_active_identity_count
    ) AS source_provenance ON true
    LEFT JOIN LATERAL (
      SELECT pg_catalog.count(*) FILTER (
          WHERE preview_row.status='READY'
        )::integer AS ready_preview_count,
        pg_catalog.count(*) FILTER (
          WHERE preview_row.status='READY'
            AND preview_row.session_version=authority.session_version
        )::integer AS ready_preview_current_session_version_count,
        pg_catalog.count(*) FILTER (
          WHERE preview_row.status='READY'
            AND preview_row.session_version IS DISTINCT FROM authority.session_version
        )::integer AS ready_preview_other_session_version_count,
        pg_catalog.md5(COALESCE(pg_catalog.string_agg(
          preview_row.section||E'\x1f'||preview_row.row_key||E'\x1f'||
            (preview_row.row_ordinal-(original_authority.frozen_scope_ordinal*1000000))::text,
          E'\x1e' ORDER BY
            (preview_row.row_ordinal-(original_authority.frozen_scope_ordinal*1000000)),
            preview_row.section,preview_row.row_key
        ) FILTER (
          WHERE preview_row.status='READY'
            AND preview_row.session_version=authority.session_version
        ),'')) AS ready_preview_identity_digest
      FROM public.banking_pay_workbench_preview_rows AS preview_row
      WHERE preview_row.session_id=authority.session_id
        AND preview_row.candidate_id=authority.candidate_id
    ) AS preview_provenance ON true
    LEFT JOIN LATERAL (
      WITH current_source AS (
        SELECT
          public.pay_workbench_preview_section_from_line_json(source_row.source_row_json)
            AS section,
          source_row.line_key,
          source_row.source_ordinal
        FROM public.banking_pay_workbench_candidate_source_lines AS source_row
        WHERE source_row.session_id=authority.session_id
          AND source_row.candidate_id=authority.candidate_id
          AND source_row.status='CURRENT'
      ), ready_preview AS (
        SELECT preview_row.section,preview_row.row_key,
          (preview_row.row_ordinal-(original_authority.frozen_scope_ordinal*1000000))::bigint
            AS source_ordinal
        FROM public.banking_pay_workbench_preview_rows AS preview_row
        WHERE preview_row.session_id=authority.session_id
          AND preview_row.candidate_id=authority.candidate_id
          AND preview_row.session_version=authority.session_version
          AND preview_row.status='READY'
      )
      SELECT
        (SELECT pg_catalog.count(*)::integer FROM (
          SELECT section,line_key,source_ordinal FROM current_source
          EXCEPT ALL
          SELECT section,row_key,source_ordinal FROM ready_preview
        ) AS source_diff) AS source_minus_preview_count,
        (SELECT pg_catalog.count(*)::integer FROM (
          SELECT section,row_key,source_ordinal FROM ready_preview
          EXCEPT ALL
          SELECT section,line_key,source_ordinal FROM current_source
        ) AS preview_diff) AS preview_minus_source_count
    ) AS parity_provenance ON true
    LEFT JOIN LATERAL (
      SELECT source_job.*
      FROM public.banking_pay_workbench_jobs AS source_job
      WHERE source_job.economic_build_id=owner_build.id
        AND source_job.job_type='WORKBENCH_CANDIDATE_SOURCE_BUILD'
        AND COALESCE(
          source_job.payload_json->>'source_build_run_id',
          source_job.payload_json#>>'{source_build,source_build_run_id}',''
        )=owner_build.source_build_run_id::text
      ORDER BY source_job.created_at_utc,source_job.id
      LIMIT 1
    ) AS root_job ON true
    LEFT JOIN LATERAL (
      SELECT context_choice.context_json,
             context_choice.context_json->>'context_digest' AS context_digest
      FROM (
        SELECT root_job.payload_json->'execution_overlay_schedule_contexts'
                 ->authority.candidate_id::text AS context_json,1 AS precedence
        UNION ALL
        SELECT root_job.payload_json->'execution_overlay_contexts'
                 ->authority.candidate_id::text AS context_json,2 AS precedence
      ) AS context_choice
      WHERE pg_catalog.jsonb_typeof(context_choice.context_json)='object'
      ORDER BY context_choice.precedence
      LIMIT 1
    ) AS root_context ON true
    LEFT JOIN LATERAL (
      SELECT pg_catalog.count(*)::integer AS active_job_count,
        pg_catalog.count(*) FILTER (WHERE active_job.status='RUNNING')::integer
          AS running_job_count,
        COALESCE(pg_catalog.jsonb_agg(active_job.id::text ORDER BY
          CASE WHEN active_job.status='RUNNING' THEN 0 ELSE 1 END,
          active_job.run_at_utc,active_job.created_at_utc,active_job.id),'[]'::jsonb)
          AS active_job_ids
      FROM (
        SELECT bounded_job.*
        FROM public.banking_pay_workbench_jobs AS bounded_job
        WHERE bounded_job.economic_build_id=owner_build.id
          AND bounded_job.status IN ('QUEUED','RUNNING')
        ORDER BY bounded_job.created_at_utc,bounded_job.id
        LIMIT 17
      ) AS active_job
    ) AS active_jobs ON true
    LEFT JOIN LATERAL (
      SELECT pg_catalog.count(*)::integer AS active_economic_owner_count,
        pg_catalog.count(*) FILTER (WHERE active_build.id IS DISTINCT FROM owner_build.id)::integer
          AS competing_owner_count
      FROM (
        SELECT build_row.id
        FROM private.banking_pay_workbench_economic_builds AS build_row
        WHERE build_row.candidate_id=authority.candidate_id
          AND build_row.session_id=authority.session_id
          AND build_row.session_version=authority.session_version
          AND pg_catalog.upper(pg_catalog.btrim(COALESCE(build_row.status,''))) IN (
            'COLLECTING','READY_FOR_RECONCILIATION','RECONCILING','RECONCILED',
            'PUBLISHING','BLOCKED_UNVALIDATED_RECONCILIATION_SCALE'
          )
          AND EXISTS (
            SELECT 1 FROM public.banking_pay_workbench_jobs AS active_job
            WHERE active_job.economic_build_id=build_row.id
              AND active_job.status IN ('QUEUED','RUNNING')
          )
        ORDER BY build_row.created_at_utc DESC,build_row.id DESC
        LIMIT 2
      ) AS active_build
    ) AS active_builds ON true
    LEFT JOIN public.banking_pay_workbench_jobs AS scope_pending
      ON scope_pending.id=authority.scope_pending_job_id
    LEFT JOIN public.banking_pay_workbench_jobs AS state_pending
      ON state_pending.id=authority.state_pending_job_id
    LEFT JOIN LATERAL (
      SELECT
        p_options_json->'expected_chain_digest_by_candidate'
          ->>authority.candidate_id::text AS expected_chain_digest,
        p_options_json->'expected_parent_proof_digest_by_candidate'
          ->>authority.candidate_id::text AS expected_parent_proof_digest,
        CASE WHEN COALESCE(p_options_json->'expected_owner_by_candidate'
          ->>authority.candidate_id::text,'')
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN (p_options_json->'expected_owner_by_candidate'
            ->>authority.candidate_id::text)::uuid END AS expected_owner_economic_build_id
    ) AS expected ON true
    LEFT JOIN LATERAL (
      SELECT pg_catalog.count(*)::integer AS result_count,
        CASE WHEN pg_catalog.count(*)=1
          THEN (pg_catalog.jsonb_agg(result.value ORDER BY result.value)->0) END AS result_json
      FROM pg_catalog.jsonb_array_elements(COALESCE(
        v_residual_page->'candidate_results','[]'::jsonb
      )) AS result(value)
      WHERE result.value->>'candidate_id'=authority.candidate_id::text
    ) AS residual ON true
  ), classified AS (
    SELECT owner_groups.*,
      CASE
        WHEN execution_operation_id IS NULL OR execution_operation_batch_id IS DISTINCT FROM p_pay_batch_id
          OR execution_operation_status<>'COMPLETE' OR execution_operation_phase<>'COMPLETE'
          THEN 'EXECUTION_REFRESH_OWNER_OPERATION_MISMATCH'
        WHEN COALESCE(chain_receipt->>'contract_version','')<>'EXECUTION_UNSENT_OVERLAY_CHAIN_V2'
          OR pg_catalog.lower(pg_catalog.btrim(COALESCE(chain_receipt->>'closed','')))
               NOT IN ('true','t','1','yes','y','on')
          THEN 'EXECUTION_REFRESH_OWNER_CHAIN_NOT_CLOSED'
        WHEN COALESCE(chain_receipt->>'execution_operation_id','')<>p_execution_operation_id::text
          OR COALESCE(chain_receipt->>'pay_batch_id','')<>p_pay_batch_id::text
          OR COALESCE(chain_receipt->>'candidate_id','')<>candidate_id::text
          OR COALESCE(CASE
            WHEN COALESCE(chain_receipt->>'transition_count','')~'^[0-9]{1,2}$'
            THEN (chain_receipt->>'transition_count')::integer END,0) NOT BETWEEN 1 AND 16
          THEN 'EXECUTION_REFRESH_OWNER_CHAIN_SCOPE_MISMATCH'
        WHEN v_options_version='2' AND COALESCE(residual_candidate_result_count,0)<>1
          THEN 'EXECUTION_RESIDUAL_CANDIDATE_RESULT_CARDINALITY_MISMATCH'
        WHEN v_options_version='2' AND (
          COALESCE(referenced_scope_count,0)<1
          OR COALESCE(common_publication_attestation_digest,'')!~'^[0-9a-f]{64}$'
          OR COALESCE(referenced_scope_set_digest,'')!~'^[0-9a-f]{64}$'
          OR frozen_scope_ordinal IS NULL
          OR pg_catalog.jsonb_typeof(frozen_attestation)<>'object')
          THEN 'EXECUTION_RESIDUAL_COMMON_PUBLICATION_AUTHORITY_INVALID'
        WHEN execution_commit_state<>'NOT_SUBMITTED'
          OR COALESCE(chain_receipt->>'execution_commit_state','')<>'NOT_SUBMITTED'
          OR COALESCE(CASE WHEN COALESCE(chain_receipt->>'provider_attempt_count','')~'^[0-9]{1,9}$'
            THEN (chain_receipt->>'provider_attempt_count')::integer END,-1)<>0
          OR COALESCE(CASE WHEN COALESCE(chain_receipt->>'rail_transaction_count','')~'^[0-9]{1,9}$'
            THEN (chain_receipt->>'rail_transaction_count')::integer END,-1)<>0
          OR COALESCE(CASE WHEN COALESCE(chain_receipt->>'settlement_count','')~'^[0-9]{1,9}$'
            THEN (chain_receipt->>'settlement_count')::integer END,-1)<>0
          OR COALESCE(CASE WHEN COALESCE(chain_receipt->>'remittance_count','')~'^[0-9]{1,9}$'
            THEN (chain_receipt->>'remittance_count')::integer END,-1)<>0
          THEN 'EXECUTION_REFRESH_OWNER_MONEY_MOVEMENT_FENCE'
        WHEN expected_chain_digest<>''
          AND expected_chain_digest IS DISTINCT FROM chain_receipt->>'chain_digest'
          THEN 'EXECUTION_REFRESH_OWNER_EXPECTED_CHAIN_MISMATCH'
        WHEN observed_source_provenance_shape='ORIGINAL_CERTIFIED_RESIDUAL_ONLY'
          AND v_options_version<>'2'
          THEN 'EXECUTION_RESIDUAL_SELECTION_AUTHORITY_REQUIRED'
        WHEN observed_source_provenance_shape='ORIGINAL_CERTIFIED_RESIDUAL_ONLY'
          AND residual_identity_admitted IS NOT TRUE
          THEN COALESCE(
            NULLIF(residual_identity_authority->>'rejection_reason',''),
            'EXECUTION_RESIDUAL_SELECTION_AUTHORITY_REQUIRED'
          )
        WHEN (live_source_change_seq IS DISTINCT FROM
          CASE WHEN COALESCE(chain_receipt->>'terminal_source_change_seq','')~'^[0-9]{1,18}$'
            THEN (chain_receipt->>'terminal_source_change_seq')::bigint END
          OR live_dirty_generation IS DISTINCT FROM
          CASE WHEN COALESCE(chain_receipt->>'terminal_execution_generation','')~'^[0-9]{1,18}$'
            THEN (chain_receipt->>'terminal_execution_generation')::bigint END
          OR registry_source_change_seq IS DISTINCT FROM live_source_change_seq
          OR registry_dirty_generation IS DISTINCT FROM live_dirty_generation
          OR candidate_state_source_change_seq IS DISTINCT FROM live_source_change_seq
          OR candidate_state_session_version IS DISTINCT FROM session_version)
          AND NOT (
            observed_source_provenance_shape='ORIGINAL_CERTIFIED_RESIDUAL_ONLY'
            AND residual_identity_admitted IS TRUE
          )
          THEN 'EXECUTION_REFRESH_OWNER_LIVE_AUTHORITY_MISMATCH'
        WHEN observed_source_provenance_shape='ORIGINAL_CERTIFIED_RESIDUAL_ONLY'
          AND residual_identity_admitted IS NOT TRUE
          AND (
            pg_catalog.jsonb_typeof(frozen_attestation)<>'object'
            OR COALESCE(frozen_attestation->>'attestation_version','')
                 <>'CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V3'
            OR COALESCE(frozen_attestation->>'contract_version','')<>'3'
            OR COALESCE(frozen_attestation->>'semantic_contract_version','')
                 <>'READY_TO_PAY_SEMANTIC_V2'
            OR pg_catalog.lower(pg_catalog.btrim(COALESCE(
                 frozen_attestation->>'semantic_ready','false'
               ))) NOT IN ('true','t','1','yes','y','on')
            OR pg_catalog.lower(pg_catalog.btrim(COALESCE(
                 frozen_attestation->>'parity_complete','false'
               ))) NOT IN ('true','t','1','yes','y','on')
            OR COALESCE(frozen_attestation->>'session_id','')<>COALESCE(session_id::text,'')
            OR COALESCE(frozen_attestation->>'candidate_id','')<>candidate_id::text
            OR COALESCE(frozen_attestation->>'session_version','')<>COALESCE(session_version::text,'')
            OR frozen_scope_ordinal IS NULL
            OR COALESCE(frozen_attestation->>'source_change_seq','')
                 <>COALESCE(chain_receipt->>'pre_execution_source_change_seq','')
            OR COALESCE(frozen_attestation->>'source_build_run_id','')
                 <>COALESCE(chain_receipt->>'original_source_build_run_id','')
            OR COALESCE(frozen_attestation->>'source_publication_id','')
                 <>COALESCE(chain_receipt->>'original_source_publication_id','')
            OR COALESCE(frozen_attestation->>'semantic_proof_digest','')
                 <>COALESCE(chain_receipt->>'original_semantic_proof_digest','')
          )
          THEN 'EXECUTION_REFRESH_OWNER_ORIGINAL_ATTESTATION_MISMATCH'
        WHEN observed_source_provenance_shape='ORIGINAL_CERTIFIED_RESIDUAL_ONLY'
          AND residual_identity_admitted IS NOT TRUE
          AND (
            CASE
              WHEN COALESCE(frozen_attestation->>'source_row_count','')~'^[0-9]{1,9}$'
              THEN (frozen_attestation->>'source_row_count')::integer
              ELSE NULL::integer
            END IS DISTINCT FROM current_source_count
            OR owner_current_source_count<>0 OR unexpected_current_source_count<>0
            OR unexpected_current_publication_count<>0
            OR unexpected_current_source_build_run_count<>0
            OR null_current_publication_count<>0 OR partial_current_publication_count<>1
            OR duplicate_active_identity_count<>0
            OR current_source_other_session_version_count<>0
            OR COALESCE(canonical_original_source_identity_digest,'')
                 <>COALESCE(frozen_attestation->>'source_identity_digest','')
            OR COALESCE(chain_receipt->>'original_source_identity_digest','')
                 <>COALESCE(frozen_attestation->>'source_identity_digest','')
            OR COALESCE(current_source_build_run_id::text,'')
                 <>COALESCE(chain_receipt->>'original_source_build_run_id','')
            OR COALESCE(current_source_publication_id::text,'')
                 <>COALESCE(chain_receipt->>'original_source_publication_id','')
            OR current_publication_parity IS NOT TRUE
          )
          THEN 'EXECUTION_REFRESH_OWNER_ORIGINAL_SOURCE_ATTESTATION_MISMATCH'
        WHEN observed_source_provenance_shape='ORIGINAL_CERTIFIED_RESIDUAL_ONLY'
          AND residual_identity_admitted IS NOT TRUE
          AND (
            CASE
              WHEN COALESCE(frozen_attestation->>'preview_row_count','')~'^[0-9]{1,9}$'
              THEN (frozen_attestation->>'preview_row_count')::integer
              ELSE NULL::integer
            END IS DISTINCT FROM ready_preview_count
            OR ready_preview_current_session_version_count<>ready_preview_count
            OR ready_preview_other_session_version_count<>0
            OR COALESCE(ready_preview_identity_digest,'')
                 <>COALESCE(frozen_attestation->>'preview_identity_digest','')
            OR source_minus_preview_count<>0 OR preview_minus_source_count<>0
          )
          THEN 'EXECUTION_REFRESH_OWNER_ORIGINAL_PREVIEW_ATTESTATION_MISMATCH'
        WHEN observed_source_provenance_shape<>'ORIGINAL_CERTIFIED_RESIDUAL_ONLY'
          AND (current_source_publication_id IS NOT NULL OR current_source_build_run_id IS NOT NULL
            OR current_source_count<>0 OR partial_current_publication_count<>0
            OR current_publication_parity IS TRUE)
          THEN 'EXECUTION_REFRESH_OWNER_PARTIAL_OR_CURRENT_PUBLICATION'
        WHEN pg_catalog.upper(pg_catalog.btrim(COALESCE(scope_status,'')))<>'SOURCE_BUILD_PENDING'
          OR pg_catalog.upper(pg_catalog.btrim(COALESCE(candidate_status,'')))<>'PENDING'
          OR scope_pending_job_id IS NULL OR state_pending_job_id IS NULL
          THEN 'EXECUTION_REFRESH_OWNER_TRANSIENT_SHAPE_MISMATCH'
        WHEN owner_economic_build_id IS NULL OR owner_source_build_run_id IS NULL
          OR owner_root_job_id IS NULL OR active_job_count<1 OR active_job_count>16
          THEN 'EXECUTION_REFRESH_OWNER_CANONICAL_OWNER_MISSING'
        WHEN active_economic_owner_count<>1 OR competing_owner_count<>0
          THEN 'EXECUTION_REFRESH_OWNER_COMPETING_OWNER'
        WHEN scope_pending_economic_build_id IS DISTINCT FROM owner_economic_build_id
          OR state_pending_economic_build_id IS DISTINCT FROM owner_economic_build_id
          OR registry_current_build_id IS DISTINCT FROM owner_economic_build_id
          THEN 'EXECUTION_REFRESH_OWNER_PENDING_POINTER_MISMATCH'
        WHEN owner_source_change_seq IS DISTINCT FROM live_source_change_seq
          OR owner_dirty_generation IS DISTINCT FROM live_dirty_generation
          OR COALESCE(owner_root_payload->>'authority_fingerprint','')
               IS DISTINCT FROM COALESCE(owner_authority_fingerprint,'')
          OR COALESCE(owner_root_payload->>'source_build_run_id',
               owner_root_payload#>>'{source_build,source_build_run_id}','')
               IS DISTINCT FROM owner_source_build_run_id::text
          THEN 'EXECUTION_REFRESH_OWNER_FINGERPRINT_MISMATCH'
        WHEN pg_catalog.jsonb_typeof(owner_execution_context)<>'object'
          OR COALESCE(owner_execution_context->>'execution_operation_id','')
               <>p_execution_operation_id::text
          OR COALESCE(owner_execution_context->>'pay_batch_id','')<>p_pay_batch_id::text
          OR COALESCE(owner_execution_context->>'candidate_id','')<>candidate_id::text
          OR COALESCE(owner_execution_context->>'source_workbench_session_id','')
               <>COALESCE(session_id::text,'')
          OR COALESCE(owner_execution_context->>'source_snapshot_run_id','')
               <>COALESCE(source_snapshot_run_id::text,'')
          OR COALESCE(owner_execution_context->>'source_session_version','')
               <>COALESCE(session_version::text,'')
          OR NULLIF(COALESCE(owner_context_digest,''),'') IS NULL
          OR context_digest_in_chain IS NOT TRUE
          THEN 'EXECUTION_REFRESH_OWNER_CAUSAL_PROVENANCE_MISMATCH'
        WHEN expected_owner_economic_build_id IS NOT NULL
          AND expected_owner_economic_build_id IS DISTINCT FROM owner_economic_build_id
          THEN 'EXECUTION_REFRESH_OWNER_EXPECTED_OWNER_MISMATCH'
        WHEN NULLIF(COALESCE(expected_parent_proof_digest,''),'') IS NOT NULL
          AND expected_parent_proof_digest IS DISTINCT FROM
            private.pay_payment_correction_sha256_v1(pg_catalog.jsonb_build_object(
              'contract_version','EXECUTION_REFRESH_OWNER_PROOF_V2',
              'execution_operation_id',p_execution_operation_id,
              'pay_batch_id',p_pay_batch_id,'candidate_id',candidate_id,
              'chain_digest',chain_receipt->>'chain_digest',
              'owner_economic_build_id',owner_economic_build_id,
              'owner_source_build_run_id',owner_source_build_run_id,
              'owner_authority_fingerprint',owner_authority_fingerprint,
              'owner_context_digest',owner_context_digest,
              'owner_source_change_seq',owner_source_change_seq,
              'owner_dirty_generation',owner_dirty_generation,
              'observed_source_provenance_shape',observed_source_provenance_shape,
              'original_source_build_run_id',chain_receipt->>'original_source_build_run_id',
              'original_source_publication_id',chain_receipt->>'original_source_publication_id',
              'frozen_source_identity_digest',frozen_attestation->>'source_identity_digest',
              'frozen_preview_identity_digest',frozen_attestation->>'preview_identity_digest',
              'referenced_scope_count',referenced_scope_count,
              'common_publication_attestation_digest',
                common_publication_attestation_digest,
              'referenced_scope_set_digest',referenced_scope_set_digest,
              'frozen_scope_ordinal',frozen_scope_ordinal,
              'residual_proof_digest',residual_proof_digest
            ))
          THEN 'EXECUTION_REFRESH_OWNER_EXPECTED_PARENT_PROOF_MISMATCH'
        ELSE NULL
      END AS rejection_reason
    FROM owner_groups
  ), result_rows AS (
    SELECT classified.ordinality,pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
      'candidate_id',classified.candidate_id,
      'bridge_admitted',classified.rejection_reason IS NULL,
      'admitted',classified.rejection_reason IS NULL,
      'currentness_basis','EXACT_UNSENT_EXECUTION_REFRESH_OWNER',
      'transient_publication_shape',classified.observed_source_provenance_shape,
      'rejection_reason',classified.rejection_reason,
      'execution_operation_id',classified.execution_operation_id,
      'pay_batch_id',p_pay_batch_id,
      'execution_overlay_chain_digest',classified.chain_receipt->>'chain_digest',
      'terminal_source_change_seq',classified.chain_receipt->'terminal_source_change_seq',
      'terminal_dirty_generation',classified.chain_receipt->'terminal_execution_generation',
      'scope_status',classified.scope_status,'scope_dirty',classified.scope_dirty,
      'candidate_status',classified.candidate_status,
      'current_source_count',classified.current_source_count,
      'provenance_diagnostics',pg_catalog.jsonb_build_object(
        'contract_version','EXECUTION_REFRESH_OWNER_PROVENANCE_OBSERVE_V1',
        'observed_source_shape',classified.observed_source_provenance_shape,
        'original_source_build_run_id',classified.chain_receipt->>'original_source_build_run_id',
        'original_source_publication_id',classified.chain_receipt->>'original_source_publication_id',
        'expected_owner_source_publication_id',classified.expected_owner_source_publication_id,
        'original_current_source_count',classified.original_current_source_count,
        'owner_current_source_count',classified.owner_current_source_count,
        'unexpected_current_source_count',classified.unexpected_current_source_count,
        'null_current_publication_count',classified.null_current_publication_count,
        'distinct_current_publication_count',classified.partial_current_publication_count,
        'unexpected_current_publication_count',classified.unexpected_current_publication_count,
        'unexpected_current_source_build_run_count',
          classified.unexpected_current_source_build_run_count,
        'duplicate_active_identity_count',classified.duplicate_active_identity_count,
        'current_active_identity_digest',classified.current_active_identity_digest,
        'original_current_source_identity_digest',
          classified.original_current_source_identity_digest,
        'owner_current_source_identity_digest',classified.owner_current_source_identity_digest,
        'unexpected_current_source_identity_digest',
          classified.unexpected_current_source_identity_digest,
        'ready_preview_count',classified.ready_preview_count,
        'ready_preview_current_session_version_count',
          classified.ready_preview_current_session_version_count,
        'ready_preview_other_session_version_count',
          classified.ready_preview_other_session_version_count,
        'ready_preview_identity_digest',classified.ready_preview_identity_digest,
        'canonical_original_source_identity_digest',
          classified.canonical_original_source_identity_digest,
        'frozen_original_source_identity_digest',
          classified.frozen_attestation->>'source_identity_digest',
        'frozen_original_preview_identity_digest',
          classified.frozen_attestation->>'preview_identity_digest',
        'frozen_original_source_row_count',classified.frozen_attestation->'source_row_count',
        'frozen_original_preview_row_count',classified.frozen_attestation->'preview_row_count',
        'current_source_other_session_version_count',
          classified.current_source_other_session_version_count,
        'source_minus_preview_count',classified.source_minus_preview_count,
        'preview_minus_source_count',classified.preview_minus_source_count,
        'observed_transient_shape_digest',pg_catalog.encode(extensions.digest(
          pg_catalog.convert_to(pg_catalog.concat_ws('|',
            'EXECUTION_REFRESH_OWNER_TRANSIENT_SHAPE_OBSERVE_V1',
            classified.observed_source_provenance_shape,
            classified.owner_stage,classified.current_source_count::text,
            classified.original_current_source_count::text,
            classified.owner_current_source_count::text,
            classified.unexpected_current_source_count::text,
            classified.duplicate_active_identity_count::text,
            classified.current_active_identity_digest,
            classified.ready_preview_count::text,
            classified.ready_preview_identity_digest
          ),'UTF8'),'sha256'),'hex')
      ),
      'owner_economic_build_id',classified.owner_economic_build_id,
      'owner_source_build_run_id',classified.owner_source_build_run_id,
      'owner_root_job_id',classified.owner_root_job_id,
      'owner_active_job_ids',classified.active_job_ids,
      'owner_authority_fingerprint',classified.owner_authority_fingerprint,
      'owner_source_change_seq',classified.owner_source_change_seq,
      'owner_dirty_generation',classified.owner_dirty_generation,
      'owner_status',classified.owner_status,'owner_stage',classified.owner_stage,
      'competing_owner_count',classified.competing_owner_count,
      'partial_publication_count',classified.partial_current_publication_count,
      'context_digest',classified.owner_context_digest,
      'residual_identity_authority',classified.residual_identity_authority,
      'residual_proof_digest',classified.residual_proof_digest,
      'residual_candidate_result_count',classified.residual_candidate_result_count,
      'referenced_scope_count',classified.referenced_scope_count,
      'common_publication_attestation_digest',
        classified.common_publication_attestation_digest,
      'referenced_scope_set_digest',classified.referenced_scope_set_digest,
      'frozen_scope_ordinal',classified.frozen_scope_ordinal,
      'proof_contract_version',CASE WHEN v_options_version='2'
        THEN 'EXECUTION_REFRESH_OWNER_PROOF_V2' ELSE 'EXECUTION_REFRESH_OWNER_PROOF_V1' END,
      'proof_digest',CASE WHEN v_options_version='2' THEN
        private.pay_payment_correction_sha256_v1(pg_catalog.jsonb_build_object(
          'contract_version','EXECUTION_REFRESH_OWNER_PROOF_V2',
          'execution_operation_id',p_execution_operation_id,
          'pay_batch_id',p_pay_batch_id,'candidate_id',classified.candidate_id,
          'chain_digest',classified.chain_receipt->>'chain_digest',
          'owner_economic_build_id',classified.owner_economic_build_id,
          'owner_source_build_run_id',classified.owner_source_build_run_id,
          'owner_authority_fingerprint',classified.owner_authority_fingerprint,
          'owner_context_digest',classified.owner_context_digest,
          'owner_source_change_seq',classified.owner_source_change_seq,
          'owner_dirty_generation',classified.owner_dirty_generation,
          'observed_source_provenance_shape',classified.observed_source_provenance_shape,
          'original_source_build_run_id',classified.chain_receipt->>'original_source_build_run_id',
          'original_source_publication_id',classified.chain_receipt->>'original_source_publication_id',
          'frozen_source_identity_digest',classified.frozen_attestation->>'source_identity_digest',
          'frozen_preview_identity_digest',classified.frozen_attestation->>'preview_identity_digest',
          'referenced_scope_count',classified.referenced_scope_count,
          'common_publication_attestation_digest',
            classified.common_publication_attestation_digest,
          'referenced_scope_set_digest',classified.referenced_scope_set_digest,
          'frozen_scope_ordinal',classified.frozen_scope_ordinal,
          'residual_proof_digest',classified.residual_proof_digest
        ))
      ELSE pg_catalog.encode(extensions.digest(pg_catalog.convert_to(
        pg_catalog.concat_ws('|','EXECUTION_REFRESH_OWNER_PROOF_V1',
          p_execution_operation_id::text,p_pay_batch_id::text,classified.candidate_id::text,
          COALESCE(classified.chain_receipt->>'chain_digest',''),
          COALESCE(classified.owner_economic_build_id::text,''),
          COALESCE(classified.owner_source_build_run_id::text,''),
          COALESCE(classified.owner_authority_fingerprint,''),
          COALESCE(classified.owner_context_digest,''),
          COALESCE(classified.owner_source_change_seq,-1)::text,
          COALESCE(classified.owner_dirty_generation,-1)::text,
          COALESCE(classified.observed_source_provenance_shape,''),
          COALESCE(classified.chain_receipt->>'original_source_build_run_id',''),
          COALESCE(classified.chain_receipt->>'original_source_publication_id',''),
          COALESCE(classified.frozen_attestation->>'source_identity_digest',''),
          COALESCE(classified.frozen_attestation->>'preview_identity_digest',''),
          (classified.rejection_reason IS NULL)::text,
          COALESCE(classified.rejection_reason,'')),
        'UTF8'),'sha256'),'hex') END
    )) AS result_json
    FROM classified
  )
  SELECT COALESCE(pg_catalog.jsonb_agg(result_json ORDER BY ordinality),'[]'::jsonb),
         pg_catalog.count(*)::integer
  INTO v_results,v_count
  FROM result_rows;

  RETURN pg_catalog.jsonb_build_object(
    'ok',true,'contract_version','EXECUTION_REFRESH_OWNER_PROOF_PAGE_V1',
    'mode',v_mode,'execution_operation_id',p_execution_operation_id,
    'pay_batch_id',p_pay_batch_id,'candidate_count',v_count,
    'admitted_count',(SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_array_elements(v_results) AS r(value)
      WHERE COALESCE((r.value->>'admitted')::boolean,false)),
    'candidate_results',v_results,
    'policy_x_authority_scope','POST_DRAFT_FROZEN_PAYMENT_PROOF_PLUS_EXACT_V2_EXECUTION_REFRESH_OWNER'
  );
END;
$function$;

-- private.pay_workbench_execution_residual_identity_proof_page_v1(uuid,uuid,uuid,uuid,uuid,bigint,uuid[],text,text,jsonb,jsonb,text)
CREATE OR REPLACE FUNCTION private.pay_workbench_execution_residual_identity_proof_page_v1(p_correction_request_id uuid, p_correction_operation_id uuid, p_execution_operation_id uuid, p_pay_batch_id uuid, p_workbench_session_id uuid, p_workbench_session_version bigint, p_candidate_ids uuid[], p_expected_request_selection_hash text, p_expected_request_plan_hash text, p_expected_v2_chain_digest_by_candidate jsonb, p_expected_selected_anchor_digest_by_candidate jsonb, p_mode text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE PARALLEL RESTRICTED SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_mode text:=pg_catalog.upper(pg_catalog.btrim(COALESCE(p_mode,'')));
  v_request public.pay_payment_correction_requests%ROWTYPE;
  v_correction_operation public.banking_pay_operations%ROWTYPE;
  v_execution_operation public.banking_pay_operations%ROWTYPE;
  v_candidate uuid;
  v_ordinal bigint;
  v_request_candidate record;
  v_chain jsonb;
  v_attestation jsonb;
  v_selected_items jsonb;
  v_selected_anchor_digest text;
  v_affected_rows jsonb;
  v_affected_digest text;
  v_residual_digest text;
  v_rejection text;
  v_results jsonb:='[]'::jsonb;
  v_authorities jsonb:='{}'::jsonb;
  v_expected_key_count integer;
  v_request_candidate_count integer;
  v_supplied_candidate_count integer;
  v_item_count integer;
  v_distinct_item_count integer;
  v_resolved_item_count integer;
  v_allocation_count integer;
  v_ambiguous_allocation_count integer;
  v_scope_count integer;
  v_attestation_identity_count integer;
  v_anchor_count integer;
  v_context_bound_item_count integer;
  v_context_unproved_item_count integer;
  v_context_ambiguous_item_count integer;
  v_unproved_affected_item_count integer;
  v_affected_closure_ambiguity_count integer;
  v_f_count integer;
  v_a_count integer;
  v_e_count integer;
  v_c_count integer;
  v_p_count integer;
  v_f_minus_partition integer;
  v_partition_minus_f integer;
  v_e_minus_c integer;
  v_c_minus_e integer;
  v_e_minus_p integer;
  v_p_minus_e integer;
  v_c_minus_p integer;
  v_p_minus_c integer;
  v_duplicate_active_identity_count integer;
  v_lineage_mismatch_count integer;
  v_f_identity text;
  v_e_identity text;
  v_c_identity text;
  v_p_identity text;
  v_e_semantic text;
  v_c_semantic text;
  v_active_item_scope_digest text;
  v_authority_digest text;
  v_request_owned_dirty_job_id uuid;
  v_live_source_change_seq bigint;
  v_live_dirty_generation bigint;
  v_request_owned_latest_source_seq bigint;
  v_request_owned_dirty_generation bigint;
  v_request_owned_dirty_proven boolean:=false;
  v_invalid_scope_count integer:=0;
  v_common_attestation_digest text;
  v_referenced_scope_set_digest text;
  v_frozen_scope_ordinal bigint;
  v_ready_identity_invalid_count integer:=0;
BEGIN
  v_supplied_candidate_count:=COALESCE(pg_catalog.cardinality(p_candidate_ids),0);

  IF p_correction_request_id IS NULL OR p_correction_operation_id IS NULL
     OR p_execution_operation_id IS NULL OR p_pay_batch_id IS NULL
     OR p_workbench_session_id IS NULL OR p_workbench_session_version IS NULL
     OR p_workbench_session_version<1 OR v_supplied_candidate_count NOT BETWEEN 1 AND 100
     OR v_mode NOT IN ('PRE_REQUEST_START','ROUTE_REPLAY')
     OR COALESCE(p_expected_request_selection_hash,'')!~'^[0-9a-f]{64}$'
     OR COALESCE(p_expected_request_plan_hash,'')!~'^[0-9a-f]{64}$'
     OR pg_catalog.jsonb_typeof(COALESCE(p_expected_v2_chain_digest_by_candidate,'null'::jsonb))<>'object'
     OR pg_catalog.jsonb_typeof(COALESCE(p_expected_selected_anchor_digest_by_candidate,'null'::jsonb))<>'object'
     OR EXISTS (SELECT 1 FROM pg_catalog.unnest(p_candidate_ids) AS supplied(id) WHERE supplied.id IS NULL)
     OR v_supplied_candidate_count<>(SELECT pg_catalog.count(DISTINCT supplied.id)
       FROM pg_catalog.unnest(p_candidate_ids) AS supplied(id)) THEN
    RAISE EXCEPTION 'EXECUTION_RESIDUAL_ARGUMENT_INVALID'
      USING ERRCODE='P0001',DETAIL=pg_catalog.jsonb_build_object(
        'code','EXECUTION_RESIDUAL_ARGUMENT_INVALID','mode',v_mode
      )::text;
  END IF;

  SELECT request_row.* INTO v_request
  FROM public.pay_payment_correction_requests AS request_row
  WHERE request_row.id=p_correction_request_id;
  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('ok',true,'admitted',false,
      'rejection_reason','EXECUTION_RESIDUAL_REQUEST_NOT_FOUND');
  END IF;

  SELECT operation_row.* INTO v_correction_operation
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id=p_correction_operation_id;
  IF NOT FOUND OR v_correction_operation.operation_type<>'PAYMENT_CORRECTION'
     OR v_correction_operation.pay_batch_id IS DISTINCT FROM p_pay_batch_id
     OR COALESCE(v_correction_operation.input_json->>'correction_request_id','')
          IS DISTINCT FROM p_correction_request_id::text
     OR v_request.pay_batch_id IS DISTINCT FROM p_pay_batch_id THEN
    RETURN pg_catalog.jsonb_build_object('ok',true,'admitted',false,
      'rejection_reason','EXECUTION_RESIDUAL_CORRECTION_OPERATION_MISMATCH');
  END IF;

  IF (v_mode='PRE_REQUEST_START' AND v_request.status<>'PLANNED')
     OR v_request.selection_hash IS DISTINCT FROM p_expected_request_selection_hash
     OR v_request.plan_hash IS DISTINCT FROM p_expected_request_plan_hash THEN
    RETURN pg_catalog.jsonb_build_object('ok',true,'admitted',false,
      'rejection_reason',CASE
        WHEN v_mode='PRE_REQUEST_START' AND v_request.status<>'PLANNED'
          THEN 'EXECUTION_RESIDUAL_REQUEST_NOT_PLANNED'
        WHEN v_request.selection_hash IS DISTINCT FROM p_expected_request_selection_hash
          THEN 'EXECUTION_RESIDUAL_REQUEST_SELECTION_HASH_MISMATCH'
        ELSE 'EXECUTION_RESIDUAL_REQUEST_PLAN_HASH_MISMATCH' END);
  END IF;

  SELECT operation_row.* INTO v_execution_operation
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id=p_execution_operation_id;
  IF NOT FOUND OR v_execution_operation.operation_type<>'PAYMENT_EXECUTE'
     OR v_execution_operation.pay_batch_id IS DISTINCT FROM p_pay_batch_id
     OR v_execution_operation.status<>'COMPLETE' OR v_execution_operation.phase<>'COMPLETE' THEN
    RETURN pg_catalog.jsonb_build_object('ok',true,'admitted',false,
      'rejection_reason','EXECUTION_RESIDUAL_EXECUTION_OPERATION_MISMATCH');
  END IF;

  SELECT pg_catalog.count(*)::integer INTO v_request_candidate_count
  FROM public.pay_payment_correction_request_candidates AS request_candidate
  WHERE request_candidate.correction_request_id=p_correction_request_id;

  IF (v_mode='PRE_REQUEST_START' AND v_request_candidate_count<>v_supplied_candidate_count)
     OR EXISTS (
       SELECT 1
       FROM pg_catalog.unnest(p_candidate_ids) WITH ORDINALITY AS supplied(candidate_id,ordinality)
       WHERE NOT EXISTS (
         SELECT 1
         FROM public.pay_payment_correction_request_candidates AS request_candidate
         JOIN public.pay_batch_candidates AS batch_candidate
           ON batch_candidate.id=request_candidate.pay_batch_candidate_id
          AND batch_candidate.pay_batch_id=p_pay_batch_id
         WHERE request_candidate.correction_request_id=p_correction_request_id
           AND batch_candidate.candidate_id=supplied.candidate_id
           AND (v_mode<>'PRE_REQUEST_START'
             OR request_candidate.selection_ordinal=supplied.ordinality)
       )
     ) THEN
    RETURN pg_catalog.jsonb_build_object('ok',true,'admitted',false,
      'rejection_reason','EXECUTION_RESIDUAL_REQUEST_CANDIDATE_SET_MISMATCH');
  END IF;

  SELECT pg_catalog.count(*)::integer INTO v_expected_key_count
  FROM pg_catalog.jsonb_object_keys(p_expected_v2_chain_digest_by_candidate);
  IF v_expected_key_count<>v_supplied_candidate_count
     OR EXISTS (
       SELECT 1 FROM pg_catalog.jsonb_each_text(p_expected_v2_chain_digest_by_candidate) AS expected(key,value)
       WHERE expected.value IS NULL
          OR expected.value!~'^[0-9a-f]{32}$'
          OR CASE
            WHEN expected.key~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              THEN NOT ((expected.key)::uuid=ANY(p_candidate_ids))
            ELSE true
          END
     ) THEN
    RAISE EXCEPTION 'EXECUTION_RESIDUAL_ARGUMENT_INVALID'
      USING ERRCODE='P0001',DETAIL=pg_catalog.jsonb_build_object(
        'code','EXECUTION_RESIDUAL_V2_CHAIN_MAP_INVALID'
      )::text;
  END IF;

  SELECT pg_catalog.count(*)::integer INTO v_expected_key_count
  FROM pg_catalog.jsonb_object_keys(p_expected_selected_anchor_digest_by_candidate);
  IF (v_mode='PRE_REQUEST_START' AND v_expected_key_count<>0)
     OR (v_mode='ROUTE_REPLAY' AND v_expected_key_count<>v_supplied_candidate_count)
     OR EXISTS (
       SELECT 1 FROM pg_catalog.jsonb_each_text(p_expected_selected_anchor_digest_by_candidate) AS expected(key,value)
       WHERE expected.value IS NULL
          OR expected.value!~'^[0-9a-f]{64}$'
          OR CASE
            WHEN expected.key~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              THEN NOT ((expected.key)::uuid=ANY(p_candidate_ids))
            ELSE true
          END
     ) THEN
    RAISE EXCEPTION 'EXECUTION_RESIDUAL_ARGUMENT_INVALID'
      USING ERRCODE='P0001',DETAIL=pg_catalog.jsonb_build_object(
        'code','EXECUTION_RESIDUAL_SELECTED_ANCHOR_MAP_INVALID'
      )::text;
  END IF;

  FOR v_candidate,v_ordinal IN
    SELECT supplied.candidate_id,supplied.ordinality::bigint
    FROM pg_catalog.unnest(p_candidate_ids) WITH ORDINALITY AS supplied(candidate_id,ordinality)
    ORDER BY supplied.ordinality
  LOOP
    v_rejection:=NULL;
    v_request_owned_dirty_job_id:=NULL;
    v_request_owned_latest_source_seq:=NULL;
    v_request_owned_dirty_generation:=NULL;
    v_request_owned_dirty_proven:=false;
    v_live_source_change_seq:=0;
    v_live_dirty_generation:=0;
    v_selected_anchor_digest:=NULL;
    v_affected_digest:=NULL;
    v_residual_digest:=NULL;
    v_authority_digest:=NULL;
    v_chain:=NULL;
    v_attestation:=NULL;
    v_selected_items:='[]'::jsonb;
    v_affected_rows:='[]'::jsonb;
    v_item_count:=0;
    v_distinct_item_count:=0;
    v_resolved_item_count:=0;
    v_allocation_count:=0;
    v_ambiguous_allocation_count:=0;
    v_scope_count:=0;
    v_attestation_identity_count:=0;
    v_invalid_scope_count:=0;
    v_common_attestation_digest:=NULL;
    v_referenced_scope_set_digest:=NULL;
    v_frozen_scope_ordinal:=NULL;
    v_ready_identity_invalid_count:=0;
    v_anchor_count:=0;
    v_context_bound_item_count:=0;
    v_context_unproved_item_count:=0;
    v_context_ambiguous_item_count:=0;
    v_unproved_affected_item_count:=0;
    v_affected_closure_ambiguity_count:=0;
    v_f_count:=0;
    v_a_count:=0;
    v_e_count:=0;
    v_c_count:=0;
    v_p_count:=0;
    v_f_minus_partition:=0;
    v_partition_minus_f:=0;
    v_e_minus_c:=0;
    v_c_minus_e:=0;
    v_e_minus_p:=0;
    v_p_minus_e:=0;
    v_c_minus_p:=0;
    v_p_minus_c:=0;
    v_duplicate_active_identity_count:=0;
    v_lineage_mismatch_count:=0;
    v_f_identity:=NULL;
    v_e_identity:=NULL;
    v_c_identity:=NULL;
    v_p_identity:=NULL;
    v_e_semantic:=NULL;
    v_c_semantic:=NULL;
    SELECT request_candidate.*,batch_candidate.candidate_id
    INTO v_request_candidate
    FROM public.pay_payment_correction_request_candidates AS request_candidate
    JOIN public.pay_batch_candidates AS batch_candidate
      ON batch_candidate.id=request_candidate.pay_batch_candidate_id
     AND batch_candidate.pay_batch_id=p_pay_batch_id
    WHERE request_candidate.correction_request_id=p_correction_request_id
      AND batch_candidate.candidate_id=v_candidate;

    IF NOT FOUND THEN v_rejection:='EXECUTION_RESIDUAL_REQUEST_CANDIDATE_SET_MISMATCH'; END IF;
    IF v_rejection IS NULL THEN
      v_item_count:=pg_catalog.cardinality(v_request_candidate.pay_batch_item_ids);
      SELECT pg_catalog.count(DISTINCT item_id)::integer INTO v_distinct_item_count
      FROM pg_catalog.unnest(v_request_candidate.pay_batch_item_ids) AS selected(item_id);
      IF v_item_count IS NULL OR v_item_count<1 OR v_item_count<>v_request_candidate.active_item_count
         OR v_distinct_item_count<>v_item_count THEN
        v_rejection:=CASE WHEN v_distinct_item_count<>v_item_count
          THEN 'EXECUTION_RESIDUAL_SELECTED_ITEM_DUPLICATE'
          ELSE 'EXECUTION_RESIDUAL_SELECTED_ITEM_ARRAY_INVALID' END;
      END IF;
    END IF;

    v_chain:=COALESCE(
      v_execution_operation.progress_json->'execution_unsent_overlay_chain_v2'->'candidates'->v_candidate::text,
      v_execution_operation.result_json->'execution_unsent_overlay_chain_v2'->'candidates'->v_candidate::text
    );
    IF v_rejection IS NULL AND (
      pg_catalog.jsonb_typeof(v_chain)<>'object'
      OR COALESCE(v_chain->>'contract_version','')<>'EXECUTION_UNSENT_OVERLAY_CHAIN_V2'
      OR pg_catalog.lower(pg_catalog.btrim(COALESCE(v_chain->>'closed','')))
           NOT IN ('true','t','1','yes','y','on')
      OR COALESCE(v_chain->>'execution_operation_id','')<>p_execution_operation_id::text
      OR COALESCE(v_chain->>'pay_batch_id','')<>p_pay_batch_id::text
      OR COALESCE(v_chain->>'candidate_id','')<>v_candidate::text
      OR COALESCE(v_chain->>'source_workbench_session_id','')<>p_workbench_session_id::text
      OR COALESCE(v_chain->>'source_session_version','')<>p_workbench_session_version::text
      OR COALESCE(v_chain->>'execution_commit_state','')<>'NOT_SUBMITTED'
      OR CASE WHEN COALESCE(v_chain->>'provider_attempt_count','')~'^[0-9]{1,9}$'
           THEN (v_chain->>'provider_attempt_count')::integer<>0 ELSE true END
      OR CASE WHEN COALESCE(v_chain->>'rail_transaction_count','')~'^[0-9]{1,9}$'
           THEN (v_chain->>'rail_transaction_count')::integer<>0 ELSE true END
      OR CASE WHEN COALESCE(v_chain->>'settlement_count','')~'^[0-9]{1,9}$'
           THEN (v_chain->>'settlement_count')::integer<>0 ELSE true END
      OR CASE WHEN COALESCE(v_chain->>'remittance_count','')~'^[0-9]{1,9}$'
           THEN (v_chain->>'remittance_count')::integer<>0 ELSE true END
      OR COALESCE(v_chain->>'terminal_source_change_seq','')!~'^[0-9]{1,18}$'
      OR COALESCE(v_chain->>'terminal_execution_generation','')!~'^[0-9]{1,18}$'
      OR COALESCE(v_chain->>'chain_digest','')
           IS DISTINCT FROM p_expected_v2_chain_digest_by_candidate->>v_candidate::text
    ) THEN v_rejection:='EXECUTION_RESIDUAL_V2_ORIGINAL_AUTHORITY_MISMATCH'; END IF;

    IF v_rejection IS NULL THEN
      SELECT COALESCE((SELECT change_counter.seq
          FROM public.app_change_counters AS change_counter
          WHERE change_counter.entity_key='pay_candidate:'||v_candidate::text),0),
        COALESCE((SELECT change_counter.scope_change_generation
          FROM public.app_change_counters AS change_counter
          WHERE change_counter.entity_key='pay_candidate:'||v_candidate::text),0)
      INTO v_live_source_change_seq,v_live_dirty_generation;

      SELECT dirty_job.id,
        CASE WHEN COALESCE(dirty_job.payload_json->>'latest_source_change_seq','')~'^[0-9]{1,18}$'
          THEN (dirty_job.payload_json->>'latest_source_change_seq')::bigint END,
        dirty_job.scope_change_generation
      INTO v_request_owned_dirty_job_id,v_request_owned_latest_source_seq,
        v_request_owned_dirty_generation
      FROM public.banking_pay_workbench_jobs AS dirty_job
      WHERE dirty_job.candidate_id=v_candidate
        AND dirty_job.job_type='WORKBENCH_CANDIDATE_DIRTY_APPLY'
        AND COALESCE(dirty_job.payload_json->>'correction_dirty_causal_contract_version','')
              ='CORRECTION_OWNED_DIRTY_CAUSAL_V1'
        AND COALESCE(dirty_job.payload_json->'correction_dirty_contexts'
              ->v_candidate::text->>'correction_request_id','')=p_correction_request_id::text
        AND COALESCE(dirty_job.payload_json->'correction_dirty_contexts'
              ->v_candidate::text->>'pay_batch_id','')=p_pay_batch_id::text
        AND COALESCE(dirty_job.payload_json->>'request_owned_scope_change_tx_token','')
              =COALESCE(dirty_job.payload_json->>'scope_change_tx_token','')
        AND COALESCE(dirty_job.payload_json->>'request_owned_scope_change_tx_token','')
              ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        AND NOT EXISTS (
          SELECT 1 FROM pg_catalog.jsonb_array_elements_text(
            COALESCE(dirty_job.payload_json->'reasons','[]'::jsonb)
          ) AS reason(value)
          WHERE pg_catalog.upper(pg_catalog.btrim(reason.value)) NOT IN (
            'DIRTY_TRIGGER:PAY_PAYMENT_CORRECTION_REQUESTS:INSERT',
            'DIRTY_TRIGGER:PAY_PAYMENT_CORRECTION_REQUESTS:UPDATE',
            'DIRTY_TRIGGER:PAY_BATCHES:UPDATE'
          )
        )
      ORDER BY dirty_job.created_at_utc DESC,dirty_job.id DESC
      LIMIT 1;

      v_request_owned_dirty_proven:=
        v_request_owned_dirty_job_id IS NOT NULL
        AND v_request_owned_latest_source_seq IS NOT DISTINCT FROM v_live_source_change_seq
        AND v_request_owned_dirty_generation IS NOT DISTINCT FROM v_live_dirty_generation;

      IF (v_live_source_change_seq IS DISTINCT FROM (v_chain->>'terminal_source_change_seq')::bigint
          OR v_live_dirty_generation IS DISTINCT FROM (v_chain->>'terminal_execution_generation')::bigint)
         AND v_request_owned_dirty_proven IS NOT TRUE THEN
        v_rejection:='EXECUTION_RESIDUAL_REQUEST_OWNED_DIRTY_CONTINUITY_UNPROVED';
      END IF;
    END IF;

    IF v_rejection IS NULL THEN
      WITH selected AS (
        SELECT selected_id.item_id
        FROM pg_catalog.unnest(v_request_candidate.pay_batch_item_ids) AS selected_id(item_id)
      ), item_rows AS (
        SELECT item.* FROM selected
        JOIN public.pay_batch_items AS item ON item.id=selected.item_id
        WHERE item.pay_batch_candidate_id=v_request_candidate.pay_batch_candidate_id
      ), allocation_counts AS (
        SELECT item_rows.id,pg_catalog.count(allocation.id)::integer AS allocation_count
        FROM item_rows
        LEFT JOIN public.banking_pay_operation_candidate_allocation_rows AS allocation
          ON allocation.pay_batch_item_id=item_rows.id
        GROUP BY item_rows.id
      ), exact_rows AS (
        SELECT item_rows.*,allocation.id AS allocation_id,
          allocation.operation_id AS allocation_operation_id,
          allocation.candidate_scope_id,allocation.pay_batch_id AS allocation_batch_id,
          allocation.candidate_id AS allocation_candidate_id,
          allocation.pay_channel AS allocation_pay_channel,
          allocation.finance_case_id AS allocation_finance_case_id,
          allocation.finance_component_id AS allocation_finance_component_id,
          allocation.allocation_type,allocation.source_ref AS allocation_source_ref,
          allocation.operation_source_key AS allocation_operation_source_key,
          allocation.allocated_amount,allocation.allocation_basis_json,
          allocation.status AS allocation_status,
          scope.operation_id AS scope_operation_id,scope.workbench_session_id,
          scope.source_session_version,scope.candidate_id AS scope_candidate_id,
          scope.pay_batch_id AS scope_batch_id,scope.pay_channel AS scope_pay_channel,
          scope.scope_hash,scope.status AS scope_status,scope.allocation_basis_json AS scope_basis
        FROM item_rows
        JOIN allocation_counts ON allocation_counts.id=item_rows.id
          AND allocation_counts.allocation_count=1
        JOIN public.banking_pay_operation_candidate_allocation_rows AS allocation
          ON allocation.pay_batch_item_id=item_rows.id
        JOIN public.banking_pay_operation_candidate_scope AS scope
          ON scope.id=allocation.candidate_scope_id
      ), referenced_scopes AS MATERIALIZED (
        SELECT DISTINCT exact.candidate_scope_id,exact.scope_operation_id,
          exact.scope_batch_id,exact.scope_candidate_id,exact.workbench_session_id,
          exact.source_session_version,exact.scope_pay_channel,exact.scope_hash,
          exact.scope_status,exact.scope_basis,
          exact.scope_basis->'source_publication_attestation' AS attestation
        FROM exact_rows exact
      ), attestation_contract AS MATERIALIZED (
        SELECT ARRAY[
          'attestation_version','contract_version','semantic_contract_version','authority_kind',
          'final_state','parity_complete','semantic_ready','session_id','candidate_id',
          'economic_build_id','source_build_run_id','source_publication_id',
          'original_economic_build_id','original_source_build_run_id',
          'original_source_publication_id','source_session_id','source_change_seq',
          'session_version','completion_job_id','refresh_scope_kind','source_row_count',
          'preview_row_count','selectable_row_count','ordinary_positive_selectable_count',
          'ordinary_positive_amount','recognised_deduction_count','recognised_deduction_amount',
          'usable_same_candidate_headroom','candidate_ready_amount','context_row_count',
          'blocked_row_count','invalid_selectable_row_count','selected_row_count','source_digest',
          'source_identity_digest','preview_identity_digest','section_counts','scope_ordinal',
          'minimum_public_ordinal','maximum_public_ordinal','certification_version',
          'certification_digest','admission_seal_version','admission_seal_digest',
          'projection_fingerprint','semantic_proof_digest','original_semantic_proof_digest',
          'selection_recovery_headroom_v1','cancellation_request_id',
          'cancellation_operation_id','cancellation_work_item_id','pay_batch_id',
          'cancellation_reversion_run_id','financial_reversion_digest','attested_at_utc',
          'policy_x_authority_scope'
        ]::text[] AS allowed_keys,
        ARRAY[
          'attestation_version','contract_version','semantic_contract_version','authority_kind',
          'final_state','parity_complete','semantic_ready','session_id','candidate_id',
          'economic_build_id','source_build_run_id','source_publication_id','source_change_seq',
          'session_version','completion_job_id','refresh_scope_kind','source_row_count',
          'preview_row_count','selectable_row_count','ordinary_positive_selectable_count',
          'ordinary_positive_amount','recognised_deduction_count','recognised_deduction_amount',
          'usable_same_candidate_headroom','candidate_ready_amount','context_row_count',
          'blocked_row_count','invalid_selectable_row_count','selected_row_count','source_digest',
          'source_identity_digest','preview_identity_digest','section_counts','scope_ordinal',
          'minimum_public_ordinal','maximum_public_ordinal','semantic_proof_digest','attested_at_utc',
          'policy_x_authority_scope'
        ]::text[] AS required_keys
      ), validated_scope_attestations AS MATERIALIZED (
        SELECT scope_row.*,
          CASE WHEN
            scope_row.scope_operation_id IS DISTINCT FROM
              CASE WHEN COALESCE(v_chain->>'draft_operation_id','')
                  ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                THEN (v_chain->>'draft_operation_id')::uuid END
            OR scope_row.scope_batch_id IS DISTINCT FROM p_pay_batch_id
            OR scope_row.scope_candidate_id IS DISTINCT FROM v_candidate
            OR scope_row.workbench_session_id IS DISTINCT FROM p_workbench_session_id
            OR scope_row.source_session_version IS DISTINCT FROM p_workbench_session_version
            OR scope_row.scope_status IS DISTINCT FROM 'DRAFTED'
            OR NULLIF(pg_catalog.btrim(COALESCE(scope_row.scope_pay_channel,'')),'') IS NULL
            OR NULLIF(pg_catalog.btrim(COALESCE(scope_row.scope_hash,'')),'') IS NULL
            OR EXISTS(SELECT 1 FROM exact_rows exact
              WHERE exact.candidate_scope_id=scope_row.candidate_scope_id
                AND pg_catalog.upper(pg_catalog.btrim(COALESCE(exact.allocation_pay_channel,'')))
                    IS DISTINCT FROM pg_catalog.upper(pg_catalog.btrim(
                      COALESCE(scope_row.scope_pay_channel,''))))
            OR pg_catalog.jsonb_typeof(scope_row.attestation)<>'object'
            OR EXISTS(SELECT 1 FROM pg_catalog.jsonb_object_keys(
                COALESCE(scope_row.attestation,'{}'::jsonb)) supplied(key_name)
              WHERE NOT supplied.key_name=ANY(contract.allowed_keys))
            OR EXISTS(SELECT 1 FROM pg_catalog.unnest(contract.required_keys) required(key_name)
              WHERE NOT COALESCE(scope_row.attestation,'{}'::jsonb) ? required.key_name)
            OR COALESCE(scope_row.attestation->>'attestation_version','')
                <>'CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V3'
            OR COALESCE(scope_row.attestation->>'contract_version','')<>'3'
            OR COALESCE(scope_row.attestation->>'semantic_contract_version','')
                <>'READY_TO_PAY_SEMANTIC_V2'
            OR COALESCE(scope_row.attestation->>'authority_kind','') NOT IN (
              'BOUNDED_FULL_SOURCE_BUILD','CERTIFIED_CLONE','TARGETED_DELTA',
              'CERTIFIED_CANCELLATION_REVERSION')
            OR COALESCE(scope_row.attestation->>'final_state','')<>'READY'
            OR pg_catalog.lower(pg_catalog.btrim(COALESCE(
              scope_row.attestation->>'parity_complete',''))) NOT IN ('true','t','1','yes','y','on')
            OR pg_catalog.lower(pg_catalog.btrim(COALESCE(
              scope_row.attestation->>'semantic_ready',''))) NOT IN ('true','t','1','yes','y','on')
            OR COALESCE(scope_row.attestation->>'session_id','')<>p_workbench_session_id::text
            OR COALESCE(scope_row.attestation->>'candidate_id','')<>v_candidate::text
            OR COALESCE(scope_row.attestation->>'session_version','')
                <>p_workbench_session_version::text
            OR COALESCE(scope_row.attestation->>'economic_build_id','')
                !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            OR COALESCE(scope_row.attestation->>'source_build_run_id','')
                !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            OR COALESCE(scope_row.attestation->>'source_publication_id','')
                !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            OR COALESCE(scope_row.attestation->>'completion_job_id','')
                !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            OR EXISTS(SELECT 1 FROM (VALUES
                (scope_row.attestation->>'original_economic_build_id'),
                (scope_row.attestation->>'original_source_build_run_id'),
                (scope_row.attestation->>'original_source_publication_id'),
                (scope_row.attestation->>'source_session_id')) optional(value)
              WHERE optional.value IS NOT NULL AND optional.value
                !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
            OR COALESCE(scope_row.attestation->>'source_change_seq','')!~'^[0-9]{1,18}$'
            OR COALESCE(scope_row.attestation->>'source_row_count','')!~'^[1-9][0-9]{0,8}$'
            OR COALESCE(scope_row.attestation->>'preview_row_count','')
                IS DISTINCT FROM COALESCE(scope_row.attestation->>'source_row_count','')
            OR EXISTS(SELECT 1 FROM (VALUES
                (scope_row.attestation->>'selectable_row_count'),
                (scope_row.attestation->>'ordinary_positive_selectable_count'),
                (scope_row.attestation->>'recognised_deduction_count'),
                (scope_row.attestation->>'context_row_count'),
                (scope_row.attestation->>'blocked_row_count'),
                (scope_row.attestation->>'invalid_selectable_row_count'),
                (scope_row.attestation->>'selected_row_count')) count_value(value)
              WHERE COALESCE(count_value.value,'')!~'^[0-9]{1,9}$')
            OR EXISTS(SELECT 1 FROM (VALUES
                (scope_row.attestation->>'ordinary_positive_amount'),
                (scope_row.attestation->>'recognised_deduction_amount'),
                (scope_row.attestation->>'usable_same_candidate_headroom'),
                (scope_row.attestation->>'candidate_ready_amount')) amount_value(value)
              WHERE COALESCE(amount_value.value,'')!~'^[-]?[0-9]+([.][0-9]+)?$')
            OR EXISTS(SELECT 1 FROM (VALUES
                (scope_row.attestation->>'source_digest'),
                (scope_row.attestation->>'source_identity_digest'),
                (scope_row.attestation->>'preview_identity_digest'),
                (scope_row.attestation->>'semantic_proof_digest')) digest(value)
              WHERE COALESCE(digest.value,'')!~'^[0-9a-f]{32}$')
            OR EXISTS(SELECT 1 FROM (VALUES
                (scope_row.attestation->>'certification_digest'),
                (scope_row.attestation->>'admission_seal_digest'),
                (scope_row.attestation->>'projection_fingerprint'),
                (scope_row.attestation->>'original_semantic_proof_digest')) optional_digest(value)
              WHERE optional_digest.value IS NOT NULL
                AND optional_digest.value!~'^[0-9a-f]{32}$')
            OR pg_catalog.jsonb_typeof(scope_row.attestation->'section_counts')<>'object'
            OR (scope_row.attestation ? 'selection_recovery_headroom_v1'
              AND pg_catalog.jsonb_typeof(
                scope_row.attestation->'selection_recovery_headroom_v1')<>'object')
            OR COALESCE(scope_row.attestation->>'scope_ordinal','')!~'^[1-9][0-9]{0,17}$'
            OR COALESCE(scope_row.attestation->>'minimum_public_ordinal','')!~'^[1-9][0-9]{0,17}$'
            OR COALESCE(scope_row.attestation->>'maximum_public_ordinal','')!~'^[1-9][0-9]{0,17}$'
            OR CASE WHEN COALESCE(scope_row.attestation->>'minimum_public_ordinal','')
                  ~'^[1-9][0-9]{0,17}$'
                AND COALESCE(scope_row.attestation->>'maximum_public_ordinal','')
                  ~'^[1-9][0-9]{0,17}$'
              THEN (scope_row.attestation->>'minimum_public_ordinal')::numeric>
                (scope_row.attestation->>'maximum_public_ordinal')::numeric
              ELSE false END
            OR (scope_row.attestation ? 'certification_version'
              AND COALESCE(scope_row.attestation->>'certification_version','')
                !~'^[1-9][0-9]{0,8}$')
            OR (scope_row.attestation ? 'admission_seal_version'
              AND COALESCE(scope_row.attestation->>'admission_seal_version','')
                !~'^[1-9][0-9]{0,8}$')
            OR NULLIF(pg_catalog.btrim(COALESCE(scope_row.attestation->>'refresh_scope_kind','')),'') IS NULL
            OR NULLIF(pg_catalog.btrim(COALESCE(scope_row.attestation->>'attested_at_utc','')),'') IS NULL
            OR COALESCE(scope_row.attestation->>'policy_x_authority_scope','')
                <>'PRE_DRAFT_LIVE_TRUTH'
            OR (scope_row.attestation->>'authority_kind'='CERTIFIED_CANCELLATION_REVERSION'
              AND (COALESCE(scope_row.attestation->>'cancellation_request_id','')
                    !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                OR COALESCE(scope_row.attestation->>'cancellation_operation_id','')
                    !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                OR COALESCE(scope_row.attestation->>'cancellation_work_item_id','')
                    !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                OR COALESCE(scope_row.attestation->>'pay_batch_id','')
                    !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                OR COALESCE(scope_row.attestation->>'cancellation_reversion_run_id','')
                    !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                OR COALESCE(scope_row.attestation->>'financial_reversion_digest','')
                    !~'^[0-9a-f]{32}$'))
          THEN 1 ELSE 0 END AS invalid_scope,
          private.pay_payment_correction_sha256_v1(scope_row.attestation)
            AS complete_attestation_digest
        FROM referenced_scopes scope_row
        CROSS JOIN attestation_contract contract
      ), scope_set_entries AS MATERIALIZED (
        SELECT validated.candidate_scope_id,
          pg_catalog.jsonb_build_object(
            'candidate_scope_id',validated.candidate_scope_id,
            'draft_operation_id',validated.scope_operation_id,
            'pay_batch_id',validated.scope_batch_id,
            'candidate_id',validated.scope_candidate_id,
            'workbench_session_id',validated.workbench_session_id,
            'source_session_version',validated.source_session_version,
            'pay_channel',validated.scope_pay_channel,
            'scope_hash',validated.scope_hash,
            'scope_status',validated.scope_status,
            'complete_attestation_digest',validated.complete_attestation_digest)
            AS scope_entry
        FROM validated_scope_attestations validated
      ), scope_summary AS MATERIALIZED (
        SELECT pg_catalog.count(*)::integer AS scope_count,
          COALESCE(pg_catalog.sum(validated.invalid_scope),0)::integer AS invalid_scope_count,
          pg_catalog.count(DISTINCT validated.attestation)::integer
            AS distinct_common_authority_count,
          CASE WHEN pg_catalog.count(DISTINCT validated.attestation)=1
            THEN (pg_catalog.jsonb_agg(DISTINCT validated.attestation
              ORDER BY validated.attestation)->0) END AS common_attestation,
          CASE WHEN pg_catalog.count(DISTINCT validated.attestation)=1
            THEN private.pay_payment_correction_sha256_v1(
              (pg_catalog.jsonb_agg(DISTINCT validated.attestation
                ORDER BY validated.attestation)->0)) END AS common_attestation_digest,
          private.pay_payment_correction_sha256_v1(pg_catalog.jsonb_build_object(
            'contract_version','EXECUTION_RESIDUAL_REFERENCED_SCOPE_SET_V1',
            'referenced_scopes',COALESCE((SELECT pg_catalog.jsonb_agg(
              entry.scope_entry ORDER BY entry.candidate_scope_id)
              FROM scope_set_entries entry),'[]'::jsonb))) AS referenced_scope_set_digest
        FROM validated_scope_attestations validated
      )
      SELECT
        (SELECT pg_catalog.count(*)::integer FROM item_rows),
        (SELECT pg_catalog.count(*)::integer FROM exact_rows),
        (SELECT pg_catalog.count(*)::integer FROM allocation_counts WHERE allocation_count>1),
        (SELECT scope_count FROM scope_summary),
        (SELECT distinct_common_authority_count FROM scope_summary),
        (SELECT common_attestation FROM scope_summary),
        (SELECT invalid_scope_count FROM scope_summary),
        (SELECT common_attestation_digest FROM scope_summary),
        (SELECT referenced_scope_set_digest FROM scope_summary),
        (SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
          'pay_batch_item_id',id,'item_type',item_type,'pay_channel',pay_channel,
          'timesheet_id',timesheet_id,'amount_ex_vat',amount_ex_vat,
          'amount_vat',amount_vat,'amount_inc_vat',amount_inc_vat,
          'reservation_id',reservation_id,'finance_case_id',finance_case_id,
          'finance_component_id',finance_component_id,'pay_bank_transfer_id',pay_bank_transfer_id,
          'operation_source_key',operation_source_key,'source_ref',source_ref,
          'frozen_component_snapshot_json',frozen_component_snapshot_json,
          'frozen_source_basis_json',frozen_source_basis_json,
          'allocation_id',allocation_id,'allocation_operation_id',allocation_operation_id,
          'allocation_candidate_scope_id',candidate_scope_id,
          'allocation_status',allocation_status,'allocation_type',allocation_type,
          'allocation_source_ref',allocation_source_ref,'allocated_amount',allocated_amount,
          'allocation_operation_source_key',allocation_operation_source_key,
          'allocation_batch_id',allocation_batch_id,'allocation_candidate_id',allocation_candidate_id,
          'allocation_basis_json',allocation_basis_json,'candidate_scope_id',candidate_scope_id,
          'candidate_scope_pay_channel',scope_pay_channel,'candidate_scope_hash',scope_hash,
          'scope_operation_id',scope_operation_id,'scope_batch_id',scope_batch_id,
          'scope_candidate_id',scope_candidate_id,'scope_workbench_session_id',workbench_session_id,
          'scope_source_session_version',source_session_version,'scope_status',scope_status,
          'v3_source_build_run_id',scope_basis#>>'{source_publication_attestation,source_build_run_id}',
          'v3_source_publication_id',scope_basis#>>'{source_publication_attestation,source_publication_id}',
          'v3_source_change_seq',scope_basis#>>'{source_publication_attestation,source_change_seq}',
          'v3_source_identity_digest',scope_basis#>>'{source_publication_attestation,source_identity_digest}',
          'v3_semantic_proof_digest',scope_basis#>>'{source_publication_attestation,semantic_proof_digest}'
        ) ORDER BY id),'[]'::jsonb) FROM exact_rows),
        (SELECT pg_catalog.md5(COALESCE(pg_catalog.string_agg(
          id::text||':'||COALESCE(timesheet_id::text,'')||':'||
          COALESCE(pay_bank_transfer_id::text,'')||':'||COALESCE(amount_inc_vat::text,'')||':'||
          COALESCE(item_type,'')||':'||COALESCE(finance_case_id::text,'')||':'||
          COALESCE(finance_component_id::text,'')||':'||COALESCE(reservation_id::text,''),
          '|' ORDER BY id),'')) FROM item_rows)
      INTO v_resolved_item_count,v_allocation_count,v_ambiguous_allocation_count,
        v_scope_count,v_attestation_identity_count,v_attestation,v_invalid_scope_count,
        v_common_attestation_digest,v_referenced_scope_set_digest,v_selected_items,
        v_active_item_scope_digest;

      IF v_resolved_item_count<>v_item_count THEN v_rejection:='EXECUTION_RESIDUAL_SELECTED_ITEM_MISSING';
      ELSIF v_ambiguous_allocation_count>0 THEN v_rejection:='EXECUTION_RESIDUAL_SELECTED_ITEM_ALLOCATION_AMBIGUOUS';
      ELSIF v_allocation_count<>v_item_count THEN v_rejection:='EXECUTION_RESIDUAL_SELECTED_ITEM_ALLOCATION_MISSING';
      ELSIF v_scope_count<1
        THEN v_rejection:='EXECUTION_RESIDUAL_CANDIDATE_SCOPE_PUBLICATION_MISSING';
      ELSIF v_invalid_scope_count<>0
        THEN v_rejection:='EXECUTION_RESIDUAL_REFERENCED_SCOPE_INVALID';
      ELSIF v_attestation_identity_count<>1
        THEN v_rejection:='EXECUTION_RESIDUAL_COMMON_PUBLICATION_AUTHORITY_CONFLICT';
      ELSIF EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(v_selected_items) AS selected(value)
        WHERE selected.value->>'allocation_operation_id'<>COALESCE(v_chain->>'draft_operation_id','')
           OR selected.value->>'allocation_status'<>'ITEM_CREATED'
           OR selected.value->>'operation_source_key'
                IS DISTINCT FROM selected.value->>'allocation_operation_source_key'
           OR selected.value->>'allocation_batch_id'<>p_pay_batch_id::text
           OR selected.value->>'allocation_candidate_id'<>v_candidate::text
           OR selected.value->>'scope_operation_id'<>COALESCE(v_chain->>'draft_operation_id','')
           OR selected.value->>'scope_batch_id'<>p_pay_batch_id::text
           OR selected.value->>'scope_candidate_id'<>v_candidate::text
           OR selected.value->>'scope_workbench_session_id'<>p_workbench_session_id::text
           OR selected.value->>'scope_source_session_version'<>p_workbench_session_version::text
           OR selected.value->>'scope_status'<>'DRAFTED'
      ) THEN v_rejection:='EXECUTION_RESIDUAL_ALLOCATION_SOURCE_KEY_MISMATCH';
      ELSIF COALESCE(v_attestation->>'attestation_version','')<>'CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V3'
         OR COALESCE(v_attestation->>'semantic_contract_version','')<>'READY_TO_PAY_SEMANTIC_V2'
         OR pg_catalog.lower(pg_catalog.btrim(COALESCE(v_attestation->>'semantic_ready','')))
              NOT IN ('true','t','1','yes','y','on')
         OR pg_catalog.lower(pg_catalog.btrim(COALESCE(v_attestation->>'parity_complete','')))
              NOT IN ('true','t','1','yes','y','on')
         OR COALESCE(v_attestation->>'candidate_id','')<>v_candidate::text
         OR COALESCE(v_attestation->>'session_id','')<>p_workbench_session_id::text
         OR COALESCE(v_attestation->>'session_version','')<>p_workbench_session_version::text
         OR COALESCE(v_attestation->>'source_build_run_id','')
              !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
         OR COALESCE(v_attestation->>'source_publication_id','')
              !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
         OR COALESCE(v_attestation->>'source_change_seq','')!~'^[0-9]{1,18}$'
         OR COALESCE(v_attestation->>'source_row_count','')!~'^[0-9]{1,9}$'
         OR COALESCE(v_attestation->>'source_build_run_id','')<>COALESCE(v_chain->>'original_source_build_run_id','')
         OR COALESCE(v_attestation->>'source_publication_id','')<>COALESCE(v_chain->>'original_source_publication_id','')
         OR COALESCE(v_attestation->>'source_change_seq','')<>COALESCE(v_chain->>'pre_execution_source_change_seq','')
         OR COALESCE(v_attestation->>'source_identity_digest','')<>COALESCE(v_chain->>'original_source_identity_digest','')
         OR COALESCE(v_attestation->>'semantic_proof_digest','')<>COALESCE(v_chain->>'original_semantic_proof_digest','')
        THEN v_rejection:='EXECUTION_RESIDUAL_V3_ATTESTATION_INVALID';
      ELSIF v_mode='PRE_REQUEST_START'
         AND v_active_item_scope_digest IS DISTINCT FROM v_chain->>'active_item_scope_digest'
        THEN v_rejection:='EXECUTION_RESIDUAL_SELECTED_ITEM_CONTRACT_MISMATCH';
      END IF;
      IF v_rejection IS NULL THEN
        v_frozen_scope_ordinal:=(v_attestation->>'scope_ordinal')::bigint;
      END IF;
    END IF;

    IF v_rejection IS NULL THEN
      v_selected_anchor_digest:=private.pay_payment_correction_sha256_v1(
        pg_catalog.jsonb_build_object(
          'contract_version','EXECUTION_RESIDUAL_SELECTED_ANCHOR_V1',
          'correction_request_id',p_correction_request_id,
          'correction_operation_id',p_correction_operation_id,
          'execution_operation_id',p_execution_operation_id,'pay_batch_id',p_pay_batch_id,
          'pay_batch_candidate_id',v_request_candidate.pay_batch_candidate_id,
          'candidate_id',v_candidate,'request_selection_hash',v_request.selection_hash,
          'request_plan_hash',v_request.plan_hash,
          'candidate_scope_hash',v_request_candidate.candidate_scope_hash,
          'selected_item_count',v_item_count,'selected_items',v_selected_items
        )
      );
      IF v_mode='ROUTE_REPLAY' AND v_selected_anchor_digest
           IS DISTINCT FROM p_expected_selected_anchor_digest_by_candidate->>v_candidate::text THEN
        v_rejection:='EXECUTION_RESIDUAL_SELECTED_ANCHOR_DIGEST_MISMATCH';
      END IF;
    END IF;

    IF v_rejection IS NULL THEN
      WITH original_rows AS (
        SELECT source_row.id,source_row.source_ordinal,source_row.line_key,
          public.pay_workbench_preview_section_from_line_json(source_row.source_row_json) AS section,
          source_row.timesheet_id,source_row.source_row_json,
          source_row.source_build_run_id,source_row.source_publication_id,
          source_row.source_change_seq
        FROM public.banking_pay_workbench_candidate_source_lines AS source_row
        WHERE source_row.session_id=p_workbench_session_id
          AND source_row.candidate_id=v_candidate
          AND source_row.session_version=p_workbench_session_version
          AND source_row.source_change_seq=(v_attestation->>'source_change_seq')::bigint
          AND source_row.source_build_run_id=(v_attestation->>'source_build_run_id')::uuid
          AND source_row.source_publication_id=(v_attestation->>'source_publication_id')::uuid
      ), current_rows AS (
        SELECT source_row.id,source_row.source_ordinal,source_row.line_key,
          public.pay_workbench_preview_section_from_line_json(source_row.source_row_json) AS section,
          source_row.timesheet_id,source_row.source_row_json,
          source_row.source_build_run_id,source_row.source_publication_id
        FROM public.banking_pay_workbench_candidate_source_lines AS source_row
        WHERE source_row.session_id=p_workbench_session_id
          AND source_row.candidate_id=v_candidate AND source_row.status='CURRENT'
      ), ready_rows_raw AS MATERIALIZED (
        SELECT preview.section,preview.row_key AS line_key,preview.row_ordinal,
          preview.row_json,
          CASE WHEN COALESCE(preview.row_json->>'source_ordinal','')~'^[1-9][0-9]{0,17}$'
            THEN (preview.row_json->>'source_ordinal')::bigint END AS source_ordinal,
          CASE WHEN pg_catalog.pg_input_is_valid(
              COALESCE(preview.row_json->>'source_line_id',''),'uuid')
            THEN (preview.row_json->>'source_line_id')::uuid END AS source_line_id
        FROM public.banking_pay_workbench_preview_rows AS preview
        WHERE preview.session_id=p_workbench_session_id
          AND preview.candidate_id=v_candidate
          AND preview.session_version=p_workbench_session_version
          AND preview.status='READY'
      ), ready_rows_validated AS MATERIALIZED (
        SELECT ready.*,original.id AS matched_source_line_id,
          original.source_ordinal AS matched_source_ordinal,
          original.section AS matched_section,original.line_key AS matched_line_key,
          CASE WHEN ready.source_ordinal IS NULL OR ready.source_line_id IS NULL
              OR original.id IS NULL
              OR original.source_ordinal IS DISTINCT FROM ready.source_ordinal
              OR original.section IS DISTINCT FROM ready.section
              OR original.line_key IS DISTINCT FROM ready.line_key
              OR ready.row_ordinal::numeric IS DISTINCT FROM
                (v_frozen_scope_ordinal::numeric*1000000::numeric
                  +ready.source_ordinal::numeric)
            THEN 1 ELSE 0 END AS identity_invalid
        FROM ready_rows_raw ready
        LEFT JOIN original_rows original ON original.id=ready.source_line_id
      ), ready_rows AS (
        SELECT ready.section,ready.line_key,ready.source_ordinal,ready.row_json
        FROM ready_rows_validated ready
        WHERE ready.identity_invalid=0
      ), chain_transitions AS (
        SELECT transition.value AS transition_json
        FROM pg_catalog.jsonb_array_elements(COALESCE(v_chain->'transitions','[]'::jsonb))
          AS transition(value)
        WHERE pg_catalog.jsonb_typeof(transition.value)='object'
      ), chain_job_ids AS (
        SELECT DISTINCT job_id.value::uuid AS job_id
        FROM chain_transitions
        CROSS JOIN LATERAL pg_catalog.jsonb_array_elements_text(
          CASE WHEN pg_catalog.jsonb_typeof(chain_transitions.transition_json->'dirty_job_ids')='array'
            THEN chain_transitions.transition_json->'dirty_job_ids' ELSE '[]'::jsonb END
        ) AS job_id(value)
        WHERE pg_catalog.pg_input_is_valid(job_id.value,'uuid')
      ), chain_context_digests AS (
        SELECT DISTINCT context_digest.value AS context_digest
        FROM chain_transitions
        CROSS JOIN LATERAL pg_catalog.jsonb_array_elements_text(
          CASE WHEN pg_catalog.jsonb_typeof(chain_transitions.transition_json->'context_digests')='array'
            THEN chain_transitions.transition_json->'context_digests' ELSE '[]'::jsonb END
        ) AS context_digest(value)
        WHERE context_digest.value~'^[0-9a-f]{32}$'
      ), context_jobs AS (
        SELECT dirty_job.id,dirty_job.payload_json
        FROM chain_job_ids
        JOIN public.banking_pay_workbench_jobs AS dirty_job ON dirty_job.id=chain_job_ids.job_id
        WHERE dirty_job.candidate_id=v_candidate
          AND dirty_job.job_type='WORKBENCH_CANDIDATE_DIRTY_APPLY'
      ), schedule_contexts AS (
        SELECT context_jobs.id AS dirty_job_id,context_row.context_json,
          context_row.context_json->>'context_digest' AS context_digest
        FROM context_jobs
        CROSS JOIN LATERAL (
          SELECT context_jobs.payload_json->'execution_overlay_schedule_contexts'
            ->v_candidate::text AS context_json
        ) AS context_row
        WHERE COALESCE(context_jobs.payload_json->>'execution_overlay_schedule_causal_contract_version','')
                ='EXECUTION_UNSENT_SCHEDULE_CAUSAL_V2'
          AND pg_catalog.jsonb_typeof(context_row.context_json)='object'
          AND COALESCE(context_row.context_json->>'contract_version','')
                ='EXECUTION_UNSENT_SCHEDULE_CONTEXT_V2'
          AND COALESCE(context_row.context_json->>'execution_operation_id','')
                =p_execution_operation_id::text
          AND COALESCE(context_row.context_json->>'pay_batch_id','')=p_pay_batch_id::text
          AND COALESCE(context_row.context_json->>'candidate_id','')=v_candidate::text
          AND COALESCE(context_row.context_json->>'source_workbench_session_id','')
                =p_workbench_session_id::text
          AND COALESCE(context_row.context_json->>'source_session_version','')
                =p_workbench_session_version::text
          AND pg_catalog.jsonb_typeof(context_row.context_json->'pay_batch_candidate_ids')='array'
          AND pg_catalog.jsonb_typeof(context_row.context_json->'pay_batch_item_ids')='array'
          AND pg_catalog.jsonb_typeof(context_row.context_json->'timesheet_ids')='array'
          AND pg_catalog.jsonb_typeof(context_row.context_json->'transfer_scope_ids')='array'
          AND pg_catalog.jsonb_typeof(context_row.context_json->'pay_bank_transfer_ids')='array'
          AND pg_catalog.jsonb_typeof(context_row.context_json->'reservation_ids')='array'
          AND pg_catalog.jsonb_typeof(context_row.context_json->'finance_case_ids')='array'
          AND pg_catalog.jsonb_typeof(context_row.context_json->'finance_component_ids')='array'
          AND EXISTS (SELECT 1 FROM chain_context_digests
            WHERE chain_context_digests.context_digest=context_row.context_json->>'context_digest')
          AND context_row.context_json->>'context_digest'=pg_catalog.md5(
            COALESCE(context_row.context_json->>'execution_operation_id','')||'|'||
            COALESCE(context_row.context_json->>'pay_batch_id','')||'|'||
            COALESCE(context_row.context_json->>'candidate_id','')||'|'||
            (context_row.context_json->'pay_batch_candidate_ids')::text||'|'||
            (context_row.context_json->'pay_batch_item_ids')::text||'|'||
            (context_row.context_json->'timesheet_ids')::text||'|'||
            (context_row.context_json->'transfer_scope_ids')::text||'|'||
            (context_row.context_json->'pay_bank_transfer_ids')::text||'|'||
            (context_row.context_json->'reservation_ids')::text||'|'||
            (context_row.context_json->'finance_case_ids')::text||'|'||
            (context_row.context_json->'finance_component_ids')::text||'|'||
            COALESCE(context_row.context_json->>'source_workbench_session_id','')||'|'||
            COALESCE(context_row.context_json->>'source_snapshot_run_id','')||'|'||
            COALESCE(context_row.context_json->>'source_session_version','')||
            '|EXECUTION_UNSENT_SCHEDULE_CONTEXT_V2'
          )
      ), link_contexts AS (
        SELECT context_jobs.id AS dirty_job_id,context_row.context_json,
          context_row.context_json->>'context_digest' AS context_digest
        FROM context_jobs
        CROSS JOIN LATERAL (
          SELECT context_jobs.payload_json->'execution_overlay_contexts'
            ->v_candidate::text AS context_json
        ) AS context_row
        WHERE COALESCE(context_jobs.payload_json->>'execution_overlay_causal_contract_version','')
                ='EXECUTION_UNSENT_OVERLAY_CAUSAL_V1'
          AND pg_catalog.jsonb_typeof(context_row.context_json)='object'
          AND COALESCE(context_row.context_json->>'contract_version','')
                ='EXECUTION_UNSENT_OVERLAY_CONTEXT_V1'
          AND COALESCE(context_row.context_json->>'execution_operation_id','')
                =p_execution_operation_id::text
          AND COALESCE(context_row.context_json->>'pay_batch_id','')=p_pay_batch_id::text
          AND COALESCE(context_row.context_json->>'candidate_id','')=v_candidate::text
          AND COALESCE(context_row.context_json->>'source_workbench_session_id','')
                =p_workbench_session_id::text
          AND COALESCE(context_row.context_json->>'source_session_version','')
                =p_workbench_session_version::text
          AND pg_catalog.jsonb_typeof(context_row.context_json->'pay_batch_candidate_ids')='array'
          AND pg_catalog.jsonb_typeof(context_row.context_json->'pay_batch_item_ids')='array'
          AND pg_catalog.jsonb_typeof(context_row.context_json->'timesheet_ids')='array'
          AND pg_catalog.jsonb_typeof(context_row.context_json->'transfer_scope_ids')='array'
          AND pg_catalog.jsonb_typeof(context_row.context_json->'pay_bank_transfer_ids')='array'
          AND EXISTS (SELECT 1 FROM chain_context_digests
            WHERE chain_context_digests.context_digest=context_row.context_json->>'context_digest')
          AND context_row.context_json->>'context_digest'=pg_catalog.md5(
            COALESCE(context_row.context_json->>'execution_operation_id','')||'|'||
            COALESCE(context_row.context_json->>'pay_batch_id','')||'|'||
            COALESCE(context_row.context_json->>'candidate_id','')||'|'||
            (context_row.context_json->'pay_batch_candidate_ids')::text||'|'||
            (context_row.context_json->'pay_batch_item_ids')::text||'|'||
            (context_row.context_json->'timesheet_ids')::text||'|'||
            (context_row.context_json->'transfer_scope_ids')::text||'|'||
            (context_row.context_json->'pay_bank_transfer_ids')::text||'|'||
            COALESCE(context_row.context_json->>'source_workbench_session_id','')||'|'||
            COALESCE(context_row.context_json->>'source_snapshot_run_id','')||'|'||
            COALESCE(context_row.context_json->>'source_session_version','')||
            '|EXECUTION_UNSENT_OVERLAY_CONTEXT_V1'
          )
      ), selected_allocations AS (
        SELECT item.id AS pay_batch_item_id,item.pay_batch_candidate_id,item.item_type,
          item.timesheet_id AS item_timesheet_id,
          item.reservation_id,item.finance_case_id,item.finance_component_id,item.amount_inc_vat,
          item.source_ref AS item_source_ref,allocation.allocation_type,
          allocation.source_ref AS allocation_source_ref,allocation.allocation_basis_json,
          CASE WHEN COALESCE(allocation.allocation_basis_json#>>'{line,source_line_id}','')
            ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN (allocation.allocation_basis_json#>>'{line,source_line_id}')::uuid END AS source_line_id,
          CASE WHEN COALESCE(allocation.allocation_basis_json#>>'{line,timesheet_id}','')
            ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN (allocation.allocation_basis_json#>>'{line,timesheet_id}')::uuid END AS linked_timesheet_id,
          allocation.allocation_basis_json#>>'{line,economic_key}' AS allocation_economic_key
        FROM pg_catalog.unnest(v_request_candidate.pay_batch_item_ids) AS selected(item_id)
        JOIN public.pay_batch_items AS item ON item.id=selected.item_id
        JOIN public.banking_pay_operation_candidate_allocation_rows AS allocation
          ON allocation.pay_batch_item_id=item.id
      ), context_matches AS (
        SELECT selected_allocations.pay_batch_item_id,
          schedule_contexts.context_digest AS schedule_context_digest,
          link_contexts.context_digest AS link_context_digest
        FROM selected_allocations
        JOIN schedule_contexts ON EXISTS (
          SELECT 1 FROM pg_catalog.jsonb_array_elements_text(
            schedule_contexts.context_json->'pay_batch_item_ids'
          ) AS context_item(value)
          WHERE context_item.value=selected_allocations.pay_batch_item_id::text
        ) AND EXISTS (
          SELECT 1 FROM pg_catalog.jsonb_array_elements_text(
            schedule_contexts.context_json->'pay_batch_candidate_ids'
          ) AS context_candidate(value)
          WHERE context_candidate.value=selected_allocations.pay_batch_candidate_id::text
        ) AND (selected_allocations.item_timesheet_id IS NULL OR EXISTS (
          SELECT 1 FROM pg_catalog.jsonb_array_elements_text(
            schedule_contexts.context_json->'timesheet_ids'
          ) AS context_timesheet(value)
          WHERE context_timesheet.value=selected_allocations.item_timesheet_id::text
        )) AND (selected_allocations.reservation_id IS NULL OR EXISTS (
          SELECT 1 FROM pg_catalog.jsonb_array_elements_text(
            schedule_contexts.context_json->'reservation_ids'
          ) AS context_reservation(value)
          WHERE context_reservation.value=selected_allocations.reservation_id::text
        )) AND (selected_allocations.finance_case_id IS NULL OR EXISTS (
          SELECT 1 FROM pg_catalog.jsonb_array_elements_text(
            schedule_contexts.context_json->'finance_case_ids'
          ) AS context_case(value)
          WHERE context_case.value=selected_allocations.finance_case_id::text
        )) AND (selected_allocations.finance_component_id IS NULL OR EXISTS (
          SELECT 1 FROM pg_catalog.jsonb_array_elements_text(
            schedule_contexts.context_json->'finance_component_ids'
          ) AS context_component(value)
          WHERE context_component.value=selected_allocations.finance_component_id::text
        ))
        JOIN link_contexts ON EXISTS (
          SELECT 1 FROM pg_catalog.jsonb_array_elements_text(
            link_contexts.context_json->'pay_batch_item_ids'
          ) AS context_item(value)
          WHERE context_item.value=selected_allocations.pay_batch_item_id::text
        ) AND EXISTS (
          SELECT 1 FROM pg_catalog.jsonb_array_elements_text(
            link_contexts.context_json->'pay_batch_candidate_ids'
          ) AS context_candidate(value)
          WHERE context_candidate.value=selected_allocations.pay_batch_candidate_id::text
        ) AND (selected_allocations.item_timesheet_id IS NULL OR EXISTS (
          SELECT 1 FROM pg_catalog.jsonb_array_elements_text(
            link_contexts.context_json->'timesheet_ids'
          ) AS context_timesheet(value)
          WHERE context_timesheet.value=selected_allocations.item_timesheet_id::text
        ))
      ), context_rollup AS (
        SELECT selected_allocations.pay_batch_item_id,
          pg_catalog.count(DISTINCT context_matches.schedule_context_digest)::integer
            AS schedule_context_count,
          pg_catalog.count(DISTINCT context_matches.link_context_digest)::integer
            AS link_context_count,
          pg_catalog.min(context_matches.schedule_context_digest) AS schedule_context_digest,
          pg_catalog.min(context_matches.link_context_digest) AS link_context_digest
        FROM selected_allocations
        LEFT JOIN context_matches
          ON context_matches.pay_batch_item_id=selected_allocations.pay_batch_item_id
        GROUP BY selected_allocations.pay_batch_item_id
      ), context_bound_allocations AS (
        SELECT selected_allocations.*,context_rollup.schedule_context_digest,
          context_rollup.link_context_digest
        FROM selected_allocations
        JOIN context_rollup ON context_rollup.pay_batch_item_id=selected_allocations.pay_batch_item_id
          AND context_rollup.schedule_context_count=1 AND context_rollup.link_context_count=1
      ), anchors AS (
        SELECT original_rows.*,context_bound_allocations.pay_batch_item_id,
          context_bound_allocations.linked_timesheet_id,context_bound_allocations.item_type,
          context_bound_allocations.reservation_id,context_bound_allocations.finance_case_id,
          context_bound_allocations.finance_component_id,context_bound_allocations.amount_inc_vat,
          context_bound_allocations.item_source_ref,context_bound_allocations.allocation_type,
          context_bound_allocations.allocation_source_ref,
          context_bound_allocations.allocation_economic_key,
          context_bound_allocations.schedule_context_digest AS transition_context_digest
        FROM context_bound_allocations
        JOIN original_rows ON original_rows.id=context_bound_allocations.source_line_id
      ), recovery_anchors AS (
        SELECT anchors.*
        FROM anchors
        WHERE pg_catalog.upper(pg_catalog.btrim(COALESCE(anchors.item_type,'')))
                ='OVERPAYMENT_RECOVERY'
          AND pg_catalog.upper(pg_catalog.btrim(COALESCE(anchors.allocation_type,'')))
                ='OVERPAYMENT_RECOVERY'
          AND COALESCE(anchors.amount_inc_vat,0)<0
          AND anchors.finance_case_id IS NOT NULL
          AND anchors.finance_component_id IS NOT NULL
          AND anchors.linked_timesheet_id IS NOT NULL
          AND anchors.source_row_json->>'finance_case_id'=anchors.finance_case_id::text
          AND anchors.source_row_json->>'finance_component_id'=anchors.finance_component_id::text
          AND anchors.source_row_json->>'source_ref'=anchors.item_source_ref
          AND anchors.source_row_json->>'source_ref'=anchors.allocation_source_ref
          AND anchors.source_row_json->>'economic_key'=anchors.allocation_economic_key
      ), recovery_parent_candidates AS (
        SELECT recovery_anchors.id AS recovery_source_line_id,original_rows.*,
          recovery_anchors.transition_context_digest
        FROM recovery_anchors
        JOIN original_rows
          ON original_rows.section=recovery_anchors.section
         AND original_rows.timesheet_id=recovery_anchors.linked_timesheet_id
         AND original_rows.line_key=recovery_anchors.linked_timesheet_id::text
         AND COALESCE(original_rows.source_row_json->>'presentation_role','')='PARENT'
      ), recovery_parent_rollup AS (
        SELECT recovery_anchors.id AS recovery_source_line_id,
          pg_catalog.count(DISTINCT recovery_parent_candidates.id)::integer AS parent_count
        FROM recovery_anchors
        LEFT JOIN recovery_parent_candidates
          ON recovery_parent_candidates.recovery_source_line_id=recovery_anchors.id
        GROUP BY recovery_anchors.id
      ), affected_candidates AS (
        SELECT recovery_anchors.id,recovery_anchors.source_ordinal,recovery_anchors.line_key,
          recovery_anchors.section,recovery_anchors.timesheet_id,recovery_anchors.source_row_json,
          recovery_anchors.source_build_run_id,recovery_anchors.source_publication_id,
          recovery_anchors.source_change_seq,
          'SELECTED_FROZEN_RECOVERY_ANCHOR'::text AS closure_reason,
          recovery_anchors.transition_context_digest
        FROM recovery_anchors
        UNION ALL
        SELECT recovery_parent_candidates.id,recovery_parent_candidates.source_ordinal,
          recovery_parent_candidates.line_key,recovery_parent_candidates.section,
          recovery_parent_candidates.timesheet_id,recovery_parent_candidates.source_row_json,
          recovery_parent_candidates.source_build_run_id,
          recovery_parent_candidates.source_publication_id,
          recovery_parent_candidates.source_change_seq,
          'SELECTED_RECOVERY_TIMESHEET_PARENT'::text AS closure_reason,
          recovery_parent_candidates.transition_context_digest
        FROM recovery_parent_candidates
      ), affected_context_rollup AS (
        SELECT affected_candidates.id,
          pg_catalog.count(DISTINCT affected_candidates.transition_context_digest)::integer
            AS context_digest_count
        FROM affected_candidates GROUP BY affected_candidates.id
      ), affected AS (
        SELECT DISTINCT ON (affected_candidates.id)
          affected_candidates.id,affected_candidates.source_ordinal,
          affected_candidates.line_key,affected_candidates.section,
          affected_candidates.timesheet_id,affected_candidates.source_row_json,
          affected_candidates.source_build_run_id,affected_candidates.source_publication_id,
          affected_candidates.source_change_seq,affected_candidates.closure_reason,
          affected_candidates.transition_context_digest
        FROM affected_candidates
        JOIN affected_context_rollup ON affected_context_rollup.id=affected_candidates.id
        ORDER BY affected_candidates.id,affected_candidates.closure_reason,
          affected_candidates.transition_context_digest
      ), expected_rows AS (
        SELECT original_rows.* FROM original_rows
        WHERE NOT EXISTS (SELECT 1 FROM affected WHERE affected.id=original_rows.id)
      ), partition_rows AS (
        SELECT section,line_key,source_ordinal FROM expected_rows
        UNION ALL SELECT section,line_key,source_ordinal FROM affected
      )
      SELECT
        (SELECT pg_catalog.count(*)::integer FROM anchors),
        (SELECT pg_catalog.count(*)::integer FROM context_bound_allocations),
        (SELECT pg_catalog.count(*)::integer FROM context_rollup
          WHERE schedule_context_count<>1 OR link_context_count<>1),
        (SELECT pg_catalog.count(*)::integer FROM context_rollup
          WHERE schedule_context_count>1 OR link_context_count>1),
        (SELECT pg_catalog.count(*)::integer FROM selected_allocations
          WHERE COALESCE(selected_allocations.amount_inc_vat,0)<0
            AND NOT EXISTS (
              SELECT 1 FROM recovery_anchors
              WHERE recovery_anchors.pay_batch_item_id=selected_allocations.pay_batch_item_id
            )),
        (SELECT pg_catalog.count(*)::integer FROM recovery_parent_rollup
          WHERE recovery_parent_rollup.parent_count<>1)
          +(SELECT pg_catalog.count(*)::integer FROM affected_context_rollup
            WHERE affected_context_rollup.context_digest_count<>1),
        (SELECT pg_catalog.count(*)::integer FROM original_rows),
        (SELECT pg_catalog.count(*)::integer FROM affected),
        (SELECT pg_catalog.count(*)::integer FROM expected_rows),
        (SELECT pg_catalog.count(*)::integer FROM current_rows),
        (SELECT pg_catalog.count(*)::integer FROM ready_rows),
        (SELECT COALESCE(pg_catalog.sum(identity_invalid),0)::integer
          FROM ready_rows_validated),
        (SELECT pg_catalog.count(*)::integer FROM (
          SELECT section,line_key,source_ordinal FROM original_rows EXCEPT ALL SELECT * FROM partition_rows
        ) d),(SELECT pg_catalog.count(*)::integer FROM (
          SELECT * FROM partition_rows EXCEPT ALL SELECT section,line_key,source_ordinal FROM original_rows
        ) d),(SELECT pg_catalog.count(*)::integer FROM (
          SELECT section,line_key,source_ordinal FROM expected_rows EXCEPT ALL SELECT section,line_key,source_ordinal FROM current_rows
        ) d),(SELECT pg_catalog.count(*)::integer FROM (
          SELECT section,line_key,source_ordinal FROM current_rows EXCEPT ALL SELECT section,line_key,source_ordinal FROM expected_rows
        ) d),(SELECT pg_catalog.count(*)::integer FROM (
          SELECT section,line_key,source_ordinal FROM expected_rows EXCEPT ALL SELECT section,line_key,source_ordinal FROM ready_rows
        ) d),(SELECT pg_catalog.count(*)::integer FROM (
          SELECT section,line_key,source_ordinal FROM ready_rows EXCEPT ALL SELECT section,line_key,source_ordinal FROM expected_rows
        ) d),(SELECT pg_catalog.count(*)::integer FROM (
          SELECT section,line_key,source_ordinal FROM current_rows EXCEPT ALL SELECT section,line_key,source_ordinal FROM ready_rows
        ) d),(SELECT pg_catalog.count(*)::integer FROM (
          SELECT section,line_key,source_ordinal FROM ready_rows EXCEPT ALL SELECT section,line_key,source_ordinal FROM current_rows
        ) d),
        (SELECT pg_catalog.count(*)::integer FROM (
          SELECT section,line_key FROM current_rows GROUP BY section,line_key HAVING pg_catalog.count(*)>1
        ) d),
        (SELECT pg_catalog.count(*)::integer FROM current_rows
          WHERE source_build_run_id<>(v_attestation->>'source_build_run_id')::uuid
             OR source_publication_id<>(v_attestation->>'source_publication_id')::uuid),
        pg_catalog.md5(COALESCE((SELECT pg_catalog.string_agg(section||E'\x1f'||line_key||E'\x1f'||source_ordinal::text,E'\x1e' ORDER BY source_ordinal,section,line_key) FROM original_rows),'')),
        pg_catalog.md5(COALESCE((SELECT pg_catalog.string_agg(section||E'\x1f'||line_key||E'\x1f'||source_ordinal::text,E'\x1e' ORDER BY source_ordinal,section,line_key) FROM expected_rows),'')),
        pg_catalog.md5(COALESCE((SELECT pg_catalog.string_agg(section||E'\x1f'||line_key||E'\x1f'||source_ordinal::text,E'\x1e' ORDER BY source_ordinal,section,line_key) FROM current_rows),'')),
        pg_catalog.md5(COALESCE((SELECT pg_catalog.string_agg(section||E'\x1f'||line_key||E'\x1f'||source_ordinal::text,E'\x1e' ORDER BY source_ordinal,section,line_key) FROM ready_rows),'')),
        pg_catalog.md5(COALESCE((SELECT pg_catalog.string_agg(pg_catalog.md5(source_row_json::text),'' ORDER BY source_ordinal) FROM expected_rows),'')),
        pg_catalog.md5(COALESCE((SELECT pg_catalog.string_agg(pg_catalog.md5(source_row_json::text),'' ORDER BY source_ordinal) FROM current_rows),'')),
        COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
          'source_line_id',id,'physical_section',section,'line_key',line_key,
          'source_ordinal',source_ordinal,'timesheet_id',timesheet_id,
          'source_build_run_id',source_build_run_id,'source_publication_id',source_publication_id,
          'source_change_seq',source_change_seq,'closure_reason',closure_reason,
          'transition_context_digest',transition_context_digest
        ) ORDER BY source_ordinal,section,line_key,id) FROM affected),'[]'::jsonb)
      INTO v_anchor_count,v_context_bound_item_count,v_context_unproved_item_count,
        v_context_ambiguous_item_count,v_unproved_affected_item_count,
        v_affected_closure_ambiguity_count,
        v_f_count,v_a_count,v_e_count,v_c_count,v_p_count,
        v_ready_identity_invalid_count,
        v_f_minus_partition,v_partition_minus_f,v_e_minus_c,v_c_minus_e,
        v_e_minus_p,v_p_minus_e,v_c_minus_p,v_p_minus_c,
        v_duplicate_active_identity_count,v_lineage_mismatch_count,
        v_f_identity,v_e_identity,v_c_identity,v_p_identity,
        v_e_semantic,v_c_semantic,v_affected_rows;

      IF v_anchor_count<>v_item_count THEN v_rejection:='EXECUTION_RESIDUAL_SELECTED_ITEM_ALLOCATION_MISSING';
      ELSIF v_context_ambiguous_item_count<>0
        THEN v_rejection:='EXECUTION_RESIDUAL_V2_TRANSITION_CONTEXT_AMBIGUOUS';
      ELSIF v_context_bound_item_count<>v_item_count OR v_context_unproved_item_count<>0
        THEN v_rejection:='EXECUTION_RESIDUAL_V2_TRANSITION_CONTEXT_MISSING';
      ELSIF v_unproved_affected_item_count<>0
        THEN v_rejection:='EXECUTION_RESIDUAL_AFFECTED_SCOPE_UNPROVED';
      ELSIF v_affected_closure_ambiguity_count<>0
        THEN v_rejection:='EXECUTION_RESIDUAL_AFFECTED_SCOPE_AMBIGUOUS';
      ELSIF v_f_count IS DISTINCT FROM (v_attestation->>'source_row_count')::integer
        OR v_f_identity IS DISTINCT FROM v_attestation->>'source_identity_digest'
        THEN v_rejection:='EXECUTION_RESIDUAL_ORIGINAL_SOURCE_PUBLICATION_MISMATCH';
      ELSIF v_f_minus_partition<>0 OR v_partition_minus_f<>0
        OR v_e_minus_c<>0 OR v_c_minus_e<>0 OR v_e_minus_p<>0 OR v_p_minus_e<>0
        OR v_c_minus_p<>0 OR v_p_minus_c<>0
        OR v_duplicate_active_identity_count<>0 OR v_lineage_mismatch_count<>0
        OR v_ready_identity_invalid_count<>0
        OR v_e_semantic IS DISTINCT FROM v_c_semantic
        THEN v_rejection:='EXECUTION_RESIDUAL_IDENTITY_MISMATCH';
      END IF;
    END IF;

    v_affected_digest:=private.pay_payment_correction_sha256_v1(
      pg_catalog.jsonb_build_object(
        'contract_version','EXECUTION_RESIDUAL_AFFECTED_PHYSICAL_CLOSURE_V1',
        'selected_anchor_digest',v_selected_anchor_digest,
        'referenced_scope_count',v_scope_count,
        'invalid_referenced_scope_count',v_invalid_scope_count,
        'common_publication_attestation_digest',v_common_attestation_digest,
        'referenced_scope_set_digest',v_referenced_scope_set_digest,
        'frozen_scope_ordinal',v_frozen_scope_ordinal,
        'execution_operation_id',p_execution_operation_id,
        'v2_chain_digest',v_chain->>'chain_digest',
        'affected_physical_rows',COALESCE(v_affected_rows,'[]'::jsonb)
      )
    );
    v_residual_digest:=private.pay_payment_correction_sha256_v1(
      pg_catalog.jsonb_build_object(
        'contract_version','EXECUTION_RESIDUAL_IDENTITY_PROOF_V1',
        'correction_request_id',p_correction_request_id,
        'correction_operation_id',p_correction_operation_id,
        'execution_operation_id',p_execution_operation_id,'pay_batch_id',p_pay_batch_id,
        'candidate_id',v_candidate,'request_selection_hash',v_request.selection_hash,
        'request_plan_hash',v_request.plan_hash,'v2_chain_digest',v_chain->>'chain_digest',
        'selected_anchor_digest',v_selected_anchor_digest,
        'referenced_scope_count',v_scope_count,
        'invalid_referenced_scope_count',v_invalid_scope_count,
        'common_publication_attestation_digest',v_common_attestation_digest,
        'referenced_scope_set_digest',v_referenced_scope_set_digest,
        'frozen_scope_ordinal',v_frozen_scope_ordinal,
        'affected_physical_closure_digest',v_affected_digest,
        'frozen_original_count',v_f_count,'affected_physical_count',v_a_count,
        'expected_residual_count',v_e_count,'current_source_count',v_c_count,
        'ready_preview_count',v_p_count,'frozen_original_identity_digest',v_f_identity,
        'expected_residual_identity_digest',v_e_identity,
        'current_source_identity_digest',v_c_identity,'ready_preview_identity_digest',v_p_identity,
        'expected_residual_semantic_digest',v_e_semantic,'current_source_semantic_digest',v_c_semantic,
        'f_minus_partition_count',v_f_minus_partition,'partition_minus_f_count',v_partition_minus_f,
        'expected_minus_current_count',v_e_minus_c,'current_minus_expected_count',v_c_minus_e,
        'expected_minus_preview_count',v_e_minus_p,'preview_minus_expected_count',v_p_minus_e,
        'current_minus_preview_count',v_c_minus_p,'preview_minus_current_count',v_p_minus_c,
        'duplicate_active_identity_count',v_duplicate_active_identity_count,
        'lineage_mismatch_count',v_lineage_mismatch_count,
        'ready_identity_invalid_count',v_ready_identity_invalid_count,
        'context_unproved_item_count',v_context_unproved_item_count,
        'context_ambiguous_item_count',v_context_ambiguous_item_count,
        'unproved_affected_item_count',v_unproved_affected_item_count,
        'affected_closure_ambiguity_count',v_affected_closure_ambiguity_count,
        'semantic_mismatch_count',CASE WHEN v_e_semantic IS DISTINCT FROM v_c_semantic THEN 1 ELSE 0 END,
        'admitted',v_rejection IS NULL,'rejection_reason',v_rejection
      )
    );
    v_authority_digest:=private.pay_payment_correction_sha256_v1(
      pg_catalog.jsonb_build_object(
        'contract_version','CANCELLATION_REVERSION_Q_BOUND_PRE_REQUEST_START_AUTHORITY_V1',
        'boundary','AFTER_REQUEST_PREPARE_BEFORE_REQUEST_START',
        'correction_request_id',p_correction_request_id,
        'correction_operation_id',p_correction_operation_id,
        'execution_operation_id',p_execution_operation_id,'pay_batch_id',p_pay_batch_id,
        'pay_batch_candidate_id',v_request_candidate.pay_batch_candidate_id,
        'candidate_id',v_candidate,'workbench_session_id',p_workbench_session_id,
        'workbench_session_version',p_workbench_session_version,
        'request_selection_hash',v_request.selection_hash,'request_plan_hash',v_request.plan_hash,
        'v2_chain_digest',v_chain->>'chain_digest','selected_anchor_digest',v_selected_anchor_digest,
        'referenced_scope_count',v_scope_count,
        'invalid_referenced_scope_count',v_invalid_scope_count,
        'common_publication_attestation_digest',v_common_attestation_digest,
        'referenced_scope_set_digest',v_referenced_scope_set_digest,
        'frozen_scope_ordinal',v_frozen_scope_ordinal,
        'affected_physical_closure_digest',v_affected_digest,
        'residual_proof_digest',v_residual_digest,
        'request_owned_dirty_job_id',v_request_owned_dirty_job_id,
        'request_owned_dirty_proven',v_request_owned_dirty_proven,
        'live_source_change_seq',v_live_source_change_seq,
        'live_dirty_generation',v_live_dirty_generation
      )
    );

    v_results:=v_results||pg_catalog.jsonb_build_array(pg_catalog.jsonb_strip_nulls(
      pg_catalog.jsonb_build_object(
        'candidate_id',v_candidate,'pay_batch_candidate_id',v_request_candidate.pay_batch_candidate_id,
        'admitted',v_rejection IS NULL,'rejection_reason',v_rejection,
        'v2_chain_digest',v_chain->>'chain_digest','selected_anchor_digest',v_selected_anchor_digest,
        'referenced_scope_count',v_scope_count,
        'invalid_referenced_scope_count',v_invalid_scope_count,
        'common_publication_attestation_digest',v_common_attestation_digest,
        'referenced_scope_set_digest',v_referenced_scope_set_digest,
        'frozen_scope_ordinal',v_frozen_scope_ordinal,
        'frozen_attestation',v_attestation,
        'affected_physical_closure_digest',v_affected_digest,'residual_proof_digest',v_residual_digest,
        'authority_digest',v_authority_digest,'frozen_original_count',v_f_count,
        'request_owned_dirty_job_id',v_request_owned_dirty_job_id,
        'request_owned_dirty_proven',v_request_owned_dirty_proven,
        'affected_physical_count',v_a_count,'expected_residual_count',v_e_count,
        'current_source_count',v_c_count,'ready_preview_count',v_p_count,
        'context_unproved_item_count',v_context_unproved_item_count,
        'context_ambiguous_item_count',v_context_ambiguous_item_count,
        'unproved_affected_item_count',v_unproved_affected_item_count,
        'affected_closure_ambiguity_count',v_affected_closure_ambiguity_count,
        'ready_identity_invalid_count',v_ready_identity_invalid_count,
        'expected_residual_identity_digest',v_e_identity,
        'current_source_identity_digest',v_c_identity,'ready_preview_identity_digest',v_p_identity,
        'affected_physical_rows',COALESCE(v_affected_rows,'[]'::jsonb)
      )
    ));
    v_authorities:=v_authorities||pg_catalog.jsonb_build_object(v_candidate::text,
      pg_catalog.jsonb_build_object(
        'contract_version','CANCELLATION_REVERSION_Q_BOUND_PRE_REQUEST_START_AUTHORITY_V1',
        'pay_batch_candidate_id',v_request_candidate.pay_batch_candidate_id,
        'v2_chain_digest',v_chain->>'chain_digest','selected_anchor_digest',v_selected_anchor_digest,
        'referenced_scope_count',v_scope_count,
        'invalid_referenced_scope_count',v_invalid_scope_count,
        'common_publication_attestation_digest',v_common_attestation_digest,
        'referenced_scope_set_digest',v_referenced_scope_set_digest,
        'frozen_scope_ordinal',v_frozen_scope_ordinal,
        'frozen_attestation',v_attestation,
        'affected_physical_closure_digest',v_affected_digest,'residual_proof_digest',v_residual_digest,
        'authority_digest',v_authority_digest,'admitted',v_rejection IS NULL,
        'rejection_reason',v_rejection
      ));
  END LOOP;

  RETURN pg_catalog.jsonb_build_object(
    'ok',true,'contract_version','EXECUTION_RESIDUAL_IDENTITY_PROOF_PAGE_V1',
    'mode',v_mode,'boundary','AFTER_REQUEST_PREPARE_BEFORE_REQUEST_START',
    'correction_request_id',p_correction_request_id,
    'correction_operation_id',p_correction_operation_id,
    'execution_operation_id',p_execution_operation_id,'pay_batch_id',p_pay_batch_id,
    'workbench_session_id',p_workbench_session_id,
    'workbench_session_version',p_workbench_session_version,
    'request_selection_hash',v_request.selection_hash,'request_plan_hash',v_request.plan_hash,
    'candidate_count',v_supplied_candidate_count,
    'admitted_count',(SELECT pg_catalog.count(*)::integer
      FROM pg_catalog.jsonb_array_elements(v_results) AS result(value)
      WHERE COALESCE((result.value->>'admitted')::boolean,false)),
    'all_admitted',NOT EXISTS (
      SELECT 1 FROM pg_catalog.jsonb_array_elements(v_results) AS result(value)
      WHERE COALESCE((result.value->>'admitted')::boolean,false) IS NOT TRUE
    ),
    'candidate_results',v_results,'candidate_authorities',v_authorities,
    'authority_set_digest',private.pay_payment_correction_sha256_v1(
      pg_catalog.jsonb_build_object(
        'contract_version','CANCELLATION_REVERSION_Q_BOUND_PRE_REQUEST_START_SET_V1',
        'boundary','AFTER_REQUEST_PREPARE_BEFORE_REQUEST_START',
        'correction_request_id',p_correction_request_id,
        'correction_operation_id',p_correction_operation_id,
        'execution_operation_id',p_execution_operation_id,'pay_batch_id',p_pay_batch_id,
        'request_selection_hash',v_request.selection_hash,'request_plan_hash',v_request.plan_hash,
        'candidate_authorities',v_authorities
      )
    ),
    'policy_x_authority_scope','POST_DRAFT_FROZEN_SELECTION_PLUS_EXACT_V2_UNSENT_EXECUTION_RESIDUAL'
  );
END;
$function$;

-- private.pay_workbench_execution_unsent_overlay_chain_seal_v2(uuid,uuid,jsonb)
CREATE OR REPLACE FUNCTION private.pay_workbench_execution_unsent_overlay_chain_seal_v2(p_operation_id uuid, p_pay_batch_id uuid, p_options_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_operation public.banking_pay_operations%ROWTYPE;
  v_batch public.pay_batches%ROWTYPE;
  v_candidate record;
  v_candidate_result jsonb;
  v_candidate_results jsonb:='{}'::jsonb;
  v_candidate_count integer:=0;
  v_closed_count integer:=0;
  v_transition_count integer:=0;
  v_distinct_generation_count integer:=0;
  v_link_transition_count integer:=0;
  v_schedule_transition_count integer:=0;
  v_non_final_count integer:=0;
  v_invalid_owned_event_count integer:=0;
  v_owned_source_event_count integer:=0;
  v_terminal_generation bigint:=NULL::bigint;
  v_first_generation bigint:=NULL::bigint;
  v_terminal_token uuid:=NULL::uuid;
  v_live_generation bigint:=0;
  v_live_source_seq bigint:=0;
  v_pre_execution_source_seq bigint:=NULL::bigint;
  v_live_token uuid:=NULL::uuid;
  v_registry_generation bigint:=NULL::bigint;
  v_registry_token uuid:=NULL::uuid;
  v_unowned_generation_count integer:=0;
  v_transition_rows jsonb:='[]'::jsonb;
  v_active_item_scope_digest text:=NULL::text;
  v_transfer_scope_digest text:=NULL::text;
  v_provider_attempt_count integer:=0;
  v_transfer_event_count integer:=0;
  v_unsafe_transfer_count integer:=0;
  v_settlement_count integer:=0;
  v_remittance_count integer:=0;
  v_rejection_reason text:=NULL::text;
  v_chain_digest text:=NULL::text;
  v_draft_operation_id uuid:=NULL::uuid;
  v_original_economic_build_id text:=NULL::text;
  v_original_source_build_run_id text:=NULL::text;
  v_original_source_publication_id text:=NULL::text;
  v_original_source_identity_digest text:=NULL::text;
  v_original_semantic_proof_digest text:=NULL::text;
BEGIN
  IF p_operation_id IS NULL OR p_pay_batch_id IS NULL
     OR pg_catalog.jsonb_typeof(COALESCE(p_options_json,'{}'::jsonb))<>'object'
     OR COALESCE(p_options_json,'{}'::jsonb)<>'{}'::jsonb THEN
    RAISE EXCEPTION 'EXECUTION_UNSENT_OVERLAY_CHAIN_SEAL_ARGUMENT_INVALID'
      USING ERRCODE='P0001',DETAIL=pg_catalog.jsonb_build_object(
        'code','EXECUTION_UNSENT_OVERLAY_CHAIN_SEAL_ARGUMENT_INVALID'
      )::text;
  END IF;

  SELECT operation_row.* INTO v_operation
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id=p_operation_id;

  SELECT batch_row.* INTO v_batch
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id=p_pay_batch_id;

  IF v_operation.id IS NULL OR v_batch.id IS NULL
     OR pg_catalog.upper(pg_catalog.btrim(COALESCE(v_operation.operation_type,'')))<>'PAYMENT_EXECUTE'
     OR v_operation.pay_batch_id IS DISTINCT FROM p_pay_batch_id THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok',false,'contract_version','EXECUTION_UNSENT_OVERLAY_CHAIN_V2',
      'closed',false,'rejection_reason','EXECUTION_OVERLAY_CHAIN_OPERATION_MISMATCH'
    );
  END IF;

  SELECT pg_catalog.count(DISTINCT membership.candidate_id)::integer
  INTO v_candidate_count
  FROM public.banking_pay_operation_transfer_scope_items AS membership
  WHERE membership.operation_id=p_operation_id
    AND membership.pay_batch_id=p_pay_batch_id
    AND membership.candidate_id IS NOT NULL;

  IF v_candidate_count<1 OR v_candidate_count>100 THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok',false,'contract_version','EXECUTION_UNSENT_OVERLAY_CHAIN_V2',
      'closed',false,'candidate_count',v_candidate_count,
      'rejection_reason',CASE WHEN v_candidate_count>100
        THEN 'EXECUTION_OVERLAY_CHAIN_CANDIDATE_LIMIT_EXCEEDED'
        ELSE 'EXECUTION_OVERLAY_CHAIN_SCOPE_MISSING' END
    );
  END IF;

  FOR v_candidate IN
    SELECT DISTINCT membership.candidate_id
    FROM public.banking_pay_operation_transfer_scope_items AS membership
    WHERE membership.operation_id=p_operation_id
      AND membership.pay_batch_id=p_pay_batch_id
      AND membership.candidate_id IS NOT NULL
    ORDER BY membership.candidate_id
  LOOP
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
      public._pay_workbench_candidate_serial_key(v_candidate.candidate_id),24062027));

    v_rejection_reason:=NULL::text;
    v_transition_count:=0;
    v_distinct_generation_count:=0;
    v_link_transition_count:=0;
    v_schedule_transition_count:=0;
    v_non_final_count:=0;
    v_invalid_owned_event_count:=0;
    v_owned_source_event_count:=0;
    v_terminal_generation:=NULL::bigint;
    v_first_generation:=NULL::bigint;
    v_terminal_token:=NULL::uuid;
    v_live_generation:=0;
    v_live_source_seq:=0;
    v_pre_execution_source_seq:=NULL::bigint;
    v_live_token:=NULL::uuid;
    v_registry_generation:=NULL::bigint;
    v_registry_token:=NULL::uuid;
    v_unowned_generation_count:=0;
    v_transition_rows:='[]'::jsonb;
    v_active_item_scope_digest:=NULL::text;
    v_transfer_scope_digest:=NULL::text;
    v_provider_attempt_count:=0;
    v_transfer_event_count:=0;
    v_unsafe_transfer_count:=0;
    v_settlement_count:=0;
    v_remittance_count:=0;
    v_chain_digest:=NULL::text;
    v_draft_operation_id:=NULL::uuid;
    v_original_economic_build_id:=NULL::text;
    v_original_source_build_run_id:=NULL::text;
    v_original_source_publication_id:=NULL::text;
    v_original_source_identity_digest:=NULL::text;
    v_original_semantic_proof_digest:=NULL::text;

    WITH owned_contexts AS (
      SELECT job.id AS dirty_job_id,job.status AS job_status,
        CASE WHEN COALESCE(job.payload_json->>'execution_overlay_scope_change_tx_token','')
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN (job.payload_json->>'execution_overlay_scope_change_tx_token')::uuid END AS tx_token,
        'EXECUTION_UNSENT_OVERLAY_CAUSAL_V1'::text AS causal_contract_version,
        job.payload_json->'execution_overlay_contexts'->v_candidate.candidate_id::text
          AS context_json
      FROM public.banking_pay_workbench_jobs AS job
      WHERE job.candidate_id=v_candidate.candidate_id
        AND job.job_type='WORKBENCH_CANDIDATE_DIRTY_APPLY'
        AND COALESCE(job.payload_json->>'execution_overlay_causal_contract_version','')
              ='EXECUTION_UNSENT_OVERLAY_CAUSAL_V1'
        AND COALESCE(job.payload_json->'execution_overlay_contexts'
              ->v_candidate.candidate_id::text->>'execution_operation_id','')=p_operation_id::text
        AND COALESCE(job.payload_json->'execution_overlay_contexts'
              ->v_candidate.candidate_id::text->>'pay_batch_id','')=p_pay_batch_id::text

      UNION ALL

      SELECT job.id,job.status,
        CASE WHEN COALESCE(job.payload_json->>'execution_overlay_schedule_scope_change_tx_token','')
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN (job.payload_json->>'execution_overlay_schedule_scope_change_tx_token')::uuid END,
        'EXECUTION_UNSENT_SCHEDULE_CAUSAL_V2'::text,
        job.payload_json->'execution_overlay_schedule_contexts'->v_candidate.candidate_id::text
      FROM public.banking_pay_workbench_jobs AS job
      WHERE job.candidate_id=v_candidate.candidate_id
        AND job.job_type='WORKBENCH_CANDIDATE_DIRTY_APPLY'
        AND COALESCE(job.payload_json->>'execution_overlay_schedule_causal_contract_version','')
              ='EXECUTION_UNSENT_SCHEDULE_CAUSAL_V2'
        AND COALESCE(job.payload_json->'execution_overlay_schedule_contexts'
              ->v_candidate.candidate_id::text->>'execution_operation_id','')=p_operation_id::text
        AND COALESCE(job.payload_json->'execution_overlay_schedule_contexts'
              ->v_candidate.candidate_id::text->>'pay_batch_id','')=p_pay_batch_id::text
    ), owned_tokens AS (
      SELECT context_row.tx_token,
        pg_catalog.min(context_row.dirty_job_id::text)::uuid AS representative_job_id,
        pg_catalog.jsonb_agg(DISTINCT context_row.dirty_job_id::text
          ORDER BY context_row.dirty_job_id::text) AS dirty_job_ids,
        pg_catalog.jsonb_agg(DISTINCT context_row.causal_contract_version
          ORDER BY context_row.causal_contract_version) AS causal_contract_versions,
        pg_catalog.jsonb_agg(DISTINCT context_row.context_json->>'context_digest'
          ORDER BY context_row.context_json->>'context_digest')
          FILTER (WHERE NULLIF(context_row.context_json->>'context_digest','') IS NOT NULL)
          AS context_digests,
        pg_catalog.max(CASE
          WHEN COALESCE(context_row.context_json->>'owned_source_event_count','') ~ '^[1-9][0-9]{0,8}$'
            THEN (context_row.context_json->>'owned_source_event_count')::integer
          ELSE NULL::integer
        END) AS owned_source_event_count,
        pg_catalog.bool_and(
          COALESCE(context_row.context_json->>'owned_source_event_count','') ~ '^[1-9][0-9]{0,8}$'
          AND COALESCE(context_row.context_json->>'owned_source_event_count_digest','')
              =pg_catalog.md5(
                COALESCE(context_row.context_json->>'context_digest','')||'|'||
                context_row.tx_token::text||'|'||v_candidate.candidate_id::text||'|'||
                COALESCE(context_row.context_json->>'owned_source_event_count','')||
                '|EXECUTION_OWNED_SOURCE_EVENT_COUNT_V1'
              )
        ) AS owned_source_event_count_exact
      FROM owned_contexts AS context_row
      WHERE context_row.tx_token IS NOT NULL
      GROUP BY context_row.tx_token
    ), transitions AS (
      SELECT owned_tokens.*,scope_tx.state,scope_tx.allocated_generation,
        pg_catalog.md5(
          owned_tokens.tx_token::text||'|'||COALESCE(scope_tx.allocated_generation::text,'')||'|'||
          COALESCE(owned_tokens.dirty_job_ids::text,'[]')||'|'||
          COALESCE(owned_tokens.causal_contract_versions::text,'[]')||'|'||
          COALESCE(owned_tokens.context_digests::text,'[]')||'|'||
          COALESCE(owned_tokens.owned_source_event_count::text,'')||'|'||
          COALESCE(owned_tokens.owned_source_event_count_exact::text,'')||
          '|EXECUTION_OVERLAY_TRANSITION_V2'
        ) AS transition_digest
      FROM owned_tokens
      LEFT JOIN public.banking_pay_scope_change_transactions AS scope_tx
        ON scope_tx.tx_token=owned_tokens.tx_token
    )
    SELECT pg_catalog.count(*)::integer,
      pg_catalog.count(DISTINCT allocated_generation)::integer,
      pg_catalog.count(*) FILTER (
        WHERE causal_contract_versions @> '["EXECUTION_UNSENT_OVERLAY_CAUSAL_V1"]'::jsonb
      )::integer,
      pg_catalog.count(*) FILTER (
        WHERE causal_contract_versions @> '["EXECUTION_UNSENT_SCHEDULE_CAUSAL_V2"]'::jsonb
      )::integer,
      pg_catalog.count(*) FILTER (WHERE state<>'FINALIZED' OR allocated_generation IS NULL)::integer,
      pg_catalog.count(*) FILTER (
        WHERE owned_source_event_count IS NULL OR owned_source_event_count_exact IS NOT TRUE
      )::integer,
      COALESCE(pg_catalog.sum(owned_source_event_count),0)::integer,
      pg_catalog.min(allocated_generation),pg_catalog.max(allocated_generation),
      (pg_catalog.array_agg(tx_token ORDER BY allocated_generation DESC,tx_token DESC))[1],
      COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'ordinal',ordinality,'scope_change_tx_token',tx_token,
        'allocated_generation',allocated_generation,'transaction_state',state,
        'representative_dirty_job_id',representative_job_id,'dirty_job_ids',dirty_job_ids,
        'causal_contract_versions',causal_contract_versions,
        'context_digests',COALESCE(context_digests,'[]'::jsonb),
        'owned_source_event_count',owned_source_event_count,
        'owned_source_event_count_exact',owned_source_event_count_exact,
        'transition_digest',transition_digest
      ) ORDER BY ordinality),'[]'::jsonb)
    INTO v_transition_count,v_distinct_generation_count,v_link_transition_count,
      v_schedule_transition_count,v_non_final_count,v_invalid_owned_event_count,
      v_owned_source_event_count,v_first_generation,
      v_terminal_generation,v_terminal_token,v_transition_rows
    FROM (
      SELECT transitions.*,
        pg_catalog.row_number() OVER (ORDER BY allocated_generation,tx_token)::integer AS ordinality
      FROM transitions
    ) AS ordered_transitions;

    SELECT COALESCE(counter.seq,0),COALESCE(counter.scope_change_generation,0),
      counter.scope_change_tx_token,registry.dirty_generation,registry.last_scope_change_tx_token
    INTO v_live_source_seq,v_live_generation,v_live_token,
      v_registry_generation,v_registry_token
    FROM public.app_change_counters AS counter
    LEFT JOIN private.banking_pay_workbench_candidate_scope_registry AS registry
      ON registry.candidate_id=v_candidate.candidate_id
    WHERE counter.entity_key='pay_candidate:'||v_candidate.candidate_id::text;

    SELECT draft_operation.id,
      draft_scope.allocation_basis_json#>>'{source_publication_attestation,economic_build_id}',
      COALESCE(
        draft_scope.allocation_basis_json#>>'{source_publication_attestation,original_source_build_run_id}',
        draft_scope.allocation_basis_json->>'source_build_run_id'
      ),
      draft_scope.allocation_basis_json->>'source_publication_id',
      draft_scope.allocation_basis_json->>'source_identity_digest',
      draft_scope.allocation_basis_json->>'semantic_proof_digest',
      CASE
        WHEN COALESCE(
          draft_scope.allocation_basis_json#>>'{post_draft_authority,source_change_seq}',''
        ) ~ '^[0-9]{1,18}$'
          THEN (draft_scope.allocation_basis_json#>>'{post_draft_authority,source_change_seq}')::bigint
        ELSE NULL::bigint
      END
    INTO v_draft_operation_id,v_original_economic_build_id,
      v_original_source_build_run_id,v_original_source_publication_id,
      v_original_source_identity_digest,v_original_semantic_proof_digest,
      v_pre_execution_source_seq
    FROM public.banking_pay_operations AS draft_operation
    JOIN public.banking_pay_operation_candidate_scope AS draft_scope
      ON draft_scope.operation_id=draft_operation.id
     AND draft_scope.pay_batch_id=p_pay_batch_id
     AND draft_scope.candidate_id=v_candidate.candidate_id
     AND draft_scope.status NOT IN ('FAILED','CANCELLED','SUPERSEDED')
    WHERE draft_operation.operation_type='DRAFT_CREATE'
      AND draft_operation.status='COMPLETE'
    ORDER BY draft_operation.completed_at_utc DESC NULLS LAST,
      draft_operation.created_at_utc DESC,draft_operation.id DESC
    LIMIT 1;

    SELECT pg_catalog.count(DISTINCT candidate_job.scope_change_generation)::integer
    INTO v_unowned_generation_count
    FROM public.banking_pay_workbench_jobs AS candidate_job
    WHERE candidate_job.candidate_id=v_candidate.candidate_id
      AND candidate_job.job_type='WORKBENCH_CANDIDATE_DIRTY_APPLY'
      AND candidate_job.scope_change_generation BETWEEN v_first_generation AND v_terminal_generation
      AND NOT EXISTS (
        SELECT 1
        FROM pg_catalog.jsonb_array_elements(v_transition_rows) AS transition(value)
        WHERE (transition.value->>'allocated_generation')::bigint
              =candidate_job.scope_change_generation
      );

    WITH active_items AS (
      SELECT item.id,item.timesheet_id,item.pay_bank_transfer_id,item.amount_inc_vat,
        item.item_type,item.finance_case_id,item.finance_component_id,item.reservation_id
      FROM public.pay_batch_items AS item
      JOIN public.pay_batch_candidates AS candidate_row
        ON candidate_row.id=item.pay_batch_candidate_id
      WHERE candidate_row.pay_batch_id=p_pay_batch_id
        AND candidate_row.candidate_id=v_candidate.candidate_id
        AND COALESCE(item.is_voided,false) IS NOT TRUE
    ), transfer_membership AS (
      SELECT membership.transfer_scope_id,membership.pay_batch_item_id,
        transfer_scope.pay_bank_transfer_id,membership.item_amount
      FROM public.banking_pay_operation_transfer_scope_items AS membership
      JOIN public.banking_pay_operation_transfer_scope AS transfer_scope
        ON transfer_scope.id=membership.transfer_scope_id
       AND transfer_scope.operation_id=membership.operation_id
      WHERE membership.operation_id=p_operation_id
        AND membership.pay_batch_id=p_pay_batch_id
        AND membership.candidate_id=v_candidate.candidate_id
    )
    SELECT
      pg_catalog.md5(COALESCE((SELECT pg_catalog.string_agg(
        active_items.id::text||':'||COALESCE(active_items.timesheet_id::text,'')||':'||
        COALESCE(active_items.pay_bank_transfer_id::text,'')||':'||
        COALESCE(active_items.amount_inc_vat::text,'')||':'||COALESCE(active_items.item_type,'')||':'||
        COALESCE(active_items.finance_case_id::text,'')||':'||
        COALESCE(active_items.finance_component_id::text,'')||':'||
        COALESCE(active_items.reservation_id::text,'')
        ,'|' ORDER BY active_items.id) FROM active_items),'')),
      pg_catalog.md5(COALESCE((SELECT pg_catalog.string_agg(
        transfer_membership.transfer_scope_id::text||':'||
        transfer_membership.pay_batch_item_id::text||':'||
        COALESCE(transfer_membership.pay_bank_transfer_id::text,'')||':'||
        COALESCE(transfer_membership.item_amount::text,'')
        ,'|' ORDER BY transfer_membership.transfer_scope_id,transfer_membership.pay_batch_item_id)
        FROM transfer_membership),'')),
      (SELECT pg_catalog.count(*)::integer
       FROM public.banking_pay_operation_provider_attempts AS attempt
       WHERE attempt.operation_id=p_operation_id OR attempt.pay_batch_id=p_pay_batch_id),
      (SELECT pg_catalog.count(*)::integer FROM public.pay_bank_transfer_events AS event_row
       WHERE event_row.pay_batch_id=p_pay_batch_id),
      (SELECT pg_catalog.count(*)::integer FROM public.pay_bank_transfers AS transfer_row
       WHERE transfer_row.id IN (SELECT pay_bank_transfer_id FROM transfer_membership)
         AND (pg_catalog.upper(pg_catalog.btrim(COALESCE(transfer_row.status,'')))<>'PENDING'
           OR transfer_row.rail_tx_id IS NOT NULL OR transfer_row.completed_at_utc IS NOT NULL
           OR pg_catalog.upper(pg_catalog.btrim(COALESCE(transfer_row.rail_state,'')))
                NOT IN ('','LOCAL','PENDING'))),
      (SELECT pg_catalog.count(*)::integer FROM public.pay_batch_candidates AS candidate_row
       WHERE candidate_row.pay_batch_id=p_pay_batch_id
         AND candidate_row.candidate_id=v_candidate.candidate_id
         AND (pg_catalog.upper(COALESCE(candidate_row.settlement_status,''))='SETTLED'
           OR candidate_row.settled_at_utc IS NOT NULL)),
      (SELECT pg_catalog.count(*)::integer FROM public.pay_batch_candidates AS candidate_row
       WHERE candidate_row.pay_batch_id=p_pay_batch_id
         AND candidate_row.candidate_id=v_candidate.candidate_id
         AND candidate_row.remittance_sent_at_utc IS NOT NULL)
    INTO v_active_item_scope_digest,v_transfer_scope_digest,
      v_provider_attempt_count,v_transfer_event_count,v_unsafe_transfer_count,
      v_settlement_count,v_remittance_count;

    v_rejection_reason:=CASE
      WHEN v_transition_count<1 THEN 'EXECUTION_OVERLAY_CHAIN_MISSING'
      WHEN v_transition_count>16 THEN 'EXECUTION_OVERLAY_CHAIN_TOO_LARGE'
      WHEN v_distinct_generation_count<>v_transition_count
        THEN 'EXECUTION_OVERLAY_CHAIN_DUPLICATE_GENERATION'
      WHEN v_link_transition_count<1 OR v_schedule_transition_count<1
        THEN 'EXECUTION_OVERLAY_CHAIN_INCOMPLETE'
      WHEN v_non_final_count<>0 THEN 'EXECUTION_OVERLAY_CHAIN_NON_FINAL_TRANSACTION'
      WHEN v_invalid_owned_event_count<>0 OR v_owned_source_event_count<v_transition_count
        THEN 'EXECUTION_OVERLAY_CHAIN_SOURCE_EVENT_PROOF_INVALID'
      WHEN v_unowned_generation_count<>0 THEN 'EXECUTION_OVERLAY_CHAIN_UNOWNED_TRANSITION'
      WHEN v_draft_operation_id IS NULL
        OR COALESCE(v_original_economic_build_id,'')
             !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        OR COALESCE(v_original_source_build_run_id,'')
             !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        OR COALESCE(v_original_source_publication_id,'')
             !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        OR NULLIF(pg_catalog.btrim(COALESCE(v_original_source_identity_digest,'')),'') IS NULL
        OR NULLIF(pg_catalog.btrim(COALESCE(v_original_semantic_proof_digest,'')),'') IS NULL
        OR v_pre_execution_source_seq IS NULL
        THEN 'EXECUTION_OVERLAY_DRAFT_AUTHORITY_MISSING'
      WHEN v_live_source_seq IS DISTINCT FROM
           (v_pre_execution_source_seq+v_owned_source_event_count)
        THEN 'EXECUTION_OVERLAY_CHAIN_SOURCE_SEQUENCE_MISMATCH'
      WHEN v_terminal_generation IS DISTINCT FROM v_live_generation
        OR v_registry_generation IS DISTINCT FROM v_live_generation
        THEN 'EXECUTION_OVERLAY_CHAIN_TERMINAL_GENERATION_MISMATCH'
      -- Finalization deliberately clears the staged live token fields.  The
      -- immutable terminal token remains in the FINALIZED transaction receipt.
      WHEN v_live_token IS NOT NULL OR v_registry_token IS NOT NULL
        THEN 'EXECUTION_OVERLAY_CHAIN_LIVE_TOKEN_NOT_CLEARED'
      WHEN pg_catalog.upper(pg_catalog.btrim(COALESCE(v_batch.execution_commit_state,'NOT_SUBMITTED')))
            <>'NOT_SUBMITTED'
        THEN 'EXECUTION_OVERLAY_PROVIDER_ACTIVITY_PRESENT'
      WHEN v_provider_attempt_count<>0 THEN 'EXECUTION_OVERLAY_PROVIDER_ACTIVITY_PRESENT'
      WHEN v_transfer_event_count<>0 OR v_unsafe_transfer_count<>0
        THEN 'EXECUTION_OVERLAY_RAIL_ACTIVITY_PRESENT'
      WHEN v_settlement_count<>0 OR v_remittance_count<>0
        THEN 'EXECUTION_OVERLAY_SETTLEMENT_OR_REMITTANCE_PRESENT'
      ELSE NULL::text
    END;

    v_chain_digest:=pg_catalog.md5(
      p_operation_id::text||'|'||p_pay_batch_id::text||'|'||v_candidate.candidate_id::text||'|'||
      COALESCE(v_batch.source_workbench_session_id::text,'')||'|'||
      COALESCE(v_batch.source_session_version::text,'')||'|'||
      COALESCE(v_batch.source_scope_change_generation::text,'')||'|'||
      COALESCE(v_first_generation::text,'')||'|'||COALESCE(v_terminal_generation::text,'')||'|'||
      COALESCE(v_terminal_token::text,'')||'|'||v_transition_rows::text||'|'||
      COALESCE(v_active_item_scope_digest,'')||'|'||COALESCE(v_transfer_scope_digest,'')||'|'||
      COALESCE(v_draft_operation_id::text,'')||'|'||COALESCE(v_original_economic_build_id,'')||'|'||
      COALESCE(v_original_source_build_run_id,'')||'|'||
      COALESCE(v_original_source_publication_id,'')||'|'||
      COALESCE(v_original_source_identity_digest,'')||'|'||
      COALESCE(v_original_semantic_proof_digest,'')||'|'||
      COALESCE(v_pre_execution_source_seq::text,'')||'|'||
      COALESCE(v_owned_source_event_count::text,'')||'|'||
      COALESCE(v_live_source_seq::text,'')||'|'||COALESCE(v_rejection_reason,'')||
      '|EXECUTION_UNSENT_OVERLAY_CHAIN_V2'
    );

    v_candidate_result:=pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
      'contract_version','EXECUTION_UNSENT_OVERLAY_CHAIN_V2',
      'execution_operation_id',p_operation_id,'pay_batch_id',p_pay_batch_id,
      'candidate_id',v_candidate.candidate_id,
      'source_workbench_session_id',v_batch.source_workbench_session_id,
      'source_session_version',v_batch.source_session_version,
      'draft_operation_id',v_draft_operation_id,
      'original_economic_build_id',v_original_economic_build_id,
      'original_source_build_run_id',v_original_source_build_run_id,
      'original_source_publication_id',v_original_source_publication_id,
      'original_source_identity_digest',v_original_source_identity_digest,
      'original_semantic_proof_digest',v_original_semantic_proof_digest,
      'pre_execution_dirty_generation',v_batch.source_scope_change_generation,
      'pre_execution_source_change_seq',v_pre_execution_source_seq,
      'first_execution_generation',v_first_generation,
      'terminal_execution_generation',v_terminal_generation,
      'terminal_scope_change_tx_token',v_terminal_token,
      'terminal_source_change_seq',v_live_source_seq,
      'owned_source_event_count',v_owned_source_event_count,
      'transition_count',v_transition_count,'transitions',v_transition_rows,
      'link_transition_count',v_link_transition_count,
      'schedule_transition_count',v_schedule_transition_count,
      'active_item_scope_digest',v_active_item_scope_digest,
      'execution_transfer_scope_digest',v_transfer_scope_digest,
      'provider_attempt_count',v_provider_attempt_count,
      'rail_transaction_count',v_transfer_event_count+v_unsafe_transfer_count,
      'settlement_count',v_settlement_count,'remittance_count',v_remittance_count,
      'execution_commit_state',v_batch.execution_commit_state,
      'closed',v_rejection_reason IS NULL,'rejection_reason',v_rejection_reason,
      'chain_digest',v_chain_digest
    ));

    v_candidate_results:=v_candidate_results||
      pg_catalog.jsonb_build_object(v_candidate.candidate_id::text,v_candidate_result);
    IF v_rejection_reason IS NULL THEN v_closed_count:=v_closed_count+1; END IF;
  END LOOP;

  RETURN pg_catalog.jsonb_build_object(
    'ok',true,'contract_version','EXECUTION_UNSENT_OVERLAY_CHAIN_V2',
    'execution_operation_id',p_operation_id,'pay_batch_id',p_pay_batch_id,
    'candidate_count',v_candidate_count,'closed_candidate_count',v_closed_count,
    'all_closed',v_closed_count=v_candidate_count,'candidates',v_candidate_results,
    'authority_set_digest',pg_catalog.md5(
      p_operation_id::text||'|'||p_pay_batch_id::text||'|'||v_candidate_results::text||
      '|EXECUTION_UNSENT_OVERLAY_CHAIN_SET_V2'),
    'policy_x_authority_scope','POST_DRAFT_FROZEN_PAYMENT_PROOF_PLUS_EXACT_UNSENT_EXECUTION_CHAIN'
  );
END;
$function$;

-- private.pay_workbench_fact_cursor_preserve_v2(jsonb)
CREATE OR REPLACE FUNCTION private.pay_workbench_fact_cursor_preserve_v2(p_cursor_json jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_cursor jsonb:=p_cursor_json;
  v_required_keys text[]:=ARRAY[
    'cursor_kind','cursor_version','build_id','candidate_id',
    'captured_candidate_generation','captured_source_change_seq',
    'dependency_unit_key','fact_family','page_number','last_source_key',
    'previous_page_digest','cumulative_fact_count','cumulative_digest','terminal',
    'raw_physical_source_count','resolved_physical_source_count',
    'failed_physical_source_count','raw_physical_amount_ex_vat',
    'resolved_physical_amount_ex_vat','last_raw_physical_source_key',
    'source_exhausted','raw_terminal_source_key','raw_page_evidence_digest',
    'input_phase','input_projection_id'
  ];
  v_key text;
  v_reservation_order_contract constant text:='RESERVATION_COMPONENT_SOURCE_KEY_C_V1';
BEGIN
  IF jsonb_typeof(v_cursor)<>'object'
     OR v_cursor->>'cursor_kind'<>'WORKSPACE_FACT'
     OR COALESCE((v_cursor->>'cursor_version')::integer,0)<>2 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_CURSOR_VERSION_OBSOLETE'
      USING ERRCODE='40001';
  END IF;

  FOREACH v_key IN ARRAY v_required_keys LOOP
    IF NOT (v_cursor ? v_key) THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_CURSOR_V2_FIELD_MISSING'
        USING ERRCODE='22023',DETAIL=v_key;
    END IF;
  END LOOP;

  IF EXISTS(
    SELECT 1
    FROM jsonb_object_keys(v_cursor) supplied(key_name)
    WHERE NOT supplied.key_name=ANY(
      v_required_keys || ARRAY['reservation_source_key_order_contract'])
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_CURSOR_V2_FIELD_UNKNOWN'
      USING ERRCODE='22023';
  END IF;

  IF v_cursor->>'fact_family'='RESERVATION_COMPONENT' THEN
    IF v_cursor ? 'reservation_source_key_order_contract'
       AND v_cursor->>'reservation_source_key_order_contract'
           <>v_reservation_order_contract THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_RESERVATION_ORDER_CONTRACT_OBSOLETE'
        USING ERRCODE='40001';
    END IF;
  ELSIF v_cursor ? 'reservation_source_key_order_contract' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_CURSOR_V2_FIELD_UNKNOWN'
      USING ERRCODE='22023',
            DETAIL='reservation_source_key_order_contract';
  END IF;

  IF COALESCE(v_cursor->>'input_phase','') NOT IN ('PHYSICAL_SOURCE','PROJECTION','COMPONENTS')
     OR jsonb_typeof(v_cursor->'terminal')<>'boolean'
     OR jsonb_typeof(v_cursor->'source_exhausted')<>'boolean'
     OR COALESCE((v_cursor->>'page_number')::integer,0)<1
     OR COALESCE((v_cursor->>'cumulative_fact_count')::bigint,-1)<0
     OR COALESCE((v_cursor->>'raw_physical_source_count')::bigint,-1)<0
     OR COALESCE((v_cursor->>'resolved_physical_source_count')::bigint,-1)<0
     OR COALESCE((v_cursor->>'failed_physical_source_count')::bigint,-1)<0 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_CURSOR_INVALID'
      USING ERRCODE='22023';
  END IF;

  RETURN v_cursor;
END;
$function$;

-- private.pay_workbench_fact_cursor_transition_v3(jsonb,text,text,text,uuid)
CREATE OR REPLACE FUNCTION private.pay_workbench_fact_cursor_transition_v3(p_current_cursor jsonb, p_dependency_unit_key text, p_fact_family text, p_input_phase text, p_input_projection_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_current jsonb:=private.pay_workbench_fact_cursor_preserve_v2(p_current_cursor);
  v_unit_key text:=NULLIF(BTRIM(COALESCE(p_dependency_unit_key,'')),'');
  v_fact_family text:=UPPER(NULLIF(BTRIM(COALESCE(p_fact_family,'')),''));
  v_input_phase text:=UPPER(NULLIF(BTRIM(COALESCE(p_input_phase,'')),''));
  v_result jsonb;
BEGIN
  IF v_unit_key IS NULL OR v_fact_family IS NULL OR v_input_phase IS NULL
     OR v_input_phase NOT IN ('PHYSICAL_SOURCE','PROJECTION','COMPONENTS')
     OR (v_unit_key='GLOBAL' AND (
       v_input_phase<>'PHYSICAL_SOURCE' OR p_input_projection_id IS NOT NULL))
     OR (v_unit_key<>'GLOBAL' AND v_fact_family='LIVE_ENTITLEMENT_INPUT'
       AND v_input_phase<>'PROJECTION')
     OR (v_unit_key<>'GLOBAL' AND v_fact_family<>'LIVE_ENTITLEMENT_INPUT'
       AND v_input_phase<>'COMPONENTS') THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_FACT_CURSOR_TRANSITION_INVALID'
      USING ERRCODE='22023';
  END IF;

  v_result:=jsonb_build_object(
    'cursor_kind','WORKSPACE_FACT',
    'cursor_version',2,
    'build_id',v_current->'build_id',
    'candidate_id',v_current->'candidate_id',
    'captured_candidate_generation',v_current->'captured_candidate_generation',
    'captured_source_change_seq',v_current->'captured_source_change_seq',
    'dependency_unit_key',v_unit_key,
    'fact_family',v_fact_family,
    'page_number',1,
    'last_source_key',NULL,
    'previous_page_digest',NULL,
    'cumulative_fact_count',0,
    'cumulative_digest',md5('BPAY_FACT_STREAM_V2'),
    'terminal',false,
    'raw_physical_source_count',0,
    'resolved_physical_source_count',0,
    'failed_physical_source_count',0,
    'raw_physical_amount_ex_vat',0,
    'resolved_physical_amount_ex_vat',0,
    'last_raw_physical_source_key',NULL,
    'source_exhausted',false,
    'raw_terminal_source_key',NULL,
    'raw_page_evidence_digest',NULL,
    'input_phase',v_input_phase,
    'input_projection_id',p_input_projection_id);

  IF v_fact_family='RESERVATION_COMPONENT' THEN
    v_result:=v_result || jsonb_build_object(
      'reservation_source_key_order_contract',
      'RESERVATION_COMPONENT_SOURCE_KEY_C_V1');
  END IF;

  -- Both functions validate the exact member set.  This is the producer-side
  -- assertion that the generated cursor is directly consumable.
  RETURN private.pay_workbench_fact_cursor_preserve_v2(v_result);
END;
$function$;

-- private.pay_workbench_finance_effect_normalise_row_v1(text,text,jsonb,jsonb)
CREATE OR REPLACE FUNCTION private.pay_workbench_finance_effect_normalise_row_v1(p_relation_name text, p_operation text, p_row_json jsonb, p_before_row_json jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_relation text:=LOWER(NULLIF(BTRIM(COALESCE(p_relation_name,'')),''));
  v_operation text:=UPPER(NULLIF(BTRIM(COALESCE(p_operation,'')),''));
  v_row jsonb:=CASE WHEN jsonb_typeof(COALESCE(p_row_json,'{}'::jsonb))='object'
    THEN COALESCE(p_row_json,'{}'::jsonb) ELSE '{}'::jsonb END;
  v_before jsonb:=CASE WHEN jsonb_typeof(COALESCE(p_before_row_json,'{}'::jsonb))='object'
    THEN COALESCE(p_before_row_json,'{}'::jsonb) ELSE '{}'::jsonb END;
  v_field text;
  v_before_value jsonb;
  v_after_value jsonb;
  v_nested_before jsonb := '{}'::jsonb;
  v_nested_after jsonb := '{}'::jsonb;
BEGIN
  IF v_relation NOT IN ('pay_advances','pay_finance_case_components','pay_finance_case_events')
     OR v_operation NOT IN ('INSERT','UPDATE','DELETE') THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_EFFECT_RELATION_INVALID' USING ERRCODE='22023';
  END IF;

  v_row:=v_row-'created_at'-'created_at_utc'-'updated_at'-'updated_at_utc'-'event_at_utc';

  -- Component sync refreshes this one nested audit timestamp whenever an
  -- existing amount-only resolution remains reusable. Capture and execute run
  -- in separate transactions, so their generated instants must be attested as
  -- the same non-economic transition. Keep every sibling amount, ratio,
  -- fingerprint and resolution field exact.
  IF v_relation='pay_finance_case_components'
     AND v_operation='UPDATE'
     AND jsonb_typeof(v_row->'saved_resolution_result_json')='object'
     AND LOWER(COALESCE(
       v_row#>>'{saved_resolution_result_json,amount_only_resolution_reused}',
       'false'
     )) IN ('true','t','1','yes','y','on')
     AND NULLIF(BTRIM(COALESCE(
       v_row#>>'{saved_resolution_result_json,amount_only_resolution_reused_at_utc}',
       ''
     )), '') IS NOT NULL THEN
    v_row:=jsonb_set(
      v_row,
      ARRAY['saved_resolution_result_json','amount_only_resolution_reused_at_utc'],
      to_jsonb('__GENERATED_NON_NULL__'::text),
      false
    );
  END IF;

  IF v_operation='INSERT' THEN
    v_row:=v_row-'id'-'finance_case_id'-'finance_component_id';

    -- Event rows duplicate their stable parent identities inside the captured
    -- before/after snapshots.  A newly inserted case/component receives a new
    -- physical UUID in capture and execute, while its logical parent identity
    -- is already attested independently by the expected-effect identity map.
    -- Remove only those duplicated generated identities from the event digest;
    -- all economic, classification and lifecycle fields remain exact.
    IF v_relation='pay_finance_case_events' THEN
      IF jsonb_typeof(v_row->'before_json')='object' THEN
        v_row:=jsonb_set(v_row,ARRAY['before_json'],
          (v_row->'before_json')-'id'-'finance_case_id'-'finance_component_id',false);
      END IF;
      IF jsonb_typeof(v_row->'after_json')='object' THEN
        v_row:=jsonb_set(v_row,ARRAY['after_json'],
          (v_row->'after_json')-'id'-'finance_case_id'-'finance_component_id',false);
      END IF;

      -- Closure timestamps are repeated in the immutable event snapshot.  The
      -- capture and execute transactions generate different instants for the
      -- same NULL -> non-NULL lifecycle transition, so attest that transition
      -- semantically.  Existing/manual timestamps, removals, and every other
      -- nested field remain exact and therefore still fail on any difference.
      v_nested_before:=CASE WHEN jsonb_typeof(v_row->'before_json')='object'
        THEN v_row->'before_json' ELSE '{}'::jsonb END;
      v_nested_after:=CASE WHEN jsonb_typeof(v_row->'after_json')='object'
        THEN v_row->'after_json' ELSE '{}'::jsonb END;
      FOR v_field IN
        SELECT field_name FROM unnest(ARRAY[
          'closed_at_utc','cleared_at_utc','written_off_at_utc'
        ]::text[]) field_name
      LOOP
        v_before_value:=v_nested_before->v_field;
        v_after_value:=v_nested_after->v_field;
        IF (v_before_value IS NULL OR v_before_value='null'::jsonb)
           AND v_after_value IS NOT NULL
           AND v_after_value<>'null'::jsonb THEN
          v_nested_after:=jsonb_set(v_nested_after,ARRAY[v_field],
            to_jsonb('__GENERATED_NON_NULL__'::text),true);
        END IF;
      END LOOP;
      IF jsonb_typeof(v_row->'after_json')='object' THEN
        v_row:=jsonb_set(v_row,ARRAY['after_json'],v_nested_after,false);
      END IF;
    END IF;
  END IF;

  FOR v_field IN
    SELECT field_name FROM unnest(CASE v_relation
      WHEN 'pay_advances' THEN ARRAY['cleared_at_utc','written_off_at_utc']::text[]
      WHEN 'pay_finance_case_components' THEN ARRAY['closed_at_utc']::text[]
      ELSE ARRAY[]::text[] END) field_name
  LOOP
    v_before_value:=v_before->v_field;
    v_after_value:=v_row->v_field;
    IF v_before_value IS NOT NULL AND v_before_value<>'null'::jsonb THEN
      IF v_after_value IS NOT NULL AND v_after_value<>'null'::jsonb
         AND v_after_value IS DISTINCT FROM v_before_value THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_LIFECYCLE_TIMESTAMP_MISMATCH'
          USING ERRCODE='23514';
      END IF;
      -- An existing manual/lifecycle timestamp remains exact authority.
    ELSIF v_after_value IS NOT NULL AND v_after_value<>'null'::jsonb THEN
      v_row:=jsonb_set(v_row,ARRAY[v_field],to_jsonb('__GENERATED_NON_NULL__'::text),true);
    END IF;
  END LOOP;
  RETURN v_row;
END;
$function$;

-- private.pay_workbench_finance_item_authority_page_bundle_v1(uuid,uuid,uuid,integer)
CREATE OR REPLACE FUNCTION private.pay_workbench_finance_item_authority_page_bundle_v1(p_build_id uuid, p_last_batch_candidate_id uuid DEFAULT NULL::uuid, p_last_item_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  WITH bounded AS MATERIALIZED (
    SELECT page.*
    FROM private.pay_workbench_finance_item_authority_page_v1(
      p_build_id,p_last_batch_candidate_id,p_last_item_id,
      LEAST(GREATEST(COALESCE(p_limit,25),1),25)
    ) page
  ), accepted AS MATERIALIZED (
    SELECT bounded.*
    FROM bounded
    ORDER BY bounded.source_key
    LIMIT LEAST(GREATEST(COALESCE(p_limit,25),1),25)
  ), evidence AS (
    SELECT COUNT(*)::bigint AS raw_page_count,
      COUNT(*) FILTER(WHERE NULLIF(BTRIM(accepted.resolution_failure),'') IS NULL)::bigint
        AS resolved_page_count,
      COUNT(*) FILTER(WHERE NULLIF(BTRIM(accepted.resolution_failure),'') IS NOT NULL)::bigint
        AS failed_page_count,
      ROUND(COALESCE(SUM(COALESCE(
        (accepted.source_payload_json->>'raw_physical_amount_ex_vat')::numeric,0)),0),2)
        AS raw_amount_ex_vat,
      ROUND(COALESCE(SUM(COALESCE(accepted.source_amount_ex_vat,0)) FILTER(
        WHERE NULLIF(BTRIM(accepted.resolution_failure),'') IS NULL),0),2)
        AS resolved_amount_ex_vat,
      MAX(accepted.source_key) AS last_raw_source_key,
      md5(COALESCE(string_agg(accepted.source_key||':'||COALESCE(
        NULLIF(accepted.source_payload_json->>'raw_physical_digest',''),
        accepted.financial_digest),'' ORDER BY accepted.source_key),'')) AS evidence_digest,
      COALESCE(jsonb_agg(to_jsonb(accepted) ORDER BY accepted.source_key),'[]'::jsonb) AS rows_json
    FROM accepted
  )
  SELECT jsonb_build_object(
    'raw_page_count',evidence.raw_page_count,
    'resolved_page_count',evidence.resolved_page_count,
    'failed_page_count',evidence.failed_page_count,
    'raw_amount_ex_vat',evidence.raw_amount_ex_vat,
    'resolved_amount_ex_vat',evidence.resolved_amount_ex_vat,
    'raw_source_has_more',(SELECT COUNT(*)>LEAST(GREATEST(COALESCE(p_limit,25),1),25)
      FROM bounded),
    'raw_source_exhausted',NOT (SELECT COUNT(*)>LEAST(GREATEST(COALESCE(p_limit,25),1),25)
      FROM bounded),
    'last_raw_source_key',evidence.last_raw_source_key,
    'raw_terminal_source_key',CASE
      WHEN NOT (SELECT COUNT(*)>LEAST(GREATEST(COALESCE(p_limit,25),1),25) FROM bounded)
      THEN evidence.last_raw_source_key END,
    'evidence_digest',evidence.evidence_digest,
    'rows',evidence.rows_json
  )
  FROM evidence;
$function$;

-- private.pay_workbench_finance_item_authority_page_v1(uuid,uuid,uuid,integer)
CREATE OR REPLACE FUNCTION private.pay_workbench_finance_item_authority_page_v1(p_build_id uuid, p_last_batch_candidate_id uuid DEFAULT NULL::uuid, p_last_item_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 25)
 RETURNS TABLE(source_key text, pay_batch_candidate_id uuid, pay_batch_item_id uuid, resolved_timesheet_id uuid, resolved_candidate_id uuid, resolved_finance_case_id uuid, finance_component_id uuid, economic_key_type text, economic_key_value text, source_amount_ex_vat numeric, source_amount_inc_vat numeric, is_authoritative boolean, source_payload_json jsonb, financial_digest text, resolution_failure text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  RETURN QUERY
  WITH build AS (
    SELECT build_row.id,build_row.candidate_id
    FROM private.banking_pay_workbench_economic_builds build_row
    WHERE build_row.id=p_build_id
  ), scope_timesheet AS MATERIALIZED (
    SELECT scope_row.timesheet_id
    FROM private.banking_pay_workbench_economic_build_scope scope_row
    WHERE scope_row.build_id=p_build_id
  ), direct_owner_item AS MATERIALIZED (
    SELECT item.pay_batch_candidate_id,item.id AS item_id
    FROM build
    JOIN scope_timesheet scope_row ON true
    JOIN public.pay_batch_items item ON item.timesheet_id=scope_row.timesheet_id
    JOIN public.pay_batch_candidates batch_candidate
      ON batch_candidate.id=item.pay_batch_candidate_id
     AND batch_candidate.candidate_id=build.candidate_id
    WHERE item.item_type IN ('OVERPAYMENT_RECOVERY','UNDERPAYMENT_PAYMENT')
      AND COALESCE(item.is_voided,false) IS FALSE
      AND (p_last_batch_candidate_id IS NULL OR
        (item.pay_batch_candidate_id,item.id)>(p_last_batch_candidate_id,p_last_item_id))
    ORDER BY item.pay_batch_candidate_id,item.id
    LIMIT LEAST(GREATEST(COALESCE(p_limit,25),1),25)+1
  ), component_owner_item AS MATERIALIZED (
    SELECT item.pay_batch_candidate_id,item.id AS item_id
    FROM build
    JOIN scope_timesheet scope_row ON true
    JOIN public.pay_finance_case_components component
      ON component.linked_timesheet_id=scope_row.timesheet_id
    JOIN public.pay_batch_items item ON item.finance_component_id=component.id
    JOIN public.pay_batch_candidates batch_candidate
      ON batch_candidate.id=item.pay_batch_candidate_id
     AND batch_candidate.candidate_id=build.candidate_id
    WHERE item.item_type IN ('OVERPAYMENT_RECOVERY','UNDERPAYMENT_PAYMENT')
      AND COALESCE(item.is_voided,false) IS FALSE
      AND (p_last_batch_candidate_id IS NULL OR
        (item.pay_batch_candidate_id,item.id)>(p_last_batch_candidate_id,p_last_item_id))
    ORDER BY item.pay_batch_candidate_id,item.id
    LIMIT LEAST(GREATEST(COALESCE(p_limit,25),1),25)+1
  ), case_owner_item AS MATERIALIZED (
    SELECT item.pay_batch_candidate_id,item.id AS item_id
    FROM build
    JOIN scope_timesheet scope_row ON true
    JOIN public.pay_advances finance_case
      ON finance_case.linked_timesheet_id=scope_row.timesheet_id
    JOIN public.pay_batch_items item ON item.finance_case_id=finance_case.id
    JOIN public.pay_batch_candidates batch_candidate
      ON batch_candidate.id=item.pay_batch_candidate_id
     AND batch_candidate.candidate_id=build.candidate_id
    WHERE item.item_type IN ('OVERPAYMENT_RECOVERY','UNDERPAYMENT_PAYMENT')
      AND COALESCE(item.is_voided,false) IS FALSE
      AND (p_last_batch_candidate_id IS NULL OR
        (item.pay_batch_candidate_id,item.id)>(p_last_batch_candidate_id,p_last_item_id))
    ORDER BY item.pay_batch_candidate_id,item.id
    LIMIT LEAST(GREATEST(COALESCE(p_limit,25),1),25)+1
  ), frozen_owner_item AS MATERIALIZED (
    SELECT item.pay_batch_candidate_id,item.id AS item_id
    FROM build
    JOIN scope_timesheet scope_row ON true
    JOIN public.pay_batch_items item ON (
      item.frozen_source_basis_json @> jsonb_build_object('linked_timesheet_id',scope_row.timesheet_id::text)
      OR item.frozen_source_basis_json @> jsonb_build_object('timesheet_id',scope_row.timesheet_id::text)
      OR item.frozen_source_basis_json @> jsonb_build_object('carrier_timesheet_id',scope_row.timesheet_id::text)
      OR item.frozen_source_basis_json @> jsonb_build_object(
        'economic_key',jsonb_build_object('timesheet_id',scope_row.timesheet_id::text))
      OR item.frozen_component_snapshot_json @> jsonb_build_object('linked_timesheet_id',scope_row.timesheet_id::text)
      OR item.frozen_component_snapshot_json @> jsonb_build_object('timesheet_id',scope_row.timesheet_id::text)
      OR item.frozen_component_snapshot_json @> jsonb_build_object('carrier_timesheet_id',scope_row.timesheet_id::text)
      OR item.frozen_component_snapshot_json @> jsonb_build_object('source_basis_json',
        jsonb_build_object('linked_timesheet_id',scope_row.timesheet_id::text))
      OR item.frozen_component_snapshot_json @> jsonb_build_object('source_basis_json',
        jsonb_build_object('timesheet_id',scope_row.timesheet_id::text))
      OR item.frozen_component_snapshot_json @> jsonb_build_object('source_basis_json',
        jsonb_build_object('carrier_timesheet_id',scope_row.timesheet_id::text)))
    JOIN public.pay_batch_candidates batch_candidate
      ON batch_candidate.id=item.pay_batch_candidate_id
     AND batch_candidate.candidate_id=build.candidate_id
    WHERE item.item_type IN ('OVERPAYMENT_RECOVERY','UNDERPAYMENT_PAYMENT')
      AND COALESCE(item.is_voided,false) IS FALSE
      AND (p_last_batch_candidate_id IS NULL OR
        (item.pay_batch_candidate_id,item.id)>(p_last_batch_candidate_id,p_last_item_id))
    ORDER BY item.pay_batch_candidate_id,item.id
    LIMIT LEAST(GREATEST(COALESCE(p_limit,25),1),25)+1
  ), candidate_settled_item AS MATERIALIZED (
    SELECT item.pay_batch_candidate_id,item.id AS item_id
    FROM build
    JOIN public.pay_batch_candidates batch_candidate
      ON batch_candidate.candidate_id=build.candidate_id
    JOIN public.pay_batch_items item ON item.pay_batch_candidate_id=batch_candidate.id
    WHERE item.item_type IN ('OVERPAYMENT_RECOVERY','UNDERPAYMENT_PAYMENT')
      AND COALESCE(item.is_voided,false) IS FALSE
      AND (UPPER(BTRIM(COALESCE(batch_candidate.settlement_status,'')))='SETTLED'
        OR batch_candidate.settled_at_utc IS NOT NULL)
      AND (p_last_batch_candidate_id IS NULL OR
        (item.pay_batch_candidate_id,item.id)>(p_last_batch_candidate_id,p_last_item_id))
    ORDER BY item.pay_batch_candidate_id,item.id
    LIMIT LEAST(GREATEST(COALESCE(p_limit,25),1),25)+1
  ), candidate_transfer_item AS MATERIALIZED (
    SELECT item.pay_batch_candidate_id,item.id AS item_id
    FROM build
    JOIN public.pay_batch_candidates batch_candidate
      ON batch_candidate.candidate_id=build.candidate_id
    JOIN public.pay_batch_items item ON item.pay_batch_candidate_id=batch_candidate.id
    JOIN public.pay_bank_transfers transfer ON transfer.id=item.pay_bank_transfer_id
    WHERE item.item_type IN ('OVERPAYMENT_RECOVERY','UNDERPAYMENT_PAYMENT')
      AND COALESCE(item.is_voided,false) IS FALSE
      AND (UPPER(BTRIM(COALESCE(transfer.status,'')))='COMPLETED'
        OR transfer.completed_at_utc IS NOT NULL)
      AND (p_last_batch_candidate_id IS NULL OR
        (item.pay_batch_candidate_id,item.id)>(p_last_batch_candidate_id,p_last_item_id))
    ORDER BY item.pay_batch_candidate_id,item.id
    LIMIT LEAST(GREATEST(COALESCE(p_limit,25),1),25)+1
  ), candidate_reservation_item AS MATERIALIZED (
    SELECT item.pay_batch_candidate_id,item.id AS item_id
    FROM build
    JOIN public.pay_batch_candidates batch_candidate
      ON batch_candidate.candidate_id=build.candidate_id
    JOIN public.pay_batch_items item ON item.pay_batch_candidate_id=batch_candidate.id
    JOIN public.pay_advance_reservations reservation
      ON reservation.pay_batch_item_id=item.id
    WHERE item.item_type IN ('OVERPAYMENT_RECOVERY','UNDERPAYMENT_PAYMENT')
      AND COALESCE(item.is_voided,false) IS FALSE
      AND (UPPER(BTRIM(COALESCE(reservation.status,'')))='SETTLED'
        OR reservation.settled_at_utc IS NOT NULL)
      AND (p_last_batch_candidate_id IS NULL OR
        (item.pay_batch_candidate_id,item.id)>(p_last_batch_candidate_id,p_last_item_id))
    ORDER BY item.pay_batch_candidate_id,item.id
    LIMIT LEAST(GREATEST(COALESCE(p_limit,25),1),25)+1
  ), candidate_item_key AS MATERIALIZED (
    SELECT * FROM direct_owner_item
    UNION ALL SELECT * FROM component_owner_item
    UNION ALL SELECT * FROM case_owner_item
    UNION ALL SELECT * FROM frozen_owner_item
    UNION ALL SELECT * FROM candidate_settled_item
    UNION ALL SELECT * FROM candidate_transfer_item
    UNION ALL SELECT * FROM candidate_reservation_item
  ), item_key AS MATERIALIZED (
    SELECT candidate_item_key.pay_batch_candidate_id,candidate_item_key.item_id
    FROM candidate_item_key
    GROUP BY candidate_item_key.pay_batch_candidate_id,candidate_item_key.item_id
    ORDER BY candidate_item_key.pay_batch_candidate_id,candidate_item_key.item_id
    LIMIT LEAST(GREATEST(COALESCE(p_limit,25),1),25)+1
  ), item_page AS MATERIALIZED (
    SELECT item.*,batch_candidate.candidate_id AS batch_candidate_candidate_id,
      batch_candidate.settlement_status,batch_candidate.settled_at_utc
    FROM item_key
    JOIN public.pay_batch_items item ON item.id=item_key.item_id
      AND item.pay_batch_candidate_id=item_key.pay_batch_candidate_id
    JOIN public.pay_batch_candidates batch_candidate
      ON batch_candidate.id=item_key.pay_batch_candidate_id
    ORDER BY item_key.pay_batch_candidate_id,item_key.item_id
  ), enriched AS (
    SELECT item_page.*,
      component.linked_timesheet_id AS component_timesheet_id,
      component.candidate_id AS component_candidate_id,
      component.finance_case_id AS component_case_id,
      component.component_key_type,component.component_key_value,
      finance_case.id AS linked_case_row_id,
      finance_case.linked_timesheet_id AS case_timesheet_id,
      finance_case.candidate_id AS case_candidate_id,
      finance_case.status::text AS case_status,
      finance_case.advance_kind::text AS case_advance_kind,
      finance_case.case_type::text AS case_type,
      finance_case.outstanding_amount AS case_outstanding_amount,
      finance_case.cleared_at_utc AS case_cleared_at_utc,
      transfer.status AS transfer_status,transfer.completed_at_utc,
      COALESCE(reservation.has_settled,false) AS reservation_has_settled,
      reservation.settled_source_amount,
      EXISTS(SELECT 1 FROM public.pay_payment_correction_items correction
        WHERE correction.pay_batch_item_id=item_page.id
          AND correction.status='APPLIED'
          AND correction.correction_item_kind IN
            ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')) AS is_reversed
    FROM item_page
    LEFT JOIN public.pay_finance_case_components component
      ON component.id=item_page.finance_component_id
    LEFT JOIN public.pay_advances finance_case
      ON finance_case.id=COALESCE(item_page.finance_case_id,component.finance_case_id)
    LEFT JOIN public.pay_bank_transfers transfer ON transfer.id=item_page.pay_bank_transfer_id
    LEFT JOIN LATERAL (
      SELECT BOOL_OR(UPPER(BTRIM(COALESCE(reservation_row.status,'')))='SETTLED'
          OR reservation_row.settled_at_utc IS NOT NULL) AS has_settled,
        ROUND(COALESCE(SUM(ABS(COALESCE(reservation_row.reserved_source_amount,
          reservation_row.reserved_amount,0))) FILTER(
            WHERE UPPER(BTRIM(COALESCE(reservation_row.status,'')))='SETTLED'
               OR reservation_row.settled_at_utc IS NOT NULL),0),2) AS settled_source_amount
      FROM public.pay_advance_reservations reservation_row
      WHERE reservation_row.pay_batch_item_id=item_page.id
    ) reservation ON true
  ), resolved AS (
    SELECT enriched.*,
      authority.owner_ids,authority.candidate_ids,authority.finance_case_ids,
      authority.finance_component_ids,authority.component_key_pairs,
      authority.resolved_timesheet_id,authority.resolved_candidate_id,
      authority.resolved_finance_case_id,authority.resolved_finance_component_id,
      authority.resolved_component_key_type,authority.resolved_component_key_value,
      authority.resolution_failure AS authority_failure,authority.evidence_json,
      ROUND(ABS(COALESCE(NULLIF(enriched.frozen_source_amount,0),
        NULLIF(enriched.settled_source_amount,0),NULLIF(enriched.amount_ex_vat,0),
        NULLIF(enriched.amount_inc_vat,0))),2) AS resolved_source_amount,
      (UPPER(BTRIM(COALESCE(enriched.settlement_status,'')))='SETTLED'
        OR enriched.settled_at_utc IS NOT NULL
        OR UPPER(BTRIM(COALESCE(enriched.transfer_status,'')))='COMPLETED'
        OR enriched.completed_at_utc IS NOT NULL
        OR enriched.reservation_has_settled) AND NOT enriched.is_reversed AS settled_authority
    FROM enriched
    CROSS JOIN LATERAL private.pay_workbench_financial_source_authority_v2(
      enriched.batch_candidate_candidate_id,
      ARRAY[enriched.timesheet_id,enriched.component_timesheet_id,enriched.case_timesheet_id],
      ARRAY[enriched.batch_candidate_candidate_id,enriched.component_candidate_id,
        enriched.case_candidate_id],
      ARRAY[enriched.finance_case_id,enriched.component_case_id],
      ARRAY[enriched.finance_component_id],
      jsonb_build_array(
        jsonb_build_object('source','PAY_BATCH_ITEM_FROZEN_COLUMNS',
          'key_type',enriched.frozen_component_key_type,
          'key_value',enriched.frozen_component_key_value),
        jsonb_build_object('source','FINANCE_COMPONENT',
          'key_type',enriched.component_key_type,
          'key_value',enriched.component_key_value)
      ),
      enriched.frozen_source_basis_json,enriched.frozen_component_snapshot_json,'FINANCE'
    ) authority
  ), scoped_authority AS (
    SELECT resolved.*,
      CASE
        WHEN NULLIF(BTRIM(COALESCE(resolved.evidence_json->>'frozen_owner_id','')),'') IS NOT NULL
         AND pg_input_is_valid(resolved.evidence_json->>'frozen_owner_id','uuid')
          THEN (resolved.evidence_json->>'frozen_owner_id')::uuid
      END AS frozen_owner_id,
      cardinality(COALESCE(resolved.owner_ids,ARRAY[]::uuid[])) AS authority_owner_count,
      (SELECT COUNT(*)::integer
       FROM private.banking_pay_workbench_economic_build_scope owner_scope
       WHERE owner_scope.build_id=p_build_id
         AND owner_scope.timesheet_id=ANY(COALESCE(resolved.owner_ids,ARRAY[]::uuid[])))
        AS authority_owner_in_scope_count,
      (SELECT COUNT(DISTINCT owner_scope.dependency_unit_key)::integer
       FROM private.banking_pay_workbench_economic_build_scope owner_scope
       WHERE owner_scope.build_id=p_build_id
         AND owner_scope.timesheet_id=ANY(COALESCE(resolved.owner_ids,ARRAY[]::uuid[])))
        AS authority_dependency_unit_count
    FROM resolved
  ), resolution_policy AS (
    SELECT scoped_authority.*,
      (
        scoped_authority.settled_authority
        AND scoped_authority.authority_failure='FINANCE_OWNER_CONFLICT'
        AND scoped_authority.frozen_owner_id IS NOT NULL
        AND scoped_authority.authority_owner_count>=2
        AND scoped_authority.authority_owner_in_scope_count=
          scoped_authority.authority_owner_count
        AND scoped_authority.authority_dependency_unit_count=1
        AND EXISTS(SELECT 1
          FROM private.banking_pay_workbench_economic_build_scope frozen_scope
          WHERE frozen_scope.build_id=p_build_id
            AND frozen_scope.timesheet_id=scoped_authority.frozen_owner_id)
        AND cardinality(COALESCE(scoped_authority.candidate_ids,ARRAY[]::uuid[]))=1
        AND scoped_authority.candidate_ids[1]=scoped_authority.batch_candidate_candidate_id
        AND cardinality(COALESCE(scoped_authority.finance_case_ids,ARRAY[]::uuid[]))=1
        AND cardinality(COALESCE(scoped_authority.finance_component_ids,ARRAY[]::uuid[]))<=1
        AND cardinality(COALESCE(scoped_authority.component_key_pairs,ARRAY[]::text[]))=1
        AND COALESCE((scoped_authority.evidence_json->>
          'invalid_frozen_uuid_count')::integer,0)=0
        AND COALESCE((scoped_authority.evidence_json->>
          'invalid_finance_component_uuid_count')::integer,0)=0
        AND COALESCE((scoped_authority.evidence_json->>
          'incomplete_component_key_count')::integer,0)=0
      ) AS use_frozen_same_unit_owner,
      (
        scoped_authority.settled_authority
        AND scoped_authority.authority_failure='FINANCE_OWNER_UNRESOLVED'
        AND scoped_authority.authority_owner_count=0
        AND cardinality(COALESCE(scoped_authority.candidate_ids,ARRAY[]::uuid[]))=1
        AND scoped_authority.candidate_ids[1]=scoped_authority.batch_candidate_candidate_id
        AND cardinality(COALESCE(scoped_authority.finance_case_ids,ARRAY[]::uuid[]))=1
        AND scoped_authority.linked_case_row_id=scoped_authority.finance_case_ids[1]
        AND scoped_authority.timesheet_id IS NULL
        AND scoped_authority.component_timesheet_id IS NULL
        AND scoped_authority.case_timesheet_id IS NULL
        AND scoped_authority.finance_component_id IS NULL
        AND scoped_authority.component_case_id IS NULL
        AND scoped_authority.frozen_owner_id IS NULL
        AND COALESCE(scoped_authority.frozen_source_basis_json,'{}'::jsonb)='{}'::jsonb
        AND COALESCE(scoped_authority.frozen_component_snapshot_json,'{}'::jsonb)='{}'::jsonb
        AND NULLIF(BTRIM(COALESCE(scoped_authority.frozen_component_key_type,'')),'') IS NULL
        AND NULLIF(BTRIM(COALESCE(scoped_authority.frozen_component_key_value,'')),'') IS NULL
        AND NULLIF(BTRIM(COALESCE(scoped_authority.operation_source_key,'')),'') IS NULL
        AND scoped_authority.source_ref='advance:'||scoped_authority.linked_case_row_id::text
        AND UPPER(BTRIM(COALESCE(scoped_authority.case_status,'')))='PAID_OFF'
        AND UPPER(BTRIM(COALESCE(scoped_authority.case_advance_kind,'')))='OVERPAYMENT'
        AND UPPER(BTRIM(COALESCE(scoped_authority.case_type,'')))='OVERPAYMENT'
        AND ROUND(COALESCE(scoped_authority.case_outstanding_amount,0),2)=0
        AND NOT EXISTS(SELECT 1
          FROM public.pay_finance_case_components legacy_component
          WHERE legacy_component.finance_case_id=scoped_authority.linked_case_row_id)
        AND NOT EXISTS(SELECT 1
          FROM public.pay_advance_reservations legacy_reservation
          WHERE (legacy_reservation.pay_batch_item_id=scoped_authority.id
              OR legacy_reservation.finance_case_id=scoped_authority.linked_case_row_id)
            AND UPPER(BTRIM(COALESCE(legacy_reservation.status,'')))
              NOT IN ('RELEASED','SETTLED'))
        AND NOT EXISTS(SELECT 1
          FROM public.pay_payment_correction_items legacy_correction
          WHERE (legacy_correction.pay_batch_item_id=scoped_authority.id
              OR legacy_correction.finance_case_id=scoped_authority.linked_case_row_id)
            AND (legacy_correction.timesheet_id IS NOT NULL
              OR UPPER(BTRIM(COALESCE(legacy_correction.status,'')))<>'APPLIED'))
        AND NOT EXISTS(SELECT 1
          FROM public.pay_item_snoozes legacy_snooze
          WHERE legacy_snooze.source_ref='advance:'||scoped_authority.linked_case_row_id::text
            AND legacy_snooze.cleared_at_utc IS NULL
            AND legacy_snooze.cancelled_at_utc IS NULL)
        AND NOT EXISTS(SELECT 1
          FROM public.pay_finance_case_events legacy_event
          WHERE legacy_event.finance_case_id=scoped_authority.linked_case_row_id
            AND (
              UPPER(BTRIM(COALESCE(legacy_event.event_type,''))) LIKE '%WRITE%OFF%'
              OR UPPER(BTRIM(COALESCE(legacy_event.event_type,''))) IN (
                'MANUAL_ECONOMIC_OVERRIDE','MANUAL_WRITE_OFF',
                'CASE_MANUAL_ECONOMIC_OVERRIDE','COMPONENT_MANUAL_ECONOMIC_OVERRIDE')
              OR UPPER(BTRIM(COALESCE(legacy_event.reason,''))) IN (
                'MANUAL_ECONOMIC_OVERRIDE','WRITE_OFF','COMPONENT_MANUAL_ECONOMIC_OVERRIDE')
              OR (UPPER(BTRIM(COALESCE(legacy_event.event_type,'')))='CASE_CLEARED'
                AND LOWER(BTRIM(COALESCE(legacy_event.reason,'')))='rail_settlement')
              OR (UPPER(BTRIM(COALESCE(legacy_event.event_type,'')))='CLEARED'
                AND UPPER(BTRIM(COALESCE(legacy_event.reason,'')))='PREVIEW_FINANCE_SYNC')
            ))
      ) AS legacy_terminal_unowned_evidence
    FROM scoped_authority
  ), effective_authority AS (
    SELECT resolution_policy.*,
      CASE WHEN resolution_policy.use_frozen_same_unit_owner
        THEN resolution_policy.frozen_owner_id
        ELSE resolution_policy.resolved_timesheet_id END AS effective_timesheet_id,
      CASE
        WHEN resolution_policy.use_frozen_same_unit_owner
          OR resolution_policy.legacy_terminal_unowned_evidence THEN NULL
        ELSE resolution_policy.authority_failure
      END AS effective_authority_failure,
      CASE
        WHEN resolution_policy.use_frozen_same_unit_owner
          THEN 'FROZEN_OWNER_SELECTED_SAME_DEPENDENCY_UNIT'
        WHEN resolution_policy.legacy_terminal_unowned_evidence
          THEN 'LEGACY_TERMINAL_UNOWNED_EVIDENCE'
        WHEN resolution_policy.authority_failure IS NOT NULL THEN 'BLOCKED_AUTHORITY_FAILURE'
        WHEN resolution_policy.settled_authority THEN 'RESOLVED_SETTLED_AUTHORITY'
        ELSE 'NON_SETTLED_EVIDENCE'
      END AS authority_resolution_status
    FROM resolution_policy
  ), classified AS (
    SELECT effective_authority.*,
      EXISTS(SELECT 1
        FROM private.banking_pay_workbench_economic_build_scope scope_row
        WHERE scope_row.build_id=p_build_id
          AND scope_row.timesheet_id=effective_authority.effective_timesheet_id) AS owner_in_scope,
      CASE
        WHEN effective_authority.effective_authority_failure IS NOT NULL
          THEN effective_authority.effective_authority_failure
        WHEN effective_authority.settled_authority
         AND EXISTS(SELECT 1
           FROM private.banking_pay_workbench_economic_build_scope scope_row
           WHERE scope_row.build_id=p_build_id
             AND scope_row.timesheet_id=effective_authority.effective_timesheet_id)
         AND (effective_authority.resolved_source_amount IS NULL
           OR effective_authority.resolved_source_amount<=0)
          THEN 'FROZEN_FINANCE_AMOUNT_INVALID'
        WHEN effective_authority.settled_authority
         AND EXISTS(SELECT 1
           FROM private.banking_pay_workbench_economic_build_scope scope_row
           WHERE scope_row.build_id=p_build_id
             AND scope_row.timesheet_id=effective_authority.effective_timesheet_id)
         AND (effective_authority.resolved_component_key_type NOT IN
            ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE',
              'MANUAL_CARRY_FORWARD')
          OR NULLIF(BTRIM(COALESCE(effective_authority.resolved_component_key_value,'')),'') IS NULL)
          THEN 'FROZEN_ECONOMIC_KEY_INVALID'
        WHEN effective_authority.settled_authority
         AND EXISTS(SELECT 1
           FROM private.banking_pay_workbench_economic_build_scope scope_row
           WHERE scope_row.build_id=p_build_id
             AND scope_row.timesheet_id=effective_authority.effective_timesheet_id)
         AND effective_authority.resolved_component_key_type='TS_DAY'
         AND NOT (
           effective_authority.resolved_component_key_value ~ '^\d{4}-\d{2}-\d{2}$'
           AND pg_input_is_valid(effective_authority.resolved_component_key_value,'date')
           AND CASE WHEN pg_input_is_valid(effective_authority.resolved_component_key_value,'date')
             THEN (effective_authority.resolved_component_key_value::date)::text=
               effective_authority.resolved_component_key_value ELSE false END)
          THEN 'FROZEN_ECONOMIC_KEY_INVALID'
      END AS final_failure
    FROM effective_authority
  ), projected AS (
    SELECT classified.*,
      classified.settled_authority AND classified.owner_in_scope
        AND classified.final_failure IS NULL AS authoritative_in_scope,
      md5(jsonb_build_object(
        'pay_batch_candidate_id',classified.pay_batch_candidate_id,
        'pay_batch_item_id',classified.id,'item_type',classified.item_type,
        'amount_ex_vat',classified.amount_ex_vat,'amount_inc_vat',classified.amount_inc_vat,
        'frozen_source_amount',classified.frozen_source_amount,
        'settlement_status',classified.settlement_status,
        'settled_at_utc',classified.settled_at_utc,
        'transfer_status',classified.transfer_status,
        'transfer_completed_at_utc',classified.completed_at_utc,
        'reservation_has_settled',classified.reservation_has_settled,
        'is_reversed',classified.is_reversed)::text) AS raw_physical_digest
    FROM classified
  )
  SELECT '05:'||projected.pay_batch_candidate_id::text||':'||projected.id::text,
    projected.pay_batch_candidate_id,projected.id,projected.effective_timesheet_id,
    projected.resolved_candidate_id,projected.resolved_finance_case_id,
    projected.resolved_finance_component_id,projected.resolved_component_key_type,
    projected.resolved_component_key_value,
    ROUND(CASE WHEN UPPER(BTRIM(projected.item_type))='OVERPAYMENT_RECOVERY'
      THEN -1 ELSE 1 END*projected.resolved_source_amount,2),
    ROUND(CASE WHEN UPPER(BTRIM(projected.item_type))='OVERPAYMENT_RECOVERY'
      THEN -1 ELSE 1 END*COALESCE(NULLIF(ABS(projected.amount_inc_vat),0),
        projected.resolved_source_amount),2),
    projected.authoritative_in_scope,
    jsonb_build_object(
      'role','FINANCE_ITEM_AUTHORITY','pay_batch_item_id',projected.id,
      'pay_batch_candidate_id',projected.pay_batch_candidate_id,
      'item_type',UPPER(BTRIM(projected.item_type)),
      'settled_authority',projected.settled_authority,
      'authoritative_in_scope',projected.authoritative_in_scope,
      'owner_in_scope',projected.owner_in_scope,
      'evidence_only',NOT projected.authoritative_in_scope,
      'authority_resolution_status',projected.authority_resolution_status,
      'owner_evidence',projected.evidence_json,
      'finance_case_id',projected.resolved_finance_case_id,
      'finance_component_id',projected.resolved_finance_component_id,
      'source_timesheet_id',projected.effective_timesheet_id,
      'raw_physical_source_key','05:'||projected.pay_batch_candidate_id::text||':'||projected.id::text,
      'raw_physical_digest',projected.raw_physical_digest,
      'raw_physical_amount_ex_vat',ROUND(CASE
        WHEN UPPER(BTRIM(projected.item_type))='OVERPAYMENT_RECOVERY' THEN -1 ELSE 1 END*
        ABS(COALESCE(NULLIF(projected.frozen_source_amount,0),
          NULLIF(projected.settled_source_amount,0),NULLIF(projected.amount_ex_vat,0),
          NULLIF(projected.amount_inc_vat,0),0)),2),
      'resolution_failure',projected.final_failure,
      'frozen_source_basis_json',projected.frozen_source_basis_json,
      'frozen_component_snapshot_json',projected.frozen_component_snapshot_json),
    md5(jsonb_build_object('pay_batch_item_id',projected.id,
      'pay_batch_candidate_id',projected.pay_batch_candidate_id,
      'resolved_timesheet_id',projected.effective_timesheet_id,
      'resolved_candidate_id',projected.resolved_candidate_id,
      'resolved_finance_case_id',projected.resolved_finance_case_id,
      'resolved_finance_component_id',projected.resolved_finance_component_id,
      'key_type',projected.resolved_component_key_type,
      'key_value',projected.resolved_component_key_value,
      'amount_ex_vat',projected.resolved_source_amount,
      'settled_authority',projected.settled_authority,
      'authoritative_in_scope',projected.authoritative_in_scope,
      'authority_resolution_status',projected.authority_resolution_status,
      'raw_physical_digest',projected.raw_physical_digest)::text),
    projected.final_failure
  FROM projected
  ORDER BY projected.pay_batch_candidate_id,projected.id;
END;
$function$;

-- private.pay_workbench_financial_scope_dirty_transition_v1()
CREATE OR REPLACE FUNCTION private.pay_workbench_financial_scope_dirty_transition_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_reason text;
  v_candidate_ids uuid[];
  v_timesheet_ids uuid[];
  v_expected regclass:=pg_catalog.to_regclass('pg_temp._bpay_wb_expected_effects');
  v_draft_context regclass:=pg_catalog.to_regclass('pg_temp._bpay_wb_draft_expected_effect_context_v1');
  v_draft_observed regclass:=pg_catalog.to_regclass('pg_temp._bpay_wb_draft_observed_effects_v1');
  v_delete_context regclass:=pg_catalog.to_regclass('pg_temp._bpay_candidate_delete_context_v1');
  v_relation_owner oid;
  v_duplicate boolean:=false;
  v_mismatch_detail jsonb:='{}'::jsonb;
  v_draft_operation_id uuid:=NULL::uuid;
  v_draft_phase text:=NULL::text;
  v_draft_context_token text:=NULL::text;
  v_correction_dirty_contexts jsonb:='{}'::jsonb;
  v_correction_context_count integer:=0;
  v_execution_overlay_context regclass:=pg_catalog.to_regclass(
    'pg_temp._bpay_wb_unsent_execution_overlay_context_v1');
  v_execution_overlay_contexts jsonb:='{}'::jsonb;
  v_execution_overlay_context_count integer:=0;
  v_execution_overlay_exact boolean:=false;
  v_execution_schedule_context regclass:=pg_catalog.to_regclass(
    'pg_temp._bpay_wb_unsent_execution_schedule_context_v2');
  v_execution_schedule_contexts jsonb:='{}'::jsonb;
  v_execution_schedule_context_count integer:=0;
  v_execution_schedule_exact boolean:=false;
  v_impacted_candidate_count integer:=0;
  v_scope_change_tx_token uuid:=NULL::uuid;
BEGIN
  CREATE TEMP TABLE IF NOT EXISTS pg_temp._bpay_wb_transition_impacts_v1(
    relation_name text NOT NULL,
    operation text NOT NULL,
    source_id uuid NOT NULL,
    candidate_id uuid NOT NULL,
    timesheet_id uuid NULL,
    before_digest text NULL,
    after_digest text NULL,
    reason text NOT NULL,
    UNIQUE NULLS NOT DISTINCT(relation_name,operation,source_id,candidate_id,timesheet_id)
  ) ON COMMIT DROP;
  TRUNCATE pg_temp._bpay_wb_transition_impacts_v1;

  v_reason:=upper(TG_TABLE_NAME)||'_'||upper(TG_OP);

  IF TG_TABLE_NAME='pay_advances' THEN
    IF TG_OP IN ('UPDATE','DELETE') THEN
      INSERT INTO pg_temp._bpay_wb_transition_impacts_v1
      SELECT TG_TABLE_NAME,TG_OP,r.id,r.candidate_id,r.linked_timesheet_id,
        md5(private.pay_workbench_finance_effect_normalise_row_v1(
          TG_TABLE_NAME,TG_OP,to_jsonb(r),to_jsonb(r))::text),NULL,v_reason FROM old_rows r ON CONFLICT DO NOTHING;
    END IF;
    IF TG_OP='INSERT' THEN
      INSERT INTO pg_temp._bpay_wb_transition_impacts_v1
      SELECT TG_TABLE_NAME,TG_OP,r.id,r.candidate_id,r.linked_timesheet_id,
        NULL,md5(private.pay_workbench_finance_effect_normalise_row_v1(
          TG_TABLE_NAME,TG_OP,to_jsonb(r),'{}'::jsonb)::text),v_reason FROM new_rows r
      ON CONFLICT(relation_name,operation,source_id,candidate_id,timesheet_id) DO UPDATE
      SET after_digest=EXCLUDED.after_digest;
    ELSIF TG_OP='UPDATE' THEN
      INSERT INTO pg_temp._bpay_wb_transition_impacts_v1
      SELECT TG_TABLE_NAME,TG_OP,r.id,r.candidate_id,r.linked_timesheet_id,
        NULL,md5(private.pay_workbench_finance_effect_normalise_row_v1(
          TG_TABLE_NAME,TG_OP,to_jsonb(r),to_jsonb(old_row))::text),v_reason
      FROM new_rows r JOIN old_rows old_row ON old_row.id=r.id
      ON CONFLICT(relation_name,operation,source_id,candidate_id,timesheet_id) DO UPDATE
      SET after_digest=EXCLUDED.after_digest;
    END IF;

  ELSIF TG_TABLE_NAME='pay_finance_case_components' THEN
    IF TG_OP IN ('UPDATE','DELETE') THEN
      INSERT INTO pg_temp._bpay_wb_transition_impacts_v1
      SELECT TG_TABLE_NAME,TG_OP,r.id,r.candidate_id,r.linked_timesheet_id,
        md5(private.pay_workbench_finance_effect_normalise_row_v1(
          TG_TABLE_NAME,TG_OP,to_jsonb(r),to_jsonb(r))::text),NULL,v_reason FROM old_rows r ON CONFLICT DO NOTHING;
    END IF;
    IF TG_OP='INSERT' THEN
      INSERT INTO pg_temp._bpay_wb_transition_impacts_v1
      SELECT TG_TABLE_NAME,TG_OP,r.id,r.candidate_id,r.linked_timesheet_id,
        NULL,md5(private.pay_workbench_finance_effect_normalise_row_v1(
          TG_TABLE_NAME,TG_OP,to_jsonb(r),'{}'::jsonb)::text),v_reason FROM new_rows r
      ON CONFLICT(relation_name,operation,source_id,candidate_id,timesheet_id) DO UPDATE
      SET after_digest=EXCLUDED.after_digest;
    ELSIF TG_OP='UPDATE' THEN
      INSERT INTO pg_temp._bpay_wb_transition_impacts_v1
      SELECT TG_TABLE_NAME,TG_OP,r.id,r.candidate_id,r.linked_timesheet_id,
        NULL,md5(private.pay_workbench_finance_effect_normalise_row_v1(
          TG_TABLE_NAME,TG_OP,to_jsonb(r),to_jsonb(old_row))::text),v_reason
      FROM new_rows r JOIN old_rows old_row ON old_row.id=r.id
      ON CONFLICT(relation_name,operation,source_id,candidate_id,timesheet_id) DO UPDATE
      SET after_digest=EXCLUDED.after_digest;
    END IF;

  ELSIF TG_TABLE_NAME='pay_finance_case_events' THEN
    IF TG_OP IN ('UPDATE','DELETE') THEN
      INSERT INTO pg_temp._bpay_wb_transition_impacts_v1
      SELECT TG_TABLE_NAME,TG_OP,r.id,COALESCE(component.candidate_id,finance_case.candidate_id),
        COALESCE(component.linked_timesheet_id,finance_case.linked_timesheet_id),
        md5(private.pay_workbench_finance_effect_normalise_row_v1(
          TG_TABLE_NAME,TG_OP,to_jsonb(r),to_jsonb(r))::text),NULL,v_reason FROM old_rows r
      LEFT JOIN public.pay_finance_case_components component ON component.id=r.finance_component_id
      LEFT JOIN public.pay_advances finance_case ON finance_case.id=r.finance_case_id
      WHERE COALESCE(component.candidate_id,finance_case.candidate_id) IS NOT NULL ON CONFLICT DO NOTHING;
    END IF;
    IF TG_OP='INSERT' THEN
      INSERT INTO pg_temp._bpay_wb_transition_impacts_v1
      SELECT TG_TABLE_NAME,TG_OP,r.id,COALESCE(component.candidate_id,finance_case.candidate_id),
        COALESCE(component.linked_timesheet_id,finance_case.linked_timesheet_id),
        NULL,md5(private.pay_workbench_finance_effect_normalise_row_v1(
          TG_TABLE_NAME,TG_OP,to_jsonb(r),'{}'::jsonb)::text),v_reason FROM new_rows r
      LEFT JOIN public.pay_finance_case_components component ON component.id=r.finance_component_id
      LEFT JOIN public.pay_advances finance_case ON finance_case.id=r.finance_case_id
      WHERE COALESCE(component.candidate_id,finance_case.candidate_id) IS NOT NULL
      ON CONFLICT(relation_name,operation,source_id,candidate_id,timesheet_id) DO UPDATE
      SET after_digest=EXCLUDED.after_digest;
    ELSIF TG_OP='UPDATE' THEN
      INSERT INTO pg_temp._bpay_wb_transition_impacts_v1
      SELECT TG_TABLE_NAME,TG_OP,r.id,COALESCE(component.candidate_id,finance_case.candidate_id),
        COALESCE(component.linked_timesheet_id,finance_case.linked_timesheet_id),
        NULL,md5(private.pay_workbench_finance_effect_normalise_row_v1(
          TG_TABLE_NAME,TG_OP,to_jsonb(r),to_jsonb(old_row))::text),v_reason
      FROM new_rows r JOIN old_rows old_row ON old_row.id=r.id
      LEFT JOIN public.pay_finance_case_components component ON component.id=r.finance_component_id
      LEFT JOIN public.pay_advances finance_case ON finance_case.id=r.finance_case_id
      WHERE COALESCE(component.candidate_id,finance_case.candidate_id) IS NOT NULL
      ON CONFLICT(relation_name,operation,source_id,candidate_id,timesheet_id) DO UPDATE
      SET after_digest=EXCLUDED.after_digest;
    END IF;

  ELSIF TG_TABLE_NAME='pay_batch_items' THEN
    IF TG_OP IN ('UPDATE','DELETE') THEN
      INSERT INTO pg_temp._bpay_wb_transition_impacts_v1
      SELECT TG_TABLE_NAME,TG_OP,r.id,
        COALESCE(batch_candidate.candidate_id,current_financial.candidate_id,component.candidate_id),
        COALESCE(r.timesheet_id,component.linked_timesheet_id),
        md5(jsonb_build_object(
          'pay_batch_candidate_id',r.pay_batch_candidate_id,'item_type',r.item_type,
          'timesheet_id',r.timesheet_id,'amount_ex_vat',r.amount_ex_vat,
          'amount_vat',r.amount_vat,'amount_inc_vat',r.amount_inc_vat,
          'pay_channel',r.pay_channel,'pay_bank_transfer_id',r.pay_bank_transfer_id,
          'is_voided',r.is_voided,'finance_case_id',r.finance_case_id,
          'reservation_id',r.reservation_id,'finance_component_id',r.finance_component_id,
          'frozen_component_snapshot_json',r.frozen_component_snapshot_json,
          'frozen_component_key_type',r.frozen_component_key_type,
          'frozen_component_key_value',r.frozen_component_key_value,
          'frozen_component_classification',r.frozen_component_classification,
          'frozen_source_basis_json',r.frozen_source_basis_json,
          'frozen_source_pay_method',r.frozen_source_pay_method,
