  ELSIF TG_TABLE_NAME='pay_batches' AND TG_OP='DELETE' THEN
    -- Exact child statement triggers carry candidate/timesheet effects. Empty batches
    -- have no Banking Pay economic scope, so this parent backstop intentionally emits none.
    NULL;
  ELSE
    RAISE EXCEPTION 'PAY_WORKBENCH_DIRTY_TRANSITION_IDENTITY_UNRESOLVED'
      USING ERRCODE='22023',DETAIL=TG_TABLE_SCHEMA||'.'||TG_TABLE_NAME||':'||TG_OP;
  END IF;

  -- Canonical Draft writers install a transaction-local operation context.
  -- Only effects belonging to that exact operation/batch/candidate scope and
  -- an allow-listed relation/action are consumed.  Everything else remains in
  -- the normal dirty path and is recorded as an unmatched effect so the writer
  -- fails closed at its phase assertion.
  IF v_draft_context IS NOT NULL AND v_draft_observed IS NOT NULL THEN
    SELECT relowner INTO v_relation_owner FROM pg_catalog.pg_class WHERE oid=v_draft_context;
    IF v_relation_owner=current_user::regrole::oid
       AND EXISTS(SELECT 1 FROM pg_catalog.pg_class relation
         WHERE relation.oid=v_draft_context AND relation.relpersistence='t'
           AND relation.relnamespace=pg_catalog.pg_my_temp_schema())
       AND (SELECT array_agg(attribute.attname::text ORDER BY attribute.attnum)
            FROM pg_catalog.pg_attribute attribute
            WHERE attribute.attrelid=v_draft_context AND attribute.attnum>0 AND NOT attribute.attisdropped)
          =ARRAY['operation_id','pay_batch_id','workbench_session_id','phase','backend_pid',
            'transaction_id','registered_at_utc','expected_effects_json','context_token']
       AND EXISTS(SELECT 1 FROM pg_catalog.pg_class relation
         WHERE relation.oid=v_draft_observed AND relation.relpersistence='t'
           AND relation.relnamespace=pg_catalog.pg_my_temp_schema())
       AND (SELECT array_agg(attribute.attname::text ORDER BY attribute.attnum)
            FROM pg_catalog.pg_attribute attribute
            WHERE attribute.attrelid=v_draft_observed AND attribute.attnum>0 AND NOT attribute.attisdropped)
          =ARRAY['operation_id','pay_batch_id','phase','relation_name','operation','source_id',
            'candidate_id','timesheet_id','before_digest','after_digest','matched','observed_at_utc'] THEN
      SELECT context_row.operation_id,context_row.phase,context_row.context_token
      INTO v_draft_operation_id,v_draft_phase,v_draft_context_token
      FROM pg_temp._bpay_wb_draft_expected_effect_context_v1 AS context_row
      WHERE context_row.backend_pid=pg_catalog.pg_backend_pid()
        AND context_row.transaction_id=pg_catalog.txid_current()
      LIMIT 1;

      IF v_draft_operation_id IS NOT NULL THEN
        INSERT INTO pg_temp._bpay_wb_draft_observed_effects_v1(
          operation_id,pay_batch_id,phase,relation_name,operation,source_id,
          candidate_id,timesheet_id,before_digest,after_digest,matched,observed_at_utc
        )
        SELECT
          context_row.operation_id,context_row.pay_batch_id,context_row.phase,
          impact.relation_name,impact.operation,impact.source_id,impact.candidate_id,
          impact.timesheet_id,impact.before_digest,impact.after_digest,
          (
            EXISTS(
              SELECT 1
              FROM pg_catalog.jsonb_array_elements(context_row.expected_effects_json) AS expected(value)
              WHERE pg_catalog.lower(pg_catalog.btrim(COALESCE(expected.value->>'relation_name','')))=impact.relation_name
                AND pg_catalog.upper(pg_catalog.btrim(COALESCE(expected.value->>'operation','')))=impact.operation
            )
            AND EXISTS(
              SELECT 1
              FROM public.banking_pay_operation_candidate_scope AS operation_scope
              WHERE operation_scope.operation_id=context_row.operation_id
                AND operation_scope.pay_batch_id=context_row.pay_batch_id
                AND operation_scope.candidate_id=impact.candidate_id
                AND operation_scope.status NOT IN ('FAILED','CANCELLED','SUPERSEDED')
            )
            AND CASE impact.relation_name
              WHEN 'pay_batch_items' THEN EXISTS(
                SELECT 1 FROM public.pay_batch_items item
                JOIN public.pay_batch_candidates candidate ON candidate.id=item.pay_batch_candidate_id
                WHERE item.id=impact.source_id AND candidate.pay_batch_id=context_row.pay_batch_id
              ) OR impact.operation='DELETE'
              WHEN 'pay_batch_item_breakdowns' THEN EXISTS(
                SELECT 1 FROM public.pay_batch_item_breakdowns breakdown
                JOIN public.pay_batch_items item ON item.id=breakdown.pay_batch_item_id
                JOIN public.pay_batch_candidates candidate ON candidate.id=item.pay_batch_candidate_id
                WHERE breakdown.id=impact.source_id AND candidate.pay_batch_id=context_row.pay_batch_id
              ) OR impact.operation='DELETE'
              WHEN 'pay_batch_timesheet_snapshots' THEN EXISTS(
                SELECT 1 FROM public.pay_batch_timesheet_snapshots snapshot
                WHERE snapshot.id=impact.source_id AND snapshot.pay_batch_id=context_row.pay_batch_id
              )
              WHEN 'pay_advance_reservations' THEN EXISTS(
                SELECT 1 FROM public.pay_advance_reservations reservation
                WHERE reservation.id=impact.source_id AND reservation.pay_batch_id=context_row.pay_batch_id
              ) OR impact.operation='DELETE'
              WHEN 'pay_finance_case_events' THEN EXISTS(
                SELECT 1 FROM public.pay_finance_case_events event
                WHERE event.id=impact.source_id AND event.pay_batch_id=context_row.pay_batch_id
              ) OR impact.operation='DELETE'
              WHEN 'pay_batch_candidates' THEN impact.operation='DELETE'
              ELSE impact.relation_name IN ('pay_advances','pay_finance_case_components')
            END
          ),
          pg_catalog.clock_timestamp()
        FROM pg_temp._bpay_wb_transition_impacts_v1 AS impact
        CROSS JOIN pg_temp._bpay_wb_draft_expected_effect_context_v1 AS context_row
        WHERE context_row.operation_id=v_draft_operation_id
        ON CONFLICT(operation_id,phase,relation_name,operation,source_id,candidate_id)
        DO UPDATE SET
          timesheet_id=EXCLUDED.timesheet_id,
          before_digest=EXCLUDED.before_digest,
          after_digest=EXCLUDED.after_digest,
          matched=EXCLUDED.matched,
          observed_at_utc=EXCLUDED.observed_at_utc;

        DELETE FROM pg_temp._bpay_wb_transition_impacts_v1 AS impact
        USING pg_temp._bpay_wb_draft_observed_effects_v1 AS observed
        WHERE observed.operation_id=v_draft_operation_id
          AND observed.phase=v_draft_phase
          AND observed.matched
          AND observed.relation_name=impact.relation_name
          AND observed.operation=impact.operation
          AND observed.source_id=impact.source_id
          AND observed.candidate_id=impact.candidate_id;
      END IF;
    END IF;
  END IF;

  -- UPDATE rows are economically relevant only where the typed digest changed.
  DELETE FROM pg_temp._bpay_wb_transition_impacts_v1
  WHERE operation='UPDATE' AND before_digest IS NOT DISTINCT FROM after_digest;

  -- A candidate-delete cascade is suppressible only through the exact owner-created,
  -- backend/transaction-bound context installed by candidate_delete_apply.
  IF v_delete_context IS NOT NULL THEN
    SELECT relowner INTO v_relation_owner FROM pg_catalog.pg_class WHERE oid=v_delete_context;
    IF v_relation_owner=current_user::regrole::oid
       AND EXISTS(SELECT 1 FROM pg_catalog.pg_class relation
         WHERE relation.oid=v_delete_context AND relation.relpersistence='t'
           AND relation.relnamespace=pg_catalog.pg_my_temp_schema())
       AND (SELECT array_agg(attribute.attname||':'||pg_catalog.format_type(attribute.atttypid,attribute.atttypmod)
              ORDER BY attribute.attnum)
            FROM pg_catalog.pg_attribute attribute
            WHERE attribute.attrelid=v_delete_context AND attribute.attnum>0 AND NOT attribute.attisdropped)
          =ARRAY['candidate_id:uuid','delete_operation_id:uuid','candidate_lock_key:bigint',
            'backend_pid:integer','transaction_id:bigint','created_at_utc:timestamp with time zone',
            'suppress:boolean'] THEN
      EXECUTE $sql$
        DELETE FROM pg_temp._bpay_wb_transition_impacts_v1 AS impact
        USING pg_temp._bpay_candidate_delete_context_v1 AS context
        WHERE impact.operation='DELETE'
          AND impact.candidate_id=context.candidate_id
          AND context.suppress
          AND context.candidate_lock_key=pg_catalog.hashtextextended(
            public._pay_workbench_candidate_serial_key(context.candidate_id),24062027)
          AND context.backend_pid=pg_catalog.pg_backend_pid()
          AND context.transaction_id=pg_catalog.txid_current()
          AND (SELECT count(*) FROM pg_temp._bpay_candidate_delete_context_v1)=1
      $sql$;
    END IF;
  END IF;

  -- Finance effects produced by the validated build are consumed only when their
  -- full identity and typed before/after digests match one owner-created row.
  IF v_expected IS NOT NULL THEN
    SELECT relowner INTO v_relation_owner FROM pg_catalog.pg_class WHERE oid=v_expected;
    IF v_relation_owner=current_user::regrole::oid
       AND EXISTS(SELECT 1 FROM pg_catalog.pg_class relation
         WHERE relation.oid=v_expected AND relation.relpersistence='t'
           AND relation.relnamespace=pg_catalog.pg_my_temp_schema())
       AND (SELECT array_agg(attribute.attname::text ORDER BY attribute.attnum)
            FROM pg_catalog.pg_attribute attribute
            WHERE attribute.attrelid=v_expected AND attribute.attnum>0 AND NOT attribute.attisdropped)
          =ARRAY['build_token','candidate_id','timesheet_id','relation_name','operation','source_id',
            'actual_source_id','finance_case_id','finance_component_id','economic_key_type','economic_key_value',
            'proposed','expected_before_digest','expected_after_digest','observed'] THEN
      EXECUTE $sql$
        SELECT EXISTS(
          SELECT 1
          FROM pg_temp._bpay_wb_transition_impacts_v1 impact
          JOIN pg_temp._bpay_wb_expected_effects expected
            ON expected.relation_name=impact.relation_name
           AND expected.operation=impact.operation
           AND COALESCE(expected.actual_source_id,expected.source_id)=impact.source_id
           AND expected.candidate_id=impact.candidate_id
           AND expected.timesheet_id IS NOT DISTINCT FROM impact.timesheet_id
           AND expected.expected_before_digest IS NOT DISTINCT FROM impact.before_digest
           AND expected.expected_after_digest IS NOT DISTINCT FROM impact.after_digest
           AND expected.proposed IS TRUE
           AND expected.observed IS NOT TRUE
          GROUP BY impact.relation_name,impact.operation,impact.source_id,impact.candidate_id,impact.timesheet_id
          HAVING count(*)<>1
        )
      $sql$ INTO v_duplicate;
      IF v_duplicate THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_CONFLICT' USING ERRCODE='23514';
      END IF;
      EXECUTE $sql$
        UPDATE pg_temp._bpay_wb_expected_effects expected SET observed=true
        FROM pg_temp._bpay_wb_transition_impacts_v1 impact
        WHERE expected.relation_name=impact.relation_name
          AND expected.operation=impact.operation
          AND COALESCE(expected.actual_source_id,expected.source_id)=impact.source_id
          AND expected.candidate_id=impact.candidate_id
          AND expected.timesheet_id IS NOT DISTINCT FROM impact.timesheet_id
          AND expected.expected_before_digest IS NOT DISTINCT FROM impact.before_digest
          AND expected.expected_after_digest IS NOT DISTINCT FROM impact.after_digest
          AND expected.proposed IS TRUE
          AND expected.observed IS NOT TRUE
      $sql$;
      EXECUTE $sql$
        DELETE FROM pg_temp._bpay_wb_transition_impacts_v1 impact
        USING pg_temp._bpay_wb_expected_effects expected
        WHERE expected.relation_name=impact.relation_name
          AND expected.operation=impact.operation
          AND COALESCE(expected.actual_source_id,expected.source_id)=impact.source_id
          AND expected.candidate_id=impact.candidate_id
          AND expected.timesheet_id IS NOT DISTINCT FROM impact.timesheet_id
          AND expected.expected_before_digest IS NOT DISTINCT FROM impact.before_digest
          AND expected.proposed IS TRUE
          AND expected.observed IS TRUE
          AND expected.expected_after_digest IS NOT DISTINCT FROM impact.after_digest
      $sql$;
      IF EXISTS(SELECT 1 FROM pg_temp._bpay_wb_transition_impacts_v1) THEN
        SELECT jsonb_build_object(
          'impact_count',(SELECT count(*) FROM pg_temp._bpay_wb_transition_impacts_v1),
          'expected_count',(SELECT count(*) FROM pg_temp._bpay_wb_expected_effects),
          'identity_match_count',(
            SELECT count(*)
            FROM pg_temp._bpay_wb_transition_impacts_v1 impact
            WHERE EXISTS(
              SELECT 1 FROM pg_temp._bpay_wb_expected_effects expected
              WHERE expected.relation_name=impact.relation_name
                AND expected.operation=impact.operation
                AND COALESCE(expected.actual_source_id,expected.source_id)=impact.source_id
                AND expected.candidate_id=impact.candidate_id
                AND expected.timesheet_id IS NOT DISTINCT FROM impact.timesheet_id
            )
          ),
          'before_match_count',(
            SELECT count(*)
            FROM pg_temp._bpay_wb_transition_impacts_v1 impact
            WHERE EXISTS(
              SELECT 1 FROM pg_temp._bpay_wb_expected_effects expected
              WHERE expected.relation_name=impact.relation_name
                AND expected.operation=impact.operation
                AND COALESCE(expected.actual_source_id,expected.source_id)=impact.source_id
                AND expected.candidate_id=impact.candidate_id
                AND expected.timesheet_id IS NOT DISTINCT FROM impact.timesheet_id
                AND expected.expected_before_digest IS NOT DISTINCT FROM impact.before_digest
            )
          ),
          'after_match_count',(
            SELECT count(*)
            FROM pg_temp._bpay_wb_transition_impacts_v1 impact
            WHERE EXISTS(
              SELECT 1 FROM pg_temp._bpay_wb_expected_effects expected
              WHERE expected.relation_name=impact.relation_name
                AND expected.operation=impact.operation
                AND COALESCE(expected.actual_source_id,expected.source_id)=impact.source_id
                AND expected.candidate_id=impact.candidate_id
                AND expected.timesheet_id IS NOT DISTINCT FROM impact.timesheet_id
                AND expected.expected_after_digest IS NOT DISTINCT FROM impact.after_digest
            )
          ),
          'by_relation_operation',COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
              'relation_name',grouped.relation_name,
              'operation',grouped.operation,
              'impact_count',grouped.impact_count
            ) ORDER BY grouped.relation_name,grouped.operation)
            FROM (
              SELECT impact.relation_name,impact.operation,count(*) AS impact_count
              FROM pg_temp._bpay_wb_transition_impacts_v1 impact
              GROUP BY impact.relation_name,impact.operation
            ) grouped
          ),'[]'::jsonb)
        ) INTO v_mismatch_detail;
        RAISE EXCEPTION 'PAY_WORKBENCH_EXPECTED_EFFECT_MISMATCH %',v_mismatch_detail::text
          USING ERRCODE='23514';
      END IF;
    END IF;
  END IF;

  SELECT array_agg(candidate_id ORDER BY candidate_id,timesheet_id NULLS FIRST),
         array_agg(timesheet_id ORDER BY candidate_id,timesheet_id NULLS FIRST)
  INTO v_candidate_ids,v_timesheet_ids
  FROM (
    SELECT DISTINCT candidate_id,timesheet_id
    FROM pg_temp._bpay_wb_transition_impacts_v1
  ) AS impacted;

  IF COALESCE(cardinality(v_candidate_ids),0)>0 THEN
    SELECT pg_catalog.count(DISTINCT candidate_id)::integer
    INTO v_impacted_candidate_count
    FROM pg_temp._bpay_wb_transition_impacts_v1;

    -- The execution owner deliberately links otherwise frozen batch items to
    -- newly prepared local transfer rows.  Preserve normal invalidation, but
    -- stamp it only when the complete UPDATE statement is exactly represented
    -- by the owner-created transaction-local context and no other column moved.
    IF TG_TABLE_NAME='pay_batch_items' AND TG_OP='UPDATE'
       AND v_execution_overlay_context IS NOT NULL THEN
      SELECT relation.relowner
      INTO v_relation_owner
      FROM pg_catalog.pg_class AS relation
      WHERE relation.oid=v_execution_overlay_context;

      IF v_relation_owner=current_user::regrole::oid
         AND EXISTS (
           SELECT 1 FROM pg_catalog.pg_class AS relation
           WHERE relation.oid=v_execution_overlay_context
             AND relation.relpersistence='t'
             AND relation.relnamespace=pg_catalog.pg_my_temp_schema()
         )
         AND (SELECT pg_catalog.array_agg(
                attribute.attname||':'||pg_catalog.format_type(attribute.atttypid,attribute.atttypmod)
                ORDER BY attribute.attnum)
              FROM pg_catalog.pg_attribute AS attribute
              WHERE attribute.attrelid=v_execution_overlay_context
                AND attribute.attnum>0 AND NOT attribute.attisdropped)
             =ARRAY[
               'contract_version:text','execution_operation_id:uuid','pay_batch_id:uuid',
               'pay_batch_candidate_id:uuid','candidate_id:uuid','timesheet_id:uuid',
               'pay_batch_item_id:uuid','pay_bank_transfer_id:uuid','transfer_scope_id:uuid',
               'source_workbench_session_id:uuid','source_snapshot_run_id:uuid',
               'source_session_version:bigint','row_context_digest:text',
               'created_at_utc:timestamp with time zone'
             ] THEN
        SELECT
          NOT EXISTS (
            SELECT 1
            FROM new_rows AS new_row
            JOIN old_rows AS old_row ON old_row.id=new_row.id
            LEFT JOIN pg_temp._bpay_wb_unsent_execution_overlay_context_v1 AS context_row
              ON context_row.pay_batch_item_id=new_row.id
             AND context_row.pay_batch_candidate_id=new_row.pay_batch_candidate_id
             AND context_row.timesheet_id IS NOT DISTINCT FROM new_row.timesheet_id
             AND context_row.pay_bank_transfer_id=new_row.pay_bank_transfer_id
            WHERE old_row.pay_bank_transfer_id IS NOT NULL
               OR new_row.pay_bank_transfer_id IS NULL
               OR context_row.pay_batch_item_id IS NULL
               OR (pg_catalog.to_jsonb(new_row)-'pay_bank_transfer_id'-'updated_at')
                    IS DISTINCT FROM
                  (pg_catalog.to_jsonb(old_row)-'pay_bank_transfer_id'-'updated_at')
          )
          AND (SELECT pg_catalog.count(*) FROM new_rows)
              =(SELECT pg_catalog.count(*)
                FROM pg_temp._bpay_wb_unsent_execution_overlay_context_v1),
          (SELECT pg_catalog.count(*)::integer
           FROM pg_temp._bpay_wb_unsent_execution_overlay_context_v1)
        INTO v_execution_overlay_exact,v_execution_overlay_context_count;

        IF v_execution_overlay_exact AND v_execution_overlay_context_count>0 THEN
          SELECT COALESCE(pg_catalog.jsonb_object_agg(
                   candidate_group.candidate_id::text,
                   pg_catalog.jsonb_build_object(
                     'contract_version','EXECUTION_UNSENT_OVERLAY_CONTEXT_V1',
                     'execution_operation_id',candidate_group.execution_operation_id,
                     'pay_batch_id',candidate_group.pay_batch_id,
                     'candidate_id',candidate_group.candidate_id,
                     'pay_batch_candidate_ids',candidate_group.pay_batch_candidate_ids,
                     'pay_batch_item_ids',candidate_group.pay_batch_item_ids,
                     'timesheet_ids',candidate_group.timesheet_ids,
                     'transfer_scope_ids',candidate_group.transfer_scope_ids,
                     'pay_bank_transfer_ids',candidate_group.pay_bank_transfer_ids,
                     'source_workbench_session_id',candidate_group.source_workbench_session_id,
                     'source_snapshot_run_id',candidate_group.source_snapshot_run_id,
                     'source_session_version',candidate_group.source_session_version,
                     'context_digest',pg_catalog.md5(
                       candidate_group.execution_operation_id::text||'|'||
                       candidate_group.pay_batch_id::text||'|'||candidate_group.candidate_id::text||'|'||
                       candidate_group.pay_batch_candidate_ids::text||'|'||
                       candidate_group.pay_batch_item_ids::text||'|'||candidate_group.timesheet_ids::text||'|'||
                       candidate_group.transfer_scope_ids::text||'|'||
                       candidate_group.pay_bank_transfer_ids::text||'|'||
                       COALESCE(candidate_group.source_workbench_session_id::text,'')||'|'||
                       COALESCE(candidate_group.source_snapshot_run_id::text,'')||'|'||
                       COALESCE(candidate_group.source_session_version::text,'')||
                       '|EXECUTION_UNSENT_OVERLAY_CONTEXT_V1'
                     )
                   ) ORDER BY candidate_group.candidate_id
                 ),'{}'::jsonb)
          INTO v_execution_overlay_contexts
          FROM (
            SELECT context_row.candidate_id,
              pg_catalog.min(context_row.execution_operation_id::text)::uuid AS execution_operation_id,
              pg_catalog.min(context_row.pay_batch_id::text)::uuid AS pay_batch_id,
              pg_catalog.jsonb_agg(DISTINCT context_row.pay_batch_candidate_id::text
                ORDER BY context_row.pay_batch_candidate_id::text) AS pay_batch_candidate_ids,
              pg_catalog.jsonb_agg(DISTINCT context_row.pay_batch_item_id::text
                ORDER BY context_row.pay_batch_item_id::text) AS pay_batch_item_ids,
              COALESCE(pg_catalog.jsonb_agg(DISTINCT context_row.timesheet_id::text
                ORDER BY context_row.timesheet_id::text)
                FILTER (WHERE context_row.timesheet_id IS NOT NULL),'[]'::jsonb) AS timesheet_ids,
              pg_catalog.jsonb_agg(DISTINCT context_row.transfer_scope_id::text
                ORDER BY context_row.transfer_scope_id::text) AS transfer_scope_ids,
              pg_catalog.jsonb_agg(DISTINCT context_row.pay_bank_transfer_id::text
                ORDER BY context_row.pay_bank_transfer_id::text) AS pay_bank_transfer_ids,
              pg_catalog.min(context_row.source_workbench_session_id::text)::uuid AS source_workbench_session_id,
              pg_catalog.min(context_row.source_snapshot_run_id::text)::uuid AS source_snapshot_run_id,
              pg_catalog.min(context_row.source_session_version) AS source_session_version
            FROM pg_temp._bpay_wb_unsent_execution_overlay_context_v1 AS context_row
            GROUP BY context_row.candidate_id
            HAVING pg_catalog.count(DISTINCT context_row.execution_operation_id)=1
               AND pg_catalog.count(DISTINCT context_row.pay_batch_id)=1
               AND pg_catalog.count(DISTINCT context_row.source_workbench_session_id)<=1
               AND pg_catalog.count(DISTINCT context_row.source_snapshot_run_id)<=1
               AND pg_catalog.count(DISTINCT context_row.source_session_version)<=1
          ) AS candidate_group;

          IF (SELECT pg_catalog.count(*)
                FROM pg_catalog.jsonb_object_keys(v_execution_overlay_contexts))
               <>v_impacted_candidate_count THEN
            v_execution_overlay_exact:=false;
            v_execution_overlay_contexts:='{}'::jsonb;
          ELSE
            v_scope_change_tx_token:=public.pay_workbench_scope_change_tx_token_v1();
          END IF;
        END IF;
      END IF;
    END IF;

    -- The exact PAYMENT_EXECUTE scheduling owner may create one further
    -- finalized candidate generation while committing frozen reservations and
    -- their audit events.  Stamp only the two writer statements whose complete
    -- transition tables match that owner-created temporary scope.  Other
    -- finance mutations remain ordinary/unowned dirtiness and therefore make
    -- the later certified route fail closed.
    IF v_execution_schedule_context IS NOT NULL
       AND ((TG_TABLE_NAME='pay_advance_reservations' AND TG_OP='UPDATE')
         OR (TG_TABLE_NAME='pay_finance_case_events' AND TG_OP='INSERT')) THEN
      SELECT relation.relowner INTO v_relation_owner
      FROM pg_catalog.pg_class AS relation
      WHERE relation.oid=v_execution_schedule_context;

      IF v_relation_owner=current_user::regrole::oid
         AND EXISTS (
           SELECT 1 FROM pg_catalog.pg_class AS relation
           WHERE relation.oid=v_execution_schedule_context
             AND relation.relpersistence='t'
             AND relation.relnamespace=pg_catalog.pg_my_temp_schema()
         )
         AND (SELECT pg_catalog.array_agg(
                attribute.attname||':'||pg_catalog.format_type(attribute.atttypid,attribute.atttypmod)
                ORDER BY attribute.attnum)
              FROM pg_catalog.pg_attribute AS attribute
              WHERE attribute.attrelid=v_execution_schedule_context
                AND attribute.attnum>0 AND NOT attribute.attisdropped)
             =ARRAY[
               'contract_version:text','execution_operation_id:uuid','pay_batch_id:uuid',
               'actor_user_id:uuid','pay_batch_candidate_id:uuid','candidate_id:uuid',
               'timesheet_id:uuid','pay_batch_item_id:uuid','pay_bank_transfer_id:uuid',
               'transfer_scope_id:uuid','reservation_id:uuid','finance_case_id:uuid',
               'finance_component_id:uuid','source_workbench_session_id:uuid',
               'source_snapshot_run_id:uuid','source_session_version:bigint',
               'row_context_digest:text','created_at_utc:timestamp with time zone'
             ] THEN
        IF TG_TABLE_NAME='pay_advance_reservations' THEN
          SELECT NOT EXISTS (
              SELECT 1
              FROM new_rows AS new_row
              JOIN old_rows AS old_row ON old_row.id=new_row.id
              LEFT JOIN pg_temp._bpay_wb_unsent_execution_schedule_context_v2 AS context_row
                ON context_row.reservation_id=new_row.id
               AND context_row.pay_batch_id=new_row.pay_batch_id
               AND context_row.pay_batch_candidate_id=new_row.pay_batch_candidate_id
               AND context_row.pay_batch_item_id=new_row.pay_batch_item_id
               AND context_row.finance_case_id=new_row.finance_case_id
               AND context_row.finance_component_id IS NOT DISTINCT FROM new_row.finance_component_id
              WHERE context_row.reservation_id IS NULL
                 OR pg_catalog.upper(pg_catalog.btrim(COALESCE(old_row.status,'')))<>'RESERVED'
                 OR pg_catalog.upper(pg_catalog.btrim(COALESCE(new_row.status,'')))<>'COMMITTED'
                 OR new_row.committed_at_utc IS NULL
                 OR (pg_catalog.to_jsonb(new_row)-'status'-'committed_at_utc'-'updated_by_user_id')
                      IS DISTINCT FROM
                    (pg_catalog.to_jsonb(old_row)-'status'-'committed_at_utc'-'updated_by_user_id')
            )
            AND (SELECT pg_catalog.count(DISTINCT new_row.id) FROM new_rows AS new_row)
              =(SELECT pg_catalog.count(DISTINCT context_row.reservation_id)
                FROM pg_temp._bpay_wb_unsent_execution_schedule_context_v2 AS context_row
                WHERE context_row.reservation_id IS NOT NULL
                  AND EXISTS (SELECT 1 FROM new_rows AS new_row
                    WHERE new_row.id=context_row.reservation_id))
          INTO v_execution_schedule_exact;
        ELSE
          SELECT NOT EXISTS (
              SELECT 1
              FROM new_rows AS new_row
              LEFT JOIN pg_temp._bpay_wb_unsent_execution_schedule_context_v2 AS context_row
                ON context_row.reservation_id=new_row.reservation_id
               AND context_row.pay_batch_id=new_row.pay_batch_id
               AND context_row.finance_case_id=new_row.finance_case_id
              WHERE context_row.reservation_id IS NULL
                 OR pg_catalog.upper(pg_catalog.btrim(COALESCE(new_row.event_type,'')))
                      <>'RESERVATION_COMMITTED'
                 OR COALESCE(new_row.reason,'')<>'schedule_commit'
                 OR new_row.actor_user_id IS DISTINCT FROM context_row.actor_user_id
            )
            AND (SELECT pg_catalog.count(*) FROM new_rows)
              =(SELECT pg_catalog.count(DISTINCT context_row.reservation_id)
                FROM pg_temp._bpay_wb_unsent_execution_schedule_context_v2 AS context_row
                WHERE context_row.reservation_id IS NOT NULL
                  AND EXISTS (SELECT 1 FROM new_rows AS new_row
                    WHERE new_row.reservation_id=context_row.reservation_id))
          INTO v_execution_schedule_exact;
        END IF;

        IF v_execution_schedule_exact THEN
          SELECT COALESCE(pg_catalog.jsonb_object_agg(
                   candidate_group.candidate_id::text,
                   pg_catalog.jsonb_build_object(
                     'contract_version','EXECUTION_UNSENT_SCHEDULE_CONTEXT_V2',
                     'execution_operation_id',candidate_group.execution_operation_id,
                     'pay_batch_id',candidate_group.pay_batch_id,
                     'candidate_id',candidate_group.candidate_id,
                     'pay_batch_candidate_ids',candidate_group.pay_batch_candidate_ids,
                     'pay_batch_item_ids',candidate_group.pay_batch_item_ids,
                     'timesheet_ids',candidate_group.timesheet_ids,
                     'transfer_scope_ids',candidate_group.transfer_scope_ids,
                     'pay_bank_transfer_ids',candidate_group.pay_bank_transfer_ids,
                     'reservation_ids',candidate_group.reservation_ids,
                     'finance_case_ids',candidate_group.finance_case_ids,
                     'finance_component_ids',candidate_group.finance_component_ids,
                     'source_workbench_session_id',candidate_group.source_workbench_session_id,
                     'source_snapshot_run_id',candidate_group.source_snapshot_run_id,
                     'source_session_version',candidate_group.source_session_version,
                     'context_digest',pg_catalog.md5(
                       candidate_group.execution_operation_id::text||'|'||
                       candidate_group.pay_batch_id::text||'|'||candidate_group.candidate_id::text||'|'||
                       candidate_group.pay_batch_candidate_ids::text||'|'||
                       candidate_group.pay_batch_item_ids::text||'|'||candidate_group.timesheet_ids::text||'|'||
                       candidate_group.transfer_scope_ids::text||'|'||
                       candidate_group.pay_bank_transfer_ids::text||'|'||
                       candidate_group.reservation_ids::text||'|'||candidate_group.finance_case_ids::text||'|'||
                       candidate_group.finance_component_ids::text||'|'||
                       COALESCE(candidate_group.source_workbench_session_id::text,'')||'|'||
                       COALESCE(candidate_group.source_snapshot_run_id::text,'')||'|'||
                       COALESCE(candidate_group.source_session_version::text,'')||
                       '|EXECUTION_UNSENT_SCHEDULE_CONTEXT_V2'
                     )
                   ) ORDER BY candidate_group.candidate_id
                 ),'{}'::jsonb),pg_catalog.count(*)::integer
          INTO v_execution_schedule_contexts,v_execution_schedule_context_count
          FROM (
            SELECT context_row.candidate_id,
              pg_catalog.min(context_row.execution_operation_id::text)::uuid AS execution_operation_id,
              pg_catalog.min(context_row.pay_batch_id::text)::uuid AS pay_batch_id,
              pg_catalog.jsonb_agg(DISTINCT context_row.pay_batch_candidate_id::text
                ORDER BY context_row.pay_batch_candidate_id::text) AS pay_batch_candidate_ids,
              pg_catalog.jsonb_agg(DISTINCT context_row.pay_batch_item_id::text
                ORDER BY context_row.pay_batch_item_id::text) AS pay_batch_item_ids,
              COALESCE(pg_catalog.jsonb_agg(DISTINCT context_row.timesheet_id::text
                ORDER BY context_row.timesheet_id::text)
                FILTER (WHERE context_row.timesheet_id IS NOT NULL),'[]'::jsonb) AS timesheet_ids,
              pg_catalog.jsonb_agg(DISTINCT context_row.transfer_scope_id::text
                ORDER BY context_row.transfer_scope_id::text) AS transfer_scope_ids,
              pg_catalog.jsonb_agg(DISTINCT context_row.pay_bank_transfer_id::text
                ORDER BY context_row.pay_bank_transfer_id::text) AS pay_bank_transfer_ids,
              COALESCE(pg_catalog.jsonb_agg(DISTINCT context_row.reservation_id::text
                ORDER BY context_row.reservation_id::text)
                FILTER (WHERE context_row.reservation_id IS NOT NULL),'[]'::jsonb) AS reservation_ids,
              COALESCE(pg_catalog.jsonb_agg(DISTINCT context_row.finance_case_id::text
                ORDER BY context_row.finance_case_id::text)
                FILTER (WHERE context_row.finance_case_id IS NOT NULL),'[]'::jsonb) AS finance_case_ids,
              COALESCE(pg_catalog.jsonb_agg(DISTINCT context_row.finance_component_id::text
                ORDER BY context_row.finance_component_id::text)
                FILTER (WHERE context_row.finance_component_id IS NOT NULL),'[]'::jsonb)
                AS finance_component_ids,
              pg_catalog.min(context_row.source_workbench_session_id::text)::uuid
                AS source_workbench_session_id,
              pg_catalog.min(context_row.source_snapshot_run_id::text)::uuid
                AS source_snapshot_run_id,
              pg_catalog.min(context_row.source_session_version) AS source_session_version
            FROM pg_temp._bpay_wb_unsent_execution_schedule_context_v2 AS context_row
            WHERE context_row.candidate_id=ANY(v_candidate_ids)
            GROUP BY context_row.candidate_id
            HAVING pg_catalog.count(DISTINCT context_row.execution_operation_id)=1
               AND pg_catalog.count(DISTINCT context_row.pay_batch_id)=1
          ) AS candidate_group;

          IF v_execution_schedule_context_count<>v_impacted_candidate_count THEN
            v_execution_schedule_exact:=false;
            v_execution_schedule_contexts:='{}'::jsonb;
          ELSE
            v_scope_change_tx_token:=public.pay_workbench_scope_change_tx_token_v1();
          END IF;
        END IF;
      END IF;
    END IF;

    -- Financial DML performed by the correction page remains genuine audit
    -- evidence.  Where every impacted candidate belongs to the exact
    -- transaction-local correction context, stamp (never suppress) that
    -- causality so its durable dirty job can wait for route election.
    IF pg_catalog.to_regclass('pg_temp._bpay_wb_correction_dirty_context_v1') IS NOT NULL THEN
      EXECUTE $context$
        SELECT COALESCE(
                 pg_catalog.jsonb_object_agg(
                   context_row.candidate_id::text,
                   pg_catalog.to_jsonb(context_row)-'created_at_utc'
                   ORDER BY context_row.candidate_id
                 ),
                 '{}'::jsonb
               ),
               pg_catalog.count(*)::integer
        FROM pg_temp._bpay_wb_correction_dirty_context_v1 AS context_row
        WHERE context_row.candidate_id=ANY($1)
      $context$
      INTO v_correction_dirty_contexts,v_correction_context_count
      USING v_candidate_ids;

      IF v_correction_context_count=v_impacted_candidate_count
         AND v_correction_context_count>0 THEN
        v_scope_change_tx_token:=COALESCE(
          v_scope_change_tx_token,public.pay_workbench_scope_change_tx_token_v1());
      ELSE
        v_correction_dirty_contexts:='{}'::jsonb;
        v_scope_change_tx_token:=NULL::uuid;
      END IF;
    END IF;

    -- A candidate scope generation is global and may legitimately have gaps
    -- caused by other candidates.  Count the exact execution-owned source
    -- events per candidate/transaction instead.  The later V2 sealer compares
    -- this closed count with the per-candidate source sequence, so a committed
    -- intervening change cannot hide merely because it did not retain a
    -- candidate dirty-job row.
    IF (v_execution_overlay_exact OR v_execution_schedule_exact)
       AND v_scope_change_tx_token IS NOT NULL THEN
      CREATE TEMP TABLE IF NOT EXISTS pg_temp._bpay_wb_execution_owned_event_counter_v2(
        scope_change_tx_token uuid NOT NULL,
        candidate_id uuid NOT NULL,
        owned_source_event_count integer NOT NULL,
        PRIMARY KEY(scope_change_tx_token,candidate_id)
      ) ON COMMIT DROP;

      INSERT INTO pg_temp._bpay_wb_execution_owned_event_counter_v2 AS owned_event(
        scope_change_tx_token,candidate_id,owned_source_event_count
      )
      SELECT v_scope_change_tx_token,candidate_id,1
      FROM (
        SELECT DISTINCT candidate_id
        FROM pg_catalog.unnest(v_candidate_ids) AS candidate_input(candidate_id)
        WHERE candidate_id IS NOT NULL
      ) AS exact_candidate
      ON CONFLICT(scope_change_tx_token,candidate_id) DO UPDATE
      SET owned_source_event_count=owned_event.owned_source_event_count+1;

      IF v_execution_overlay_exact THEN
        SELECT COALESCE(pg_catalog.jsonb_object_agg(
                 context_entry.key,
                 context_entry.value||pg_catalog.jsonb_build_object(
                   'owned_source_event_count',owned_event.owned_source_event_count,
                   'owned_source_event_count_digest',pg_catalog.md5(
                     COALESCE(context_entry.value->>'context_digest','')||'|'||
                     v_scope_change_tx_token::text||'|'||context_entry.key||'|'||
                     owned_event.owned_source_event_count::text||
                     '|EXECUTION_OWNED_SOURCE_EVENT_COUNT_V1'
                   )
                 ) ORDER BY context_entry.key
               ),'{}'::jsonb)
        INTO v_execution_overlay_contexts
        FROM pg_catalog.jsonb_each(v_execution_overlay_contexts) AS context_entry(key,value)
        JOIN pg_temp._bpay_wb_execution_owned_event_counter_v2 AS owned_event
          ON owned_event.scope_change_tx_token=v_scope_change_tx_token
         AND owned_event.candidate_id=context_entry.key::uuid;
      END IF;

      IF v_execution_schedule_exact THEN
        SELECT COALESCE(pg_catalog.jsonb_object_agg(
                 context_entry.key,
                 context_entry.value||pg_catalog.jsonb_build_object(
                   'owned_source_event_count',owned_event.owned_source_event_count,
                   'owned_source_event_count_digest',pg_catalog.md5(
                     COALESCE(context_entry.value->>'context_digest','')||'|'||
                     v_scope_change_tx_token::text||'|'||context_entry.key||'|'||
                     owned_event.owned_source_event_count::text||
                     '|EXECUTION_OWNED_SOURCE_EVENT_COUNT_V1'
                   )
                 ) ORDER BY context_entry.key
               ),'{}'::jsonb)
        INTO v_execution_schedule_contexts
        FROM pg_catalog.jsonb_each(v_execution_schedule_contexts) AS context_entry(key,value)
        JOIN pg_temp._bpay_wb_execution_owned_event_counter_v2 AS owned_event
          ON owned_event.scope_change_tx_token=v_scope_change_tx_token
         AND owned_event.candidate_id=context_entry.key::uuid;
      END IF;
    END IF;

    PERFORM private.pay_workbench_scope_invalidate_v1(
      v_candidate_ids,v_timesheet_ids,v_reason,v_scope_change_tx_token,
      jsonb_strip_nulls(jsonb_build_object(
        'source_relation',TG_TABLE_NAME,'source_operation',TG_OP,
        'draft_operation_id',v_draft_operation_id,
        'draft_phase',v_draft_phase,
        'draft_context_token',v_draft_context_token,
        'correction_dirty_contexts',CASE
          WHEN v_correction_dirty_contexts<>'{}'::jsonb
            THEN v_correction_dirty_contexts ELSE NULL::jsonb END,
        'request_owned_scope_change_tx_token',CASE
          WHEN v_correction_dirty_contexts<>'{}'::jsonb
            THEN v_scope_change_tx_token ELSE NULL::uuid END,
        'correction_dirty_causal_contract_version',CASE
          WHEN v_correction_dirty_contexts<>'{}'::jsonb
            THEN 'CORRECTION_OWNED_DIRTY_CAUSAL_V1' ELSE NULL::text END,
        'execution_overlay_contexts',CASE
          WHEN v_execution_overlay_exact THEN v_execution_overlay_contexts ELSE NULL::jsonb END,
        'execution_overlay_scope_change_tx_token',CASE
          WHEN v_execution_overlay_exact THEN v_scope_change_tx_token ELSE NULL::uuid END,
        'execution_overlay_causal_contract_version',CASE
          WHEN v_execution_overlay_exact THEN 'EXECUTION_UNSENT_OVERLAY_CAUSAL_V1'
          ELSE NULL::text END,
        'execution_overlay_schedule_contexts',CASE
          WHEN v_execution_schedule_exact THEN v_execution_schedule_contexts ELSE NULL::jsonb END,
        'execution_overlay_schedule_scope_change_tx_token',CASE
          WHEN v_execution_schedule_exact THEN v_scope_change_tx_token ELSE NULL::uuid END,
        'execution_overlay_schedule_causal_contract_version',CASE
          WHEN v_execution_schedule_exact THEN 'EXECUTION_UNSENT_SCHEDULE_CAUSAL_V2'
          ELSE NULL::text END
      ))
    );
  END IF;
  RETURN NULL;
END;
$function$;

-- private.pay_workbench_financial_source_authority_v1(uuid,uuid[],uuid[],uuid[],jsonb,jsonb,text)
CREATE OR REPLACE FUNCTION private.pay_workbench_financial_source_authority_v1(p_expected_candidate_id uuid, p_owner_ids uuid[] DEFAULT ARRAY[]::uuid[], p_candidate_ids uuid[] DEFAULT ARRAY[]::uuid[], p_finance_case_ids uuid[] DEFAULT ARRAY[]::uuid[], p_frozen_source_basis_json jsonb DEFAULT '{}'::jsonb, p_frozen_component_snapshot_json jsonb DEFAULT '{}'::jsonb, p_context text DEFAULT 'FINANCE'::text)
 RETURNS TABLE(owner_ids uuid[], candidate_ids uuid[], finance_case_ids uuid[], resolved_timesheet_id uuid, resolved_candidate_id uuid, resolved_finance_case_id uuid, resolution_failure text, evidence_json jsonb)
 LANGUAGE plpgsql
 STABLE PARALLEL SAFE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_context text:=UPPER(NULLIF(BTRIM(COALESCE(p_context,'')),''));
  v_basis jsonb:=COALESCE(p_frozen_source_basis_json,'{}'::jsonb);
  v_snapshot jsonb:=COALESCE(p_frozen_component_snapshot_json,'{}'::jsonb);
  v_invalid_uuid_count integer:=0;
  v_linked_ids uuid[]:=ARRAY[]::uuid[];
  v_direct_ids uuid[]:=ARRAY[]::uuid[];
  v_carrier_ids uuid[]:=ARRAY[]::uuid[];
  v_frozen_candidate_ids uuid[]:=ARRAY[]::uuid[];
  v_frozen_case_ids uuid[]:=ARRAY[]::uuid[];
  v_frozen_owner uuid;
BEGIN
  IF p_expected_candidate_id IS NULL OR v_context NOT IN ('FINANCE','RESERVATION') THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_FINANCIAL_SOURCE_AUTHORITY_INVALID'
      USING ERRCODE='22023';
  END IF;

  IF jsonb_typeof(v_basis)<>'object' OR jsonb_typeof(v_snapshot)<>'object' THEN
    resolution_failure:=v_context||'_FROZEN_SOURCE_BASIS_INVALID';
    owner_ids:=ARRAY[]::uuid[];
    candidate_ids:=ARRAY[]::uuid[];
    finance_case_ids:=ARRAY[]::uuid[];
    evidence_json:=jsonb_build_object('context',v_context,'frozen_json_valid',false);
    RETURN NEXT;
    RETURN;
  END IF;

  WITH frozen_value(role_name,value_text) AS (
    VALUES
      ('LINKED_OWNER',NULLIF(BTRIM(v_basis->>'linked_timesheet_id'),'')),
      ('LINKED_OWNER',NULLIF(BTRIM(v_snapshot->>'linked_timesheet_id'),'')),
      ('LINKED_OWNER',NULLIF(BTRIM(v_snapshot#>>'{source_basis_json,linked_timesheet_id}'),'')),
      ('DIRECT_OWNER',NULLIF(BTRIM(v_basis->>'timesheet_id'),'')),
      ('DIRECT_OWNER',NULLIF(BTRIM(v_basis#>>'{economic_key,timesheet_id}'),'')),
      ('DIRECT_OWNER',NULLIF(BTRIM(v_snapshot->>'timesheet_id'),'')),
      ('DIRECT_OWNER',NULLIF(BTRIM(v_snapshot#>>'{source_basis_json,timesheet_id}'),'')),
      ('CARRIER_OWNER',NULLIF(BTRIM(v_basis->>'carrier_timesheet_id'),'')),
      ('CARRIER_OWNER',NULLIF(BTRIM(v_snapshot->>'carrier_timesheet_id'),'')),
      ('CARRIER_OWNER',NULLIF(BTRIM(v_snapshot#>>'{source_basis_json,carrier_timesheet_id}'),'')),
      ('CANDIDATE',NULLIF(BTRIM(v_basis->>'candidate_id'),'')),
      ('CANDIDATE',NULLIF(BTRIM(v_snapshot->>'candidate_id'),'')),
      ('CANDIDATE',NULLIF(BTRIM(v_snapshot#>>'{source_basis_json,candidate_id}'),'')),
      ('FINANCE_CASE',NULLIF(BTRIM(v_basis->>'finance_case_id'),'')),
      ('FINANCE_CASE',NULLIF(BTRIM(v_snapshot->>'finance_case_id'),'')),
      ('FINANCE_CASE',NULLIF(BTRIM(v_snapshot#>>'{source_basis_json,finance_case_id}'),''))
  ), classified AS (
    SELECT role_name,value_text,
      pg_input_is_valid(value_text,'uuid') AS is_valid
    FROM frozen_value
    WHERE value_text IS NOT NULL
  )
  SELECT
    COUNT(*) FILTER(WHERE NOT is_valid)::integer,
    COALESCE(array_agg(DISTINCT value_text::uuid ORDER BY value_text::uuid)
      FILTER(WHERE role_name='LINKED_OWNER' AND is_valid),ARRAY[]::uuid[]),
    COALESCE(array_agg(DISTINCT value_text::uuid ORDER BY value_text::uuid)
      FILTER(WHERE role_name='DIRECT_OWNER' AND is_valid),ARRAY[]::uuid[]),
    COALESCE(array_agg(DISTINCT value_text::uuid ORDER BY value_text::uuid)
      FILTER(WHERE role_name='CARRIER_OWNER' AND is_valid),ARRAY[]::uuid[]),
    COALESCE(array_agg(DISTINCT value_text::uuid ORDER BY value_text::uuid)
      FILTER(WHERE role_name='CANDIDATE' AND is_valid),ARRAY[]::uuid[]),
    COALESCE(array_agg(DISTINCT value_text::uuid ORDER BY value_text::uuid)
      FILTER(WHERE role_name='FINANCE_CASE' AND is_valid),ARRAY[]::uuid[])
  INTO v_invalid_uuid_count,v_linked_ids,v_direct_ids,v_carrier_ids,
    v_frozen_candidate_ids,v_frozen_case_ids
  FROM classified;

  -- Recovery artefacts may intentionally contain a stable linked/root member
  -- and a different carrier member. Resolve the frozen role with the existing
  -- Policy X preference instead of treating that valid pair as a conflict.
  IF cardinality(v_linked_ids)>1 OR cardinality(v_direct_ids)>1
     OR cardinality(v_carrier_ids)>1 THEN
    resolution_failure:=v_context||'_FROZEN_OWNER_CONFLICT';
  ELSIF v_invalid_uuid_count>0 THEN
    resolution_failure:=v_context||'_FROZEN_UUID_INVALID';
  ELSE
    v_frozen_owner:=COALESCE(v_linked_ids[1],v_direct_ids[1],v_carrier_ids[1]);
  END IF;

  SELECT COALESCE(array_agg(DISTINCT value ORDER BY value),ARRAY[]::uuid[])
  INTO owner_ids
  FROM unnest(COALESCE(p_owner_ids,ARRAY[]::uuid[])||
    CASE WHEN v_frozen_owner IS NULL THEN ARRAY[]::uuid[] ELSE ARRAY[v_frozen_owner] END) value
  WHERE value IS NOT NULL;

  SELECT COALESCE(array_agg(DISTINCT value ORDER BY value),ARRAY[]::uuid[])
  INTO candidate_ids
  FROM unnest(COALESCE(p_candidate_ids,ARRAY[]::uuid[])||v_frozen_candidate_ids) value
  WHERE value IS NOT NULL;

  SELECT COALESCE(array_agg(DISTINCT value ORDER BY value),ARRAY[]::uuid[])
  INTO finance_case_ids
  FROM unnest(COALESCE(p_finance_case_ids,ARRAY[]::uuid[])||v_frozen_case_ids) value
  WHERE value IS NOT NULL;

  IF resolution_failure IS NULL THEN
    IF cardinality(owner_ids)=0 THEN
      resolution_failure:=v_context||'_OWNER_UNRESOLVED';
    ELSIF cardinality(owner_ids)>1 THEN
      resolution_failure:=v_context||'_OWNER_CONFLICT';
    ELSIF cardinality(candidate_ids)<>1
       OR candidate_ids[1] IS DISTINCT FROM p_expected_candidate_id THEN
      resolution_failure:=v_context||'_CANDIDATE_CONFLICT';
    ELSIF cardinality(finance_case_ids)>1 THEN
      resolution_failure:=v_context||'_FINANCE_CASE_CONFLICT';
    END IF;
  END IF;

  resolved_timesheet_id:=CASE WHEN cardinality(owner_ids)=1 THEN owner_ids[1] END;
  resolved_candidate_id:=CASE WHEN cardinality(candidate_ids)=1 THEN candidate_ids[1] END;
  resolved_finance_case_id:=CASE WHEN cardinality(finance_case_ids)=1 THEN finance_case_ids[1] END;
  evidence_json:=jsonb_build_object(
    'context',v_context,
    'owner_ids',to_jsonb(owner_ids),
    'candidate_ids',to_jsonb(candidate_ids),
    'finance_case_ids',to_jsonb(finance_case_ids),
    'frozen_owner_role',CASE WHEN cardinality(v_linked_ids)=1 THEN 'LINKED'
      WHEN cardinality(v_direct_ids)=1 THEN 'DIRECT'
      WHEN cardinality(v_carrier_ids)=1 THEN 'CARRIER' END,
    'frozen_owner_id',v_frozen_owner,
    'resolution_failure',resolution_failure
  );
  RETURN NEXT;
END;
$function$;

-- private.pay_workbench_financial_source_authority_v2(uuid,uuid[],uuid[],uuid[],uuid[],jsonb,jsonb,jsonb,text)
CREATE OR REPLACE FUNCTION private.pay_workbench_financial_source_authority_v2(p_expected_candidate_id uuid, p_owner_ids uuid[] DEFAULT ARRAY[]::uuid[], p_candidate_ids uuid[] DEFAULT ARRAY[]::uuid[], p_finance_case_ids uuid[] DEFAULT ARRAY[]::uuid[], p_finance_component_ids uuid[] DEFAULT ARRAY[]::uuid[], p_component_key_assertions jsonb DEFAULT '[]'::jsonb, p_frozen_source_basis_json jsonb DEFAULT '{}'::jsonb, p_frozen_component_snapshot_json jsonb DEFAULT '{}'::jsonb, p_context text DEFAULT 'FINANCE'::text)
 RETURNS TABLE(owner_ids uuid[], candidate_ids uuid[], finance_case_ids uuid[], finance_component_ids uuid[], component_key_pairs text[], resolved_timesheet_id uuid, resolved_candidate_id uuid, resolved_finance_case_id uuid, resolved_finance_component_id uuid, resolved_component_key_type text, resolved_component_key_value text, resolution_failure text, evidence_json jsonb)
 LANGUAGE plpgsql
 STABLE PARALLEL SAFE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_context text:=UPPER(NULLIF(BTRIM(COALESCE(p_context,'')),''));
  v_basis jsonb:=COALESCE(p_frozen_source_basis_json,'{}'::jsonb);
  v_snapshot jsonb:=COALESCE(p_frozen_component_snapshot_json,'{}'::jsonb);
  v_key_assertions jsonb:=COALESCE(p_component_key_assertions,'[]'::jsonb);
  v_base record;
  v_invalid_component_uuid_count integer:=0;
  v_incomplete_key_count integer:=0;
BEGIN
  IF p_expected_candidate_id IS NULL OR v_context NOT IN ('FINANCE','RESERVATION')
     OR jsonb_typeof(v_basis)<>'object' OR jsonb_typeof(v_snapshot)<>'object'
     OR jsonb_typeof(v_key_assertions)<>'array' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_FINANCIAL_SOURCE_AUTHORITY_INVALID'
      USING ERRCODE='22023';
  END IF;

  SELECT * INTO STRICT v_base
  FROM private.pay_workbench_financial_source_authority_v1(
    p_expected_candidate_id,p_owner_ids,p_candidate_ids,p_finance_case_ids,
    v_basis,v_snapshot,v_context
  );

  owner_ids:=COALESCE(v_base.owner_ids,ARRAY[]::uuid[]);
  candidate_ids:=COALESCE(v_base.candidate_ids,ARRAY[]::uuid[]);
  finance_case_ids:=COALESCE(v_base.finance_case_ids,ARRAY[]::uuid[]);
  resolved_timesheet_id:=v_base.resolved_timesheet_id;
  resolved_candidate_id:=v_base.resolved_candidate_id;
  resolved_finance_case_id:=v_base.resolved_finance_case_id;
  resolution_failure:=v_base.resolution_failure;

  WITH component_value(value_text) AS (
    SELECT value::text FROM unnest(COALESCE(p_finance_component_ids,ARRAY[]::uuid[])) value
    WHERE value IS NOT NULL
    UNION ALL VALUES
      (NULLIF(BTRIM(v_basis->>'finance_component_id'),'')),
      (NULLIF(BTRIM(v_basis#>>'{component,finance_component_id}'),'')),
      (NULLIF(BTRIM(v_snapshot->>'finance_component_id'),'')),
      (NULLIF(BTRIM(v_snapshot#>>'{source_basis_json,finance_component_id}'),'')),
      (NULLIF(BTRIM(v_snapshot#>>'{component,finance_component_id}'),''))
  ), classified AS (
    SELECT value_text,pg_input_is_valid(value_text,'uuid') AS is_valid
    FROM component_value WHERE value_text IS NOT NULL
  )
  SELECT COUNT(*) FILTER(WHERE NOT is_valid)::integer,
    COALESCE(array_agg(DISTINCT value_text::uuid ORDER BY value_text::uuid)
      FILTER(WHERE is_valid),ARRAY[]::uuid[])
  INTO v_invalid_component_uuid_count,finance_component_ids
  FROM classified;

  WITH supplied_assertion AS (
    SELECT NULLIF(UPPER(BTRIM(COALESCE(assertion.value->>'key_type',
        assertion.value->>'component_key_type',''))),'') AS key_type,
      NULLIF(BTRIM(COALESCE(assertion.value->>'key_value',
        assertion.value->>'component_key_value','')),'') AS key_value
    FROM jsonb_array_elements(v_key_assertions) assertion(value)
    WHERE jsonb_typeof(assertion.value)='object'
  ), frozen_assertion(key_type,key_value) AS (
    VALUES
      (NULLIF(UPPER(BTRIM(COALESCE(v_basis->>'component_key_type',v_basis->>'key_type',''))),''),
       NULLIF(BTRIM(COALESCE(v_basis->>'component_key_value',v_basis->>'key_value','')),'')),
      (NULLIF(UPPER(BTRIM(COALESCE(v_snapshot->>'component_key_type',v_snapshot->>'key_type',''))),''),
       NULLIF(BTRIM(COALESCE(v_snapshot->>'component_key_value',v_snapshot->>'key_value','')),'')),
      (NULLIF(UPPER(BTRIM(COALESCE(v_snapshot#>>'{source_basis_json,component_key_type}',
          v_snapshot#>>'{source_basis_json,key_type}',''))),''),
       NULLIF(BTRIM(COALESCE(v_snapshot#>>'{source_basis_json,component_key_value}',
          v_snapshot#>>'{source_basis_json,key_value}','')),''))
  ), all_assertion AS (
    SELECT * FROM supplied_assertion
    UNION ALL SELECT * FROM frozen_assertion
  )
  SELECT COUNT(*) FILTER(WHERE (key_type IS NULL)<>(key_value IS NULL))::integer,
    COALESCE(array_agg(DISTINCT key_type||E'\x1f'||key_value
      ORDER BY key_type||E'\x1f'||key_value)
      FILTER(WHERE key_type IS NOT NULL AND key_value IS NOT NULL),ARRAY[]::text[])
  INTO v_incomplete_key_count,component_key_pairs
  FROM all_assertion
  WHERE key_type IS NOT NULL OR key_value IS NOT NULL;

  IF resolution_failure IS NULL THEN
    IF v_invalid_component_uuid_count>0 THEN
      resolution_failure:=CASE WHEN v_context='FINANCE' THEN 'FINANCE_COMPONENT_UUID_INVALID'
        ELSE 'RESERVATION_COMPONENT_UUID_INVALID' END;
    ELSIF cardinality(finance_component_ids)>1 THEN
      resolution_failure:=CASE WHEN v_context='FINANCE' THEN 'FINANCE_COMPONENT_CONFLICT'
        ELSE 'RESERVATION_COMPONENT_CONFLICT' END;
    ELSIF v_incomplete_key_count>0 THEN
      resolution_failure:=CASE WHEN v_context='FINANCE' THEN 'FINANCE_COMPONENT_KEY_INCOMPLETE'
        ELSE 'RESERVATION_COMPONENT_KEY_INCOMPLETE' END;
    ELSIF cardinality(component_key_pairs)>1 THEN
      resolution_failure:=CASE WHEN v_context='FINANCE' THEN 'FINANCE_COMPONENT_KEY_CONFLICT'
        ELSE 'RESERVATION_COMPONENT_KEY_CONFLICT' END;
    END IF;
  END IF;

  resolved_finance_component_id:=CASE WHEN cardinality(finance_component_ids)=1
    THEN finance_component_ids[1] END;
  resolved_component_key_type:=CASE WHEN cardinality(component_key_pairs)=1
    THEN split_part(component_key_pairs[1],E'\x1f',1) END;
  resolved_component_key_value:=CASE WHEN cardinality(component_key_pairs)=1
    THEN split_part(component_key_pairs[1],E'\x1f',2) END;

  evidence_json:=COALESCE(v_base.evidence_json,'{}'::jsonb)||jsonb_build_object(
    'authority_version',2,
    'finance_component_ids',to_jsonb(finance_component_ids),
    'component_key_pairs',to_jsonb(component_key_pairs),
    'invalid_finance_component_uuid_count',v_invalid_component_uuid_count,
    'incomplete_component_key_count',v_incomplete_key_count,
    'resolved_finance_component_id',resolved_finance_component_id,
    'resolved_component_key_type',resolved_component_key_type,
    'resolved_component_key_value',resolved_component_key_value,
    'resolution_failure',resolution_failure
  );
  RETURN NEXT;
END;
$function$;

-- private.pay_workbench_financial_source_authority_v3(uuid,uuid[],uuid[],uuid[],uuid[],jsonb,jsonb,jsonb,text)
CREATE OR REPLACE FUNCTION private.pay_workbench_financial_source_authority_v3(p_expected_candidate_id uuid, p_owner_ids uuid[] DEFAULT ARRAY[]::uuid[], p_candidate_ids uuid[] DEFAULT ARRAY[]::uuid[], p_finance_case_ids uuid[] DEFAULT ARRAY[]::uuid[], p_finance_component_ids uuid[] DEFAULT ARRAY[]::uuid[], p_component_key_assertions jsonb DEFAULT '[]'::jsonb, p_frozen_source_basis_documents jsonb DEFAULT '[]'::jsonb, p_frozen_component_snapshot_documents jsonb DEFAULT '[]'::jsonb, p_context text DEFAULT 'FINANCE'::text)
 RETURNS TABLE(owner_ids uuid[], candidate_ids uuid[], finance_case_ids uuid[], finance_component_ids uuid[], component_key_pairs text[], resolved_timesheet_id uuid, resolved_candidate_id uuid, resolved_finance_case_id uuid, resolved_finance_component_id uuid, resolved_component_key_type text, resolved_component_key_value text, resolution_failure text, evidence_json jsonb)
 LANGUAGE plpgsql
 STABLE PARALLEL SAFE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_context text:=UPPER(NULLIF(BTRIM(COALESCE(p_context,'')),''));
  v_basis_documents jsonb:=COALESCE(p_frozen_source_basis_documents,'[]'::jsonb);
  v_snapshot_documents jsonb:=COALESCE(p_frozen_component_snapshot_documents,'[]'::jsonb);
  v_key_assertions jsonb:=COALESCE(p_component_key_assertions,'[]'::jsonb);
  v_invalid_uuid_count integer:=0;
  v_invalid_component_uuid_count integer:=0;
  v_incomplete_key_count integer:=0;
  v_linked_ids uuid[]:=ARRAY[]::uuid[];
  v_direct_ids uuid[]:=ARRAY[]::uuid[];
  v_carrier_ids uuid[]:=ARRAY[]::uuid[];
  v_frozen_candidate_ids uuid[]:=ARRAY[]::uuid[];
  v_frozen_case_ids uuid[]:=ARRAY[]::uuid[];
  v_frozen_owner uuid;
  v_document_evidence jsonb:='[]'::jsonb;
BEGIN
  IF p_expected_candidate_id IS NULL
     OR v_context NOT IN ('FINANCE','RESERVATION')
     OR jsonb_typeof(v_basis_documents)<>'array'
     OR jsonb_typeof(v_snapshot_documents)<>'array'
     OR jsonb_typeof(v_key_assertions)<>'array'
     OR EXISTS(
       SELECT 1
       FROM jsonb_array_elements(v_basis_documents||v_snapshot_documents) entry(value)
       WHERE jsonb_typeof(entry.value)<>'object'
          OR NULLIF(BTRIM(COALESCE(entry.value->>'source','')),'') IS NULL
          OR jsonb_typeof(entry.value->'document')<>'object'
     ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_FINANCIAL_SOURCE_AUTHORITY_INVALID'
      USING ERRCODE='22023';
  END IF;

  WITH document AS (
    SELECT 'SOURCE_BASIS'::text AS document_kind,
      UPPER(BTRIM(entry.value->>'source')) AS source_name,
      entry.value->'document' AS body
    FROM jsonb_array_elements(v_basis_documents) entry(value)
    UNION ALL
    SELECT 'COMPONENT_SNAPSHOT',UPPER(BTRIM(entry.value->>'source')),
      entry.value->'document'
    FROM jsonb_array_elements(v_snapshot_documents) entry(value)
  ), frozen_value(role_name,value_text) AS (
    SELECT value.role_name,NULLIF(BTRIM(value.value_text),'')
    FROM document
    CROSS JOIN LATERAL (VALUES
      ('LINKED_OWNER',document.body->>'linked_timesheet_id'),
      ('LINKED_OWNER',document.body#>>'{source_basis_json,linked_timesheet_id}'),
      ('DIRECT_OWNER',document.body->>'timesheet_id'),
      ('DIRECT_OWNER',document.body#>>'{economic_key,timesheet_id}'),
      ('DIRECT_OWNER',document.body#>>'{source_basis_json,timesheet_id}'),
      ('DIRECT_OWNER',document.body#>>'{source_basis_json,economic_key,timesheet_id}'),
      ('CARRIER_OWNER',document.body->>'carrier_timesheet_id'),
      ('CARRIER_OWNER',document.body#>>'{source_basis_json,carrier_timesheet_id}'),
      ('CANDIDATE',document.body->>'candidate_id'),
      ('CANDIDATE',document.body#>>'{source_basis_json,candidate_id}'),
      ('FINANCE_CASE',document.body->>'finance_case_id'),
      ('FINANCE_CASE',document.body#>>'{source_basis_json,finance_case_id}')
    ) value(role_name,value_text)
  ), classified AS (
    SELECT role_name,value_text,pg_input_is_valid(value_text,'uuid') AS is_valid
    FROM frozen_value WHERE value_text IS NOT NULL
  )
  SELECT COUNT(*) FILTER(WHERE NOT is_valid)::integer,
    COALESCE(array_agg(DISTINCT value_text::uuid ORDER BY value_text::uuid)
      FILTER(WHERE role_name='LINKED_OWNER' AND is_valid),ARRAY[]::uuid[]),
    COALESCE(array_agg(DISTINCT value_text::uuid ORDER BY value_text::uuid)
      FILTER(WHERE role_name='DIRECT_OWNER' AND is_valid),ARRAY[]::uuid[]),
    COALESCE(array_agg(DISTINCT value_text::uuid ORDER BY value_text::uuid)
      FILTER(WHERE role_name='CARRIER_OWNER' AND is_valid),ARRAY[]::uuid[]),
    COALESCE(array_agg(DISTINCT value_text::uuid ORDER BY value_text::uuid)
      FILTER(WHERE role_name='CANDIDATE' AND is_valid),ARRAY[]::uuid[]),
    COALESCE(array_agg(DISTINCT value_text::uuid ORDER BY value_text::uuid)
      FILTER(WHERE role_name='FINANCE_CASE' AND is_valid),ARRAY[]::uuid[])
  INTO v_invalid_uuid_count,v_linked_ids,v_direct_ids,v_carrier_ids,
    v_frozen_candidate_ids,v_frozen_case_ids
  FROM classified;

  IF cardinality(v_linked_ids)>1 OR cardinality(v_direct_ids)>1
     OR cardinality(v_carrier_ids)>1 THEN
    resolution_failure:=v_context||'_FROZEN_OWNER_CONFLICT';
  ELSIF v_invalid_uuid_count>0 THEN
    resolution_failure:=v_context||'_FROZEN_UUID_INVALID';
  ELSE
    -- Preserve the existing Policy X role preference.  A stable linked/root
    -- owner may legitimately differ from a carrier member, but two assertions
    -- within the same role can never be accepted.
    v_frozen_owner:=COALESCE(v_linked_ids[1],v_direct_ids[1],v_carrier_ids[1]);
  END IF;

  SELECT COALESCE(array_agg(DISTINCT value ORDER BY value),ARRAY[]::uuid[])
  INTO owner_ids
  FROM unnest(COALESCE(p_owner_ids,ARRAY[]::uuid[])||CASE
    WHEN v_frozen_owner IS NULL THEN ARRAY[]::uuid[] ELSE ARRAY[v_frozen_owner] END) value
  WHERE value IS NOT NULL;

  SELECT COALESCE(array_agg(DISTINCT value ORDER BY value),ARRAY[]::uuid[])
  INTO candidate_ids
  FROM unnest(COALESCE(p_candidate_ids,ARRAY[]::uuid[])||v_frozen_candidate_ids) value
  WHERE value IS NOT NULL;

  SELECT COALESCE(array_agg(DISTINCT value ORDER BY value),ARRAY[]::uuid[])
  INTO finance_case_ids
  FROM unnest(COALESCE(p_finance_case_ids,ARRAY[]::uuid[])||v_frozen_case_ids) value
  WHERE value IS NOT NULL;

  IF resolution_failure IS NULL THEN
    IF cardinality(owner_ids)=0 THEN
      resolution_failure:=v_context||'_OWNER_UNRESOLVED';
    ELSIF cardinality(owner_ids)>1 THEN
      resolution_failure:=v_context||'_OWNER_CONFLICT';
    ELSIF cardinality(candidate_ids)<>1
       OR candidate_ids[1] IS DISTINCT FROM p_expected_candidate_id THEN
      resolution_failure:=v_context||'_CANDIDATE_CONFLICT';
    ELSIF cardinality(finance_case_ids)>1 THEN
      resolution_failure:=v_context||'_FINANCE_CASE_CONFLICT';
    END IF;
  END IF;

  WITH document AS (
    SELECT entry.value->'document' AS body
    FROM jsonb_array_elements(v_basis_documents||v_snapshot_documents) entry(value)
  ), component_value(value_text) AS (
    SELECT value::text
    FROM unnest(COALESCE(p_finance_component_ids,ARRAY[]::uuid[])) value
    WHERE value IS NOT NULL
    UNION ALL
    SELECT NULLIF(BTRIM(value.value_text),'')
    FROM document
    CROSS JOIN LATERAL (VALUES
      (document.body->>'finance_component_id'),
      (document.body#>>'{source_basis_json,finance_component_id}'),
      (document.body#>>'{component,finance_component_id}')
    ) value(value_text)
  ), classified AS (
    SELECT value_text,pg_input_is_valid(value_text,'uuid') AS is_valid
    FROM component_value WHERE value_text IS NOT NULL
  )
  SELECT COUNT(*) FILTER(WHERE NOT is_valid)::integer,
    COALESCE(array_agg(DISTINCT value_text::uuid ORDER BY value_text::uuid)
      FILTER(WHERE is_valid),ARRAY[]::uuid[])
  INTO v_invalid_component_uuid_count,finance_component_ids
  FROM classified;

  WITH document AS (
    SELECT entry.value->'document' AS body
    FROM jsonb_array_elements(v_basis_documents||v_snapshot_documents) entry(value)
  ), supplied_assertion AS (
    SELECT NULLIF(UPPER(BTRIM(COALESCE(value.key_type,''))),'') AS key_type,
      NULLIF(BTRIM(COALESCE(value.key_value,'')),'') AS key_value
    FROM jsonb_array_elements(v_key_assertions) assertion(value)
    CROSS JOIN LATERAL (VALUES
      (assertion.value->>'component_key_type',
       assertion.value->>'component_key_value'),
      (assertion.value->>'key_type',assertion.value->>'key_value')
    ) value(key_type,key_value)
    WHERE jsonb_typeof(assertion.value)='object'
  ), frozen_assertion AS (
    SELECT NULLIF(UPPER(BTRIM(COALESCE(value.key_type,''))),'') AS key_type,
      NULLIF(BTRIM(COALESCE(value.key_value,'')),'') AS key_value
    FROM document
    CROSS JOIN LATERAL (VALUES
      (document.body->>'component_key_type',
       document.body->>'component_key_value'),
      (document.body->>'key_type',document.body->>'key_value'),
      (document.body#>>'{economic_key,component_key_type}',
       document.body#>>'{economic_key,component_key_value}'),
      (document.body#>>'{economic_key,key_type}',
       document.body#>>'{economic_key,key_value}'),
      (document.body#>>'{source_basis_json,component_key_type}',
       document.body#>>'{source_basis_json,component_key_value}'),
      (document.body#>>'{source_basis_json,key_type}',
       document.body#>>'{source_basis_json,key_value}'),
      (document.body#>>'{source_basis_json,economic_key,component_key_type}',
       document.body#>>'{source_basis_json,economic_key,component_key_value}'),
      (document.body#>>'{source_basis_json,economic_key,key_type}',
       document.body#>>'{source_basis_json,economic_key,key_value}'),
      (document.body#>>'{component,component_key_type}',
       document.body#>>'{component,component_key_value}'),
      (document.body#>>'{component,key_type}',
       document.body#>>'{component,key_value}')
    ) value(key_type,key_value)
  ), all_assertion AS (
    SELECT * FROM supplied_assertion
    UNION ALL SELECT * FROM frozen_assertion
  )
  SELECT COUNT(*) FILTER(WHERE (key_type IS NULL)<>(key_value IS NULL))::integer,
    COALESCE(array_agg(DISTINCT key_type||E'\x1f'||key_value
      ORDER BY key_type||E'\x1f'||key_value)
      FILTER(WHERE key_type IS NOT NULL AND key_value IS NOT NULL),ARRAY[]::text[])
  INTO v_incomplete_key_count,component_key_pairs
  FROM all_assertion
  WHERE key_type IS NOT NULL OR key_value IS NOT NULL;

  IF resolution_failure IS NULL THEN
    IF v_invalid_component_uuid_count>0 THEN
      resolution_failure:=CASE WHEN v_context='FINANCE' THEN 'FINANCE_COMPONENT_UUID_INVALID'
        ELSE 'RESERVATION_COMPONENT_UUID_INVALID' END;
    ELSIF cardinality(finance_component_ids)>1 THEN
      resolution_failure:=CASE WHEN v_context='FINANCE' THEN 'FINANCE_COMPONENT_CONFLICT'
        ELSE 'RESERVATION_COMPONENT_CONFLICT' END;
    ELSIF v_incomplete_key_count>0 THEN
      resolution_failure:=CASE WHEN v_context='FINANCE' THEN 'FINANCE_COMPONENT_KEY_INCOMPLETE'
        ELSE 'RESERVATION_COMPONENT_KEY_INCOMPLETE' END;
    ELSIF cardinality(component_key_pairs)>1 THEN
      resolution_failure:=CASE WHEN v_context='FINANCE' THEN 'FINANCE_COMPONENT_KEY_CONFLICT'
        ELSE 'RESERVATION_COMPONENT_KEY_CONFLICT' END;
    END IF;
  END IF;

  resolved_timesheet_id:=CASE WHEN cardinality(owner_ids)=1 THEN owner_ids[1] END;
  resolved_candidate_id:=CASE WHEN cardinality(candidate_ids)=1 THEN candidate_ids[1] END;
  resolved_finance_case_id:=CASE WHEN cardinality(finance_case_ids)=1
    THEN finance_case_ids[1] END;
  resolved_finance_component_id:=CASE WHEN cardinality(finance_component_ids)=1
    THEN finance_component_ids[1] END;
  resolved_component_key_type:=CASE WHEN cardinality(component_key_pairs)=1
    THEN split_part(component_key_pairs[1],E'\x1f',1) END;
  resolved_component_key_value:=CASE WHEN cardinality(component_key_pairs)=1
    THEN split_part(component_key_pairs[1],E'\x1f',2) END;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'document_kind',document_kind,'source',source_name,
      'document_digest',md5(body::text)) ORDER BY document_kind,source_name,md5(body::text)),
    '[]'::jsonb)
  INTO v_document_evidence
  FROM (
    SELECT 'SOURCE_BASIS'::text document_kind,
      UPPER(BTRIM(entry.value->>'source')) source_name,entry.value->'document' body
    FROM jsonb_array_elements(v_basis_documents) entry(value)
    UNION ALL
    SELECT 'COMPONENT_SNAPSHOT',UPPER(BTRIM(entry.value->>'source')),
      entry.value->'document'
    FROM jsonb_array_elements(v_snapshot_documents) entry(value)
  ) documents;

  evidence_json:=jsonb_build_object(
    'authority_version',3,'context',v_context,
    'documents',v_document_evidence,
    'owner_ids',to_jsonb(owner_ids),'candidate_ids',to_jsonb(candidate_ids),
    'finance_case_ids',to_jsonb(finance_case_ids),
    'finance_component_ids',to_jsonb(finance_component_ids),
    'component_key_pairs',to_jsonb(component_key_pairs),
    'invalid_frozen_uuid_count',v_invalid_uuid_count,
    'invalid_finance_component_uuid_count',v_invalid_component_uuid_count,
    'incomplete_component_key_count',v_incomplete_key_count,
    'resolved_timesheet_id',resolved_timesheet_id,
    'resolved_candidate_id',resolved_candidate_id,
    'resolved_finance_case_id',resolved_finance_case_id,
    'resolved_finance_component_id',resolved_finance_component_id,
    'resolved_component_key_type',resolved_component_key_type,
    'resolved_component_key_value',resolved_component_key_value,
    'resolution_failure',resolution_failure);
  RETURN NEXT;
END;
$function$;

-- private.pay_workbench_physical_source_continuation_v1(boolean,boolean,boolean)
CREATE OR REPLACE FUNCTION private.pay_workbench_physical_source_continuation_v1(p_raw_source_has_more boolean, p_raw_source_exhausted boolean, p_another_projection_exists boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_raw_has_more boolean:=COALESCE(p_raw_source_has_more,false);
  v_raw_exhausted boolean:=COALESCE(p_raw_source_exhausted,false);
  v_another_projection boolean:=COALESCE(p_another_projection_exists,false);
BEGIN
  IF v_raw_exhausted IS DISTINCT FROM NOT v_raw_has_more THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_PHYSICAL_SOURCE_EVIDENCE_INVALID'
      USING ERRCODE='23514';
  END IF;
  RETURN v_raw_has_more OR v_another_projection;
END;
$function$;

-- private.pay_workbench_presentation_allocation_expected_v1(jsonb)
CREATE OR REPLACE FUNCTION private.pay_workbench_presentation_allocation_expected_v1(p_state_json jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_state jsonb:=COALESCE(p_state_json,'{}'::jsonb);
  v_timesheet_id text:=NULLIF(BTRIM(COALESCE(v_state->>'timesheet_id','')),'');
  v_candidate_id text:=NULLIF(BTRIM(COALESCE(v_state->>'candidate_id','')),'');
  v_pay_channel text:=UPPER(NULLIF(BTRIM(COALESCE(v_state->>'candidate_pay_method','')),''));
  v_has_whole_snooze boolean:=COALESCE((v_state->>'has_active_timesheet_snooze')::boolean,false);
  v_snooze_until_date text:=NULLIF(BTRIM(COALESCE(v_state->>'snooze_until_date','')),'');
  v_whole_snooze_indefinite boolean:=false;
  v_total_amount numeric:=ROUND(COALESCE((v_state->>'amount_ex_vat')::numeric,0),2);
  v_case_blocked boolean:=COALESCE((v_state->>'case_is_blocked')::boolean,false);
  v_has_ready boolean:=false;
  v_has_blocked boolean:=false;
  v_has_case boolean:=false;
  v_ready_for_draft boolean:=COALESCE((v_state->>'is_ready_for_draft')::boolean,false);
  v_partial_ready boolean:=false;
  v_non_resolution_block boolean:=false;
  v_blocked_segment_count integer:=GREATEST(COALESCE((v_state->>'blocked_visible_segment_count')::integer,0),0);
  v_blocked_expense_count integer:=GREATEST(COALESCE((v_state->>'blocked_expense_count')::integer,0),0);
  v_ready_segment_count integer:=GREATEST(COALESCE((v_state->>'ready_segment_count')::integer,0),0);
  v_ready_amount numeric:=ROUND(COALESCE((v_state->>'ready_section_amount_ex_vat')::numeric,0),2);
  v_case_amount numeric:=ROUND(COALESCE((v_state->>'case_resolution_section_amount_ex_vat')::numeric,0),2);
  v_case_needs_resolution boolean:=false;
  v_has_actionable_component boolean:=false;
  v_has_payee_readiness_block boolean:=COALESCE(
    (v_state->>'has_payee_readiness_block')::boolean,false);
  v_result jsonb:='[]'::jsonb;
  v_line_id text;
BEGIN
  IF jsonb_typeof(v_state)<>'object'
     OR v_timesheet_id IS NULL
     OR v_timesheet_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     OR v_candidate_id IS NULL
     OR v_candidate_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     OR v_pay_channel IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_PRESENTATION_STATE_INVALID' USING ERRCODE='22023';
  END IF;

  v_case_needs_resolution:=COALESCE(
    (v_state#>>'{case_resolution_summary_json,case_needs_resolution}')::boolean,false);
  v_whole_snooze_indefinite:=v_has_whole_snooze AND v_snooze_until_date IS NULL;
  SELECT EXISTS(
    SELECT 1
    FROM jsonb_array_elements(CASE
      WHEN jsonb_typeof(v_state->'case_components_json')='array'
        THEN v_state->'case_components_json' ELSE '[]'::jsonb END) component(value)
    WHERE COALESCE((component.value->>'requires_resolution')::boolean,false)
      AND COALESCE((component.value->>'is_actionable_resolution_row')::boolean,false)
  ) INTO v_has_actionable_component;
  -- A component-bearing zero-net target remains privately attested but does
  -- not invent a public economic row.
  v_has_ready:=v_total_amount<>0 AND (v_ready_amount<>0 OR v_ready_segment_count>0);
  v_non_resolution_block:=NOT v_has_whole_snooze AND NOT v_ready_for_draft
    AND NOT v_case_needs_resolution
    AND (NOT v_case_blocked OR v_has_payee_readiness_block)
    AND v_has_ready;
  -- An indefinite whole-timesheet snooze is completely hidden.  A dated whole
  -- snooze retains the existing BLOCKED_FOR_PAY presentation.
  v_has_blocked:=v_total_amount<>0 AND (
    (v_has_whole_snooze AND NOT v_whole_snooze_indefinite)
    OR v_blocked_segment_count>0 OR v_blocked_expense_count>0
    OR v_non_resolution_block);
  v_has_case:=NOT v_has_whole_snooze AND v_case_blocked AND v_case_needs_resolution
    AND (v_case_amount<>0 OR v_has_actionable_component)
    AND v_blocked_segment_count=0 AND NOT v_non_resolution_block;
  v_partial_ready:=NOT v_has_whole_snooze AND NOT v_case_blocked AND v_has_ready
    AND (v_blocked_segment_count>0 OR v_blocked_expense_count>0);

  IF NOT v_has_whole_snooze AND NOT v_case_blocked AND v_has_ready AND v_ready_for_draft THEN
    v_line_id:=CASE WHEN v_partial_ready THEN v_timesheet_id||':01:ready' ELSE v_timesheet_id END;
    v_result:=v_result||jsonb_build_array(jsonb_build_object(
      'candidate_id',v_candidate_id,'timesheet_id',v_timesheet_id,
      'line_identity',v_line_id,'parent_line_identity',v_timesheet_id,
      'presentation_section','READY_TO_PAY','pay_channel',v_pay_channel,
      'amount_ex_vat',ROUND(COALESCE((v_state->>'ready_section_amount_ex_vat')::numeric,0),2),
      'draftable',v_ready_for_draft,'excluded_from_allocation',false,
      'section_non_segment_amount_ex_vat',ROUND(COALESCE(
        (v_state->>'non_segment_amount_ex_vat')::numeric,0),2),
      'section_segment_rows',CASE WHEN jsonb_typeof(v_state->'ready_segment_rows_json')='array'
        THEN v_state->'ready_segment_rows_json' ELSE '[]'::jsonb END,
      'resolved_segment_rows_replace_source_total',COALESCE(
        (v_state->>'resolved_segment_rows_replace_source_total')::boolean,false)));
  END IF;

  IF v_has_case THEN
    v_result:=v_result||jsonb_build_array(jsonb_build_object(
      'candidate_id',v_candidate_id,'timesheet_id',v_timesheet_id,
      'line_identity',v_timesheet_id||':03:case','parent_line_identity',v_timesheet_id,
      'presentation_section','CASES_RESOLUTIONS','pay_channel',v_pay_channel,
      'amount_ex_vat',ROUND(COALESCE(
        (v_state->>'case_resolution_section_amount_ex_vat')::numeric,0),2),
      'draftable',false,'excluded_from_allocation',false,
      'section_non_segment_amount_ex_vat',ROUND(COALESCE(
        (v_state->>'case_resolution_section_amount_ex_vat')::numeric,0),2),
      'section_segment_rows','[]'::jsonb,
      'resolved_segment_rows_replace_source_total',false));
  END IF;

  IF v_has_blocked AND (
       v_has_whole_snooze OR v_non_resolution_block OR v_blocked_segment_count>0
       OR v_blocked_expense_count>0
     ) THEN
    v_line_id:=CASE WHEN NOT v_has_whole_snooze AND NOT v_case_blocked
      AND v_has_ready AND v_blocked_segment_count>0
      THEN v_timesheet_id||':02:blocked' ELSE v_timesheet_id END;
    v_result:=v_result||jsonb_build_array(jsonb_build_object(
      'candidate_id',v_candidate_id,'timesheet_id',v_timesheet_id,
      'line_identity',v_line_id,'parent_line_identity',v_timesheet_id,
      'presentation_section','BLOCKED_FOR_PAY','pay_channel',v_pay_channel,
      'amount_ex_vat',ROUND(CASE WHEN v_has_whole_snooze OR v_non_resolution_block
        THEN COALESCE((v_state->>'amount_ex_vat')::numeric,0)
        ELSE COALESCE((v_state->>'blocked_section_amount_ex_vat')::numeric,0) END,2),
      'draftable',CASE WHEN v_has_whole_snooze THEN v_ready_for_draft ELSE false END,
      'excluded_from_allocation',v_has_whole_snooze,
      'section_non_segment_amount_ex_vat',ROUND(CASE
        WHEN v_has_whole_snooze OR v_non_resolution_block
          THEN COALESCE((v_state->>'non_segment_amount_ex_vat')::numeric,0)
        ELSE COALESCE((v_state->>'blocked_expense_amount_ex_vat')::numeric,0) END,2),
      'section_segment_rows',CASE
        WHEN v_has_whole_snooze OR v_non_resolution_block THEN CASE
          WHEN jsonb_typeof(v_state->'visible_segment_rows_json')='array'
            THEN v_state->'visible_segment_rows_json' ELSE '[]'::jsonb END
        ELSE CASE WHEN jsonb_typeof(v_state->'blocked_visible_segment_rows_json')='array'
          THEN v_state->'blocked_visible_segment_rows_json' ELSE '[]'::jsonb END END,
      'resolved_segment_rows_replace_source_total',false));
  END IF;

  RETURN v_result;
END;
$function$;

-- private.pay_workbench_preview_effective_section_v1(text,jsonb)
CREATE OR REPLACE FUNCTION private.pay_workbench_preview_effective_section_v1(p_physical_section text, p_row_json jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO ''
AS $function$
  SELECT CASE
    WHEN COALESCE(
      pg_catalog.lower(pg_catalog.btrim(COALESCE(
        p_row_json->>'case_needs_resolution',
        p_row_json#>>'{case_resolution_summary,case_needs_resolution}',
        p_row_json#>>'{case_resolution_summary_json,case_needs_resolution}',
        ''
      ))) IN ('true', 't', '1', 'yes', 'y', 'on'),
      false
    )
    AND pg_catalog.upper(pg_catalog.btrim(COALESCE(
      p_row_json->>'resolution_family',
      p_row_json#>>'{case_resolution_summary,resolution_family}',
      p_row_json#>>'{case_resolution_summary_json,resolution_family}',
      ''
    ))) = 'TAXABLE_CHANNEL_RESTRUCTURE'
    AND COALESCE(
      pg_catalog.lower(pg_catalog.btrim(COALESCE(
        p_row_json#>>'{taxable_channel_restructure,can_apply}',
        p_row_json#>>'{case_resolution_summary,taxable_channel_restructure,can_apply}',
        p_row_json#>>'{case_resolution_summary_json,taxable_channel_restructure,can_apply}',
        ''
      ))) IN ('true', 't', '1', 'yes', 'y', 'on'),
      false
    )
      THEN 'cases_resolutions'
    WHEN COALESCE(p_row_json#>>'{selection_recovery_headroom_v1,contract_version}', '') IN (
      '1', 'PAY_WORKBENCH_SELECTION_RECOVERY_HEADROOM_V1'
    )
      THEN COALESCE(
        NULLIF(pg_catalog.btrim(p_row_json#>>'{selection_recovery_headroom_v1,effective_section}'), ''),
        NULLIF(pg_catalog.btrim(p_physical_section), ''),
        'canonical_preview_lines'
      )
    ELSE COALESCE(NULLIF(pg_catalog.btrim(p_physical_section), ''), 'canonical_preview_lines')
  END;
$function$;

-- private.pay_workbench_preview_recovery_residual_is_current_v1(text,uuid,uuid,uuid,jsonb,numeric,integer,boolean)
CREATE OR REPLACE FUNCTION private.pay_workbench_preview_recovery_residual_is_current_v1(p_row_status text, p_row_candidate_id uuid, p_expected_candidate_id uuid, p_finance_case_id uuid, p_row_json jsonb, p_current_active_reserved_ex_vat numeric, p_current_active_reservation_count integer, p_exact_active_item_overlap boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO ''
AS $function$
DECLARE
  v_source_outstanding_ex_vat numeric;
  v_embedded_active_reserved_ex_vat numeric;
  v_residual_outstanding_ex_vat numeric;
  v_nominal_due_amount_ex_vat numeric;
BEGIN
  IF pg_catalog.upper(pg_catalog.btrim(COALESCE(p_row_status, ''))) <> 'READY'
     OR p_row_candidate_id IS NULL
     OR p_expected_candidate_id IS NULL
     OR p_row_candidate_id <> p_expected_candidate_id
     OR p_finance_case_id IS NULL
     OR pg_catalog.jsonb_typeof(COALESCE(p_row_json, '{}'::jsonb)) <> 'object'
     OR pg_catalog.upper(pg_catalog.btrim(COALESCE(
          p_row_json->>'line_type',
          p_row_json#>>'{preview_contract,line_type}',
          ''
        ))) <> 'OVERPAYMENT_RECOVERY'
     OR pg_catalog.jsonb_typeof(p_row_json->'recovery_residual_contract_version') <> 'number'
     OR pg_catalog.jsonb_typeof(p_row_json->'recovery_source_outstanding_ex_vat') <> 'number'
     OR pg_catalog.jsonb_typeof(p_row_json->'recovery_active_reserved_ex_vat') <> 'number'
     OR pg_catalog.jsonb_typeof(p_row_json->'recovery_residual_outstanding_ex_vat') <> 'number'
     OR pg_catalog.jsonb_typeof(p_row_json->'nominal_due_amount_ex_vat') <> 'number'
     OR NULLIF(pg_catalog.btrim(COALESCE(p_row_json->>'finance_case_id', '')), '')
          !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     OR COALESCE(p_current_active_reservation_count, 0) < 0
     OR p_current_active_reserved_ex_vat IS NULL
     OR p_current_active_reserved_ex_vat < 0
  THEN
    RETURN false;
  END IF;

  BEGIN
    IF (p_row_json->>'recovery_residual_contract_version')::numeric <> 1
       OR (p_row_json->>'finance_case_id')::uuid <> p_finance_case_id
    THEN
      RETURN false;
    END IF;

    v_source_outstanding_ex_vat := pg_catalog.round(
      (p_row_json->>'recovery_source_outstanding_ex_vat')::numeric,
      2
    );
    v_embedded_active_reserved_ex_vat := pg_catalog.round(
      (p_row_json->>'recovery_active_reserved_ex_vat')::numeric,
      2
    );
    v_residual_outstanding_ex_vat := pg_catalog.round(
      (p_row_json->>'recovery_residual_outstanding_ex_vat')::numeric,
      2
    );
    v_nominal_due_amount_ex_vat := pg_catalog.round(
      (p_row_json->>'nominal_due_amount_ex_vat')::numeric,
      2
    );
  EXCEPTION
    WHEN invalid_text_representation OR numeric_value_out_of_range THEN
      RETURN false;
  END;

  RETURN v_source_outstanding_ex_vat > 0
    AND v_embedded_active_reserved_ex_vat >= 0
    AND v_embedded_active_reserved_ex_vat < v_source_outstanding_ex_vat
    AND v_residual_outstanding_ex_vat > 0
    AND pg_catalog.round(
      greatest(
        v_source_outstanding_ex_vat - v_embedded_active_reserved_ex_vat,
        0
      ),
      2
    ) = v_residual_outstanding_ex_vat
    AND v_residual_outstanding_ex_vat = v_nominal_due_amount_ex_vat
    AND pg_catalog.round(p_current_active_reserved_ex_vat, 2)
      = v_embedded_active_reserved_ex_vat
    AND (
      v_embedded_active_reserved_ex_vat = 0
      OR COALESCE(p_current_active_reservation_count, 0) > 0
    )
    AND (
      COALESCE(p_exact_active_item_overlap, false) IS NOT TRUE
      OR v_embedded_active_reserved_ex_vat > 0
    );
EXCEPTION
  WHEN OTHERS THEN
    -- Reader safety: malformed published data must fail closed, never make the
    -- whole Workbench page RPC fail.
    RETURN false;
END;
$function$;

-- private.pay_workbench_publish_certified_source_preview_page_v1(uuid,jsonb,jsonb)
CREATE OR REPLACE FUNCTION private.pay_workbench_publish_certified_source_preview_page_v1(p_session_id uuid, p_candidate_authorities_json jsonb, p_publication_options_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_descriptor jsonb;
  v_ordinality bigint;
  v_candidate_id uuid;
  v_result jsonb;
  v_results jsonb := '[]'::jsonb;
  v_count integer := 0;
  v_descriptor_options jsonb := '{}'::jsonb;
  v_authority_kind text;
  v_original_source_build_run_id uuid;
  v_replay_source_build_run_id uuid;
  v_original_source_publication_id uuid;
  v_source_publication_id uuid;
  v_publication_identity_write_enabled boolean := false;
  v_publication_identity_enforce_enabled boolean := false;
  v_current_source_change_seq bigint;
  v_current_dirty_generation bigint;
  v_expected_source_count integer;
  v_staged_source_count integer;
  v_expected_source_identity_digest text;
  v_staged_source_identity_digest text;
  v_progress_result jsonb := '{}'::jsonb;
BEGIN
  IF p_session_id IS NULL
     OR pg_catalog.jsonb_typeof(COALESCE(p_candidate_authorities_json, '[]'::jsonb)) <> 'array'
     OR pg_catalog.jsonb_array_length(COALESCE(p_candidate_authorities_json, '[]'::jsonb)) > 100
     OR pg_catalog.jsonb_typeof(COALESCE(p_publication_options_json, '{}'::jsonb)) <> 'object' THEN
    RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_PAGE_ARGUMENT_INVALID'
      USING ERRCODE='P0001', DETAIL=pg_catalog.jsonb_build_object(
        'code','CERTIFIED_SOURCE_PREVIEW_PAGE_ARGUMENT_INVALID'
      )::text;
  END IF;

  SELECT COALESCE(setting.banking_pay_source_publication_identity_enforce_v1_enabled,false)
  INTO v_publication_identity_enforce_enabled
  FROM public.settings_defaults AS setting
  WHERE setting.id=1;

  SELECT COALESCE(setting.banking_pay_source_publication_identity_write_v1_enabled,false),
         COALESCE(setting.banking_pay_source_publication_identity_enforce_v1_enabled,false)
  INTO v_publication_identity_write_enabled,v_publication_identity_enforce_enabled
  FROM public.settings_defaults AS setting
  WHERE setting.id=1;

  IF (
    SELECT pg_catalog.count(*)
    FROM pg_catalog.jsonb_array_elements(COALESCE(p_candidate_authorities_json,'[]'::jsonb)) AS descriptor(value)
  ) IS DISTINCT FROM (
    SELECT pg_catalog.count(DISTINCT descriptor.value->>'candidate_id')
    FROM pg_catalog.jsonb_array_elements(COALESCE(p_candidate_authorities_json,'[]'::jsonb)) AS descriptor(value)
  ) THEN
    RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_PAGE_DUPLICATE_CANDIDATE'
      USING ERRCODE='P0001',DETAIL=pg_catalog.jsonb_build_object(
        'code','CERTIFIED_SOURCE_PREVIEW_PAGE_DUPLICATE_CANDIDATE'
      )::text;
  END IF;

  FOR v_descriptor, v_ordinality IN
    SELECT descriptor.value, descriptor.ordinality
    FROM pg_catalog.jsonb_array_elements(COALESCE(p_candidate_authorities_json, '[]'::jsonb))
      WITH ORDINALITY AS descriptor(value, ordinality)
    ORDER BY descriptor.value->>'candidate_id', descriptor.ordinality
  LOOP
    IF pg_catalog.jsonb_typeof(v_descriptor) <> 'object'
       OR COALESCE(v_descriptor->>'candidate_id','')
            !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR COALESCE(v_descriptor->>'economic_build_id','')
            !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR COALESCE(v_descriptor->>'source_build_run_id','')
            !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR COALESCE(v_descriptor->>'completion_job_id','')
            !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR COALESCE(v_descriptor->>'source_change_seq','') !~ '^[0-9]{1,18}$'
       OR COALESCE(v_descriptor->>'session_version','') !~ '^[1-9][0-9]{0,18}$' THEN
      RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_PAGE_DESCRIPTOR_INVALID'
        USING ERRCODE='P0001', DETAIL=pg_catalog.jsonb_build_object(
          'code','CERTIFIED_SOURCE_PREVIEW_PAGE_DESCRIPTOR_INVALID',
          'ordinality',v_ordinality
        )::text;
    END IF;

    v_candidate_id := (v_descriptor->>'candidate_id')::uuid;

    -- The page is sorted by candidate UUID, so candidate serial locks are
    -- acquired in one deterministic global order.  This makes source-run
    -- adoption safe against full builds, clone finalisation and dirty apply.
    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        public._pay_workbench_candidate_serial_key(v_candidate_id),
        24062027
      )
    );

    PERFORM 1
    FROM public.candidates AS candidate_row
    WHERE candidate_row.id=v_candidate_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_PAGE_CANDIDATE_MISSING'
        USING ERRCODE='P0001',DETAIL=pg_catalog.jsonb_build_object(
          'code','CERTIFIED_SOURCE_PREVIEW_PAGE_CANDIDATE_MISSING',
          'candidate_id',v_candidate_id
        )::text;
    END IF;

    PERFORM 1
    FROM private.banking_pay_workbench_candidate_scope_registry AS locked_registry
    WHERE locked_registry.candidate_id=v_candidate_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_PAGE_REGISTRY_MISSING'
        USING ERRCODE='P0001',DETAIL=pg_catalog.jsonb_build_object(
          'code','CERTIFIED_SOURCE_PREVIEW_PAGE_REGISTRY_MISSING',
          'candidate_id',v_candidate_id
        )::text;
    END IF;

    v_descriptor_options := COALESCE(p_publication_options_json,'{}'::jsonb)
      || CASE WHEN pg_catalog.jsonb_typeof(v_descriptor->'publication_options_json')='object'
        THEN v_descriptor->'publication_options_json' ELSE '{}'::jsonb END;
    v_authority_kind := pg_catalog.upper(pg_catalog.btrim(COALESCE(
      v_descriptor_options->>'authority_kind','BOUNDED_FULL_SOURCE_BUILD'
    )));

    IF v_authority_kind='CERTIFIED_CANCELLATION_REVERSION' THEN
      IF COALESCE(v_descriptor_options->>'original_source_build_run_id','')
           !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
         OR COALESCE(v_descriptor_options->>'replay_source_build_run_id','')
              !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
         OR COALESCE(v_descriptor_options->>'original_source_publication_id','')
              !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
         OR COALESCE(v_descriptor_options->>'source_session_id','') IS DISTINCT FROM p_session_id::text
         OR COALESCE(v_descriptor_options->>'source_count','') !~ '^[0-9]{1,9}$'
         OR COALESCE(v_descriptor->>'source_identity_digest','') !~ '^[0-9a-f]{32}$' THEN
        RAISE EXCEPTION 'CERTIFIED_CANCELLATION_REVERSION_SOURCE_INVALID'
          USING ERRCODE='P0001',DETAIL=pg_catalog.jsonb_build_object(
            'code','CERTIFIED_CANCELLATION_REVERSION_SOURCE_INVALID',
            'candidate_id',v_candidate_id
          )::text;
      END IF;

      v_original_source_build_run_id := (v_descriptor_options->>'original_source_build_run_id')::uuid;
      v_replay_source_build_run_id := (v_descriptor_options->>'replay_source_build_run_id')::uuid;
      v_original_source_publication_id := CASE
        WHEN COALESCE(v_descriptor_options->>'original_source_publication_id','')
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN (v_descriptor_options->>'original_source_publication_id')::uuid
        ELSE NULL::uuid
      END;
      v_current_source_change_seq := (v_descriptor->>'source_change_seq')::bigint;
      v_expected_source_count := (v_descriptor_options->>'source_count')::integer;
      v_expected_source_identity_digest := v_descriptor->>'source_identity_digest';
      v_source_publication_id := CASE WHEN v_publication_identity_write_enabled
        THEN private.pay_workbench_source_publication_identity_v1(
          p_session_id,v_candidate_id,(v_descriptor->>'session_version')::bigint,
          v_current_source_change_seq,(v_descriptor->>'source_build_run_id')::uuid
        ) ELSE NULL::uuid END;

      SELECT COALESCE(change_counter.scope_change_generation,0)
      INTO v_current_dirty_generation
      FROM public.app_change_counters AS change_counter
      WHERE change_counter.entity_key='pay_candidate:'||v_candidate_id::text;

      UPDATE private.banking_pay_workbench_candidate_scope_registry AS registry
      SET current_source_change_seq=v_current_source_change_seq,
          evaluated_generation=GREATEST(COALESCE(registry.evaluated_generation,0),v_current_dirty_generation),
          current_build_id=(v_descriptor->>'economic_build_id')::uuid,
          initialisation_status='READY',
          last_evaluated_at_utc=pg_catalog.clock_timestamp(),
          failure_json='{}'::jsonb,
          updated_at_utc=pg_catalog.clock_timestamp()
      WHERE registry.candidate_id=v_candidate_id
        AND registry.dirty_generation=v_current_dirty_generation
        AND registry.current_source_change_seq <= v_current_source_change_seq;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'CERTIFIED_CANCELLATION_REVERSION_REGISTRY_STALE'
          USING ERRCODE='P0001',DETAIL=pg_catalog.jsonb_build_object(
            'code','CERTIFIED_CANCELLATION_REVERSION_REGISTRY_STALE',
            'candidate_id',v_candidate_id
          )::text;
      END IF;

      UPDATE public.banking_pay_workbench_session_candidate_state AS candidate_state
      SET source_change_seq=v_current_source_change_seq,
          session_version=(v_descriptor->>'session_version')::bigint,
          status='PENDING',
          pending_job_id=NULL,
          last_error_json='{}'::jsonb,
          updated_at_utc=pg_catalog.clock_timestamp()
      WHERE candidate_state.session_id=p_session_id
        AND candidate_state.candidate_id=v_candidate_id;

      INSERT INTO public.banking_pay_workbench_candidate_source_lines(
        session_id,candidate_id,session_version,source_change_seq,source_build_run_id,source_publication_id,
        source_ordinal,line_key,parent_line_key,split_suffix,timesheet_id,section,
        source_row_json,economic_key_json,contract_json,pay_channel_scope,
        refresh_scope_kind,status,created_at_utc,updated_at_utc
      )
      SELECT
        p_session_id,source_row.candidate_id,(v_descriptor->>'session_version')::bigint,
        v_current_source_change_seq,(v_descriptor->>'source_build_run_id')::uuid,
        v_source_publication_id,
        source_row.source_ordinal,source_row.line_key,source_row.parent_line_key,
        source_row.split_suffix,source_row.timesheet_id,source_row.section,
        source_row.source_row_json || pg_catalog.jsonb_build_object(
          'cancellation_reversion_run_id',v_descriptor->>'source_build_run_id',
          'original_source_build_run_id',v_original_source_build_run_id::text,
          'replayed_from_source_build_run_id',v_replay_source_build_run_id::text,
          'policy_x_authority_scope','PRE_DRAFT_LIVE_TRUTH'
        ),
        source_row.economic_key_json,
        COALESCE(source_row.contract_json,'{}'::jsonb) || pg_catalog.jsonb_build_object(
          'authority_kind','CERTIFIED_CANCELLATION_REVERSION',
          'cancellation_request_id',v_descriptor_options->>'cancellation_request_id',
          'cancellation_work_item_id',v_descriptor_options->>'cancellation_work_item_id',
          'financial_reversion_digest',v_descriptor_options->>'financial_reversion_digest'
        ),
        source_row.pay_channel_scope,'CANDIDATE_FULL_LIVE','DIRTY',
        pg_catalog.clock_timestamp(),pg_catalog.clock_timestamp()
      FROM public.banking_pay_workbench_candidate_source_lines AS source_row
      WHERE source_row.session_id=p_session_id
        AND source_row.candidate_id=v_candidate_id
        AND source_row.source_build_run_id=v_replay_source_build_run_id
        AND source_row.source_publication_id=v_original_source_publication_id
        AND NOT EXISTS (
          SELECT 1
          FROM public.banking_pay_workbench_candidate_source_lines AS replay_row
          WHERE replay_row.session_id=p_session_id
            AND replay_row.candidate_id=v_candidate_id
            AND replay_row.source_build_run_id=(v_descriptor->>'source_build_run_id')::uuid
            AND replay_row.source_change_seq=v_current_source_change_seq
            AND replay_row.source_publication_id IS NOT DISTINCT FROM v_source_publication_id
            AND replay_row.source_ordinal=source_row.source_ordinal
            AND replay_row.line_key=source_row.line_key
        );

      SELECT pg_catalog.count(*)::integer,
             pg_catalog.md5(COALESCE(pg_catalog.string_agg(
               public.pay_workbench_preview_section_from_line_json(staged_row.source_row_json)
                 || E'\x1f' || staged_row.line_key || E'\x1f' || staged_row.source_ordinal::text,
               E'\x1e' ORDER BY staged_row.source_ordinal,
                 public.pay_workbench_preview_section_from_line_json(staged_row.source_row_json),
                 staged_row.line_key
             ),''))
      INTO v_staged_source_count,v_staged_source_identity_digest
      FROM public.banking_pay_workbench_candidate_source_lines AS staged_row
      WHERE staged_row.session_id=p_session_id
        AND staged_row.candidate_id=v_candidate_id
        AND staged_row.source_build_run_id=(v_descriptor->>'source_build_run_id')::uuid
        AND staged_row.source_change_seq=v_current_source_change_seq
        AND staged_row.source_publication_id IS NOT DISTINCT FROM v_source_publication_id
        AND staged_row.status IN ('DIRTY','CURRENT');

      IF v_staged_source_count IS DISTINCT FROM v_expected_source_count THEN
        RAISE EXCEPTION 'CERTIFIED_CANCELLATION_REVERSION_SOURCE_COUNT_MISMATCH'
          USING ERRCODE='P0001',DETAIL=pg_catalog.jsonb_build_object(
            'code','CERTIFIED_CANCELLATION_REVERSION_SOURCE_COUNT_MISMATCH',
            'candidate_id',v_candidate_id,
            'expected_count',v_expected_source_count,
            'staged_count',v_staged_source_count
          )::text;
      END IF;
      IF v_staged_source_identity_digest IS DISTINCT FROM v_expected_source_identity_digest THEN
        RAISE EXCEPTION 'CERTIFIED_CANCELLATION_REVERSION_SOURCE_REPLAY_CONFLICT'
          USING ERRCODE='23514',DETAIL=pg_catalog.jsonb_build_object(
            'code','CERTIFIED_CANCELLATION_REVERSION_SOURCE_REPLAY_CONFLICT',
            'candidate_id',v_candidate_id,
            'expected_digest',v_expected_source_identity_digest,
            'staged_digest',v_staged_source_identity_digest
          )::text;
      END IF;

      UPDATE public.banking_pay_workbench_candidate_source_lines AS old_current
      SET status='SUPERSEDED',updated_at_utc=pg_catalog.clock_timestamp()
      WHERE old_current.session_id=p_session_id
        AND old_current.candidate_id=v_candidate_id
        AND old_current.status='CURRENT'
        AND old_current.source_build_run_id IS DISTINCT FROM (v_descriptor->>'source_build_run_id')::uuid;

      UPDATE public.banking_pay_workbench_candidate_source_lines AS staged_row
      SET status='CURRENT',updated_at_utc=pg_catalog.clock_timestamp()
      WHERE staged_row.session_id=p_session_id
        AND staged_row.candidate_id=v_candidate_id
        AND staged_row.source_build_run_id=(v_descriptor->>'source_build_run_id')::uuid
        AND staged_row.source_change_seq=v_current_source_change_seq
        AND staged_row.source_publication_id IS NOT DISTINCT FROM v_source_publication_id
        AND staged_row.status='DIRTY';
    END IF;

    v_result := private.pay_workbench_publish_certified_source_preview_v1(
      p_session_id,
      v_candidate_id,
      (v_descriptor->>'economic_build_id')::uuid,
      (v_descriptor->>'source_build_run_id')::uuid,
      (v_descriptor->>'source_change_seq')::bigint,
      (v_descriptor->>'session_version')::bigint,
      (v_descriptor->>'completion_job_id')::uuid,
      COALESCE(v_descriptor->>'refresh_scope_kind','CANDIDATE_FULL_LIVE'),
      CASE WHEN pg_catalog.jsonb_typeof(v_descriptor->'targeted_timesheet_ids')='array'
        THEN v_descriptor->'targeted_timesheet_ids' ELSE '[]'::jsonb END,
      CASE WHEN pg_catalog.jsonb_typeof(v_descriptor->'linked_timesheet_ids')='array'
        THEN v_descriptor->'linked_timesheet_ids' ELSE '[]'::jsonb END,
      v_descriptor_options
    );

    IF v_authority_kind='CERTIFIED_CANCELLATION_REVERSION' THEN
      UPDATE public.banking_pay_workbench_session_scope AS completed_scope
      SET status=CASE WHEN v_expected_source_count=0 THEN 'SOURCE_EMPTY' ELSE 'MATERIALISED' END,
          pending_job_id=NULL,dirty=false,error_json='{}'::jsonb,
          updated_at_utc=pg_catalog.clock_timestamp()
      WHERE completed_scope.session_id=p_session_id
        AND completed_scope.candidate_id=v_candidate_id
        AND completed_scope.certified_preview_publication_parity_ok IS TRUE
        AND completed_scope.certified_preview_publication_source_build_run_id
          =(v_descriptor->>'source_build_run_id')::uuid;

      UPDATE public.banking_pay_workbench_session_candidate_state AS completed_state
      SET status='READY',pending_job_id=NULL,last_error_json='{}'::jsonb,
          last_recomputed_at_utc=pg_catalog.clock_timestamp(),
          updated_at_utc=pg_catalog.clock_timestamp()
      WHERE completed_state.session_id=p_session_id
        AND completed_state.candidate_id=v_candidate_id
        AND completed_state.source_change_seq=v_current_source_change_seq;
    END IF;

    v_results := v_results || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object('candidate_id',v_candidate_id::text,'publication',v_result)
    );
    v_count := v_count + 1;
  END LOOP;

  IF v_count > 0 THEN
    v_progress_result := public.pay_workbench_session_recompute_progress_counters(
      p_session_id,true,'CERTIFIED_SOURCE_PREVIEW_PUBLICATION_PAGE_V1',true
    );
  END IF;

  RETURN pg_catalog.jsonb_build_object(
    'ok',true,
    'contract_version','CERTIFIED_SOURCE_PREVIEW_PUBLICATION_PAGE_V1',
    'session_id',p_session_id::text,
    'candidate_count',v_count,
    'candidate_results',v_results,
    'progress',v_progress_result
  );
END;
$function$;

-- private.pay_workbench_publish_certified_source_preview_v1(uuid,uuid,uuid,uuid,bigint,bigint,uuid,text,jsonb,jsonb,jsonb)
CREATE OR REPLACE FUNCTION private.pay_workbench_publish_certified_source_preview_v1(p_session_id uuid, p_candidate_id uuid, p_economic_build_id uuid, p_source_build_run_id uuid, p_source_change_seq bigint, p_session_version bigint, p_completion_job_id uuid, p_refresh_scope_kind text, p_targeted_timesheet_ids jsonb DEFAULT '[]'::jsonb, p_linked_timesheet_ids jsonb DEFAULT '[]'::jsonb, p_publication_options_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_job public.banking_pay_workbench_jobs%ROWTYPE;
  v_cancellation_work_item public.pay_payment_correction_work_items%ROWTYPE;
  v_build private.banking_pay_workbench_economic_builds%ROWTYPE;
  v_session public.banking_pay_workbench_sessions%ROWTYPE;
  v_scope public.banking_pay_workbench_session_scope%ROWTYPE;
  v_registry private.banking_pay_workbench_candidate_scope_registry%ROWTYPE;
  v_candidate_state public.banking_pay_workbench_session_candidate_state%ROWTYPE;
  v_authority_kind text := UPPER(BTRIM(COALESCE(
    p_publication_options_json->>'authority_kind',
    'BOUNDED_FULL_SOURCE_BUILD'
  )));
  v_invocation_kind text := UPPER(BTRIM(COALESCE(
    p_publication_options_json->>'invocation_kind',
    'AUTO'
  )));
  v_refresh_scope_kind text := UPPER(BTRIM(COALESCE(p_refresh_scope_kind, 'CANDIDATE_FULL_LIVE')));
  v_source_count integer := 0;
  v_source_digest text := NULL;
  v_source_identity_digest text := NULL;
  v_preview_count integer := 0;
  v_preview_identity_digest text := NULL;
  v_selectable_count integer := 0;
  v_context_count integer := 0;
  v_selected_count integer := 0;
  v_upserted_count integer := 0;
  v_retired_count integer := 0;
  v_source_minus_preview integer := 0;
  v_preview_minus_source integer := 0;
  v_live_source_change_seq bigint := 0;
  v_scope_ordinal bigint := 0;
  v_explicit_selection boolean := false;
  v_selected_ids jsonb := '[]'::jsonb;
  v_section_counts jsonb := '{}'::jsonb;
  v_attestation jsonb := '{}'::jsonb;
  v_unknown_option_count integer := 0;
  v_invalid_scope_id_count integer := 0;
  v_unmatched_target_id_count integer := 0;
  v_row_contract_error_count integer := 0;
  v_already_current boolean := false;
  v_contract_version integer := CASE
    WHEN COALESCE(p_publication_options_json->>'contract_version','1') ~ '^[123]$'
      THEN (COALESCE(p_publication_options_json->>'contract_version','1'))::integer
    ELSE -1
  END;
  v_final_state text := UPPER(BTRIM(COALESCE(p_publication_options_json->>'final_state','READY')));
  v_certification_version text := NULLIF(BTRIM(COALESCE(p_publication_options_json->>'certification_version','')),'');
  v_certification_digest text := NULLIF(BTRIM(COALESCE(p_publication_options_json->>'certification_digest','')),'');
  v_projection_run public.banking_pay_workbench_candidate_delta_projection_runs%ROWTYPE;
  v_admission_seal_version integer := NULL::integer;
  v_admission_seal_digest text := NULL::text;
  v_projection_fingerprint text := NULL::text;
  v_original_economic_build_id uuid := NULL::uuid;
  v_original_source_build_run_id uuid := NULL::uuid;
  v_source_session_id uuid := NULL::uuid;
  v_clone_fence jsonb := '{}'::jsonb;
  v_min_public_ordinal bigint := NULL::bigint;
  v_max_public_ordinal bigint := NULL::bigint;
  v_semantic_proof jsonb := '{}'::jsonb;
  v_semantic_candidate_proof jsonb := '{}'::jsonb;
  v_semantic_ready boolean := false;
  v_semantic_proof_digest text := NULL::text;
  v_selection_recovery_overlay jsonb := '{}'::jsonb;
  v_ordinary_positive_selectable_count integer := 0;
  v_ordinary_positive_amount numeric := 0;
  v_recognised_deduction_count integer := 0;
  v_recognised_deduction_amount numeric := 0;
  v_usable_same_candidate_headroom numeric := 0;
  v_candidate_ready_amount numeric := 0;
  v_invalid_selectable_row_count integer := 0;
  v_cancellation_request_id uuid := NULL::uuid;
  v_cancellation_operation_id uuid := NULL::uuid;
  v_cancellation_work_item_id uuid := NULL::uuid;
  v_cancellation_reversion_run_id uuid := NULL::uuid;
  v_financial_reversion_digest text := NULL::text;
  v_source_publication_id uuid := NULL::uuid;
  v_publication_identity_write_enabled boolean := false;
  v_publication_identity_enforce_enabled boolean := false;
  v_selection_intent_identity_enabled boolean := false;
  v_cancellation_route text := UPPER(BTRIM(COALESCE(
    p_publication_options_json->>'cancellation_route','PRE_BANK_CANCEL'
  )));
BEGIN
  SELECT COALESCE(setting.banking_pay_source_publication_identity_write_v1_enabled,false),
         COALESCE(setting.banking_pay_source_publication_identity_enforce_v1_enabled,false),
         COALESCE(setting.banking_pay_selection_intent_identity_v1_enabled,false)
  INTO v_publication_identity_write_enabled,v_publication_identity_enforce_enabled,
       v_selection_intent_identity_enabled
  FROM public.settings_defaults AS setting
  WHERE setting.id=1;

  IF p_session_id IS NULL OR p_candidate_id IS NULL OR p_economic_build_id IS NULL
     OR p_source_build_run_id IS NULL OR p_completion_job_id IS NULL THEN
    RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_BUILD_AUTHORITY_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'CERTIFIED_SOURCE_PREVIEW_BUILD_AUTHORITY_MISMATCH')::text;
  END IF;

  IF p_source_change_seq IS NULL OR p_source_change_seq < 0
     OR p_session_version IS NULL OR p_session_version <= 0 THEN
    RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_BUILD_AUTHORITY_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'CERTIFIED_SOURCE_PREVIEW_BUILD_AUTHORITY_MISMATCH',
              'reason', 'INVALID_VERSION_OR_SEQUENCE'
            )::text;
  END IF;

  IF jsonb_typeof(COALESCE(p_publication_options_json, '{}'::jsonb)) <> 'object'
     OR jsonb_typeof(COALESCE(p_targeted_timesheet_ids, '[]'::jsonb)) <> 'array'
     OR jsonb_typeof(COALESCE(p_linked_timesheet_ids, '[]'::jsonb)) <> 'array' THEN
    RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_BUILD_AUTHORITY_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'CERTIFIED_SOURCE_PREVIEW_BUILD_AUTHORITY_MISMATCH',
              'reason', 'JSON_ARGUMENT_SHAPE_INVALID'
            )::text;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_unknown_option_count
  FROM jsonb_object_keys(COALESCE(p_publication_options_json, '{}'::jsonb)) AS option_key(key)
  WHERE option_key.key NOT IN (
    'contract_version','authority_kind','invocation_kind','final_state',
    'certification_version','certification_digest','post_clone_action','post_clone_job_id',
    'source_session_id','original_economic_build_id','original_source_build_run_id','clone_job_id',
    'original_source_publication_id',
    'projection_run_id','admission_seal_version','admission_seal_digest',
    'projection_fingerprint','accepted_baseline_build_id',
    'semantic_contract_version','semantic_proof_digest','original_semantic_proof_digest',
    'cancellation_request_id','cancellation_operation_id','cancellation_work_item_id',
    'pay_batch_id','cancellation_reversion_run_id','financial_reversion_digest','source_count',
    'cancellation_route','replay_source_build_run_id'
  );

  IF v_unknown_option_count > 0 OR v_contract_version NOT IN (1,2,3)
     OR (
       v_contract_version=1
       AND (
         EXISTS (
           SELECT 1 FROM jsonb_object_keys(COALESCE(p_publication_options_json,'{}'::jsonb)) AS v1_key(key)
           WHERE v1_key.key NOT IN ('authority_kind','invocation_kind','contract_version')
         )
         OR v_authority_kind <> 'BOUNDED_FULL_SOURCE_BUILD'
         OR v_invocation_kind NOT IN ('AUTO','INITIAL_COMPLETION','DUPLICATE_REPLAY_REPAIR')
       )
     )
     OR (
       v_contract_version=2
       AND (
         v_authority_kind NOT IN ('CERTIFIED_CLONE','TARGETED_DELTA')
         OR v_final_state NOT IN ('READY','SOURCE_EMPTY','PENDING_DELTA')
         OR v_invocation_kind NOT IN ('CLONE_OWNER_FINALISE','DELTA_FINALISE')
       )
     )
     OR (
       v_contract_version=3
       AND (
         COALESCE(p_publication_options_json->>'semantic_contract_version','')
           IS DISTINCT FROM 'READY_TO_PAY_SEMANTIC_V2'
         OR v_authority_kind NOT IN (
           'BOUNDED_FULL_SOURCE_BUILD','CERTIFIED_CLONE','TARGETED_DELTA',
           'CERTIFIED_CANCELLATION_REVERSION'
         )
         OR v_final_state NOT IN ('READY','SOURCE_EMPTY','PENDING_DELTA')
         OR (
           (v_authority_kind='BOUNDED_FULL_SOURCE_BUILD'
             AND v_invocation_kind NOT IN ('AUTO','INITIAL_COMPLETION','DUPLICATE_REPLAY_REPAIR'))
           OR (v_authority_kind='CERTIFIED_CLONE'
             AND v_invocation_kind<>'CLONE_OWNER_FINALISE')
           OR (v_authority_kind='TARGETED_DELTA'
             AND v_invocation_kind<>'DELTA_FINALISE')
           OR (v_authority_kind='CERTIFIED_CANCELLATION_REVERSION'
             AND v_invocation_kind<>'CANCELLATION_REVERSION_FINALISE')
         )
       )
     ) THEN
    RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_BUILD_AUTHORITY_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'CERTIFIED_SOURCE_PREVIEW_BUILD_AUTHORITY_MISMATCH',
              'reason', 'PUBLICATION_OPTIONS_NOT_ALLOWED'
            )::text;
  END IF;

  IF v_refresh_scope_kind NOT IN ('CANDIDATE_FULL_LIVE', 'TARGETED_TIMESHEETS') THEN
    RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_SCOPE_MISSING'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'CERTIFIED_SOURCE_PREVIEW_SCOPE_MISSING',
              'reason', 'REFRESH_SCOPE_KIND_INVALID'
            )::text;
  END IF;

  -- Canonical lock order: owning job/work item -> candidate -> registry ->
  -- build -> session -> scope -> candidate state -> source -> preview.
  IF v_contract_version=3 AND v_authority_kind='CERTIFIED_CANCELLATION_REVERSION' THEN
    IF COALESCE(p_publication_options_json->>'cancellation_request_id','')
         !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR COALESCE(p_publication_options_json->>'cancellation_operation_id','')
         !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR v_cancellation_route NOT IN ('PRE_BANK_CANCEL','DRAFT_OVERLAY_FAST')
       OR (
         v_cancellation_route='PRE_BANK_CANCEL'
         AND COALESCE(p_publication_options_json->>'cancellation_work_item_id','')
               IS DISTINCT FROM p_completion_job_id::text
       )
       OR (
         v_cancellation_route='DRAFT_OVERLAY_FAST'
         AND p_completion_job_id::text
               IS DISTINCT FROM COALESCE(p_publication_options_json->>'cancellation_operation_id','')
       )
       OR COALESCE(p_publication_options_json->>'pay_batch_id','')
         !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR COALESCE(p_publication_options_json->>'cancellation_reversion_run_id','')
         IS DISTINCT FROM p_source_build_run_id::text
       OR NULLIF(BTRIM(COALESCE(p_publication_options_json->>'financial_reversion_digest','')),'') IS NULL THEN
      RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_BUILD_AUTHORITY_MISMATCH'
        USING ERRCODE='P0001',DETAIL=jsonb_build_object(
          'code','CERTIFIED_SOURCE_PREVIEW_BUILD_AUTHORITY_MISMATCH',
          'reason','CANCELLATION_OPTIONS_INCOMPLETE'
        )::text;
    END IF;

    v_cancellation_request_id := (p_publication_options_json->>'cancellation_request_id')::uuid;
    v_cancellation_operation_id := (p_publication_options_json->>'cancellation_operation_id')::uuid;
    v_cancellation_work_item_id := CASE WHEN v_cancellation_route='PRE_BANK_CANCEL'
      THEN p_completion_job_id ELSE NULL::uuid END;
    v_cancellation_reversion_run_id := p_source_build_run_id;
    v_financial_reversion_digest := p_publication_options_json->>'financial_reversion_digest';

    IF v_cancellation_route='PRE_BANK_CANCEL' THEN
      SELECT work_item.*
      INTO v_cancellation_work_item
      FROM public.pay_payment_correction_work_items AS work_item
      WHERE work_item.id=p_completion_job_id
      FOR UPDATE;

      IF NOT FOUND
         OR v_cancellation_work_item.correction_request_id IS DISTINCT FROM v_cancellation_request_id
         OR v_cancellation_work_item.candidate_id IS DISTINCT FROM p_candidate_id
         OR v_cancellation_work_item.pay_batch_id::text
              IS DISTINCT FROM p_publication_options_json->>'pay_batch_id'
         OR UPPER(BTRIM(COALESCE(v_cancellation_work_item.work_kind,''))) <> 'PRE_BANK_CANCEL'
         OR UPPER(BTRIM(COALESCE(v_cancellation_work_item.status,''))) <> 'APPLIED'
         OR COALESCE(v_cancellation_work_item.result_json->>'result_code','') <> 'APPLIED'
         OR NOT EXISTS (
           SELECT 1 FROM public.banking_pay_operations AS correction_operation
           WHERE correction_operation.id=v_cancellation_operation_id
             AND correction_operation.operation_type='PAYMENT_CORRECTION'
             AND correction_operation.pay_batch_id=v_cancellation_work_item.pay_batch_id
             AND correction_operation.input_json->>'correction_request_id'=v_cancellation_request_id::text
         )
         OR pg_catalog.md5((COALESCE(v_cancellation_work_item.result_json,'{}'::jsonb)
               - 'applied_at_utc' - 'processed_at_utc')::text)
              IS DISTINCT FROM v_financial_reversion_digest THEN
        RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_BUILD_AUTHORITY_MISMATCH'
          USING ERRCODE='P0001',DETAIL=jsonb_build_object(
            'code','CERTIFIED_SOURCE_PREVIEW_BUILD_AUTHORITY_MISMATCH',
            'reason','CANCELLATION_WORK_ITEM_NOT_EXACT'
          )::text;
      END IF;
    ELSE
      IF NOT EXISTS (
        SELECT 1
        FROM public.banking_pay_operations AS correction_operation
        JOIN public.pay_payment_correction_requests AS correction_request
          ON correction_request.id=v_cancellation_request_id
         AND correction_request.pay_batch_id=correction_operation.pay_batch_id
        JOIN public.pay_payment_correction_request_candidates AS request_candidate
          ON request_candidate.correction_request_id=correction_request.id
        JOIN public.pay_batch_candidates AS batch_candidate
          ON batch_candidate.id=request_candidate.pay_batch_candidate_id
         AND batch_candidate.pay_batch_id=correction_request.pay_batch_id
         AND batch_candidate.candidate_id=p_candidate_id
        WHERE correction_operation.id=v_cancellation_operation_id
          AND correction_operation.operation_type='PAYMENT_CORRECTION'
          AND correction_operation.pay_batch_id::text
                =p_publication_options_json->>'pay_batch_id'
          AND correction_operation.input_json->>'correction_request_id'
                =v_cancellation_request_id::text
          AND COALESCE(correction_request.plan_json->>'requested_action',
                       correction_request.selection_json->>'requested_action')='DRAFT_CANCEL'
          AND NOT EXISTS (
            SELECT 1
            FROM public.pay_payment_correction_work_items AS financial_work
            WHERE financial_work.correction_request_id=correction_request.id
          )
      ) THEN
        RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_BUILD_AUTHORITY_MISMATCH'
          USING ERRCODE='P0001',DETAIL=jsonb_build_object(
            'code','CERTIFIED_SOURCE_PREVIEW_BUILD_AUTHORITY_MISMATCH',
            'reason','DRAFT_OVERLAY_CANCELLATION_AUTHORITY_NOT_EXACT'
          )::text;
      END IF;
    END IF;
  ELSE
    SELECT job_row.*
    INTO v_job
    FROM public.banking_pay_workbench_jobs AS job_row
    WHERE job_row.id = p_completion_job_id
    FOR UPDATE;

    IF NOT FOUND
       OR v_job.session_id IS DISTINCT FROM p_session_id
       OR (
         v_job.candidate_id IS DISTINCT FROM p_candidate_id
         AND NOT (v_contract_version IN (2,3) AND v_authority_kind='CERTIFIED_CLONE' AND v_job.candidate_id IS NULL)
       )
       OR UPPER(BTRIM(COALESCE(v_job.status, ''))) NOT IN ('RUNNING', 'SUCCEEDED')
       OR (
         v_contract_version IN (1,3) AND v_authority_kind='BOUNDED_FULL_SOURCE_BUILD'
         AND (
           v_job.economic_build_id IS DISTINCT FROM p_economic_build_id
           OR UPPER(BTRIM(COALESCE(v_job.job_type, ''))) NOT IN (
             'WORKBENCH_CANDIDATE_SOURCE_BUILD','WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK',
             'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE','CANDIDATE_SOURCE_BUILD',
             'CANDIDATE_SOURCE_BUILD_CHUNK','SOURCE_BUILD','SOURCE_BUILD_PAGE'
           )
         )
       )
       OR (
         v_contract_version IN (2,3) AND v_authority_kind='CERTIFIED_CLONE'
         AND (
           UPPER(BTRIM(COALESCE(v_job.job_type,''))) NOT IN (
             'WORKBENCH_SESSION_CLONE_REBASE','SESSION_CLONE_REBASE','CLONE_REBASE',
             'WORKBENCH_CANDIDATE_DIRTY_APPLY'
           )
           OR COALESCE(p_publication_options_json->>'clone_job_id','') IS DISTINCT FROM p_completion_job_id::text
         )
       )
       OR (
         v_contract_version IN (2,3) AND v_authority_kind='TARGETED_DELTA'
         AND (
           UPPER(BTRIM(COALESCE(v_job.job_type,''))) NOT IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH','CANDIDATE_DELTA_REFRESH','DELTA_REFRESH')
           OR COALESCE(p_publication_options_json->>'projection_run_id','') IS DISTINCT FROM p_source_build_run_id::text
         )
       ) THEN
      RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_BUILD_AUTHORITY_MISMATCH'
        USING ERRCODE = 'P0001', DETAIL = jsonb_build_object(
          'code', 'CERTIFIED_SOURCE_PREVIEW_BUILD_AUTHORITY_MISMATCH',
          'reason', 'COMPLETION_JOB_NOT_EXACT'
        )::text;
    END IF;
  END IF;

  PERFORM 1
  FROM public.candidates AS candidate_row
  WHERE candidate_row.id = p_candidate_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_SCOPE_MISSING'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'CERTIFIED_SOURCE_PREVIEW_SCOPE_MISSING')::text;
  END IF;

  SELECT registry_row.*
  INTO v_registry
  FROM private.banking_pay_workbench_candidate_scope_registry AS registry_row
  WHERE registry_row.candidate_id = p_candidate_id
  FOR UPDATE;

  IF NOT FOUND OR v_registry.current_source_change_seq IS DISTINCT FROM p_source_change_seq THEN
    RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_SOURCE_SEQUENCE_STALE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'CERTIFIED_SOURCE_PREVIEW_SOURCE_SEQUENCE_STALE')::text;
  END IF;

  IF v_contract_version IN (2,3) AND v_authority_kind='CERTIFIED_CLONE' THEN
    IF COALESCE(p_publication_options_json->>'source_session_id','')
         !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR COALESCE(p_publication_options_json->>'original_economic_build_id','')
         !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR COALESCE(p_publication_options_json->>'original_source_build_run_id','')
         !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR v_certification_version IS NULL OR v_certification_digest IS NULL THEN
      RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_BUILD_AUTHORITY_MISMATCH'
        USING ERRCODE='P0001',DETAIL=jsonb_build_object('code','CERTIFIED_SOURCE_PREVIEW_BUILD_AUTHORITY_MISMATCH','reason','CLONE_OPTIONS_INCOMPLETE')::text;
    END IF;
    v_source_session_id := (p_publication_options_json->>'source_session_id')::uuid;
    v_original_economic_build_id := (p_publication_options_json->>'original_economic_build_id')::uuid;
    v_original_source_build_run_id := (p_publication_options_json->>'original_source_build_run_id')::uuid;
  ELSIF v_contract_version IN (2,3) AND v_authority_kind='TARGETED_DELTA' THEN
    v_admission_seal_version := CASE WHEN COALESCE(p_publication_options_json->>'admission_seal_version','') ~ '^\d+$' THEN (p_publication_options_json->>'admission_seal_version')::integer END;
    v_admission_seal_digest := NULLIF(BTRIM(COALESCE(p_publication_options_json->>'admission_seal_digest','')),'');
    v_projection_fingerprint := NULLIF(BTRIM(COALESCE(p_publication_options_json->>'projection_fingerprint','')),'');
    IF v_admission_seal_version IS NULL OR v_admission_seal_digest IS NULL
       OR v_projection_fingerprint IS NULL
       OR COALESCE(p_publication_options_json->>'accepted_baseline_build_id','') IS DISTINCT FROM p_economic_build_id::text THEN
      RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_BUILD_AUTHORITY_MISMATCH'
        USING ERRCODE='P0001',DETAIL=jsonb_build_object('code','CERTIFIED_SOURCE_PREVIEW_BUILD_AUTHORITY_MISMATCH','reason','DELTA_OPTIONS_INCOMPLETE')::text;
    END IF;
  ELSIF v_contract_version=3 AND v_authority_kind='CERTIFIED_CANCELLATION_REVERSION' THEN
    IF COALESCE(p_publication_options_json->>'source_session_id','')
         !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR COALESCE(p_publication_options_json->>'original_economic_build_id','')
         !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR COALESCE(p_publication_options_json->>'original_source_build_run_id','')
         !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR NULLIF(BTRIM(COALESCE(p_publication_options_json->>'original_semantic_proof_digest','')),'') IS NULL THEN
      RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_BUILD_AUTHORITY_MISMATCH'
        USING ERRCODE='P0001',DETAIL=jsonb_build_object(
          'code','CERTIFIED_SOURCE_PREVIEW_BUILD_AUTHORITY_MISMATCH',
          'reason','CANCELLATION_LINEAGE_INCOMPLETE'
        )::text;
    END IF;
    v_source_session_id := (p_publication_options_json->>'source_session_id')::uuid;
    v_original_economic_build_id := (p_publication_options_json->>'original_economic_build_id')::uuid;
    v_original_source_build_run_id := (p_publication_options_json->>'original_source_build_run_id')::uuid;
  END IF;

  SELECT build_row.*
  INTO v_build
  FROM private.banking_pay_workbench_economic_builds AS build_row
  WHERE build_row.id = p_economic_build_id
  FOR UPDATE;

  IF NOT FOUND
     OR v_build.candidate_id IS DISTINCT FROM p_candidate_id
     OR (
       v_contract_version IN (1,3) AND v_authority_kind='BOUNDED_FULL_SOURCE_BUILD'
       AND (
         v_build.session_id IS DISTINCT FROM p_session_id
         OR v_build.session_version IS DISTINCT FROM p_session_version
         OR v_build.source_build_run_id IS DISTINCT FROM p_source_build_run_id
         OR v_build.source_change_seq IS DISTINCT FROM p_source_change_seq
         OR v_build.source_job_id IS DISTINCT FROM p_completion_job_id
       )
     )
     OR (
       v_contract_version IN (2,3) AND v_authority_kind='CERTIFIED_CLONE'
       AND (
         v_original_economic_build_id IS DISTINCT FROM p_economic_build_id
         OR v_build.source_build_run_id IS DISTINCT FROM v_original_source_build_run_id
         OR v_build.session_id IS DISTINCT FROM v_source_session_id
       )
     )
     OR (
       v_contract_version IN (2,3) AND v_authority_kind='TARGETED_DELTA'
       AND v_build.id IS DISTINCT FROM p_economic_build_id
     )
     OR (
       v_contract_version=3 AND v_authority_kind='CERTIFIED_CANCELLATION_REVERSION'
       AND (
         v_build.id IS DISTINCT FROM v_original_economic_build_id
         OR v_build.source_build_run_id IS DISTINCT FROM v_original_source_build_run_id
         OR v_build.session_id IS DISTINCT FROM v_source_session_id
         OR v_build.candidate_id IS DISTINCT FROM p_candidate_id
       )
     ) THEN
    RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_BUILD_AUTHORITY_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'CERTIFIED_SOURCE_PREVIEW_BUILD_AUTHORITY_MISMATCH')::text;
  END IF;

  IF UPPER(BTRIM(COALESCE(v_build.status, ''))) <> 'COMPLETE'
     OR UPPER(BTRIM(COALESCE(v_build.private_stage, ''))) <> 'COMPLETE'
     OR v_build.completed_at_utc IS NULL
     OR v_build.reconciled_at_utc IS NULL
     OR v_build.failed_at_utc IS NOT NULL
     OR COALESCE(v_build.failure_json, '{}'::jsonb) <> '{}'::jsonb
     OR v_build.dependency_closure_sealed_at_utc IS NULL
     OR v_build.dependency_edge_stream_complete IS NOT TRUE
     OR v_build.edge_tag_stream_complete IS NOT TRUE
     OR NULLIF(BTRIM(COALESCE(v_build.sealed_fingerprint_digest, '')), '') IS NULL
     OR NULLIF(BTRIM(COALESCE(v_build.canonical_digest, '')), '') IS NULL
     OR jsonb_typeof(COALESCE(v_build.attestation_json, '{}'::jsonb)) <> 'object'
     OR COALESCE(v_build.attestation_json, '{}'::jsonb) = '{}'::jsonb
     OR LOWER(BTRIM(COALESCE(v_build.attestation_json->>'effect_plan_sealed', 'false')))
          NOT IN ('true', 't', '1', 'yes', 'y', 'on')
     OR NULLIF(BTRIM(COALESCE(v_build.attestation_json->>'effect_plan_digest', '')), '') IS NULL
     OR NULLIF(BTRIM(COALESCE(v_build.attestation_json->>'observed_finance_effect_digest', '')), '') IS NULL THEN
    RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_BUILD_NOT_COMPLETE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'CERTIFIED_SOURCE_PREVIEW_BUILD_NOT_COMPLETE')::text;
  END IF;

  SELECT session_row.*
  INTO v_session
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id
  FOR UPDATE;

  IF NOT FOUND
     OR UPPER(BTRIM(COALESCE(v_session.status, ''))) <> 'OPEN'
     OR v_session.discarded_at_utc IS NOT NULL
     OR v_session.version IS DISTINCT FROM p_session_version
     OR (v_contract_version IN (1,3) AND v_authority_kind='BOUNDED_FULL_SOURCE_BUILD'
       AND v_session.source_snapshot_run_id IS DISTINCT FROM v_build.source_snapshot_run_id) THEN
    RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_SESSION_STALE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'CERTIFIED_SOURCE_PREVIEW_SESSION_STALE')::text;
  END IF;

  SELECT scope_row.*
  INTO v_scope
  FROM public.banking_pay_workbench_session_scope AS scope_row
  WHERE scope_row.session_id = p_session_id
    AND scope_row.candidate_id = p_candidate_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_SCOPE_MISSING'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'CERTIFIED_SOURCE_PREVIEW_SCOPE_MISSING')::text;
  END IF;
  v_scope_ordinal := v_scope.scope_ordinal;

  SELECT candidate_state.*
  INTO v_candidate_state
  FROM public.banking_pay_workbench_session_candidate_state AS candidate_state
  WHERE candidate_state.session_id = p_session_id
    AND candidate_state.candidate_id = p_candidate_id
  FOR UPDATE;

  IF NOT FOUND
     OR v_candidate_state.session_version IS DISTINCT FROM p_session_version
     OR v_candidate_state.source_change_seq IS DISTINCT FROM p_source_change_seq THEN
    RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_SOURCE_SEQUENCE_STALE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'CERTIFIED_SOURCE_PREVIEW_SOURCE_SEQUENCE_STALE')::text;
  END IF;

  SELECT COALESCE(change_counter.seq, 0)
  INTO v_live_source_change_seq
  FROM public.app_change_counters AS change_counter
  WHERE change_counter.entity_key = 'pay_candidate:' || p_candidate_id::text;

  IF v_live_source_change_seq IS DISTINCT FROM p_source_change_seq THEN
    RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_SOURCE_SEQUENCE_STALE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'CERTIFIED_SOURCE_PREVIEW_SOURCE_SEQUENCE_STALE')::text;
  END IF;

  IF v_contract_version IN (2,3) AND v_authority_kind='TARGETED_DELTA' THEN
    SELECT projection_row.*
    INTO v_projection_run
    FROM public.banking_pay_workbench_candidate_delta_projection_runs AS projection_row
    WHERE projection_row.id=p_source_build_run_id
      AND projection_row.session_id=p_session_id
      AND projection_row.candidate_id=p_candidate_id
    FOR UPDATE;

    IF NOT FOUND
       OR v_projection_run.session_version IS DISTINCT FROM p_session_version
       OR v_projection_run.source_change_seq IS DISTINCT FROM p_source_change_seq
       OR v_projection_run.admission_seal_version IS DISTINCT FROM v_admission_seal_version
       OR v_projection_run.admission_seal_digest IS DISTINCT FROM v_admission_seal_digest
       OR v_projection_run.projection_fingerprint IS DISTINCT FROM v_projection_fingerprint
       OR v_projection_run.admission_seal_json->>'accepted_build_id' IS DISTINCT FROM p_economic_build_id::text
       OR UPPER(BTRIM(COALESCE(v_projection_run.status,''))) NOT IN ('RUNNING','PROCESSING','WRITING','READY') THEN
      RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_BUILD_AUTHORITY_MISMATCH'
        USING ERRCODE='P0001',DETAIL=jsonb_build_object('code','CERTIFIED_SOURCE_PREVIEW_BUILD_AUTHORITY_MISMATCH','reason','DELTA_AUTHORITY_NOT_EXACT')::text;
    END IF;
  ELSIF v_contract_version IN (2,3) AND v_authority_kind='CERTIFIED_CLONE' THEN
    v_clone_fence := private.pay_workbench_session_clone_bounded_certification_v1(
      v_source_session_id,
      p_session_id,
      p_candidate_id,
      jsonb_build_object(
        'certification_version',v_certification_version,
        'expected_certification_digest',v_certification_digest,
        'expected_economic_build_id',p_economic_build_id,
        'expected_source_build_run_id',v_original_source_build_run_id,
        'final_fence',true,
        'caller_holds_candidate_and_session_locks',true
      )
    );

    IF COALESCE((v_clone_fence->>'clone_eligible')::boolean,false) IS NOT TRUE
       OR COALESCE(v_clone_fence->>'certification_digest','') IS DISTINCT FROM v_certification_digest
       OR COALESCE(v_clone_fence->>'economic_build_id',v_clone_fence->>'original_economic_build_id','') IS DISTINCT FROM p_economic_build_id::text
       OR COALESCE(v_clone_fence->>'source_build_run_id',v_clone_fence->>'original_source_build_run_id','') IS DISTINCT FROM v_original_source_build_run_id::text THEN
      RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_BUILD_AUTHORITY_MISMATCH'
        USING ERRCODE='P0001',DETAIL=jsonb_build_object('code','CERTIFIED_SOURCE_PREVIEW_BUILD_AUTHORITY_MISMATCH','reason','CLONE_CERTIFICATION_STALE')::text;
    END IF;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM private.banking_pay_workbench_economic_builds AS newer_build
    WHERE newer_build.session_id = p_session_id
      AND newer_build.candidate_id = p_candidate_id
      AND newer_build.session_version = p_session_version
      AND newer_build.id <> p_economic_build_id
      AND newer_build.obsolete_at_utc IS NULL
      AND newer_build.failed_at_utc IS NULL
      AND (
        newer_build.source_change_seq > p_source_change_seq
        OR (
          newer_build.source_change_seq = p_source_change_seq
          AND newer_build.created_at_utc > v_build.created_at_utc
          AND UPPER(BTRIM(COALESCE(newer_build.status, ''))) NOT IN ('FAILED', 'OBSOLETE')
        )
      )
  ) OR EXISTS (
    SELECT 1
    FROM public.banking_pay_workbench_jobs AS newer_job
    WHERE newer_job.session_id = p_session_id
      AND newer_job.candidate_id = p_candidate_id
      AND newer_job.id <> p_completion_job_id
      AND UPPER(BTRIM(COALESCE(newer_job.status, ''))) IN ('QUEUED', 'RUNNING')
      AND UPPER(BTRIM(COALESCE(newer_job.job_type, ''))) IN (
        'WORKBENCH_CANDIDATE_SOURCE_BUILD',
        'WORKBENCH_CANDIDATE_SOURCE_BUILD_CHUNK',
        'WORKBENCH_CANDIDATE_SOURCE_BUILD_PAGE',
        'CANDIDATE_SOURCE_BUILD',
        'CANDIDATE_SOURCE_BUILD_CHUNK',
        'SOURCE_BUILD',
        'SOURCE_BUILD_PAGE'
      )
      AND (
        COALESCE(newer_job.payload_json->>'source_change_seq', '') !~ '^[0-9]{1,18}$'
        OR (newer_job.payload_json->>'source_change_seq')::bigint >= p_source_change_seq
      )
  ) OR EXISTS (
    SELECT 1
    FROM public.banking_pay_workbench_candidate_delta_projection_runs AS projection_run
    WHERE projection_run.session_id = p_session_id
      AND (v_authority_kind<>'TARGETED_DELTA' OR projection_run.id IS DISTINCT FROM p_source_build_run_id)
      AND projection_run.candidate_id = p_candidate_id
      AND projection_run.session_version = p_session_version
      AND projection_run.source_change_seq >= p_source_change_seq
      AND UPPER(BTRIM(COALESCE(projection_run.status, ''))) IN (
        'PENDING', 'QUEUED', 'RUNNING', 'PROCESSING', 'WRITING', 'READY'
      )
  ) THEN
    RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_NEWER_WORK_PRESENT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'CERTIFIED_SOURCE_PREVIEW_NEWER_WORK_PRESENT')::text;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_invalid_scope_id_count
  FROM (
    SELECT value
    FROM jsonb_array_elements_text(COALESCE(p_targeted_timesheet_ids, '[]'::jsonb))
    UNION ALL
    SELECT value
    FROM jsonb_array_elements_text(COALESCE(p_linked_timesheet_ids, '[]'::jsonb))
  ) AS scope_value
  WHERE NULLIF(BTRIM(scope_value.value), '') IS NULL
     OR scope_value.value !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

  IF v_invalid_scope_id_count > 0 THEN
    RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_SCOPE_MISSING'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'CERTIFIED_SOURCE_PREVIEW_SCOPE_MISSING',
              'reason', 'INVALID_TIMESHEET_SCOPE_ID'
            )::text;
  END IF;

  IF v_refresh_scope_kind = 'TARGETED_TIMESHEETS' THEN
    WITH requested_ids AS (
      SELECT DISTINCT value::uuid AS timesheet_id
      FROM (
        SELECT value FROM jsonb_array_elements_text(COALESCE(p_targeted_timesheet_ids, '[]'::jsonb))
        UNION ALL
        SELECT value FROM jsonb_array_elements_text(COALESCE(p_linked_timesheet_ids, '[]'::jsonb))
      ) AS raw_ids
    )
    SELECT COUNT(*)::integer
    INTO v_unmatched_target_id_count
    FROM requested_ids
    WHERE NOT EXISTS (
      SELECT 1
      FROM private.banking_pay_workbench_economic_build_scope AS build_scope
      WHERE build_scope.build_id = p_economic_build_id
        AND build_scope.timesheet_id = requested_ids.timesheet_id
    )
      AND NOT EXISTS (
        SELECT 1
        FROM public.banking_pay_workbench_candidate_source_lines AS source_scope
        WHERE source_scope.session_id = p_session_id
          AND source_scope.candidate_id = p_candidate_id
          AND source_scope.session_version = p_session_version
          AND source_scope.source_build_run_id = p_source_build_run_id
          AND source_scope.source_change_seq = p_source_change_seq
          AND source_scope.status = 'CURRENT'
          AND source_scope.timesheet_id = requested_ids.timesheet_id
      );

    IF v_unmatched_target_id_count > 0
       OR (
         jsonb_array_length(COALESCE(p_targeted_timesheet_ids, '[]'::jsonb))
         + jsonb_array_length(COALESCE(p_linked_timesheet_ids, '[]'::jsonb))
       ) = 0 THEN
      RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_SCOPE_MISSING'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'CERTIFIED_SOURCE_PREVIEW_SCOPE_MISSING',
                'reason', 'TARGETED_SCOPE_NOT_CERTIFIED'
              )::text;
    END IF;
  END IF;

  IF v_publication_identity_write_enabled OR v_publication_identity_enforce_enabled THEN
    v_source_publication_id := private.pay_workbench_source_publication_identity_v1(
      p_session_id,p_candidate_id,p_session_version,p_source_change_seq,p_source_build_run_id
    );

    IF NOT EXISTS (
      SELECT 1
      FROM public.banking_pay_workbench_candidate_source_lines AS publication_probe
      WHERE publication_probe.session_id=p_session_id
        AND publication_probe.candidate_id=p_candidate_id
        AND publication_probe.session_version=p_session_version
        AND publication_probe.source_change_seq=p_source_change_seq
        AND publication_probe.source_build_run_id=p_source_build_run_id
        AND publication_probe.source_publication_id=v_source_publication_id
        AND publication_probe.status='CURRENT'
    ) THEN
      IF v_publication_identity_enforce_enabled THEN
        RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_SOURCE_PUBLICATION_MISSING'
          USING ERRCODE='P0001',DETAIL=jsonb_build_object(
            'code','CERTIFIED_SOURCE_PREVIEW_SOURCE_PUBLICATION_MISSING',
            'source_publication_id',v_source_publication_id
          )::text;
      END IF;
      v_source_publication_id := NULL::uuid;
    END IF;
  END IF;

  PERFORM source_lock.id
  FROM public.banking_pay_workbench_candidate_source_lines AS source_lock
  WHERE source_lock.session_id = p_session_id
    AND source_lock.candidate_id = p_candidate_id
    AND source_lock.session_version = p_session_version
    AND source_lock.status = 'CURRENT'
    AND (v_source_publication_id IS NULL OR source_lock.source_publication_id=v_source_publication_id)
  ORDER BY source_lock.source_ordinal, source_lock.id
  FOR UPDATE;

  IF EXISTS (
    SELECT 1
    FROM public.banking_pay_workbench_candidate_source_lines AS ambiguous_source
    WHERE ambiguous_source.session_id = p_session_id
      AND ambiguous_source.candidate_id = p_candidate_id
      AND ambiguous_source.session_version = p_session_version
      AND ambiguous_source.status = 'CURRENT'
      AND (
        ambiguous_source.source_change_seq IS DISTINCT FROM p_source_change_seq
        OR (
          v_source_publication_id IS NULL
          AND ambiguous_source.source_build_run_id IS DISTINCT FROM p_source_build_run_id
        )
        OR (
          v_source_publication_id IS NOT NULL
          AND ambiguous_source.source_publication_id IS DISTINCT FROM v_source_publication_id
        )
      )
  ) THEN
    RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_SOURCE_SET_AMBIGUOUS'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'CERTIFIED_SOURCE_PREVIEW_SOURCE_SET_AMBIGUOUS')::text;
  END IF;

  SELECT COUNT(*)::integer,
         md5(COALESCE(string_agg(md5(source_row.source_row_json::text), '' ORDER BY source_row.source_ordinal), ''))
  INTO v_source_count, v_source_digest
  FROM public.banking_pay_workbench_candidate_source_lines AS source_row
  WHERE source_row.session_id = p_session_id
    AND source_row.candidate_id = p_candidate_id
    AND source_row.session_version = p_session_version
    AND source_row.source_change_seq = p_source_change_seq
    AND (
      (v_source_publication_id IS NOT NULL AND source_row.source_publication_id=v_source_publication_id)
      OR (v_source_publication_id IS NULL AND source_row.source_build_run_id=p_source_build_run_id)
    )
    AND source_row.status = 'CURRENT';

  IF v_contract_version IN (1,3) AND v_authority_kind='BOUNDED_FULL_SOURCE_BUILD'
     AND (
       v_source_count IS DISTINCT FROM v_build.canonical_count
       OR v_source_digest IS DISTINCT FROM v_build.canonical_digest) THEN
    RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_SOURCE_DIGEST_MISMATCH'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'CERTIFIED_SOURCE_PREVIEW_SOURCE_DIGEST_MISMATCH')::text;
  END IF;

  IF v_contract_version IN (2,3) AND v_authority_kind='TARGETED_DELTA' AND v_final_state='PENDING_DELTA' THEN
    v_attestation:=jsonb_build_object(
      'attestation_version',CASE WHEN v_contract_version=3 THEN 'CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V3' ELSE 'CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V2' END,
      'contract_version',v_contract_version,
      'semantic_contract_version',CASE WHEN v_contract_version=3 THEN 'READY_TO_PAY_SEMANTIC_V2' ELSE NULL END,
      'authority_kind',v_authority_kind,
      'final_state','PENDING_DELTA',
      'parity_complete',false,
      'economic_build_id',p_economic_build_id,
      'source_build_run_id',p_source_build_run_id,
      'source_publication_id',v_source_publication_id,
      'source_change_seq',p_source_change_seq,
      'session_version',p_session_version,
      'completion_job_id',p_completion_job_id,
      'certification_version',v_certification_version,
      'certification_digest',v_certification_digest,
      'attested_at_utc',v_now,
      'policy_x_authority_scope','PRE_DRAFT_LIVE_TRUTH'
    );

    UPDATE public.banking_pay_workbench_session_scope AS pending_scope
    SET certified_preview_publication_required=true,
        certified_preview_publication_parity_ok=false,
        certified_preview_publication_session_version=p_session_version,
        certified_preview_publication_source_change_seq=p_source_change_seq,
        certified_preview_publication_source_build_run_id=p_source_build_run_id,
        certified_preview_publication_source_publication_id=v_source_publication_id,
        certified_preview_publication_attestation_json=v_attestation,
        certified_preview_publication_attested_at_utc=NULL,
        status='DELTA_REFRESH_PENDING',
        dirty=true,
        updated_at_utc=v_now
    WHERE pending_scope.id=v_scope.id;

    RETURN jsonb_build_object(
      'ok',true,
      'contract_version',v_contract_version,
      'authority_kind',v_authority_kind,
      'final_state','PENDING_DELTA',
      'parity_complete',false,
      'source_row_count',v_source_count,
      'session_id',p_session_id,
      'candidate_id',p_candidate_id,
      'source_change_seq',p_source_change_seq,
      'session_version',p_session_version,
      'retry_safe',true,
      'policy_x_authority_scope','PRE_DRAFT_LIVE_TRUTH'
    );
  END IF;

  IF v_contract_version IN (2,3) AND ((v_final_state='SOURCE_EMPTY' AND v_source_count<>0)
     OR (v_final_state='READY' AND v_source_count=0)) THEN
    RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_PARITY_FAILED'
      USING ERRCODE='P0001',DETAIL=jsonb_build_object('code','CERTIFIED_SOURCE_PREVIEW_PARITY_FAILED','reason','FINAL_STATE_SOURCE_COUNT_MISMATCH')::text;
  END IF;

  PERFORM preview_lock.id
  FROM public.banking_pay_workbench_preview_rows AS preview_lock
  WHERE preview_lock.session_id = p_session_id
    AND preview_lock.candidate_id = p_candidate_id
  ORDER BY preview_lock.section, preview_lock.row_key, preview_lock.id
  FOR UPDATE;

  DROP TABLE IF EXISTS pg_temp._bpay_certified_preview_publish_rows;
  CREATE TEMPORARY TABLE pg_temp._bpay_certified_preview_publish_rows ON COMMIT DROP AS
  SELECT
    source_row.id AS source_line_id,
    source_row.source_ordinal,
    source_row.line_key,
    source_row.timesheet_id,
    source_row.source_row_json,
    source_row.economic_key_json,
    public.pay_workbench_preview_section_from_line_json(source_row.source_row_json) AS resolved_section,
    public.pay_workbench_preview_line_contract_ok(
      source_row.source_row_json,
      source_row.economic_key_json,
      public.pay_workbench_preview_section_from_line_json(source_row.source_row_json)
    ) AS preview_contract_json,
    LOWER(BTRIM(COALESCE(source_row.source_row_json->>'selection_allowed', 'false')))
      IN ('true', 't', '1', 'yes', 'y', 'on') AS is_selectable,
    NULLIF(BTRIM(COALESCE(source_row.economic_key_json->>'key_type', '')), '') AS key_type,
    NULLIF(BTRIM(COALESCE(source_row.economic_key_json->>'key_value', '')), '') AS key_value,
    encode(
      extensions.digest(
        convert_to(
          jsonb_build_object(
            'identity_version', 'CERTIFIED_PREVIEW_SELECTION_IDENTITY_V1',
            'section', public.pay_workbench_preview_section_from_line_json(source_row.source_row_json),
            'row_key', source_row.line_key,
            'timesheet_id', source_row.timesheet_id,
            'economic_key_json', source_row.economic_key_json,
            'line_type', source_row.source_row_json->>'line_type',
            'finance_component_id', source_row.source_row_json->>'finance_component_id',
            'amount_ex_vat', source_row.source_row_json->>'amount_ex_vat',
            'pay_channel', source_row.source_row_json->>'pay_channel',
            'route_type', source_row.source_row_json->>'route_type',
            'draftable', source_row.source_row_json->>'draftable',
            'readiness_state', source_row.source_row_json->>'readiness_state',
            'selection_allowed', source_row.source_row_json->>'selection_allowed'
          )::text,
          'UTF8'
        ),
        'sha256'
      ),
      'hex'
    ) AS selection_identity_digest,
    existing_preview.id AS existing_preview_id,
    existing_preview.selected AS existing_selected,
    existing_preview.selection_state AS existing_selection_state,
    existing_preview.status AS existing_status,
    existing_preview.row_json->>'selection_identity_digest' AS existing_selection_identity_digest,
    existing_preview.row_json->>'selection_user_override' AS existing_selection_user_override,
    existing_preview.row_json->>'selection_origin' AS existing_selection_origin,
    existing_preview.row_json->>'selection_user_override_at_utc' AS existing_selection_user_override_at_utc
  FROM public.banking_pay_workbench_candidate_source_lines AS source_row
  LEFT JOIN public.banking_pay_workbench_preview_rows AS existing_preview
    ON existing_preview.session_id = p_session_id
   AND existing_preview.candidate_id = p_candidate_id
   AND existing_preview.section = public.pay_workbench_preview_section_from_line_json(source_row.source_row_json)
   AND existing_preview.row_key = source_row.line_key
  WHERE source_row.session_id = p_session_id
    AND source_row.candidate_id = p_candidate_id
    AND source_row.session_version = p_session_version
    AND source_row.source_change_seq = p_source_change_seq
    AND (
      (v_source_publication_id IS NOT NULL AND source_row.source_publication_id=v_source_publication_id)
      OR (v_source_publication_id IS NULL AND source_row.source_build_run_id=p_source_build_run_id)
    )
    AND source_row.status = 'CURRENT';

  IF EXISTS (
    SELECT 1
    FROM pg_temp._bpay_certified_preview_publish_rows AS prepared_row
    WHERE NULLIF(BTRIM(COALESCE(prepared_row.resolved_section, '')), '') IS NULL
       OR prepared_row.resolved_section IN ('internal_only', 'INTERNAL_ONLY')
       OR NULLIF(BTRIM(COALESCE(prepared_row.line_key, '')), '') IS NULL
  ) OR EXISTS (
    SELECT 1
    FROM pg_temp._bpay_certified_preview_publish_rows
    GROUP BY resolved_section, line_key
    HAVING COUNT(*) <> 1
  ) OR EXISTS (
    SELECT 1
    FROM pg_temp._bpay_certified_preview_publish_rows
    GROUP BY source_ordinal
    HAVING COUNT(*) <> 1
  ) THEN
    RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_ROW_CONTRACT_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'CERTIFIED_SOURCE_PREVIEW_ROW_CONTRACT_INVALID')::text;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_row_contract_error_count
  FROM pg_temp._bpay_certified_preview_publish_rows AS prepared_row
  WHERE (
    prepared_row.is_selectable IS TRUE
    AND (
      prepared_row.key_type IS NULL
      OR prepared_row.key_value IS NULL
      OR LOWER(BTRIM(COALESCE(
        public.pay_workbench_preview_line_contract_ok(
          prepared_row.source_row_json,
          prepared_row.economic_key_json,
          prepared_row.resolved_section
        )->>'ok',
        'false'
      ))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
    )
  ) OR (
    prepared_row.is_selectable IS NOT TRUE
    AND NOT (
      -- Retain the installed V1 allowance for non-economic timesheet context
      -- rows.  Other blocked/case economic rows must also satisfy the existing
      -- canonical display-row contract before this exact allow-list applies.
      (
        UPPER(BTRIM(COALESCE(prepared_row.source_row_json->>'line_type', ''))) = 'TIMESHEET_PAYMENT'
        OR LOWER(BTRIM(COALESCE(
          public.pay_workbench_preview_line_contract_ok(
            prepared_row.source_row_json,
            prepared_row.economic_key_json,
            prepared_row.resolved_section
          )->>'ok',
          'false'
        ))) IN ('true', 't', '1', 'yes', 'y', 'on')
      )
      AND UPPER(BTRIM(COALESCE(prepared_row.source_row_json->>'presentation_section', ''))) IN (
        'READY_TO_PAY', 'CASES_RESOLUTIONS', 'BLOCKED_FOR_PAY', 'SNOOZED'
      )
      AND UPPER(BTRIM(COALESCE(prepared_row.source_row_json->>'presentation_role', ''))) IN (
        'PARENT', 'CONTEXT', 'DETAIL', 'SUMMARY'
      )
      AND UPPER(BTRIM(COALESCE(prepared_row.source_row_json->>'readiness_state', ''))) IN (
        'READY_TO_PAY', 'BLOCKED', 'BLOCKED_FOR_PAY', 'SNOOZED',
        'CASE_RESOLUTION', 'CASES_RESOLUTIONS'
      )
    )
  );

  IF v_row_contract_error_count > 0 THEN
    RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_ROW_CONTRACT_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'CERTIFIED_SOURCE_PREVIEW_ROW_CONTRACT_INVALID',
              'row_count', v_row_contract_error_count
            )::text;
  END IF;

  v_explicit_selection := v_session.server_selected_preview_row_ids_provided IS TRUE;
  IF jsonb_typeof(COALESCE(v_session.server_selected_preview_row_ids, '[]'::jsonb)) <> 'array' THEN
    RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_SELECTION_INTENT_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'CERTIFIED_SOURCE_PREVIEW_SELECTION_INTENT_INVALID')::text;
  END IF;

  DROP TABLE IF EXISTS pg_temp._bpay_certified_preview_ready_rows;
  CREATE TEMPORARY TABLE pg_temp._bpay_certified_preview_ready_rows ON COMMIT DROP AS
  SELECT
    prepared_row.*,
    CASE
      WHEN prepared_row.is_selectable IS NOT TRUE THEN false
      WHEN v_contract_version = 3 THEN
        CASE
          WHEN prepared_row.existing_preview_id IS NOT NULL
           AND (prepared_row.existing_status = 'READY' OR v_selection_intent_identity_enabled)
           AND prepared_row.existing_selection_identity_digest = prepared_row.selection_identity_digest
           AND UPPER(BTRIM(COALESCE(prepared_row.existing_selection_user_override, ''))) = 'UNSELECTED'
            THEN false
          WHEN prepared_row.existing_preview_id IS NOT NULL
           AND (prepared_row.existing_status = 'READY' OR v_selection_intent_identity_enabled)
           AND prepared_row.existing_selection_identity_digest = prepared_row.selection_identity_digest
           AND UPPER(BTRIM(COALESCE(prepared_row.existing_selection_user_override, ''))) = 'SELECTED'
            THEN true
          WHEN prepared_row.existing_preview_id IS NOT NULL
           AND prepared_row.existing_status = 'READY'
           AND prepared_row.existing_selection_identity_digest = prepared_row.selection_identity_digest
           AND UPPER(BTRIM(COALESCE(prepared_row.existing_selection_state, ''))) IN ('SELECTED', 'UNSELECTED')
            THEN prepared_row.existing_selected IS TRUE
          ELSE true
        END
      WHEN v_explicit_selection THEN
        prepared_row.existing_preview_id IS NOT NULL
        AND prepared_row.existing_status = 'READY'
        AND prepared_row.existing_selection_identity_digest = prepared_row.selection_identity_digest
        AND EXISTS (
          SELECT 1
          FROM jsonb_array_elements_text(v_session.server_selected_preview_row_ids) AS selected_id(value)
          WHERE selected_id.value = prepared_row.existing_preview_id::text
        )
      WHEN prepared_row.existing_preview_id IS NULL THEN true
      WHEN prepared_row.existing_status = 'READY'
        AND prepared_row.existing_selection_identity_digest = prepared_row.selection_identity_digest
        AND UPPER(BTRIM(COALESCE(prepared_row.existing_selection_state, ''))) IN ('SELECTED', 'UNSELECTED')
        THEN prepared_row.existing_selected IS TRUE
      ELSE false
    END AS effective_selected,
    CASE
      WHEN prepared_row.is_selectable IS NOT TRUE THEN 'NOT_SELECTABLE'
      WHEN v_contract_version = 3 THEN
        CASE
          WHEN prepared_row.existing_preview_id IS NOT NULL
           AND (prepared_row.existing_status = 'READY' OR v_selection_intent_identity_enabled)
           AND prepared_row.existing_selection_identity_digest = prepared_row.selection_identity_digest
           AND UPPER(BTRIM(COALESCE(prepared_row.existing_selection_user_override, ''))) = 'UNSELECTED'
            THEN 'UNSELECTED'
          WHEN prepared_row.existing_preview_id IS NOT NULL
           AND (prepared_row.existing_status = 'READY' OR v_selection_intent_identity_enabled)
           AND prepared_row.existing_selection_identity_digest = prepared_row.selection_identity_digest
           AND UPPER(BTRIM(COALESCE(prepared_row.existing_selection_user_override, ''))) = 'SELECTED'
            THEN 'SELECTED'
          WHEN prepared_row.existing_preview_id IS NOT NULL
           AND prepared_row.existing_status = 'READY'
           AND prepared_row.existing_selection_identity_digest = prepared_row.selection_identity_digest
           AND UPPER(BTRIM(COALESCE(prepared_row.existing_selection_state, ''))) IN ('SELECTED', 'UNSELECTED')
            THEN CASE WHEN prepared_row.existing_selected IS TRUE THEN 'SELECTED' ELSE 'UNSELECTED' END
          ELSE 'SELECTED'
        END
      WHEN v_explicit_selection THEN
        CASE
          WHEN prepared_row.existing_preview_id IS NOT NULL
           AND prepared_row.existing_status = 'READY'
           AND prepared_row.existing_selection_identity_digest = prepared_row.selection_identity_digest
           AND EXISTS (
             SELECT 1
             FROM jsonb_array_elements_text(v_session.server_selected_preview_row_ids) AS selected_id(value)
             WHERE selected_id.value = prepared_row.existing_preview_id::text
           ) THEN 'SELECTED'
          ELSE 'UNSELECTED'
        END
      WHEN prepared_row.existing_preview_id IS NULL THEN 'SELECTED'
      WHEN prepared_row.existing_status = 'READY'
        AND prepared_row.existing_selection_identity_digest = prepared_row.selection_identity_digest
        AND UPPER(BTRIM(COALESCE(prepared_row.existing_selection_state, ''))) IN ('SELECTED', 'UNSELECTED')
        THEN CASE WHEN prepared_row.existing_selected IS TRUE THEN 'SELECTED' ELSE 'UNSELECTED' END
      ELSE 'UNSELECTED'
    END AS effective_selection_state
  FROM pg_temp._bpay_certified_preview_publish_rows AS prepared_row;

  -- A lost-response/duplicate completion must be a true publication no-op once
  -- the exact certified source, public identities, selection identity and scope
  -- attestation are already current.  The checks remain read-only and occur
  -- after every source/build/sequence/contract proof above has been repeated.
  SELECT
    v_scope.certified_preview_publication_required IS TRUE
    AND v_scope.certified_preview_publication_parity_ok IS TRUE
    AND v_scope.certified_preview_publication_session_version = p_session_version
    AND v_scope.certified_preview_publication_source_change_seq = p_source_change_seq
    AND v_scope.certified_preview_publication_source_build_run_id = p_source_build_run_id
    AND v_scope.certified_preview_publication_source_publication_id IS NOT DISTINCT FROM v_source_publication_id
    AND v_scope.certified_preview_publication_attestation_json->>'economic_build_id' = p_economic_build_id::text
    AND v_scope.certified_preview_publication_attestation_json->>'completion_job_id' = p_completion_job_id::text
    AND COALESCE((v_scope.certified_preview_publication_attestation_json->>'parity_complete')::boolean, false)
    AND v_scope.certified_preview_publication_attestation_json->>'attestation_version' = CASE
      WHEN v_contract_version=1 THEN 'CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V1'
      WHEN v_contract_version=2 THEN 'CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V2'
      ELSE 'CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V3'
    END
    AND v_scope.certified_preview_publication_attestation_json->>'authority_kind'=v_authority_kind
    AND NOT EXISTS (
      SELECT 1
      FROM pg_temp._bpay_certified_preview_ready_rows AS exact_row
      WHERE exact_row.existing_preview_id IS NULL
         OR exact_row.existing_status IS DISTINCT FROM 'READY'
         OR exact_row.existing_selection_identity_digest IS DISTINCT FROM exact_row.selection_identity_digest
         OR exact_row.existing_selected IS DISTINCT FROM exact_row.effective_selected
         OR exact_row.existing_selection_state IS DISTINCT FROM exact_row.effective_selection_state
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.banking_pay_workbench_preview_rows AS current_preview
      WHERE current_preview.session_id = p_session_id
        AND current_preview.candidate_id = p_candidate_id
        AND current_preview.session_version = p_session_version
        AND current_preview.status = 'READY'
        AND NOT EXISTS (
          SELECT 1
          FROM pg_temp._bpay_certified_preview_ready_rows AS exact_row
          WHERE exact_row.resolved_section = current_preview.section
            AND exact_row.line_key = current_preview.row_key
        )
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.banking_pay_workbench_preview_rows AS current_preview
      JOIN pg_temp._bpay_certified_preview_ready_rows AS exact_row
        ON exact_row.resolved_section = current_preview.section
       AND exact_row.line_key = current_preview.row_key
      WHERE current_preview.session_id = p_session_id
        AND current_preview.candidate_id = p_candidate_id
        AND current_preview.session_version = p_session_version
        AND (
          current_preview.status IS DISTINCT FROM 'READY'
          OR current_preview.row_json->>'economic_build_id' IS DISTINCT FROM p_economic_build_id::text
          OR current_preview.row_json->>'source_build_run_id' IS DISTINCT FROM p_source_build_run_id::text
          OR current_preview.row_json->>'source_change_seq' IS DISTINCT FROM p_source_change_seq::text
          OR current_preview.row_json->>'source_line_id' IS DISTINCT FROM exact_row.source_line_id::text
          OR current_preview.row_json->>'selection_identity_digest' IS DISTINCT FROM exact_row.selection_identity_digest
          OR current_preview.row_json->'preview_contract' IS DISTINCT FROM exact_row.preview_contract_json
        )
    )
  INTO v_already_current;

  IF v_already_current IS TRUE THEN
    IF v_contract_version = 3 THEN
      v_selection_recovery_overlay := private.pay_workbench_recovery_selection_overlay_apply_v1(
        p_session_id,
        p_candidate_id,
        jsonb_build_object(
          'force_v3', true,
          'reason', 'V3_PUBLICATION_DUPLICATE_REPLAY'
        )
      );
    END IF;

    SELECT COUNT(*) FILTER (WHERE is_selectable)::integer,
           COUNT(*) FILTER (WHERE is_selectable IS NOT TRUE)::integer,
           COUNT(*) FILTER (WHERE effective_selected)::integer,
           COUNT(*)::integer
    INTO v_selectable_count, v_context_count, v_selected_count, v_preview_count
    FROM pg_temp._bpay_certified_preview_ready_rows;

    SELECT COALESCE(
      jsonb_object_agg(section_count.section, section_count.row_count ORDER BY section_count.section),
      '{}'::jsonb
    )
    INTO v_section_counts
    FROM (
      SELECT ready_row.resolved_section AS section, COUNT(*)::integer AS row_count
      FROM pg_temp._bpay_certified_preview_ready_rows AS ready_row
      GROUP BY ready_row.resolved_section
    ) AS section_count;

    RETURN jsonb_build_object(
      'ok', true,
      'parity_complete', true,
      'already_current', true,
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'economic_build_id', p_economic_build_id::text,
      'source_build_run_id', p_source_build_run_id::text,
      'source_publication_id', CASE WHEN v_source_publication_id IS NULL THEN NULL ELSE v_source_publication_id::text END,
      'source_change_seq', p_source_change_seq,
      'session_version', p_session_version,
      'source_row_count', v_preview_count,
      'preview_row_count', v_preview_count,
      'selectable_row_count', v_selectable_count,
      'context_row_count', v_context_count,
      'selected_row_count', v_selected_count,
      'upserted_row_count', 0,
      'retired_row_count', 0,
      'section_counts', v_section_counts,
      'selection_mode', CASE WHEN v_explicit_selection THEN 'EXPLICIT_INCLUDE' ELSE 'IMPLICIT_ALL' END,
      'retry_safe', true,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    );
  END IF;

  WITH upserted AS (
    INSERT INTO public.banking_pay_workbench_preview_rows (
      session_id, candidate_id, section, row_key, row_ordinal, row_json,
      timesheet_id, key_type, key_value, selected, selection_state, status,
      session_version, created_at_utc, updated_at_utc
    )
    SELECT
      p_session_id,
      p_candidate_id,
      ready_row.resolved_section,
      ready_row.line_key,
      (v_scope_ordinal * 1000000) + ready_row.source_ordinal,
      jsonb_strip_nulls(
        ready_row.source_row_json
        || jsonb_build_object(
          'published_from_certified_source', true,
          'publication_authority_kind', v_authority_kind,
          'economic_build_id', p_economic_build_id::text,
          'source_build_run_id', p_source_build_run_id::text,
          'source_change_seq', p_source_change_seq,
          'source_ordinal', ready_row.source_ordinal,
          'source_line_id', ready_row.source_line_id::text,
          'publication_job_id', p_completion_job_id::text,
          'published_at_utc', v_now::text,
          'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH',
          'selection_identity_digest', ready_row.selection_identity_digest,
          'preview_contract', ready_row.preview_contract_json,
          'selected', ready_row.effective_selected,
          'selection_state', ready_row.effective_selection_state,
          'selection_user_override', CASE
            WHEN v_contract_version = 3
             AND ready_row.existing_preview_id IS NOT NULL
             AND (ready_row.existing_status = 'READY' OR v_selection_intent_identity_enabled)
             AND ready_row.existing_selection_identity_digest = ready_row.selection_identity_digest
             AND UPPER(BTRIM(COALESCE(ready_row.existing_selection_user_override, ''))) IN ('SELECTED', 'UNSELECTED')
              THEN UPPER(BTRIM(ready_row.existing_selection_user_override))
            ELSE NULL::text
          END,
          'selection_origin', CASE
            WHEN v_contract_version = 3
             AND ready_row.existing_preview_id IS NOT NULL
             AND (ready_row.existing_status = 'READY' OR v_selection_intent_identity_enabled)
             AND ready_row.existing_selection_identity_digest = ready_row.selection_identity_digest
             AND UPPER(BTRIM(COALESCE(ready_row.existing_selection_user_override, ''))) IN ('SELECTED', 'UNSELECTED')
              THEN COALESCE(NULLIF(ready_row.existing_selection_origin, ''), 'USER_EXPLICIT_SELECTION')
            WHEN v_contract_version = 3 AND ready_row.is_selectable IS TRUE
              THEN 'SERVER_DEFAULT_NEW_READY_LINE'
            ELSE NULL::text
          END,
          'selection_user_override_at_utc', CASE
            WHEN v_contract_version = 3
             AND ready_row.existing_preview_id IS NOT NULL
             AND (ready_row.existing_status = 'READY' OR v_selection_intent_identity_enabled)
             AND ready_row.existing_selection_identity_digest = ready_row.selection_identity_digest
             AND UPPER(BTRIM(COALESCE(ready_row.existing_selection_user_override, ''))) IN ('SELECTED', 'UNSELECTED')
              THEN ready_row.existing_selection_user_override_at_utc
            ELSE NULL::text
          END
        )
      ),
      ready_row.timesheet_id,
      CASE WHEN ready_row.is_selectable THEN ready_row.key_type ELSE NULL::text END,
      CASE WHEN ready_row.is_selectable THEN ready_row.key_value ELSE NULL::text END,
      ready_row.effective_selected,
      ready_row.effective_selection_state,
      'READY',
      p_session_version,
      v_now,
      v_now
    FROM pg_temp._bpay_certified_preview_ready_rows AS ready_row
    ON CONFLICT (session_id, section, candidate_id, row_key)
    DO UPDATE SET
      row_ordinal = EXCLUDED.row_ordinal,
      row_json = EXCLUDED.row_json,
      timesheet_id = EXCLUDED.timesheet_id,
      key_type = EXCLUDED.key_type,
      key_value = EXCLUDED.key_value,
      selected = EXCLUDED.selected,
      selection_state = EXCLUDED.selection_state,
      status = EXCLUDED.status,
      session_version = EXCLUDED.session_version,
      updated_at_utc = EXCLUDED.updated_at_utc
    RETURNING id
  )
  SELECT COUNT(*)::integer INTO v_upserted_count FROM upserted;

  WITH retired AS (
    UPDATE public.banking_pay_workbench_preview_rows AS stale_preview
    SET selected = false,
        selection_state = 'SUPERSEDED',
        status = 'SUPERSEDED',
        row_json = jsonb_strip_nulls(
          COALESCE(stale_preview.row_json, '{}'::jsonb)
          || jsonb_build_object(
            'certified_source_preview_superseded', true,
            'certified_source_preview_superseded_at_utc', v_now::text,
            'certified_source_preview_superseded_by_build_id', p_economic_build_id::text,
            'certified_source_preview_superseded_by_run_id', p_source_build_run_id::text,
            'certified_source_preview_superseded_by_change_seq', p_source_change_seq
          )
        ),
        updated_at_utc = v_now
    WHERE stale_preview.session_id = p_session_id
      AND stale_preview.candidate_id = p_candidate_id
      AND NOT EXISTS (
        SELECT 1
        FROM pg_temp._bpay_certified_preview_ready_rows AS exact_row
        WHERE exact_row.resolved_section = stale_preview.section
          AND exact_row.line_key = stale_preview.row_key
      )
      AND UPPER(BTRIM(COALESCE(stale_preview.status, ''))) <> 'SUPERSEDED'
    RETURNING stale_preview.id
  )
  SELECT COUNT(*)::integer INTO v_retired_count FROM retired;

  WITH source_identities AS (
    SELECT resolved_section AS section, line_key, source_ordinal
    FROM pg_temp._bpay_certified_preview_ready_rows
  ), preview_identities AS (
    SELECT preview_row.section,
           preview_row.row_key,
           (preview_row.row_ordinal - (v_scope_ordinal * 1000000))::bigint AS source_ordinal
    FROM public.banking_pay_workbench_preview_rows AS preview_row
    WHERE preview_row.session_id = p_session_id
      AND preview_row.candidate_id = p_candidate_id
      AND preview_row.session_version = p_session_version
      AND preview_row.status = 'READY'
  )
  SELECT
    (SELECT COUNT(*) FROM (SELECT * FROM source_identities EXCEPT ALL SELECT * FROM preview_identities) AS source_diff)::integer,
    (SELECT COUNT(*) FROM (SELECT * FROM preview_identities EXCEPT ALL SELECT * FROM source_identities) AS preview_diff)::integer
  INTO v_source_minus_preview, v_preview_minus_source;

  SELECT COUNT(*)::integer,
         md5(COALESCE(string_agg(resolved_section || E'\x1f' || line_key || E'\x1f' || source_ordinal::text, E'\x1e' ORDER BY source_ordinal, resolved_section, line_key), ''))
  INTO v_source_count, v_source_identity_digest
  FROM pg_temp._bpay_certified_preview_ready_rows;

  SELECT COUNT(*)::integer,
         md5(COALESCE(string_agg(
           preview_row.section || E'\x1f' || preview_row.row_key || E'\x1f'
             || (preview_row.row_ordinal - (v_scope_ordinal * 1000000))::text,
           E'\x1e'
           ORDER BY preview_row.row_ordinal, preview_row.section, preview_row.row_key
         ), ''))
  INTO v_preview_count, v_preview_identity_digest
  FROM public.banking_pay_workbench_preview_rows AS preview_row
  WHERE preview_row.session_id = p_session_id
    AND preview_row.candidate_id = p_candidate_id
    AND preview_row.session_version = p_session_version
    AND preview_row.status = 'READY';

  SELECT COUNT(*) FILTER (WHERE is_selectable)::integer,
         COUNT(*) FILTER (WHERE is_selectable IS NOT TRUE)::integer,
         COUNT(*) FILTER (WHERE effective_selected)::integer
  INTO v_selectable_count, v_context_count, v_selected_count
  FROM pg_temp._bpay_certified_preview_ready_rows;

  IF v_source_minus_preview <> 0
     OR v_preview_minus_source <> 0
     OR v_source_count IS DISTINCT FROM v_preview_count
     OR v_source_identity_digest IS DISTINCT FROM v_preview_identity_digest
     OR (v_contract_version IN (1,3) AND v_authority_kind='BOUNDED_FULL_SOURCE_BUILD'
       AND v_source_count IS DISTINCT FROM v_build.canonical_count) THEN
    RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_PARITY_FAILED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'CERTIFIED_SOURCE_PREVIEW_PARITY_FAILED',
              'source_minus_preview', v_source_minus_preview,
              'preview_minus_source', v_preview_minus_source
            )::text;
  END IF;

  SELECT COALESCE(jsonb_object_agg(section_count.section, section_count.row_count ORDER BY section_count.section), '{}'::jsonb)
  INTO v_section_counts
  FROM (
    SELECT ready_row.resolved_section AS section, COUNT(*)::integer AS row_count
    FROM pg_temp._bpay_certified_preview_ready_rows AS ready_row
    GROUP BY ready_row.resolved_section
  ) AS section_count;

  IF v_contract_version = 3 THEN
    v_selection_recovery_overlay := private.pay_workbench_recovery_selection_overlay_apply_v1(
      p_session_id,
      p_candidate_id,
      jsonb_build_object(
        'force_v3', true,
        'reason', 'V3_PUBLICATION'
      )
    );
  END IF;

  SELECT COALESCE(jsonb_agg(selected_row.id::text ORDER BY selected_row.row_ordinal, selected_row.id), '[]'::jsonb)
  INTO v_selected_ids
  FROM public.banking_pay_workbench_preview_rows AS selected_row
  WHERE selected_row.session_id = p_session_id
    AND selected_row.session_version = p_session_version
    AND selected_row.status = 'READY'
    AND selected_row.selected IS TRUE
    AND selected_row.selection_state = 'SELECTED';

  UPDATE public.banking_pay_workbench_sessions AS session_update
  SET server_selected_preview_row_ids = v_selected_ids,
      selected_row_count = jsonb_array_length(v_selected_ids),
      preview_row_count = (
        SELECT COUNT(*)::integer
        FROM public.banking_pay_workbench_preview_rows AS session_preview
        WHERE session_preview.session_id = p_session_id
          AND session_preview.session_version = p_session_version
          AND session_preview.status = 'READY'
      ),
      updated_at_utc = v_now
  WHERE session_update.id = p_session_id;

  SELECT pg_catalog.min(preview_row.row_ordinal),pg_catalog.max(preview_row.row_ordinal)
  INTO v_min_public_ordinal,v_max_public_ordinal
  FROM public.banking_pay_workbench_preview_rows AS preview_row
  WHERE preview_row.session_id=p_session_id
    AND preview_row.candidate_id=p_candidate_id
    AND preview_row.session_version=p_session_version
    AND preview_row.status='READY';

  IF v_contract_version=3 THEN
    v_semantic_proof := private.pay_workbench_semantic_ready_proof_page_v1(
      p_session_id => p_session_id,
      p_candidate_ids => ARRAY[p_candidate_id],
      p_source_run_by_candidate_json => jsonb_build_object(
        p_candidate_id::text,
        p_source_build_run_id::text
      ),
      p_selected_preview_row_ids_by_candidate_json => NULL::jsonb,
      p_mode => CASE
        WHEN v_authority_kind='CERTIFIED_CANCELLATION_REVERSION' THEN 'CANCELLATION_REVERSION'
        ELSE 'PUBLICATION'
      END,
      p_options_json => '{}'::jsonb
    );

    v_semantic_candidate_proof := COALESCE(v_semantic_proof->'candidate_results'->0, '{}'::jsonb);
    v_semantic_ready := COALESCE((v_semantic_candidate_proof->>'semantic_ready')::boolean, false);
    v_semantic_proof_digest := NULLIF(BTRIM(COALESCE(v_semantic_candidate_proof->>'semantic_proof_digest','')), '');
    v_ordinary_positive_selectable_count := COALESCE((v_semantic_candidate_proof->>'ordinary_positive_selectable_count')::integer, 0);
    v_ordinary_positive_amount := COALESCE((v_semantic_candidate_proof->>'ordinary_positive_amount')::numeric, 0);
    v_recognised_deduction_count := COALESCE((v_semantic_candidate_proof->>'recognised_deduction_count')::integer, 0);
    v_recognised_deduction_amount := COALESCE((v_semantic_candidate_proof->>'recognised_deduction_amount')::numeric, 0);
    v_usable_same_candidate_headroom := COALESCE((v_semantic_candidate_proof->>'usable_same_candidate_headroom')::numeric, 0);
    v_candidate_ready_amount := COALESCE((v_semantic_candidate_proof->>'candidate_ready_amount')::numeric, 0);
    v_invalid_selectable_row_count := COALESCE((v_semantic_candidate_proof->>'invalid_selectable_row_count')::integer, -1);

    IF v_semantic_ready IS NOT TRUE
       OR v_semantic_proof_digest IS NULL
       OR v_invalid_selectable_row_count <> 0
       OR v_candidate_ready_amount < 0
       OR (
         NULLIF(BTRIM(COALESCE(p_publication_options_json->>'semantic_proof_digest','')), '') IS NOT NULL
         AND p_publication_options_json->>'semantic_proof_digest' IS DISTINCT FROM v_semantic_proof_digest
       ) THEN
      RAISE EXCEPTION 'CERTIFIED_SOURCE_PREVIEW_SEMANTIC_PARITY_FAILED'
        USING ERRCODE='P0001',
              DETAIL=jsonb_build_object(
                'code','CERTIFIED_SOURCE_PREVIEW_SEMANTIC_PARITY_FAILED',
                'candidate_id',p_candidate_id,
                'semantic_proof',v_semantic_candidate_proof
              )::text;
    END IF;
  END IF;

  IF v_contract_version=1 THEN
    v_attestation := jsonb_build_object(
      'attestation_version', 'CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V1',
      'authority_kind', v_authority_kind,
      'parity_complete', true,
      'economic_build_id', p_economic_build_id::text,
      'source_build_run_id', p_source_build_run_id::text,
      'source_change_seq', p_source_change_seq,
      'session_version', p_session_version,
      'completion_job_id', p_completion_job_id::text,
      'refresh_scope_kind', v_refresh_scope_kind,
      'source_row_count', v_source_count,
      'preview_row_count', v_preview_count,
      'selectable_row_count', v_selectable_count,
      'context_row_count', v_context_count,
      'selected_row_count', v_selected_count,
      'source_digest', v_source_digest,
      'source_identity_digest', v_source_identity_digest,
      'preview_identity_digest', v_preview_identity_digest,
      'section_counts', v_section_counts,
      'attested_at_utc', v_now::text,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    );
  ELSIF v_contract_version=2 THEN
    v_attestation := jsonb_strip_nulls(jsonb_build_object(
      'attestation_version','CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V2',
      'contract_version',2,
      'authority_kind',v_authority_kind,
      'final_state',v_final_state,
      'parity_complete',true,
      'session_id',p_session_id,
      'candidate_id',p_candidate_id,
      'economic_build_id',p_economic_build_id,
      'source_build_run_id',p_source_build_run_id,
      'source_publication_id',v_source_publication_id,
      'original_economic_build_id',v_original_economic_build_id,
      'original_source_build_run_id',v_original_source_build_run_id,
      'original_source_publication_id',p_publication_options_json->>'original_source_publication_id',
      'source_session_id',v_source_session_id,
      'source_change_seq',p_source_change_seq,
      'session_version',p_session_version,
      'completion_job_id',p_completion_job_id,
      'refresh_scope_kind',v_refresh_scope_kind,
      'source_row_count',v_source_count,
      'preview_row_count',v_preview_count,
      'selectable_row_count',v_selectable_count,
      'context_row_count',v_context_count,
      'selected_row_count',v_selected_count,
      'source_digest',v_source_digest,
      'source_identity_digest',v_source_identity_digest,
      'preview_identity_digest',v_preview_identity_digest,
      'section_counts',v_section_counts,
      'scope_ordinal',v_scope_ordinal,
      'minimum_public_ordinal',v_min_public_ordinal,
      'maximum_public_ordinal',v_max_public_ordinal,
      'certification_version',v_certification_version,
      'certification_digest',v_certification_digest,
      'admission_seal_version',v_admission_seal_version,
      'admission_seal_digest',v_admission_seal_digest,
      'projection_fingerprint',v_projection_fingerprint,
      'attested_at_utc',v_now,
      'policy_x_authority_scope','PRE_DRAFT_LIVE_TRUTH'
    ));
  ELSE
    v_attestation := jsonb_strip_nulls(jsonb_build_object(
      'attestation_version','CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V3',
      'contract_version',3,
      'semantic_contract_version','READY_TO_PAY_SEMANTIC_V2',
      'authority_kind',v_authority_kind,
      'final_state',v_final_state,
      'parity_complete',true,
      'semantic_ready',v_semantic_ready,
      'session_id',p_session_id,
      'candidate_id',p_candidate_id,
      'economic_build_id',p_economic_build_id,
      'source_build_run_id',p_source_build_run_id,
      'source_publication_id',v_source_publication_id,
      'original_economic_build_id',v_original_economic_build_id,
      'original_source_build_run_id',v_original_source_build_run_id,
      'original_source_publication_id',p_publication_options_json->>'original_source_publication_id',
      'source_session_id',v_source_session_id,
      'source_change_seq',p_source_change_seq,
      'session_version',p_session_version,
      'completion_job_id',p_completion_job_id,
      'refresh_scope_kind',v_refresh_scope_kind,
      'source_row_count',v_source_count,
      'preview_row_count',v_preview_count,
      'selectable_row_count',v_selectable_count,
      'ordinary_positive_selectable_count',v_ordinary_positive_selectable_count,
      'ordinary_positive_amount',v_ordinary_positive_amount,
      'recognised_deduction_count',v_recognised_deduction_count,
      'recognised_deduction_amount',v_recognised_deduction_amount,
      'usable_same_candidate_headroom',v_usable_same_candidate_headroom,
      'candidate_ready_amount',v_candidate_ready_amount,
      'context_row_count',v_context_count,
      'blocked_row_count',COALESCE((v_semantic_candidate_proof->>'blocked_row_count')::integer,0),
      'invalid_selectable_row_count',v_invalid_selectable_row_count,
      'selected_row_count',v_selected_count,
      'source_digest',v_source_digest,
      'source_identity_digest',v_source_identity_digest,
      'preview_identity_digest',v_preview_identity_digest,
      'section_counts',v_section_counts
    ) || jsonb_build_object(
      'scope_ordinal',v_scope_ordinal,
      'minimum_public_ordinal',v_min_public_ordinal,
      'maximum_public_ordinal',v_max_public_ordinal,
      'certification_version',v_certification_version,
      'certification_digest',v_certification_digest,
      'admission_seal_version',v_admission_seal_version,
      'admission_seal_digest',v_admission_seal_digest,
      'projection_fingerprint',v_projection_fingerprint,
      'semantic_proof_digest',v_semantic_proof_digest,
      'original_semantic_proof_digest',p_publication_options_json->>'original_semantic_proof_digest',
      'selection_recovery_headroom_v1',COALESCE(v_selection_recovery_overlay,'{}'::jsonb),
      'cancellation_request_id',p_publication_options_json->>'cancellation_request_id',
      'cancellation_operation_id',p_publication_options_json->>'cancellation_operation_id',
      'cancellation_work_item_id',p_publication_options_json->>'cancellation_work_item_id',
      'pay_batch_id',p_publication_options_json->>'pay_batch_id',
      'cancellation_reversion_run_id',p_publication_options_json->>'cancellation_reversion_run_id',
      'financial_reversion_digest',p_publication_options_json->>'financial_reversion_digest',
      'attested_at_utc',v_now,
      'policy_x_authority_scope','PRE_DRAFT_LIVE_TRUTH'
    ));
  END IF;

  UPDATE public.banking_pay_workbench_session_scope AS scope_update
  SET certified_preview_publication_required = true,
      certified_preview_publication_parity_ok = true,
      certified_preview_publication_session_version = p_session_version,
      certified_preview_publication_source_change_seq = p_source_change_seq,
      certified_preview_publication_source_build_run_id = p_source_build_run_id,
      certified_preview_publication_source_publication_id = v_source_publication_id,
      certified_preview_publication_attestation_json = v_attestation,
      certified_preview_publication_attested_at_utc = v_now,
      updated_at_utc = v_now
  WHERE scope_update.id = v_scope.id;

  PERFORM public._audit_insert(
    'banking_pay_workbench_certified_source_preview',
    p_session_id::text,
    'PUBLISH_CERTIFIED_SOURCE_PREVIEW',
    NULL::jsonb,
    v_attestation || jsonb_build_object(
      'candidate_id', p_candidate_id::text,
      'upserted_row_count', v_upserted_count,
      'retired_row_count', v_retired_count,
      'selection_mode', CASE WHEN v_explicit_selection THEN 'EXPLICIT_INCLUDE' ELSE 'IMPLICIT_ALL' END
    ),
    'CERTIFIED_SOURCE_PREVIEW_PARITY_COMPLETE',
    v_session.actor_user_id
  );

  RETURN jsonb_build_object(
    'ok', true,
    'parity_complete', true,
    'contract_version',v_contract_version,
    'authority_kind',v_authority_kind,
    'final_state',CASE WHEN v_contract_version=1 THEN 'READY' ELSE v_final_state END,
    'already_current', false,
    'session_id', p_session_id::text,
    'candidate_id', p_candidate_id::text,
    'economic_build_id', p_economic_build_id::text,
    'source_build_run_id', p_source_build_run_id::text,
    'source_change_seq', p_source_change_seq,
    'session_version', p_session_version,
    'source_row_count', v_source_count,
    'preview_row_count', v_preview_count,
    'selectable_row_count', v_selectable_count,
    'context_row_count', v_context_count,
    'selected_row_count', v_selected_count,
    'upserted_row_count', v_upserted_count,
    'retired_row_count', v_retired_count,
    'section_counts', v_section_counts,
    'selection_mode', CASE WHEN v_explicit_selection THEN 'EXPLICIT_INCLUDE' ELSE 'IMPLICIT_ALL' END,
    'retry_safe', true,
    'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
  );
END;
$function$;

-- private.pay_workbench_recovery_selection_overlay_apply_v1(uuid,uuid,jsonb)
CREATE OR REPLACE FUNCTION private.pay_workbench_recovery_selection_overlay_apply_v1(p_session_id uuid, p_candidate_id uuid, p_options_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_session public.banking_pay_workbench_sessions%ROWTYPE;
  v_scope public.banking_pay_workbench_session_scope%ROWTYPE;
  v_force_v3 boolean := false;
  v_reason text := 'SELECTION_CHANGED';
  v_unknown_option_count integer := 0;
  v_is_v3 boolean := false;
  v_recovery_row_count integer := 0;
  v_ready_recovery_count integer := 0;
  v_case_recovery_count integer := 0;
  v_blocked_recovery_count integer := 0;
  v_forced_deselected_count integer := 0;
  v_updated_count integer := 0;
  v_selected_positive_amount numeric := 0;
  v_ready_recovery_amount numeric := 0;
  v_selected_preview_row_ids jsonb := '[]'::jsonb;
  v_selected_row_count integer := 0;
  v_overlay_digest text := NULL::text;
  v_duplicate_recovery_identity_count integer := 0;
  v_session_ready boolean := false;
  v_draft_blocker_codes jsonb := '[]'::jsonb;
BEGIN
  IF p_session_id IS NULL OR p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_SELECTION_OVERLAY_SCOPE_REQUIRED'
      USING ERRCODE = '22023';
  END IF;

  IF p_options_json IS NULL OR pg_catalog.jsonb_typeof(p_options_json) <> 'object' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_SELECTION_OVERLAY_OPTIONS_INVALID'
      USING ERRCODE = '22023';
  END IF;

  SELECT pg_catalog.count(*)::integer
  INTO v_unknown_option_count
  FROM pg_catalog.jsonb_object_keys(p_options_json) AS supplied_option(option_key)
  WHERE supplied_option.option_key NOT IN ('force_v3', 'reason');

  IF v_unknown_option_count > 0 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_SELECTION_OVERLAY_OPTIONS_UNKNOWN'
      USING ERRCODE = '22023';
  END IF;

  v_force_v3 := pg_catalog.lower(pg_catalog.btrim(COALESCE(p_options_json->>'force_v3', 'false')))
    IN ('true', 't', '1', 'yes', 'y', 'on');
  v_reason := pg_catalog.upper(pg_catalog.btrim(COALESCE(NULLIF(p_options_json->>'reason', ''), 'SELECTION_CHANGED')));

  SELECT session_row.*
  INTO v_session
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id
  FOR UPDATE;

  IF NOT FOUND
     OR pg_catalog.upper(pg_catalog.btrim(COALESCE(v_session.status, ''))) <> 'OPEN'
     OR v_session.discarded_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_SELECTION_OVERLAY_SESSION_NOT_OPEN'
      USING ERRCODE = 'P0001';
  END IF;

  SELECT scope_row.*
  INTO v_scope
  FROM public.banking_pay_workbench_session_scope AS scope_row
  WHERE scope_row.session_id = p_session_id
    AND scope_row.candidate_id = p_candidate_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_SELECTION_OVERLAY_CANDIDATE_NOT_IN_SCOPE'
      USING ERRCODE = 'P0001';
  END IF;

  v_is_v3 := v_force_v3 OR (
    v_scope.certified_preview_publication_attestation_json->>'attestation_version'
      = 'CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V3'
    AND v_scope.certified_preview_publication_attestation_json->>'contract_version' = '3'
    AND v_scope.certified_preview_publication_attestation_json->>'semantic_contract_version'
      = 'READY_TO_PAY_SEMANTIC_V2'
  );

  IF v_is_v3 IS NOT TRUE THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'NOT_V3_SEMANTIC_SOURCE',
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'updated_count', 0,
      'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
    );
  END IF;

  DROP TABLE IF EXISTS pg_temp._bpay_recovery_selection_overlay;
  CREATE TEMPORARY TABLE pg_temp._bpay_recovery_selection_overlay ON COMMIT DROP AS
  WITH selected_positive_by_channel AS (
    SELECT
      pg_catalog.upper(pg_catalog.btrim(COALESCE(
        positive_row.row_json->>'pay_channel',
        positive_row.row_json->>'candidate_pay_method',
        positive_row.row_json->>'current_pay_method',
        ''
      ))) AS pay_channel,
      pg_catalog.round(COALESCE(pg_catalog.sum(
        CASE
          WHEN COALESCE(positive_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN GREATEST((positive_row.row_json->>'amount_ex_vat')::numeric, 0)
          ELSE 0::numeric
        END
      ), 0), 2) AS selected_positive_headroom_ex_vat
    FROM public.banking_pay_workbench_preview_rows AS positive_row
    WHERE positive_row.session_id = p_session_id
      AND positive_row.session_version = v_session.version
      AND positive_row.candidate_id = p_candidate_id
      AND positive_row.status = 'READY'
      AND positive_row.selected IS TRUE
      AND pg_catalog.upper(pg_catalog.btrim(COALESCE(positive_row.selection_state, ''))) = 'SELECTED'
      AND pg_catalog.upper(pg_catalog.btrim(COALESCE(positive_row.row_json->>'line_type', ''))) = 'TIMESHEET_PAYMENT'
      AND pg_catalog.upper(pg_catalog.btrim(COALESCE(positive_row.row_json->>'presentation_role', ''))) = 'ALLOCATION_COMPONENT'
      AND pg_catalog.lower(pg_catalog.btrim(COALESCE(positive_row.row_json->>'draftable', 'false')))
        IN ('true', 't', '1', 'yes', 'y', 'on')
      AND pg_catalog.lower(pg_catalog.btrim(COALESCE(positive_row.row_json->>'is_ready_for_draft', 'false')))
        IN ('true', 't', '1', 'yes', 'y', 'on')
      AND pg_catalog.lower(pg_catalog.btrim(COALESCE(positive_row.row_json->>'selection_allowed', 'false')))
        IN ('true', 't', '1', 'yes', 'y', 'on')
      AND COALESCE(positive_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
      AND (positive_row.row_json->>'amount_ex_vat')::numeric > 0
    GROUP BY pg_catalog.upper(pg_catalog.btrim(COALESCE(
      positive_row.row_json->>'pay_channel',
      positive_row.row_json->>'candidate_pay_method',
      positive_row.row_json->>'current_pay_method',
      ''
    )))
  ), recovery_base AS (
    SELECT
      recovery_row.id,
      recovery_row.row_ordinal,
      recovery_row.section AS physical_section,
      recovery_row.row_key,
      recovery_row.selected AS current_selected,
      recovery_row.selection_state AS current_selection_state,
      COALESCE(recovery_row.row_json, '{}'::jsonb) AS base_row_json,
      pg_catalog.upper(pg_catalog.btrim(COALESCE(
        recovery_row.row_json->>'selection_user_override',
        ''
      ))) = 'UNSELECTED' AS explicitly_user_unselected,
      pg_catalog.upper(pg_catalog.btrim(COALESCE(
        recovery_row.row_json->>'pay_channel',
        recovery_row.row_json->>'candidate_pay_method',
        recovery_row.row_json->>'current_pay_method',
        ''
      ))) AS pay_channel,
      pg_catalog.round(COALESCE(
        CASE
          WHEN COALESCE(recovery_row.row_json->>'nominal_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN pg_catalog.abs((recovery_row.row_json->>'nominal_due_amount_ex_vat')::numeric)
          ELSE NULL::numeric
        END,
        CASE
          WHEN COALESCE(recovery_row.row_json->>'source_due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN pg_catalog.abs((recovery_row.row_json->>'source_due_amount_ex_vat')::numeric)
          ELSE NULL::numeric
        END,
        CASE
          WHEN COALESCE(recovery_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN pg_catalog.abs((recovery_row.row_json->>'amount_ex_vat')::numeric)
          ELSE 0::numeric
        END
      ), 2) AS nominal_due_amount_ex_vat,
      CASE
        WHEN pg_catalog.jsonb_typeof(recovery_row.row_json->'case_components') = 'array'
          THEN recovery_row.row_json->'case_components'
        ELSE '[]'::jsonb
      END AS canonical_case_components,
      CASE
        WHEN pg_catalog.jsonb_typeof(recovery_row.row_json->'case_resolution_summary') = 'object'
          THEN recovery_row.row_json->'case_resolution_summary'
        WHEN pg_catalog.jsonb_typeof(recovery_row.row_json->'case_resolution_summary_json') = 'object'
          THEN recovery_row.row_json->'case_resolution_summary_json'
        ELSE '{}'::jsonb
      END AS case_resolution_summary_json,
      (
        pg_catalog.lower(pg_catalog.btrim(COALESCE(
          recovery_row.row_json#>>'{case_resolution_summary,case_needs_resolution}',
          recovery_row.row_json#>>'{case_resolution_summary_json,case_needs_resolution}',
          recovery_row.row_json->>'case_needs_resolution_now',
          'false'
        ))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND pg_catalog.lower(pg_catalog.btrim(COALESCE(
          recovery_row.row_json#>>'{case_resolution_summary,taxable_channel_restructure,can_apply}',
          recovery_row.row_json#>>'{case_resolution_summary_json,taxable_channel_restructure,can_apply}',
          'false'
        ))) IN ('true', 't', '1', 'yes', 'y', 'on')
        AND pg_catalog.upper(pg_catalog.btrim(COALESCE(
          recovery_row.row_json#>>'{case_resolution_summary,resolution_family}',
          recovery_row.row_json#>>'{case_resolution_summary_json,resolution_family}',
          recovery_row.row_json->>'resolution_family',
          ''
        ))) = 'TAXABLE_CHANNEL_RESTRUCTURE'
      ) AS actionable_restructure,
      COALESCE(
        recovery_row.row_json#>'{selection_recovery_headroom_v1,base_blocked_reason_codes}',
        (
          SELECT COALESCE(pg_catalog.jsonb_agg(reason.value ORDER BY reason.ordinality), '[]'::jsonb)
          FROM pg_catalog.jsonb_array_elements_text(
            CASE
              WHEN pg_catalog.jsonb_typeof(recovery_row.row_json->'blocked_reason_codes') = 'array'
                THEN recovery_row.row_json->'blocked_reason_codes'
              ELSE '[]'::jsonb
            END
          ) WITH ORDINALITY AS reason(value, ordinality)
          WHERE pg_catalog.upper(pg_catalog.btrim(reason.value)) <> 'NO_PAY_HEADROOM'
        ),
        '[]'::jsonb
      ) AS base_blocked_reason_codes,
      COALESCE(
        NULLIF(recovery_row.row_json#>>'{selection_recovery_headroom_v1,base_presentation_reason}', ''),
        CASE
          WHEN pg_catalog.upper(COALESCE(recovery_row.row_json->>'presentation_reason', '')) = 'NO_PAY_HEADROOM'
            THEN 'READY_TO_PAY'
          ELSE NULLIF(recovery_row.row_json->>'presentation_reason', '')
        END,
        'READY_TO_PAY'
      ) AS base_presentation_reason,
      (
        recovery_row.row_json->>'finance_case_id'
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        AND pg_catalog.upper(pg_catalog.btrim(COALESCE(recovery_row.row_json->>'line_type', ''))) IN (
          'OVERPAYMENT_RECOVERY', 'MANUAL_DEBT_RECOVERY',
          'PAYMENT_ADVANCE_REPAYMENT', 'LOAN_REPAYMENT'
        )
        AND pg_catalog.lower(pg_catalog.btrim(COALESCE(recovery_row.row_json->>'post_draft_overlay_applied', 'false')))
          NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        AND pg_catalog.lower(pg_catalog.btrim(COALESCE(recovery_row.row_json->>'case_needs_resolution_now', 'false')))
          NOT IN ('true', 't', '1', 'yes', 'y', 'on')
        AND pg_catalog.upper(pg_catalog.btrim(COALESCE(recovery_row.row_json#>>'{snooze_state,state}', 'NONE'))) = 'NONE'
        AND NOT EXISTS (
          SELECT 1
          FROM pg_catalog.jsonb_array_elements_text(
            COALESCE(
              recovery_row.row_json#>'{selection_recovery_headroom_v1,base_blocked_reason_codes}',
              CASE
                WHEN pg_catalog.jsonb_typeof(recovery_row.row_json->'blocked_reason_codes') = 'array'
                  THEN recovery_row.row_json->'blocked_reason_codes'
                ELSE '[]'::jsonb
              END
            )
          ) AS blocker(value)
          WHERE pg_catalog.upper(pg_catalog.btrim(blocker.value)) <> 'NO_PAY_HEADROOM'
        )
      ) AS static_recovery_eligible
    FROM public.banking_pay_workbench_preview_rows AS recovery_row
    WHERE recovery_row.session_id = p_session_id
      AND recovery_row.session_version = v_session.version
      AND recovery_row.candidate_id = p_candidate_id
      AND recovery_row.status = 'READY'
      AND pg_catalog.upper(pg_catalog.btrim(COALESCE(
        recovery_row.row_json->>'line_type',
        recovery_row.row_json->>'case_type',
        ''
      ))) IN (
        'OVERPAYMENT_RECOVERY', 'MANUAL_DEBT_RECOVERY',
        'PAYMENT_ADVANCE_REPAYMENT', 'LOAN_REPAYMENT'
      )
  ), ranked_recovery AS (
    SELECT
      recovery_base.*,
      COALESCE(selected_headroom.selected_positive_headroom_ex_vat, 0)::numeric AS selected_positive_headroom_ex_vat,
      COALESCE(pg_catalog.sum(
        CASE
          WHEN recovery_base.static_recovery_eligible
           AND recovery_base.actionable_restructure IS NOT TRUE
            THEN recovery_base.nominal_due_amount_ex_vat
          ELSE 0::numeric
        END
      ) OVER (
        PARTITION BY recovery_base.pay_channel
        ORDER BY recovery_base.row_ordinal, recovery_base.id
        ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
      ), 0)::numeric AS prior_nominal_due_amount_ex_vat
    FROM recovery_base
    LEFT JOIN selected_positive_by_channel AS selected_headroom
      ON selected_headroom.pay_channel = recovery_base.pay_channel
  ), allocated_recovery AS (
    SELECT
      ranked_recovery.*,
      CASE
        WHEN ranked_recovery.static_recovery_eligible
         AND ranked_recovery.actionable_restructure IS NOT TRUE
         AND ranked_recovery.pay_channel IN ('PAYE', 'UMBRELLA')
          THEN pg_catalog.round(LEAST(
            ranked_recovery.nominal_due_amount_ex_vat,
            GREATEST(
              ranked_recovery.selected_positive_headroom_ex_vat
                - ranked_recovery.prior_nominal_due_amount_ex_vat,
              0
            )
          ), 2)
        ELSE 0::numeric
      END AS recoverable_amount_ex_vat
    FROM ranked_recovery
  ), recovery_component_base AS (
    SELECT
      allocated_recovery.id AS recovery_row_id,
      component.ordinality::integer AS component_ordinality,
      component.value AS component_json,
      CASE
        WHEN COALESCE(component.value->>'finance_component_id', '')
               ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN true
        ELSE NULLIF(pg_catalog.btrim(COALESCE(component.value->>'source_family_key', '')), '') IS NOT NULL
          AND NULLIF(pg_catalog.btrim(COALESCE(
                component.value->>'component_key_type',
                component.value#>>'{component_key,key_type}',
                ''
              )), '') IS NOT NULL
          AND NULLIF(pg_catalog.btrim(COALESCE(
                component.value->>'component_key_value',
                component.value#>>'{component_key,key_value}',
                ''
              )), '') IS NOT NULL
          AND NULLIF(pg_catalog.btrim(COALESCE(component.value->>'bucket_code', '')), '') IS NOT NULL
          AND NULLIF(pg_catalog.btrim(COALESCE(component.value->>'source_basis_fingerprint', '')), '') IS NOT NULL
          AND NULLIF(pg_catalog.btrim(COALESCE(component.value->>'component_fingerprint', '')), '') IS NOT NULL
      END AS identity_complete,
      CASE
        WHEN COALESCE(component.value->>'finance_component_id', '')
               ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN 'FINANCE:' || pg_catalog.lower(component.value->>'finance_component_id')
        ELSE 'STRUCT:' || pg_catalog.concat_ws(E'\x1f',
          pg_catalog.upper(pg_catalog.btrim(COALESCE(component.value->>'source_family_key', ''))),
          pg_catalog.upper(pg_catalog.btrim(COALESCE(
            component.value->>'component_key_type', component.value#>>'{component_key,key_type}', ''
          ))),
          pg_catalog.btrim(COALESCE(
            component.value->>'component_key_value', component.value#>>'{component_key,key_value}', ''
          )),
          pg_catalog.upper(pg_catalog.btrim(COALESCE(component.value->>'bucket_code', ''))),
          pg_catalog.btrim(COALESCE(component.value->>'source_basis_fingerprint', '')),
          pg_catalog.btrim(COALESCE(component.value->>'component_fingerprint', ''))
        )
      END AS component_identity,
      pg_catalog.round(COALESCE(
        CASE
          WHEN COALESCE(component.value->>'target_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN pg_catalog.abs((component.value->>'target_pay_ex_vat')::numeric)
          ELSE NULL::numeric
        END,
        CASE
          WHEN COALESCE(component.value->>'authoritative_outstanding_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN pg_catalog.abs((component.value->>'authoritative_outstanding_ex_vat')::numeric)
          ELSE NULL::numeric
        END,
        CASE
          WHEN COALESCE(component.value->>'source_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN pg_catalog.abs((component.value->>'source_pay_ex_vat')::numeric)
          ELSE NULL::numeric
        END,
        CASE
          WHEN COALESCE(component.value->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN pg_catalog.abs((component.value->>'component_amount_ex_vat')::numeric)
          ELSE 0::numeric
        END
      ), 2) AS component_capacity_ex_vat,
      allocated_recovery.recoverable_amount_ex_vat
    FROM allocated_recovery
    CROSS JOIN LATERAL pg_catalog.jsonb_array_elements(
      allocated_recovery.canonical_case_components
    ) WITH ORDINALITY AS component(value, ordinality)
  ), recovery_component_ranked AS (
    SELECT
      recovery_component_base.*,
      pg_catalog.count(*) OVER (
        PARTITION BY recovery_component_base.recovery_row_id,
          recovery_component_base.component_identity
      )::integer AS component_identity_count,
      COALESCE(pg_catalog.sum(recovery_component_base.component_capacity_ex_vat) OVER (
        PARTITION BY recovery_component_base.recovery_row_id
        ORDER BY
          pg_catalog.upper(pg_catalog.btrim(COALESCE(
            recovery_component_base.component_json->>'component_key_type',
            recovery_component_base.component_json#>>'{component_key,key_type}',
            ''
          ))),
          pg_catalog.btrim(COALESCE(
            recovery_component_base.component_json->>'component_key_value',
            recovery_component_base.component_json#>>'{component_key,key_value}',
            ''
          )),
          pg_catalog.lower(COALESCE(recovery_component_base.component_json->>'finance_component_id', '')),
          COALESCE(recovery_component_base.component_json->>'component_fingerprint', ''),
          recovery_component_base.component_ordinality
        ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
      ), 0)::numeric AS prior_component_capacity_ex_vat
    FROM recovery_component_base
  ), recovery_component_allocated AS (
    SELECT
      recovery_component_ranked.*,
      pg_catalog.round(LEAST(
        recovery_component_ranked.component_capacity_ex_vat,
        GREATEST(
          recovery_component_ranked.recoverable_amount_ex_vat
            - recovery_component_ranked.prior_component_capacity_ex_vat,
          0
        )
      ), 2) AS base_component_recoverable_ex_vat,
      pg_catalog.row_number() OVER (
        PARTITION BY recovery_component_ranked.recovery_row_id
        ORDER BY
          pg_catalog.upper(pg_catalog.btrim(COALESCE(
            recovery_component_ranked.component_json->>'component_key_type',
            recovery_component_ranked.component_json#>>'{component_key,key_type}',
            ''
          ))),
          pg_catalog.btrim(COALESCE(
            recovery_component_ranked.component_json->>'component_key_value',
            recovery_component_ranked.component_json#>>'{component_key,key_value}',
            ''
          )),
          pg_catalog.lower(COALESCE(recovery_component_ranked.component_json->>'finance_component_id', '')),
          COALESCE(recovery_component_ranked.component_json->>'component_fingerprint', ''),
          recovery_component_ranked.component_ordinality
      )::integer AS allocation_order
    FROM recovery_component_ranked
  ), recovery_component_residual AS (
    SELECT
      recovery_component_allocated.*,
      pg_catalog.round(
        recovery_component_allocated.recoverable_amount_ex_vat
          - pg_catalog.sum(recovery_component_allocated.base_component_recoverable_ex_vat)
              OVER (PARTITION BY recovery_component_allocated.recovery_row_id),
        2
      ) AS penny_residual_ex_vat,
      pg_catalog.max(recovery_component_allocated.allocation_order) FILTER (
        WHERE recovery_component_allocated.component_capacity_ex_vat
              - recovery_component_allocated.base_component_recoverable_ex_vat > 0
      ) OVER (PARTITION BY recovery_component_allocated.recovery_row_id)
        AS residual_target_order
    FROM recovery_component_allocated
  ), recovery_component_final AS (
    SELECT
      recovery_component_residual.*,
      pg_catalog.round(
        recovery_component_residual.base_component_recoverable_ex_vat
          + CASE
              WHEN recovery_component_residual.penny_residual_ex_vat <> 0
               AND recovery_component_residual.allocation_order
                    = recovery_component_residual.residual_target_order
               AND recovery_component_residual.component_capacity_ex_vat
                     - recovery_component_residual.base_component_recoverable_ex_vat
                    >= recovery_component_residual.penny_residual_ex_vat
                THEN recovery_component_residual.penny_residual_ex_vat
              ELSE 0::numeric
            END,
        2
      ) AS component_recoverable_ex_vat
    FROM recovery_component_residual
  ), recovery_component_rollup AS (
    SELECT
      recovery_component_final.recovery_row_id,
      pg_catalog.jsonb_agg(
        recovery_component_final.component_json
        || pg_catalog.jsonb_build_object(
          'preview_due_amount_ex_vat', recovery_component_final.component_recoverable_ex_vat,
          'allocated_source_due_amount_ex_vat', recovery_component_final.component_recoverable_ex_vat,
          'ready_preview_amount_ex_vat', recovery_component_final.component_recoverable_ex_vat,
          'preview_component_amount_ex_vat', recovery_component_final.component_recoverable_ex_vat,
          'component_amount_ex_vat', recovery_component_final.component_recoverable_ex_vat,
          'recoverable_this_pay_run_ex_vat', recovery_component_final.component_recoverable_ex_vat
        )
        ORDER BY recovery_component_final.component_ordinality
      ) AS allocated_case_components,
      pg_catalog.count(*) FILTER (
        WHERE recovery_component_final.identity_complete IS NOT TRUE
      )::integer AS incomplete_identity_count,
      pg_catalog.count(*) FILTER (
        WHERE recovery_component_final.component_identity_count > 1
      )::integer AS duplicate_identity_count,
      pg_catalog.round(COALESCE(pg_catalog.sum(
        recovery_component_final.component_capacity_ex_vat
      ), 0), 2) AS component_capacity_ex_vat,
      pg_catalog.round(COALESCE(pg_catalog.sum(
        recovery_component_final.component_recoverable_ex_vat
      ), 0), 2) AS component_recoverable_ex_vat
    FROM recovery_component_final
    GROUP BY recovery_component_final.recovery_row_id
  )
  SELECT
    allocated_recovery.*,
    COALESCE(recovery_component_rollup.allocated_case_components, '[]'::jsonb)
      AS allocated_case_components,
    COALESCE(recovery_component_rollup.incomplete_identity_count, 0)::integer
      AS incomplete_component_identity_count,
    COALESCE(recovery_component_rollup.duplicate_identity_count, 0)::integer
      AS duplicate_component_identity_count,
    COALESCE(recovery_component_rollup.component_capacity_ex_vat, 0)::numeric
      AS component_capacity_ex_vat,
    COALESCE(recovery_component_rollup.component_recoverable_ex_vat, 0)::numeric
      AS component_recoverable_ex_vat,
    CASE
      WHEN allocated_recovery.actionable_restructure
        THEN 'cases_resolutions'
      WHEN allocated_recovery.static_recovery_eligible
       AND allocated_recovery.recoverable_amount_ex_vat > 0
        THEN 'canonical_preview_lines'
      ELSE 'blocked_for_pay'
    END AS effective_section,
    pg_catalog.md5(pg_catalog.jsonb_build_object(
      'contract_version', 1,
      'candidate_id', p_candidate_id::text,
      'pay_channel', allocated_recovery.pay_channel,
      'row_key', allocated_recovery.row_key,
      'selected_positive_headroom_ex_vat', allocated_recovery.selected_positive_headroom_ex_vat,
      'nominal_due_amount_ex_vat', allocated_recovery.nominal_due_amount_ex_vat,
      'recoverable_amount_ex_vat', allocated_recovery.recoverable_amount_ex_vat,
      'effective_section', CASE
        WHEN allocated_recovery.actionable_restructure
          THEN 'cases_resolutions'
        WHEN allocated_recovery.static_recovery_eligible
         AND allocated_recovery.recoverable_amount_ex_vat > 0
          THEN 'canonical_preview_lines'
        ELSE 'blocked_for_pay'
      END
    )::text) AS row_overlay_digest
  FROM allocated_recovery
  LEFT JOIN recovery_component_rollup
    ON recovery_component_rollup.recovery_row_id = allocated_recovery.id;

  IF EXISTS (
    SELECT 1
    FROM pg_temp._bpay_recovery_selection_overlay AS overlay_row
    WHERE overlay_row.incomplete_component_identity_count > 0
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_COMPONENT_IDENTITY_INCOMPLETE'
      USING ERRCODE = 'P0001';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_temp._bpay_recovery_selection_overlay AS overlay_row
    WHERE overlay_row.duplicate_component_identity_count > 0
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_COMPONENT_IDENTITY_DUPLICATE'
      USING ERRCODE = 'P0001';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_temp._bpay_recovery_selection_overlay AS overlay_row
    WHERE overlay_row.nominal_due_amount_ex_vat > 0
      AND pg_catalog.jsonb_array_length(overlay_row.allocated_case_components) = 0
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_COMPONENT_AUTHORITY_MISSING'
      USING ERRCODE = 'P0001';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_temp._bpay_recovery_selection_overlay AS overlay_row
    WHERE overlay_row.recoverable_amount_ex_vat > overlay_row.component_capacity_ex_vat
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_COMPONENT_CAPACITY_INSUFFICIENT'
      USING ERRCODE = 'P0001';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_temp._bpay_recovery_selection_overlay AS overlay_row
    WHERE overlay_row.component_recoverable_ex_vat
      IS DISTINCT FROM overlay_row.recoverable_amount_ex_vat
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_COMPONENT_PENNY_RECONCILIATION_FAILED'
      USING ERRCODE = 'P0001';
  END IF;

  SELECT pg_catalog.count(*)::integer
  INTO v_duplicate_recovery_identity_count
  FROM (
    SELECT
      COALESCE(NULLIF(overlay_row.base_row_json->>'finance_case_id', ''), overlay_row.row_key) AS recovery_identity,
      pg_catalog.upper(pg_catalog.btrim(COALESCE(overlay_row.base_row_json->>'line_type', ''))) AS recovery_family
    FROM pg_temp._bpay_recovery_selection_overlay AS overlay_row
    GROUP BY
      COALESCE(NULLIF(overlay_row.base_row_json->>'finance_case_id', ''), overlay_row.row_key),
      pg_catalog.upper(pg_catalog.btrim(COALESCE(overlay_row.base_row_json->>'line_type', '')))
    HAVING pg_catalog.count(*) > 1
  ) AS duplicate_identity;

  IF v_duplicate_recovery_identity_count > 0 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_RECOVERY_SELECTION_OVERLAY_DUPLICATE_IDENTITY'
      USING ERRCODE = 'P0001';
  END IF;

  SELECT pg_catalog.count(*)::integer,
         pg_catalog.count(*) FILTER (WHERE overlay_row.effective_section = 'canonical_preview_lines')::integer,
         pg_catalog.count(*) FILTER (WHERE overlay_row.effective_section = 'cases_resolutions')::integer,
         pg_catalog.count(*) FILTER (WHERE overlay_row.effective_section = 'blocked_for_pay')::integer,
         (
           SELECT pg_catalog.round(COALESCE(pg_catalog.sum(channel_headroom.selected_positive_headroom_ex_vat), 0), 2)
           FROM (
             SELECT overlay_channel.pay_channel,
                    pg_catalog.max(overlay_channel.selected_positive_headroom_ex_vat) AS selected_positive_headroom_ex_vat
             FROM pg_temp._bpay_recovery_selection_overlay AS overlay_channel
             GROUP BY overlay_channel.pay_channel
           ) AS channel_headroom
         ),
         pg_catalog.round(COALESCE(pg_catalog.sum(overlay_row.recoverable_amount_ex_vat), 0), 2),
         pg_catalog.md5(COALESCE(pg_catalog.string_agg(
           overlay_row.row_key || E'\x1f' || overlay_row.row_overlay_digest,
           E'\x1e' ORDER BY overlay_row.row_ordinal, overlay_row.id
         ), ''))
  INTO v_recovery_row_count,
       v_ready_recovery_count,
       v_case_recovery_count,
       v_blocked_recovery_count,
       v_selected_positive_amount,
       v_ready_recovery_amount,
       v_overlay_digest
  FROM pg_temp._bpay_recovery_selection_overlay AS overlay_row;

  WITH updated_rows AS (
    UPDATE public.banking_pay_workbench_preview_rows AS recovery_row
    SET selected = CASE
          WHEN overlay_row.effective_section = 'canonical_preview_lines'
            THEN overlay_row.explicitly_user_unselected IS NOT TRUE
          ELSE false
        END,
        selection_state = CASE
          WHEN overlay_row.effective_section = 'canonical_preview_lines'
            THEN CASE
              WHEN overlay_row.explicitly_user_unselected IS TRUE THEN 'UNSELECTED'
              ELSE 'SELECTED'
            END
          ELSE 'NOT_SELECTABLE'
        END,
        row_json = pg_catalog.jsonb_strip_nulls(
          overlay_row.base_row_json
          || pg_catalog.jsonb_build_object(
            'case_components', overlay_row.allocated_case_components,
            'amount_ex_vat', -overlay_row.recoverable_amount_ex_vat,
            'preview_amount_ex_vat', -overlay_row.recoverable_amount_ex_vat,
            'amount_display', -overlay_row.recoverable_amount_ex_vat,
            'section_amount_ex_vat', -overlay_row.recoverable_amount_ex_vat,
            'section_amount_display', -overlay_row.recoverable_amount_ex_vat,
            'target_pay_ex_vat', -overlay_row.recoverable_amount_ex_vat,
            'ready_preview_amount_ex_vat', -overlay_row.recoverable_amount_ex_vat,
            'preview_component_amount_ex_vat', -overlay_row.recoverable_amount_ex_vat,
            'nominal_due_amount_ex_vat', overlay_row.nominal_due_amount_ex_vat,
            'recoverable_this_pay_run_ex_vat', overlay_row.recoverable_amount_ex_vat,
            'semantic_ordinary_positive_headroom_ex_vat', overlay_row.selected_positive_headroom_ex_vat,
            'retained_positive_headroom_ex_vat', overlay_row.selected_positive_headroom_ex_vat,
            'semantic_recovery_headroom_capped',
              overlay_row.recoverable_amount_ex_vat < overlay_row.nominal_due_amount_ex_vat,
            'effective_section', overlay_row.effective_section,
            'physical_section', overlay_row.physical_section,
            'readiness_state', CASE overlay_row.effective_section
              WHEN 'canonical_preview_lines' THEN 'READY_TO_PAY'
              WHEN 'cases_resolutions' THEN 'RESOLUTION_REQUIRED'
              ELSE 'BLOCKED_FOR_PAY'
            END,
            'presentation_section', CASE overlay_row.effective_section
              WHEN 'canonical_preview_lines' THEN 'READY_TO_PAY'
              WHEN 'cases_resolutions' THEN 'CASES_RESOLUTIONS'
              ELSE 'BLOCKED_FOR_PAY'
            END,
            'presentation_reason', CASE
              WHEN overlay_row.effective_section = 'canonical_preview_lines'
                THEN overlay_row.base_presentation_reason
              WHEN overlay_row.effective_section = 'cases_resolutions'
                THEN 'CASE_NEEDS_RESOLUTION'
              WHEN overlay_row.static_recovery_eligible THEN 'NO_PAY_HEADROOM'
              ELSE overlay_row.base_presentation_reason
            END,
            'draftable', overlay_row.effective_section = 'canonical_preview_lines',
            'is_ready_for_draft', overlay_row.effective_section = 'canonical_preview_lines',
            'selection_allowed', overlay_row.effective_section = 'canonical_preview_lines',
            'is_excluded_from_allocation', overlay_row.effective_section <> 'canonical_preview_lines',
            'selected', CASE
              WHEN overlay_row.effective_section = 'canonical_preview_lines'
                THEN overlay_row.explicitly_user_unselected IS NOT TRUE
              ELSE false
            END,
            'selection_state', CASE
              WHEN overlay_row.effective_section = 'canonical_preview_lines'
               AND overlay_row.explicitly_user_unselected IS NOT TRUE
                THEN 'SELECTED'
              WHEN overlay_row.effective_section = 'canonical_preview_lines' THEN 'UNSELECTED'
              ELSE 'NOT_SELECTABLE'
            END,
            'selection_origin', CASE
              WHEN overlay_row.effective_section = 'canonical_preview_lines'
               AND overlay_row.explicitly_user_unselected IS TRUE
                THEN 'USER_EXPLICIT_DESELECT'
              WHEN overlay_row.effective_section = 'canonical_preview_lines'
                THEN 'SERVER_DEFAULT_NEWLY_ELIGIBLE'
              ELSE COALESCE(overlay_row.base_row_json->>'selection_origin', 'SERVER_HEADROOM_BLOCKED')
            END,
            'blocked_reason_codes', CASE
              WHEN overlay_row.effective_section = 'canonical_preview_lines'
                THEN overlay_row.base_blocked_reason_codes
              WHEN overlay_row.static_recovery_eligible
                THEN overlay_row.base_blocked_reason_codes || pg_catalog.jsonb_build_array('NO_PAY_HEADROOM')
              ELSE overlay_row.base_blocked_reason_codes
            END,
            'case_is_blocked', overlay_row.effective_section <> 'canonical_preview_lines',
            'selection_recovery_headroom_v1', pg_catalog.jsonb_build_object(
              'contract_version', 1,
              'component_allocation_contract_version', 1,
              'candidate_id', p_candidate_id::text,
              'pay_channel', overlay_row.pay_channel,
              'physical_section', overlay_row.physical_section,
              'prior_physical_section', overlay_row.physical_section,
              'effective_section', overlay_row.effective_section,
              'selected_positive_headroom_ex_vat', overlay_row.selected_positive_headroom_ex_vat,
              'nominal_due_amount_ex_vat', overlay_row.nominal_due_amount_ex_vat,
              'recoverable_amount_ex_vat', overlay_row.recoverable_amount_ex_vat,
              'base_blocked_reason_codes', overlay_row.base_blocked_reason_codes,
              'base_presentation_reason', overlay_row.base_presentation_reason,
              'static_recovery_eligible', overlay_row.static_recovery_eligible,
              'actionable_restructure', overlay_row.actionable_restructure,
              'component_capacity_ex_vat', overlay_row.component_capacity_ex_vat,
              'component_recoverable_ex_vat', overlay_row.component_recoverable_ex_vat,
              'overlay_digest', overlay_row.row_overlay_digest,
              'reason', v_reason,
              'updated_at_utc', v_now::text,
              'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
            ),
            'case_resolution_summary', CASE
              WHEN pg_catalog.jsonb_typeof(overlay_row.case_resolution_summary_json) = 'object'
                THEN overlay_row.case_resolution_summary_json
                  || pg_catalog.jsonb_build_object('due_amount_ex_vat', overlay_row.recoverable_amount_ex_vat)
              ELSE pg_catalog.jsonb_build_object('due_amount_ex_vat', overlay_row.recoverable_amount_ex_vat)
            END,
            'case_resolution_summary_json', CASE
              WHEN pg_catalog.jsonb_typeof(overlay_row.case_resolution_summary_json) = 'object'
                THEN overlay_row.case_resolution_summary_json
                  || pg_catalog.jsonb_build_object('due_amount_ex_vat', overlay_row.recoverable_amount_ex_vat)
              ELSE pg_catalog.jsonb_build_object('due_amount_ex_vat', overlay_row.recoverable_amount_ex_vat)
            END
          )
          || CASE
            WHEN pg_catalog.jsonb_typeof(overlay_row.base_row_json->'row_json') = 'object'
              THEN pg_catalog.jsonb_build_object(
                'row_json', (overlay_row.base_row_json->'row_json')
                  || pg_catalog.jsonb_build_object(
                    'case_components', overlay_row.allocated_case_components
                  )
              )
            ELSE '{}'::jsonb
          END
          || CASE
            WHEN pg_catalog.jsonb_typeof(overlay_row.base_row_json->'case') = 'object'
              THEN pg_catalog.jsonb_build_object(
                'case', (overlay_row.base_row_json->'case')
                  || pg_catalog.jsonb_build_object(
                    'case_components', overlay_row.allocated_case_components
                  )
              )
            ELSE '{}'::jsonb
          END
          || CASE
            WHEN pg_catalog.jsonb_typeof(overlay_row.base_row_json->'raw_case') = 'object'
              THEN pg_catalog.jsonb_build_object(
                'raw_case', (overlay_row.base_row_json->'raw_case')
                  || pg_catalog.jsonb_build_object(
                    'case_components', overlay_row.allocated_case_components
                  )
              )
            ELSE '{}'::jsonb
          END
        ),
        updated_at_utc = v_now
    FROM pg_temp._bpay_recovery_selection_overlay AS overlay_row
    WHERE recovery_row.id = overlay_row.id
    RETURNING recovery_row.id,
              overlay_row.effective_section,
              overlay_row.current_selected,
              recovery_row.selected
  )
  SELECT pg_catalog.count(*)::integer,
         pg_catalog.count(*) FILTER (
           WHERE updated_rows.current_selected IS TRUE
             AND updated_rows.selected IS FALSE
         )::integer
  INTO v_updated_count, v_forced_deselected_count
  FROM updated_rows;

  SELECT COALESCE(
           pg_catalog.jsonb_agg(selected_row.id::text ORDER BY selected_row.row_ordinal, selected_row.id),
           '[]'::jsonb
         ),
         pg_catalog.count(*)::integer
  INTO v_selected_preview_row_ids,
       v_selected_row_count
  FROM public.banking_pay_workbench_preview_rows AS selected_row
  WHERE selected_row.session_id = p_session_id
    AND selected_row.session_version = v_session.version
    AND selected_row.status = 'READY'
    AND selected_row.selected IS TRUE
    AND pg_catalog.upper(pg_catalog.btrim(COALESCE(selected_row.selection_state, ''))) = 'SELECTED';

  v_session_ready := pg_catalog.lower(pg_catalog.btrim(COALESCE(
    v_session.progress_json->>'ready',
    v_session.progress_json->>'session_ready',
    v_session.progress_json->>'ready_flag',
    'false'
  ))) IN ('true', 't', '1', 'yes', 'y', 'on');

  SELECT COALESCE(
           pg_catalog.jsonb_agg(pg_catalog.to_jsonb(blocker.value) ORDER BY blocker.ordinality),
           '[]'::jsonb
         )
  INTO v_draft_blocker_codes
  FROM pg_catalog.jsonb_array_elements_text(
    CASE
      WHEN pg_catalog.jsonb_typeof(v_session.progress_json->'draft_blocker_codes') = 'array'
        THEN v_session.progress_json->'draft_blocker_codes'
      ELSE '[]'::jsonb
    END
  ) WITH ORDINALITY AS blocker(value, ordinality)
  WHERE pg_catalog.upper(pg_catalog.btrim(blocker.value)) <> 'NO_SELECTED_ROWS';

  IF v_session_ready AND COALESCE(v_selected_row_count, 0) = 0 THEN
    v_draft_blocker_codes := COALESCE(v_draft_blocker_codes, '[]'::jsonb)
      || pg_catalog.jsonb_build_array('NO_SELECTED_ROWS');
  END IF;

  UPDATE public.banking_pay_workbench_sessions AS session_update
  SET selected_row_count = COALESCE(v_selected_row_count, 0),
      server_selected_preview_row_ids = CASE
        WHEN COALESCE(session_update.server_selected_preview_row_ids_provided, false)
          THEN COALESCE(v_selected_preview_row_ids, '[]'::jsonb)
        ELSE session_update.server_selected_preview_row_ids
      END,
      progress_json = COALESCE(session_update.progress_json, '{}'::jsonb)
        || pg_catalog.jsonb_build_object(
          'selection_recovery_headroom_v1', pg_catalog.jsonb_build_object(
            'contract_version', 1,
            'candidate_id', p_candidate_id::text,
            'selected_positive_headroom_ex_vat', v_selected_positive_amount,
            'ready_recovery_count', v_ready_recovery_count,
            'case_recovery_count', v_case_recovery_count,
            'blocked_recovery_count', v_blocked_recovery_count,
            'recoverable_amount_ex_vat', v_ready_recovery_amount,
            'overlay_digest', v_overlay_digest,
            'reason', v_reason,
            'updated_at_utc', v_now::text
          ),
          'selected_row_count', COALESCE(v_selected_row_count, 0),
          'selected_eligible_ready_row_count', COALESCE(v_selected_row_count, 0),
          'selected_rows_available', COALESCE(v_selected_row_count, 0) > 0,
          'ready_for_draft', v_session_ready AND COALESCE(v_selected_row_count, 0) > 0,
          'can_create_draft', v_session_ready AND COALESCE(v_selected_row_count, 0) > 0,
          'draft_blocker_codes', COALESCE(v_draft_blocker_codes, '[]'::jsonb),
          'blocker_codes', COALESCE(v_draft_blocker_codes, '[]'::jsonb)
        ),
      updated_at_utc = v_now
  WHERE session_update.id = p_session_id;

  UPDATE public.banking_pay_workbench_session_scope AS scope_update
  SET certified_preview_publication_attestation_json = CASE
        WHEN v_scope.certified_preview_publication_attestation_json->>'attestation_version'
             = 'CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V3'
          THEN COALESCE(scope_update.certified_preview_publication_attestation_json, '{}'::jsonb)
            || pg_catalog.jsonb_build_object(
              'selection_recovery_headroom_v1', pg_catalog.jsonb_build_object(
                'contract_version', 1,
                'selected_positive_headroom_ex_vat', v_selected_positive_amount,
                'ready_recovery_count', v_ready_recovery_count,
                'case_recovery_count', v_case_recovery_count,
                'blocked_recovery_count', v_blocked_recovery_count,
                'recoverable_amount_ex_vat', v_ready_recovery_amount,
                'overlay_digest', v_overlay_digest,
                'reason', v_reason,
                'updated_at_utc', v_now::text
              )
            )
        ELSE scope_update.certified_preview_publication_attestation_json
      END,
      updated_at_utc = v_now
  WHERE scope_update.id = v_scope.id;

  RETURN pg_catalog.jsonb_build_object(
    'ok', true,
    'action', 'SELECTION_DEPENDENT_RECOVERY_HEADROOM_APPLIED',
    'session_id', p_session_id::text,
    'candidate_id', p_candidate_id::text,
    'recovery_row_count', v_recovery_row_count,
    'ready_recovery_count', v_ready_recovery_count,
    'case_recovery_count', v_case_recovery_count,
    'blocked_recovery_count', v_blocked_recovery_count,
    'forced_deselected_count', v_forced_deselected_count,
    'updated_count', v_updated_count,
    'selected_positive_headroom_ex_vat', v_selected_positive_amount,
    'recoverable_amount_ex_vat', v_ready_recovery_amount,
    'overlay_digest', v_overlay_digest,
    'physical_sections_changed', false,
    'source_rows_changed', false,
    'post_draft_artifacts_touched', false,
    'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
  );
END;
$function$;

-- private.pay_workbench_scope_invalidate_v1(uuid[],uuid[],text,uuid,jsonb)
CREATE OR REPLACE FUNCTION private.pay_workbench_scope_invalidate_v1(p_candidate_ids uuid[], p_timesheet_ids uuid[], p_reason text, p_scope_change_tx_token uuid DEFAULT NULL::uuid, p_payload_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_reason text := NULLIF(btrim(COALESCE(p_reason,'')), '');
  v_payload jsonb := COALESCE(p_payload_json,'{}'::jsonb);
  v_tx_token uuid;
  v_pair_count integer := 0;
  v_candidate_count integer := 0;
  v_timesheet_count integer := 0;
  v_registry_existing integer := 0;
  v_state_existing integer := 0;
  v_registry_affected integer := 0;
  v_state_affected integer := 0;
  v_job_inserted integer := 0;
  v_job_coalesced integer := 0;
  v_job_result jsonb;
  v_candidate record;
  v_source_change_seq bigint := 0;
  v_invalidation_at_utc timestamptz;
BEGIN
  IF jsonb_typeof(v_payload) <> 'object' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_INVALIDATION_INPUT_INVALID'
      USING ERRCODE='22023', DETAIL=jsonb_build_object(
        'code','PAY_WORKBENCH_SCOPE_INVALIDATION_INPUT_INVALID',
        'field','p_payload_json'
      )::text;
  END IF;

  IF v_reason IS NULL
     OR cardinality(COALESCE(p_candidate_ids,ARRAY[]::uuid[]))
        <> cardinality(COALESCE(p_timesheet_ids,ARRAY[]::uuid[])) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_INVALIDATION_INPUT_INVALID'
      USING ERRCODE='22023', DETAIL=jsonb_build_object(
        'code','PAY_WORKBENCH_SCOPE_INVALIDATION_INPUT_INVALID',
        'candidate_count',cardinality(COALESCE(p_candidate_ids,ARRAY[]::uuid[])),
        'timesheet_count',cardinality(COALESCE(p_timesheet_ids,ARRAY[]::uuid[]))
      )::text;
  END IF;

  CREATE TEMP TABLE IF NOT EXISTS pg_temp._bpay_wb_invalidation_pairs_v1(
    candidate_id uuid NOT NULL,
    timesheet_id uuid NULL,
    UNIQUE NULLS NOT DISTINCT(candidate_id,timesheet_id)
  ) ON COMMIT DROP;
  TRUNCATE pg_temp._bpay_wb_invalidation_pairs_v1;

  INSERT INTO pg_temp._bpay_wb_invalidation_pairs_v1(candidate_id,timesheet_id)
  SELECT candidate_id,timesheet_id
  FROM unnest(
    COALESCE(p_candidate_ids,ARRAY[]::uuid[]),
    COALESCE(p_timesheet_ids,ARRAY[]::uuid[])
  ) AS input_pair(candidate_id,timesheet_id)
  WHERE candidate_id IS NOT NULL
  ON CONFLICT DO NOTHING;

  GET DIAGNOSTICS v_pair_count = ROW_COUNT;
  IF v_pair_count = 0 THEN
    RETURN jsonb_build_object(
      'ok',true,'candidate_count',0,'timesheet_count',0,
      'registry_inserted_count',0,'registry_updated_count',0,
      'state_inserted_count',0,'state_updated_count',0,
      'job_inserted_count',0,'job_coalesced_count',0,
      'scope_change_tx_token',NULL,'reason',v_reason
    );
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_temp._bpay_wb_invalidation_pairs_v1 AS invalidation_pair
    LEFT JOIN public.candidates AS candidate_row
      ON candidate_row.id=invalidation_pair.candidate_id
    WHERE candidate_row.id IS NULL
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_INVALIDATION_OWNERSHIP_MISMATCH'
      USING ERRCODE='23503', DETAIL=jsonb_build_object(
        'code','PAY_WORKBENCH_SCOPE_INVALIDATION_OWNERSHIP_MISMATCH',
        'kind','CANDIDATE_NOT_FOUND'
      )::text;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_temp._bpay_wb_invalidation_pairs_v1 AS invalidation_pair
    LEFT JOIN public.timesheets AS timesheet_row
      ON timesheet_row.timesheet_id=invalidation_pair.timesheet_id
    WHERE invalidation_pair.timesheet_id IS NOT NULL
      AND (
        timesheet_row.timesheet_id IS NULL
        OR EXISTS (
          SELECT 1
          FROM public.timesheets_financials AS ownership_financial
          WHERE ownership_financial.timesheet_id=invalidation_pair.timesheet_id
            AND ownership_financial.is_current
            AND ownership_financial.candidate_id IS DISTINCT FROM invalidation_pair.candidate_id
        )
      )
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_INVALIDATION_OWNERSHIP_MISMATCH'
      USING ERRCODE='23503', DETAIL=jsonb_build_object(
        'code','PAY_WORKBENCH_SCOPE_INVALIDATION_OWNERSHIP_MISMATCH',
        'kind','TIMESHEET_CANDIDATE_MISMATCH'
      )::text;
  END IF;

  v_tx_token := COALESCE(p_scope_change_tx_token,public.pay_workbench_scope_change_tx_token_v1());
  IF NOT EXISTS (
    SELECT 1 FROM public.banking_pay_scope_change_transactions AS scope_tx
    WHERE scope_tx.tx_token=v_tx_token AND scope_tx.state='PENDING'
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_TRANSACTION_TOKEN_INVALID'
      USING ERRCODE='22023', DETAIL=jsonb_build_object(
        'code','PAY_WORKBENCH_SCOPE_TRANSACTION_TOKEN_INVALID',
        'scope_change_tx_token',v_tx_token
      )::text;
  END IF;

  SELECT count(DISTINCT candidate_id)::integer,
         count(DISTINCT timesheet_id) FILTER (WHERE timesheet_id IS NOT NULL)::integer
  INTO v_candidate_count,v_timesheet_count
  FROM pg_temp._bpay_wb_invalidation_pairs_v1;

  SELECT count(*)::integer INTO v_registry_existing
  FROM private.banking_pay_workbench_candidate_scope_registry AS registry
  WHERE registry.candidate_id IN (
    SELECT DISTINCT candidate_id FROM pg_temp._bpay_wb_invalidation_pairs_v1
  );

  -- Use one timestamp for every lifecycle column in the proposed inserts.
  -- PostgreSQL validates CHECK constraints on the proposed INSERT row before
  -- resolving ON CONFLICT, so separate clock_timestamp() calls can otherwise
  -- make created_at_utc a few microseconds later than last_dirtied/updated.
  v_invalidation_at_utc := clock_timestamp();
  v_source_change_seq := GREATEST(
    COALESCE(CASE WHEN COALESCE(v_payload->>'latest_source_change_seq','') ~ '^\d+$'
      THEN (v_payload->>'latest_source_change_seq')::bigint END,0),
    COALESCE(CASE WHEN COALESCE(v_payload->>'source_change_seq','') ~ '^\d+$'
      THEN (v_payload->>'source_change_seq')::bigint END,0),
    COALESCE(CASE WHEN COALESCE(v_payload->>'source_change_sequence','') ~ '^\d+$'
      THEN (v_payload->>'source_change_sequence')::bigint END,0)
  );

  INSERT INTO private.banking_pay_workbench_candidate_scope_registry AS registry(
    candidate_id,last_dirty_reason,last_scope_change_tx_token,
    current_source_change_seq,last_dirtied_at_utc,created_at_utc,updated_at_utc
  )
  SELECT DISTINCT candidate_id,v_reason,v_tx_token,v_source_change_seq,
         v_invalidation_at_utc,v_invalidation_at_utc,v_invalidation_at_utc
  FROM pg_temp._bpay_wb_invalidation_pairs_v1
  ORDER BY candidate_id
  ON CONFLICT(candidate_id) DO UPDATE
  SET last_dirty_reason=EXCLUDED.last_dirty_reason,
      last_scope_change_tx_token=EXCLUDED.last_scope_change_tx_token,
      current_source_change_seq=GREATEST(
        registry.current_source_change_seq,
        EXCLUDED.current_source_change_seq
      ),
      last_dirtied_at_utc=EXCLUDED.last_dirtied_at_utc,
      updated_at_utc=EXCLUDED.updated_at_utc;
  GET DIAGNOSTICS v_registry_affected = ROW_COUNT;

  SELECT count(*)::integer INTO v_state_existing
  FROM private.banking_pay_workbench_timesheet_scope_state AS scope_state
  WHERE scope_state.timesheet_id IN (
    SELECT timesheet_id FROM pg_temp._bpay_wb_invalidation_pairs_v1
    WHERE timesheet_id IS NOT NULL
  );

  INSERT INTO private.banking_pay_workbench_timesheet_scope_state AS scope_state(
    timesheet_id,candidate_id,economic_state,dirty_generation,
    last_dirty_reason,last_scope_change_tx_token,registered_at_utc,
    last_dirtied_at_utc,updated_at_utc
  )
  SELECT timesheet_id,candidate_id,'DIRTY',0,v_reason,v_tx_token,
         v_invalidation_at_utc,v_invalidation_at_utc,v_invalidation_at_utc
  FROM pg_temp._bpay_wb_invalidation_pairs_v1
  WHERE timesheet_id IS NOT NULL
  ORDER BY candidate_id,timesheet_id
  ON CONFLICT(timesheet_id) DO UPDATE
  SET candidate_id=EXCLUDED.candidate_id,
      economic_state='DIRTY',
      last_dirty_reason=EXCLUDED.last_dirty_reason,
      last_scope_change_tx_token=EXCLUDED.last_scope_change_tx_token,
      last_dirtied_at_utc=EXCLUDED.last_dirtied_at_utc,
      closed_at_utc=NULL,
      updated_at_utc=EXCLUDED.updated_at_utc;
  GET DIAGNOSTICS v_state_affected = ROW_COUNT;

  IF COALESCE((v_payload->>'skip_candidate_job_enqueue')::boolean,false) IS NOT TRUE THEN
    PERFORM set_config('cloudtms.bpay_scope_invalidator_active','true',true);
    FOR v_candidate IN
      SELECT candidate_id,
             COALESCE(array_agg(timesheet_id ORDER BY timesheet_id)
               FILTER (WHERE timesheet_id IS NOT NULL),ARRAY[]::uuid[]) AS timesheet_ids
      FROM pg_temp._bpay_wb_invalidation_pairs_v1
      GROUP BY candidate_id
      ORDER BY candidate_id
    LOOP
      v_job_result := public.pay_workbench_dirty_event_enqueue(
        p_job_type=>'WORKBENCH_CANDIDATE_DIRTY_APPLY',
        p_scope_kind=>'CANDIDATE',
        p_scope_id=>v_candidate.candidate_id::text,
        p_candidate_id=>v_candidate.candidate_id,
        p_targeted_timesheet_ids=>v_candidate.timesheet_ids,
        p_linked_timesheet_ids=>ARRAY[]::uuid[],
        p_payload_json=>v_payload || jsonb_build_object(
          'scope_change_tx_token',v_tx_token,
          'bounded_scope_state_precedes_job',true
        ),
        p_reason=>v_reason,
        p_priority=>COALESCE((v_payload->>'priority')::integer,-1000),
        p_run_at_utc=>clock_timestamp()
      );
      IF COALESCE(v_job_result->>'status','')='QUEUED' THEN
        v_job_inserted := v_job_inserted+1;
      ELSE
        v_job_coalesced := v_job_coalesced+1;
      END IF;
      IF COALESCE(v_job_result->>'latest_source_change_seq','') ~ '^\d+$' THEN
        v_source_change_seq := (v_job_result->>'latest_source_change_seq')::bigint;
        UPDATE private.banking_pay_workbench_candidate_scope_registry
        SET current_source_change_seq=GREATEST(current_source_change_seq,v_source_change_seq),
            updated_at_utc=clock_timestamp()
        WHERE candidate_id=v_candidate.candidate_id;
      END IF;
    END LOOP;
  END IF;

  RETURN jsonb_build_object(
    'ok',true,
    'candidate_count',v_candidate_count,
    'timesheet_count',v_timesheet_count,
    'registry_inserted_count',GREATEST(v_registry_affected-v_registry_existing,0),
    'registry_updated_count',LEAST(v_registry_existing,v_registry_affected),
    'state_inserted_count',GREATEST(v_state_affected-v_state_existing,0),
    'state_updated_count',LEAST(v_state_existing,v_state_affected),
    'job_inserted_count',v_job_inserted,
    'job_coalesced_count',v_job_coalesced,
    'scope_change_tx_token',v_tx_token,
    'reason',v_reason
  );
END;
$function$;

-- private.pay_workbench_sealed_rate_component_projection_v1(uuid,uuid,uuid[])
CREATE OR REPLACE FUNCTION private.pay_workbench_sealed_rate_component_projection_v1(p_build_id uuid, p_candidate_id uuid, p_timesheet_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS TABLE(build_id uuid, candidate_id uuid, timesheet_id uuid, financial_row_id uuid, source_family_key text, economic_key_type text, economic_key_value text, component_kind text, component_member_identity text, segment_id text, segment_key text, segment_stable_key text, bucket_code text, bucket_sort_ordinal integer, physical_bucket_key text, physical_bucket_digest text, source_units numeric, source_rate numeric, source_charge_rate numeric, truth_ex_vat numeric, baseline_ex_vat numeric, reserved_ex_vat numeric, outstanding_ex_vat numeric, source_charge_ex_vat numeric, source_pay_method text, target_pay_method text, umbrella_id uuid, umbrella_enabled boolean, umbrella_vat_chargeable boolean, erni_pct numeric, vat_rate_pct numeric, financial_revision_digest text, target_authority_digest text, conversion_context_digest text, sealed_evidence_digest text, projection_status text, failure_code text, evidence_json jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  WITH build_authority AS MATERIALIZED (
    SELECT build.id,build.candidate_id
    FROM private.banking_pay_workbench_economic_builds build
    WHERE build.id=p_build_id
  ), scoped_facts AS MATERIALIZED (
    SELECT fact.*,build.candidate_id AS build_candidate_id,
      fact.source_payload_json->'rate_authority' AS rate_authority
    FROM build_authority build
    JOIN private.banking_pay_workbench_economic_build_scope scope_row
      ON scope_row.build_id=build.id AND scope_row.candidate_id=build.candidate_id
    JOIN private.banking_pay_workbench_economic_build_facts fact
      ON fact.build_id=scope_row.build_id AND fact.timesheet_id=scope_row.timesheet_id
    WHERE build.candidate_id=p_candidate_id
      AND fact.fact_family='LIVE_ENTITLEMENT_INPUT'
      AND fact.source_relation<>'UNIT_PROJECTION'
      AND fact.timesheet_id IS NOT NULL
      AND (p_timesheet_ids IS NULL OR fact.timesheet_id=ANY(p_timesheet_ids))
  ), candidate_context_values AS MATERIALIZED (
    SELECT DISTINCT
      UPPER(NULLIF(BTRIM(fact.rate_authority#>>'{target,target_pay_method}'),''))
        AS target_pay_method,
      NULLIF(BTRIM(fact.rate_authority#>>'{target,target_authority_digest}'),'')
        AS target_authority_digest,
      NULLIF(BTRIM(fact.rate_authority#>>'{conversion,conversion_context_digest}'),'')
        AS conversion_context_digest,
      CASE WHEN COALESCE(fact.rate_authority#>>'{target,umbrella_id}','')
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN (fact.rate_authority#>>'{target,umbrella_id}')::uuid END AS umbrella_id,
      CASE WHEN jsonb_typeof(fact.rate_authority#>'{target,umbrella_enabled}')='boolean'
        THEN (fact.rate_authority#>>'{target,umbrella_enabled}')::boolean END
        AS umbrella_enabled,
      CASE WHEN jsonb_typeof(fact.rate_authority#>'{target,umbrella_vat_chargeable}')='boolean'
        THEN (fact.rate_authority#>>'{target,umbrella_vat_chargeable}')::boolean END
        AS umbrella_vat_chargeable,
      CASE WHEN COALESCE(fact.rate_authority#>>'{conversion,erni_pct}','')
          ~ '^-?\d+(\.\d+)?$'
        THEN ROUND((fact.rate_authority#>>'{conversion,erni_pct}')::numeric,6) END AS erni_pct,
      CASE WHEN COALESCE(fact.rate_authority#>>'{conversion,vat_rate_pct}','')
          ~ '^-?\d+(\.\d+)?$'
        THEN ROUND((fact.rate_authority#>>'{conversion,vat_rate_pct}')::numeric,6) END
        AS vat_rate_pct
    FROM scoped_facts fact
    WHERE jsonb_typeof(fact.rate_authority)='object'
      AND COALESCE(fact.rate_authority->>'rate_authority_version','')='1'
  ), candidate_sealed_context AS MATERIALIZED (
    SELECT MIN(context.target_pay_method) AS target_pay_method,
      MIN(context.target_authority_digest) AS target_authority_digest,
      MIN(context.conversion_context_digest) AS conversion_context_digest,
      MIN(context.umbrella_id::text)::uuid AS umbrella_id,
      BOOL_AND(context.umbrella_enabled) AS umbrella_enabled,
      BOOL_AND(context.umbrella_vat_chargeable) AS umbrella_vat_chargeable,
      MIN(context.erni_pct) AS erni_pct,MIN(context.vat_rate_pct) AS vat_rate_pct,
      CASE
        WHEN COUNT(*)=0 OR COUNT(context.target_authority_digest)=0
          OR COUNT(context.conversion_context_digest)=0
          THEN 'RATE_AUTHORITY_TARGET_AUTHORITY_NOT_SEALED'
        WHEN COUNT(DISTINCT context.target_authority_digest)<>1
          OR COUNT(DISTINCT context.conversion_context_digest)<>1
          OR COUNT(DISTINCT context.target_pay_method)<>1
          THEN 'RATE_AUTHORITY_TARGET_AUTHORITY_CONFLICT'
      END AS context_failure
    FROM candidate_context_values context
  ), occurrence_base AS MATERIALIZED (
    SELECT fact.*,
      CASE
        WHEN jsonb_typeof(fact.rate_authority)<>'object'
          THEN 'RATE_AUTHORITY_PAYLOAD_VERSION_UNSUPPORTED'
        WHEN jsonb_typeof(fact.rate_authority->'rate_authority_version')<>'number'
          THEN 'RATE_AUTHORITY_PAYLOAD_VERSION_UNSUPPORTED'
        WHEN COALESCE(fact.rate_authority->>'rate_authority_version','') !~ '^\d+$'
          THEN 'RATE_AUTHORITY_PAYLOAD_VERSION_UNSUPPORTED'
        WHEN (fact.rate_authority->>'rate_authority_version')::integer<>1
          THEN 'RATE_AUTHORITY_PAYLOAD_VERSION_UNSUPPORTED'
        WHEN fact.build_candidate_id IS DISTINCT FROM p_candidate_id
          OR COALESCE(fact.rate_authority#>>'{build,candidate_id}','')
            IS DISTINCT FROM p_candidate_id::text
          THEN 'RATE_AUTHORITY_CANDIDATE_MISMATCH'
        WHEN NULLIF(BTRIM(COALESCE(fact.source_payload_json->>'resolution_failure','')),'')
          IS NOT NULL
          THEN COALESCE(NULLIF(BTRIM(fact.rate_authority->>'failure_code'),''),
            NULLIF(BTRIM(fact.source_payload_json->>'resolution_failure'),''))
        WHEN jsonb_typeof(fact.rate_authority->'physical_buckets')<>'array'
          THEN 'RATE_AUTHORITY_PHYSICAL_IDENTITY_INCOMPLETE'
        WHEN jsonb_array_length(fact.rate_authority->'physical_buckets')=0
          THEN 'RATE_AUTHORITY_PHYSICAL_IDENTITY_INCOMPLETE'
      END AS occurrence_failure
    FROM scoped_facts fact
  ), bucket_base AS MATERIALIZED (
    SELECT occurrence.*,
      bucket.value AS bucket_json,bucket.ordinality::integer AS bucket_ordinality,
      NULLIF(BTRIM(bucket.value->>'physical_bucket_key'),'') AS parsed_physical_bucket_key,
      NULLIF(BTRIM(bucket.value->>'component_kind'),'') AS parsed_component_kind,
      NULLIF(BTRIM(bucket.value->>'component_member_identity'),'')
        AS parsed_component_member_identity,
      NULLIF(BTRIM(bucket.value->>'segment_id'),'') AS parsed_segment_id,
      NULLIF(BTRIM(bucket.value->>'segment_key'),'') AS parsed_segment_key,
      NULLIF(BTRIM(bucket.value->>'segment_stable_key'),'') AS parsed_segment_stable_key,
      UPPER(NULLIF(BTRIM(bucket.value->>'bucket_code'),'')) AS parsed_bucket_code,
      CASE WHEN COALESCE(bucket.value->>'bucket_sort_ordinal','') ~ '^\d+$'
        THEN (bucket.value->>'bucket_sort_ordinal')::integer END AS parsed_bucket_sort_ordinal,
      CASE WHEN COALESCE(bucket.value->>'source_units','') ~ '^-?\d+(\.\d+)?$'
        THEN ROUND((bucket.value->>'source_units')::numeric,6) END AS parsed_source_units,
      CASE WHEN COALESCE(bucket.value->>'source_rate','') ~ '^-?\d+(\.\d+)?$'
        THEN ROUND((bucket.value->>'source_rate')::numeric,6) END AS parsed_source_rate,
      CASE WHEN COALESCE(bucket.value->>'source_charge_rate','') ~ '^-?\d+(\.\d+)?$'
        THEN ROUND((bucket.value->>'source_charge_rate')::numeric,6) END
        AS parsed_source_charge_rate,
      CASE WHEN COALESCE(bucket.value->>'source_pay_ex_vat','') ~ '^-?\d+(\.\d+)?$'
        THEN ROUND((bucket.value->>'source_pay_ex_vat')::numeric,2) END
        AS parsed_source_pay_ex_vat,
      CASE WHEN COALESCE(bucket.value->>'source_charge_ex_vat','') ~ '^-?\d+(\.\d+)?$'
        THEN ROUND((bucket.value->>'source_charge_ex_vat')::numeric,2) END
        AS parsed_source_charge_ex_vat,
      CASE WHEN COALESCE(bucket.value->>'baseline_source_pay_ex_vat','') ~ '^-?\d+(\.\d+)?$'
        THEN ROUND((bucket.value->>'baseline_source_pay_ex_vat')::numeric,2) END
        AS parsed_baseline_ex_vat,
      CASE WHEN COALESCE(bucket.value->>'reserved_source_pay_ex_vat','') ~ '^-?\d+(\.\d+)?$'
        THEN ROUND((bucket.value->>'reserved_source_pay_ex_vat')::numeric,2) END
        AS parsed_reserved_ex_vat,
      CASE WHEN COALESCE(bucket.value->>'outstanding_source_pay_ex_vat','') ~ '^-?\d+(\.\d+)?$'
        THEN ROUND((bucket.value->>'outstanding_source_pay_ex_vat')::numeric,2) END
        AS parsed_outstanding_ex_vat,
      UPPER(NULLIF(BTRIM(occurrence.rate_authority#>>'{source,source_pay_method}'),''))
        AS parsed_source_pay_method,
      UPPER(NULLIF(BTRIM(occurrence.rate_authority#>>'{target,target_pay_method}'),''))
        AS parsed_target_pay_method
    FROM occurrence_base occurrence
    CROSS JOIN LATERAL jsonb_array_elements(
      CASE WHEN jsonb_typeof(occurrence.rate_authority->'physical_buckets')='array'
        THEN occurrence.rate_authority->'physical_buckets' ELSE '[]'::jsonb END
    ) WITH ORDINALITY bucket(value,ordinality)
  ), bucket_canonical AS MATERIALIZED (
    SELECT bucket.*,
      jsonb_build_object(
        -- Validate the serializer-owned sealed payload against its frozen V1
        -- canonical document.  The helper publishes a separate attributed V2
        -- document after baseline/reservation ownership has been resolved.
        'physical_bucket_version',1,
        'physical_bucket_key',bucket.parsed_physical_bucket_key,
        'component_kind',bucket.parsed_component_kind,
        'component_member_identity',bucket.parsed_component_member_identity,
        'bucket_code',bucket.parsed_bucket_code,
        'source_units',bucket.parsed_source_units,
        'source_rate',bucket.parsed_source_rate,
        'source_charge_rate',bucket.parsed_source_charge_rate,
        'source_pay_ex_vat',bucket.parsed_source_pay_ex_vat,
        'source_charge_ex_vat',bucket.parsed_source_charge_ex_vat,
        'baseline_source_pay_ex_vat',bucket.parsed_baseline_ex_vat,
        'reserved_source_pay_ex_vat',bucket.parsed_reserved_ex_vat,
        'outstanding_source_pay_ex_vat',bucket.parsed_outstanding_ex_vat,
        'source_pay_method',bucket.parsed_source_pay_method,
        'target_pay_method',bucket.parsed_target_pay_method) AS physical_canonical_json
    FROM bucket_base bucket
  ), occurrence_physical AS MATERIALIZED (
    SELECT canonical.natural_key,
      md5(COALESCE(jsonb_agg(canonical.physical_canonical_json ORDER BY
        canonical.parsed_bucket_sort_ordinal,canonical.parsed_physical_bucket_key)::text,'[]'))
        AS recomputed_physical_bucket_digest,
      ROUND(COALESCE(SUM(canonical.parsed_source_pay_ex_vat),0),2) AS physical_truth_ex_vat,
      ROUND(COALESCE(SUM(canonical.parsed_baseline_ex_vat),0),2) AS physical_baseline_ex_vat,
      ROUND(COALESCE(SUM(canonical.parsed_reserved_ex_vat),0),2) AS physical_reserved_ex_vat
    FROM bucket_canonical canonical
    GROUP BY canonical.natural_key
  ), baseline_totals AS MATERIALIZED (
    SELECT baseline.timesheet_id,UPPER(BTRIM(baseline.economic_key_type)) AS economic_key_type,
      BTRIM(baseline.economic_key_value) AS economic_key_value,
      ROUND(COALESCE(SUM(baseline.amount_ex_vat),0),2) AS baseline_ex_vat
    FROM private.banking_pay_workbench_economic_build_facts baseline
    JOIN build_authority build ON build.id=baseline.build_id
    WHERE baseline.fact_family IN ('FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK')
      AND baseline.candidate_id=p_candidate_id
      AND (p_timesheet_ids IS NULL OR baseline.timesheet_id=ANY(p_timesheet_ids))
    GROUP BY baseline.timesheet_id,UPPER(BTRIM(baseline.economic_key_type)),
      BTRIM(baseline.economic_key_value)
  ), sealed_finance_case_authority AS MATERIALIZED (
    SELECT fact.build_id,fact.candidate_id,fact.finance_case_id,
      COUNT(*)::integer AS evidence_count,
      COUNT(DISTINCT UPPER(NULLIF(BTRIM(fact.source_payload_json->>'case_type'),'')))::integer
        AS distinct_case_type_count,
      MIN(UPPER(NULLIF(BTRIM(fact.source_payload_json->>'case_type'),''))) AS case_type
    FROM private.banking_pay_workbench_economic_build_facts fact
    JOIN build_authority build ON build.id=fact.build_id
    WHERE fact.fact_family='FINANCE_CASE_IDENTITY'
      AND fact.candidate_id=p_candidate_id
      AND fact.finance_case_id IS NOT NULL
    GROUP BY fact.build_id,fact.candidate_id,fact.finance_case_id
  ), reservation_totals AS MATERIALIZED (
    SELECT reservation.timesheet_id,
      UPPER(BTRIM(reservation.economic_key_type)) AS economic_key_type,
      BTRIM(reservation.economic_key_value) AS economic_key_value,
      ROUND(COALESCE(SUM(CASE
        WHEN case_authority.evidence_count=1
          AND case_authority.distinct_case_type_count=1
          AND case_authority.case_type='OVERPAYMENT'
          THEN -ABS(COALESCE(reservation.reserved_source_amount,0))
        ELSE COALESCE(reservation.reserved_source_amount,0)
      END),0),2) AS reserved_ex_vat
    FROM private.banking_pay_workbench_economic_build_facts reservation
    JOIN build_authority build ON build.id=reservation.build_id
    LEFT JOIN sealed_finance_case_authority case_authority
      ON case_authority.build_id=reservation.build_id
     AND case_authority.candidate_id=reservation.candidate_id
     AND case_authority.finance_case_id=reservation.finance_case_id
    WHERE reservation.fact_family='RESERVATION_COMPONENT'
      AND reservation.candidate_id=p_candidate_id
      AND (p_timesheet_ids IS NULL OR reservation.timesheet_id=ANY(p_timesheet_ids))
    GROUP BY reservation.timesheet_id,UPPER(BTRIM(reservation.economic_key_type)),
      BTRIM(reservation.economic_key_value)
  ), entitlement_economic_domain AS MATERIALIZED (
    SELECT entitlement.timesheet_id,UPPER(BTRIM(entitlement.key_type)) AS economic_key_type,
      BTRIM(entitlement.key_value) AS economic_key_value,
      ROUND(COALESCE(SUM(entitlement.truth_ex_vat),0),2) AS truth_ex_vat,
      ROUND(COALESCE(SUM(entitlement.baseline_ex_vat),0),2) AS baseline_ex_vat,
      ROUND(COALESCE(SUM(entitlement.truth_inc_vat),SUM(entitlement.truth_ex_vat),0),2)
        AS truth_inc_vat,
      ROUND(COALESCE(SUM(entitlement.baseline_inc_vat),SUM(entitlement.baseline_ex_vat),0),2)
        AS baseline_inc_vat
    FROM private.pay_current_timesheet_entitlement_components_from_build_v1(
      p_build_id,NULL::text) entitlement
    WHERE entitlement.timesheet_id IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(entitlement.key_type,'')),'') IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(entitlement.key_value,'')),'') IS NOT NULL
      AND (p_timesheet_ids IS NULL OR entitlement.timesheet_id=ANY(p_timesheet_ids))
    GROUP BY entitlement.timesheet_id,UPPER(BTRIM(entitlement.key_type)),
      BTRIM(entitlement.key_value)
  ), economic_totals AS MATERIALIZED (
    SELECT domain.timesheet_id,domain.economic_key_type,domain.economic_key_value,
      domain.truth_ex_vat,domain.baseline_ex_vat,
      ROUND(COALESCE(reservation.reserved_ex_vat,0),2) AS reserved_ex_vat,
      domain.truth_inc_vat,domain.baseline_inc_vat
    FROM entitlement_economic_domain domain
    LEFT JOIN reservation_totals reservation
      USING(timesheet_id,economic_key_type,economic_key_value)
    UNION ALL
    SELECT reservation.timesheet_id,reservation.economic_key_type,
      reservation.economic_key_value,0::numeric AS truth_ex_vat,
      0::numeric AS baseline_ex_vat,reservation.reserved_ex_vat,
      0::numeric AS truth_inc_vat,0::numeric AS baseline_inc_vat
    FROM reservation_totals reservation
    WHERE NOT EXISTS(
      SELECT 1 FROM entitlement_economic_domain domain
      WHERE domain.timesheet_id=reservation.timesheet_id
        AND domain.economic_key_type=reservation.economic_key_type
        AND domain.economic_key_value=reservation.economic_key_value)
  ), occurrence_validated AS MATERIALIZED (
    SELECT occurrence.*,
      COALESCE(occurrence.occurrence_failure,
        CASE
          WHEN physical.recomputed_physical_bucket_digest IS DISTINCT FROM
            occurrence.rate_authority#>>'{economic,physical_bucket_digest}'
            THEN 'RATE_AUTHORITY_SEALED_DIGEST_MISMATCH'
          WHEN occurrence.rate_authority->>'sealed_evidence_digest' IS DISTINCT FROM
            md5(jsonb_build_object(
              'sealed_evidence_version',1,
              'financial_revision_digest',occurrence.rate_authority#>>'{source,financial_revision_digest}',
              'target_authority_digest',occurrence.rate_authority#>>'{target,target_authority_digest}',
              'conversion_context_digest',occurrence.rate_authority#>>'{conversion,conversion_context_digest}',
              'physical_bucket_digest',occurrence.rate_authority#>>'{economic,physical_bucket_digest}',
              'economic_key_type',occurrence.economic_key_type,
              'economic_key_value',occurrence.economic_key_value,
              'parent_source_pay_ex_vat',ROUND(occurrence.truth_ex_vat,2),
              'parent_source_charge_ex_vat',CASE
                WHEN COALESCE(occurrence.rate_authority#>>'{economic,parent_source_charge_ex_vat}','')
                  ~ '^-?\d+(\.\d+)?$'
                  THEN ROUND((occurrence.rate_authority#>>'{economic,parent_source_charge_ex_vat}')::numeric,2)
                ELSE NULL::numeric END,
              'source_pay_method',occurrence.rate_authority#>>'{source,source_pay_method}',
              'target_pay_method',occurrence.rate_authority#>>'{target,target_pay_method}')::text)
            THEN 'RATE_AUTHORITY_SEALED_DIGEST_MISMATCH'
        END) AS validated_failure
    FROM occurrence_base occurrence
    LEFT JOIN occurrence_physical physical USING(natural_key)
  ), bucket_validated AS MATERIALIZED (
    SELECT bucket.*,
      COALESCE(occurrence.validated_failure,
        CASE
          WHEN bucket.parsed_physical_bucket_key IS NULL
            OR bucket.parsed_component_kind IS NULL
            OR bucket.parsed_component_member_identity IS NULL
            OR bucket.parsed_bucket_code IS NULL
            OR bucket.parsed_bucket_sort_ordinal IS NULL
            THEN 'RATE_AUTHORITY_PHYSICAL_IDENTITY_INCOMPLETE'
          WHEN bucket.bucket_json->>'physical_bucket_digest'
            IS DISTINCT FROM md5(bucket.physical_canonical_json::text)
            THEN 'RATE_AUTHORITY_SEALED_DIGEST_MISMATCH'
        END) AS validated_failure
    FROM bucket_canonical bucket
    JOIN occurrence_validated occurrence USING(natural_key)
  ), physical_bucket_cardinality AS MATERIALIZED (
    SELECT bucket.timesheet_id,UPPER(BTRIM(bucket.economic_key_type)) AS economic_key_type,
      BTRIM(bucket.economic_key_value) AS economic_key_value,
      COUNT(DISTINCT bucket.parsed_physical_bucket_key)::integer AS physical_bucket_count
    FROM bucket_validated bucket
    WHERE bucket.validated_failure IS NULL
    GROUP BY bucket.timesheet_id,UPPER(BTRIM(bucket.economic_key_type)),
      BTRIM(bucket.economic_key_value)
  ), sealed_parent_facts AS MATERIALIZED (
    SELECT fact.fact_family||':'||fact.natural_key AS fact_identity,
      CASE WHEN fact.fact_family='RESERVATION_COMPONENT' THEN 'RESERVATION'
        ELSE 'BASELINE' END AS authority_kind,
      fact.timesheet_id,UPPER(BTRIM(fact.economic_key_type)) AS economic_key_type,
      BTRIM(fact.economic_key_value) AS economic_key_value,
      ROUND(CASE WHEN fact.fact_family='RESERVATION_COMPONENT'
          AND case_authority.evidence_count=1
          AND case_authority.distinct_case_type_count=1
          AND case_authority.case_type='OVERPAYMENT'
        THEN -ABS(COALESCE(fact.reserved_source_amount,0))
        WHEN fact.fact_family='RESERVATION_COMPONENT'
        THEN COALESCE(fact.reserved_source_amount,0)
        ELSE COALESCE(fact.amount_ex_vat,0) END,2) AS parent_amount_ex_vat,
      CASE WHEN fact.fact_family='RESERVATION_COMPONENT' THEN NULL::numeric
        WHEN COALESCE(
          fact.source_payload_json#>>'{pay_batch_item,frozen_source_basis_json,source_charge_ex_vat}',
          fact.source_payload_json#>>'{pay_batch_item,frozen_component_snapshot_json,source_basis_json,source_charge_ex_vat}',
          fact.source_payload_json#>>'{pay_batch_item,frozen_resolution_result_json,source_charge_ex_vat}',
          fact.source_payload_json#>>'{frozen_source_basis_json,source_charge_ex_vat}',
          fact.source_payload_json#>>'{frozen_component_snapshot_json,source_basis_json,source_charge_ex_vat}',
          fact.source_payload_json#>>'{frozen_resolution_result_json,source_charge_ex_vat}','')
            ~ '^-?\d+(\.\d+)?$'
          THEN ROUND(COALESCE(
            fact.source_payload_json#>>'{pay_batch_item,frozen_source_basis_json,source_charge_ex_vat}',
            fact.source_payload_json#>>'{pay_batch_item,frozen_component_snapshot_json,source_basis_json,source_charge_ex_vat}',
            fact.source_payload_json#>>'{pay_batch_item,frozen_resolution_result_json,source_charge_ex_vat}',
            fact.source_payload_json#>>'{frozen_source_basis_json,source_charge_ex_vat}',
            fact.source_payload_json#>>'{frozen_component_snapshot_json,source_basis_json,source_charge_ex_vat}',
            fact.source_payload_json#>>'{frozen_resolution_result_json,source_charge_ex_vat}')::numeric,2)
        END AS parent_source_charge_ex_vat,
      fact.source_payload_json,fact.financial_digest,
      UPPER(NULLIF(BTRIM(COALESCE(
        fact.source_payload_json#>>'{pay_batch_item,frozen_source_pay_method}',
        fact.source_payload_json->>'frozen_source_pay_method')),'')) AS sealed_source_pay_method,
      COALESCE(UPPER(NULLIF(BTRIM(fact.source_payload_json->>'item_type'),'')),
        CASE WHEN fact.fact_family='RESERVATION_COMPONENT'
            AND case_authority.evidence_count=1
            AND case_authority.distinct_case_type_count=1
            AND case_authority.case_type='OVERPAYMENT'
          THEN 'OVERPAYMENT_RECOVERY' END) AS parent_item_type,
      COALESCE(UPPER(NULLIF(BTRIM(fact.source_payload_json->>'key_resolution_source'),'')),
        CASE WHEN fact.fact_family='RESERVATION_COMPONENT'
            AND case_authority.evidence_count=1
            AND case_authority.distinct_case_type_count=1
            AND case_authority.case_type='OVERPAYMENT'
          THEN 'FINANCE_CASE_IDENTITY' END) AS key_resolution_source,
      (UPPER(NULLIF(BTRIM(fact.source_payload_json->>'item_type'),''))='OVERPAYMENT_RECOVERY'
          AND UPPER(NULLIF(BTRIM(fact.source_payload_json->>'key_resolution_source'),''))=
            'FINANCE_ITEM_AUTHORITY')
        OR (fact.fact_family='RESERVATION_COMPONENT'
          AND case_authority.evidence_count=1
          AND case_authority.distinct_case_type_count=1
          AND case_authority.case_type='OVERPAYMENT') AS is_signed_non_charge_recovery
    FROM private.banking_pay_workbench_economic_build_facts fact
    JOIN build_authority build ON build.id=fact.build_id
    LEFT JOIN sealed_finance_case_authority case_authority
      ON case_authority.build_id=fact.build_id
     AND case_authority.candidate_id=fact.candidate_id
     AND case_authority.finance_case_id=fact.finance_case_id
    WHERE fact.fact_family IN ('FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK',
        'RESERVATION_COMPONENT')
      AND fact.candidate_id=p_candidate_id AND fact.timesheet_id IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(fact.economic_key_type,'')),'') IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(fact.economic_key_value,'')),'') IS NOT NULL
      AND (p_timesheet_ids IS NULL OR fact.timesheet_id=ANY(p_timesheet_ids))
  ), allocative_parent_facts AS MATERIALIZED (
    SELECT parent.*
    FROM sealed_parent_facts parent
    WHERE parent.is_signed_non_charge_recovery IS NOT TRUE
  ), nested_evidence_shape_failures AS MATERIALIZED (
    SELECT parent.fact_identity,
      'RATE_AUTHORITY_NESTED_EVIDENCE_INVALID'::text AS failure_code
    FROM allocative_parent_facts parent
    WHERE (parent.source_payload_json#>'{pay_batch_item,frozen_resolution_payload_json,case_components}' IS NOT NULL
        AND jsonb_typeof(parent.source_payload_json#>'{pay_batch_item,frozen_resolution_payload_json,case_components}')<>'array')
       OR (parent.source_payload_json#>'{pay_batch_item,frozen_resolution_payload_json,correction_chain_component,resolution_rows}' IS NOT NULL
        AND jsonb_typeof(parent.source_payload_json#>'{pay_batch_item,frozen_resolution_payload_json,correction_chain_component,resolution_rows}')<>'array')
       OR (parent.source_payload_json#>'{pay_batch_item,frozen_source_basis_json,correction_chain_residual,components}' IS NOT NULL
        AND jsonb_typeof(parent.source_payload_json#>'{pay_batch_item,frozen_source_basis_json,correction_chain_residual,components}')<>'array')
       OR (parent.source_payload_json#>'{pay_batch_item,frozen_component_snapshot_json,correction_chain_residual,components}' IS NOT NULL
        AND jsonb_typeof(parent.source_payload_json#>'{pay_batch_item,frozen_component_snapshot_json,correction_chain_residual,components}')<>'array')
       OR (parent.source_payload_json#>'{pay_batch_item,frozen_resolution_payload_json,correction_chain_residual,components}' IS NOT NULL
        AND jsonb_typeof(parent.source_payload_json#>'{pay_batch_item,frozen_resolution_payload_json,correction_chain_residual,components}')<>'array')
    UNION
    SELECT parent.fact_identity,'RATE_AUTHORITY_NESTED_EVIDENCE_INVALID'::text
    FROM allocative_parent_facts parent
    CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(
      parent.source_payload_json#>'{pay_batch_item,frozen_resolution_payload_json,case_components}')='array'
      THEN parent.source_payload_json#>'{pay_batch_item,frozen_resolution_payload_json,case_components}'
      ELSE '[]'::jsonb END) component(value)
    WHERE component.value#>'{saved_resolution_payload_json,bucket_resolutions}' IS NOT NULL
      AND jsonb_typeof(component.value#>'{saved_resolution_payload_json,bucket_resolutions}')<>'array'
    UNION
    SELECT parent.fact_identity,'RATE_AUTHORITY_NESTED_EVIDENCE_INVALID'::text
    FROM allocative_parent_facts parent
    CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(
      parent.source_payload_json#>'{pay_batch_item,frozen_resolution_payload_json,correction_chain_component,resolution_rows}')='array'
      THEN parent.source_payload_json#>'{pay_batch_item,frozen_resolution_payload_json,correction_chain_component,resolution_rows}'
      ELSE '[]'::jsonb END) resolution(value)
    WHERE resolution.value#>'{payload_json,bucket_resolutions}' IS NOT NULL
      AND jsonb_typeof(resolution.value#>'{payload_json,bucket_resolutions}')<>'array'
  ), nested_evidence_raw AS MATERIALIZED (
    SELECT parent.*, 'TOP_LEVEL_SOURCE_BASIS'::text AS evidence_origin,
      NULL::text AS evidence_container_identity,basis.source_basis_json AS evidence_json
    FROM allocative_parent_facts parent
    CROSS JOIN LATERAL (
      SELECT source_basis_json
      FROM (VALUES
        (CASE WHEN jsonb_typeof(parent.source_payload_json#>'{pay_batch_item,frozen_source_basis_json}')='object'
          THEN parent.source_payload_json#>'{pay_batch_item,frozen_source_basis_json}' END),
        (CASE WHEN jsonb_typeof(parent.source_payload_json#>'{pay_batch_item,frozen_component_snapshot_json,source_basis_json}')='object'
          THEN parent.source_payload_json#>'{pay_batch_item,frozen_component_snapshot_json,source_basis_json}' END),
        (CASE WHEN jsonb_typeof(parent.source_payload_json->'frozen_source_basis_json')='object'
          THEN parent.source_payload_json->'frozen_source_basis_json' END),
        (CASE WHEN jsonb_typeof(parent.source_payload_json#>'{frozen_component_snapshot_json,source_basis_json}')='object'
          THEN parent.source_payload_json#>'{frozen_component_snapshot_json,source_basis_json}' END)
      ) basis_values(source_basis_json)
    ) basis
    WHERE basis.source_basis_json IS NOT NULL AND basis.source_basis_json<>'{}'::jsonb
    UNION ALL
    SELECT parent.*,'CASE_COMPONENT',COALESCE(NULLIF(component.value->>'source_basis_fingerprint',''),
      md5(component.value::text)),component.value
    FROM allocative_parent_facts parent
    CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(
      parent.source_payload_json#>'{pay_batch_item,frozen_resolution_payload_json,case_components}')='array'
      THEN parent.source_payload_json#>'{pay_batch_item,frozen_resolution_payload_json,case_components}'
      ELSE '[]'::jsonb END) component(value)
    UNION ALL
    SELECT parent.*,'CASE_BUCKET_RESOLUTION',COALESCE(
      NULLIF(component.value->>'source_basis_fingerprint',''),md5(component.value::text)),bucket.value
    FROM allocative_parent_facts parent
    CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(
      parent.source_payload_json#>'{pay_batch_item,frozen_resolution_payload_json,case_components}')='array'
      THEN parent.source_payload_json#>'{pay_batch_item,frozen_resolution_payload_json,case_components}'
      ELSE '[]'::jsonb END) component(value)
    CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(
      component.value#>'{saved_resolution_payload_json,bucket_resolutions}')='array'
      THEN component.value#>'{saved_resolution_payload_json,bucket_resolutions}'
      ELSE '[]'::jsonb END) bucket(value)
    UNION ALL
    SELECT parent.*,'CORRECTION_BUCKET_RESOLUTION',COALESCE(
      NULLIF(resolution.value->>'source_basis_fingerprint',''),md5(resolution.value::text)),bucket.value
    FROM allocative_parent_facts parent
    CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(
      parent.source_payload_json#>'{pay_batch_item,frozen_resolution_payload_json,correction_chain_component,resolution_rows}')='array'
      THEN parent.source_payload_json#>'{pay_batch_item,frozen_resolution_payload_json,correction_chain_component,resolution_rows}'
      ELSE '[]'::jsonb END) resolution(value)
    CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(
      resolution.value#>'{payload_json,bucket_resolutions}')='array'
      THEN resolution.value#>'{payload_json,bucket_resolutions}' ELSE '[]'::jsonb END) bucket(value)
    UNION ALL
    SELECT parent.*,'SOURCE_BASIS_CORRECTION_RESIDUAL',NULL::text,residual.value
    FROM allocative_parent_facts parent
    CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(
      parent.source_payload_json#>'{pay_batch_item,frozen_source_basis_json,correction_chain_residual,components}')='array'
      THEN parent.source_payload_json#>'{pay_batch_item,frozen_source_basis_json,correction_chain_residual,components}'
      ELSE '[]'::jsonb END) residual(value)
    UNION ALL
    SELECT parent.*,'SNAPSHOT_CORRECTION_RESIDUAL',NULL::text,residual.value
    FROM allocative_parent_facts parent
    CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(
      parent.source_payload_json#>'{pay_batch_item,frozen_component_snapshot_json,correction_chain_residual,components}')='array'
      THEN parent.source_payload_json#>'{pay_batch_item,frozen_component_snapshot_json,correction_chain_residual,components}'
      ELSE '[]'::jsonb END) residual(value)
    UNION ALL
    SELECT parent.*,'RESOLUTION_CORRECTION_RESIDUAL',NULL::text,residual.value
    FROM allocative_parent_facts parent
    CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(
      parent.source_payload_json#>'{pay_batch_item,frozen_resolution_payload_json,correction_chain_residual,components}')='array'
      THEN parent.source_payload_json#>'{pay_batch_item,frozen_resolution_payload_json,correction_chain_residual,components}'
      ELSE '[]'::jsonb END) residual(value)
  ), nested_evidence_parsed AS MATERIALIZED (
    SELECT raw.*,
      CASE WHEN jsonb_typeof(raw.evidence_json->'source_basis_json')='object'
        THEN raw.evidence_json->'source_basis_json' ELSE raw.evidence_json END AS source_basis_json,
      NULLIF(BTRIM(COALESCE(raw.evidence_json->>'physical_bucket_key',
        raw.evidence_json#>>'{source_basis_json,physical_bucket_key}')),'') AS direct_physical_bucket_key,
      NULLIF(BTRIM(COALESCE(raw.evidence_json->>'component_member_identity',
        raw.evidence_json#>>'{source_basis_json,component_member_identity}')),'')
        AS direct_component_member_identity,
      NULLIF(BTRIM(COALESCE(raw.evidence_json->>'source_family_key',
        raw.evidence_json#>>'{source_basis_json,source_family_key}',
        raw.evidence_json#>>'{source_basis_json,represented_source_family_key}')),'')
        AS direct_source_family_key,
      NULLIF(BTRIM(COALESCE(raw.evidence_json->>'source_basis_fingerprint',
        raw.evidence_json#>>'{source_basis_json,source_basis_fingerprint}')),'')
        AS source_basis_fingerprint,
      NULLIF(BTRIM(COALESCE(raw.evidence_json->>'component_fingerprint',
        raw.evidence_json#>>'{source_basis_json,component_fingerprint}')),'')
        AS component_fingerprint,
      UPPER(NULLIF(BTRIM(COALESCE(raw.evidence_json->>'source_pay_method',
        raw.evidence_json#>>'{source_basis_json,source_pay_method}')),''))
        AS evidence_source_pay_method,
      UPPER(NULLIF(BTRIM(COALESCE(raw.evidence_json->>'component_fallback',
        raw.evidence_json#>>'{source_basis_json,component_fallback}')),''))
        AS component_fallback
    FROM nested_evidence_raw raw
  ), source_method_evidence AS MATERIALIZED (
    SELECT occurrence.timesheet_id,
      UPPER(BTRIM(occurrence.economic_key_type)) AS economic_key_type,
      BTRIM(occurrence.economic_key_value) AS economic_key_value,
      NULLIF(BTRIM(occurrence.rate_authority#>>'{source,source_pay_method}'),'')
        AS raw_source_pay_method,
      UPPER(NULLIF(BTRIM(occurrence.rate_authority#>>'{source,source_pay_method}'),''))
        AS normalized_source_pay_method,
      10::integer AS authority_priority,
      'LIVE_OCCURRENCE'::text AS evidence_kind,
      occurrence.natural_key AS evidence_identity
    FROM occurrence_validated occurrence
    WHERE occurrence.validated_failure IS NULL
      AND NULLIF(BTRIM(COALESCE(occurrence.economic_key_type,'')),'') IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(occurrence.economic_key_value,'')),'') IS NOT NULL
    UNION ALL
    SELECT parent.timesheet_id,parent.economic_key_type,parent.economic_key_value,
      NULLIF(BTRIM(parent.sealed_source_pay_method),''),
      UPPER(NULLIF(BTRIM(parent.sealed_source_pay_method),'')),
      20::integer,
      'SEALED_PARENT',parent.fact_identity
    FROM sealed_parent_facts parent
    UNION ALL
    SELECT nested.timesheet_id,nested.economic_key_type,nested.economic_key_value,
      NULLIF(BTRIM(nested.evidence_source_pay_method),''),
      UPPER(NULLIF(BTRIM(nested.evidence_source_pay_method),'')),
      20::integer,
      'NESTED_'||nested.evidence_origin,
      nested.fact_identity||':'||COALESCE(nested.evidence_container_identity,
        md5(nested.evidence_json::text))
    FROM nested_evidence_parsed nested
  ), source_method_evidence_documents AS MATERIALIZED (
    SELECT evidence.*,
      jsonb_build_object(
        'authority_priority',evidence.authority_priority,
        'evidence_kind',evidence.evidence_kind,
        'evidence_identity',evidence.evidence_identity,
        'source_pay_method',evidence.normalized_source_pay_method) AS evidence_document
    FROM source_method_evidence evidence
  ), source_method_authority_tier AS MATERIALIZED (
    SELECT evidence.timesheet_id,evidence.economic_key_type,evidence.economic_key_value,
      MIN(evidence.authority_priority)::integer AS selected_authority_priority
    FROM source_method_evidence_documents evidence
    GROUP BY evidence.timesheet_id,evidence.economic_key_type,evidence.economic_key_value
  ), source_method_authority_summary AS MATERIALIZED (
    SELECT evidence.timesheet_id,evidence.economic_key_type,evidence.economic_key_value,
      COUNT(*)::integer AS total_evidence_count,
      COUNT(*) FILTER(WHERE evidence.authority_priority=tier.selected_authority_priority)::integer
        AS selected_evidence_count,
      tier.selected_authority_priority,
      COUNT(*) FILTER(WHERE evidence.authority_priority=tier.selected_authority_priority
        AND evidence.normalized_source_pay_method IN ('PAYE','UMBRELLA'))::integer
        AS supported_method_evidence_count,
      COUNT(*) FILTER(WHERE evidence.authority_priority=tier.selected_authority_priority
        AND evidence.raw_source_pay_method IS NOT NULL
        AND evidence.normalized_source_pay_method NOT IN ('PAYE','UMBRELLA'))::integer
        AS invalid_method_count,
      COUNT(DISTINCT evidence.normalized_source_pay_method) FILTER(
        WHERE evidence.authority_priority=tier.selected_authority_priority
          AND evidence.normalized_source_pay_method IN ('PAYE','UMBRELLA'))::integer
        AS distinct_supported_source_method_count,
      CASE WHEN COUNT(*) FILTER(WHERE evidence.authority_priority=tier.selected_authority_priority
          AND evidence.raw_source_pay_method IS NOT NULL
          AND evidence.normalized_source_pay_method NOT IN ('PAYE','UMBRELLA'))=0
          AND COUNT(DISTINCT evidence.normalized_source_pay_method) FILTER(
            WHERE evidence.authority_priority=tier.selected_authority_priority
              AND evidence.normalized_source_pay_method IN ('PAYE','UMBRELLA'))=1
        THEN (jsonb_agg(DISTINCT evidence.normalized_source_pay_method
          ORDER BY evidence.normalized_source_pay_method) FILTER(
            WHERE evidence.authority_priority=tier.selected_authority_priority
              AND evidence.normalized_source_pay_method IN ('PAYE','UMBRELLA'))->>0)
      END AS authoritative_source_pay_method,
      pg_catalog.encode(extensions.digest(pg_catalog.convert_to(
        COALESCE(jsonb_agg(evidence.evidence_document ORDER BY evidence.evidence_kind,
          evidence.evidence_identity),'[]'::jsonb)::text,'UTF8'),'sha256'),'hex')
        AS complete_evidence_digest
    FROM source_method_evidence_documents evidence
    JOIN source_method_authority_tier tier
      USING(timesheet_id,economic_key_type,economic_key_value)
    GROUP BY evidence.timesheet_id,evidence.economic_key_type,evidence.economic_key_value,
      tier.selected_authority_priority
  ), source_method_authority AS MATERIALIZED (
    SELECT summary.*,
      CASE
        WHEN summary.invalid_method_count>0
          THEN 'RATE_AUTHORITY_SOURCE_PAY_METHOD_MISSING'
        WHEN summary.distinct_supported_source_method_count=0
          THEN 'RATE_AUTHORITY_SOURCE_PAY_METHOD_MISSING'
        WHEN summary.distinct_supported_source_method_count>1
          THEN 'RATE_AUTHORITY_SOURCE_PAY_METHOD_CONFLICT'
      END AS failure_code,
      jsonb_build_object(
        'authority_contract_version',1,
        'total_evidence_count',summary.total_evidence_count,
        'selected_evidence_count',summary.selected_evidence_count,
        'selected_authority_priority',summary.selected_authority_priority,
        'supported_method_evidence_count',summary.supported_method_evidence_count,
        'invalid_method_count',summary.invalid_method_count,
        'distinct_supported_source_method_count',
          summary.distinct_supported_source_method_count,
        'authoritative_source_pay_method',CASE
          WHEN summary.invalid_method_count=0
            AND summary.distinct_supported_source_method_count=1
            THEN summary.authoritative_source_pay_method END,
        'complete_evidence_digest',summary.complete_evidence_digest,
        'sample_truncated',summary.total_evidence_count>25,
        'evidence_sample',COALESCE((
          SELECT jsonb_agg(sample.evidence_document ORDER BY sample.authority_priority,
            sample.evidence_kind,sample.evidence_identity)
          FROM (
            SELECT evidence.evidence_document,evidence.authority_priority,evidence.evidence_kind,
              evidence.evidence_identity
            FROM source_method_evidence_documents evidence
            WHERE evidence.timesheet_id=summary.timesheet_id
              AND evidence.economic_key_type=summary.economic_key_type
              AND evidence.economic_key_value=summary.economic_key_value
            ORDER BY evidence.authority_priority,evidence.evidence_kind,evidence.evidence_identity
            LIMIT 25
          ) sample
        ),'[]'::jsonb)) AS evidence_json
    FROM source_method_authority_summary summary
  ), nested_evidence_normalized AS MATERIALIZED (
    SELECT parsed.*,
      CASE
        WHEN parsed.direct_physical_bucket_key IS NOT NULL THEN 10
        WHEN parsed.evidence_origin='CASE_COMPONENT' THEN 20
        WHEN parsed.evidence_origin IN ('CASE_BUCKET_RESOLUTION','CORRECTION_BUCKET_RESOLUTION')
          THEN 30
        ELSE 40 END AS evidence_priority,
      COALESCE(parsed.direct_source_family_key,'timesheet:'||parsed.timesheet_id::text)
        AS source_family_key,
      COALESCE(parsed.direct_component_member_identity,
        CASE
          WHEN parsed.component_fallback='WORKED_TIME_AMOUNT'
            THEN 'worked-time-residual:'||parsed.economic_key_type||':'||parsed.economic_key_value
          WHEN parsed.economic_key_type IN ('TS_DAY','TS_TOTAL') THEN COALESCE(
            NULLIF(BTRIM(parsed.source_basis_json->>'segment_stable_key'),''),
            NULLIF(BTRIM(parsed.source_basis_json->>'segment_id'),''),
            NULLIF(BTRIM(parsed.source_basis_json->>'segment_key'),''))
          WHEN parsed.economic_key_type='ADDITIONAL_CODE'
            THEN 'additional:'||UPPER(parsed.economic_key_value)
          WHEN parsed.economic_key_type='EXPENSE_CODE'
            THEN 'expense:'||UPPER(parsed.economic_key_value)
          WHEN parsed.economic_key_type='ADJUSTMENT_CODE'
            THEN 'adjustment:'||parsed.economic_key_value
        END) AS component_member_identity,
      UPPER(COALESCE(CASE WHEN parsed.component_fallback='WORKED_TIME_AMOUNT'
          THEN 'FIXED' END,
        NULLIF(BTRIM(parsed.evidence_json->>'bucket_code'),''),
        NULLIF(BTRIM(parsed.source_basis_json->>'bucket_code'),''),
        CASE WHEN UPPER(BTRIM(COALESCE(parsed.source_basis_json->>'band','')))
          IN ('DAY','NIGHT','SAT','SUN','BH')
          THEN UPPER(BTRIM(parsed.source_basis_json->>'band')) END,
        CASE parsed.economic_key_type WHEN 'ADDITIONAL_CODE' THEN 'ADDITIONAL'
          WHEN 'EXPENSE_CODE' THEN 'FIXED' WHEN 'ADJUSTMENT_CODE' THEN 'FIXED' END))
        AS bucket_code,
      NULLIF(BTRIM(COALESCE(parsed.evidence_json->>'segment_id',
        parsed.source_basis_json->>'segment_id')),'') AS segment_id,
      COALESCE(NULLIF(BTRIM(COALESCE(parsed.evidence_json->>'segment_key',
        parsed.source_basis_json->>'segment_key')),''),
        NULLIF(BTRIM(COALESCE(parsed.evidence_json->>'segment_id',
          parsed.source_basis_json->>'segment_id')),'')) AS segment_key,
      NULLIF(BTRIM(COALESCE(parsed.evidence_json->>'segment_stable_key',
        parsed.source_basis_json->>'segment_stable_key')),'') AS segment_stable_key,
      CASE WHEN COALESCE(parsed.evidence_json->>'source_units',
          parsed.source_basis_json->>'source_units','') ~ '^-?\d+(\.\d+)?$'
        THEN ROUND(COALESCE(parsed.evidence_json->>'source_units',
          parsed.source_basis_json->>'source_units')::numeric,6) END AS source_units,
      CASE WHEN COALESCE(parsed.evidence_json->>'source_rate',
          parsed.source_basis_json->>'source_rate','') ~ '^-?\d+(\.\d+)?$'
        THEN ROUND(COALESCE(parsed.evidence_json->>'source_rate',
          parsed.source_basis_json->>'source_rate')::numeric,6) END AS source_rate,
      CASE WHEN COALESCE(parsed.evidence_json->>'source_charge_rate',
          parsed.source_basis_json->>'source_charge_rate','') ~ '^-?\d+(\.\d+)?$'
        THEN ROUND(COALESCE(parsed.evidence_json->>'source_charge_rate',
          parsed.source_basis_json->>'source_charge_rate')::numeric,6) END
        AS source_charge_rate,
      CASE WHEN COALESCE(parsed.evidence_json->>'source_charge_ex_vat',
          parsed.source_basis_json->>'source_charge_ex_vat','') ~ '^-?\d+(\.\d+)?$'
        THEN ROUND(COALESCE(parsed.evidence_json->>'source_charge_ex_vat',
          parsed.source_basis_json->>'source_charge_ex_vat')::numeric,2) END
        AS source_charge_ex_vat,
      CASE
        WHEN COALESCE(parsed.evidence_json->>'component_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$'
          THEN ROUND((parsed.evidence_json->>'component_amount_ex_vat')::numeric,2)
        WHEN COALESCE(parsed.evidence_json->>'source_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$'
          THEN ROUND((parsed.evidence_json->>'source_amount_ex_vat')::numeric,2)
        WHEN COALESCE(parsed.evidence_json->>'source_pay_ex_vat','') ~ '^-?\d+(\.\d+)?$'
          THEN ROUND((parsed.evidence_json->>'source_pay_ex_vat')::numeric,2)
        WHEN COALESCE(parsed.source_basis_json->>'source_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$'
          THEN ROUND((parsed.source_basis_json->>'source_amount_ex_vat')::numeric,2)
        WHEN COALESCE(parsed.source_basis_json->>'source_pay_ex_vat','') ~ '^-?\d+(\.\d+)?$'
          THEN ROUND((parsed.source_basis_json->>'source_pay_ex_vat')::numeric,2)
        WHEN COALESCE(parsed.evidence_json->>'source_units',parsed.source_basis_json->>'source_units','')
            ~ '^-?\d+(\.\d+)?$'
          AND COALESCE(parsed.evidence_json->>'source_rate',parsed.source_basis_json->>'source_rate','')
            ~ '^-?\d+(\.\d+)?$'
          THEN ROUND(COALESCE(parsed.evidence_json->>'source_units',
            parsed.source_basis_json->>'source_units')::numeric
            *COALESCE(parsed.evidence_json->>'source_rate',
              parsed.source_basis_json->>'source_rate')::numeric,2)
      END AS allocated_amount_ex_vat,
      CASE
        WHEN parsed.evidence_origin IN ('CASE_COMPONENT','CASE_BUCKET_RESOLUTION',
            'CORRECTION_BUCKET_RESOLUTION','SOURCE_BASIS_CORRECTION_RESIDUAL',
            'SNAPSHOT_CORRECTION_RESIDUAL','RESOLUTION_CORRECTION_RESIDUAL')
          THEN COALESCE(parsed.evidence_json->>'component_amount_ex_vat',
            parsed.evidence_json->>'source_amount_ex_vat',parsed.evidence_json->>'source_pay_ex_vat',
            CASE WHEN COALESCE(parsed.evidence_json->>'source_units','') ~ '^-?\d+(\.\d+)?$'
              AND COALESCE(parsed.evidence_json->>'source_rate','') ~ '^-?\d+(\.\d+)?$'
              THEN 'DERIVED_UNITS_RATE' END) IS NOT NULL
        WHEN parsed.evidence_origin='TOP_LEVEL_SOURCE_BASIS'
          THEN COALESCE(parsed.source_basis_json->>'source_amount_ex_vat',
            parsed.source_basis_json->>'source_pay_ex_vat') IS NOT NULL
        ELSE false END AS allocation_claimed
    FROM nested_evidence_parsed parsed
  ), nested_evidence_digest AS MATERIALIZED (
    SELECT normalized.*,md5(jsonb_build_object(
      'evidence_contract_version',1,
      'economic_key_type',normalized.economic_key_type,
      'economic_key_value',normalized.economic_key_value,
      'source_family_key',normalized.source_family_key,
      'physical_bucket_key',normalized.direct_physical_bucket_key,
      'component_member_identity',normalized.component_member_identity,
      'bucket_code',normalized.bucket_code,
      'source_basis_fingerprint',normalized.source_basis_fingerprint,
      'component_fingerprint',normalized.component_fingerprint,
      'source_units',normalized.source_units,
      'source_rate',normalized.source_rate,
      'source_charge_rate',normalized.source_charge_rate,
      'source_amount_ex_vat',normalized.allocated_amount_ex_vat)::text)
        AS logical_evidence_digest
    FROM nested_evidence_normalized normalized
  ), nested_evidence_preferred AS MATERIALIZED (
    SELECT normalized.*
    FROM nested_evidence_digest normalized
    WHERE NOT (
      (normalized.evidence_origin='CASE_COMPONENT'
        AND EXISTS(
          SELECT 1 FROM nested_evidence_digest specific
          WHERE specific.fact_identity=normalized.fact_identity
            AND specific.evidence_container_identity IS NOT DISTINCT FROM
              normalized.evidence_container_identity
            AND specific.evidence_origin='CASE_BUCKET_RESOLUTION'
            AND specific.bucket_code IS NOT NULL
            AND specific.allocation_claimed
            AND specific.allocated_amount_ex_vat IS NOT NULL))
      OR (normalized.evidence_origin='TOP_LEVEL_SOURCE_BASIS'
        AND normalized.allocation_claimed
        AND normalized.allocated_amount_ex_vat IS NOT NULL
        AND EXISTS(
          SELECT 1 FROM nested_evidence_digest specific
          WHERE specific.fact_identity=normalized.fact_identity
            AND specific.evidence_origin IN
              ('CASE_BUCKET_RESOLUTION','CORRECTION_BUCKET_RESOLUTION')
            AND specific.allocation_claimed
            AND specific.allocated_amount_ex_vat IS NOT NULL
            AND (
              (normalized.direct_physical_bucket_key IS NOT NULL
                AND specific.direct_physical_bucket_key=
                  normalized.direct_physical_bucket_key)
              OR (normalized.component_member_identity IS NOT NULL
                AND normalized.bucket_code IS NOT NULL
                AND specific.component_member_identity=
                  normalized.component_member_identity
                AND specific.bucket_code=normalized.bucket_code)))))
  ), nested_evidence_deduped AS MATERIALIZED (
    SELECT ranked.*
    FROM (
      SELECT preferred.*,ROW_NUMBER() OVER(PARTITION BY preferred.fact_identity,
        preferred.logical_evidence_digest
        ORDER BY preferred.evidence_priority,preferred.evidence_origin,
          preferred.direct_physical_bucket_key NULLS LAST,
          preferred.source_basis_fingerprint NULLS LAST,
          preferred.component_fingerprint NULLS LAST)::integer AS evidence_rank
      FROM nested_evidence_preferred preferred
    ) ranked
    WHERE ranked.evidence_rank=1
  ), exact_allocation_candidates AS MATERIALIZED (
    SELECT evidence.*
    FROM nested_evidence_deduped evidence
    WHERE evidence.allocation_claimed AND evidence.allocated_amount_ex_vat IS NOT NULL
      AND ABS(evidence.allocated_amount_ex_vat)>0.005
      AND (evidence.direct_physical_bucket_key IS NOT NULL
        OR (evidence.component_member_identity IS NOT NULL AND evidence.bucket_code IS NOT NULL))
      AND (evidence.parent_amount_ex_vat=0
        OR SIGN(evidence.allocated_amount_ex_vat)=SIGN(evidence.parent_amount_ex_vat)
        OR evidence.component_fallback='WORKED_TIME_AMOUNT')
  ), nested_allocation_failures AS MATERIALIZED (
    SELECT parent.timesheet_id,parent.economic_key_type,parent.economic_key_value,
      MIN(failure.failure_rank) AS failure_rank,
      (array_agg(failure.failure_code ORDER BY failure.failure_rank,failure.failure_code))[1]
        AS failure_code
    FROM sealed_parent_facts parent
    JOIN (
      SELECT shape.fact_identity,10 AS failure_rank,shape.failure_code
      FROM nested_evidence_shape_failures shape
      UNION ALL
      SELECT evidence.fact_identity,20,'RATE_AUTHORITY_NESTED_AMOUNT_SIGN_MISMATCH'::text
      FROM nested_evidence_deduped evidence
      WHERE evidence.allocation_claimed AND evidence.allocated_amount_ex_vat IS NOT NULL
        AND ABS(evidence.allocated_amount_ex_vat)>0.005
        AND evidence.parent_amount_ex_vat<>0
        AND SIGN(evidence.allocated_amount_ex_vat)<>SIGN(evidence.parent_amount_ex_vat)
        AND evidence.component_fallback IS DISTINCT FROM 'WORKED_TIME_AMOUNT'
    ) failure USING(fact_identity)
    GROUP BY parent.timesheet_id,parent.economic_key_type,parent.economic_key_value
  ), exact_allocation_matched AS MATERIALIZED (
    SELECT allocation.*,
      COALESCE(match.matched_physical_bucket_key,
        CASE WHEN allocation.direct_physical_bucket_key IS NOT NULL
          THEN allocation.direct_physical_bucket_key
          WHEN allocation.component_member_identity IS NOT NULL AND allocation.bucket_code IS NOT NULL
            THEN concat_ws('|','RATE_BUCKET_V1',allocation.timesheet_id::text,
              allocation.source_family_key,allocation.economic_key_type,
              allocation.economic_key_value,allocation.component_member_identity,
              allocation.bucket_code) END) AS physical_bucket_key,
      COALESCE(match.match_authority,
        CASE WHEN allocation.direct_physical_bucket_key IS NOT NULL THEN 'PHYSICAL_BUCKET_KEY'
          ELSE 'SEALED_NESTED_IDENTITY' END) AS match_authority,
      COALESCE(match.matched_count,0) AS matched_count
    FROM exact_allocation_candidates allocation
    LEFT JOIN LATERAL (
      SELECT COUNT(*)::integer AS matched_count,MIN(candidate.physical_bucket_key)
          AS matched_physical_bucket_key,MIN(candidate.match_authority) AS match_authority
      FROM (
        SELECT bucket.parsed_physical_bucket_key AS physical_bucket_key,
          CASE
            WHEN allocation.direct_physical_bucket_key IS NOT NULL
              AND bucket.parsed_physical_bucket_key=allocation.direct_physical_bucket_key
              THEN 'PHYSICAL_BUCKET_KEY'
            WHEN bucket.parsed_component_member_identity=allocation.component_member_identity
              AND bucket.parsed_bucket_code=allocation.bucket_code THEN 'STRUCTURAL_IDENTITY'
            WHEN bucket.parsed_bucket_code=allocation.bucket_code THEN 'BUCKET_RESOLUTION'
            ELSE 'SOLE_BUCKET' END AS match_authority,
          CASE
            WHEN allocation.direct_physical_bucket_key IS NOT NULL
              AND bucket.parsed_physical_bucket_key=allocation.direct_physical_bucket_key THEN 10
            WHEN bucket.parsed_component_member_identity=allocation.component_member_identity
              AND bucket.parsed_bucket_code=allocation.bucket_code THEN 20
            WHEN bucket.parsed_bucket_code=allocation.bucket_code THEN 30 ELSE 40 END AS match_rank
        FROM bucket_validated bucket
        WHERE bucket.validated_failure IS NULL
          AND bucket.timesheet_id=allocation.timesheet_id
          AND UPPER(BTRIM(bucket.economic_key_type))=allocation.economic_key_type
          AND BTRIM(bucket.economic_key_value)=allocation.economic_key_value
          AND (bucket.parsed_physical_bucket_key=allocation.direct_physical_bucket_key
            OR (bucket.parsed_component_member_identity=allocation.component_member_identity
              AND bucket.parsed_bucket_code=allocation.bucket_code)
            OR bucket.parsed_bucket_code=allocation.bucket_code
            OR (SELECT COUNT(*) FROM bucket_validated sole
              WHERE sole.validated_failure IS NULL
                AND sole.timesheet_id=allocation.timesheet_id
                AND UPPER(BTRIM(sole.economic_key_type))=allocation.economic_key_type
                AND BTRIM(sole.economic_key_value)=allocation.economic_key_value)=1)
      ) candidate
      WHERE candidate.match_rank=(SELECT MIN(ranked.match_rank) FROM (
        SELECT CASE
          WHEN allocation.direct_physical_bucket_key IS NOT NULL
            AND bucket_rank.parsed_physical_bucket_key=allocation.direct_physical_bucket_key THEN 10
          WHEN bucket_rank.parsed_component_member_identity=allocation.component_member_identity
            AND bucket_rank.parsed_bucket_code=allocation.bucket_code THEN 20
          WHEN bucket_rank.parsed_bucket_code=allocation.bucket_code THEN 30 ELSE 40 END AS match_rank
        FROM bucket_validated bucket_rank
        WHERE bucket_rank.validated_failure IS NULL
          AND bucket_rank.timesheet_id=allocation.timesheet_id
          AND UPPER(BTRIM(bucket_rank.economic_key_type))=allocation.economic_key_type
          AND BTRIM(bucket_rank.economic_key_value)=allocation.economic_key_value
          AND (bucket_rank.parsed_physical_bucket_key=allocation.direct_physical_bucket_key
            OR (bucket_rank.parsed_component_member_identity=allocation.component_member_identity
              AND bucket_rank.parsed_bucket_code=allocation.bucket_code)
            OR bucket_rank.parsed_bucket_code=allocation.bucket_code
            OR (SELECT COUNT(*) FROM bucket_validated sole_rank
              WHERE sole_rank.validated_failure IS NULL
                AND sole_rank.timesheet_id=allocation.timesheet_id
                AND UPPER(BTRIM(sole_rank.economic_key_type))=allocation.economic_key_type
                AND BTRIM(sole_rank.economic_key_value)=allocation.economic_key_value)=1)
      ) ranked)
    ) match ON true
  ), parent_allocation_totals AS MATERIALIZED (
    SELECT parent.fact_identity,ROUND(COALESCE(SUM(
        allocation.allocated_amount_ex_vat),0),2)
        AS exact_allocated_ex_vat,
      ROUND(SUM(allocation.source_charge_ex_vat),2)
        AS exact_allocated_charge_ex_vat,
      BOOL_OR(allocation.component_fallback='WORKED_TIME_AMOUNT') AS has_explicit_residual
    FROM sealed_parent_facts parent
    LEFT JOIN exact_allocation_matched allocation USING(fact_identity)
    GROUP BY parent.fact_identity
  ), parent_residual_bucket_authority AS MATERIALIZED (
    SELECT parent.fact_identity,bucket.parsed_physical_bucket_key,
      bucket.parsed_component_member_identity,bucket.parsed_bucket_code,
      bucket.parsed_segment_id,bucket.parsed_segment_key,
      bucket.parsed_segment_stable_key,bucket.parsed_source_rate,
      bucket.parsed_source_charge_rate,
      CASE WHEN parent.authority_kind='RESERVATION' THEN NULL::numeric
        WHEN bucket.parsed_source_units IS NOT NULL
          AND ROUND(parent.parent_amount_ex_vat-total.exact_allocated_ex_vat,2)=
            ROUND(bucket.parsed_source_pay_ex_vat,2)
        THEN bucket.parsed_source_units
        ELSE ROUND((parent.parent_amount_ex_vat-total.exact_allocated_ex_vat)
          /bucket.parsed_source_rate,6) END AS residual_source_units,
      CASE
        WHEN parent.authority_kind='RESERVATION' THEN NULL::numeric
        WHEN parent.parent_source_charge_ex_vat IS NOT NULL
          THEN ROUND(parent.parent_source_charge_ex_vat
            - COALESCE(total.exact_allocated_charge_ex_vat,0),2)
        WHEN bucket.parsed_source_charge_ex_vat IS NOT NULL
          AND ROUND(parent.parent_amount_ex_vat-total.exact_allocated_ex_vat,2)=
            ROUND(bucket.parsed_source_pay_ex_vat,2)
          THEN bucket.parsed_source_charge_ex_vat
        ELSE ROUND(ROUND((parent.parent_amount_ex_vat-total.exact_allocated_ex_vat)
            /bucket.parsed_source_rate,6)*bucket.parsed_source_charge_rate,2)
      END AS residual_source_charge_ex_vat,
      CASE WHEN parent.authority_kind='RESERVATION'
        THEN 'SEALED_SOLE_BUCKET_RESERVATION_ATTRIBUTION_V1'
        ELSE 'SEALED_SOLE_BUCKET_RATE_DERIVATION_V1' END::text AS match_authority
    FROM sealed_parent_facts parent
    JOIN parent_allocation_totals total USING(fact_identity)
    JOIN physical_bucket_cardinality cardinality
      ON cardinality.timesheet_id=parent.timesheet_id
     AND cardinality.economic_key_type=parent.economic_key_type
     AND cardinality.economic_key_value=parent.economic_key_value
     AND cardinality.physical_bucket_count=1
    JOIN bucket_validated bucket
      ON bucket.validated_failure IS NULL
     AND bucket.timesheet_id=parent.timesheet_id
     AND UPPER(BTRIM(bucket.economic_key_type))=parent.economic_key_type
     AND BTRIM(bucket.economic_key_value)=parent.economic_key_value
    WHERE parent.authority_kind IN ('BASELINE','RESERVATION')
      AND parent.economic_key_type IN ('TS_DAY','TS_TOTAL')
      AND parent.is_signed_non_charge_recovery IS NOT TRUE
      AND ABS(ROUND(parent.parent_amount_ex_vat-total.exact_allocated_ex_vat,2))>0.005
      AND (parent.authority_kind='RESERVATION' OR (
        bucket.parsed_source_rate IS NOT NULL
        AND bucket.parsed_source_rate<>0
        AND (parent.parent_source_charge_ex_vat IS NOT NULL
          OR bucket.parsed_source_charge_ex_vat IS NOT NULL
          OR bucket.parsed_source_charge_rate IS NOT NULL)
        AND ROUND(ROUND((parent.parent_amount_ex_vat-total.exact_allocated_ex_vat)
            /bucket.parsed_source_rate,6)*bucket.parsed_source_rate,2)=
          ROUND(parent.parent_amount_ex_vat-total.exact_allocated_ex_vat,2)))
  ), parent_reconciliation_failures AS MATERIALIZED (
    SELECT parent.timesheet_id,parent.economic_key_type,parent.economic_key_value,
      MIN(failure.failure_rank) AS failure_rank,
      (array_agg(failure.failure_code ORDER BY failure.failure_rank,failure.failure_code))[1]
        AS failure_code
    FROM sealed_parent_facts parent
    JOIN parent_allocation_totals total USING(fact_identity)
    CROSS JOIN LATERAL (VALUES
      (CASE WHEN NOT COALESCE(total.has_explicit_residual,false)
          AND parent.parent_amount_ex_vat<>0 AND total.exact_allocated_ex_vat<>0
          AND SIGN(total.exact_allocated_ex_vat)=SIGN(parent.parent_amount_ex_vat)
          AND ABS(total.exact_allocated_ex_vat)>ABS(parent.parent_amount_ex_vat)+0.005
        THEN 30 END,
       CASE WHEN NOT COALESCE(total.has_explicit_residual,false)
          AND parent.parent_amount_ex_vat<>0 AND total.exact_allocated_ex_vat<>0
          AND SIGN(total.exact_allocated_ex_vat)=SIGN(parent.parent_amount_ex_vat)
          AND ABS(total.exact_allocated_ex_vat)>ABS(parent.parent_amount_ex_vat)+0.005
        THEN 'RATE_AUTHORITY_NESTED_AMOUNT_OVERCONSUMED' END),
      (CASE WHEN parent.authority_kind='BASELINE'
          AND parent.economic_key_type IN ('TS_DAY','TS_TOTAL')
          AND parent.is_signed_non_charge_recovery IS NOT TRUE
          AND ABS(ROUND(parent.parent_amount_ex_vat-total.exact_allocated_ex_vat,2))>0.005
          AND parent.parent_source_charge_ex_vat IS NULL
          AND NOT EXISTS(SELECT 1 FROM parent_residual_bucket_authority authority
            WHERE authority.fact_identity=parent.fact_identity) THEN 40 END,
       CASE WHEN parent.authority_kind='BASELINE'
          AND parent.economic_key_type IN ('TS_DAY','TS_TOTAL')
          AND parent.is_signed_non_charge_recovery IS NOT TRUE
          AND ABS(ROUND(parent.parent_amount_ex_vat-total.exact_allocated_ex_vat,2))>0.005
          AND parent.parent_source_charge_ex_vat IS NULL
          AND NOT EXISTS(SELECT 1 FROM parent_residual_bucket_authority authority
            WHERE authority.fact_identity=parent.fact_identity)
        THEN 'RATE_AUTHORITY_PARENT_SOURCE_CHARGE_MISSING' END)
      ,(CASE WHEN ROUND(parent.parent_amount_ex_vat-total.exact_allocated_ex_vat
            - ROUND(parent.parent_amount_ex_vat-total.exact_allocated_ex_vat,2),2)<>0
          THEN 50 END,
        CASE WHEN ROUND(parent.parent_amount_ex_vat-total.exact_allocated_ex_vat
            - ROUND(parent.parent_amount_ex_vat-total.exact_allocated_ex_vat,2),2)<>0
          THEN 'RATE_AUTHORITY_PARENT_COMPONENT_RECONCILIATION_MISMATCH' END)
    ) failure(failure_rank,failure_code)
    WHERE failure.failure_code IS NOT NULL
    GROUP BY parent.timesheet_id,parent.economic_key_type,parent.economic_key_value
  ), sealed_physical_amount_facts AS MATERIALIZED (
    SELECT allocation.fact_identity,allocation.authority_kind,allocation.timesheet_id,
      allocation.economic_key_type,allocation.economic_key_value,
      allocation.allocated_amount_ex_vat AS authority_amount_ex_vat,
      allocation.source_basis_json,allocation.physical_bucket_key AS direct_physical_bucket_key,
      allocation.component_member_identity AS direct_component_member_identity,
      allocation.source_family_key AS direct_source_family_key,
      allocation.bucket_code,allocation.segment_id,allocation.segment_key,
      allocation.segment_stable_key,allocation.source_units,allocation.source_rate,
      allocation.source_charge_rate,allocation.source_charge_ex_vat,
      COALESCE(allocation.evidence_source_pay_method,allocation.sealed_source_pay_method)
        AS sealed_source_pay_method,
      allocation.match_authority,(allocation.component_fallback='WORKED_TIME_AMOUNT') AS is_residual
    FROM exact_allocation_matched allocation
    WHERE allocation.physical_bucket_key IS NOT NULL AND allocation.matched_count<=1
    UNION ALL
    SELECT parent.fact_identity||':RESIDUAL',parent.authority_kind,parent.timesheet_id,
      parent.economic_key_type,parent.economic_key_value,
      ROUND(parent.parent_amount_ex_vat-total.exact_allocated_ex_vat,2),
      jsonb_build_object('timesheet_id',parent.timesheet_id::text,
        'work_date',CASE WHEN parent.economic_key_type='TS_DAY'
          THEN parent.economic_key_value END,'component_fallback','WORKED_TIME_AMOUNT',
        'residual_contract_version',1,
        'sole_bucket_rate_derivation_contract',residual_bucket.match_authority,
        'signed_non_charge_recovery_contract',CASE
          WHEN parent.is_signed_non_charge_recovery
            THEN 'SIGNED_NON_CHARGE_RECOVERY_V1' END),
      COALESCE(residual_bucket.parsed_physical_bucket_key,concat_ws('|','RATE_BUCKET_V1',parent.timesheet_id::text,
        'timesheet:'||parent.timesheet_id::text,parent.economic_key_type,
        parent.economic_key_value,
        CASE WHEN parent.economic_key_type='EXPENSE_CODE'
          THEN 'expense:'||UPPER(parent.economic_key_value)
          WHEN parent.economic_key_type='ADJUSTMENT_CODE'
          THEN 'adjustment:'||parent.economic_key_value
          ELSE 'worked-time-residual:'||parent.economic_key_type||':'||parent.economic_key_value END,
        'FIXED')),
      COALESCE(residual_bucket.parsed_component_member_identity,CASE WHEN parent.economic_key_type='EXPENSE_CODE'
          THEN 'expense:'||UPPER(parent.economic_key_value)
        WHEN parent.economic_key_type='ADJUSTMENT_CODE'
          THEN 'adjustment:'||parent.economic_key_value
        ELSE 'worked-time-residual:'||parent.economic_key_type||':'||parent.economic_key_value END),
      'timesheet:'||parent.timesheet_id::text,
      COALESCE(residual_bucket.parsed_bucket_code,'FIXED'),
      residual_bucket.parsed_segment_id,residual_bucket.parsed_segment_key,
      residual_bucket.parsed_segment_stable_key,residual_bucket.residual_source_units,
      residual_bucket.parsed_source_rate,residual_bucket.parsed_source_charge_rate,
      CASE WHEN parent.is_signed_non_charge_recovery THEN 0::numeric
        WHEN parent.authority_kind='BASELINE'
        THEN COALESCE(residual_bucket.residual_source_charge_ex_vat,
          ROUND(parent.parent_source_charge_ex_vat
            - COALESCE(total.exact_allocated_charge_ex_vat,0),2)) END,
      parent.sealed_source_pay_method,
      CASE WHEN parent.is_signed_non_charge_recovery
        THEN 'SIGNED_NON_CHARGE_RECOVERY_V1'
        ELSE COALESCE(residual_bucket.match_authority,'ECONOMIC_RESIDUAL') END,true
    FROM sealed_parent_facts parent
    JOIN parent_allocation_totals total USING(fact_identity)
    LEFT JOIN parent_residual_bucket_authority residual_bucket USING(fact_identity)
    WHERE ABS(ROUND(parent.parent_amount_ex_vat-total.exact_allocated_ex_vat,2))>0.005
      AND parent.economic_key_type<>'ADDITIONAL_CODE'
      AND NOT EXISTS(SELECT 1 FROM nested_allocation_failures failure
        WHERE failure.timesheet_id=parent.timesheet_id
          AND failure.economic_key_type=parent.economic_key_type
          AND failure.economic_key_value=parent.economic_key_value)
      AND NOT EXISTS(SELECT 1 FROM parent_reconciliation_failures failure
        WHERE failure.timesheet_id=parent.timesheet_id
          AND failure.economic_key_type=parent.economic_key_type
          AND failure.economic_key_value=parent.economic_key_value)
  ), sealed_physical_amount_attribution AS MATERIALIZED (
    SELECT fact.timesheet_id,fact.economic_key_type,fact.economic_key_value,
      fact.direct_physical_bucket_key AS matched_physical_bucket_key,
      ROUND(COALESCE(SUM(fact.authority_amount_ex_vat) FILTER(
        WHERE fact.authority_kind='BASELINE'),0),2) AS baseline_ex_vat,
      ROUND(COALESCE(SUM(fact.authority_amount_ex_vat) FILTER(
        WHERE fact.authority_kind='RESERVATION'),0),2) AS reserved_ex_vat,
      ROUND(COALESCE(SUM(fact.source_units) FILTER(
        WHERE fact.authority_kind='BASELINE'),0),6) AS baseline_source_units,
      ROUND(SUM(fact.source_charge_ex_vat) FILTER(
        WHERE fact.authority_kind='BASELINE'),2) AS baseline_source_charge_ex_vat,
      COALESCE(jsonb_agg(DISTINCT fact.match_authority ORDER BY fact.match_authority),
        '[]'::jsonb) AS match_authorities
    FROM sealed_physical_amount_facts fact
    GROUP BY fact.timesheet_id,fact.economic_key_type,fact.economic_key_value,
      fact.direct_physical_bucket_key
  ), sealed_physical_amount_ambiguity AS MATERIALIZED (
    SELECT parent.timesheet_id,parent.economic_key_type,parent.economic_key_value,
      BOOL_OR(parent.authority_kind='BASELINE' AND (
        EXISTS(SELECT 1 FROM exact_allocation_matched allocation
          WHERE allocation.fact_identity=parent.fact_identity AND allocation.matched_count>1)
        OR ABS(total.exact_allocated_ex_vat)>ABS(parent.parent_amount_ex_vat)+0.005))
        AS baseline_ambiguous,
      BOOL_OR(parent.authority_kind='RESERVATION' AND (
        EXISTS(SELECT 1 FROM exact_allocation_matched allocation
          WHERE allocation.fact_identity=parent.fact_identity AND allocation.matched_count>1)
        OR ABS(total.exact_allocated_ex_vat)>ABS(parent.parent_amount_ex_vat)+0.005))
        AS reservation_ambiguous
    FROM sealed_parent_facts parent
    JOIN parent_allocation_totals total USING(fact_identity)
    GROUP BY parent.timesheet_id,parent.economic_key_type,parent.economic_key_value
  ), bucket_attributed AS MATERIALIZED (
    SELECT bucket.*,
      ROUND(COALESCE(attribution.baseline_ex_vat,0),2) AS attributed_baseline_ex_vat,
      ROUND(COALESCE(attribution.reserved_ex_vat,0),2) AS attributed_reserved_ex_vat,
      ROUND(COALESCE(attribution.baseline_source_units,0),6)
        AS attributed_baseline_source_units,
      ROUND(COALESCE(attribution.baseline_source_charge_ex_vat,0),2)
        AS attributed_baseline_source_charge_ex_vat,
      ROUND(bucket.parsed_source_pay_ex_vat
        - COALESCE(attribution.baseline_ex_vat,0)
        - COALESCE(attribution.reserved_ex_vat,0),2) AS attributed_outstanding_ex_vat,
      (bucket.parsed_component_kind<>'WORKED_TIME'
        OR (COALESCE(bucket.parsed_source_units,0)>0
          AND bucket.parsed_source_rate IS NOT NULL
          AND bucket.parsed_source_pay_ex_vat>0)) AS builder_bucket_eligible,
      COALESCE(attribution.match_authorities,'[]'::jsonb) AS attribution_authorities
    FROM bucket_validated bucket
    LEFT JOIN sealed_physical_amount_attribution attribution
      ON attribution.timesheet_id=bucket.timesheet_id
     AND attribution.economic_key_type=UPPER(BTRIM(bucket.economic_key_type))
     AND attribution.economic_key_value=BTRIM(bucket.economic_key_value)
     AND attribution.matched_physical_bucket_key=bucket.parsed_physical_bucket_key
  ), bucket_builder_delta AS MATERIALIZED (
    SELECT bucket.*,
      ROUND(COALESCE(bucket.parsed_source_units,0)
        - bucket.attributed_baseline_source_units,6) AS raw_delta_source_units,
      ROUND(bucket.parsed_source_pay_ex_vat-bucket.attributed_baseline_ex_vat,2)
        AS raw_delta_before_reservation_ex,
      ROUND(COALESCE(bucket.parsed_source_charge_ex_vat,0)
        - bucket.attributed_baseline_source_charge_ex_vat,2) AS raw_delta_charge_ex_vat
    FROM bucket_attributed bucket
  ), bucket_builder_expected AS MATERIALIZED (
    SELECT delta.*,
      ROUND(delta.raw_delta_before_reservation_ex-delta.attributed_reserved_ex_vat,2)
        AS builder_component_amount_ex_vat,
      CASE
        WHEN delta.parsed_source_charge_rate IS NOT NULL
          AND delta.parsed_source_rate IS NOT NULL
          AND delta.parsed_source_rate<>0
          AND ROUND(GREATEST(delta.raw_delta_source_units,0),6)>0
          AND ROUND(GREATEST(delta.raw_delta_source_units,0)*delta.parsed_source_rate,2)=
            ROUND(delta.raw_delta_before_reservation_ex-delta.attributed_reserved_ex_vat,2)
          THEN ROUND(GREATEST(delta.raw_delta_source_units,0)
            *delta.parsed_source_charge_rate,2)
        WHEN ROUND(delta.raw_delta_before_reservation_ex,2)=0
          THEN ROUND(delta.raw_delta_charge_ex_vat,2)
        ELSE ROUND(delta.raw_delta_charge_ex_vat
          *((delta.raw_delta_before_reservation_ex-delta.attributed_reserved_ex_vat)
            /NULLIF(delta.raw_delta_before_reservation_ex,0)),2)
      END AS builder_source_charge_ex_vat,
      CASE WHEN delta.parsed_source_rate IS NOT NULL AND delta.parsed_source_rate<>0
          AND ROUND(GREATEST(delta.raw_delta_source_units,0),6)>0
          AND ROUND(GREATEST(delta.raw_delta_source_units,0)*delta.parsed_source_rate,2)=
            ROUND(delta.raw_delta_before_reservation_ex-delta.attributed_reserved_ex_vat,2)
        THEN ROUND(GREATEST(delta.raw_delta_source_units,0),6) END AS builder_source_units,
      CASE WHEN delta.parsed_source_rate IS NOT NULL AND delta.parsed_source_rate<>0
          AND ROUND(GREATEST(delta.raw_delta_source_units,0),6)>0
          AND ROUND(GREATEST(delta.raw_delta_source_units,0)*delta.parsed_source_rate,2)=
            ROUND(delta.raw_delta_before_reservation_ex-delta.attributed_reserved_ex_vat,2)
        THEN delta.parsed_source_rate END AS builder_source_rate,
      CASE WHEN delta.parsed_source_rate IS NOT NULL AND delta.parsed_source_rate<>0
          AND ROUND(GREATEST(delta.raw_delta_source_units,0),6)>0
          AND ROUND(GREATEST(delta.raw_delta_source_units,0)*delta.parsed_source_rate,2)=
            ROUND(delta.raw_delta_before_reservation_ex-delta.attributed_reserved_ex_vat,2)
        THEN CASE
          WHEN delta.parsed_source_charge_rate IS NOT NULL
            THEN delta.parsed_source_charge_rate
          WHEN ROUND(delta.raw_delta_charge_ex_vat,2)=0 THEN NULL::numeric
          ELSE ROUND(delta.raw_delta_charge_ex_vat
            /NULLIF(ROUND(GREATEST(delta.raw_delta_source_units,0),6),0),6)
        END
      END AS builder_source_charge_rate,
      ABS(ROUND(delta.raw_delta_before_reservation_ex
        - delta.attributed_reserved_ex_vat,2))>0.005 AS builder_component_expected
    FROM bucket_builder_delta delta
  ), synthetic_baseline_sources AS MATERIALIZED (
    SELECT attribution.timesheet_id,attribution.economic_key_type,attribution.economic_key_value,
      attribution.matched_physical_bucket_key AS physical_bucket_key,
      CASE WHEN BOOL_OR(fact.is_residual) THEN 'WORKED_TIME_RESIDUAL'
        WHEN attribution.economic_key_type IN ('TS_DAY','TS_TOTAL') THEN 'WORKED_TIME'
        WHEN attribution.economic_key_type='ADDITIONAL_CODE' THEN 'ADDITIONAL_UNIT'
        WHEN attribution.economic_key_type='EXPENSE_CODE' THEN 'EXPENSE'
        ELSE 'ADJUSTMENT' END AS component_kind,
      (array_agg(fact.direct_component_member_identity ORDER BY fact.is_residual DESC,
        fact.fact_identity))[1] AS component_member_identity,
      (array_agg(fact.segment_id ORDER BY fact.is_residual DESC,fact.fact_identity))[1]
        AS segment_id,
      (array_agg(fact.segment_key ORDER BY fact.is_residual DESC,fact.fact_identity))[1]
        AS segment_key,
      (array_agg(fact.segment_stable_key ORDER BY fact.is_residual DESC,fact.fact_identity))[1]
        AS segment_stable_key,
      (array_agg(fact.bucket_code ORDER BY fact.is_residual DESC,fact.fact_identity))[1]
        AS bucket_code,
      NULL::numeric AS source_units,NULL::numeric AS source_rate,
      NULL::numeric AS source_charge_rate,0::numeric AS truth_ex_vat,
      attribution.baseline_ex_vat,attribution.reserved_ex_vat,
      -COALESCE(attribution.baseline_source_charge_ex_vat,0) AS source_charge_ex_vat,
      method.authoritative_source_pay_method AS source_pay_method,
      context.target_pay_method,context.umbrella_id,context.umbrella_enabled,
      context.umbrella_vat_chargeable,context.erni_pct,context.vat_rate_pct,
      string_agg(fact.fact_identity||':'||fact.authority_amount_ex_vat::text,''
        ORDER BY fact.fact_identity) AS revision_identity,
      context.target_authority_digest,context.conversion_context_digest,
      (array_agg(fact.source_basis_json ORDER BY fact.is_residual DESC,fact.fact_identity))[1]
        AS source_basis_json,
      attribution.match_authorities,BOOL_OR(fact.is_residual) AS is_residual
    FROM sealed_physical_amount_attribution attribution
    JOIN sealed_physical_amount_facts fact
      ON fact.timesheet_id=attribution.timesheet_id
     AND fact.economic_key_type=attribution.economic_key_type
     AND fact.economic_key_value=attribution.economic_key_value
     AND fact.direct_physical_bucket_key=attribution.matched_physical_bucket_key
    JOIN source_method_authority method
      ON method.timesheet_id=attribution.timesheet_id
     AND method.economic_key_type=attribution.economic_key_type
     AND method.economic_key_value=attribution.economic_key_value
    CROSS JOIN candidate_sealed_context context
    WHERE NOT EXISTS(
      SELECT 1 FROM bucket_validated live_bucket
      WHERE live_bucket.validated_failure IS NULL
        AND live_bucket.timesheet_id=attribution.timesheet_id
        AND live_bucket.parsed_physical_bucket_key=attribution.matched_physical_bucket_key)
    GROUP BY attribution.timesheet_id,attribution.economic_key_type,
      attribution.economic_key_value,attribution.matched_physical_bucket_key,
      attribution.baseline_ex_vat,attribution.reserved_ex_vat,
      attribution.baseline_source_charge_ex_vat,attribution.match_authorities,
      context.target_pay_method,context.umbrella_id,context.umbrella_enabled,
      context.umbrella_vat_chargeable,context.erni_pct,context.vat_rate_pct,
      context.target_authority_digest,context.conversion_context_digest,
      method.authoritative_source_pay_method
  ), truth_residual_sources AS MATERIALIZED (
    SELECT expected.timesheet_id,expected.economic_key_type,expected.economic_key_value,
      concat_ws('|','RATE_BUCKET_V1',expected.timesheet_id::text,
        'timesheet:'||expected.timesheet_id::text,expected.economic_key_type,
        expected.economic_key_value,
        'worked-time-residual:'||expected.economic_key_type||':'||expected.economic_key_value,
        'FIXED') AS physical_bucket_key,
      'WORKED_TIME_RESIDUAL'::text AS component_kind,
      'worked-time-residual:'||expected.economic_key_type||':'||expected.economic_key_value
        AS component_member_identity,
      NULL::text AS segment_id,NULL::text AS segment_key,NULL::text AS segment_stable_key,
      'FIXED'::text AS bucket_code,NULL::numeric AS source_units,NULL::numeric AS source_rate,
      NULL::numeric AS source_charge_rate,
      ROUND(expected.truth_ex_vat-COALESCE(represented.truth_ex_vat,0),2) AS truth_ex_vat,
      0::numeric AS baseline_ex_vat,0::numeric AS reserved_ex_vat,
      represented.residual_source_charge_ex_vat AS source_charge_ex_vat,
      method.authoritative_source_pay_method,context.target_pay_method,context.umbrella_id,
      context.umbrella_enabled,context.umbrella_vat_chargeable,context.erni_pct,
      context.vat_rate_pct,
      'TRUTH_RESIDUAL:'||expected.timesheet_id::text||':'||expected.economic_key_type||':'
        ||expected.economic_key_value AS revision_identity,
      context.target_authority_digest,context.conversion_context_digest,
      jsonb_build_object('timesheet_id',expected.timesheet_id::text,
        'work_date',CASE WHEN expected.economic_key_type='TS_DAY'
          THEN expected.economic_key_value END,
        'component_fallback','WORKED_TIME_AMOUNT','residual_contract_version',1)
        AS source_basis_json,
      jsonb_build_array('ECONOMIC_TRUTH_RESIDUAL') AS match_authorities,true AS is_residual
    FROM economic_totals expected
    JOIN source_method_authority method
      USING(timesheet_id,economic_key_type,economic_key_value)
    CROSS JOIN candidate_sealed_context context
    LEFT JOIN LATERAL (
      SELECT ROUND(COALESCE(SUM(bucket.parsed_source_pay_ex_vat)
          FILTER(WHERE bucket.builder_bucket_eligible),0),2) AS truth_ex_vat,
        ROUND(COALESCE(SUM(bucket.parsed_source_charge_ex_vat)
          FILTER(WHERE NOT bucket.builder_bucket_eligible),0),2)
          AS residual_source_charge_ex_vat
      FROM bucket_attributed bucket
      WHERE bucket.validated_failure IS NULL
        AND bucket.timesheet_id=expected.timesheet_id
        AND UPPER(BTRIM(bucket.economic_key_type))=expected.economic_key_type
        AND BTRIM(bucket.economic_key_value)=expected.economic_key_value
    ) represented ON true
    WHERE expected.economic_key_type IN ('TS_DAY','TS_TOTAL')
      AND ABS(ROUND(expected.truth_ex_vat-COALESCE(represented.truth_ex_vat,0),2))>0.005
  ), synthetic_component_sources AS MATERIALIZED (
    SELECT * FROM synthetic_baseline_sources
    UNION ALL SELECT * FROM truth_residual_sources
  ), synthetic_component_authorities AS MATERIALIZED (
    SELECT source.timesheet_id,source.economic_key_type,source.economic_key_value,
      source.physical_bucket_key,
      COALESCE(jsonb_agg(DISTINCT authority.value ORDER BY authority.value)
        FILTER(WHERE authority.value IS NOT NULL),'[]'::jsonb) AS match_authorities
    FROM synthetic_component_sources source
    LEFT JOIN LATERAL jsonb_array_elements_text(
      COALESCE(source.match_authorities,'[]'::jsonb)) authority(value) ON true
    GROUP BY source.timesheet_id,source.economic_key_type,source.economic_key_value,
      source.physical_bucket_key
  ), synthetic_bucket_attributed AS MATERIALIZED (
    SELECT source.timesheet_id,source.economic_key_type,source.economic_key_value,
      source.physical_bucket_key,
      CASE WHEN BOOL_OR(source.is_residual) THEN 'WORKED_TIME_RESIDUAL'
        ELSE MIN(source.component_kind) END AS component_kind,
      (array_agg(source.component_member_identity ORDER BY source.is_residual DESC,
        source.revision_identity))[1] AS component_member_identity,
      (array_agg(source.segment_id ORDER BY source.is_residual DESC,source.revision_identity))[1]
        AS segment_id,
      (array_agg(source.segment_key ORDER BY source.is_residual DESC,source.revision_identity))[1]
        AS segment_key,
      (array_agg(source.segment_stable_key ORDER BY source.is_residual DESC,
        source.revision_identity))[1] AS segment_stable_key,
      (array_agg(source.bucket_code ORDER BY source.is_residual DESC,source.revision_identity))[1]
        AS bucket_code,
      CASE WHEN BOOL_OR(source.is_residual) THEN 90 ELSE 7 END AS bucket_sort_ordinal,
      NULL::numeric AS source_units,NULL::numeric AS source_rate,
      NULL::numeric AS source_charge_rate,
      ROUND(SUM(source.truth_ex_vat),2) AS truth_ex_vat,
      ROUND(SUM(source.baseline_ex_vat),2) AS baseline_ex_vat,
      ROUND(SUM(source.reserved_ex_vat),2) AS reserved_ex_vat,
      ROUND(SUM(source.truth_ex_vat)-SUM(source.baseline_ex_vat)-SUM(source.reserved_ex_vat),2)
        AS outstanding_ex_vat,
      ROUND(SUM(source.source_charge_ex_vat),2) AS source_charge_ex_vat,
      (jsonb_agg(DISTINCT source.source_pay_method ORDER BY source.source_pay_method)
        FILTER(WHERE source.source_pay_method IS NOT NULL)->>0) AS source_pay_method,
      MIN(source.target_pay_method)
        AS target_pay_method,MIN(source.umbrella_id::text)::uuid AS umbrella_id,
      BOOL_AND(source.umbrella_enabled) AS umbrella_enabled,
      BOOL_AND(source.umbrella_vat_chargeable) AS umbrella_vat_chargeable,
      MIN(source.erni_pct) AS erni_pct,MIN(source.vat_rate_pct) AS vat_rate_pct,
      md5(string_agg(source.revision_identity,'' ORDER BY source.revision_identity))
        AS financial_revision_digest,
      MIN(source.target_authority_digest) AS target_authority_digest,
      MIN(source.conversion_context_digest) AS conversion_context_digest,
      (array_agg(source.source_basis_json ORDER BY source.is_residual DESC,
        source.revision_identity))[1] AS source_basis_json,
      COALESCE(authority.match_authorities,'[]'::jsonb) AS match_authorities,
      BOOL_OR(source.is_residual) AS is_residual
    FROM synthetic_component_sources source
    LEFT JOIN synthetic_component_authorities authority
      USING(timesheet_id,economic_key_type,economic_key_value,physical_bucket_key)
    GROUP BY source.timesheet_id,source.economic_key_type,source.economic_key_value,
      source.physical_bucket_key,authority.match_authorities
  ), physical_amount_rows AS MATERIALIZED (
    SELECT bucket.timesheet_id,UPPER(BTRIM(bucket.economic_key_type)) AS economic_key_type,
      BTRIM(bucket.economic_key_value) AS economic_key_value,
      bucket.parsed_source_pay_ex_vat AS truth_ex_vat,
      bucket.attributed_baseline_ex_vat AS baseline_ex_vat,
      bucket.attributed_reserved_ex_vat AS reserved_ex_vat
    FROM bucket_builder_expected bucket
    WHERE bucket.validated_failure IS NULL AND bucket.builder_bucket_eligible
    UNION ALL
    SELECT synthetic.timesheet_id,synthetic.economic_key_type,synthetic.economic_key_value,
      synthetic.truth_ex_vat,synthetic.baseline_ex_vat,synthetic.reserved_ex_vat
    FROM synthetic_bucket_attributed synthetic
  ), economic_physical_totals AS MATERIALIZED (
    SELECT bucket.timesheet_id,bucket.economic_key_type,bucket.economic_key_value,
      ROUND(COALESCE(SUM(bucket.truth_ex_vat),0),2) AS truth_ex_vat,
      ROUND(COALESCE(SUM(bucket.baseline_ex_vat),0),2) AS baseline_ex_vat,
      ROUND(COALESCE(SUM(bucket.reserved_ex_vat),0),2) AS reserved_ex_vat
    FROM physical_amount_rows bucket
    GROUP BY bucket.timesheet_id,bucket.economic_key_type,bucket.economic_key_value
  ), economic_failures AS MATERIALIZED (
    SELECT expected.timesheet_id,expected.economic_key_type,expected.economic_key_value,
      CASE
        WHEN context.context_failure IS NOT NULL THEN context.context_failure
        WHEN method.failure_code IS NOT NULL THEN method.failure_code
        WHEN method.timesheet_id IS NULL THEN 'RATE_AUTHORITY_SOURCE_PAY_METHOD_MISSING'
        WHEN nested.failure_code IS NOT NULL THEN nested.failure_code
        WHEN reconciliation.failure_code IS NOT NULL THEN reconciliation.failure_code
        WHEN actual.truth_ex_vat IS NULL OR actual.truth_ex_vat IS DISTINCT FROM expected.truth_ex_vat
          THEN 'RATE_AUTHORITY_PARENT_PAY_MISMATCH'
        WHEN COALESCE(ambiguity.baseline_ambiguous,false)
          OR actual.baseline_ex_vat IS DISTINCT FROM expected.baseline_ex_vat
          THEN 'RATE_AUTHORITY_PHYSICAL_BASELINE_REQUIRED'
        WHEN COALESCE(ambiguity.reservation_ambiguous,false)
          OR actual.reserved_ex_vat IS DISTINCT FROM expected.reserved_ex_vat
          THEN 'RATE_AUTHORITY_PHYSICAL_RESERVATION_REQUIRED'
      END AS failure_code,
      COALESCE(method.evidence_json,jsonb_build_object(
        'authority_contract_version',1,
        'total_evidence_count',0,
        'supported_method_evidence_count',0,
        'invalid_method_count',0,
        'distinct_supported_source_method_count',0,
        'authoritative_source_pay_method',NULL,
        'complete_evidence_digest',pg_catalog.encode(extensions.digest(
          pg_catalog.convert_to('[]','UTF8'),'sha256'),'hex'),
        'sample_truncated',false,
        'evidence_sample','[]'::jsonb)) AS source_method_evidence_json
    FROM economic_totals expected
    CROSS JOIN candidate_sealed_context context
    LEFT JOIN source_method_authority method
      USING(timesheet_id,economic_key_type,economic_key_value)
    LEFT JOIN nested_allocation_failures nested
      USING(timesheet_id,economic_key_type,economic_key_value)
    LEFT JOIN parent_reconciliation_failures reconciliation
      USING(timesheet_id,economic_key_type,economic_key_value)
    LEFT JOIN economic_physical_totals actual
      USING(timesheet_id,economic_key_type,economic_key_value)
    LEFT JOIN sealed_physical_amount_ambiguity ambiguity
      USING(timesheet_id,economic_key_type,economic_key_value)
    WHERE context.context_failure IS NOT NULL
       OR method.failure_code IS NOT NULL
       OR method.timesheet_id IS NULL
       OR nested.failure_code IS NOT NULL
       OR reconciliation.failure_code IS NOT NULL
       OR actual.truth_ex_vat IS DISTINCT FROM expected.truth_ex_vat
       OR COALESCE(ambiguity.baseline_ambiguous,false)
       OR actual.baseline_ex_vat IS DISTINCT FROM expected.baseline_ex_vat
       OR COALESCE(ambiguity.reservation_ambiguous,false)
       OR actual.reserved_ex_vat IS DISTINCT FROM expected.reserved_ex_vat
  ), bucket_documents AS MATERIALIZED (
    SELECT bucket.*,
      jsonb_build_object(
        'physical_bucket_version',2,
        'physical_bucket_key',bucket.parsed_physical_bucket_key,
        'component_kind',bucket.parsed_component_kind,
        'component_member_identity',bucket.parsed_component_member_identity,
        'bucket_code',bucket.parsed_bucket_code,
        'source_units',bucket.builder_source_units,
        'source_rate',bucket.builder_source_rate,
        'source_charge_rate',bucket.builder_source_charge_rate,
        'source_pay_ex_vat',bucket.parsed_source_pay_ex_vat,
        'source_charge_ex_vat',bucket.builder_source_charge_ex_vat,
        'baseline_source_pay_ex_vat',bucket.attributed_baseline_ex_vat,
        'reserved_source_pay_ex_vat',bucket.attributed_reserved_ex_vat,
        'outstanding_source_pay_ex_vat',bucket.attributed_outstanding_ex_vat,
        'source_pay_method',bucket.parsed_source_pay_method,
        'target_pay_method',bucket.parsed_target_pay_method) AS attributed_physical_canonical_json,
      md5(jsonb_build_object(
        'builder_comparison_version',1,'timesheet_id',bucket.timesheet_id::text,
        'source_family_key',bucket.rate_authority#>>'{economic,source_family_key}',
        'component_key_type',UPPER(BTRIM(bucket.economic_key_type)),
        'component_key_value',BTRIM(bucket.economic_key_value),
        'segment_id',bucket.parsed_segment_id,
        'segment_key',COALESCE(bucket.parsed_segment_key,bucket.parsed_segment_id),
        'segment_stable_key',bucket.parsed_segment_stable_key,
        'work_date',NULLIF(BTRIM(COALESCE(bucket.bucket_json->>'work_date',
          bucket.source_payload_json#>>'{segment,work_date}',
          bucket.source_payload_json#>>'{segment,date}')),''),
        'ref_num',NULLIF(BTRIM(COALESCE(bucket.bucket_json->>'ref_num',
          bucket.source_payload_json#>>'{segment,ref_num}')),''),
        'additional_code',NULLIF(UPPER(BTRIM(bucket.bucket_json->>'additional_code')),''),
        'expense_code',NULLIF(UPPER(BTRIM(bucket.bucket_json->>'expense_code')),''),
        'adjustment_id',NULLIF(BTRIM(bucket.bucket_json->>'adjustment_id'),''),
        'bucket_code',bucket.parsed_bucket_code,
        'source_units',bucket.builder_source_units,
        'source_rate',bucket.builder_source_rate,
        'source_charge_rate',bucket.builder_source_charge_rate,
        'source_pay_ex_vat',bucket.builder_component_amount_ex_vat,
        'source_charge_ex_vat',bucket.builder_source_charge_ex_vat,
        'source_pay_method',bucket.parsed_source_pay_method,
        'target_pay_method',bucket.parsed_target_pay_method)::text)
        AS attributed_builder_comparison_digest
    FROM bucket_builder_expected bucket
    WHERE bucket.builder_bucket_eligible
  ), synthetic_bucket_documents AS MATERIALIZED (
    SELECT synthetic.*,
      jsonb_build_object(
        'physical_bucket_version',2,
        'physical_bucket_key',synthetic.physical_bucket_key,
        'component_kind',synthetic.component_kind,
        'component_member_identity',synthetic.component_member_identity,
        'bucket_code',synthetic.bucket_code,
        'source_units',synthetic.source_units,
        'source_rate',synthetic.source_rate,
        'source_charge_rate',synthetic.source_charge_rate,
        'source_pay_ex_vat',synthetic.truth_ex_vat,
        'source_charge_ex_vat',synthetic.source_charge_ex_vat,
        'baseline_source_pay_ex_vat',synthetic.baseline_ex_vat,
        'reserved_source_pay_ex_vat',synthetic.reserved_ex_vat,
        'outstanding_source_pay_ex_vat',synthetic.outstanding_ex_vat,
        'source_pay_method',synthetic.source_pay_method,
        'target_pay_method',synthetic.target_pay_method) AS physical_canonical_json,
      md5(jsonb_build_object(
        'builder_comparison_version',1,
        'timesheet_id',synthetic.timesheet_id::text,
        'source_family_key','timesheet:'||synthetic.timesheet_id::text,
        'component_key_type',synthetic.economic_key_type,
        'component_key_value',synthetic.economic_key_value,
        'segment_id',synthetic.segment_id,
        'segment_key',COALESCE(synthetic.segment_key,synthetic.segment_id),
        'segment_stable_key',synthetic.segment_stable_key,
        'work_date',NULLIF(BTRIM(COALESCE(synthetic.source_basis_json->>'work_date',
          synthetic.source_basis_json->>'date')),''),
        'ref_num',NULLIF(BTRIM(synthetic.source_basis_json->>'ref_num'),''),
        'additional_code',CASE WHEN synthetic.economic_key_type='ADDITIONAL_CODE'
          THEN UPPER(synthetic.economic_key_value) END,
        'expense_code',CASE WHEN synthetic.economic_key_type='EXPENSE_CODE'
          THEN UPPER(synthetic.economic_key_value) END,
        'adjustment_id',CASE WHEN synthetic.economic_key_type='ADJUSTMENT_CODE'
          THEN synthetic.economic_key_value END,
        'bucket_code',synthetic.bucket_code,
        'source_units',synthetic.source_units,
        'source_rate',synthetic.source_rate,
        'source_charge_rate',synthetic.source_charge_rate,
        'source_pay_ex_vat',synthetic.outstanding_ex_vat,
        'source_charge_ex_vat',synthetic.source_charge_ex_vat,
        'source_pay_method',synthetic.source_pay_method,
        'target_pay_method',synthetic.target_pay_method)::text)
        AS builder_comparison_digest
    FROM synthetic_bucket_attributed synthetic
  ), failed_occurrences AS (
    SELECT occurrence.build_id,occurrence.build_candidate_id AS candidate_id,
      occurrence.timesheet_id,
      CASE WHEN COALESCE(occurrence.rate_authority#>>'{source,financial_row_id}','')
        ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN (occurrence.rate_authority#>>'{source,financial_row_id}')::uuid END AS financial_row_id,
      occurrence.rate_authority#>>'{economic,source_family_key}' AS source_family_key,
      occurrence.economic_key_type,occurrence.economic_key_value,
      occurrence.rate_authority#>>'{economic,component_kind}' AS component_kind,
      NULL::text AS component_member_identity,NULL::text AS segment_id,
      NULL::text AS segment_key,NULL::text AS segment_stable_key,NULL::text AS bucket_code,
      NULL::integer AS bucket_sort_ordinal,NULL::text AS physical_bucket_key,
      NULL::text AS physical_bucket_digest,NULL::numeric AS source_units,
      NULL::numeric AS source_rate,NULL::numeric AS source_charge_rate,
      ROUND(occurrence.truth_ex_vat,2) AS truth_ex_vat,
      0::numeric AS baseline_ex_vat,0::numeric AS reserved_ex_vat,
      ROUND(occurrence.truth_ex_vat,2) AS outstanding_ex_vat,
      NULL::numeric AS source_charge_ex_vat,
      NULL::text AS source_pay_method,
      UPPER(NULLIF(BTRIM(occurrence.rate_authority#>>'{target,target_pay_method}'),''))
        AS target_pay_method,
      CASE WHEN COALESCE(occurrence.rate_authority#>>'{target,umbrella_id}','')
        ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN (occurrence.rate_authority#>>'{target,umbrella_id}')::uuid END AS umbrella_id,
      CASE WHEN jsonb_typeof(occurrence.rate_authority#>'{target,umbrella_enabled}')='boolean'
        THEN (occurrence.rate_authority#>>'{target,umbrella_enabled}')::boolean END
        AS umbrella_enabled,
      CASE WHEN jsonb_typeof(occurrence.rate_authority#>'{target,umbrella_vat_chargeable}')='boolean'
        THEN (occurrence.rate_authority#>>'{target,umbrella_vat_chargeable}')::boolean END
        AS umbrella_vat_chargeable,
      CASE WHEN COALESCE(occurrence.rate_authority#>>'{conversion,erni_pct}','') ~ '^-?\d+(\.\d+)?$'
        THEN ROUND((occurrence.rate_authority#>>'{conversion,erni_pct}')::numeric,6) END AS erni_pct,
      CASE WHEN COALESCE(occurrence.rate_authority#>>'{conversion,vat_rate_pct}','') ~ '^-?\d+(\.\d+)?$'
        THEN ROUND((occurrence.rate_authority#>>'{conversion,vat_rate_pct}')::numeric,6) END AS vat_rate_pct,
      occurrence.rate_authority#>>'{source,financial_revision_digest}' AS financial_revision_digest,
      occurrence.rate_authority#>>'{target,target_authority_digest}' AS target_authority_digest,
      occurrence.rate_authority#>>'{conversion,conversion_context_digest}'
        AS conversion_context_digest,
      occurrence.rate_authority->>'sealed_evidence_digest' AS sealed_evidence_digest,
      'FAILED'::text AS projection_status,
      COALESCE(occurrence.validated_failure,economic.failure_code) AS failure_code,
      jsonb_build_object('source_key',occurrence.source_payload_json->>'source_key',
        'source_ordinal',occurrence.source_payload_json#>'{rate_authority,lineage,source_ordinal}',
        'source_payload',occurrence.source_payload_json,'physical_bucket',NULL,
        'source_method_authority',economic.source_method_evidence_json) AS evidence_json
    FROM occurrence_validated occurrence
    LEFT JOIN economic_failures economic
      ON economic.timesheet_id=occurrence.timesheet_id
     AND economic.economic_key_type=UPPER(BTRIM(occurrence.economic_key_type))
     AND economic.economic_key_value=BTRIM(occurrence.economic_key_value)
    WHERE COALESCE(occurrence.validated_failure,economic.failure_code) IS NOT NULL
  ), failed_economic_domain AS (
    SELECT p_build_id,p_candidate_id,economic.timesheet_id,NULL::uuid AS financial_row_id,
      'timesheet:'||economic.timesheet_id::text AS source_family_key,
      economic.economic_key_type,economic.economic_key_value,NULL::text AS component_kind,
      NULL::text AS component_member_identity,NULL::text AS segment_id,
      NULL::text AS segment_key,NULL::text AS segment_stable_key,NULL::text AS bucket_code,
      NULL::integer AS bucket_sort_ordinal,NULL::text AS physical_bucket_key,
      NULL::text AS physical_bucket_digest,NULL::numeric AS source_units,
      NULL::numeric AS source_rate,NULL::numeric AS source_charge_rate,
      expected.truth_ex_vat,expected.baseline_ex_vat,expected.reserved_ex_vat,
      ROUND(expected.truth_ex_vat-expected.baseline_ex_vat-expected.reserved_ex_vat,2)
        AS outstanding_ex_vat,
      NULL::numeric AS source_charge_ex_vat,NULL::text AS source_pay_method,
      context.target_pay_method,context.umbrella_id,context.umbrella_enabled,
      context.umbrella_vat_chargeable,context.erni_pct,context.vat_rate_pct,
      NULL::text AS financial_revision_digest,context.target_authority_digest,
      context.conversion_context_digest,NULL::text AS sealed_evidence_digest,
      'FAILED'::text AS projection_status,economic.failure_code,
      jsonb_build_object('build_id',p_build_id::text,'candidate_id',p_candidate_id::text,
        'timesheet_id',economic.timesheet_id::text,
        'economic_key_type',economic.economic_key_type,
        'economic_key_value',economic.economic_key_value,
        'source_method_authority',economic.source_method_evidence_json) AS evidence_json
    FROM economic_failures economic
    JOIN economic_totals expected USING(timesheet_id,economic_key_type,economic_key_value)
    CROSS JOIN candidate_sealed_context context
    WHERE NOT EXISTS(
      SELECT 1 FROM occurrence_validated occurrence
      WHERE occurrence.timesheet_id=economic.timesheet_id
        AND UPPER(BTRIM(occurrence.economic_key_type))=economic.economic_key_type
        AND BTRIM(occurrence.economic_key_value)=economic.economic_key_value)
  ), bucket_outputs AS (
    SELECT bucket.build_id,bucket.build_candidate_id AS candidate_id,bucket.timesheet_id,
      CASE WHEN COALESCE(bucket.rate_authority#>>'{source,financial_row_id}','')
        ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN (bucket.rate_authority#>>'{source,financial_row_id}')::uuid END AS financial_row_id,
      bucket.rate_authority#>>'{economic,source_family_key}' AS source_family_key,
      UPPER(BTRIM(bucket.economic_key_type)) AS economic_key_type,
      BTRIM(bucket.economic_key_value) AS economic_key_value,
      bucket.parsed_component_kind,bucket.parsed_component_member_identity,
      bucket.parsed_segment_id,bucket.parsed_segment_key,bucket.parsed_segment_stable_key,
      bucket.parsed_bucket_code,bucket.parsed_bucket_sort_ordinal,
      bucket.parsed_physical_bucket_key,md5(bucket.attributed_physical_canonical_json::text),
      bucket.builder_source_units,bucket.builder_source_rate,bucket.builder_source_charge_rate,
      bucket.parsed_source_pay_ex_vat,bucket.attributed_baseline_ex_vat,
      bucket.attributed_reserved_ex_vat,bucket.attributed_outstanding_ex_vat,
      bucket.builder_source_charge_ex_vat,CASE
        WHEN COALESCE(bucket.validated_failure,economic.failure_code) IS NULL
          THEN method.authoritative_source_pay_method END,
      bucket.parsed_target_pay_method,
      CASE WHEN COALESCE(bucket.rate_authority#>>'{target,umbrella_id}','')
        ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN (bucket.rate_authority#>>'{target,umbrella_id}')::uuid END AS umbrella_id,
      CASE WHEN jsonb_typeof(bucket.rate_authority#>'{target,umbrella_enabled}')='boolean'
        THEN (bucket.rate_authority#>>'{target,umbrella_enabled}')::boolean END,
      CASE WHEN jsonb_typeof(bucket.rate_authority#>'{target,umbrella_vat_chargeable}')='boolean'
        THEN (bucket.rate_authority#>>'{target,umbrella_vat_chargeable}')::boolean END,
      CASE WHEN COALESCE(bucket.rate_authority#>>'{conversion,erni_pct}','') ~ '^-?\d+(\.\d+)?$'
        THEN ROUND((bucket.rate_authority#>>'{conversion,erni_pct}')::numeric,6) END,
      CASE WHEN COALESCE(bucket.rate_authority#>>'{conversion,vat_rate_pct}','') ~ '^-?\d+(\.\d+)?$'
        THEN ROUND((bucket.rate_authority#>>'{conversion,vat_rate_pct}')::numeric,6) END,
      bucket.rate_authority#>>'{source,financial_revision_digest}',
      bucket.rate_authority#>>'{target,target_authority_digest}',
      bucket.rate_authority#>>'{conversion,conversion_context_digest}',
      md5(jsonb_build_object(
        'sealed_evidence_version',2,
        'financial_revision_digest',bucket.rate_authority#>>'{source,financial_revision_digest}',
        'target_authority_digest',bucket.rate_authority#>>'{target,target_authority_digest}',
        'conversion_context_digest',bucket.rate_authority#>>'{conversion,conversion_context_digest}',
        'physical_bucket_digest',md5(bucket.attributed_physical_canonical_json::text),
        'economic_key_type',UPPER(BTRIM(bucket.economic_key_type)),
        'economic_key_value',BTRIM(bucket.economic_key_value),
        'truth_ex_vat',bucket.parsed_source_pay_ex_vat,
        'baseline_ex_vat',bucket.attributed_baseline_ex_vat,
        'reserved_ex_vat',bucket.attributed_reserved_ex_vat)::text),
      CASE WHEN COALESCE(bucket.validated_failure,economic.failure_code) IS NOT NULL
        THEN 'FAILED'
        WHEN bucket.builder_component_expected
        AND bucket.builder_source_units IS NOT NULL
        AND bucket.builder_source_rate IS NOT NULL
        AND method.authoritative_source_pay_method IS DISTINCT FROM bucket.parsed_target_pay_method
        THEN 'READY' ELSE 'FIXED' END AS projection_status,
      COALESCE(bucket.validated_failure,economic.failure_code) AS failure_code,
      jsonb_build_object('source_key',bucket.source_payload_json->>'source_key',
        'source_ordinal',bucket.source_payload_json#>'{rate_authority,lineage,source_ordinal}',
        'source_payload',bucket.source_payload_json,
        'physical_bucket',bucket.attributed_physical_canonical_json||jsonb_build_object(
          'physical_bucket_digest',md5(bucket.attributed_physical_canonical_json::text),
          'builder_comparison_digest',bucket.attributed_builder_comparison_digest,
          'builder_component_amount_ex_vat',bucket.builder_component_amount_ex_vat,
          'builder_component_expected',bucket.builder_component_expected,
          'is_rate_bearing',bucket.builder_source_units IS NOT NULL
            AND bucket.builder_source_rate IS NOT NULL,
          'is_actionable_candidate',bucket.builder_component_expected
            AND bucket.builder_source_units IS NOT NULL
            AND bucket.builder_source_rate IS NOT NULL
            AND COALESCE(bucket.validated_failure,economic.failure_code) IS NULL
            AND method.authoritative_source_pay_method IS DISTINCT FROM bucket.parsed_target_pay_method),
        'sealed_physical_attribution',jsonb_build_object(
          'baseline_ex_vat',bucket.attributed_baseline_ex_vat,
          'reserved_ex_vat',bucket.attributed_reserved_ex_vat,
          'outstanding_ex_vat',bucket.attributed_outstanding_ex_vat,
          'match_authorities',bucket.attribution_authorities),
        'economic_authority',(SELECT jsonb_build_object(
            'truth_inc_vat',economic_total.truth_inc_vat,
            'baseline_inc_vat',economic_total.baseline_inc_vat)
          FROM economic_totals economic_total
          WHERE economic_total.timesheet_id=bucket.timesheet_id
            AND economic_total.economic_key_type=UPPER(BTRIM(bucket.economic_key_type))
            AND economic_total.economic_key_value=BTRIM(bucket.economic_key_value)),
        'source_method_authority',method.evidence_json) AS evidence_json
    FROM bucket_documents bucket
    LEFT JOIN source_method_authority method
      ON method.timesheet_id=bucket.timesheet_id
     AND method.economic_key_type=UPPER(BTRIM(bucket.economic_key_type))
     AND method.economic_key_value=BTRIM(bucket.economic_key_value)
    LEFT JOIN economic_failures economic
      ON economic.timesheet_id=bucket.timesheet_id
     AND economic.economic_key_type=UPPER(BTRIM(bucket.economic_key_type))
     AND economic.economic_key_value=BTRIM(bucket.economic_key_value)
    WHERE NOT EXISTS(SELECT 1 FROM failed_occurrences failed
      WHERE failed.build_id=bucket.build_id AND failed.timesheet_id=bucket.timesheet_id
        AND failed.economic_key_type=bucket.economic_key_type
        AND failed.economic_key_value=bucket.economic_key_value)
  ), synthetic_bucket_outputs AS (
    SELECT p_build_id,p_candidate_id,synthetic.timesheet_id,NULL::uuid AS financial_row_id,
      'timesheet:'||synthetic.timesheet_id::text AS source_family_key,
      synthetic.economic_key_type,synthetic.economic_key_value,synthetic.component_kind,
      synthetic.component_member_identity,synthetic.segment_id,synthetic.segment_key,
      synthetic.segment_stable_key,synthetic.bucket_code,synthetic.bucket_sort_ordinal,
      synthetic.physical_bucket_key,md5(synthetic.physical_canonical_json::text)
        AS physical_bucket_digest,
      synthetic.source_units,synthetic.source_rate,synthetic.source_charge_rate,
      synthetic.truth_ex_vat,synthetic.baseline_ex_vat,synthetic.reserved_ex_vat,
      synthetic.outstanding_ex_vat,synthetic.source_charge_ex_vat,
      synthetic.source_pay_method,synthetic.target_pay_method,synthetic.umbrella_id,
      synthetic.umbrella_enabled,synthetic.umbrella_vat_chargeable,synthetic.erni_pct,
      synthetic.vat_rate_pct,synthetic.financial_revision_digest,
      synthetic.target_authority_digest,synthetic.conversion_context_digest,
      md5(jsonb_build_object(
        'sealed_evidence_version',2,
        'financial_revision_digest',synthetic.financial_revision_digest,
        'target_authority_digest',synthetic.target_authority_digest,
        'conversion_context_digest',synthetic.conversion_context_digest,
        'physical_bucket_digest',md5(synthetic.physical_canonical_json::text),
        'economic_key_type',synthetic.economic_key_type,
        'economic_key_value',synthetic.economic_key_value,
        'truth_ex_vat',synthetic.truth_ex_vat,
        'baseline_ex_vat',synthetic.baseline_ex_vat,
        'reserved_ex_vat',synthetic.reserved_ex_vat)::text) AS sealed_evidence_digest,
      CASE WHEN ABS(ROUND(synthetic.outstanding_ex_vat,2))>0.005
        AND NOT synthetic.is_residual AND synthetic.source_units IS NOT NULL
        AND synthetic.source_rate IS NOT NULL
        AND synthetic.source_pay_method IS DISTINCT FROM synthetic.target_pay_method
        THEN 'READY' ELSE 'FIXED' END AS projection_status,
      economic.failure_code,
      jsonb_build_object(
        'source_key','SEALED_SYNTHETIC:'||synthetic.physical_bucket_key,
        'source_payload',jsonb_build_object(
          'source_kind',CASE WHEN synthetic.is_residual THEN 'WORKED_TIME_RESIDUAL'
            ELSE 'SEALED_BASELINE_COMPONENT' END,
          'source_value',synthetic.source_basis_json,
          'segment',synthetic.source_basis_json,
          'expense_code',CASE WHEN synthetic.economic_key_type='EXPENSE_CODE'
            THEN UPPER(synthetic.economic_key_value) END,
          'adjustment_id',CASE WHEN synthetic.economic_key_type='ADJUSTMENT_CODE'
            THEN synthetic.economic_key_value END),
        'physical_bucket',synthetic.physical_canonical_json||jsonb_build_object(
          'physical_bucket_digest',md5(synthetic.physical_canonical_json::text),
          'builder_comparison_digest',synthetic.builder_comparison_digest,
          'builder_component_amount_ex_vat',synthetic.outstanding_ex_vat,
          'builder_component_expected',ABS(ROUND(synthetic.outstanding_ex_vat,2))>0.005,
          'is_rate_bearing',NOT synthetic.is_residual
            AND synthetic.source_units IS NOT NULL AND synthetic.source_rate IS NOT NULL,
          'is_actionable_candidate',ABS(ROUND(synthetic.outstanding_ex_vat,2))>0.005
            AND NOT synthetic.is_residual
            AND synthetic.source_units IS NOT NULL AND synthetic.source_rate IS NOT NULL
            AND synthetic.source_pay_method IS DISTINCT FROM synthetic.target_pay_method),
        'sealed_physical_attribution',jsonb_build_object(
          'baseline_ex_vat',synthetic.baseline_ex_vat,
          'reserved_ex_vat',synthetic.reserved_ex_vat,
          'outstanding_ex_vat',synthetic.outstanding_ex_vat,
          'match_authorities',synthetic.match_authorities,
          'residual_contract_version',CASE WHEN synthetic.is_residual THEN 1 END),
        'economic_authority',(SELECT jsonb_build_object(
            'truth_inc_vat',economic_total.truth_inc_vat,
            'baseline_inc_vat',economic_total.baseline_inc_vat)
          FROM economic_totals economic_total
          WHERE economic_total.timesheet_id=synthetic.timesheet_id
            AND economic_total.economic_key_type=synthetic.economic_key_type
            AND economic_total.economic_key_value=synthetic.economic_key_value),
        'source_method_authority',method.evidence_json)
        AS evidence_json
    FROM synthetic_bucket_documents synthetic
    JOIN source_method_authority method
      USING(timesheet_id,economic_key_type,economic_key_value)
    LEFT JOIN economic_failures economic
      USING(timesheet_id,economic_key_type,economic_key_value)
    WHERE economic.failure_code IS NULL
  ), missing_authority AS (
    SELECT p_build_id,p_candidate_id,NULL::uuid,NULL::uuid,NULL::text,NULL::text,NULL::text,
      NULL::text,NULL::text,NULL::text,NULL::text,NULL::text,NULL::text,NULL::integer,
      NULL::text,NULL::text,NULL::numeric,NULL::numeric,NULL::numeric,NULL::numeric,
      NULL::numeric,NULL::numeric,NULL::numeric,NULL::numeric,NULL::text,NULL::text,
      NULL::uuid,NULL::boolean,NULL::boolean,NULL::numeric,NULL::numeric,NULL::text,NULL::text,
      NULL::text,NULL::text,'FAILED'::text,
      CASE
        WHEN NOT EXISTS(SELECT 1 FROM build_authority)
          THEN 'RATE_AUTHORITY_BUILD_NOT_FOUND'::text
        WHEN EXISTS(SELECT 1 FROM build_authority build
          WHERE build.candidate_id IS DISTINCT FROM p_candidate_id)
          THEN 'RATE_AUTHORITY_CANDIDATE_MISMATCH'::text
        ELSE 'RATE_AUTHORITY_SCOPE_NOT_FOUND'::text
      END,
      jsonb_build_object('build_id',p_build_id::text,'candidate_id',p_candidate_id::text)
    WHERE NOT EXISTS(SELECT 1 FROM scoped_facts)
  )
  SELECT * FROM failed_occurrences
  UNION ALL SELECT * FROM failed_economic_domain
  UNION ALL SELECT * FROM bucket_outputs
  UNION ALL SELECT * FROM synthetic_bucket_outputs
  UNION ALL SELECT * FROM missing_authority
  ORDER BY timesheet_id NULLS FIRST,economic_key_type NULLS FIRST,
    economic_key_value NULLS FIRST,bucket_sort_ordinal NULLS FIRST,
    physical_bucket_key NULLS FIRST;
$function$;

-- private.pay_workbench_semantic_ready_proof_page_v1(uuid,uuid[],jsonb,jsonb,text,jsonb)
CREATE OR REPLACE FUNCTION private.pay_workbench_semantic_ready_proof_page_v1(p_session_id uuid, p_candidate_ids uuid[], p_source_run_by_candidate_json jsonb DEFAULT '{}'::jsonb, p_selected_preview_row_ids_by_candidate_json jsonb DEFAULT NULL::jsonb, p_mode text DEFAULT 'PUBLICATION'::text, p_options_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_mode text := pg_catalog.upper(pg_catalog.btrim(COALESCE(p_mode, 'PUBLICATION')));
  v_candidate_ids uuid[] := COALESCE(p_candidate_ids, ARRAY[]::uuid[]);
  v_candidate_count integer := 0;
  v_result jsonb := '[]'::jsonb;
  v_semantic_ready boolean := false;
  v_publication_identity_enforce_enabled boolean := false;
BEGIN
  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SEMANTIC_READY_SESSION_REQUIRED'
      USING ERRCODE = '22023';
  END IF;

  IF v_mode NOT IN ('PUBLICATION', 'DRAFT_SELECTION', 'CANCELLATION_REVERSION', 'OBSERVE_ONLY') THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SEMANTIC_READY_MODE_INVALID: %', v_mode
      USING ERRCODE = '22023';
  END IF;

  IF p_source_run_by_candidate_json IS NOT NULL
     AND pg_catalog.jsonb_typeof(p_source_run_by_candidate_json) <> 'object' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SEMANTIC_READY_SOURCE_RUN_MAP_INVALID'
      USING ERRCODE = '22023';
  END IF;

  IF p_selected_preview_row_ids_by_candidate_json IS NOT NULL
     AND pg_catalog.jsonb_typeof(p_selected_preview_row_ids_by_candidate_json) <> 'object' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SEMANTIC_READY_SELECTION_MAP_INVALID'
      USING ERRCODE = '22023';
  END IF;

  IF p_options_json IS NULL OR pg_catalog.jsonb_typeof(p_options_json) <> 'object' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SEMANTIC_READY_OPTIONS_INVALID'
      USING ERRCODE = '22023';
  END IF;

  SELECT pg_catalog.count(*)::integer
  INTO v_candidate_count
  FROM (
    SELECT DISTINCT candidate_id
    FROM pg_catalog.unnest(v_candidate_ids) AS candidate_id
    WHERE candidate_id IS NOT NULL
  ) AS distinct_candidates;

  IF v_candidate_count < 1 OR v_candidate_count > 100 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SEMANTIC_READY_CANDIDATE_LIMIT: %', v_candidate_count
      USING ERRCODE = '22023';
  END IF;

  WITH requested_candidates AS (
    SELECT DISTINCT candidate_id
    FROM pg_catalog.unnest(v_candidate_ids) AS candidate_id
    WHERE candidate_id IS NOT NULL
  ), selected_ids AS (
    SELECT
      requested.candidate_id,
      selected_id.value::uuid AS preview_row_id
    FROM requested_candidates AS requested
    CROSS JOIN LATERAL pg_catalog.jsonb_array_elements_text(
      CASE
        WHEN pg_catalog.jsonb_typeof(p_selected_preview_row_ids_by_candidate_json -> requested.candidate_id::text) = 'array'
          THEN p_selected_preview_row_ids_by_candidate_json -> requested.candidate_id::text
        ELSE '[]'::jsonb
      END
    ) AS selected_id(value)
    WHERE selected_id.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ), ready_rows AS (
    SELECT
      preview_row.candidate_id,
      preview_row.id AS preview_row_id,
      preview_row.row_key,
      preview_row.row_json,
      preview_row.timesheet_id,
      preview_row.key_type,
      preview_row.key_value,
      preview_row.selected,
      preview_row.selection_state,
      public.pay_workbench_preview_line_contract_ok(
        p_line_json => preview_row.row_json
          || pg_catalog.jsonb_build_object(
            'row_key', preview_row.row_key,
            'selected', preview_row.selected,
            'selection_state', preview_row.selection_state,
            'status', preview_row.status
          ),
        p_economic_key_json => pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
          'timesheet_id', CASE WHEN preview_row.timesheet_id IS NULL THEN NULL ELSE preview_row.timesheet_id::text END,
          'key_type', preview_row.key_type,
          'key_value', preview_row.key_value
        )),
        p_target_section => CASE
          WHEN COALESCE(
                 preview_row.row_json#>>'{selection_recovery_headroom_v1,contract_version}',
                 ''
               ) = '1'
            THEN COALESCE(
              NULLIF(pg_catalog.btrim(
                preview_row.row_json#>>'{selection_recovery_headroom_v1,effective_section}'
              ), ''),
              NULLIF(pg_catalog.btrim(preview_row.section), ''),
              'canonical_preview_lines'
            )
          ELSE COALESCE(
            NULLIF(pg_catalog.btrim(preview_row.section), ''),
            'canonical_preview_lines'
          )
        END
      ) AS line_contract,
      CASE
        WHEN COALESCE(preview_row.row_json->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN pg_catalog.round((preview_row.row_json->>'amount_ex_vat')::numeric, 2)
        WHEN COALESCE(preview_row.row_json->>'preview_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN pg_catalog.round((preview_row.row_json->>'preview_amount_ex_vat')::numeric, 2)
        ELSE 0::numeric
      END AS amount_ex_vat,
      CASE
        WHEN v_mode = 'DRAFT_SELECTION'
          THEN EXISTS (
            SELECT 1
            FROM selected_ids AS selected_id
            WHERE selected_id.candidate_id = preview_row.candidate_id
              AND selected_id.preview_row_id = preview_row.id
          )
        ELSE true
      END AS included_in_proof
    FROM public.banking_pay_workbench_preview_rows AS preview_row
    JOIN requested_candidates AS requested
      ON requested.candidate_id = preview_row.candidate_id
    WHERE preview_row.session_id = p_session_id
      AND preview_row.status = 'READY'
  ), classified AS (
    SELECT
      ready_row.*,
      pg_catalog.lower(pg_catalog.btrim(COALESCE(ready_row.line_contract->>'ok', 'false')))
        IN ('true', 't', '1', 'yes', 'y', 'on') AS contract_ok,
      pg_catalog.lower(pg_catalog.btrim(COALESCE(ready_row.line_contract->>'selection_allowed', 'false')))
        IN ('true', 't', '1', 'yes', 'y', 'on') AS contract_selection_allowed,
      pg_catalog.lower(pg_catalog.btrim(COALESCE(ready_row.line_contract->>'is_recognised_finance_deduction', 'false')))
        IN ('true', 't', '1', 'yes', 'y', 'on') AS recognised_deduction,
      pg_catalog.upper(pg_catalog.btrim(COALESCE(ready_row.row_json->>'line_type', ready_row.row_json->>'case_type', ''))) AS line_type,
      pg_catalog.upper(pg_catalog.btrim(COALESCE(ready_row.row_json->>'presentation_role', ''))) AS presentation_role
    FROM ready_rows AS ready_row
  ), source_authority AS (
    SELECT
      requested.candidate_id,
      pg_catalog.count(DISTINCT source_row.source_publication_id)::integer AS source_publication_count,
      pg_catalog.min(source_row.source_publication_id::text)::uuid AS source_publication_id
    FROM requested_candidates AS requested
    LEFT JOIN public.banking_pay_workbench_candidate_source_lines AS source_row
      ON source_row.session_id=p_session_id
     AND source_row.candidate_id=requested.candidate_id
     AND source_row.status='CURRENT'
    GROUP BY requested.candidate_id
  ), candidate_rollup AS (
    SELECT
      requested.candidate_id,
      source_authority.source_publication_count,
      source_authority.source_publication_id,
      pg_catalog.count(classified.preview_row_id) FILTER (
        WHERE classified.included_in_proof
          AND classified.contract_ok
          AND classified.contract_selection_allowed
          AND NOT classified.recognised_deduction
          AND classified.amount_ex_vat > 0
          AND classified.line_type = 'TIMESHEET_PAYMENT'
          AND classified.presentation_role = 'ALLOCATION_COMPONENT'
      )::integer AS ordinary_positive_selectable_count,
      pg_catalog.round(COALESCE(pg_catalog.sum(classified.amount_ex_vat) FILTER (
        WHERE classified.included_in_proof
          AND classified.contract_ok
          AND classified.contract_selection_allowed
          AND NOT classified.recognised_deduction
          AND classified.amount_ex_vat > 0
          AND classified.line_type = 'TIMESHEET_PAYMENT'
          AND classified.presentation_role = 'ALLOCATION_COMPONENT'
      ), 0), 2) AS ordinary_positive_amount,
      pg_catalog.count(classified.preview_row_id) FILTER (
        WHERE classified.included_in_proof
          AND classified.contract_ok
          AND classified.contract_selection_allowed
          AND classified.recognised_deduction
          AND classified.amount_ex_vat < 0
      )::integer AS recognised_deduction_count,
      pg_catalog.round(COALESCE(pg_catalog.sum(classified.amount_ex_vat) FILTER (
        WHERE classified.included_in_proof
          AND classified.contract_ok
          AND classified.contract_selection_allowed
          AND classified.recognised_deduction
          AND classified.amount_ex_vat < 0
      ), 0), 2) AS recognised_deduction_amount,
      pg_catalog.count(classified.preview_row_id) FILTER (
        WHERE classified.included_in_proof
          AND (
            (classified.contract_selection_allowed AND NOT classified.contract_ok)
            OR (
              pg_catalog.upper(COALESCE(classified.selection_state, '')) <> 'NOT_SELECTABLE'
              AND NOT classified.contract_ok
            )
          )
      )::integer AS invalid_selectable_row_count,
      pg_catalog.count(classified.preview_row_id) FILTER (
        WHERE pg_catalog.lower(COALESCE(classified.row_json->>'draftable', 'false')) NOT IN ('true','t','1','yes','y','on')
      )::integer AS context_row_count,
      pg_catalog.count(classified.preview_row_id) FILTER (
        WHERE pg_catalog.upper(COALESCE(classified.row_json->>'presentation_section', classified.row_json->>'readiness_state', '')) = 'BLOCKED_FOR_PAY'
      )::integer AS blocked_row_count,
      pg_catalog.count(classified.preview_row_id) FILTER (
        WHERE classified.line_type = 'TIMESHEET_PAYMENT'
          AND classified.presentation_role = 'PARENT'
          AND classified.amount_ex_vat < 0
          AND pg_catalog.upper(COALESCE(classified.row_json->>'presentation_section', classified.row_json->>'readiness_state', '')) = 'READY_TO_PAY'
      )::integer AS invalid_ready_negative_parent_count,
      pg_catalog.count(classified.preview_row_id) FILTER (
        WHERE classified.line_type = 'TIMESHEET_PAYMENT'
          AND classified.presentation_role = 'PARENT'
          AND classified.amount_ex_vat < 0
          AND pg_catalog.upper(COALESCE(classified.row_json->>'presentation_section', classified.row_json->>'readiness_state', '')) = 'BLOCKED_FOR_PAY'
      )::integer AS negative_ordinary_blocked_count,
      pg_catalog.count(classified.preview_row_id) FILTER (
        WHERE classified.line_type = 'TIMESHEET_PAYMENT'
          AND classified.presentation_role = 'PARENT'
          AND classified.amount_ex_vat < 0
          AND pg_catalog.upper(COALESCE(classified.row_json->>'presentation_section', classified.row_json->>'readiness_state', '')) = 'CASES_RESOLUTIONS'
      )::integer AS negative_ordinary_cases_count,
      pg_catalog.md5(COALESCE(pg_catalog.string_agg(
        classified.preview_row_id::text || ':' ||
        pg_catalog.upper(COALESCE(classified.row_json->>'presentation_section', classified.row_json->>'readiness_state', '')),
        '|' ORDER BY classified.preview_row_id
      ), '')) AS presentation_section_digest,
      pg_catalog.count(classified.preview_row_id) FILTER (WHERE classified.included_in_proof)::integer AS proof_row_count
    FROM requested_candidates AS requested
    JOIN source_authority ON source_authority.candidate_id=requested.candidate_id
    LEFT JOIN classified
      ON classified.candidate_id = requested.candidate_id
    GROUP BY requested.candidate_id,source_authority.source_publication_count,
      source_authority.source_publication_id
  ), candidate_proof AS (
    SELECT
      rollup.*,
      pg_catalog.round(LEAST(
        GREATEST(rollup.ordinary_positive_amount, 0),
        GREATEST(-rollup.recognised_deduction_amount, 0)
      ), 2) AS usable_same_candidate_headroom,
      pg_catalog.round(rollup.ordinary_positive_amount + rollup.recognised_deduction_amount, 2) AS candidate_ready_amount,
      (
        rollup.invalid_selectable_row_count = 0
        AND (
          v_publication_identity_enforce_enabled IS NOT TRUE
          OR (rollup.source_publication_count=1 AND rollup.source_publication_id IS NOT NULL)
        )
        AND rollup.invalid_ready_negative_parent_count = 0
        AND rollup.ordinary_positive_amount >= 0
        AND (
          rollup.recognised_deduction_amount = 0
          OR (
            rollup.ordinary_positive_amount > 0
            AND -rollup.recognised_deduction_amount <= rollup.ordinary_positive_amount
          )
        )
        AND rollup.ordinary_positive_amount + rollup.recognised_deduction_amount >= 0
      ) AS semantic_ready
    FROM candidate_rollup AS rollup
  ), proof_json AS (
    SELECT
      proof.candidate_id,
      proof.semantic_ready,
      pg_catalog.jsonb_build_object(
        'candidate_id', proof.candidate_id::text,
        'mode', v_mode,
        'semantic_contract_version', 'READY_TO_PAY_SEMANTIC_V2',
        'source_publication_id', proof.source_publication_id,
        'source_publication_count', proof.source_publication_count,
        'ordinary_positive_selectable_count', proof.ordinary_positive_selectable_count,
        'ordinary_positive_amount', proof.ordinary_positive_amount,
        'recognised_deduction_count', proof.recognised_deduction_count,
        'recognised_deduction_amount', proof.recognised_deduction_amount,
        'usable_same_candidate_headroom', proof.usable_same_candidate_headroom,
        'candidate_ready_amount', proof.candidate_ready_amount,
        'context_row_count', proof.context_row_count,
        'blocked_row_count', proof.blocked_row_count,
        'invalid_ready_negative_parent_count', proof.invalid_ready_negative_parent_count,
        'negative_ordinary_blocked_count', proof.negative_ordinary_blocked_count,
        'negative_ordinary_cases_count', proof.negative_ordinary_cases_count,
        'presentation_section_digest', proof.presentation_section_digest,
        'invalid_selectable_row_count', proof.invalid_selectable_row_count,
        'proof_row_count', proof.proof_row_count,
        'negative_or_recovery_only', (
          proof.recognised_deduction_amount < 0
          AND proof.ordinary_positive_amount <= 0
        ),
        'cross_candidate_headroom_used', false,
        'semantic_ready', proof.semantic_ready,
        'source_run_hint', p_source_run_by_candidate_json -> proof.candidate_id::text
      ) AS proof_without_digest
    FROM candidate_proof AS proof
  )
  SELECT
    COALESCE(
      pg_catalog.jsonb_agg(
        proof.proof_without_digest
        || pg_catalog.jsonb_build_object(
          'semantic_proof_digest', pg_catalog.md5(
            (proof.proof_without_digest - 'mode' - 'source_run_hint')::text
          )
        )
        ORDER BY proof.candidate_id
      ),
      '[]'::jsonb
    ),
    pg_catalog.bool_and(proof.semantic_ready)
  INTO v_result, v_semantic_ready
  FROM proof_json AS proof;

  RETURN pg_catalog.jsonb_build_object(
    'ok', true,
    'proof_version', 1,
    'semantic_contract_version', 'READY_TO_PAY_SEMANTIC_V2',
    'mode', v_mode,
    'session_id', p_session_id::text,
    'candidate_count', v_candidate_count,
    'semantic_ready', COALESCE(v_semantic_ready, false),
    'candidate_results', COALESCE(v_result, '[]'::jsonb)
  );
END;
$function$;

-- private.pay_workbench_session_candidate_scope_ensure_v1(uuid,uuid,uuid,bigint,text)
CREATE OR REPLACE FUNCTION private.pay_workbench_session_candidate_scope_ensure_v1(p_session_id uuid, p_candidate_id uuid, p_dirty_job_id uuid, p_source_change_seq bigint, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_job public.banking_pay_workbench_jobs%ROWTYPE;
  v_session public.banking_pay_workbench_sessions%ROWTYPE;
  v_registry private.banking_pay_workbench_candidate_scope_registry%ROWTYPE;
  v_context jsonb := '{}'::jsonb;
  v_candidate_ids jsonb := '[]'::jsonb;
  v_filter_candidate_id uuid;
  v_filter_client_id uuid;
  v_eligible boolean := false;
  v_inserted boolean := false;
  v_scope_id uuid;
  v_scope_ordinal bigint;
BEGIN
  IF p_session_id IS NULL OR p_candidate_id IS NULL OR p_dirty_job_id IS NULL
     OR p_source_change_seq IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_ENSURE_ARGUMENT_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code','PAY_WORKBENCH_SCOPE_ENSURE_ARGUMENT_REQUIRED')::text;
  END IF;

  IF NOT pg_catalog.pg_try_advisory_xact_lock(
    pg_catalog.hashtextextended(
      public._pay_workbench_candidate_serial_key(p_candidate_id),
      24062027
    )
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_ENSURE_CANDIDATE_LOCK_NOT_OWNED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code','PAY_WORKBENCH_SCOPE_ENSURE_CANDIDATE_LOCK_NOT_OWNED',
              'candidate_id',p_candidate_id,
              'dirty_job_id',p_dirty_job_id
            )::text;
  END IF;

  SELECT job_row.*
  INTO v_job
  FROM public.banking_pay_workbench_jobs AS job_row
  WHERE job_row.id = p_dirty_job_id
  FOR UPDATE;

  IF NOT FOUND
     OR v_job.job_type <> 'WORKBENCH_CANDIDATE_DIRTY_APPLY'
     OR v_job.status <> 'RUNNING'
     OR v_job.candidate_id IS DISTINCT FROM p_candidate_id THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SCOPE_ENSURE_DIRTY_JOB_INVALID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code','PAY_WORKBENCH_SCOPE_ENSURE_DIRTY_JOB_INVALID',
              'job_id',p_dirty_job_id,
              'candidate_id',p_candidate_id
            )::text;
  END IF;

  SELECT registry_row.*
  INTO v_registry
  FROM private.banking_pay_workbench_candidate_scope_registry AS registry_row
  WHERE registry_row.candidate_id = p_candidate_id
  FOR UPDATE;

  IF NOT FOUND
     OR COALESCE(v_registry.current_source_change_seq, 0) <> p_source_change_seq THEN
    RETURN jsonb_build_object(
      'ok', true,
      'eligible', false,
      'inserted', false,
      'reused', false,
      'reason', 'SOURCE_CHANGE_SEQUENCE_STALE'
    );
  END IF;

  SELECT session_row.*
  INTO v_session
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id = p_session_id
  FOR UPDATE;

  IF NOT FOUND
     OR pg_catalog.upper(pg_catalog.btrim(COALESCE(v_session.status,''))) <> 'OPEN'
     OR v_session.discarded_at_utc IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'eligible', false,
      'inserted', false,
      'reused', false,
      'reason', 'SESSION_NOT_OPEN'
    );
  END IF;

  IF pg_catalog.btrim(COALESCE(
       v_session.filters_json->>'candidate_id',
       v_session.filters_json->>'candidateId',''
     )) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_filter_candidate_id := COALESCE(
      v_session.filters_json->>'candidate_id',
      v_session.filters_json->>'candidateId'
    )::uuid;
  END IF;

  IF v_filter_candidate_id IS NOT NULL
     AND v_filter_candidate_id IS DISTINCT FROM p_candidate_id THEN
    RETURN jsonb_build_object(
      'ok', true,
      'eligible', false,
      'inserted', false,
      'reused', false,
      'reason', 'CANDIDATE_FILTER_EXCLUDED'
    );
  END IF;

  IF pg_catalog.btrim(COALESCE(
       v_session.filters_json->>'client_id',
       v_session.filters_json->>'clientId',''
     )) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_filter_client_id := COALESCE(
      v_session.filters_json->>'client_id',
      v_session.filters_json->>'clientId'
    )::uuid;
  END IF;

  v_context := public.pay_preview_build_context(
    p_pay_date => v_session.pay_date,
    p_week_ending_cutoff => v_session.week_ending_cutoff,
    p_actor_user_id => v_session.actor_user_id,
    p_candidate_id => p_candidate_id,
    p_client_id => v_filter_client_id,
    p_preview_decisions_json => COALESCE(v_session.filters_json,'{}'::jsonb)
      || jsonb_build_object(
        'preview_context_mode','PAGE',
        'scope_limit',1,
        'scope_cursor',NULL::jsonb,
        'scope_candidate_ensure',true
      )
  );

  v_candidate_ids := CASE
    WHEN jsonb_typeof(v_context->'candidate_ids') = 'array'
      THEN COALESCE(v_context->'candidate_ids','[]'::jsonb)
    WHEN jsonb_typeof(v_context->'scope_candidate_ids') = 'array'
      THEN COALESCE(v_context->'scope_candidate_ids','[]'::jsonb)
    ELSE '[]'::jsonb
  END;

  SELECT EXISTS (
    SELECT 1
    FROM jsonb_array_elements_text(v_candidate_ids) AS candidate_value(value)
    WHERE pg_catalog.btrim(candidate_value.value) ~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      AND pg_catalog.btrim(candidate_value.value)::uuid = p_candidate_id
  ) INTO v_eligible;

  IF NOT v_eligible THEN
    RETURN jsonb_build_object(
      'ok', true,
      'eligible', false,
      'inserted', false,
      'reused', false,
      'reason', 'CANDIDATE_NOT_SESSION_ELIGIBLE'
    );
  END IF;

  SELECT scope_row.id, scope_row.scope_ordinal
  INTO v_scope_id, v_scope_ordinal
  FROM public.banking_pay_workbench_session_scope AS scope_row
  WHERE scope_row.session_id = p_session_id
    AND scope_row.candidate_id = p_candidate_id
  FOR UPDATE;

  IF NOT FOUND THEN
    SELECT COALESCE(pg_catalog.max(scope_row.scope_ordinal),0) + 1
    INTO v_scope_ordinal
    FROM public.banking_pay_workbench_session_scope AS scope_row
    WHERE scope_row.session_id = p_session_id;

    INSERT INTO public.banking_pay_workbench_session_scope(
      session_id,candidate_id,scope_ordinal,status,pending_job_id,
      seeded,dirty,error_json,created_at_utc,updated_at_utc
    )
    VALUES(
      p_session_id,p_candidate_id,v_scope_ordinal,'PENDING',NULL,
      true,true,NULL,v_now,v_now
    )
    ON CONFLICT (session_id,candidate_id) DO NOTHING
    RETURNING id INTO v_scope_id;

    v_inserted := v_scope_id IS NOT NULL;

    IF NOT v_inserted THEN
      SELECT scope_row.id, scope_row.scope_ordinal
      INTO v_scope_id, v_scope_ordinal
      FROM public.banking_pay_workbench_session_scope AS scope_row
      WHERE scope_row.session_id = p_session_id
        AND scope_row.candidate_id = p_candidate_id
      FOR UPDATE;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'eligible', true,
    'inserted', v_inserted,
    'reused', NOT v_inserted,
    'baseline_required', v_inserted,
    'baseline_resolution_required', v_inserted,
    'scope_id', v_scope_id,
    'scope_ordinal', v_scope_ordinal,
    'source_change_seq', p_source_change_seq,
    'reason', CASE WHEN v_inserted THEN 'NEW_SCOPE_BASELINE_REQUIRED' ELSE COALESCE(NULLIF(p_reason,''),'SCOPE_REUSED') END
  );
END;
$function$;

-- private.pay_workbench_session_clone_bounded_certification_v1(uuid,uuid,uuid,jsonb)
CREATE OR REPLACE FUNCTION private.pay_workbench_session_clone_bounded_certification_v1(p_source_session_id uuid, p_target_session_id uuid, p_candidate_id uuid, p_options_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_source_session public.banking_pay_workbench_sessions%ROWTYPE;
  v_target_session public.banking_pay_workbench_sessions%ROWTYPE;
  v_source_scope public.banking_pay_workbench_session_scope%ROWTYPE;
  v_registry private.banking_pay_workbench_candidate_scope_registry%ROWTYPE;
  v_candidate public.candidates%ROWTYPE;
  v_build private.banking_pay_workbench_economic_builds%ROWTYPE;
  v_current_source_change_seq bigint := 0;
  v_source_count integer := 0;
  v_source_run_count integer := 0;
  v_source_build_run_id uuid := NULL::uuid;
  v_source_seq_min bigint := NULL::bigint;
  v_source_seq_max bigint := NULL::bigint;
  v_source_digest text := NULL::text;
  v_source_identity_digest text := NULL::text;
  v_preview_identity_digest text := NULL::text;
  v_ready_preview_count integer := 0;
  v_active_preview_poison_count integer := 0;
  v_bad_ready_preview_count integer := 0;
  v_active_line_work_count integer := 0;
  v_active_job_count integer := 0;
  v_bad_timesheet_scope_count integer := 0;
  v_matching_build_count integer := 0;
  v_matching_build_digest_count integer := 0;
  v_noncloneable_complexity_count integer := 0;
  v_payee_mismatch_count integer := 0;
  v_rail_provider text := 'CSV';
  v_rail_env text := 'PROD';
  v_need_name_check boolean := false;
  v_requires_payee_map boolean := false;
  v_readiness_mismatch boolean := false;
  v_umbrella_bank_hash text := NULL::text;
  v_umbrella_enabled boolean := false;
  v_proof_digest text := NULL::text;
  v_options_json jsonb := CASE
    WHEN pg_catalog.jsonb_typeof(coalesce(p_options_json, '{}'::jsonb)) = 'object'
      THEN coalesce(p_options_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_option_source_session_id_text text := NULL::text;
  v_option_target_session_id_text text := NULL::text;
  v_option_source_session_id uuid := NULL::uuid;
  v_option_target_session_id uuid := NULL::uuid;
  v_controlled_clone_rebase boolean := false;
  v_final_fence_mode boolean := false;
  v_clone_job_id uuid := NULL::uuid;
  v_source_mode text := 'NONEMPTY';
  v_certification_digest text := NULL::text;
  v_live_eligibility jsonb := '{}'::jsonb;
BEGIN
  IF p_source_session_id IS NULL
     OR p_target_session_id IS NULL
     OR p_candidate_id IS NULL THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', true,
      'clone_eligible', false,
      'bounded_build_certified', false,
      'reason', 'SOURCE_TARGET_AND_CANDIDATE_REQUIRED',
      'required_refresh_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
    );
  END IF;

  SELECT source_session.*
  INTO v_source_session
  FROM public.banking_pay_workbench_sessions AS source_session
  WHERE source_session.id = p_source_session_id
    AND (
      (
        pg_catalog.upper(pg_catalog.btrim(coalesce(source_session.status, ''))) = 'OPEN'
        AND source_session.discarded_at_utc IS NULL
      )
      OR (
        pg_catalog.upper(pg_catalog.btrim(coalesce(source_session.status, ''))) = 'DISCARDED'
        AND source_session.discarded_at_utc IS NOT NULL
      )
    )
  FOR SHARE;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', true,
      'clone_eligible', false,
      'bounded_build_certified', false,
      'reason', 'SOURCE_SESSION_NOT_AVAILABLE',
      'required_refresh_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
    );
  END IF;

  SELECT target_session.*
  INTO v_target_session
  FROM public.banking_pay_workbench_sessions AS target_session
  WHERE target_session.id = p_target_session_id
    AND pg_catalog.upper(pg_catalog.btrim(coalesce(target_session.status, ''))) = 'OPEN'
    AND target_session.discarded_at_utc IS NULL
  FOR SHARE;

  IF NOT FOUND
     OR v_source_session.pay_date IS NULL
     OR v_target_session.pay_date IS NULL
     OR v_source_session.pay_date >= v_target_session.pay_date THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', true,
      'clone_eligible', false,
      'bounded_build_certified', false,
      'reason', 'SOURCE_TARGET_SESSION_SCOPE_MISMATCH',
      'required_refresh_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
    );
  END IF;

  v_option_source_session_id_text := NULLIF(pg_catalog.btrim(coalesce(
    v_options_json->>'source_session_id',
    v_options_json->>'source_session_id_text',
    v_options_json->>'clone_from_session_id',
    v_options_json->>'replacement_source_session_id',
    ''
  )), '');

  IF v_option_source_session_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_option_source_session_id := v_option_source_session_id_text::uuid;
  END IF;

  v_option_target_session_id_text := NULLIF(pg_catalog.btrim(coalesce(
    v_options_json->>'target_session_id',
    v_options_json->>'session_id',
    v_options_json->>'clone_to_session_id',
    ''
  )), '');

  IF v_option_target_session_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_option_target_session_id := v_option_target_session_id_text::uuid;
  END IF;
  v_final_fence_mode := pg_catalog.lower(pg_catalog.btrim(coalesce(
    v_options_json->>'final_fence_mode','false'
  ))) IN ('true','t','1','yes','y','on');

  IF NULLIF(pg_catalog.btrim(coalesce(
       v_options_json->>'clone_job_id',
       v_options_json->>'source_job_id',
       ''
     )), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_clone_job_id := NULLIF(pg_catalog.btrim(coalesce(
      v_options_json->>'clone_job_id',v_options_json->>'source_job_id',''
    )), '')::uuid;
  END IF;

  v_controlled_clone_rebase := (
    (
      pg_catalog.upper(pg_catalog.btrim(coalesce(
        v_options_json->>'job_type',
        v_options_json->>'operation_type',
        v_options_json->>'created_by_helper',
        ''
      ))) IN (
        'WORKBENCH_SESSION_CLONE_REBASE',
        'SESSION_CLONE_REBASE',
        'CLONE_REBASE',
        'PAY_WORKBENCH_SESSION_OPEN_SHARED_V2'
      )
      OR pg_catalog.lower(pg_catalog.btrim(coalesce(
        v_options_json->>'allow_session_rebase',
        v_options_json->>'allowSessionRebase',
        'false'
      ))) IN ('true', 't', '1', 'yes', 'y', 'on')
      OR pg_catalog.upper(pg_catalog.btrim(coalesce(
        v_options_json->>'clone_mode',
        v_options_json->>'cloneMode',
        ''
      ))) IN ('CERTIFIED_SIMPLE_ONLY', 'CERTIFIED_ONLY')
    )
    AND pg_catalog.lower(pg_catalog.btrim(coalesce(
      v_options_json->>'rebase_simple_rows_only',
      v_options_json->>'rebaseSimpleRowsOnly',
      'true'
    ))) IN ('true', 't', '1', 'yes', 'y', 'on')
    AND v_option_source_session_id_text IS NOT NULL
    AND v_option_source_session_id = p_source_session_id
    AND v_option_target_session_id_text IS NOT NULL
    AND v_option_target_session_id = p_target_session_id
    AND (
      v_final_fence_mode IS TRUE
      OR pg_catalog.upper(pg_catalog.btrim(coalesce(v_target_session.progress_state, ''))) = 'CLONE_REBASING'
      OR NULLIF(pg_catalog.btrim(coalesce(
        v_target_session.progress_json->>'clone_from_session_id',
        ''
      )), '') = p_source_session_id::text
      OR pg_catalog.lower(pg_catalog.btrim(coalesce(v_options_json->>'source_selection_authorised','false'))) IN ('true','t','1','yes','y','on')
    )
  );

  IF coalesce(v_controlled_clone_rebase, false) IS NOT TRUE THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', true,
      'clone_eligible', false,
      'bounded_build_certified', false,
      'reason', 'CONTROLLED_CLONE_REBASE_NOT_AUTHORISED',
      'required_refresh_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
    );
  END IF;

  v_live_eligibility := public.pay_workbench_session_clone_eligibility_v1(
    p_source_session_id,
    p_target_session_id,
    p_candidate_id,
    v_options_json || pg_catalog.jsonb_build_object(
      'source_session_id',p_source_session_id::text,
      'target_session_id',p_target_session_id::text,
      'source_selection_authorised',true,
      'allow_session_rebase',true,
      'rebase_simple_rows_only',true
    )
  );

  IF coalesce((v_live_eligibility->>'target_date_eligible')::boolean,false) IS NOT TRUE THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok',true,
      'clone_eligible',false,
      'bounded_build_certified',false,
      'reason',coalesce(
        nullif(v_live_eligibility->>'reason',''),
        'TARGET_DATE_REUSE_NOT_CERTIFIED'
      ),
      'required_refresh_job_type','WORKBENCH_CANDIDATE_SOURCE_BUILD'
    );
  END IF;

  SELECT source_scope.*
  INTO v_source_scope
  FROM public.banking_pay_workbench_session_scope AS source_scope
  WHERE source_scope.session_id = p_source_session_id
    AND source_scope.candidate_id = p_candidate_id
    AND pg_catalog.upper(pg_catalog.btrim(coalesce(source_scope.status, '')))
          IN ('READY', 'MATERIALISED', 'MATERIALIZED')
    AND coalesce(source_scope.certified_preview_publication_required,false) IS TRUE
    AND coalesce(source_scope.certified_preview_publication_parity_ok,false) IS TRUE
    AND coalesce(source_scope.dirty, false) IS NOT TRUE
    AND source_scope.pending_job_id IS NULL
  FOR SHARE;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', true,
      'clone_eligible', false,
      'bounded_build_certified', false,
      'reason', 'SOURCE_SCOPE_NOT_CURRENT',
      'required_refresh_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
    );
  END IF;

  SELECT registry.*
  INTO v_registry
  FROM private.banking_pay_workbench_candidate_scope_registry AS registry
  WHERE registry.candidate_id = p_candidate_id
    AND registry.initialisation_status = 'READY'
    AND registry.evaluated_generation = registry.dirty_generation
    AND registry.failure_json = '{}'::jsonb
  FOR SHARE;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', true,
      'clone_eligible', false,
      'bounded_build_certified', false,
      'reason', 'CANDIDATE_REGISTRY_NOT_CURRENT',
      'required_refresh_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
    );
  END IF;

  SELECT coalesce(change_counter.seq, 0)
  INTO v_current_source_change_seq
  FROM (SELECT 1) AS authority_anchor
  LEFT JOIN public.app_change_counters AS change_counter
    ON change_counter.entity_key = 'pay_candidate:' || p_candidate_id::text;

  IF v_registry.current_source_change_seq IS DISTINCT FROM v_current_source_change_seq THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', true,
      'clone_eligible', false,
      'bounded_build_certified', false,
      'reason', 'SOURCE_CHANGE_SEQUENCE_STALE',
      'required_refresh_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
    );
  END IF;

  SELECT
    pg_catalog.count(*)::integer,
    pg_catalog.count(DISTINCT source_line.source_build_run_id)::integer,
    (pg_catalog.array_agg(source_line.source_build_run_id ORDER BY source_line.source_build_run_id))[1],
    pg_catalog.min(source_line.source_change_seq),
    pg_catalog.max(source_line.source_change_seq),
    pg_catalog.md5(coalesce(
      pg_catalog.string_agg(
        pg_catalog.md5(source_line.source_row_json::text),
        '' ORDER BY source_line.source_ordinal
      ),
      ''
    )),
    pg_catalog.md5(coalesce(
      pg_catalog.string_agg(
        public.pay_workbench_preview_section_from_line_json(source_line.source_row_json)
          || E'\x1f' || source_line.line_key || E'\x1f' || source_line.source_ordinal::text,
        E'\x1e' ORDER BY source_line.source_ordinal,
          public.pay_workbench_preview_section_from_line_json(source_line.source_row_json),
          source_line.line_key
      ),
      ''
    ))
  INTO
    v_source_count,
    v_source_run_count,
    v_source_build_run_id,
    v_source_seq_min,
    v_source_seq_max,
    v_source_digest,
    v_source_identity_digest
  FROM public.banking_pay_workbench_candidate_source_lines AS source_line
  WHERE source_line.session_id = p_source_session_id
    AND source_line.candidate_id = p_candidate_id
    AND source_line.session_version = v_source_session.version
    AND source_line.status = 'CURRENT';

  IF coalesce(v_source_count,0)=0 THEN
    v_source_mode := 'SOURCE_EMPTY';
    v_source_build_run_id := v_source_scope.certified_preview_publication_source_build_run_id;
    v_source_run_count := CASE WHEN v_source_build_run_id IS NULL THEN 0 ELSE 1 END;
    v_source_seq_min := v_current_source_change_seq;
    v_source_seq_max := v_current_source_change_seq;
    v_source_digest := pg_catalog.md5('');
  END IF;
  IF v_source_run_count <> 1
     OR v_source_build_run_id IS NULL
     OR v_source_seq_min IS DISTINCT FROM v_current_source_change_seq
     OR v_source_seq_max IS DISTINCT FROM v_current_source_change_seq THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', true,
      'clone_eligible', false,
      'bounded_build_certified', false,
      'reason', 'CURRENT_SOURCE_BUILD_AUTHORITY_INCOMPLETE',
      'required_refresh_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
    );
  END IF;

  SELECT
    pg_catalog.count(*)::integer,
    pg_catalog.count(DISTINCT candidate_build.canonical_digest)::integer
  INTO v_matching_build_count, v_matching_build_digest_count
  FROM private.banking_pay_workbench_economic_builds AS candidate_build
  WHERE candidate_build.candidate_id = p_candidate_id
    AND candidate_build.source_build_run_id = v_source_build_run_id
    AND candidate_build.status = 'COMPLETE'
    AND candidate_build.private_stage = 'COMPLETE'
    AND candidate_build.completed_at_utc IS NOT NULL
    AND candidate_build.failure_json = '{}'::jsonb
    AND candidate_build.source_change_seq = v_current_source_change_seq
    AND candidate_build.captured_candidate_generation = v_registry.evaluated_generation
    AND candidate_build.canonical_count = v_source_count
    AND candidate_build.canonical_digest = v_source_digest
    AND candidate_build.sealed_fingerprint_digest IS NOT NULL
    AND coalesce((candidate_build.attestation_json->>'effect_plan_sealed')::boolean,false) IS TRUE
    AND NULLIF(candidate_build.attestation_json->>'effect_plan_digest','') IS NOT NULL
    AND NULLIF(candidate_build.attestation_json->>'observed_finance_effect_digest','') IS NOT NULL
    AND candidate_build.attestation_json->>'observed_finance_effect_count' ~ '^[0-9]+$'
    AND candidate_build.pre_sync_digest IS NOT NULL
    AND candidate_build.post_sync_digest IS NOT NULL
    AND candidate_build.canonical_digest IS NOT NULL
    AND candidate_build.dependency_closure_sealed_at_utc IS NOT NULL
    AND candidate_build.dependency_edge_stream_complete IS TRUE
    AND candidate_build.edge_tag_stream_complete IS TRUE
    AND pg_catalog.lower(coalesce(candidate_build.publication_cursor_json->>'terminal', 'false'))
          IN ('true', 't', '1', 'yes', 'y', 'on');

  IF v_matching_build_count < 1 OR v_matching_build_digest_count <> 1 THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', true,
      'clone_eligible', false,
      'bounded_build_certified', false,
      'reason', 'COMPLETE_BUILD_PUBLICATION_NOT_PROVEN',
      'required_refresh_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
    );
  END IF;

  SELECT candidate_build.*
  INTO v_build
  FROM private.banking_pay_workbench_economic_builds AS candidate_build
  WHERE candidate_build.candidate_id = p_candidate_id
    AND candidate_build.source_build_run_id = v_source_build_run_id
    AND candidate_build.status = 'COMPLETE'
    AND candidate_build.private_stage = 'COMPLETE'
    AND candidate_build.source_change_seq = v_current_source_change_seq
    AND candidate_build.captured_candidate_generation = v_registry.evaluated_generation
    AND candidate_build.canonical_count = v_source_count
    AND candidate_build.canonical_digest = v_source_digest
  ORDER BY candidate_build.completed_at_utc DESC, candidate_build.id
  LIMIT 1
  FOR SHARE;

  SELECT pg_catalog.count(*)::integer
  INTO v_bad_timesheet_scope_count
  FROM private.banking_pay_workbench_economic_build_scope AS build_scope
  LEFT JOIN private.banking_pay_workbench_timesheet_scope_state AS timesheet_state
    ON timesheet_state.timesheet_id = build_scope.timesheet_id
   AND timesheet_state.candidate_id = p_candidate_id
  WHERE build_scope.build_id = v_build.id
    AND (
      timesheet_state.timesheet_id IS NULL
      OR timesheet_state.evaluated_generation IS DISTINCT FROM timesheet_state.dirty_generation
      OR timesheet_state.current_input_fingerprint IS NULL
      OR timesheet_state.evaluated_input_fingerprint IS DISTINCT FROM timesheet_state.current_input_fingerprint
      OR build_scope.captured_input_fingerprint IS DISTINCT FROM timesheet_state.current_input_fingerprint
    );

  IF v_bad_timesheet_scope_count > 0
     OR (SELECT pg_catalog.count(*) FROM private.banking_pay_workbench_economic_build_scope AS build_scope WHERE build_scope.build_id = v_build.id)
          IS DISTINCT FROM v_build.scope_count::bigint THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', true,
      'clone_eligible', false,
      'bounded_build_certified', false,
      'reason', 'SEALED_TIMESHEET_SCOPE_NOT_CURRENT',
      'required_refresh_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
    );
  END IF;

  SELECT
    pg_catalog.count(*) FILTER (WHERE preview_row.status = 'READY')::integer,
    pg_catalog.count(*) FILTER (
      WHERE pg_catalog.upper(pg_catalog.btrim(coalesce(preview_row.status, '')))
            IN ('DIRTY', 'ERROR', 'FAILED', 'PENDING')
    )::integer,
    pg_catalog.count(*) FILTER (
      WHERE preview_row.status = 'READY'
        AND (
          pg_catalog.jsonb_typeof(coalesce(preview_row.row_json, '{}'::jsonb)) <> 'object'
          OR
          pg_catalog.upper(pg_catalog.btrim(coalesce(preview_row.row_json->>'policy_x_authority_scope', ''))) <> 'PRE_DRAFT_LIVE_TRUTH'
        )
    )::integer
  INTO v_ready_preview_count, v_active_preview_poison_count, v_bad_ready_preview_count
  FROM public.banking_pay_workbench_preview_rows AS preview_row
  WHERE preview_row.session_id = p_source_session_id
    AND preview_row.candidate_id = p_candidate_id
    AND preview_row.session_version = v_source_session.version;

  SELECT pg_catalog.count(*)::integer
  INTO v_active_line_work_count
  FROM public.banking_pay_workbench_candidate_line_work AS line_work
  WHERE line_work.session_id = p_source_session_id
    AND line_work.candidate_id = p_candidate_id
    AND pg_catalog.upper(pg_catalog.btrim(coalesce(line_work.status, '')))
          IN ('PENDING', 'READY', 'ERROR', 'FAILED');

  SELECT pg_catalog.count(*)::integer
  INTO v_active_job_count
  FROM public.banking_pay_workbench_jobs AS job_row
  WHERE job_row.candidate_id = p_candidate_id
    AND pg_catalog.upper(pg_catalog.btrim(coalesce(job_row.status, '')))
          IN ('QUEUED', 'PENDING', 'CLAIMED', 'RUNNING', 'PROCESSING')
    AND (
      job_row.session_id IN (p_source_session_id, p_target_session_id)
      OR job_row.session_id IS NULL
    )
    AND (v_clone_job_id IS NULL OR job_row.id <> v_clone_job_id);

  SELECT pg_catalog.md5(coalesce(pg_catalog.string_agg(
    preview_row.section || E'\x1f' || preview_row.row_key || E'\x1f'
      || (preview_row.row_ordinal - (v_source_scope.scope_ordinal * 1000000))::text,
    E'\x1e' ORDER BY preview_row.row_ordinal,preview_row.section,preview_row.row_key
  ),''))
  INTO v_preview_identity_digest
  FROM public.banking_pay_workbench_preview_rows AS preview_row
  WHERE preview_row.session_id=p_source_session_id
    AND preview_row.candidate_id=p_candidate_id
    AND preview_row.session_version=v_source_session.version
    AND preview_row.status='READY';

  IF v_ready_preview_count IS DISTINCT FROM v_source_count
     OR v_source_identity_digest IS DISTINCT FROM v_preview_identity_digest
     OR coalesce(v_source_scope.certified_preview_publication_attestation_json->>'source_row_count','')
          IS DISTINCT FROM v_source_count::text
     OR coalesce(v_source_scope.certified_preview_publication_attestation_json->>'preview_row_count','')
          IS DISTINCT FROM v_ready_preview_count::text
     OR nullif(v_source_scope.certified_preview_publication_attestation_json->>'source_identity_digest','')
          IS DISTINCT FROM v_source_identity_digest
     OR nullif(v_source_scope.certified_preview_publication_attestation_json->>'preview_identity_digest','')
          IS DISTINCT FROM v_preview_identity_digest
     OR v_source_scope.certified_preview_publication_source_build_run_id IS DISTINCT FROM v_source_build_run_id
     OR v_source_scope.certified_preview_publication_source_change_seq IS DISTINCT FROM v_current_source_change_seq
     OR v_source_scope.certified_preview_publication_session_version IS DISTINCT FROM v_source_session.version
     OR NOT (
       (
         v_source_scope.certified_preview_publication_attestation_json->>'attestation_version'
           = 'CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V1'
         AND v_source_scope.certified_preview_publication_attestation_json->>'authority_kind'
           = 'BOUNDED_FULL_SOURCE_BUILD'
       )
       OR (
         v_source_scope.certified_preview_publication_attestation_json->>'attestation_version'
           = 'CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V2'
         AND v_source_scope.certified_preview_publication_attestation_json->>'authority_kind'
           IN ('CERTIFIED_CLONE','TARGETED_DELTA')
         AND v_source_scope.certified_preview_publication_attestation_json->>'final_state'
           IN ('READY','SOURCE_EMPTY')
       )
     ) THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok',true,
      'clone_eligible',false,
      'bounded_build_certified',false,
      'reason','CERTIFIED_PUBLICATION_ATTESTATION_DRIFT',
      'required_refresh_job_type','WORKBENCH_CANDIDATE_SOURCE_BUILD'
    );
  END IF;

  IF (v_source_mode='NONEMPTY' AND v_ready_preview_count = 0)
     OR v_active_preview_poison_count > 0
     OR v_bad_ready_preview_count > 0
     OR v_active_line_work_count > 0
     OR v_active_job_count > 0
     OR NOT EXISTS (
       SELECT 1
       FROM public.banking_pay_workbench_session_candidate_state AS candidate_state
       WHERE candidate_state.session_id = p_source_session_id
         AND candidate_state.candidate_id = p_candidate_id
         AND candidate_state.status = 'READY'
         AND candidate_state.session_version = v_source_session.version
         AND candidate_state.source_change_seq = v_current_source_change_seq
         AND candidate_state.pending_job_id IS NULL
     ) THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', true,
      'clone_eligible', false,
      'bounded_build_certified', false,
      'reason', 'PUBLISHED_PREVIEW_NOT_CURRENT',
      'required_refresh_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
    );
  END IF;

  -- These authorities can change merely because a date/session boundary is
  -- crossed.  They remain full-build-only even where the last economic build
  -- itself is complete.
  SELECT (
    SELECT pg_catalog.count(*)
    FROM public.pay_item_snoozes AS snooze_row
    WHERE snooze_row.candidate_id = p_candidate_id
      AND snooze_row.cleared_at_utc IS NULL
      AND snooze_row.cancelled_at_utc IS NULL
  ) + (
    SELECT pg_catalog.count(*)
    FROM public.pay_advances AS advance_row
    WHERE advance_row.candidate_id = p_candidate_id
      AND pg_catalog.upper(pg_catalog.btrim(coalesce(advance_row.status::text, ''))) IN ('ACTIVE', 'PAUSED')
      AND advance_row.cleared_at_utc IS NULL
      AND advance_row.written_off_at_utc IS NULL
  ) + (
    SELECT pg_catalog.count(*)
    FROM public.timesheet_payment_overrides AS override_row
    WHERE override_row.candidate_id = p_candidate_id
      AND override_row.consumed_at_utc IS NULL
      AND override_row.cleared_at_utc IS NULL
  ) + (
    SELECT pg_catalog.count(*)
    FROM public.ts_pay_adjustments AS adjustment_row
    WHERE adjustment_row.candidate_id = p_candidate_id
      AND adjustment_row.paid_at_utc IS NULL
  ) + (
    SELECT pg_catalog.count(*)
    FROM public.banking_pay_workbench_session_case_resolutions AS resolution_row
    WHERE resolution_row.session_id IN (p_source_session_id, p_target_session_id)
      AND resolution_row.candidate_id = p_candidate_id
  )
  INTO v_noncloneable_complexity_count;

  IF v_noncloneable_complexity_count > 0 THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', true,
      'clone_eligible', false,
      'bounded_build_certified', false,
      'reason', 'TIME_OR_SESSION_SENSITIVE_AUTHORITY_REQUIRES_FULL_BUILD',
      'required_refresh_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
    );
  END IF;

  SELECT candidate_row.*
  INTO v_candidate
  FROM public.candidates AS candidate_row
  WHERE candidate_row.id = p_candidate_id
  FOR SHARE;

  SELECT umbrella_row.bank_details_hash, coalesce(umbrella_row.enabled, false)
  INTO v_umbrella_bank_hash, v_umbrella_enabled
  FROM public.umbrellas AS umbrella_row
  WHERE umbrella_row.id = v_candidate.umbrella_id;

  SELECT
    pg_catalog.upper(pg_catalog.btrim(coalesce(settings_row.rail_provider_default, 'CSV'))),
    pg_catalog.upper(pg_catalog.btrim(coalesce(settings_row.rail_env_default, 'PROD'))),
    coalesce(settings_row.rail_supports_name_check, false)
      AND pg_catalog.upper(pg_catalog.btrim(coalesce(settings_row.rail_provider_default, 'CSV'))) <> 'CSV',
    pg_catalog.upper(pg_catalog.btrim(coalesce(settings_row.rail_provider_default, 'CSV'))) <> 'CSV'
  INTO v_rail_provider, v_rail_env, v_need_name_check, v_requires_payee_map
  FROM public.settings_defaults AS settings_row
  WHERE settings_row.id = 1;

  SELECT pg_catalog.count(*)::integer
  INTO v_payee_mismatch_count
  FROM public.banking_pay_workbench_preview_rows AS preview_row
  WHERE preview_row.session_id = p_source_session_id
    AND preview_row.candidate_id = p_candidate_id
    AND preview_row.session_version = v_source_session.version
    AND preview_row.status = 'READY'
    AND (
      pg_catalog.upper(pg_catalog.btrim(coalesce(preview_row.row_json->>'pay_channel', ''))) NOT IN ('PAYE', 'UMBRELLA')
      OR (
        pg_catalog.upper(pg_catalog.btrim(coalesce(preview_row.row_json->>'pay_channel', ''))) = 'PAYE'
        AND (
          pg_catalog.upper(pg_catalog.btrim(coalesce(v_candidate.pay_method, ''))) <> 'PAYE'
          OR nullif(pg_catalog.btrim(coalesce(preview_row.row_json#>>'{payee_context,payee_bank_hash}', '')), '')
               IS DISTINCT FROM nullif(pg_catalog.btrim(coalesce(v_candidate.bank_details_hash, '')), '')
        )
      )
      OR (
        pg_catalog.upper(pg_catalog.btrim(coalesce(preview_row.row_json->>'pay_channel', ''))) = 'UMBRELLA'
        AND (
          pg_catalog.upper(pg_catalog.btrim(coalesce(v_candidate.pay_method, ''))) <> 'UMBRELLA'
          OR v_candidate.umbrella_id IS NULL
          OR v_umbrella_enabled IS NOT TRUE
          OR nullif(pg_catalog.btrim(coalesce(preview_row.row_json#>>'{payee_context,payee_bank_hash}', '')), '')
               IS DISTINCT FROM nullif(pg_catalog.btrim(coalesce(v_umbrella_bank_hash, '')), '')
        )
      )
    );

  IF v_payee_mismatch_count > 0 THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', true,
      'clone_eligible', false,
      'bounded_build_certified', false,
      'reason', 'PAYE_UMBRELLA_OR_BANK_ROUTING_CHANGED',
      'required_refresh_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
    );
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.banking_pay_workbench_preview_rows AS preview_row
    CROSS JOIN LATERAL (
      SELECT
        CASE
          WHEN pg_catalog.upper(pg_catalog.btrim(coalesce(v_candidate.pay_method, ''))) = 'PAYE'
            THEN 'CANDIDATE'
          ELSE 'UMBRELLA'
        END AS payee_entity_kind,
        CASE
          WHEN pg_catalog.upper(pg_catalog.btrim(coalesce(v_candidate.pay_method, ''))) = 'PAYE'
            THEN v_candidate.id
          ELSE v_candidate.umbrella_id
        END AS payee_entity_id,
        CASE
          WHEN pg_catalog.upper(pg_catalog.btrim(coalesce(v_candidate.pay_method, ''))) = 'PAYE'
            THEN nullif(pg_catalog.btrim(coalesce(v_candidate.bank_details_hash, '')), '')
          ELSE nullif(pg_catalog.btrim(coalesce(v_umbrella_bank_hash, '')), '')
        END AS payee_bank_hash
    ) AS current_payee
    LEFT JOIN LATERAL (
      SELECT
        bank_name_check_row.status,
        (
          bank_name_check_row.override_reason IS NOT NULL
          AND bank_name_check_row.override_hash IS NOT DISTINCT FROM current_payee.payee_bank_hash
        ) AS has_override
      FROM public.bank_name_checks AS bank_name_check_row
      WHERE bank_name_check_row.rail_provider = v_rail_provider
        AND bank_name_check_row.rail_env = v_rail_env
        AND bank_name_check_row.entity_kind = current_payee.payee_entity_kind
        AND bank_name_check_row.entity_id = current_payee.payee_entity_id
        AND bank_name_check_row.bank_details_hash IS NOT DISTINCT FROM current_payee.payee_bank_hash
      ORDER BY bank_name_check_row.checked_at_utc DESC NULLS LAST,
               bank_name_check_row.updated_at_utc DESC,
               bank_name_check_row.created_at_utc DESC,
               bank_name_check_row.id DESC
      LIMIT 1
    ) AS current_name_check ON true
    LEFT JOIN LATERAL (
      SELECT bank_payee_map_row.payee_id
      FROM public.bank_payee_map AS bank_payee_map_row
      WHERE bank_payee_map_row.rail_provider = v_rail_provider
        AND bank_payee_map_row.rail_env = v_rail_env
        AND bank_payee_map_row.entity_kind = current_payee.payee_entity_kind
        AND bank_payee_map_row.entity_id = current_payee.payee_entity_id
        AND bank_payee_map_row.bank_details_hash IS NOT DISTINCT FROM current_payee.payee_bank_hash
      ORDER BY bank_payee_map_row.updated_at_utc DESC,
               bank_payee_map_row.created_at_utc DESC,
               bank_payee_map_row.id DESC
      LIMIT 1
    ) AS current_payee_map ON true
    WHERE preview_row.session_id = p_source_session_id
      AND preview_row.candidate_id = p_candidate_id
      AND preview_row.session_version = v_source_session.version
      AND preview_row.status = 'READY'
      AND (
        (
          v_need_name_check IS TRUE
          AND nullif(pg_catalog.btrim(coalesce(preview_row.row_json#>>'{payee_context,name_check_status}', '')), '') IS NOT NULL
          AND pg_catalog.upper(pg_catalog.btrim(coalesce(preview_row.row_json#>>'{payee_context,name_check_status}', 'UNVERIFIED')))
                IS DISTINCT FROM pg_catalog.upper(pg_catalog.btrim(coalesce(current_name_check.status, 'UNVERIFIED')))
        )
        OR (
          v_need_name_check IS TRUE
          AND nullif(pg_catalog.btrim(coalesce(preview_row.row_json#>>'{payee_context,name_check_has_override}', '')), '') IS NOT NULL
          AND (
            pg_catalog.lower(pg_catalog.btrim(coalesce(preview_row.row_json#>>'{payee_context,name_check_has_override}', 'false')))
              IN ('true', 't', '1', 'yes', 'y', 'on')
          ) IS DISTINCT FROM coalesce(current_name_check.has_override, false)
        )
        OR (
          (
            v_requires_payee_map IS TRUE
            OR nullif(pg_catalog.btrim(coalesce(preview_row.row_json#>>'{payee_context,payee_map_present}', '')), '') IS NOT NULL
          )
          AND (
            pg_catalog.lower(pg_catalog.btrim(coalesce(preview_row.row_json#>>'{payee_context,payee_map_present}', 'false')))
              IN ('true', 't', '1', 'yes', 'y', 'on')
          ) IS DISTINCT FROM (current_payee_map.payee_id IS NOT NULL)
        )
      )
  )
  INTO v_readiness_mismatch;

  IF v_readiness_mismatch IS TRUE THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', true,
      'clone_eligible', false,
      'bounded_build_certified', false,
      'reason', 'PAYEE_READINESS_FINGERPRINT_CHANGED',
      'required_refresh_job_type', 'WORKBENCH_CANDIDATE_SOURCE_BUILD'
    );
  END IF;

  v_proof_digest := pg_catalog.md5(pg_catalog.jsonb_build_object(
    'certification_version', 2,
    'source_session_id',p_source_session_id::text,
    'target_session_id',p_target_session_id::text,
    'original_economic_build_id',v_build.id::text,
    'source_mode',v_source_mode,
    'candidate_generation', v_registry.evaluated_generation,
    'source_change_seq', v_current_source_change_seq,
    'source_build_run_id', v_source_build_run_id::text,
    'source_count', v_source_count,
    'source_digest', v_source_digest,
    'canonical_digest', v_build.canonical_digest,
    'sealed_fingerprint_digest', v_build.sealed_fingerprint_digest,
    'pre_sync_digest', v_build.pre_sync_digest,
    'post_sync_digest', v_build.post_sync_digest,
    'ready_preview_count', v_ready_preview_count,
    'target_authority_scope_digest',v_live_eligibility->>'authority_scope_digest',
    'target_authority_timesheet_count',v_live_eligibility->>'authority_timesheet_count',
    'target_snapshot_key_count',v_live_eligibility->>'target_snapshot_key_count'
  )::text);
  v_certification_digest := v_proof_digest;

  RETURN pg_catalog.jsonb_build_object(
    'ok', true,
    'clone_eligible', true,
    'bounded_build_certified', true,
    'bounded_build_proof_version', 2,
    'certification_version',2,
    'certification_digest',v_certification_digest,
    'source_mode',v_source_mode,
    'ready_empty',(v_source_mode='SOURCE_EMPTY'),
    'post_clone_action','NONE',
    'reason', NULL::text,
    'required_refresh_job_type', NULL::text,
    'current_source_change_seq', v_current_source_change_seq,
    'source_build_run_id', v_source_build_run_id::text,
    'source_row_count', v_source_count,
    'original_economic_build_id',v_build.id::text,
    'economic_build_id',v_build.id::text,
    'original_source_build_run_id',v_source_build_run_id::text,
    'source_session_id',p_source_session_id::text,
    'source_digest', v_source_digest,
    'ready_preview_row_count', v_ready_preview_count,
    'proof_digest', v_proof_digest,
    'target_authority_scope_digest',v_live_eligibility->>'authority_scope_digest',
    'target_authority_timesheet_count',v_live_eligibility->>'authority_timesheet_count',
    'target_snapshot_key_count',v_live_eligibility->>'target_snapshot_key_count',
    'policy_x_authority_scope', 'PRE_DRAFT_LIVE_TRUTH'
  );
END;
$function$;

-- private.pay_workbench_session_clone_publication_fence_v1(uuid,uuid,uuid,jsonb)
CREATE OR REPLACE FUNCTION private.pay_workbench_session_clone_publication_fence_v1(p_source_session_id uuid, p_target_session_id uuid, p_candidate_id uuid, p_certification_json jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_expected jsonb := CASE
    WHEN pg_catalog.jsonb_typeof(coalesce(p_certification_json,'{}'::jsonb))='object'
      THEN coalesce(p_certification_json,'{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_current jsonb := '{}'::jsonb;
  v_clone_job_id text := NULLIF(pg_catalog.btrim(coalesce(v_expected->>'clone_job_id','')),'');
BEGIN
  IF NULLIF(v_expected->>'certification_digest','') IS NULL
     OR coalesce(v_expected->>'certification_version','')<>'2' THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok',true,'fence_passed',false,
      'reason','CLONE_CERTIFICATION_V2_REQUIRED'
    );
  END IF;

  v_current := private.pay_workbench_session_clone_bounded_certification_v1(
    p_source_session_id,
    p_target_session_id,
    p_candidate_id,
    pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
      'source_session_id',p_source_session_id::text,
      'target_session_id',p_target_session_id::text,
      'source_selection_authorised',true,
      'allow_session_rebase',true,
      'rebase_simple_rows_only',true,
      'certification_version',2,
      'final_fence_mode',true,
      'clone_job_id',v_clone_job_id
    ))
  );

  IF coalesce((v_current->>'clone_eligible')::boolean,false) IS NOT TRUE
     OR NULLIF(v_current->>'certification_digest','')
          IS DISTINCT FROM NULLIF(v_expected->>'certification_digest','')
     OR NULLIF(v_current->>'original_economic_build_id','')
          IS DISTINCT FROM NULLIF(v_expected->>'original_economic_build_id','')
     OR NULLIF(v_current->>'source_build_run_id','')
          IS DISTINCT FROM NULLIF(v_expected->>'source_build_run_id','') THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok',true,'fence_passed',false,
      'reason',coalesce(NULLIF(v_current->>'reason',''),'CLONE_CERTIFICATION_DRIFT'),
      'current_certification',v_current
    );
  END IF;

  RETURN pg_catalog.jsonb_build_object(
    'ok',true,'fence_passed',true,
    'reason',NULL::text,
    'certification',v_current,
    'certification_digest',v_current->>'certification_digest'
  );
END;
$function$;

-- private.pay_workbench_source_publication_identity_v1(uuid,uuid,bigint,bigint,uuid)
CREATE OR REPLACE FUNCTION private.pay_workbench_source_publication_identity_v1(p_session_id uuid, p_candidate_id uuid, p_session_version bigint, p_source_change_seq bigint, p_source_build_run_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE STRICT
 SET search_path TO ''
AS $function$
DECLARE
  v_hash text;
BEGIN
  IF p_session_version <= 0 OR p_source_change_seq < 0 THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_SOURCE_PUBLICATION_AUTHORITY_INVALID'
      USING ERRCODE='22023', DETAIL=pg_catalog.jsonb_build_object(
        'code','PAY_WORKBENCH_SOURCE_PUBLICATION_AUTHORITY_INVALID',
        'reason','VERSION_OR_SEQUENCE_INVALID'
      )::text;
  END IF;

  v_hash := pg_catalog.md5(
    'BANKING_PAY_SOURCE_PUBLICATION_V1|' ||
    p_session_id::text || '|' || p_candidate_id::text || '|' ||
    p_session_version::text || '|' || p_source_change_seq::text || '|' ||
    p_source_build_run_id::text
  );

  RETURN (
    pg_catalog.substr(v_hash,1,8) || '-' ||
    pg_catalog.substr(v_hash,9,4) || '-' ||
    pg_catalog.substr(v_hash,13,4) || '-' ||
    pg_catalog.substr(v_hash,17,4) || '-' ||
    pg_catalog.substr(v_hash,21,12)
  )::uuid;
END;
$function$;

-- private.pay_workbench_targeted_delta_admission_v1(uuid,uuid,uuid,text,uuid[],uuid[],bigint)
CREATE OR REPLACE FUNCTION private.pay_workbench_targeted_delta_admission_v1(p_session_id uuid, p_candidate_id uuid, p_projection_run_id uuid, p_event_class text, p_targeted_timesheet_ids uuid[], p_linked_timesheet_ids uuid[], p_source_change_seq bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_session public.banking_pay_workbench_sessions%ROWTYPE;
  v_scope public.banking_pay_workbench_session_scope%ROWTYPE;
  v_registry private.banking_pay_workbench_candidate_scope_registry%ROWTYPE;
  v_event_class text := pg_catalog.upper(pg_catalog.btrim(COALESCE(p_event_class,'')));
  v_targets uuid[] := ARRAY[]::uuid[];
  v_linked uuid[] := ARRAY[]::uuid[];
  v_affected uuid[] := ARRAY[]::uuid[];
  v_closure jsonb := '{}'::jsonb;
  v_owner_count integer := 0;
  v_finance_count integer := 0;
  v_settled_count integer := 0;
  v_connected_count integer := 0;
  v_current_count integer := 0;
  v_current_build_count integer := 0;
  v_unaffected_count integer := 0;
  v_target_before_count integer := 0;
  v_unaffected_digest text;
  v_target_before_digest text;
  v_input_digest text;
  v_preview_digest text;
  v_existing_seal_json jsonb := '{}'::jsonb;
  v_current_build_id uuid;
  v_current_source_change_seq bigint;
  v_accepted_full_build_id uuid;
  v_source_run_digest text;
  v_seal jsonb;
  v_seal_digest text;
  v_exact_import_candidate boolean:=false;
  v_exact_import_admission jsonb:='{}'::jsonb;
  v_exact_import_family_kind text:=NULL::text;
BEGIN
  IF p_session_id IS NULL OR p_candidate_id IS NULL OR p_source_change_seq IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_TARGETED_DELTA_ADMISSION_ARGUMENT_REQUIRED'
      USING ERRCODE='P0001', DETAIL=jsonb_build_object('code','PAY_WORKBENCH_TARGETED_DELTA_ADMISSION_ARGUMENT_REQUIRED')::text;
  END IF;

  IF v_event_class NOT IN ('AUTHORISE','UNAUTHORISE') THEN
    RETURN jsonb_build_object('ok',true,'admitted',false,'full_route_required',true,'reason','TARGETED_DELTA_EVENT_NOT_SUPPORTED');
  END IF;

  SELECT COALESCE(array_agg(DISTINCT value ORDER BY value),ARRAY[]::uuid[])
  INTO v_targets
  FROM unnest(COALESCE(p_targeted_timesheet_ids,ARRAY[]::uuid[])) AS target(value)
  WHERE value IS NOT NULL;

  SELECT COALESCE(array_agg(DISTINCT value ORDER BY value),ARRAY[]::uuid[])
  INTO v_linked
  FROM unnest(COALESCE(p_linked_timesheet_ids,ARRAY[]::uuid[])) AS linked(value)
  WHERE value IS NOT NULL;

  IF COALESCE(array_length(v_targets,1),0) = 0 OR array_length(v_targets,1) > 250 THEN
    RETURN jsonb_build_object('ok',true,'admitted',false,'full_route_required',true,'reason','TARGETED_DELTA_TARGET_INVALID');
  END IF;
  SELECT EXISTS(
    SELECT 1
    FROM public.timesheets AS import_timesheet
    JOIN public.contracts AS import_contract ON import_contract.id=import_timesheet.contract_id
    WHERE import_timesheet.timesheet_id=ANY(v_targets)
      AND import_contract.candidate_id=p_candidate_id
      AND pg_catalog.upper(import_contract.weekly_timesheet_source::text) IN ('NHSP','HEALTHROSTER')
  ) INTO v_exact_import_candidate;

  IF v_exact_import_candidate THEN
    v_exact_import_admission:=private.pay_workbench_exact_import_family_admission_v1(
      p_session_id,p_candidate_id,v_targets,p_source_change_seq
    );
    IF coalesce((v_exact_import_admission->>'admitted')::boolean,false) IS NOT TRUE THEN
      RETURN jsonb_build_object(
        'ok',true,'admitted',false,'full_route_required',true,
        'reason',coalesce(NULLIF(v_exact_import_admission->>'reason',''),'EXACT_IMPORT_FAMILY_NOT_ADMITTED')
      );
    END IF;
    SELECT coalesce(array_agg(DISTINCT value::uuid ORDER BY value::uuid),ARRAY[]::uuid[])
    INTO v_targets
    FROM jsonb_array_elements_text(
      coalesce(v_exact_import_admission->'family_timesheet_ids','[]'::jsonb)
    ) AS family_value(value)
    WHERE value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
    v_exact_import_family_kind:=NULLIF(v_exact_import_admission->>'family_kind','');
  END IF;


  SELECT session_row.* INTO v_session
  FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id=p_session_id;
  IF NOT FOUND OR pg_catalog.upper(pg_catalog.btrim(COALESCE(v_session.status,''))) <> 'OPEN'
     OR v_session.discarded_at_utc IS NOT NULL THEN
    RETURN jsonb_build_object('ok',true,'admitted',false,'full_route_required',true,'reason','TARGETED_DELTA_SESSION_STALE');
  END IF;

  SELECT scope_row.* INTO v_scope
  FROM public.banking_pay_workbench_session_scope AS scope_row
  WHERE scope_row.session_id=p_session_id AND scope_row.candidate_id=p_candidate_id;
  IF NOT FOUND OR pg_catalog.upper(COALESCE(v_scope.status,'')) NOT IN ('READY','MATERIALISED','SOURCE_EMPTY','READY_EMPTY')
     OR COALESCE(v_scope.dirty,false) THEN
    RETURN jsonb_build_object('ok',true,'admitted',false,'full_route_required',true,'reason','TARGETED_DELTA_BASELINE_NOT_ESTABLISHED');
  END IF;

  SELECT registry_row.* INTO v_registry
  FROM private.banking_pay_workbench_candidate_scope_registry AS registry_row
  WHERE registry_row.candidate_id=p_candidate_id;
  IF NOT FOUND OR COALESCE(v_registry.current_source_change_seq,0) <> p_source_change_seq
     OR COALESCE(v_registry.evaluated_generation,-1) <> COALESCE(v_registry.dirty_generation,0) THEN
    RETURN jsonb_build_object('ok',true,'admitted',false,'full_route_required',true,'reason','TARGETED_DELTA_GENERATION_STALE');
  END IF;

  SELECT completed_build.id
  INTO v_accepted_full_build_id
  FROM private.banking_pay_workbench_economic_builds AS completed_build
  WHERE completed_build.session_id=p_session_id
    AND completed_build.candidate_id=p_candidate_id
    AND completed_build.session_version=v_session.version
    AND completed_build.status='COMPLETE'
    AND completed_build.private_stage='COMPLETE'
    AND completed_build.completed_at_utc IS NOT NULL
    AND completed_build.captured_candidate_generation<=v_registry.dirty_generation
    AND completed_build.source_change_seq<=p_source_change_seq
  ORDER BY completed_build.source_change_seq DESC,
           completed_build.completed_at_utc DESC,
           completed_build.id DESC
  LIMIT 1;
  IF v_accepted_full_build_id IS NULL
     AND coalesce(v_scope.certified_preview_publication_parity_ok,false) IS TRUE
     AND v_scope.certified_preview_publication_attestation_json->>'attestation_version'
           ='CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V2'
     AND v_scope.certified_preview_publication_attestation_json->>'authority_kind'
           ='CERTIFIED_CLONE'
     AND coalesce(v_scope.certified_preview_publication_attestation_json->>'original_economic_build_id','')
           ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    SELECT completed_build.id
    INTO v_accepted_full_build_id
    FROM private.banking_pay_workbench_economic_builds AS completed_build
    WHERE completed_build.id=(v_scope.certified_preview_publication_attestation_json->>'original_economic_build_id')::uuid
      AND completed_build.candidate_id=p_candidate_id
      AND completed_build.status='COMPLETE'
      AND completed_build.private_stage='COMPLETE'
      AND completed_build.completed_at_utc IS NOT NULL
      AND completed_build.failure_json='{}'::jsonb;
  END IF;

  IF v_accepted_full_build_id IS NULL THEN
    RETURN jsonb_build_object('ok',true,'admitted',false,'full_route_required',true,'reason','TARGETED_DELTA_BASELINE_NOT_ESTABLISHED');
  END IF;

  SELECT count(DISTINCT target.value)::integer
  INTO v_owner_count
  FROM unnest(v_targets) AS target(value)
  JOIN public.timesheets AS timesheet_row ON timesheet_row.timesheet_id=target.value
  LEFT JOIN public.contracts AS contract_row ON contract_row.id=timesheet_row.contract_id
  WHERE contract_row.candidate_id=p_candidate_id
     OR EXISTS (
       SELECT 1 FROM public.timesheets_financials AS tf
       WHERE tf.timesheet_id=target.value AND tf.candidate_id=p_candidate_id
     );
  IF v_owner_count <> array_length(v_targets,1) THEN
    RETURN jsonb_build_object('ok',true,'admitted',false,'full_route_required',true,'reason','TARGETED_DELTA_TARGET_OWNERSHIP_MISMATCH');
  END IF;

  v_closure := public._pay_workbench_refresh_dependency_closure_v1(
    p_candidate_id,v_targets,v_linked,ARRAY[]::uuid[],250,100
  );
  IF COALESCE((v_closure->>'coverage_complete')::boolean,false) IS NOT TRUE
     OR COALESCE((v_closure->>'requires_full_candidate')::boolean,true) THEN
    RETURN jsonb_build_object('ok',true,'admitted',false,'full_route_required',true,
      'reason',COALESCE(v_closure->>'fallback_reason','TARGETED_DELTA_DEPENDENCY_INCOMPLETE'));
  END IF;

  SELECT COALESCE(array_agg(DISTINCT value::uuid ORDER BY value::uuid),ARRAY[]::uuid[])
  INTO v_affected
  FROM jsonb_array_elements_text(COALESCE(v_closure->'effective_targeted_timesheet_ids','[]'::jsonb)) AS affected(value)
  WHERE value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

  IF v_affected IS DISTINCT FROM v_targets THEN
    RETURN jsonb_build_object('ok',true,'admitted',false,'full_route_required',true,'reason','TARGETED_DELTA_CONNECTED_SCOPE_PRESENT');
  END IF;

  SELECT count(*)::integer INTO v_connected_count
  FROM public.timesheets AS t
  WHERE t.timesheet_id=ANY(v_affected)
    AND (t.correction_id IS NOT NULL OR COALESCE(t.is_adjustment,false)
         OR t.parent_timesheet_id IS NOT NULL);
  SELECT v_connected_count + count(*)::integer INTO v_connected_count
  FROM public.timesheets_financials AS tf
  WHERE tf.timesheet_id=ANY(v_affected) AND tf.is_current
    AND tf.nhsp_import_id IS NOT NULL
    AND v_exact_import_candidate IS NOT TRUE;
  SELECT v_connected_count+count(*)::integer INTO v_connected_count
  FROM public.timesheets AS import_timesheet
  JOIN public.contracts AS import_contract ON import_contract.id=import_timesheet.contract_id
  WHERE import_timesheet.timesheet_id=ANY(v_affected)
    AND pg_catalog.upper(import_contract.weekly_timesheet_source::text) IN ('NHSP','HEALTHROSTER')
    AND v_exact_import_candidate IS NOT TRUE;
  IF v_connected_count > 0 THEN
    RETURN jsonb_build_object('ok',true,'admitted',false,'full_route_required',true,'reason','TARGETED_DELTA_CONNECTED_AUTHORITY_PRESENT');
  END IF;

  SELECT count(*)::integer INTO v_finance_count
  FROM public.pay_finance_case_components AS c
  WHERE c.candidate_id=p_candidate_id
    AND (c.linked_timesheet_id IS NULL OR c.linked_timesheet_id=ANY(v_affected));
  SELECT v_finance_count + count(*)::integer INTO v_finance_count
  FROM public.pay_advances AS a
  WHERE a.candidate_id=p_candidate_id
    AND pg_catalog.upper(COALESCE(a.status::text,'')) IN ('ACTIVE','PAUSED')
    AND a.cleared_at_utc IS NULL AND a.written_off_at_utc IS NULL
    AND (a.linked_timesheet_id IS NULL OR a.linked_timesheet_id=ANY(v_affected));
  SELECT v_finance_count + count(*)::integer INTO v_finance_count
  FROM public.ts_pay_adjustments AS a
  WHERE a.candidate_id=p_candidate_id AND a.paid_at_utc IS NULL
    AND a.timesheet_id=ANY(v_affected);
  SELECT v_finance_count + count(*)::integer INTO v_finance_count
  FROM public.timesheet_payment_overrides AS o
  WHERE o.candidate_id=p_candidate_id AND o.timesheet_id=ANY(v_affected)
    AND o.consumed_at_utc IS NULL AND o.cleared_at_utc IS NULL;
  IF v_finance_count > 0 THEN
    RETURN jsonb_build_object('ok',true,'admitted',false,'full_route_required',true,'reason','TARGETED_DELTA_FINANCE_AUTHORITY_PRESENT');
  END IF;

  SELECT count(*)::integer INTO v_settled_count
  FROM public.timesheet_pay_state AS ps
  WHERE ps.timesheet_id=ANY(v_affected)
    AND (ps.last_settled_signature IS NOT NULL OR ps.last_settled_pay_batch_id IS NOT NULL);
  SELECT v_settled_count + count(*)::integer INTO v_settled_count
  FROM public.pay_batch_items AS bi
  WHERE bi.timesheet_id=ANY(v_affected) AND NOT COALESCE(bi.is_voided,false);
  SELECT v_settled_count + count(*)::integer INTO v_settled_count
  FROM public.pay_payment_correction_items AS ci
  WHERE ci.candidate_id=p_candidate_id AND ci.timesheet_id=ANY(v_affected);
  IF v_settled_count > 0 THEN
    RETURN jsonb_build_object('ok',true,'admitted',false,'full_route_required',true,'reason','TARGETED_DELTA_SETTLED_AUTHORITY_PRESENT');
  END IF;

  SELECT count(*)::integer,
         count(DISTINCT source_build_run_id)::integer,
         pg_catalog.min(source_build_run_id),
         pg_catalog.min(source_change_seq)
  INTO v_current_count,v_current_build_count,v_current_build_id,v_current_source_change_seq
  FROM public.banking_pay_workbench_candidate_source_lines AS source_row
  WHERE source_row.session_id=p_session_id AND source_row.candidate_id=p_candidate_id
    AND source_row.status='CURRENT';
  SELECT pg_catalog.encode(extensions.digest(pg_catalog.convert_to(COALESCE(
    pg_catalog.string_agg(run_id::text,'|' ORDER BY run_id::text),'EMPTY'),'UTF8'),'sha256'),'hex')
  INTO v_source_run_digest
  FROM (
    SELECT DISTINCT source_row.source_build_run_id AS run_id
    FROM public.banking_pay_workbench_candidate_source_lines AS source_row
    WHERE source_row.session_id=p_session_id
      AND source_row.candidate_id=p_candidate_id
      AND source_row.status='CURRENT'
      AND source_row.source_build_run_id IS NOT NULL
  ) AS current_runs;

  IF EXISTS (
        SELECT 1 FROM public.banking_pay_workbench_candidate_source_lines AS source_row
        WHERE source_row.session_id=p_session_id AND source_row.candidate_id=p_candidate_id
         AND (
           source_row.status = 'ERROR'
           OR (
             source_row.status = 'DIRTY'
             AND (
               p_projection_run_id IS NULL
               OR source_row.source_build_run_id IS DISTINCT FROM p_projection_run_id
             )
           )
         )
     )
     OR EXISTS (
       SELECT 1
       FROM public.banking_pay_workbench_candidate_source_lines AS source_row
       WHERE source_row.session_id=p_session_id
         AND source_row.candidate_id=p_candidate_id
         AND source_row.status='CURRENT'
         AND (
           source_row.session_version IS DISTINCT FROM v_session.version
           OR source_row.source_change_seq>p_source_change_seq
           OR source_row.source_build_run_id IS NULL
           OR NOT (
             EXISTS (
               SELECT 1
               FROM private.banking_pay_workbench_economic_builds AS source_build
               WHERE source_build.source_build_run_id=source_row.source_build_run_id
                 AND source_build.session_id=p_session_id
                 AND source_build.candidate_id=p_candidate_id
                 AND source_build.status='COMPLETE'
                 AND source_build.private_stage='COMPLETE'
                 AND source_build.completed_at_utc IS NOT NULL
             )
             OR EXISTS (
               SELECT 1
               FROM public.banking_pay_workbench_candidate_delta_projection_runs AS source_delta
               WHERE source_delta.id=source_row.source_build_run_id
                 AND source_delta.session_id=p_session_id
                 AND source_delta.candidate_id=p_candidate_id
                 AND source_delta.status='COMPLETED'
                 AND source_delta.completed_at_utc IS NOT NULL
             )
             OR (
               COALESCE(v_scope.certified_preview_publication_parity_ok,false) IS TRUE
               AND v_scope.certified_preview_publication_session_version=v_session.version
               AND v_scope.certified_preview_publication_source_change_seq=p_source_change_seq
               AND v_scope.certified_preview_publication_source_build_run_id=source_row.source_build_run_id
               AND v_scope.certified_preview_publication_attestation_json->>'attestation_version'
                     ='CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V3'
               AND v_scope.certified_preview_publication_attestation_json->>'semantic_contract_version'
                     ='READY_TO_PAY_SEMANTIC_V2'
               AND v_scope.certified_preview_publication_attestation_json->>'authority_kind'
                     ='CERTIFIED_CANCELLATION_REVERSION'
               AND COALESCE((v_scope.certified_preview_publication_attestation_json->>'semantic_ready')::boolean,false)
               AND COALESCE((v_scope.certified_preview_publication_attestation_json->>'parity_complete')::boolean,false)
             )
           )
         )
     ) THEN
    RETURN jsonb_build_object('ok',true,'admitted',false,'full_route_required',true,'reason','TARGETED_DELTA_SOURCE_NOT_CURRENT');
  END IF;
  IF v_current_count=0 AND pg_catalog.upper(COALESCE(v_scope.status,'')) NOT IN ('SOURCE_EMPTY','READY_EMPTY') THEN
    RETURN jsonb_build_object('ok',true,'admitted',false,'full_route_required',true,'reason','TARGETED_DELTA_SOURCE_NOT_CURRENT');
  END IF;

  SELECT count(*)::integer,
         pg_catalog.encode(extensions.digest(pg_catalog.convert_to(COALESCE(jsonb_agg(
           jsonb_build_object('id',s.id,'ordinal',s.source_ordinal,'line_key',s.line_key,
             'timesheet_id',s.timesheet_id,'row',s.source_row_json,'key',s.economic_key_json)
           ORDER BY s.source_ordinal,s.id)::text,'[]'),'UTF8'),'sha256'),'hex')
  INTO v_unaffected_count,v_unaffected_digest
  FROM public.banking_pay_workbench_candidate_source_lines AS s
  WHERE s.session_id=p_session_id AND s.candidate_id=p_candidate_id
    AND s.status='CURRENT'
    AND (s.timesheet_id IS NULL OR NOT (s.timesheet_id=ANY(v_affected)));

  SELECT count(*)::integer,
         pg_catalog.encode(extensions.digest(pg_catalog.convert_to(COALESCE(jsonb_agg(
           jsonb_build_object('id',s.id,'ordinal',s.source_ordinal,'line_key',s.line_key,
             'timesheet_id',s.timesheet_id,'row',s.source_row_json,'key',s.economic_key_json)
           ORDER BY s.source_ordinal,s.id)::text,'[]'),'UTF8'),'sha256'),'hex')
  INTO v_target_before_count,v_target_before_digest
  FROM public.banking_pay_workbench_candidate_source_lines AS s
  WHERE s.session_id=p_session_id AND s.candidate_id=p_candidate_id
    AND s.status='CURRENT' AND s.timesheet_id=ANY(v_affected);

  SELECT pg_catalog.encode(extensions.digest(pg_catalog.convert_to(COALESCE(jsonb_agg(
    jsonb_build_object('timesheet',to_jsonb(t),'financial',COALESCE(tf.rows,'[]'::jsonb),'pay_state',to_jsonb(ps))
    ORDER BY t.timesheet_id)::text,'[]'),'UTF8'),'sha256'),'hex')
  INTO v_input_digest
  FROM public.timesheets AS t
  LEFT JOIN LATERAL (
    SELECT jsonb_agg(to_jsonb(f) ORDER BY f.id) AS rows
    FROM public.timesheets_financials AS f
    WHERE f.timesheet_id=t.timesheet_id AND f.is_current
  ) AS tf ON true
  LEFT JOIN public.timesheet_pay_state AS ps ON ps.timesheet_id=t.timesheet_id
  WHERE t.timesheet_id=ANY(v_affected);

  IF p_projection_run_id IS NOT NULL THEN
    SELECT projection_run.admission_seal_json
    INTO v_existing_seal_json
    FROM public.banking_pay_workbench_candidate_delta_projection_runs projection_run
    WHERE projection_run.id=p_projection_run_id
      AND projection_run.session_id=p_session_id
      AND projection_run.candidate_id=p_candidate_id
      AND projection_run.admission_seal_version=1;
  END IF;

  IF COALESCE(v_existing_seal_json,'{}'::jsonb) <> '{}'::jsonb THEN
    IF EXISTS (
      SELECT 1
      FROM public.banking_pay_workbench_preview_rows p
      WHERE p.session_id=p_session_id AND p.candidate_id=p_candidate_id
        AND p.timesheet_id=ANY(v_affected)
        AND p.row_json ? 'targeted_delta_stage'
        AND p.row_json#>>'{targeted_delta_stage,projection_run_id}' IS DISTINCT FROM p_projection_run_id::text
    ) THEN
      RETURN jsonb_build_object('ok',true,'admitted',false,'full_route_required',true,'reason','TARGETED_DELTA_FOREIGN_STAGING_PRESENT');
    END IF;
    v_preview_digest:=v_existing_seal_json->>'preview_selection_digest';
  ELSE
    SELECT pg_catalog.encode(extensions.digest(pg_catalog.convert_to(COALESCE(jsonb_agg(
      jsonb_build_object('id',p.id,'row_key',p.row_key,'selected',p.selected,
        'selection_state',p.selection_state,'status',p.status)
      ORDER BY p.section,p.row_ordinal,p.id)::text,'[]'),'UTF8'),'sha256'),'hex')
    INTO v_preview_digest
    FROM public.banking_pay_workbench_preview_rows AS p
    WHERE p.session_id=p_session_id AND p.candidate_id=p_candidate_id
      AND p.timesheet_id=ANY(v_affected);
  END IF;

  v_seal := jsonb_build_object(
    'seal_version',1,
    'projection_run_id',p_projection_run_id,
    'session_id',p_session_id,
    'candidate_id',p_candidate_id,
    'event_class',v_event_class,
    'session_version',v_session.version,
    'source_snapshot_run_id',v_session.source_snapshot_run_id,
    'source_change_seq',p_source_change_seq,
    'candidate_dirty_generation',v_registry.dirty_generation,
    'candidate_evaluated_generation',v_registry.evaluated_generation,
    'accepted_build_id',v_accepted_full_build_id,
    'accepted_source_build_run_id',CASE WHEN v_current_build_count=1 THEN v_current_build_id ELSE NULL::uuid END,
    'accepted_source_run_count',v_current_build_count,
    'accepted_source_run_digest',v_source_run_digest,
    'accepted_source_change_seq',v_current_source_change_seq,
    'affected_timesheet_ids',to_jsonb(v_affected),
    'unaffected_source_count',v_unaffected_count,
    'unaffected_source_digest',v_unaffected_digest,
    'target_before_count',v_target_before_count,
    'target_before_digest',v_target_before_digest,
    'input_digest',v_input_digest,
    'preview_selection_digest',v_preview_digest,
    'current_source_count',v_current_count,
    'exact_import_family',v_exact_import_candidate,
    'exact_import_family_kind',v_exact_import_family_kind,
    'exact_import_tsfin_revision_digest',v_exact_import_admission->>'tsfin_revision_digest',
    'exact_import_occurrence_count',v_exact_import_admission->>'occurrence_count',
    'exact_import_occurrence_digest',v_exact_import_admission->>'occurrence_digest',
    'policy_x_authority_scope','PRE_DRAFT_LIVE_TRUTH'
  );
  v_seal_digest := pg_catalog.encode(
    extensions.digest(pg_catalog.convert_to(v_seal::text,'UTF8'),'sha256'),'hex'
  );

  RETURN jsonb_build_object(
    'ok',true,'admitted',true,'full_route_required',false,'seal_version',1,
    'admission_seal_json',v_seal,'admission_seal_digest',v_seal_digest,
    'reason','TARGETED_DELTA_ADMITTED'
  );
END;
$function$;

-- private.pay_workbench_targeted_delta_scope_finalize_v1(uuid,uuid,uuid)
CREATE OR REPLACE FUNCTION private.pay_workbench_targeted_delta_scope_finalize_v1(p_session_id uuid, p_candidate_id uuid, p_projection_run_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_run public.banking_pay_workbench_candidate_delta_projection_runs%ROWTYPE;
  v_session public.banking_pay_workbench_sessions%ROWTYPE;
  v_scope public.banking_pay_workbench_session_scope%ROWTYPE;
  v_registry private.banking_pay_workbench_candidate_scope_registry%ROWTYPE;
  v_seal jsonb;
  v_seal_digest text;
  v_admission jsonb;
  v_targets uuid[] := ARRAY[]::uuid[];
  v_event_class text;
  v_source_promoted integer := 0;
  v_source_retired integer := 0;
  v_line_promoted integer := 0;
  v_line_retired integer := 0;
  v_preview_promoted integer := 0;
  v_preview_retired integer := 0;
  v_state jsonb;
  v_publication jsonb := '{}'::jsonb;
  v_completion_job_id uuid := NULL::uuid;
  v_semantic_publication_v3_enabled boolean := false;
  v_source_publication_identity_write_enabled boolean := false;
  v_source_publication_id uuid := NULL::uuid;
BEGIN
  IF p_session_id IS NULL OR p_candidate_id IS NULL OR p_projection_run_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_TARGETED_DELTA_FINALIZE_ARGUMENT_REQUIRED' USING ERRCODE='P0001';
  END IF;

  SELECT COALESCE(settings_row.banking_pay_workbench_semantic_ready_publication_v3_enabled,false),
         COALESCE(settings_row.banking_pay_source_publication_identity_write_v1_enabled,false)
  INTO v_semantic_publication_v3_enabled,
       v_source_publication_identity_write_enabled
  FROM public.settings_defaults AS settings_row
  WHERE settings_row.id=1;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(public._pay_workbench_candidate_serial_key(p_candidate_id),24062027)
  );
  PERFORM candidate_lock.id
  FROM public.candidates AS candidate_lock
  WHERE candidate_lock.id=p_candidate_id
  FOR UPDATE;

  SELECT registry_row.* INTO v_registry
  FROM private.banking_pay_workbench_candidate_scope_registry AS registry_row
  WHERE registry_row.candidate_id=p_candidate_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_TARGETED_DELTA_FINALIZE_AUTHORITY_MISSING' USING ERRCODE='P0001';
  END IF;

  SELECT run_row.* INTO v_run
  FROM public.banking_pay_workbench_candidate_delta_projection_runs AS run_row
  WHERE run_row.id=p_projection_run_id
    AND run_row.session_id=p_session_id
    AND run_row.candidate_id=p_candidate_id
  FOR UPDATE;
  IF NOT FOUND OR v_run.status <> 'RUNNING' OR COALESCE(v_run.admission_seal_version,0) <> 1
     OR jsonb_typeof(v_run.admission_seal_json) <> 'object'
     OR v_run.admission_seal_digest IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_TARGETED_DELTA_FINALIZE_RUN_INVALID' USING ERRCODE='P0001';
  END IF;

  v_seal := v_run.admission_seal_json;
  v_seal_digest := pg_catalog.encode(
    extensions.digest(pg_catalog.convert_to(v_seal::text,'UTF8'),'sha256'),'hex'
  );
  IF v_seal_digest IS DISTINCT FROM v_run.admission_seal_digest
     OR v_seal->>'projection_run_id' IS DISTINCT FROM p_projection_run_id::text
     OR v_seal->>'session_id' IS DISTINCT FROM p_session_id::text
     OR v_seal->>'candidate_id' IS DISTINCT FROM p_candidate_id::text THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_TARGETED_DELTA_FINALIZE_SEAL_INVALID' USING ERRCODE='P0001';
  END IF;

  SELECT COALESCE(array_agg(value::uuid ORDER BY value::uuid),ARRAY[]::uuid[])
  INTO v_targets
  FROM jsonb_array_elements_text(COALESCE(v_seal->'affected_timesheet_ids','[]'::jsonb)) AS target(value)
  WHERE value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
  v_event_class := v_seal->>'event_class';

  SELECT session_row.* INTO v_session FROM public.banking_pay_workbench_sessions AS session_row
  WHERE session_row.id=p_session_id FOR UPDATE;
  SELECT scope_row.* INTO v_scope FROM public.banking_pay_workbench_session_scope AS scope_row
  WHERE scope_row.session_id=p_session_id AND scope_row.candidate_id=p_candidate_id FOR UPDATE;
  IF v_session.id IS NULL OR v_scope.id IS NULL OR v_registry.candidate_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_TARGETED_DELTA_FINALIZE_AUTHORITY_MISSING' USING ERRCODE='P0001';
  END IF;

  v_admission := private.pay_workbench_targeted_delta_admission_v1(
    p_session_id,p_candidate_id,p_projection_run_id,v_event_class,v_targets,ARRAY[]::uuid[],v_run.source_change_seq
  );
  IF COALESCE((v_admission->>'admitted')::boolean,false) IS NOT TRUE
     OR v_admission->>'admission_seal_digest' IS DISTINCT FROM v_run.admission_seal_digest THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_TARGETED_DELTA_FINALIZE_PROOF_STALE'
      USING ERRCODE='P0001', DETAIL=jsonb_build_object('code','PAY_WORKBENCH_TARGETED_DELTA_FINALIZE_PROOF_STALE','reason',v_admission->>'reason')::text;
  END IF;

  UPDATE public.banking_pay_workbench_candidate_source_lines AS old_source
  SET status='SUPERSEDED',updated_at_utc=v_now
  WHERE old_source.session_id=p_session_id AND old_source.candidate_id=p_candidate_id
    AND old_source.status='CURRENT' AND old_source.timesheet_id=ANY(v_targets);
  GET DIAGNOSTICS v_source_retired = ROW_COUNT;

  UPDATE public.banking_pay_workbench_candidate_source_lines AS staged_source
  SET status='CURRENT',updated_at_utc=v_now
  WHERE staged_source.session_id=p_session_id AND staged_source.candidate_id=p_candidate_id
    AND staged_source.source_build_run_id=p_projection_run_id
    AND staged_source.status='DIRTY' AND staged_source.timesheet_id=ANY(v_targets);
  GET DIAGNOSTICS v_source_promoted = ROW_COUNT;

  -- A targeted delta changes only a subset of line lineage, but publication
  -- identity describes the complete physical CURRENT set.  Assign one new
  -- immutable set identity to both promoted and unaffected CURRENT rows.
  IF v_source_publication_identity_write_enabled THEN
    v_source_publication_id := private.pay_workbench_source_publication_identity_v1(
      p_session_id,p_candidate_id,v_run.session_version,v_run.source_change_seq,p_projection_run_id
    );

    UPDATE public.banking_pay_workbench_candidate_source_lines AS current_source
    SET source_change_seq=v_run.source_change_seq,
        source_publication_id=v_source_publication_id,
        updated_at_utc=v_now
    WHERE current_source.session_id=p_session_id
      AND current_source.candidate_id=p_candidate_id
      AND current_source.session_version=v_run.session_version
      AND current_source.status='CURRENT';
  END IF;

  UPDATE public.banking_pay_workbench_candidate_line_work AS line_row
  SET status=COALESCE(NULLIF(line_row.work_payload_json#>>'{targeted_delta_stage,final_status}',''),'READY'),
      work_payload_json=line_row.work_payload_json-'targeted_delta_stage',
      updated_at_utc=v_now
  WHERE line_row.session_id=p_session_id AND line_row.candidate_id=p_candidate_id
    AND line_row.timesheet_id=ANY(v_targets)
    AND line_row.work_payload_json#>>'{targeted_delta_stage,projection_run_id}'=p_projection_run_id::text;
  GET DIAGNOSTICS v_line_promoted = ROW_COUNT;

  UPDATE public.banking_pay_workbench_candidate_line_work AS line_row
  SET status='SKIPPED',updated_at_utc=v_now
  WHERE line_row.session_id=p_session_id AND line_row.candidate_id=p_candidate_id
    AND line_row.timesheet_id=ANY(v_targets)
    AND line_row.work_payload_json#>>'{targeted_delta_stage,projection_run_id}' IS DISTINCT FROM p_projection_run_id::text
    AND NOT EXISTS (
      SELECT 1 FROM public.banking_pay_workbench_candidate_source_lines AS current_source
      WHERE current_source.session_id=p_session_id AND current_source.candidate_id=p_candidate_id
        AND current_source.status='CURRENT' AND current_source.timesheet_id=line_row.timesheet_id
        AND current_source.line_key=line_row.line_key
    );
  GET DIAGNOSTICS v_line_retired = ROW_COUNT;

  UPDATE public.banking_pay_workbench_preview_rows AS preview_row
  SET selected=COALESCE((preview_row.row_json#>>'{targeted_delta_stage,final_selected}')::boolean,false),
      selection_state=COALESCE(NULLIF(preview_row.row_json#>>'{targeted_delta_stage,final_selection_state}',''),'NOT_SELECTED'),
      status=COALESCE(NULLIF(preview_row.row_json#>>'{targeted_delta_stage,final_status}',''),'READY'),
      row_json=preview_row.row_json-'targeted_delta_stage',
      updated_at_utc=v_now
  WHERE preview_row.session_id=p_session_id AND preview_row.candidate_id=p_candidate_id
    AND preview_row.timesheet_id=ANY(v_targets)
    AND preview_row.row_json#>>'{targeted_delta_stage,projection_run_id}'=p_projection_run_id::text;
  GET DIAGNOSTICS v_preview_promoted = ROW_COUNT;

  UPDATE public.banking_pay_workbench_preview_rows AS preview_row
  SET selected=false,selection_state='NOT_SELECTABLE',status='SUPERSEDED',updated_at_utc=v_now
  WHERE preview_row.session_id=p_session_id AND preview_row.candidate_id=p_candidate_id
    AND preview_row.timesheet_id=ANY(v_targets)
    AND preview_row.row_json#>>'{targeted_delta_stage,projection_run_id}' IS DISTINCT FROM p_projection_run_id::text
    AND NOT EXISTS (
      SELECT 1 FROM public.banking_pay_workbench_candidate_source_lines AS current_source
      WHERE current_source.session_id=p_session_id AND current_source.candidate_id=p_candidate_id
        AND current_source.status='CURRENT' AND current_source.timesheet_id=preview_row.timesheet_id
    );
  GET DIAGNOSTICS v_preview_retired = ROW_COUNT;

  SELECT delta_job.id
  INTO v_completion_job_id
  FROM public.banking_pay_workbench_jobs AS delta_job
  WHERE delta_job.session_id=p_session_id
    AND delta_job.candidate_id=p_candidate_id
    AND UPPER(BTRIM(COALESCE(delta_job.job_type,''))) IN ('WORKBENCH_CANDIDATE_DELTA_REFRESH','CANDIDATE_DELTA_REFRESH','DELTA_REFRESH')
    AND UPPER(BTRIM(COALESCE(delta_job.status,'')))='RUNNING'
    AND COALESCE(delta_job.payload_json->>'projection_run_id','')=p_projection_run_id::text
  ORDER BY delta_job.started_at_utc DESC NULLS LAST,delta_job.id
  LIMIT 1
  FOR UPDATE;
  IF v_completion_job_id IS NULL THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_TARGETED_DELTA_FINALIZE_JOB_MISSING' USING ERRCODE='P0001';
  END IF;

  v_publication:=private.pay_workbench_publish_certified_source_preview_v1(
    p_session_id,p_candidate_id,(v_seal->>'accepted_build_id')::uuid,p_projection_run_id,
    v_run.source_change_seq,v_run.session_version,v_completion_job_id,'TARGETED_TIMESHEETS',
    COALESCE(v_run.targeted_timesheet_ids,'[]'::jsonb),COALESCE(v_run.linked_timesheet_ids,'[]'::jsonb),
    jsonb_build_object(
      'contract_version',CASE WHEN v_semantic_publication_v3_enabled THEN 3 ELSE 2 END,
      'semantic_contract_version',CASE WHEN v_semantic_publication_v3_enabled THEN 'READY_TO_PAY_SEMANTIC_V2' ELSE NULL END,
      'authority_kind','TARGETED_DELTA',
      'invocation_kind','DELTA_FINALISE',
      'final_state',CASE WHEN EXISTS (
        SELECT 1 FROM public.banking_pay_workbench_candidate_source_lines AS current_source
        WHERE current_source.session_id=p_session_id AND current_source.candidate_id=p_candidate_id AND current_source.status='CURRENT'
      ) THEN 'READY' ELSE 'SOURCE_EMPTY' END,
      'projection_run_id',p_projection_run_id,
      'admission_seal_version',v_run.admission_seal_version,
      'admission_seal_digest',v_run.admission_seal_digest,
      'projection_fingerprint',v_run.projection_fingerprint,
      'accepted_baseline_build_id',v_seal->>'accepted_build_id'
    )
  );

  v_state := public.pay_workbench_delta_update_candidate_state_v1(
    p_session_id,p_candidate_id,p_projection_run_id,
    jsonb_build_object('context','TARGETED_LIFECYCLE_DELTA_FINALIZE','source_change_seq',v_run.source_change_seq)
  );

  UPDATE private.banking_pay_workbench_timesheet_scope_state AS state_row
  SET economic_state=CASE WHEN EXISTS (
        SELECT 1 FROM public.banking_pay_workbench_candidate_source_lines AS s
        WHERE s.session_id=p_session_id AND s.candidate_id=p_candidate_id
          AND s.timesheet_id=state_row.timesheet_id AND s.status='CURRENT'
      ) THEN 'LIVE' ELSE 'CLOSED' END,
      evaluated_generation=state_row.dirty_generation,
      evaluated_input_fingerprint=state_row.current_input_fingerprint,
      last_evaluated_at_utc=v_now,
      closed_at_utc=CASE WHEN EXISTS (
        SELECT 1 FROM public.banking_pay_workbench_candidate_source_lines AS s
        WHERE s.session_id=p_session_id AND s.candidate_id=p_candidate_id
          AND s.timesheet_id=state_row.timesheet_id AND s.status='CURRENT'
      ) THEN NULL ELSE v_now END,
      updated_at_utc=v_now
  WHERE state_row.candidate_id=p_candidate_id AND state_row.timesheet_id=ANY(v_targets);

  UPDATE public.banking_pay_workbench_candidate_delta_projection_runs AS run_update
  SET status='COMPLETED',phase='FINALISE',fallback_required=false,fallback_reason=NULL,
      candidate_state_updated=true,completed_at_utc=v_now,updated_at_utc=v_now,
      diagnostics_json=COALESCE(run_update.diagnostics_json,'{}'::jsonb)||jsonb_build_object(
        'atomic_promotion',true,'source_promoted',v_source_promoted,'source_retired',v_source_retired,
        'line_promoted',v_line_promoted,'line_retired',v_line_retired,
        'preview_promoted',v_preview_promoted,'preview_retired',v_preview_retired
      )
  WHERE run_update.id=p_projection_run_id;

  PERFORM public.pay_workbench_session_recompute_progress_counters(
    p_session_id,true,'TARGETED_LIFECYCLE_DELTA_FINALISE',true
  );

  RETURN jsonb_build_object(
    'ok',true,'status','COMPLETED','projection_run_id',p_projection_run_id,
    'source_promoted',v_source_promoted,'source_retired',v_source_retired,
    'line_promoted',v_line_promoted,'line_retired',v_line_retired,
    'preview_promoted',v_preview_promoted,'preview_retired',v_preview_retired,
    'candidate_state',v_state,
    'certified_publication',v_publication
  );
END;
$function$;

-- private.pay_workbench_timesheet_dependency_closure_v2(uuid,jsonb,integer)
CREATE OR REPLACE FUNCTION private.pay_workbench_timesheet_dependency_closure_v2(p_build_id uuid, p_cursor_json jsonb DEFAULT '{}'::jsonb, p_limit integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_build private.banking_pay_workbench_economic_builds%ROWTYPE;
  v_registry private.banking_pay_workbench_candidate_scope_registry%ROWTYPE;
  v_cursor jsonb:=COALESCE(p_cursor_json,'{}'::jsonb);
  v_limit integer:=LEAST(GREATEST(COALESCE(p_limit,25),2),25);
  v_mode text:=COALESCE(NULLIF(v_cursor->>'cursor_kind',''),'DEPENDENCY_CLOSURE');
  v_frontier uuid;
  v_family integer:=COALESCE((v_cursor->>'dependency_family_ordinal')::integer,1);
  v_last_key text:=v_cursor->>'last_edge_key';
  v_processed integer:=0;
  v_used integer:=0;
  v_new_scope integer:=0;
  v_new_edges integer:=0;
  v_edge_count bigint:=COALESCE((v_cursor->>'processed_edge_count')::bigint,0);
  v_emission_count bigint:=COALESCE((v_cursor->>'processed_emission_count')::bigint,0);
  v_page integer:=COALESCE((v_cursor->>'page_number')::integer,1);
  v_phase text:=COALESCE(NULLIF(v_cursor->>'seal_phase',''),'ANCHOR_INITIALISE');
  v_pass integer:=COALESCE((v_cursor->>'pass_number')::integer,1);
  v_changed bigint:=COALESCE((v_cursor->>'changed_rows_in_pass')::bigint,0);
  v_tagged bigint:=COALESCE((v_cursor->>'tagged_edge_count')::bigint,0);
  v_row_seal_count bigint:=COALESCE((v_cursor->>'row_seal_count')::bigint,0);
  v_last_ordinal bigint:=COALESCE((v_cursor->>'last_stable_ordinal')::bigint,0);
  v_scope_digest text:=COALESCE(NULLIF(v_cursor->>'rolling_scope_digest',''),md5('BPAY_SCOPE_V1'));
  v_fingerprint_digest text:=COALESCE(NULLIF(v_cursor->>'rolling_fingerprint_digest',''),md5('BPAY_FINGERPRINT_V1'));
  v_edge_tag_digest text:=COALESCE(NULLIF(v_cursor->>'rolling_edge_tag_digest',''),md5('BPAY_EDGE_TAG_V1'));
  v_edge_stream_digest text:=COALESCE(NULLIF(v_cursor->>'rolling_dependency_edge_digest',''),md5('BPAY_DEPENDENCY_EDGE_STREAM_V1'));
  v_unit_roll text:=COALESCE(NULLIF(v_cursor->>'current_unit_digest',''),md5('BPAY_UNIT_V1'));
  v_all_unit_digest text:=COALESCE(NULLIF(v_cursor->>'rolling_all_unit_digest',''),md5('BPAY_ALL_UNITS_V1'));
  v_completed_units integer:=COALESCE((v_cursor->>'completed_unit_count')::integer,0);
  v_unit_subphase text:=COALESCE(NULLIF(v_cursor->>'unit_subphase',''),'TAGGED_EDGE_STREAM');
  v_current_unit text:=NULLIF(v_cursor->>'current_unit_key','');
  v_last_timesheet uuid:=NULLIF(v_cursor->>'last_timesheet_id','')::uuid;
  v_last_anchor uuid:=NULLIF(v_cursor->>'last_unit_anchor_timesheet_id','')::uuid;
  v_candidate_id uuid;
  v_source_key text;
  v_member uuid;
  v_edge_kind text;
  v_edge_source uuid;
  v_natural_key text;
  v_financial_digest text;
  v_scope_exists boolean;
  v_edge_exists boolean;
  v_existing_digest text;
  v_anchor_from uuid;
  v_anchor_to uuid;
  v_anchor uuid;
  v_unit_key text;
  v_unit_digest text;
  v_input_fingerprint text;
  v_row_digest text;
  v_next jsonb;
  v_has_more boolean:=true;
  v_row record;
  v_family_names text[]:=ARRAY[
    'CORRECTION_FORWARD','CORRECTION_REVERSE','CORRECTION_OPERATION_UNIT',
    'IMPORT_AUTHORITATIVE_UNIT','BOOKING_FAMILY','ROTATION_FAMILY',
    'CANONICAL_ROTATION_PROJECTION','FINANCE_CASE_LINK','FINANCE_COMPONENT_LINK',
    'RESERVATION_LINK','COMPLETE'
  ];
BEGIN
  IF jsonb_typeof(v_cursor)<>'object' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_CURSOR_INVALID' USING ERRCODE='22023';
  END IF;
  SELECT candidate_id INTO v_candidate_id
  FROM private.banking_pay_workbench_economic_builds WHERE id=p_build_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_NOT_CURRENT' USING ERRCODE='40001'; END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    public._pay_workbench_candidate_serial_key(v_candidate_id),24062027));
  SELECT * INTO v_registry FROM private.banking_pay_workbench_candidate_scope_registry
  WHERE candidate_id=v_candidate_id FOR UPDATE;
  SELECT * INTO v_build FROM private.banking_pay_workbench_economic_builds
  WHERE id=p_build_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_NOT_CURRENT' USING ERRCODE='40001'; END IF;
  IF v_registry.current_build_id IS DISTINCT FROM p_build_id
     OR v_registry.dirty_generation<>v_build.captured_candidate_generation
     OR v_registry.current_source_change_seq<>v_build.source_change_seq
     OR v_build.status<>'COLLECTING' OR v_build.private_stage<>'DEPENDENCY_CLOSURE' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_NOT_CURRENT' USING ERRCODE='40001';
  END IF;

  IF v_mode='DEPENDENCY_CLOSURE' THEN
    v_frontier:=NULLIF(v_cursor->>'frontier_timesheet_id','')::uuid;
    IF v_frontier IS NULL THEN
      SELECT timesheet_id INTO v_frontier
      FROM private.banking_pay_workbench_economic_build_scope
      WHERE build_id=p_build_id AND closure_status='PENDING'
      ORDER BY timesheet_id LIMIT 1 FOR UPDATE;
      v_family:=1; v_last_key:=NULL;
    END IF;

    IF v_frontier IS NULL THEN
      UPDATE private.banking_pay_workbench_economic_builds
      SET dependency_edge_stream_complete=true,
          dependency_edge_stream_terminal_key_json=jsonb_build_object('terminal',true,'last_edge_key',v_cursor->>'last_edge_key'),
          dependency_edge_stream_digest=v_edge_stream_digest,
          dependency_node_count=scope_count,
          closure_cursor_json=jsonb_build_object(
            'cursor_kind','DEPENDENCY_SCOPE_SEAL','cursor_version',1,'build_id',p_build_id,
            'candidate_id',v_candidate_id,'captured_candidate_generation',v_build.captured_candidate_generation,
            'captured_source_change_seq',v_build.source_change_seq,'seal_phase','ANCHOR_INITIALISE',
            'pass_number',1,'last_timesheet_id',NULL,'last_edge_key',NULL,
            'changed_rows_in_pass',0,'tagged_edge_count',0,'row_seal_count',0,
            'last_stable_ordinal',0,'rolling_scope_digest',md5('BPAY_SCOPE_V1'),
            'rolling_fingerprint_digest',md5('BPAY_FINGERPRINT_V1'),
            'rolling_edge_tag_digest',md5('BPAY_EDGE_TAG_V1'),
            'rolling_dependency_edge_digest',v_edge_stream_digest,
            'rolling_all_unit_digest',md5('BPAY_ALL_UNITS_V1'),
            'completed_unit_count',0,'unit_subphase','TAGGED_EDGE_STREAM','page_number',1
          ),updated_at_utc=clock_timestamp()
      WHERE id=p_build_id;
      v_next:=(SELECT closure_cursor_json FROM private.banking_pay_workbench_economic_builds WHERE id=p_build_id);
      RETURN jsonb_build_object('ok',true,'build_id',p_build_id,'processed_frontier_count',0,
        'processed_emission_count',0,'inserted_scope_count',0,'inserted_edge_count',0,
        'dependency_node_count',v_build.scope_count,'dependency_edge_count',v_build.dependency_edge_count,
        'has_more',true,'next_cursor_json',v_next,'scope_digest',NULL,'dependency_digest',NULL);
    END IF;

    CREATE TEMP TABLE IF NOT EXISTS pg_temp._bpay_wb_closure_edge_page_v2(
      source_key text PRIMARY KEY,member_timesheet_id uuid NOT NULL,
      edge_kind text NOT NULL,edge_source_id uuid NOT NULL
    ) ON COMMIT DROP;
    -- Empty dependency families are metadata transitions, not material edge
    -- pages. Skip the fixed ten-family set inside this one bounded attempt and
    -- stop as soon as a real edge page is found. This removes one-job-per-empty-
    -- family latency without increasing the 25-unit edge/emission budget.
    LOOP
      TRUNCATE pg_temp._bpay_wb_closure_edge_page_v2;

      IF v_family=1 THEN
      INSERT INTO pg_temp._bpay_wb_closure_edge_page_v2
      SELECT 'PARENT:'||parent_timesheet_id::text,parent_timesheet_id,'CORRECTION_FORWARD',timesheet_id
      FROM public.timesheets WHERE timesheet_id=v_frontier AND parent_timesheet_id IS NOT NULL
        AND (v_last_key IS NULL OR 'PARENT:'||parent_timesheet_id::text>v_last_key)
      ORDER BY 1 LIMIT v_limit+1;
    ELSIF v_family=2 THEN
      INSERT INTO pg_temp._bpay_wb_closure_edge_page_v2
      SELECT 'CHILD:'||timesheet_id::text,timesheet_id,'CORRECTION_REVERSE',timesheet_id
      FROM public.timesheets WHERE parent_timesheet_id=v_frontier
        AND (v_last_key IS NULL OR 'CHILD:'||timesheet_id::text>v_last_key)
      ORDER BY 1 LIMIT v_limit+1;
    ELSIF v_family IN (3,4) THEN
      INSERT INTO pg_temp._bpay_wb_closure_edge_page_v2
      SELECT (CASE WHEN v_family=3 THEN 'CORRECTION:' ELSE 'IMPORT:' END)||related.timesheet_id::text,
             related.timesheet_id,
             CASE WHEN v_family=3 THEN 'CORRECTION_OPERATION_UNIT' ELSE 'IMPORT_AUTHORITATIVE_UNIT' END,
             related.timesheet_id
      FROM public.timesheets AS frontier
      JOIN public.timesheets AS related ON related.correction_id=frontier.correction_id
      WHERE frontier.timesheet_id=v_frontier AND frontier.correction_id IS NOT NULL
        AND related.timesheet_id<>v_frontier
        AND (v_last_key IS NULL OR (CASE WHEN v_family=3 THEN 'CORRECTION:' ELSE 'IMPORT:' END)||related.timesheet_id::text>v_last_key)
      ORDER BY 1 LIMIT v_limit+1;
    ELSIF v_family=5 THEN
      INSERT INTO pg_temp._bpay_wb_closure_edge_page_v2
      SELECT 'BOOKING:'||related.timesheet_id::text,related.timesheet_id,'BOOKING_FAMILY',related.timesheet_id
      FROM public.timesheets AS frontier
      JOIN public.timesheets AS related ON related.booking_id=frontier.booking_id
      WHERE frontier.timesheet_id=v_frontier AND frontier.booking_id IS NOT NULL
        AND related.timesheet_id<>v_frontier
        AND (v_last_key IS NULL OR 'BOOKING:'||related.timesheet_id::text>v_last_key)
      ORDER BY 1 LIMIT v_limit+1;
    ELSIF v_family IN (6,7) THEN
      INSERT INTO pg_temp._bpay_wb_closure_edge_page_v2
      SELECT (CASE WHEN v_family=6 THEN 'ROTATION:' ELSE 'CANONICAL_ROTATION:' END)||rotation.family_timesheet_id::text,
             rotation.family_timesheet_id,
             CASE WHEN v_family=6 THEN 'ROTATION_FAMILY' ELSE 'CANONICAL_ROTATION_PROJECTION' END,
             rotation.family_timesheet_id
      FROM public._pay_timesheet_rotation_scope(ARRAY[v_frontier]) AS rotation
      WHERE rotation.family_timesheet_id<>v_frontier
        AND (v_last_key IS NULL OR (CASE WHEN v_family=6 THEN 'ROTATION:' ELSE 'CANONICAL_ROTATION:' END)||rotation.family_timesheet_id::text>v_last_key)
      ORDER BY 1 LIMIT v_limit+1;
    ELSIF v_family IN (8,9) THEN
      INSERT INTO pg_temp._bpay_wb_closure_edge_page_v2
      WITH frontier_cases AS (
        SELECT DISTINCT frontier_component.finance_case_id
        FROM public.pay_finance_case_components AS frontier_component
        WHERE frontier_component.linked_timesheet_id=v_frontier
          AND frontier_component.finance_case_id IS NOT NULL
      ), authoritative_edges AS (
        SELECT DISTINCT
          (CASE WHEN v_family=8 THEN 'CASE:' ELSE 'COMPONENT:' END)||component_row.id::text AS source_key,
          component_row.linked_timesheet_id AS target_timesheet_id,
          CASE WHEN v_family=8 THEN 'FINANCE_CASE_LINK' ELSE 'FINANCE_COMPONENT_LINK' END AS edge_kind,
          component_row.id AS edge_source_id
        FROM frontier_cases
        JOIN public.pay_finance_case_components AS component_row
          ON component_row.finance_case_id=frontier_cases.finance_case_id
        WHERE component_row.linked_timesheet_id IS NOT NULL
          AND component_row.linked_timesheet_id<>v_frontier
      )
      SELECT source_key,target_timesheet_id,edge_kind,edge_source_id
      FROM authoritative_edges
      WHERE v_last_key IS NULL OR source_key>v_last_key
      ORDER BY source_key LIMIT v_limit+1;
      ELSIF v_family=10 THEN
      INSERT INTO pg_temp._bpay_wb_closure_edge_page_v2
      WITH frontier_components AS (
        SELECT DISTINCT frontier_component.id,frontier_component.finance_case_id
        FROM public.pay_finance_case_components AS frontier_component
        WHERE frontier_component.linked_timesheet_id=v_frontier
      ), authoritative_reservation_ids AS (
        SELECT reservation_row.id
        FROM public.pay_advance_reservations AS reservation_row
        JOIN (SELECT DISTINCT finance_case_id FROM frontier_components WHERE finance_case_id IS NOT NULL) AS frontier_cases
          ON frontier_cases.finance_case_id=reservation_row.finance_case_id
        UNION
        SELECT reservation_row.id
        FROM public.pay_advance_reservations AS reservation_row
        JOIN frontier_components ON frontier_components.id=reservation_row.finance_component_id
      ), authoritative_edges AS (
        SELECT DISTINCT
          'RESERVATION:'||reservation_row.id::text||':'||linked_component.linked_timesheet_id::text AS source_key,
          linked_component.linked_timesheet_id AS target_timesheet_id,
          'RESERVATION_LINK'::text AS edge_kind,
          reservation_row.id AS edge_source_id
        FROM authoritative_reservation_ids
        JOIN public.pay_advance_reservations AS reservation_row
          ON reservation_row.id=authoritative_reservation_ids.id
        JOIN public.pay_finance_case_components AS linked_component
          ON linked_component.id=reservation_row.finance_component_id
        WHERE linked_component.linked_timesheet_id IS NOT NULL
          AND linked_component.linked_timesheet_id<>v_frontier
      )
      SELECT source_key,target_timesheet_id,edge_kind,edge_source_id
      FROM authoritative_edges
      WHERE v_last_key IS NULL OR source_key>v_last_key
      ORDER BY source_key LIMIT v_limit+1;
      END IF;

      EXIT WHEN EXISTS(SELECT 1 FROM pg_temp._bpay_wb_closure_edge_page_v2)
        OR v_family>=10;
      v_family:=v_family+1;
      v_last_key:=NULL;
    END LOOP;

    FOR v_row IN SELECT * FROM pg_temp._bpay_wb_closure_edge_page_v2 ORDER BY source_key
    LOOP
      SELECT EXISTS(SELECT 1 FROM private.banking_pay_workbench_economic_build_scope
        WHERE build_id=p_build_id AND timesheet_id=v_row.member_timesheet_id) INTO v_scope_exists;
      IF v_used+1+(CASE WHEN v_scope_exists THEN 0 ELSE 1 END)>v_limit THEN EXIT; END IF;
      IF NOT v_scope_exists AND NOT EXISTS(
        SELECT 1 FROM public.timesheets_financials AS owner_row
        WHERE owner_row.timesheet_id=v_row.member_timesheet_id AND owner_row.candidate_id=v_candidate_id
      ) THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_DEPENDENCY_IDENTITY_CONFLICT' USING ERRCODE='23514';
      END IF;
      v_source_key:=v_row.source_key; v_member:=v_row.member_timesheet_id;
      v_edge_kind:=v_row.edge_kind; v_edge_source:=v_row.edge_source_id;
      v_natural_key:=lower(md5(v_edge_kind||':'||v_frontier::text||':'||v_member::text||':'||v_edge_source::text));
      v_financial_digest:=md5(jsonb_build_object('edge_kind',v_edge_kind,
        'from',v_frontier,'to',v_member,'source',v_edge_source)::text);
      v_edge_exists:=false; v_existing_digest:=NULL;
      SELECT true,financial_digest INTO v_edge_exists,v_existing_digest
      FROM private.banking_pay_workbench_economic_build_facts
      WHERE build_id=p_build_id AND fact_family='DEPENDENCY_EDGE' AND natural_key=v_natural_key;
      IF COALESCE(v_edge_exists,false) THEN
        IF v_existing_digest IS DISTINCT FROM v_financial_digest THEN
          RAISE EXCEPTION 'PAY_WORKBENCH_DEPENDENCY_EDGE_REPLAY_CONFLICT' USING ERRCODE='23514';
        END IF;
      ELSE
        INSERT INTO private.banking_pay_workbench_economic_build_facts(
          build_id,fact_family,natural_key,candidate_id,subject_timesheet_ids,
          source_relation,source_id,financial_digest,edge_kind,
          edge_from_timesheet_id,edge_to_timesheet_id,edge_source_id
        ) VALUES (p_build_id,'DEPENDENCY_EDGE',v_natural_key,v_candidate_id,
          ARRAY[v_frontier,v_member],CASE WHEN v_edge_kind LIKE 'FINANCE_%' THEN 'pay_finance_case_components'
            WHEN v_edge_kind='RESERVATION_LINK' THEN 'pay_advance_reservations' ELSE 'timesheets' END,
          v_edge_source,v_financial_digest,v_edge_kind,v_frontier,v_member,v_edge_source);
        v_new_edges:=v_new_edges+1;
      END IF;
      v_edge_stream_digest:=md5(v_edge_stream_digest||v_natural_key||v_financial_digest);
      IF NOT v_scope_exists THEN
        INSERT INTO private.banking_pay_workbench_economic_build_scope(
          build_id,timesheet_id,candidate_id,seed_reasons,dependency_reasons,
          captured_dirty_generation,required_fact_families
        ) VALUES (p_build_id,v_member,v_candidate_id,ARRAY[]::text[],ARRAY[v_edge_kind],
          v_build.captured_candidate_generation,
          ARRAY['FROZEN_SETTLED_COMPONENT','LIVE_ENTITLEMENT_INPUT','ENTITLEMENT_COMPONENT',
            'PAY_STATE_FALLBACK','PAYEE_BASELINE_INPUT','CANONICAL_INPUT']::text[])
        ON CONFLICT(build_id,timesheet_id) DO NOTHING;
        v_new_scope:=v_new_scope+1;
      ELSE
        UPDATE private.banking_pay_workbench_economic_build_scope AS scope_row
        SET dependency_reasons=(SELECT array_agg(DISTINCT reason ORDER BY reason)
          FROM unnest(scope_row.dependency_reasons||ARRAY[v_edge_kind]) AS reason),
            updated_at_utc=clock_timestamp()
        WHERE build_id=p_build_id AND timesheet_id=v_member;
      END IF;
      v_used:=v_used+1+(CASE WHEN v_scope_exists THEN 0 ELSE 1 END);
      v_processed:=v_processed+1; v_edge_count:=v_edge_count+1;
      v_emission_count:=v_emission_count+1; v_last_key:=v_source_key;
    END LOOP;

    IF v_processed=0 AND EXISTS(SELECT 1 FROM pg_temp._bpay_wb_closure_edge_page_v2) THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_DEPENDENCY_PAGE_UNIT_TOO_SMALL' USING ERRCODE='54000';
    END IF;
    IF NOT EXISTS(
      SELECT 1 FROM pg_temp._bpay_wb_closure_edge_page_v2
      WHERE v_last_key IS NULL OR source_key>v_last_key
    ) THEN
      v_family:=v_family+1; v_last_key:=NULL;
    END IF;
    IF v_family>10 THEN
      UPDATE private.banking_pay_workbench_economic_build_scope
      SET closure_status='EXPANDED',closure_family_ordinal=11,updated_at_utc=clock_timestamp()
      WHERE build_id=p_build_id AND timesheet_id=v_frontier AND closure_status='PENDING';
      v_frontier:=NULL; v_family:=1;
    ELSE
      UPDATE private.banking_pay_workbench_economic_build_scope
      SET closure_family_ordinal=v_family,closure_last_edge_key=v_last_key,
          closure_processed_edge_count=closure_processed_edge_count+v_processed,
          closure_processed_emission_count=closure_processed_emission_count+v_processed,
          updated_at_utc=clock_timestamp()
      WHERE build_id=p_build_id AND timesheet_id=v_frontier;
    END IF;
    UPDATE private.banking_pay_workbench_economic_builds
    SET scope_count=scope_count+v_new_scope,dependency_node_count=dependency_node_count+v_new_scope,
        dependency_edge_count=dependency_edge_count+v_new_edges,
        dependency_edge_stream_digest=v_edge_stream_digest,
        closure_cursor_json=jsonb_build_object(
          'cursor_kind','DEPENDENCY_CLOSURE','cursor_version',1,'build_id',p_build_id,
          'candidate_id',v_candidate_id,'captured_candidate_generation',v_build.captured_candidate_generation,
          'captured_source_change_seq',v_build.source_change_seq,'frontier_timesheet_id',v_frontier,
          'dependency_family',v_family_names[v_family],'dependency_family_ordinal',v_family,
          'last_edge_key',v_last_key,'processed_edge_count',v_edge_count,
          'processed_emission_count',v_emission_count,'page_number',v_page+1,
          'rolling_dependency_edge_digest',v_edge_stream_digest,
          'previous_page_digest',md5(v_cursor::text||COALESCE(v_last_key,'')||v_edge_stream_digest)
        ),updated_at_utc=clock_timestamp()
    WHERE id=p_build_id;
    v_next:=(SELECT closure_cursor_json FROM private.banking_pay_workbench_economic_builds WHERE id=p_build_id);
    RETURN jsonb_build_object('ok',true,'build_id',p_build_id,'processed_frontier_count',1,
      'processed_emission_count',v_processed,'inserted_scope_count',v_new_scope,
      'inserted_edge_count',v_new_edges,'dependency_node_count',v_build.dependency_node_count+v_new_scope,
      'dependency_edge_count',v_build.dependency_edge_count+v_new_edges,'has_more',true,
      'next_cursor_json',v_next,'scope_digest',NULL,'dependency_digest',NULL);
  END IF;

  IF v_mode<>'DEPENDENCY_SCOPE_SEAL' THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_CURSOR_INVALID' USING ERRCODE='22023';
  END IF;

  -- Phase 1: bounded anchor initialisation.
  IF v_phase='ANCHOR_INITIALISE' THEN
    FOR v_row IN SELECT timesheet_id FROM private.banking_pay_workbench_economic_build_scope
      WHERE build_id=p_build_id AND closure_status='EXPANDED'
        AND (v_last_timesheet IS NULL OR timesheet_id>v_last_timesheet)
      ORDER BY timesheet_id LIMIT v_limit FOR UPDATE
    LOOP
      UPDATE private.banking_pay_workbench_economic_build_scope
      SET dependency_unit_anchor_timesheet_id=v_row.timesheet_id,closure_status='SEALING',updated_at_utc=clock_timestamp()
      WHERE build_id=p_build_id AND timesheet_id=v_row.timesheet_id;
      v_last_timesheet:=v_row.timesheet_id; v_processed:=v_processed+1;
    END LOOP;
    IF v_processed<v_limit THEN v_phase:='ANCHOR_PROPAGATE';v_last_timesheet:=NULL;v_last_key:=NULL;v_pass:=1;v_changed:=0; END IF;

  ELSIF v_phase='ANCHOR_PROPAGATE' THEN
    FOR v_row IN SELECT natural_key,edge_from_timesheet_id,edge_to_timesheet_id
      FROM private.banking_pay_workbench_economic_build_facts
      WHERE build_id=p_build_id AND fact_family='DEPENDENCY_EDGE'
        AND (v_last_key IS NULL OR natural_key>v_last_key)
      ORDER BY natural_key LIMIT v_limit
    LOOP
      SELECT dependency_unit_anchor_timesheet_id INTO v_anchor_from
      FROM private.banking_pay_workbench_economic_build_scope
      WHERE build_id=p_build_id AND timesheet_id=v_row.edge_from_timesheet_id FOR UPDATE;
      SELECT dependency_unit_anchor_timesheet_id INTO v_anchor_to
      FROM private.banking_pay_workbench_economic_build_scope
      WHERE build_id=p_build_id AND timesheet_id=v_row.edge_to_timesheet_id FOR UPDATE;
      v_anchor:=LEAST(v_anchor_from,v_anchor_to);
      UPDATE private.banking_pay_workbench_economic_build_scope
      SET dependency_unit_anchor_timesheet_id=v_anchor,updated_at_utc=clock_timestamp()
      WHERE build_id=p_build_id AND timesheet_id IN (v_row.edge_from_timesheet_id,v_row.edge_to_timesheet_id)
        AND dependency_unit_anchor_timesheet_id<>v_anchor;
      GET DIAGNOSTICS v_used=ROW_COUNT; v_changed:=v_changed+v_used;
      v_last_key:=v_row.natural_key;v_processed:=v_processed+1;
    END LOOP;
    IF v_processed<v_limit THEN
      IF v_changed>0 THEN v_pass:=v_pass+1;v_last_key:=NULL;v_changed:=0;
      ELSE v_phase:='EDGE_UNIT_TAG';v_last_key:=NULL; END IF;
    END IF;

  ELSIF v_phase='EDGE_UNIT_TAG' THEN
    FOR v_row IN SELECT natural_key,edge_from_timesheet_id,edge_to_timesheet_id,financial_digest
      FROM private.banking_pay_workbench_economic_build_facts
      WHERE build_id=p_build_id AND fact_family='DEPENDENCY_EDGE'
        AND (v_last_key IS NULL OR natural_key>v_last_key)
      ORDER BY natural_key LIMIT v_limit FOR UPDATE
    LOOP
      SELECT dependency_unit_anchor_timesheet_id INTO v_anchor_from FROM private.banking_pay_workbench_economic_build_scope
      WHERE build_id=p_build_id AND timesheet_id=v_row.edge_from_timesheet_id;
      SELECT dependency_unit_anchor_timesheet_id INTO v_anchor_to FROM private.banking_pay_workbench_economic_build_scope
      WHERE build_id=p_build_id AND timesheet_id=v_row.edge_to_timesheet_id;
      IF v_anchor_from IS NULL OR v_anchor_from IS DISTINCT FROM v_anchor_to THEN
        RAISE EXCEPTION 'PAY_WORKBENCH_DEPENDENCY_IDENTITY_CONFLICT' USING ERRCODE='23514';
      END IF;
      v_unit_key:='UNIT:'||lower(v_anchor_from::text);
      UPDATE private.banking_pay_workbench_economic_build_facts SET dependency_unit_key=v_unit_key
      WHERE build_id=p_build_id AND fact_family='DEPENDENCY_EDGE' AND natural_key=v_row.natural_key;
      v_edge_tag_digest:=md5(v_edge_tag_digest||md5(v_row.natural_key||':'||v_unit_key||':'||v_row.financial_digest));
      v_tagged:=v_tagged+1;v_last_key:=v_row.natural_key;v_processed:=v_processed+1;
    END LOOP;
    IF v_processed<v_limit THEN
      IF v_tagged<>v_build.dependency_edge_count THEN RAISE EXCEPTION 'PAY_WORKBENCH_DEPENDENCY_EDGE_COUNT_MISMATCH' USING ERRCODE='23514'; END IF;
      UPDATE private.banking_pay_workbench_economic_builds SET tagged_edge_count=v_tagged,
        edge_tag_digest=v_edge_tag_digest,edge_tag_stream_complete=true,
        edge_tag_stream_terminal_key_json=jsonb_build_object('terminal',true,'last_edge_key',v_last_key),updated_at_utc=clock_timestamp()
      WHERE id=p_build_id;
      v_phase:='UNIT_DIGEST';v_last_key:=NULL;v_current_unit:=NULL;
      v_unit_subphase:='TAGGED_EDGE_STREAM';v_unit_roll:=md5('BPAY_UNIT_V1');
    END IF;

  ELSIF v_phase='UNIT_DIGEST' THEN
    IF v_unit_subphase='TAGGED_EDGE_STREAM' THEN
      FOR v_row IN
        SELECT dependency_unit_key,natural_key,financial_digest
        FROM private.banking_pay_workbench_economic_build_facts
        WHERE build_id=p_build_id AND fact_family='DEPENDENCY_EDGE'
          AND dependency_unit_key IS NOT NULL
          AND (
            v_current_unit IS NULL
            OR dependency_unit_key>v_current_unit
            OR (dependency_unit_key=v_current_unit AND (v_last_key IS NULL OR natural_key>v_last_key))
          )
        ORDER BY dependency_unit_key,natural_key LIMIT v_limit
      LOOP
        IF v_current_unit IS NULL THEN
          v_current_unit:=v_row.dependency_unit_key;
          v_unit_roll:=md5('BPAY_UNIT_V1');
        ELSIF v_row.dependency_unit_key<>v_current_unit THEN
          v_anchor:=substring(v_current_unit from 6)::uuid;
          UPDATE private.banking_pay_workbench_economic_build_scope
          SET dependency_unit_digest=v_unit_roll,updated_at_utc=clock_timestamp()
          WHERE build_id=p_build_id AND timesheet_id=v_anchor
            AND dependency_unit_anchor_timesheet_id=v_anchor AND dependency_unit_digest IS NULL;
          IF NOT FOUND THEN RAISE EXCEPTION 'PAY_WORKBENCH_DEPENDENCY_UNIT_DIGEST_CONFLICT' USING ERRCODE='23514'; END IF;
          v_all_unit_digest:=md5(v_all_unit_digest||v_current_unit||v_unit_roll);
          v_completed_units:=v_completed_units+1;
          v_current_unit:=v_row.dependency_unit_key;
          v_unit_roll:=md5('BPAY_UNIT_V1');
        END IF;
        v_unit_roll:=md5(v_unit_roll||v_row.natural_key||v_row.financial_digest);
        v_last_key:=v_row.natural_key;v_processed:=v_processed+1;
      END LOOP;
      IF v_processed<v_limit THEN
        IF v_current_unit IS NOT NULL THEN
          v_anchor:=substring(v_current_unit from 6)::uuid;
          UPDATE private.banking_pay_workbench_economic_build_scope
          SET dependency_unit_digest=v_unit_roll,updated_at_utc=clock_timestamp()
          WHERE build_id=p_build_id AND timesheet_id=v_anchor
            AND dependency_unit_anchor_timesheet_id=v_anchor AND dependency_unit_digest IS NULL;
          IF NOT FOUND THEN RAISE EXCEPTION 'PAY_WORKBENCH_DEPENDENCY_UNIT_DIGEST_CONFLICT' USING ERRCODE='23514'; END IF;
          v_all_unit_digest:=md5(v_all_unit_digest||v_current_unit||v_unit_roll);
          v_completed_units:=v_completed_units+1;
        END IF;
        v_unit_subphase:='ISOLATED_UNITS';v_current_unit:=NULL;v_last_key:=NULL;v_last_timesheet:=NULL;
      END IF;
    ELSE
      FOR v_row IN
        SELECT timesheet_id,dependency_unit_anchor_timesheet_id
        FROM private.banking_pay_workbench_economic_build_scope
        WHERE build_id=p_build_id AND timesheet_id=dependency_unit_anchor_timesheet_id
          AND dependency_unit_digest IS NULL
          AND (v_last_timesheet IS NULL OR timesheet_id>v_last_timesheet)
        ORDER BY timesheet_id LIMIT v_limit FOR UPDATE
      LOOP
        v_unit_key:='UNIT:'||lower(v_row.timesheet_id::text);
        v_unit_roll:=md5('BPAY_UNIT_V1:'||v_row.timesheet_id::text);
        UPDATE private.banking_pay_workbench_economic_build_scope
        SET dependency_unit_digest=v_unit_roll,updated_at_utc=clock_timestamp()
        WHERE build_id=p_build_id AND timesheet_id=v_row.timesheet_id AND dependency_unit_digest IS NULL;
        v_all_unit_digest:=md5(v_all_unit_digest||v_unit_key||v_unit_roll);
        v_completed_units:=v_completed_units+1;v_last_timesheet:=v_row.timesheet_id;v_processed:=v_processed+1;
      END LOOP;
      IF v_processed<v_limit THEN
        v_phase:='ROW_SEAL';v_last_timesheet:=NULL;v_current_unit:=NULL;v_last_key:=NULL;
      END IF;
    END IF;

  ELSIF v_phase='ROW_SEAL' THEN
    FOR v_row IN SELECT scope_row.timesheet_id,scope_row.dependency_unit_anchor_timesheet_id,
      anchor_row.dependency_unit_digest
      FROM private.banking_pay_workbench_economic_build_scope AS scope_row
      JOIN private.banking_pay_workbench_economic_build_scope AS anchor_row
        ON anchor_row.build_id=scope_row.build_id
       AND anchor_row.timesheet_id=scope_row.dependency_unit_anchor_timesheet_id
      WHERE scope_row.build_id=p_build_id AND scope_row.closure_status='SEALING'
        AND (
          v_last_anchor IS NULL
          OR (scope_row.dependency_unit_anchor_timesheet_id,scope_row.timesheet_id)>(v_last_anchor,v_last_timesheet)
        )
      ORDER BY scope_row.dependency_unit_anchor_timesheet_id,scope_row.timesheet_id
      LIMIT v_limit FOR UPDATE OF scope_row
    LOOP
      SELECT fingerprint.input_fingerprint INTO v_input_fingerprint
      FROM private.pay_workbench_timesheet_input_fingerprint_v1(p_build_id,v_candidate_id,ARRAY[v_row.timesheet_id]) AS fingerprint;
      IF v_input_fingerprint IS NULL THEN RAISE EXCEPTION 'PAY_WORKBENCH_FINGERPRINT_INCOMPLETE' USING ERRCODE='23514'; END IF;
      v_last_ordinal:=v_last_ordinal+1;
      v_unit_key:='UNIT:'||lower(v_row.dependency_unit_anchor_timesheet_id::text);
      UPDATE private.banking_pay_workbench_economic_build_scope SET
        dependency_unit_key=v_unit_key,dependency_unit_digest=v_row.dependency_unit_digest,
        stable_ordinal=v_last_ordinal,captured_input_fingerprint=v_input_fingerprint,
        closure_status='SEALED',seal_prepared_at_utc=clock_timestamp(),updated_at_utc=clock_timestamp()
      WHERE build_id=p_build_id AND timesheet_id=v_row.timesheet_id;
      v_row_digest:=md5(jsonb_build_object('timesheet_id',v_row.timesheet_id,'unit',v_unit_key,
        'unit_digest',v_row.dependency_unit_digest,'ordinal',v_last_ordinal,'fingerprint',v_input_fingerprint)::text);
      v_scope_digest:=md5(v_scope_digest||v_row_digest);
      v_fingerprint_digest:=md5(v_fingerprint_digest||v_input_fingerprint);
      v_row_seal_count:=v_row_seal_count+1;v_last_anchor:=v_row.dependency_unit_anchor_timesheet_id;
      v_last_timesheet:=v_row.timesheet_id;v_processed:=v_processed+1;
    END LOOP;
    IF v_processed<v_limit THEN v_phase:='COMPLETE'; END IF;

  ELSIF v_phase='COMPLETE' THEN
    -- Metadata-only terminal proof: scalar cursor/header checks plus one partial-index probe.
    IF NOT v_build.dependency_edge_stream_complete
       OR NOT v_build.edge_tag_stream_complete
       OR v_build.tagged_edge_count<>v_build.dependency_edge_count
       OR v_build.unit_count<>v_completed_units OR v_build.unit_digest IS NULL
       OR v_row_seal_count<>v_build.scope_count OR v_last_ordinal<>v_row_seal_count
       OR EXISTS(SELECT 1 FROM private.banking_pay_workbench_economic_build_scope
         WHERE build_id=p_build_id AND closure_status<>'SEALED' LIMIT 1) THEN
      RAISE EXCEPTION 'PAY_WORKBENCH_DEPENDENCY_SEAL_INCOMPLETE' USING ERRCODE='23514';
    END IF;
    v_next:=jsonb_build_object(
      'cursor_kind','WORKSPACE_FACT','cursor_version',2,
      'build_id',p_build_id,'candidate_id',v_candidate_id,
      'captured_candidate_generation',v_build.captured_candidate_generation,
      'captured_source_change_seq',v_build.source_change_seq,
      'dependency_unit_key','GLOBAL','fact_family','FINANCE_ITEM_AUTHORITY',
      'input_phase','PHYSICAL_SOURCE','input_projection_id',NULL,
      'page_number',1,'last_source_key',NULL,'previous_page_digest',NULL,
      'cumulative_fact_count',0,
      'cumulative_digest',md5('BPAY_FACT_STREAM_V2'),'terminal',false,
      'raw_physical_source_count',0,'resolved_physical_source_count',0,
      'failed_physical_source_count',0,'raw_physical_amount_ex_vat',0,
      'resolved_physical_amount_ex_vat',0,'last_raw_physical_source_key',NULL,
      'source_exhausted',false,'raw_terminal_source_key',NULL,
      'raw_page_evidence_digest',NULL
    );
    UPDATE private.banking_pay_workbench_economic_builds SET
      row_seal_count=v_row_seal_count,last_stable_ordinal=v_last_ordinal,
      scope_digest=v_scope_digest,sealed_fingerprint_digest=v_fingerprint_digest,
      dependency_digest=md5(COALESCE(dependency_edge_stream_digest,'')||COALESCE(edge_tag_digest,'')),
      unit_digest=v_all_unit_digest,unit_count=v_completed_units,
      dependency_closure_sealed_at_utc=clock_timestamp(),
      private_stage='WORKSPACE_FACT',
      closure_cursor_json=jsonb_build_object('cursor_kind','DEPENDENCY_SCOPE_SEAL','cursor_version',1,
        'seal_phase','COMPLETE','terminal',true,'build_id',p_build_id,'candidate_id',v_candidate_id,
        'tagged_edge_count',tagged_edge_count,'row_seal_count',v_row_seal_count,
        'completed_unit_count',v_completed_units,'rolling_all_unit_digest',v_all_unit_digest,
        'last_stable_ordinal',v_last_ordinal,'rolling_scope_digest',v_scope_digest,
        'rolling_fingerprint_digest',v_fingerprint_digest,'rolling_edge_tag_digest',edge_tag_digest),
      fact_cursor_json=v_next,
      attestation_json=COALESCE(attestation_json,'{}'::jsonb)||CASE
        WHEN v_registry.bootstrap_stream='ACTIVE_RECONCILIATION' THEN jsonb_build_object(
          'bootstrap_active_reconciliation',true,
          'bootstrap_active_reconciliation_started_at_utc',COALESCE(
            NULLIF(attestation_json->>'bootstrap_active_reconciliation_started_at_utc','')::timestamptz,
            statement_timestamp()))
        ELSE '{}'::jsonb END,
      updated_at_utc=clock_timestamp()
    WHERE id=p_build_id;
    IF v_registry.initialisation_status IN ('DISCOVERING','CLASSIFYING')
       AND v_registry.bootstrap_id IS NOT NULL THEN
      UPDATE private.banking_pay_workbench_candidate_scope_registry
      SET initialisation_status='CLASSIFYING',bootstrap_stream='WORKSPACE_FACT',
          bootstrap_cursor_json=v_next,updated_at_utc=clock_timestamp()
      WHERE candidate_id=v_candidate_id AND current_build_id=p_build_id;
    END IF;
    RETURN jsonb_build_object('ok',true,'build_id',p_build_id,'processed_frontier_count',0,
      'processed_emission_count',0,'inserted_scope_count',0,'inserted_edge_count',0,
      'dependency_node_count',v_build.scope_count,'dependency_edge_count',v_build.dependency_edge_count,
      'has_more',true,'next_cursor_json',v_next,'scope_digest',v_scope_digest,
      'dependency_digest',md5(COALESCE(v_build.dependency_edge_stream_digest,'')||COALESCE(v_build.edge_tag_digest,'')));
  ELSE
    RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_CURSOR_INVALID' USING ERRCODE='22023';
  END IF;

  v_next:=jsonb_build_object(
    'cursor_kind','DEPENDENCY_SCOPE_SEAL','cursor_version',1,'build_id',p_build_id,
    'candidate_id',v_candidate_id,'captured_candidate_generation',v_build.captured_candidate_generation,
    'captured_source_change_seq',v_build.source_change_seq,'seal_phase',v_phase,
    'pass_number',v_pass,'last_timesheet_id',v_last_timesheet,
    'last_unit_anchor_timesheet_id',v_last_anchor,'last_edge_key',v_last_key,
    'changed_rows_in_pass',v_changed,'current_unit_key',v_current_unit,
    'current_unit_digest',v_unit_roll,'unit_subphase',v_unit_subphase,
    'completed_unit_count',v_completed_units,'rolling_all_unit_digest',v_all_unit_digest,
    'rolling_dependency_edge_digest',v_edge_stream_digest,'tagged_edge_count',v_tagged,
    'row_seal_count',v_row_seal_count,'last_stable_ordinal',v_last_ordinal,
    'rolling_scope_digest',v_scope_digest,'rolling_fingerprint_digest',v_fingerprint_digest,
    'rolling_edge_tag_digest',v_edge_tag_digest,'page_number',v_page+1
  );
  UPDATE private.banking_pay_workbench_economic_builds
  SET closure_cursor_json=v_next,row_seal_count=v_row_seal_count,last_stable_ordinal=v_last_ordinal,
      unit_count=v_completed_units,unit_digest=v_all_unit_digest,
      dependency_edge_stream_digest=v_edge_stream_digest,
      scope_digest=CASE WHEN v_row_seal_count>0 THEN v_scope_digest ELSE scope_digest END,
      sealed_fingerprint_digest=CASE WHEN v_row_seal_count>0 THEN v_fingerprint_digest ELSE sealed_fingerprint_digest END,
      updated_at_utc=clock_timestamp()
  WHERE id=p_build_id;
  RETURN jsonb_build_object('ok',true,'build_id',p_build_id,'processed_frontier_count',v_processed,
    'processed_emission_count',v_processed,'inserted_scope_count',0,'inserted_edge_count',0,
    'dependency_node_count',v_build.scope_count,'dependency_edge_count',v_build.dependency_edge_count,
    'has_more',v_has_more,'next_cursor_json',v_next,'scope_digest',NULL,'dependency_digest',NULL);
END;
$function$;

-- private.pay_workbench_timesheet_input_fingerprint_v1(uuid,uuid,uuid[])
CREATE OR REPLACE FUNCTION private.pay_workbench_timesheet_input_fingerprint_v1(p_build_id uuid, p_candidate_id uuid, p_timesheet_ids uuid[])
 RETURNS TABLE(timesheet_id uuid, input_fingerprint text, revision_json jsonb)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
WITH requested AS (
  SELECT DISTINCT requested_id AS timesheet_id
  FROM unnest(COALESCE(p_timesheet_ids,ARRAY[]::uuid[])) AS requested_id
  WHERE requested_id IS NOT NULL
), revisions AS (
  SELECT
    requested.timesheet_id,
    jsonb_strip_nulls(jsonb_build_object(
      'fingerprint_version',1,
      'build_id',p_build_id,
      'candidate_id',p_candidate_id,
      'timesheet_id',requested.timesheet_id,
      'timesheet_digest',md5(to_jsonb(timesheet_row)::text),
      'tsfin_digest',tsfin_revision.row_digest,
      'candidate_route_digest',md5(jsonb_build_object(
        'pay_method',to_jsonb(candidate_row)->'pay_method',
        'umbrella_id',to_jsonb(candidate_row)->'umbrella_id',
        'paye_state',to_jsonb(candidate_row)->'paye_state'
      )::text),
      'pay_state_digest',pay_state_revision.row_digest,
      'dirty_generation',scope_state.dirty_generation,
      'economic_state',scope_state.economic_state,
      'dependency_unit_key','UNIT:'||lower(build_scope.dependency_unit_anchor_timesheet_id::text),
      'dependency_unit_digest',anchor_scope.dependency_unit_digest,
      'override_revision',override_revision.revision_digest,
      'adjustment_revision',adjustment_revision.revision_digest,
      'snooze_revision',snooze_revision.revision_digest
    )) AS revision_json
  FROM requested
  JOIN public.timesheets AS timesheet_row
    ON timesheet_row.timesheet_id=requested.timesheet_id
  JOIN public.candidates AS candidate_row ON candidate_row.id=p_candidate_id
  JOIN private.banking_pay_workbench_timesheet_scope_state AS scope_state
    ON scope_state.timesheet_id=requested.timesheet_id
   AND scope_state.candidate_id=p_candidate_id
  JOIN private.banking_pay_workbench_economic_build_scope AS build_scope
    ON build_scope.build_id=p_build_id
   AND build_scope.timesheet_id=requested.timesheet_id
  JOIN private.banking_pay_workbench_economic_build_scope AS anchor_scope
    ON anchor_scope.build_id=build_scope.build_id
   AND anchor_scope.timesheet_id=build_scope.dependency_unit_anchor_timesheet_id
   AND anchor_scope.dependency_unit_digest IS NOT NULL
  LEFT JOIN LATERAL (
    SELECT md5(string_agg(md5(to_jsonb(financial_row)::text),'' ORDER BY financial_row.id)) AS row_digest
    FROM public.timesheets_financials AS financial_row
    WHERE financial_row.timesheet_id=requested.timesheet_id AND financial_row.is_current
      AND financial_row.candidate_id=p_candidate_id
  ) AS tsfin_revision ON true
  LEFT JOIN LATERAL (
    SELECT md5(to_jsonb(pay_state_row)::text) AS row_digest
    FROM public.timesheet_pay_state AS pay_state_row
    WHERE pay_state_row.timesheet_id=requested.timesheet_id
  ) AS pay_state_revision ON true
  LEFT JOIN LATERAL (
    SELECT md5(COALESCE(string_agg(
      override_row.id::text||':'||COALESCE(override_row.created_at_utc::text,'')||':'
      ||COALESCE(override_row.cleared_at_utc::text,'')||':'||COALESCE(override_row.consumed_at_utc::text,''),
      '' ORDER BY override_row.id),'')) AS revision_digest
    FROM public.timesheet_payment_overrides AS override_row
    WHERE override_row.candidate_id=p_candidate_id
      AND override_row.timesheet_id=requested.timesheet_id
      AND override_row.cleared_at_utc IS NULL
      AND override_row.consumed_at_utc IS NULL
      AND override_row.consumed_by_pay_batch_id IS NULL
  ) AS override_revision ON true
  LEFT JOIN LATERAL (
    SELECT md5(COALESCE(string_agg(
      adjustment_row.id::text||':'||COALESCE(adjustment_row.updated_at::text,''),
      '' ORDER BY adjustment_row.id),'')) AS revision_digest
    FROM public.ts_pay_adjustments AS adjustment_row
    WHERE adjustment_row.candidate_id=p_candidate_id
      AND adjustment_row.timesheet_id=requested.timesheet_id
      AND adjustment_row.paid_at_utc IS NULL
  ) AS adjustment_revision ON true
  LEFT JOIN LATERAL (
    SELECT md5(COALESCE(string_agg(
      snooze_row.id::text||':'||COALESCE(snooze_row.updated_at_utc::text,''),
      '' ORDER BY snooze_row.id),'')) AS revision_digest
    FROM public.pay_item_snoozes AS snooze_row
    WHERE snooze_row.candidate_id=p_candidate_id
      AND snooze_row.timesheet_id=requested.timesheet_id
      AND snooze_row.cleared_at_utc IS NULL AND snooze_row.cancelled_at_utc IS NULL
  ) AS snooze_revision ON true
)
SELECT revisions.timesheet_id,md5(revisions.revision_json::text),revisions.revision_json
FROM revisions
ORDER BY revisions.timesheet_id;
$function$;

-- private.pay_workbench_unit_economic_occurrence_bundle_v1(uuid,text,text,uuid,text,integer)
CREATE OR REPLACE FUNCTION private.pay_workbench_unit_economic_occurrence_bundle_v1(p_build_id uuid, p_dependency_unit_key text, p_fact_family text, p_projected_timesheet_id uuid, p_last_source_key text DEFAULT NULL::text, p_limit integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  WITH bounded AS MATERIALIZED (
    SELECT occurrence.*,
      row_number() OVER(ORDER BY occurrence.source_key) AS page_ordinal
    FROM private.pay_workbench_unit_economic_occurrence_page_v1(
      p_build_id,p_dependency_unit_key,p_fact_family,p_projected_timesheet_id,
      p_last_source_key,LEAST(GREATEST(COALESCE(p_limit,25),1),25)
    ) occurrence
    ORDER BY occurrence.source_key
  ), accepted AS MATERIALIZED (
    SELECT * FROM bounded
    WHERE page_ordinal<=LEAST(GREATEST(COALESCE(p_limit,25),1),25)
    ORDER BY source_key
  ), evidence AS (
    SELECT
      count(*) FILTER(WHERE COALESCE(source_payload_json->>'evidence_only','false')<>'true')::integer
        AS raw_page_count,
      count(*) FILTER(WHERE resolution_failure IS NULL
        AND COALESCE(source_payload_json->>'evidence_only','false')<>'true')::integer
        AS resolved_page_count,
      count(*) FILTER(WHERE resolution_failure IS NOT NULL
        AND COALESCE(source_payload_json->>'evidence_only','false')<>'true')::integer
        AS failed_page_count,
      round(COALESCE(sum(COALESCE(truth_ex_vat,amount_ex_vat,0)) FILTER(
        WHERE COALESCE(source_payload_json->>'evidence_only','false')<>'true'),0),2)
        AS raw_amount_ex_vat,
      round(COALESCE(sum(COALESCE(truth_ex_vat,amount_ex_vat,0))
        FILTER(WHERE resolution_failure IS NULL
          AND COALESCE(source_payload_json->>'evidence_only','false')<>'true'),0),2)
        AS resolved_amount_ex_vat,
      min(source_key) FILTER(WHERE COALESCE(source_payload_json->>'evidence_only','false')<>'true')
        AS first_raw_source_key,
      max(source_key) FILTER(WHERE COALESCE(source_payload_json->>'evidence_only','false')<>'true')
        AS last_raw_source_key
    FROM accepted
  )
  SELECT jsonb_build_object(
    'bundle_version',1,
    'build_id',p_build_id,
    'dependency_unit_key',p_dependency_unit_key,
    'fact_family',UPPER(BTRIM(p_fact_family)),
    'projected_timesheet_id',p_projected_timesheet_id,
    'cursor_start_source_key',p_last_source_key,
    'rows',COALESCE((SELECT jsonb_agg(to_jsonb(accepted)-'page_ordinal'
      ORDER BY accepted.source_key) FROM accepted),'[]'::jsonb),
    'raw_page_count',evidence.raw_page_count,
    'resolved_page_count',evidence.resolved_page_count,
    'failed_page_count',evidence.failed_page_count,
    'raw_amount_ex_vat',evidence.raw_amount_ex_vat,
    'resolved_amount_ex_vat',evidence.resolved_amount_ex_vat,
    'first_raw_source_key',evidence.first_raw_source_key,
    'last_raw_source_key',evidence.last_raw_source_key,
    'raw_source_has_more',(SELECT count(*)>
      LEAST(GREATEST(COALESCE(p_limit,25),1),25) FROM bounded),
    'raw_source_exhausted',(SELECT count(*)<=
      LEAST(GREATEST(COALESCE(p_limit,25),1),25) FROM bounded),
    'evidence_digest',md5(jsonb_build_object(
      'raw_page_count',evidence.raw_page_count,
      'resolved_page_count',evidence.resolved_page_count,
      'failed_page_count',evidence.failed_page_count,
      'raw_amount_ex_vat',evidence.raw_amount_ex_vat,
      'resolved_amount_ex_vat',evidence.resolved_amount_ex_vat,
      'first_raw_source_key',evidence.first_raw_source_key,
      'last_raw_source_key',evidence.last_raw_source_key,
      'raw_source_has_more',(SELECT count(*)>
        LEAST(GREATEST(COALESCE(p_limit,25),1),25) FROM bounded)
    )::text)
  )
  FROM evidence;
$function$;

-- private.pay_workbench_unit_economic_occurrence_page_v1(uuid,text,text,uuid,text,integer)
CREATE OR REPLACE FUNCTION private.pay_workbench_unit_economic_occurrence_page_v1(p_build_id uuid, p_dependency_unit_key text, p_fact_family text, p_projected_timesheet_id uuid, p_last_source_key text DEFAULT NULL::text, p_limit integer DEFAULT 25)
 RETURNS TABLE(source_key text, natural_key text, timesheet_id uuid, subject_timesheet_ids uuid[], source_relation text, source_id uuid, economic_key_type text, economic_key_value text, amount_ex_vat numeric, amount_inc_vat numeric, truth_ex_vat numeric, truth_inc_vat numeric, baseline_ex_vat numeric, baseline_inc_vat numeric, source_payload_json jsonb, financial_digest text, resolution_failure text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_limit integer:=LEAST(GREATEST(COALESCE(p_limit,25),1),25)+1;
  v_family text:=UPPER(NULLIF(BTRIM(COALESCE(p_fact_family,'')),''));
BEGIN
  IF p_build_id IS NULL OR NULLIF(BTRIM(COALESCE(p_dependency_unit_key,'')),'') IS NULL
     OR p_projected_timesheet_id IS NULL
     OR v_family NOT IN ('LIVE_ENTITLEMENT_INPUT','FROZEN_SETTLED_COMPONENT','PAY_STATE_FALLBACK') THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_BUILD_CURSOR_INVALID' USING ERRCODE='22023';
  END IF;

  IF NOT EXISTS(
    SELECT 1
    FROM private.banking_pay_workbench_economic_build_facts projection
    WHERE projection.build_id=p_build_id
      AND projection.fact_family='LIVE_ENTITLEMENT_INPUT'
      AND projection.dependency_unit_key=p_dependency_unit_key
      AND projection.source_relation='UNIT_PROJECTION'
      AND projection.timesheet_id=p_projected_timesheet_id
  ) THEN
    RAISE EXCEPTION 'PAY_WORKBENCH_UNIT_PROJECTION_INCOMPLETE' USING ERRCODE='23514';
  END IF;

  IF v_family='LIVE_ENTITLEMENT_INPUT' THEN
    RETURN QUERY
    WITH build_authority AS MATERIALIZED (
      SELECT build.*
      FROM private.banking_pay_workbench_economic_builds build
      WHERE build.id=p_build_id
    ), session_authority AS MATERIALIZED (
      SELECT build.*,session.id AS authority_session_id,
        session.version AS authority_session_version,session.pay_date,
        session.week_ending_cutoff
      FROM build_authority build
      LEFT JOIN public.banking_pay_workbench_sessions session
        ON session.id=build.session_id
    ), target_authority AS MATERIALIZED (
      SELECT authority.*,
        candidate.id AS authority_candidate_id,
        UPPER(NULLIF(BTRIM(candidate.pay_method),'')) AS target_pay_method,
        candidate.rev AS candidate_rev,candidate.updated_at AS candidate_updated_at,
        candidate.umbrella_id,
        umbrella.enabled AS umbrella_enabled,
        umbrella.vat_chargeable AS umbrella_vat_chargeable,
        umbrella.updated_at AS umbrella_updated_at
      FROM session_authority authority
      LEFT JOIN public.candidates candidate ON candidate.id=authority.candidate_id
      LEFT JOIN public.umbrellas umbrella ON umbrella.id=candidate.umbrella_id
    ), finance_window_authority AS MATERIALIZED (
      SELECT authority.*,
        finance_window.id AS finance_window_id,
        finance_window.date_from AS finance_window_date_from,
        finance_window.date_to AS finance_window_date_to,
        finance_window.erni_pct,finance_window.vat_rate_pct,
        finance_window.updated_at AS finance_window_updated_at,
        COALESCE(finance_window.winning_date_match_count,0)::integer
          AS finance_window_winning_date_match_count
      FROM target_authority authority
      LEFT JOIN LATERAL (
        SELECT matched.*,
          count(*) OVER(PARTITION BY matched.date_from) AS winning_date_match_count
        FROM public.settings_finance_windows matched
        WHERE authority.pay_date>=matched.date_from
          AND authority.pay_date<=COALESCE(matched.date_to,'infinity'::date)
        ORDER BY matched.date_from DESC,matched.id DESC
        LIMIT 1
      ) finance_window ON true
    ), projection_members AS (
      SELECT DISTINCT projection.source_id AS family_timesheet_id
      FROM private.banking_pay_workbench_economic_build_facts projection
      WHERE projection.build_id=p_build_id
        AND projection.fact_family='LIVE_ENTITLEMENT_INPUT'
        AND projection.dependency_unit_key=p_dependency_unit_key
        AND projection.source_relation='UNIT_PROJECTION'
        AND projection.timesheet_id=p_projected_timesheet_id
        AND projection.source_id IS NOT NULL
    ), canonical AS (
      SELECT ts.*,tf.id AS financial_id,tf.timesheet_version AS financial_timesheet_version,
        tf.computed_at_utc AS financial_computed_at_utc,
        tf.updated_at AS financial_updated_at,tf.candidate_id AS financial_candidate_id,
        tf.client_id AS financial_client_id,
        UPPER(NULLIF(BTRIM(tf.pay_method),'')) AS source_pay_method,
        tf.total_pay_ex_vat,tf.total_charge_ex_vat,tf.invoice_breakdown_json,
        tf.additional_units_json,tf.expenses_pay_ex_vat,tf.expenses_charge_ex_vat,
        tf.travel_pay_ex_vat,tf.travel_charge_ex_vat,
        tf.accommodation_pay_ex_vat,tf.accommodation_charge_ex_vat,
        tf.other_pay_ex_vat,tf.other_charge_ex_vat,
        tf.mileage_pay_ex_vat,tf.mileage_charge_ex_vat,
        tf.hours_day,tf.hours_night,tf.hours_sat,tf.hours_sun,tf.hours_bh,
        tf.pay_day,tf.pay_night,tf.pay_sat,tf.pay_sun,tf.pay_bh,
        tf.charge_day,tf.charge_night,tf.charge_sat,tf.charge_sun,tf.charge_bh,
        tf.current_financial_count,
        tf.worked_start_iso AS tf_worked_start_iso,
        tf.worked_end_iso AS tf_worked_end_iso,
        tf.break_start_iso AS tf_break_start_iso,
        tf.break_end_iso AS tf_break_end_iso,
        tf.break_minutes AS tf_break_minutes,
        tf.actual_schedule_json AS tf_actual_schedule_json,
        authority.candidate_id AS build_candidate_id,
        authority.session_id AS build_session_id,
        authority.session_version AS build_session_version,
        authority.captured_candidate_generation,authority.source_change_seq,
        authority.authority_fingerprint_version,authority.authority_fingerprint,
        authority.source_build_run_id,authority.source_job_id,
        authority.authority_session_id,authority.authority_session_version,
        authority.pay_date,authority.week_ending_cutoff,
        authority.authority_candidate_id,authority.target_pay_method,
        authority.candidate_rev,authority.candidate_updated_at,
        authority.umbrella_id,authority.umbrella_enabled,
        authority.umbrella_vat_chargeable,authority.umbrella_updated_at,
        authority.finance_window_id,authority.finance_window_date_from,
        authority.finance_window_date_to,authority.erni_pct,authority.vat_rate_pct,
        authority.finance_window_updated_at,
        authority.finance_window_winning_date_match_count
      FROM public.timesheets ts
      CROSS JOIN finance_window_authority authority
      LEFT JOIN LATERAL (
        SELECT current_financial.*,
          count(*) OVER()::integer AS current_financial_count
        FROM public.timesheets_financials current_financial
        WHERE current_financial.timesheet_id=ts.timesheet_id
          AND current_financial.is_current
        ORDER BY current_financial.computed_at_utc DESC NULLS LAST,
          current_financial.id DESC
        LIMIT 1
      ) tf ON true
      WHERE ts.timesheet_id=p_projected_timesheet_id
        AND ts.is_current AND ts.revoked_at IS NULL
        AND ts.archived_at_utc IS NULL AND ts.authorised_at_server IS NOT NULL
      LIMIT 1
    ), segment_rows AS (
      SELECT
        '10:'||p_projected_timesheet_id::text||':SEGMENT:'||LPAD(segment.ordinality::text,12,'0') AS source_key,
        'timesheets_financials'::text AS source_relation,
        canonical.financial_id AS source_id,
        CASE WHEN NULLIF(BTRIM(COALESCE(segment.value->>'date','')),'') ~ '^\d{4}-\d{2}-\d{2}$'
          THEN 'TS_DAY' ELSE 'TS_TOTAL' END AS raw_key_type,
        CASE WHEN NULLIF(BTRIM(COALESCE(segment.value->>'date','')),'') ~ '^\d{4}-\d{2}-\d{2}$'
          THEN BTRIM(segment.value->>'date') ELSE 'TOTAL' END AS raw_key_value,
        ROUND(CASE WHEN lower(COALESCE(NULLIF(segment.value->>'exclude_from_pay',''),'false'))='true'
          THEN 0::numeric
          WHEN COALESCE(segment.value->>'pay_amount','') ~ '^-?\d+(\.\d+)?$'
          THEN (segment.value->>'pay_amount')::numeric ELSE 0::numeric END,2) AS amount_ex_vat,
        jsonb_build_object('role','LIVE_COMPONENT','source_kind','SEGMENT',
          'projected_timesheet_id',p_projected_timesheet_id,'segment',segment.value,
          'source_ordinal',segment.ordinality) AS payload,
        CASE
          WHEN jsonb_typeof(canonical.invoice_breakdown_json)='object'
            AND UPPER(COALESCE(canonical.invoice_breakdown_json->>'mode',''))='SEGMENTS'
            AND jsonb_typeof(canonical.invoice_breakdown_json->'segments') IS DISTINCT FROM 'array'
            THEN 'SEGMENT_INPUT_NOT_ARRAY'
          WHEN jsonb_typeof(segment.value)<>'object' THEN 'SEGMENT_NOT_OBJECT'
          WHEN NULLIF(BTRIM(COALESCE(segment.value->>'segment_id','')),'') IS NULL
            THEN 'SEGMENT_ID_MISSING'
          WHEN NULLIF(segment.value->>'exclude_from_pay','') IS NOT NULL
            AND lower(segment.value->>'exclude_from_pay') NOT IN ('true','false')
            THEN 'SEGMENT_EXCLUDE_INVALID'
          WHEN lower(COALESCE(NULLIF(segment.value->>'exclude_from_pay',''),'false'))='false'
            AND COALESCE(segment.value->>'pay_amount','') !~ '^-?\d+(\.\d+)?$'
            THEN 'SEGMENT_AMOUNT_INVALID'
          WHEN NULLIF(BTRIM(COALESCE(segment.value->>'date','')),'') IS NOT NULL
            AND NOT (
              segment.value->>'date' ~ '^\d{4}-\d{2}-\d{2}$'
              AND pg_input_is_valid(segment.value->>'date','date')
              AND CASE WHEN pg_input_is_valid(segment.value->>'date','date')
                THEN ((segment.value->>'date')::date)::text=segment.value->>'date'
                ELSE false END)
            THEN 'SEGMENT_DATE_INVALID'
        END AS raw_failure
      FROM canonical
      CROSS JOIN LATERAL (
        SELECT canonical.invoice_breakdown_json->'segments'->bounded_index.zero_index AS value,
          bounded_index.zero_index+1 AS ordinality
        FROM LATERAL generate_series(
          CASE WHEN p_last_source_key LIKE '10:'||p_projected_timesheet_id::text||':SEGMENT:%'
            THEN COALESCE(NULLIF(regexp_replace(p_last_source_key,
              '^.*:SEGMENT:0*','','g'),'')::integer,0) ELSE 0 END,
          LEAST(jsonb_array_length(CASE WHEN jsonb_typeof(canonical.invoice_breakdown_json)='object'
              AND jsonb_typeof(canonical.invoice_breakdown_json->'segments')='array'
            THEN canonical.invoice_breakdown_json->'segments' ELSE '[]'::jsonb END)-1,
            CASE WHEN p_last_source_key LIKE '10:'||p_projected_timesheet_id::text||':SEGMENT:%'
              THEN COALESCE(NULLIF(regexp_replace(p_last_source_key,
                '^.*:SEGMENT:0*','','g'),'')::integer,0) ELSE 0 END + v_limit-1)
        ) bounded_index(zero_index)
        WHERE jsonb_typeof(canonical.invoice_breakdown_json)='object'
          AND UPPER(COALESCE(canonical.invoice_breakdown_json->>'mode',''))='SEGMENTS'
          AND jsonb_typeof(canonical.invoice_breakdown_json->'segments')='array'
        UNION ALL
        SELECT jsonb_build_object(
            'segment_id','ts:'||canonical.timesheet_id::text,
            'segment_key','ts:'||canonical.timesheet_id::text,
            'segment_stable_key','ts:'||canonical.timesheet_id::text,
            'hours_day',ROUND(COALESCE(canonical.hours_day,0),6),
            'hours_night',ROUND(COALESCE(canonical.hours_night,0),6),
            'hours_sat',ROUND(COALESCE(canonical.hours_sat,0),6),
            'hours_sun',ROUND(COALESCE(canonical.hours_sun,0),6),
            'hours_bh',ROUND(COALESCE(canonical.hours_bh,0),6),
            'pay_amount',ROUND(COALESCE(canonical.total_pay_ex_vat,0),2),
            'charge_amount',ROUND(COALESCE(canonical.total_charge_ex_vat,0),2),
            'exclude_from_pay',false,
            'date',CASE
              WHEN UPPER(COALESCE(canonical.sheet_scope::text,''))='DAILY'
               AND COALESCE(canonical.tf_worked_start_iso,canonical.worked_start_iso) IS NOT NULL
                THEN ((COALESCE(canonical.tf_worked_start_iso,canonical.worked_start_iso)
                  AT TIME ZONE 'Europe/London')::date)::text
              WHEN UPPER(COALESCE(canonical.sheet_scope::text,''))='DAILY' THEN COALESCE(
                NULLIF(BTRIM(COALESCE(canonical.tf_actual_schedule_json->>'date','')),''),
                NULLIF(BTRIM(COALESCE(canonical.actual_schedule_json->>'date','')),''))
              ELSE NULL END),
          1::bigint
        WHERE NOT (jsonb_typeof(canonical.invoice_breakdown_json)='object'
          AND UPPER(COALESCE(canonical.invoice_breakdown_json->>'mode',''))='SEGMENTS'
          AND jsonb_typeof(canonical.invoice_breakdown_json->'segments')='array')
      ) segment
    ), additional_rows AS (
      SELECT '10:'||p_projected_timesheet_id::text||':ADDITIONAL:'||
          LPAD(octet_length(additional.key)::text,10,'0')||':'||
          encode(convert_to(additional.key,'UTF8'),'hex') AS source_key,
        'timesheets_financials'::text AS source_relation,canonical.financial_id AS source_id,
        'ADDITIONAL_CODE'::text AS raw_key_type,UPPER(BTRIM(additional.key)) AS raw_key_value,
        ROUND(COALESCE(
          CASE WHEN COALESCE(additional.value->>'pay_ex_vat','') ~ '^-?\d+(\.\d+)?$'
            THEN (additional.value->>'pay_ex_vat')::numeric END,
          CASE WHEN COALESCE(additional.value->>'amount_ex_vat','') ~ '^-?\d+(\.\d+)?$'
            THEN (additional.value->>'amount_ex_vat')::numeric END,
          COALESCE(CASE WHEN COALESCE(additional.value->>'unit_count','') ~ '^-?\d+(\.\d+)?$'
            THEN (additional.value->>'unit_count')::numeric END,
            CASE WHEN COALESCE(additional.value->>'units_week','') ~ '^-?\d+(\.\d+)?$'
              THEN (additional.value->>'units_week')::numeric END,0)
          * COALESCE(CASE WHEN COALESCE(additional.value->>'pay_rate','') ~ '^-?\d+(\.\d+)?$'
            THEN (additional.value->>'pay_rate')::numeric END,
            CASE WHEN COALESCE(additional.value->>'rate','') ~ '^-?\d+(\.\d+)?$'
              THEN (additional.value->>'rate')::numeric END,0),0),2) AS amount_ex_vat,
        jsonb_build_object('role','LIVE_COMPONENT','source_kind','ADDITIONAL',
           'projected_timesheet_id',p_projected_timesheet_id,'raw_additional_code',additional.key,
           'additional_code',UPPER(BTRIM(additional.key)),
          'source_value',additional.value) AS payload,
        CASE
          WHEN pg_column_size(COALESCE(canonical.additional_units_json,'{}'::jsonb))>65536
            THEN 'ADDITIONAL_INPUT_EXCEEDS_ENVELOPE'
          WHEN jsonb_typeof(COALESCE(canonical.additional_units_json,'{}'::jsonb))<>'object'
            THEN 'ADDITIONAL_INPUT_NOT_OBJECT'
          WHEN NULLIF(BTRIM(additional.key),'') IS NULL THEN 'ADDITIONAL_CODE_MISSING'
          WHEN jsonb_typeof(additional.value)<>'object' THEN 'ADDITIONAL_VALUE_NOT_OBJECT'
          WHEN NULLIF(COALESCE(additional.value->>'pay_ex_vat',additional.value->>'amount_ex_vat',''),'') IS NOT NULL
            AND COALESCE(additional.value->>'pay_ex_vat',additional.value->>'amount_ex_vat','') !~ '^-?\d+(\.\d+)?$'
            THEN 'ADDITIONAL_AMOUNT_INVALID'
          WHEN EXISTS(SELECT 1 FROM unnest(ARRAY['unit_count','units_week','pay_rate','rate']) field_name
            WHERE NULLIF(additional.value->>field_name,'') IS NOT NULL
              AND additional.value->>field_name !~ '^-?\d+(\.\d+)?$')
            THEN 'ADDITIONAL_RATE_INPUT_INVALID'
        END AS raw_failure
      FROM canonical
      CROSS JOIN LATERAL (
        SELECT entry.key,entry.value
        FROM jsonb_each(CASE
          WHEN pg_column_size(COALESCE(canonical.additional_units_json,'{}'::jsonb))<=65536
           AND jsonb_typeof(COALESCE(canonical.additional_units_json,'{}'::jsonb))='object'
            THEN COALESCE(canonical.additional_units_json,'{}'::jsonb)
          ELSE '{}'::jsonb
        END) entry
        WHERE p_last_source_key IS NULL OR
          '10:'||p_projected_timesheet_id::text||':ADDITIONAL:'||
            LPAD(octet_length(entry.key)::text,10,'0')||':'||
            encode(convert_to(entry.key,'UTF8'),'hex')>p_last_source_key
        ORDER BY octet_length(entry.key),encode(convert_to(entry.key,'UTF8'),'hex') LIMIT v_limit
      ) additional
    ), additional_container_failure AS (
      SELECT '10:'||p_projected_timesheet_id::text||':ADDITIONAL:!INVALID' AS source_key,
        'timesheets_financials'::text AS source_relation,canonical.financial_id AS source_id,
        NULL::text AS raw_key_type,NULL::text AS raw_key_value,0::numeric AS amount_ex_vat,
        jsonb_build_object('role','LIVE_COMPONENT','source_kind','ADDITIONAL_CONTAINER',
          'projected_timesheet_id',p_projected_timesheet_id) AS payload,
        CASE WHEN pg_column_size(COALESCE(canonical.additional_units_json,'{}'::jsonb))>65536
          THEN 'ADDITIONAL_INPUT_EXCEEDS_ENVELOPE' ELSE 'ADDITIONAL_INPUT_NOT_OBJECT' END AS raw_failure
      FROM canonical
      WHERE (jsonb_typeof(COALESCE(canonical.additional_units_json,'{}'::jsonb))<>'object'
          OR pg_column_size(COALESCE(canonical.additional_units_json,'{}'::jsonb))>65536)
        AND (p_last_source_key IS NULL OR
          '10:'||p_projected_timesheet_id::text||':ADDITIONAL:!INVALID'>p_last_source_key)
    ), expense_source AS (
      SELECT canonical.*,
        COALESCE(canonical.travel_pay_ex_vat,0)::numeric AS travel_ex,
        COALESCE(canonical.accommodation_pay_ex_vat,0)::numeric AS accommodation_ex,
        COALESCE(canonical.other_pay_ex_vat,0)::numeric AS other_ex,
        COALESCE(canonical.mileage_pay_ex_vat,0)::numeric AS mileage_ex,
        COALESCE(canonical.expenses_pay_ex_vat,0)::numeric AS expenses_ex,
        COALESCE(canonical.travel_charge_ex_vat,0)::numeric AS travel_charge_ex,
        COALESCE(canonical.accommodation_charge_ex_vat,0)::numeric AS accommodation_charge_ex,
        COALESCE(canonical.other_charge_ex_vat,0)::numeric AS other_charge_ex,
        COALESCE(canonical.mileage_charge_ex_vat,0)::numeric AS mileage_charge_ex,
        COALESCE(canonical.expenses_charge_ex_vat,0)::numeric AS expenses_charge_ex
      FROM canonical
    ), expense_rows AS (
      SELECT '10:'||p_projected_timesheet_id::text||':EXPENSE:'||expense.key_value AS source_key,
        'timesheets_financials'::text AS source_relation,expense_source.financial_id AS source_id,
        'EXPENSE_CODE'::text AS raw_key_type,expense.key_value,ROUND(expense.amount_ex_vat,2) AS amount_ex_vat,
        jsonb_build_object('role','LIVE_COMPONENT','source_kind','EXPENSE',
          'projected_timesheet_id',p_projected_timesheet_id,'expense_code',expense.key_value,
          'source_charge_ex_vat',ROUND(expense.charge_ex_vat,2)) AS payload,
        NULL::text AS raw_failure
      FROM expense_source
      CROSS JOIN LATERAL (VALUES
        ('TRAVEL'::text,expense_source.travel_ex,expense_source.travel_charge_ex),
        ('ACCOMMODATION'::text,expense_source.accommodation_ex,expense_source.accommodation_charge_ex),
        ('OTHER'::text,expense_source.other_ex,expense_source.other_charge_ex),
        ('MILEAGE'::text,expense_source.mileage_ex,expense_source.mileage_charge_ex),
        ('EXPENSES'::text,CASE WHEN expense_source.travel_ex=0 AND expense_source.accommodation_ex=0
          AND expense_source.other_ex=0 AND expense_source.mileage_ex=0
          THEN expense_source.expenses_ex ELSE 0::numeric END,
          CASE WHEN expense_source.travel_ex=0 AND expense_source.accommodation_ex=0
            AND expense_source.other_ex=0 AND expense_source.mileage_ex=0
            THEN expense_source.expenses_charge_ex ELSE 0::numeric END)
      ) expense(key_value,amount_ex_vat,charge_ex_vat)
      WHERE ROUND(COALESCE(expense.amount_ex_vat,0),2)<>0
    ), adjustment_rows AS (
      SELECT '10:'||p_projected_timesheet_id::text||':ADJUSTMENT:'||adjustment.id::text AS source_key,
        'ts_pay_adjustments'::text AS source_relation,adjustment.id AS source_id,
        'ADJUSTMENT_CODE'::text AS raw_key_type,adjustment.id::text AS raw_key_value,
        ROUND(COALESCE(adjustment.delta_pay_ex_vat,0),2) AS amount_ex_vat,
        jsonb_build_object('role','LIVE_COMPONENT','source_kind','ADJUSTMENT',
          'projected_timesheet_id',p_projected_timesheet_id,'family_timesheet_id',adjustment.timesheet_id,
          'adjustment_id',adjustment.id) AS payload,
        NULL::text AS raw_failure
      FROM projection_members member
      JOIN public.ts_pay_adjustments adjustment ON adjustment.timesheet_id=member.family_timesheet_id
      WHERE adjustment.as_advance IS FALSE AND adjustment.id IS NOT NULL
        AND ROUND(COALESCE(adjustment.delta_pay_ex_vat,0),2)<>0
        AND (p_last_source_key IS NULL OR
          '10:'||p_projected_timesheet_id::text||':ADJUSTMENT:'||adjustment.id::text>p_last_source_key)
      ORDER BY adjustment.id LIMIT v_limit
    ), raw_rows AS (
      SELECT * FROM segment_rows
      UNION ALL SELECT additional.* FROM additional_rows additional
        WHERE additional.amount_ex_vat<>0 OR additional.raw_failure IS NOT NULL
      UNION ALL SELECT * FROM additional_container_failure
      UNION ALL SELECT * FROM expense_rows
      UNION ALL SELECT * FROM adjustment_rows
    ), paged_raw_rows AS MATERIALIZED (
      SELECT raw.* FROM raw_rows raw
      WHERE p_last_source_key IS NULL OR raw.source_key>p_last_source_key
      ORDER BY raw.source_key
      -- One extra parent beyond the row look-ahead is required because the
      -- resume cursor can point inside the final component of the prior item.
      -- Without it, a 25-row page can falsely report source exhaustion at an
      -- item boundary (for example, exactly 50 or 51 physical occurrences).
      LIMIT v_limit+1
    ), resolved AS (
      SELECT raw.*,
        resolved_key.key_type,resolved_key.key_value,
        resolved_key.key_resolution_source,resolved_key.key_resolution_failure_reason
      FROM paged_raw_rows raw
      LEFT JOIN LATERAL public._pay_policy_x_resolve_pre_draft_economic_key(
        p_timesheet_id=>p_projected_timesheet_id,
        p_live_source_json=>raw.payload||jsonb_build_object(
          'timesheet_id',p_projected_timesheet_id,'component_key_type',raw.raw_key_type,
          'component_key_value',raw.raw_key_value),
        p_item_type=>CASE raw.raw_key_type WHEN 'TS_DAY' THEN 'SEGMENT_DELTA'
          WHEN 'TS_TOTAL' THEN 'SEGMENT_DELTA' WHEN 'ADJUSTMENT_CODE' THEN 'ADJUSTMENT_DELTA'
          WHEN 'ADDITIONAL_CODE' THEN 'EXPENSE_DELTA' WHEN 'EXPENSE_CODE' THEN
            CASE WHEN raw.raw_key_value='MILEAGE' THEN 'MILEAGE_DELTA' ELSE 'EXPENSE_DELTA' END END,
        p_key_type_hint=>raw.raw_key_type,p_key_value_hint=>raw.raw_key_value,
        p_work_date=>NULL::date
      ) resolved_key ON raw.raw_failure IS NULL
    ), rate_inputs AS MATERIALIZED (
      SELECT resolved.*,canonical.*,
        CASE resolved.payload->>'source_kind'
          WHEN 'SEGMENT' THEN 'WORKED_TIME'
          WHEN 'ADDITIONAL' THEN 'ADDITIONAL_UNIT'
          WHEN 'EXPENSE' THEN 'EXPENSE'
          WHEN 'ADJUSTMENT' THEN 'ADJUSTMENT'
          ELSE 'UNKNOWN'
        END AS component_kind,
        COALESCE(
          NULLIF(BTRIM(resolved.payload#>>'{segment,segment_stable_key}'),''),
          NULLIF(BTRIM(resolved.payload#>>'{segment,segment_id}'),''),
          NULLIF(BTRIM(resolved.payload#>>'{segment,segment_key}'),''),
          NULLIF(BTRIM(resolved.payload#>>'{segment,date}'),''),
          NULLIF(BTRIM(resolved.payload#>>'{segment,ref_num}'),''),
          'segment-fallback:'||md5(jsonb_build_object(
            'timesheet_id',p_projected_timesheet_id::text,
            'source_kind',resolved.payload->>'source_kind',
            'source_ordinal',resolved.payload->'source_ordinal',
            'date',NULLIF(BTRIM(resolved.payload#>>'{segment,date}'),''),
            'start_utc',NULLIF(BTRIM(resolved.payload#>>'{segment,start_utc}'),''),
            'end_utc',NULLIF(BTRIM(resolved.payload#>>'{segment,end_utc}'),''),
            'start',NULLIF(BTRIM(resolved.payload#>>'{segment,start}'),''),
            'end',NULLIF(BTRIM(resolved.payload#>>'{segment,end}'),''),
            'ref_num',NULLIF(BTRIM(resolved.payload#>>'{segment,ref_num}'),''),
            'shift_id',COALESCE(NULLIF(BTRIM(resolved.payload#>>'{segment,shift_id}'),''),
              NULLIF(BTRIM(resolved.payload#>>'{segment,nhsp_shift_id}'),'')),
            'request_id',COALESCE(NULLIF(BTRIM(resolved.payload#>>'{segment,request_id}'),''),
              NULLIF(BTRIM(resolved.payload#>>'{segment,hr_request_id}'),'')),
            'external_row_key',NULLIF(BTRIM(resolved.payload#>>'{segment,external_row_key}'),''),
            'latest_import_id',NULLIF(BTRIM(resolved.payload#>>'{segment,latest_import_id}'),'')
          )::text)
        ) AS segment_stable_key,
        CASE resolved.payload->>'source_kind'
          WHEN 'SEGMENT' THEN COALESCE(
            NULLIF(BTRIM(resolved.payload#>>'{segment,segment_stable_key}'),''),
            NULLIF(BTRIM(resolved.payload#>>'{segment,segment_id}'),''),
            NULLIF(BTRIM(resolved.payload#>>'{segment,segment_key}'),''),
            NULLIF(BTRIM(resolved.payload#>>'{segment,date}'),''),
            NULLIF(BTRIM(resolved.payload#>>'{segment,ref_num}'),''),
            'segment-fallback:'||md5(jsonb_build_object(
              'timesheet_id',p_projected_timesheet_id::text,
              'source_kind',resolved.payload->>'source_kind',
              'source_ordinal',resolved.payload->'source_ordinal',
              'date',NULLIF(BTRIM(resolved.payload#>>'{segment,date}'),''),
              'start_utc',NULLIF(BTRIM(resolved.payload#>>'{segment,start_utc}'),''),
              'end_utc',NULLIF(BTRIM(resolved.payload#>>'{segment,end_utc}'),''),
              'start',NULLIF(BTRIM(resolved.payload#>>'{segment,start}'),''),
              'end',NULLIF(BTRIM(resolved.payload#>>'{segment,end}'),''),
              'ref_num',NULLIF(BTRIM(resolved.payload#>>'{segment,ref_num}'),''),
              'shift_id',COALESCE(NULLIF(BTRIM(resolved.payload#>>'{segment,shift_id}'),''),
                NULLIF(BTRIM(resolved.payload#>>'{segment,nhsp_shift_id}'),'')),
              'request_id',COALESCE(NULLIF(BTRIM(resolved.payload#>>'{segment,request_id}'),''),
                NULLIF(BTRIM(resolved.payload#>>'{segment,hr_request_id}'),'')),
              'external_row_key',NULLIF(BTRIM(resolved.payload#>>'{segment,external_row_key}'),''),
              'latest_import_id',NULLIF(BTRIM(resolved.payload#>>'{segment,latest_import_id}'),'')
            )::text)
          )
          WHEN 'ADDITIONAL' THEN 'additional:'||UPPER(BTRIM(resolved.payload->>'additional_code'))
          WHEN 'EXPENSE' THEN 'expense:'||UPPER(BTRIM(resolved.payload->>'expense_code'))
          WHEN 'ADJUSTMENT' THEN 'adjustment:'||BTRIM(resolved.payload->>'adjustment_id')
        END AS component_member_identity,
        CASE resolved.payload->>'source_kind'
          WHEN 'SEGMENT' THEN ROUND(COALESCE(
            CASE WHEN COALESCE(resolved.payload#>>'{segment,charge_amount}','') ~ '^-?\d+(\.\d+)?$'
              THEN (resolved.payload#>>'{segment,charge_amount}')::numeric END,
            CASE WHEN COALESCE(resolved.payload#>>'{segment,charge_ex_vat}','') ~ '^-?\d+(\.\d+)?$'
              THEN (resolved.payload#>>'{segment,charge_ex_vat}')::numeric END),2)
          WHEN 'ADDITIONAL' THEN ROUND(COALESCE(
            CASE WHEN COALESCE(resolved.payload#>>'{source_value,charge_ex_vat}','') ~ '^-?\d+(\.\d+)?$'
              THEN (resolved.payload#>>'{source_value,charge_ex_vat}')::numeric END,
            CASE WHEN COALESCE(resolved.payload#>>'{source_value,charge_amount_ex_vat}','') ~ '^-?\d+(\.\d+)?$'
              THEN (resolved.payload#>>'{source_value,charge_amount_ex_vat}')::numeric END),2)
          WHEN 'EXPENSE' THEN ROUND(CASE WHEN COALESCE(resolved.payload->>'source_charge_ex_vat','')
              ~ '^-?\d+(\.\d+)?$' THEN (resolved.payload->>'source_charge_ex_vat')::numeric END,2)
        END AS parent_source_charge_ex_vat,
        md5(jsonb_build_object(
          'financial_revision_version',1,'timesheet_id',p_projected_timesheet_id::text,
          'timesheet_version',canonical.version,
          'timesheet_updated_at_utc',to_char(canonical.updated_at AT TIME ZONE 'UTC',
            'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
          'financial_row_id',canonical.financial_id::text,
          'financial_timesheet_version',canonical.financial_timesheet_version,
          'financial_computed_at_utc',to_char(canonical.financial_computed_at_utc AT TIME ZONE 'UTC',
            'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
          'financial_updated_at_utc',to_char(canonical.financial_updated_at AT TIME ZONE 'UTC',
            'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
          'financial_is_current',canonical.current_financial_count=1,
          'source_pay_method',canonical.source_pay_method)::text) AS financial_revision_digest,
        md5(jsonb_build_object(
          'target_authority_version',1,'candidate_id',canonical.authority_candidate_id::text,
          'target_pay_method',canonical.target_pay_method,'candidate_rev',canonical.candidate_rev,
          'candidate_updated_at_utc',to_char(canonical.candidate_updated_at AT TIME ZONE 'UTC',
            'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
          'umbrella_id',canonical.umbrella_id::text,
          'umbrella_enabled',canonical.umbrella_enabled,
          'umbrella_vat_chargeable',canonical.umbrella_vat_chargeable,
          'umbrella_updated_at_utc',to_char(canonical.umbrella_updated_at AT TIME ZONE 'UTC',
            'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))::text) AS target_authority_digest,
        md5(jsonb_build_object(
          'conversion_context_version',1,'pay_date',canonical.pay_date::text,
          'finance_window_id',canonical.finance_window_id::text,
          'date_from',canonical.finance_window_date_from::text,
          'date_to',canonical.finance_window_date_to::text,
          'erni_pct',ROUND(canonical.erni_pct,6),'vat_rate_pct',ROUND(canonical.vat_rate_pct,6),
          'finance_window_updated_at_utc',to_char(canonical.finance_window_updated_at AT TIME ZONE 'UTC',
            'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
          'target_pay_method',canonical.target_pay_method,
          'umbrella_vat_chargeable',canonical.umbrella_vat_chargeable)::text)
          AS conversion_context_digest
      FROM resolved CROSS JOIN canonical
    ), physical_rows AS MATERIALIZED (
      SELECT input.source_key,input.component_kind,input.component_member_identity,
        NULLIF(BTRIM(input.payload#>>'{segment,segment_id}'),'') AS segment_id,
        COALESCE(
          NULLIF(BTRIM(input.payload#>>'{segment,segment_key}'),''),
          NULLIF(BTRIM(input.payload#>>'{segment,segment_id}'),'')
        ) AS segment_key,
        CASE WHEN input.component_kind='WORKED_TIME' THEN input.segment_stable_key END
          AS segment_stable_key,
        NULLIF(BTRIM(input.payload#>>'{segment,date}'),'') AS work_date,
        NULLIF(BTRIM(input.payload#>>'{segment,ref_num}'),'') AS ref_num,
        CASE WHEN input.component_kind='ADDITIONAL_UNIT'
          THEN UPPER(NULLIF(BTRIM(input.payload->>'additional_code'),'')) END AS additional_code,
        CASE WHEN input.component_kind='EXPENSE'
          THEN UPPER(NULLIF(BTRIM(input.payload->>'expense_code'),'')) END AS expense_code,
        CASE WHEN input.component_kind='ADJUSTMENT'
          THEN NULLIF(BTRIM(input.payload->>'adjustment_id'),'') END AS adjustment_id,
        bucket.bucket_code,bucket.bucket_sort_ordinal,
        CASE WHEN bucket.source_units IS NULL THEN NULL ELSE ROUND(bucket.source_units,6) END
          AS source_units,
        CASE WHEN bucket.source_rate IS NULL THEN NULL ELSE ROUND(bucket.source_rate,6) END
          AS source_rate,
        CASE WHEN bucket.source_charge_rate IS NULL THEN NULL
          ELSE ROUND(bucket.source_charge_rate,6) END AS source_charge_rate,
        ROUND(bucket.source_pay_ex_vat,2) AS source_pay_ex_vat,
        CASE WHEN bucket.source_charge_ex_vat IS NULL THEN NULL
          ELSE ROUND(bucket.source_charge_ex_vat,2) END AS source_charge_ex_vat,
        bucket.is_rate_bearing
      FROM rate_inputs input
      CROSS JOIN LATERAL (
        SELECT worked.bucket_code,worked.bucket_sort_ordinal,worked.source_units,
          worked.source_rate,worked.source_charge_rate,
          worked.source_units*worked.source_rate AS source_pay_ex_vat,
          worked.source_units*worked.source_charge_rate AS source_charge_ex_vat,true AS is_rate_bearing
        FROM (VALUES
          ('DAY'::text,1,
            CASE WHEN COALESCE(input.payload#>>'{segment,hours_day}','') ~ '^-?\d+(\.\d+)?$'
              THEN (input.payload#>>'{segment,hours_day}')::numeric END,input.pay_day,input.charge_day),
          ('NIGHT'::text,2,
            CASE WHEN COALESCE(input.payload#>>'{segment,hours_night}','') ~ '^-?\d+(\.\d+)?$'
              THEN (input.payload#>>'{segment,hours_night}')::numeric END,input.pay_night,input.charge_night),
          ('SAT'::text,3,
            CASE WHEN COALESCE(input.payload#>>'{segment,hours_sat}','') ~ '^-?\d+(\.\d+)?$'
              THEN (input.payload#>>'{segment,hours_sat}')::numeric END,input.pay_sat,input.charge_sat),
          ('SUN'::text,4,
            CASE WHEN COALESCE(input.payload#>>'{segment,hours_sun}','') ~ '^-?\d+(\.\d+)?$'
              THEN (input.payload#>>'{segment,hours_sun}')::numeric END,input.pay_sun,input.charge_sun),
          ('BH'::text,5,
            CASE WHEN COALESCE(input.payload#>>'{segment,hours_bh}','') ~ '^-?\d+(\.\d+)?$'
              THEN (input.payload#>>'{segment,hours_bh}')::numeric END,input.pay_bh,input.charge_bh)
        ) worked(bucket_code,bucket_sort_ordinal,source_units,source_rate,source_charge_rate)
        WHERE input.component_kind='WORKED_TIME' AND COALESCE(worked.source_units,0)<>0
        UNION ALL
        SELECT 'ADDITIONAL',6,
          COALESCE(
            CASE WHEN COALESCE(input.payload#>>'{source_value,unit_count}','') ~ '^-?\d+(\.\d+)?$'
              THEN (input.payload#>>'{source_value,unit_count}')::numeric END,
            CASE WHEN COALESCE(input.payload#>>'{source_value,units_week}','') ~ '^-?\d+(\.\d+)?$'
              THEN (input.payload#>>'{source_value,units_week}')::numeric END),
          COALESCE(
            CASE WHEN COALESCE(input.payload#>>'{source_value,pay_rate}','') ~ '^-?\d+(\.\d+)?$'
              THEN (input.payload#>>'{source_value,pay_rate}')::numeric END,
            CASE WHEN COALESCE(input.payload#>>'{source_value,rate}','') ~ '^-?\d+(\.\d+)?$'
              THEN (input.payload#>>'{source_value,rate}')::numeric END),
          CASE WHEN COALESCE(input.payload#>>'{source_value,charge_rate}','') ~ '^-?\d+(\.\d+)?$'
            THEN (input.payload#>>'{source_value,charge_rate}')::numeric END,
          input.amount_ex_vat,input.parent_source_charge_ex_vat,true
        WHERE input.component_kind='ADDITIONAL_UNIT'
        UNION ALL
        SELECT 'FIXED',7,NULL::numeric,NULL::numeric,NULL::numeric,
          input.amount_ex_vat,input.parent_source_charge_ex_vat,false
        WHERE input.component_kind IN ('EXPENSE','ADJUSTMENT')
      ) bucket
    ), physical_keyed AS MATERIALIZED (
      SELECT physical.*,
        concat_ws('|','RATE_BUCKET_V1',p_projected_timesheet_id::text,
          'timesheet:'||p_projected_timesheet_id::text,input.key_type,input.key_value,
          physical.component_member_identity,physical.bucket_code) AS physical_bucket_key,
        md5(jsonb_build_object(
          'builder_comparison_version',1,'timesheet_id',p_projected_timesheet_id::text,
          'source_family_key','timesheet:'||p_projected_timesheet_id::text,
          'component_key_type',UPPER(BTRIM(input.key_type)),
          'component_key_value',BTRIM(input.key_value),
          'segment_id',physical.segment_id,'segment_key',physical.segment_key,
          'segment_stable_key',physical.segment_stable_key,'work_date',physical.work_date,
          'ref_num',physical.ref_num,'additional_code',physical.additional_code,
          'expense_code',physical.expense_code,'adjustment_id',physical.adjustment_id,
          'bucket_code',physical.bucket_code,'source_units',physical.source_units,
          'source_rate',physical.source_rate,'source_charge_rate',physical.source_charge_rate,
          'source_pay_ex_vat',physical.source_pay_ex_vat,
          'source_charge_ex_vat',physical.source_charge_ex_vat,
          'source_pay_method',input.source_pay_method,
          'target_pay_method',input.target_pay_method)::text) AS builder_comparison_digest
      FROM physical_rows physical
      JOIN rate_inputs input USING(source_key)
    ), physical_digested AS MATERIALIZED (
      SELECT keyed.*,
        jsonb_build_object(
          'physical_bucket_version',1,'physical_bucket_key',keyed.physical_bucket_key,
          'component_kind',keyed.component_kind,
          'component_member_identity',keyed.component_member_identity,
          'bucket_code',keyed.bucket_code,'source_units',keyed.source_units,
          'source_rate',keyed.source_rate,'source_charge_rate',keyed.source_charge_rate,
          'source_pay_ex_vat',keyed.source_pay_ex_vat,
          'source_charge_ex_vat',keyed.source_charge_ex_vat,
          -- Baseline and reservation are separate sealed finance authority.
          -- They are attributed to this physical source only after all build
          -- fact families have been persisted; do not invent a live zero here.
          'baseline_source_pay_ex_vat',NULL::numeric,
          'reserved_source_pay_ex_vat',NULL::numeric,
          'outstanding_source_pay_ex_vat',NULL::numeric,
          'source_pay_method',input.source_pay_method,
          'target_pay_method',input.target_pay_method) AS physical_canonical_json
      FROM physical_keyed keyed JOIN rate_inputs input USING(source_key)
    ), rate_documents_pre AS MATERIALIZED (
      SELECT input.*,bucket.physical_buckets,bucket.physical_bucket_digest,
        bucket.physical_pay_total,bucket.physical_charge_total,
        CASE
          WHEN input.authority_session_id IS NULL THEN 'RATE_AUTHORITY_SESSION_NOT_FOUND'
          WHEN input.authority_session_version IS DISTINCT FROM input.build_session_version
            THEN 'RATE_AUTHORITY_SESSION_VERSION_MISMATCH'
          WHEN input.authority_candidate_id IS NULL THEN 'RATE_AUTHORITY_CANDIDATE_NOT_FOUND'
          WHEN input.financial_candidate_id IS DISTINCT FROM input.build_candidate_id
            THEN 'RATE_AUTHORITY_CANDIDATE_MISMATCH'
          WHEN COALESCE(input.current_financial_count,0)=0
            THEN 'RATE_AUTHORITY_FINANCIAL_ROW_NOT_FOUND'
          WHEN input.current_financial_count<>1 THEN 'RATE_AUTHORITY_FINANCIAL_ROW_AMBIGUOUS'
          WHEN input.financial_timesheet_version IS DISTINCT FROM input.version
            THEN 'RATE_AUTHORITY_FINANCIAL_VERSION_MISMATCH'
          WHEN input.source_pay_method IS NULL
            OR input.source_pay_method NOT IN ('PAYE','UMBRELLA')
            THEN 'RATE_AUTHORITY_SOURCE_PAY_METHOD_MISSING'
          WHEN input.target_pay_method IS NULL
            OR input.target_pay_method NOT IN ('PAYE','UMBRELLA')
            THEN 'RATE_AUTHORITY_TARGET_PAY_METHOD_MISSING'
          WHEN input.target_pay_method='UMBRELLA' AND input.umbrella_id IS NULL
            THEN 'RATE_AUTHORITY_UMBRELLA_REQUIRED'
          WHEN input.target_pay_method='UMBRELLA' AND input.umbrella_enabled IS NULL
            THEN 'RATE_AUTHORITY_UMBRELLA_NOT_FOUND'
          WHEN input.target_pay_method='UMBRELLA' AND input.umbrella_enabled IS DISTINCT FROM true
            THEN 'RATE_AUTHORITY_UMBRELLA_DISABLED'
          WHEN input.finance_window_id IS NULL THEN 'RATE_AUTHORITY_FINANCE_WINDOW_NOT_FOUND'
          WHEN input.finance_window_winning_date_match_count<>1
            THEN 'RATE_AUTHORITY_FINANCE_WINDOW_AMBIGUOUS'
          WHEN input.component_kind IN ('WORKED_TIME','ADDITIONAL_UNIT')
            AND input.source_pay_method IS DISTINCT FROM input.target_pay_method
            AND NOT EXISTS(SELECT 1 FROM physical_digested p
              WHERE p.source_key=input.source_key AND COALESCE(p.source_units,0)<>0)
            THEN 'RATE_AUTHORITY_UNITS_INVALID'
          WHEN input.component_kind IN ('WORKED_TIME','ADDITIONAL_UNIT')
            AND input.source_pay_method IS DISTINCT FROM input.target_pay_method
            AND EXISTS(SELECT 1 FROM physical_digested p
              WHERE p.source_key=input.source_key AND p.source_rate IS NULL)
            THEN 'RATE_AUTHORITY_SOURCE_PAY_RATE_MISSING'
          WHEN input.component_kind IN ('WORKED_TIME','ADDITIONAL_UNIT')
            AND input.source_pay_method IS DISTINCT FROM input.target_pay_method
            AND EXISTS(SELECT 1 FROM physical_digested p
              WHERE p.source_key=input.source_key AND p.source_charge_rate IS NULL)
            THEN 'RATE_AUTHORITY_SOURCE_CHARGE_RATE_MISSING'
          WHEN input.component_kind IN ('WORKED_TIME','ADDITIONAL_UNIT')
            AND ROUND(COALESCE(bucket.physical_pay_total,0),2)
              IS DISTINCT FROM ROUND(COALESCE(input.amount_ex_vat,0),2)
            THEN 'RATE_AUTHORITY_PARENT_PAY_MISMATCH'
          WHEN input.component_kind IN ('WORKED_TIME','ADDITIONAL_UNIT')
            AND input.parent_source_charge_ex_vat IS NOT NULL
            AND ROUND(COALESCE(bucket.physical_charge_total,0),2)
              IS DISTINCT FROM ROUND(input.parent_source_charge_ex_vat,2)
            THEN 'RATE_AUTHORITY_PARENT_CHARGE_MISMATCH'
        END AS rate_authority_failure_code
      FROM rate_inputs input
      LEFT JOIN LATERAL (
        SELECT COALESCE(jsonb_agg(
            jsonb_build_object(
              'physical_bucket_key',physical.physical_bucket_key,
              'component_kind',physical.component_kind,
              'component_member_identity',physical.component_member_identity,
              'segment_id',physical.segment_id,'segment_key',physical.segment_key,
              'segment_stable_key',physical.segment_stable_key,'work_date',physical.work_date,
              'ref_num',physical.ref_num,'additional_code',physical.additional_code,
              'expense_code',physical.expense_code,'adjustment_id',physical.adjustment_id,
              'bucket_code',physical.bucket_code,
              'bucket_sort_ordinal',physical.bucket_sort_ordinal,
              'source_units',physical.source_units,'source_rate',physical.source_rate,
              'source_charge_rate',physical.source_charge_rate,
              'source_pay_ex_vat',physical.source_pay_ex_vat,
              'source_charge_ex_vat',physical.source_charge_ex_vat,
              'baseline_source_pay_ex_vat',NULL::numeric,
              'reserved_source_pay_ex_vat',NULL::numeric,
              'outstanding_source_pay_ex_vat',NULL::numeric,
              'is_rate_bearing',physical.is_rate_bearing,
              'is_actionable_candidate',physical.is_rate_bearing
                AND input.source_pay_method IS DISTINCT FROM input.target_pay_method,
              'builder_comparison_digest',physical.builder_comparison_digest,
              'physical_bucket_digest',md5(physical.physical_canonical_json::text))
            ORDER BY physical.bucket_sort_ordinal,physical.physical_bucket_key),'[]'::jsonb)
            AS physical_buckets,
          md5(COALESCE(jsonb_agg(physical.physical_canonical_json
            ORDER BY physical.bucket_sort_ordinal,physical.physical_bucket_key)::text,'[]'))
            AS physical_bucket_digest,
          ROUND(COALESCE(SUM(physical.source_pay_ex_vat),0),2) AS physical_pay_total,
          ROUND(COALESCE(SUM(COALESCE(physical.source_charge_ex_vat,0)),0),2)
            AS physical_charge_total
        FROM physical_digested physical WHERE physical.source_key=input.source_key
      ) bucket ON true
    ), rate_documents AS MATERIALIZED (
      SELECT prepared.*,
        md5(jsonb_build_object(
          'sealed_evidence_version',1,
          'financial_revision_digest',prepared.financial_revision_digest,
          'target_authority_digest',prepared.target_authority_digest,
          'conversion_context_digest',prepared.conversion_context_digest,
          'physical_bucket_digest',prepared.physical_bucket_digest,
          'economic_key_type',prepared.key_type,'economic_key_value',prepared.key_value,
          'parent_source_pay_ex_vat',ROUND(prepared.amount_ex_vat,2),
          'parent_source_charge_ex_vat',ROUND(prepared.parent_source_charge_ex_vat,2),
          'source_pay_method',prepared.source_pay_method,
          'target_pay_method',prepared.target_pay_method)::text) AS sealed_evidence_digest
      FROM rate_documents_pre prepared
    ), completed AS MATERIALIZED (
      SELECT document.*,
        COALESCE(document.raw_failure,document.key_resolution_failure_reason,
          CASE WHEN document.key_type IS NULL OR document.key_value IS NULL
            THEN 'ECONOMIC_KEY_MISSING' END,
          document.rate_authority_failure_code) AS final_resolution_failure,
        jsonb_build_object(
          'rate_authority_version',1,
          'authority_state',CASE
            WHEN document.rate_authority_failure_code IS NOT NULL THEN 'FAILED'
            WHEN document.component_kind IN ('EXPENSE','ADJUSTMENT')
              OR document.source_pay_method IS NOT DISTINCT FROM document.target_pay_method
              THEN 'FIXED_NO_RATE' ELSE 'COMPLETE' END,
          'failure_code',document.rate_authority_failure_code,
          'failure_detail',CASE WHEN document.rate_authority_failure_code IS NULL THEN NULL
            ELSE jsonb_build_object('code',document.rate_authority_failure_code,
              'timesheet_id',p_projected_timesheet_id::text,'source_key',document.source_key) END,
          'sealed_evidence_digest',document.sealed_evidence_digest,
          'build',jsonb_build_object(
            'build_id',p_build_id::text,'candidate_id',document.build_candidate_id::text,
            'session_id',document.build_session_id::text,
            'session_version',document.build_session_version,
            'captured_candidate_generation',document.captured_candidate_generation,
            'source_change_seq',document.source_change_seq,
            'authority_fingerprint_version',document.authority_fingerprint_version,
            'authority_fingerprint',document.authority_fingerprint,
            'pay_date',document.pay_date::text,
            'week_ending_cutoff',document.week_ending_cutoff::text),
          'source',jsonb_build_object(
            'timesheet_id',p_projected_timesheet_id::text,
            'timesheet_version',document.version,
            'timesheet_updated_at_utc',to_char(document.updated_at AT TIME ZONE 'UTC',
              'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
            'financial_row_id',document.financial_id::text,
            'financial_timesheet_version',document.financial_timesheet_version,
            'financial_computed_at_utc',to_char(document.financial_computed_at_utc AT TIME ZONE 'UTC',
              'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
            'financial_updated_at_utc',to_char(document.financial_updated_at AT TIME ZONE 'UTC',
              'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
            'candidate_id',document.financial_candidate_id::text,
            'client_id',document.financial_client_id::text,
            'contract_id',document.contract_id::text,
            'booking_id',NULLIF(BTRIM(document.booking_id),''),
            'source_pay_method',document.source_pay_method,
            'financial_revision_digest',document.financial_revision_digest),
          'target',jsonb_build_object(
            'candidate_id',document.authority_candidate_id::text,
            'target_pay_method',document.target_pay_method,
            'candidate_rev',document.candidate_rev,
            'candidate_updated_at_utc',to_char(document.candidate_updated_at AT TIME ZONE 'UTC',
              'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
            'umbrella_id',document.umbrella_id::text,
            'umbrella_enabled',document.umbrella_enabled,
            'umbrella_vat_chargeable',document.umbrella_vat_chargeable,
            'umbrella_updated_at_utc',to_char(document.umbrella_updated_at AT TIME ZONE 'UTC',
              'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
            'target_authority_digest',document.target_authority_digest),
          'conversion',jsonb_build_object(
            'finance_window_id',document.finance_window_id::text,
            'date_from',document.finance_window_date_from::text,
            'date_to',document.finance_window_date_to::text,
            'erni_pct',ROUND(document.erni_pct,6),'vat_rate_pct',ROUND(document.vat_rate_pct,6),
            'finance_window_updated_at_utc',to_char(document.finance_window_updated_at AT TIME ZONE 'UTC',
              'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
            'conversion_context_digest',document.conversion_context_digest),
          'economic',jsonb_build_object(
            'source_family_key','timesheet:'||p_projected_timesheet_id::text,
            'economic_key_type',document.key_type,'economic_key_value',document.key_value,
            'component_kind',document.component_kind,
            'parent_source_pay_ex_vat',ROUND(document.amount_ex_vat,2),
            'parent_source_charge_ex_vat',ROUND(document.parent_source_charge_ex_vat,2),
            'truth_ex_vat',ROUND(document.amount_ex_vat,2),'baseline_ex_vat',NULL::numeric,
            'reserved_ex_vat',NULL::numeric,'outstanding_ex_vat',NULL::numeric,
            'physical_bucket_digest',document.physical_bucket_digest),
          'physical_buckets',document.physical_buckets,
          'lineage',jsonb_build_object(
            'source_kind',document.payload->>'source_kind',
            'source_ordinal',document.payload->'source_ordinal',
            'booking_id',NULLIF(BTRIM(document.booking_id),''),
            'source_system',document.payload#>>'{segment,source_system}',
            'shift_id',COALESCE(document.payload#>>'{segment,shift_id}',
              document.payload#>>'{segment,nhsp_shift_id}'),
            'request_id',COALESCE(document.payload#>>'{segment,request_id}',
              document.payload#>>'{segment,hr_request_id}'),
            'external_row_key',document.payload#>>'{segment,external_row_key}',
            'latest_import_id',document.payload#>>'{segment,latest_import_id}',
            'correction_root_id',document.payload#>>'{segment,correction_root_id}',
            'correction_member_id',document.payload#>>'{segment,correction_member_id}',
            'parent_timesheet_id',document.parent_timesheet_id::text,
            'build_id',p_build_id::text,
            'source_build_run_id',document.source_build_run_id::text,
            'source_job_id',document.source_job_id::text)
        ) AS rate_authority_json
      FROM rate_documents document
    )
    SELECT completed.source_key,md5('LIVE:'||completed.source_key),p_projected_timesheet_id,
      ARRAY[p_projected_timesheet_id],completed.source_relation,completed.source_id,
      completed.key_type,completed.key_value,NULL::numeric,NULL::numeric,
      completed.amount_ex_vat,completed.amount_ex_vat,NULL::numeric,NULL::numeric,
      completed.payload||jsonb_build_object('source_key',completed.source_key,
        'raw_key_type',completed.raw_key_type,'raw_key_value',completed.raw_key_value,
        'key_resolution_source',completed.key_resolution_source,
        'resolution_failure',completed.final_resolution_failure,
        'rate_authority',completed.rate_authority_json),
      md5(jsonb_build_object('financial_digest_version',2,
        'source_key',completed.source_key,'timesheet_id',p_projected_timesheet_id::text,
        'economic_key_type',completed.key_type,'economic_key_value',completed.key_value,
        'truth_ex_vat',ROUND(completed.amount_ex_vat,2),
        'truth_inc_vat',ROUND(completed.amount_ex_vat,2),
        'baseline_ex_vat',0::numeric,'baseline_inc_vat',0::numeric,
        'financial_revision_digest',completed.financial_revision_digest,
        'target_authority_digest',completed.target_authority_digest,
        'conversion_context_digest',completed.conversion_context_digest,
        'physical_bucket_digest',completed.physical_bucket_digest,
        'resolution_failure',completed.final_resolution_failure)::text),
      completed.final_resolution_failure
    FROM completed
    WHERE p_last_source_key IS NULL OR completed.source_key>p_last_source_key
    ORDER BY completed.source_key
    LIMIT v_limit;
    RETURN;
  END IF;

  IF v_family='FROZEN_SETTLED_COMPONENT' THEN
    RETURN QUERY
    WITH projection_members AS (
      SELECT DISTINCT projection.source_id AS family_timesheet_id
      FROM private.banking_pay_workbench_economic_build_facts projection
      WHERE projection.build_id=p_build_id AND projection.fact_family='LIVE_ENTITLEMENT_INPUT'
        AND projection.dependency_unit_key=p_dependency_unit_key
        AND projection.source_relation='UNIT_PROJECTION'
        AND projection.timesheet_id=p_projected_timesheet_id
        AND projection.source_id IS NOT NULL
    ), standard_items AS (
      SELECT item.id,item.timesheet_id,item.item_type,to_jsonb(item) AS payload
      FROM projection_members member
      JOIN public.pay_batch_items item ON item.timesheet_id=member.family_timesheet_id
      JOIN public.pay_batch_candidates candidate ON candidate.id=item.pay_batch_candidate_id
      LEFT JOIN public.pay_bank_transfers transfer ON transfer.id=item.pay_bank_transfer_id
      WHERE COALESCE(item.is_voided,false) IS FALSE
        AND UPPER(BTRIM(COALESCE(item.item_type,''))) IN
          ('SEGMENT_DELTA','EXPENSE_DELTA','ADJUSTMENT_DELTA','MILEAGE_DELTA')
        AND (UPPER(BTRIM(COALESCE(candidate.settlement_status,'')))='SETTLED'
          OR candidate.settled_at_utc IS NOT NULL
          OR UPPER(BTRIM(COALESCE(transfer.status,'')))='COMPLETED'
          OR transfer.completed_at_utc IS NOT NULL
          OR EXISTS(SELECT 1 FROM public.timesheet_pay_state_history history
            WHERE history.pay_batch_id=candidate.pay_batch_id AND history.timesheet_id=item.timesheet_id))
        AND NOT EXISTS(SELECT 1 FROM public.pay_payment_correction_items correction
          WHERE correction.pay_batch_item_id=item.id AND correction.status='APPLIED'
            AND correction.correction_item_kind IN ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL'))
    ), standard_items_page AS MATERIALIZED (
      SELECT item.* FROM standard_items item
      WHERE p_last_source_key IS NULL OR
        '20:'||p_projected_timesheet_id::text||':'||item.id::text||':99999999'>p_last_source_key
      ORDER BY item.id
      -- Keep the current parent plus one parent beyond the page look-ahead so
      -- that an exact 25-row component boundary cannot look terminal.
      LIMIT v_limit+1
    ), standard_components AS (
      SELECT item.id AS pay_batch_item_id,item.timesheet_id AS source_timesheet_id,
        item.payload,economic.item_type,economic.key_type,economic.key_value,
        economic.source_amount_ex_vat,economic.source_amount_inc_vat,
        economic.key_resolution_source,economic.key_resolution_failure_reason,
        ROW_NUMBER() OVER(PARTITION BY item.id ORDER BY economic.key_type,economic.key_value,
          economic.item_type,economic.source_amount_ex_vat,economic.source_amount_inc_vat) AS occurrence_ordinal
      FROM standard_items_page item
      LEFT JOIN LATERAL public._pay_batch_item_economic_components(
        p_pay_batch_id=>NULL::uuid,p_pay_batch_item_ids=>ARRAY[item.id]) economic ON true
    ), /* Version 1.2.8 deliberately retires the candidate-global finance-item
          discovery branch below. Finance movement authority is captured once,
          physically paged, in the GLOBAL FINANCE_ITEM_AUTHORITY stream before
          unit derivation. Keeping the superseded text inside this comment for
          one repeatable revision makes the financial formula provenance
          inspectable without leaving it in the executable query plan.
       legacy_finance_components_v127 AS (
      SELECT item.id AS pay_batch_item_id,owner_resolution.timesheet_id AS source_timesheet_id,
        to_jsonb(item)||jsonb_build_object(
          'resolved_owner_timesheet_id',owner_resolution.timesheet_id,
          'finance_case_id',COALESCE(item.finance_case_id,component.finance_case_id),
          'finance_component_id',item.finance_component_id,
          'owner_timesheet_ids',owner_resolution.owner_ids,
          'owner_candidate_ids',owner_resolution.candidate_ids,
          'owner_finance_case_ids',owner_resolution.case_ids,
          'resolution_failure',CASE
            WHEN COALESCE(cardinality(owner_resolution.owner_ids),0)=0
              THEN 'FROZEN_FINANCE_OWNER_UNRESOLVED'
            WHEN cardinality(owner_resolution.owner_ids)>1
              THEN 'FROZEN_FINANCE_OWNER_CONFLICT'
            WHEN cardinality(owner_resolution.case_ids)>1
              THEN 'FROZEN_FINANCE_CASE_CONFLICT'
            WHEN cardinality(owner_resolution.candidate_ids)<>1
              OR owner_resolution.candidate_ids[1] IS DISTINCT FROM build_row.candidate_id
              THEN 'FROZEN_FINANCE_CANDIDATE_CONFLICT'
          END) AS payload,
        UPPER(BTRIM(item.item_type)) AS item_type,UPPER(BTRIM(item.frozen_component_key_type)) AS key_type,
        BTRIM(item.frozen_component_key_value) AS key_value,
        ROUND(CASE WHEN UPPER(BTRIM(item.item_type))='OVERPAYMENT_RECOVERY' THEN -1 ELSE 1 END
          * source_amount.amount_ex_vat,2) AS source_amount_ex_vat,
        ROUND(CASE WHEN UPPER(BTRIM(item.item_type))='OVERPAYMENT_RECOVERY' THEN -1 ELSE 1 END
          * COALESCE(NULLIF(ABS(item.amount_inc_vat),0),source_amount.amount_ex_vat),2) AS source_amount_inc_vat,
        'FROZEN_COMPONENT_KEY'::text AS key_resolution_source,
        CASE WHEN UPPER(BTRIM(COALESCE(item.frozen_component_key_type,''))) NOT IN
          ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE','MANUAL_CARRY_FORWARD')
          OR NULLIF(BTRIM(COALESCE(item.frozen_component_key_value,'')),'') IS NULL
          OR (UPPER(BTRIM(item.frozen_component_key_type))='TS_DAY' AND NOT (
            item.frozen_component_key_value ~ '^\d{4}-\d{2}-\d{2}$'
            AND pg_input_is_valid(item.frozen_component_key_value,'date')
            AND CASE WHEN pg_input_is_valid(item.frozen_component_key_value,'date')
              THEN (item.frozen_component_key_value::date)::text=item.frozen_component_key_value
              ELSE false END))
          THEN 'FROZEN_ECONOMIC_KEY_INVALID' END AS key_resolution_failure_reason,
        1::bigint AS occurrence_ordinal
      FROM private.banking_pay_workbench_economic_builds build_row
      JOIN public.pay_batch_candidates candidate ON candidate.candidate_id=build_row.candidate_id
      JOIN public.pay_batch_items item ON item.pay_batch_candidate_id=candidate.id
      LEFT JOIN public.pay_finance_case_components component ON component.id=item.finance_component_id
      LEFT JOIN public.pay_advances finance_case
        ON finance_case.id=COALESCE(item.finance_case_id,component.finance_case_id)
      LEFT JOIN LATERAL (
        SELECT
          ARRAY(SELECT DISTINCT owner_id FROM (VALUES
            (item.timesheet_id),(component.linked_timesheet_id),(finance_case.linked_timesheet_id),
            (CASE WHEN COALESCE(item.frozen_source_basis_json->>'timesheet_id','')
              ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              THEN (item.frozen_source_basis_json->>'timesheet_id')::uuid END)
          ) owner(owner_id) WHERE owner_id IS NOT NULL ORDER BY owner_id) AS owner_ids,
          ARRAY(SELECT DISTINCT candidate_id FROM (VALUES
            (candidate.candidate_id),(component.candidate_id),(finance_case.candidate_id),
            (CASE WHEN COALESCE(item.frozen_source_basis_json->>'candidate_id','')
              ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              THEN (item.frozen_source_basis_json->>'candidate_id')::uuid END)
          ) owner_candidate(candidate_id) WHERE candidate_id IS NOT NULL ORDER BY candidate_id) AS candidate_ids,
          ARRAY(SELECT DISTINCT finance_case_id FROM (VALUES
            (item.finance_case_id),(component.finance_case_id),
            (CASE WHEN COALESCE(item.frozen_source_basis_json->>'finance_case_id','')
              ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              THEN (item.frozen_source_basis_json->>'finance_case_id')::uuid END)
          ) owner_case(finance_case_id) WHERE finance_case_id IS NOT NULL ORDER BY finance_case_id) AS case_ids
      ) owner_candidates ON true
      LEFT JOIN LATERAL (
        SELECT owner_candidates.owner_ids,owner_candidates.candidate_ids,owner_candidates.case_ids,
          owner_candidates.owner_ids[1] AS timesheet_id
      ) owner_resolution ON true
      LEFT JOIN projection_members member ON member.family_timesheet_id=owner_resolution.timesheet_id
      LEFT JOIN public.pay_bank_transfers transfer ON transfer.id=item.pay_bank_transfer_id
      LEFT JOIN LATERAL (
        SELECT BOOL_OR(UPPER(BTRIM(COALESCE(reservation_row.status,'')))='SETTLED'
            OR reservation_row.settled_at_utc IS NOT NULL) AS has_settled,
          ROUND(COALESCE(SUM(ABS(COALESCE(reservation_row.reserved_source_amount,
            reservation_row.reserved_amount,0))) FILTER(
              WHERE UPPER(BTRIM(COALESCE(reservation_row.status,'')))='SETTLED'
                 OR reservation_row.settled_at_utc IS NOT NULL),0),2) AS settled_source_amount
        FROM public.pay_advance_reservations reservation_row
        WHERE reservation_row.pay_batch_item_id=item.id
      ) reservation ON true
      CROSS JOIN LATERAL (SELECT ROUND(ABS(COALESCE(NULLIF(item.frozen_source_amount,0),
        NULLIF(reservation.settled_source_amount,0),NULLIF(item.amount_ex_vat,0),
        NULLIF(item.amount_inc_vat,0))),2) AS amount_ex_vat) source_amount
      WHERE build_row.id=p_build_id
        AND (item.timesheet_id IN (SELECT member_scope.family_timesheet_id FROM projection_members member_scope)
          OR item.finance_component_id IN (SELECT scoped_component.id
            FROM public.pay_finance_case_components scoped_component
            JOIN projection_members member_scope
              ON member_scope.family_timesheet_id=scoped_component.linked_timesheet_id)
          OR item.finance_case_id IN (SELECT scoped_case.id
            FROM public.pay_advances scoped_case
            JOIN projection_members member_scope
              ON member_scope.family_timesheet_id=scoped_case.linked_timesheet_id)
          OR item.timesheet_id IS NULL)
        AND (EXISTS(SELECT 1 FROM unnest(owner_resolution.owner_ids) owner(owner_id)
              JOIN projection_members scoped_member ON scoped_member.family_timesheet_id=owner.owner_id)
          OR (
          cardinality(owner_resolution.owner_ids)=0
          AND p_dependency_unit_key=(SELECT MIN(scope_row.dependency_unit_key)
            FROM private.banking_pay_workbench_economic_build_scope scope_row
            WHERE scope_row.build_id=p_build_id)
          AND p_projected_timesheet_id=(SELECT MIN(projection.timesheet_id)
            FROM private.banking_pay_workbench_economic_build_facts projection
            WHERE projection.build_id=p_build_id AND projection.fact_family='LIVE_ENTITLEMENT_INPUT'
              AND projection.source_relation='UNIT_PROJECTION'
              AND projection.dependency_unit_key=p_dependency_unit_key)
        ))
        AND COALESCE(item.is_voided,false) IS FALSE
        AND UPPER(BTRIM(COALESCE(item.item_type,''))) IN ('OVERPAYMENT_RECOVERY','UNDERPAYMENT_PAYMENT')
        AND source_amount.amount_ex_vat>0
        AND (UPPER(BTRIM(COALESCE(candidate.settlement_status,'')))='SETTLED'
          OR candidate.settled_at_utc IS NOT NULL
          OR UPPER(BTRIM(COALESCE(transfer.status,'')))='COMPLETED'
          OR transfer.completed_at_utc IS NOT NULL OR COALESCE(reservation.has_settled,false))
        AND NOT EXISTS(SELECT 1 FROM public.pay_payment_correction_items correction
          WHERE correction.pay_batch_item_id=item.id AND correction.status='APPLIED'
            AND correction.correction_item_kind IN ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL'))
        AND (p_last_source_key IS NULL OR
          '20:'||p_projected_timesheet_id::text||':'||item.id::text||':99999999'>p_last_source_key)
      ORDER BY item.id
      LIMIT v_limit+1
    ) */ finance_components AS (
      SELECT authority.source_id AS pay_batch_item_id,
        authority.timesheet_id AS source_timesheet_id,
        authority.source_payload_json AS payload,
        UPPER(BTRIM(authority.source_payload_json->>'item_type')) AS item_type,
        authority.economic_key_type AS key_type,
        authority.economic_key_value AS key_value,
        authority.amount_ex_vat AS source_amount_ex_vat,
        authority.amount_inc_vat AS source_amount_inc_vat,
        'FINANCE_ITEM_AUTHORITY'::text AS key_resolution_source,
        NULL::text AS key_resolution_failure_reason,
        1::bigint AS occurrence_ordinal
      FROM private.banking_pay_workbench_economic_build_facts authority
      JOIN projection_members member
        ON member.family_timesheet_id=authority.timesheet_id
      WHERE authority.build_id=p_build_id
        AND authority.fact_family='FINANCE_ITEM_AUTHORITY'
        AND authority.dependency_unit_key='GLOBAL'
        AND COALESCE((authority.source_payload_json->>'settled_authority')::boolean,false)
        AND COALESCE((authority.source_payload_json->>'authoritative_in_scope')::boolean,false)
        AND COALESCE((authority.source_payload_json->>'evidence_only')::boolean,false) IS FALSE
    ), components AS (
      SELECT * FROM standard_components
      UNION ALL SELECT * FROM finance_components
    ), keyed AS (
      SELECT '20:'||p_projected_timesheet_id::text||':'||component.pay_batch_item_id::text||':'||
          LPAD(component.occurrence_ordinal::text,8,'0') AS source_key,component.*
      FROM components component
    )
    SELECT keyed.source_key,md5('SETTLED:'||keyed.source_key),p_projected_timesheet_id,
      ARRAY[p_projected_timesheet_id], 'pay_batch_items'::text,keyed.pay_batch_item_id,
      UPPER(BTRIM(keyed.key_type)),BTRIM(keyed.key_value),keyed.source_amount_ex_vat,
      keyed.source_amount_inc_vat,NULL::numeric,NULL::numeric,NULL::numeric,NULL::numeric,
      jsonb_build_object('role','FROZEN_SETTLED_COMPONENT','projected_timesheet_id',p_projected_timesheet_id,
        'source_timesheet_id',keyed.source_timesheet_id,'item_type',keyed.item_type,
        'key_resolution_source',keyed.key_resolution_source,'pay_batch_item',keyed.payload,
        'finance_case_id',keyed.payload->>'finance_case_id',
        'finance_component_id',keyed.payload->>'finance_component_id',
        'resolution_failure',COALESCE(keyed.payload->>'resolution_failure',keyed.key_resolution_failure_reason,
          CASE WHEN keyed.key_type IS NULL OR keyed.key_value IS NULL THEN 'ECONOMIC_COMPONENT_MISSING' END)),
      md5(jsonb_build_object('source_key',keyed.source_key,'timesheet_id',p_projected_timesheet_id,
        'key_type',UPPER(BTRIM(keyed.key_type)),'key_value',BTRIM(keyed.key_value),
        'amount_ex_vat',keyed.source_amount_ex_vat,'amount_inc_vat',keyed.source_amount_inc_vat)::text),
      COALESCE(keyed.payload->>'resolution_failure',keyed.key_resolution_failure_reason,
        CASE WHEN keyed.key_type IS NULL OR keyed.key_value IS NULL THEN 'ECONOMIC_COMPONENT_MISSING' END)
    FROM keyed
    WHERE p_last_source_key IS NULL OR keyed.source_key>p_last_source_key
    ORDER BY keyed.source_key
    LIMIT v_limit;
    RETURN;
  END IF;

  RETURN QUERY
  WITH projection_members AS (
    SELECT DISTINCT projection.source_id AS family_timesheet_id
    FROM private.banking_pay_workbench_economic_build_facts projection
    WHERE projection.build_id=p_build_id AND projection.fact_family='LIVE_ENTITLEMENT_INPUT'
      AND projection.dependency_unit_key=p_dependency_unit_key
      AND projection.source_relation='UNIT_PROJECTION'
      AND projection.timesheet_id=p_projected_timesheet_id
      AND projection.source_id IS NOT NULL
  ), fallback_states AS MATERIALIZED (
    SELECT state.timesheet_id,state.last_settled_signature,
      COALESCE(state.last_settled_snapshot_json,'{}'::jsonb) AS snapshot
    FROM projection_members member
    JOIN public.timesheet_pay_state state ON state.timesheet_id=member.family_timesheet_id
    WHERE state.last_settled_snapshot_json<>'{}'::jsonb
      AND NOT EXISTS(SELECT 1 FROM private.banking_pay_workbench_economic_build_facts active
        WHERE active.build_id=p_build_id AND active.fact_family='FROZEN_SETTLED_COMPONENT'
          AND active.dependency_unit_key=p_dependency_unit_key
          AND active.timesheet_id=p_projected_timesheet_id)
      AND (p_last_source_key IS NULL OR
        '30:'||p_projected_timesheet_id::text||':'||state.timesheet_id::text||':~'>p_last_source_key)
    ORDER BY state.timesheet_id
    -- Include the current parent plus enough following parents to provide the
    -- complete 25-row page and one row of look-ahead after cursor filtering.
    LIMIT v_limit+1
  ), validation_failure AS (
    SELECT state.timesheet_id AS source_timesheet_id,state.last_settled_signature,
      0::bigint AS source_ordinal,
      '30:'||p_projected_timesheet_id::text||':'||state.timesheet_id::text||':00:CONTAINER' AS source_key,
      NULL::text AS raw_key_type,NULL::text AS raw_key_value,
      NULL::numeric AS amount_ex_vat,NULL::numeric AS amount_inc_vat,
      CASE WHEN jsonb_typeof(state.snapshot)<>'object' THEN 'FALLBACK_SNAPSHOT_NOT_OBJECT'
        WHEN pg_column_size(state.snapshot)>65536 THEN 'FALLBACK_SNAPSHOT_EXCEEDS_ENVELOPE'
        WHEN state.snapshot ? 'segments' AND jsonb_typeof(state.snapshot->'segments')<>'array'
          THEN 'FALLBACK_SEGMENTS_NOT_ARRAY'
        WHEN state.snapshot ? 'additional_units_json'
          AND jsonb_typeof(state.snapshot->'additional_units_json')<>'object'
          THEN 'FALLBACK_ADDITIONAL_NOT_OBJECT'
        WHEN state.snapshot ? 'adjustments' AND jsonb_typeof(state.snapshot->'adjustments')<>'array'
          THEN 'FALLBACK_ADJUSTMENTS_NOT_ARRAY' END AS raw_failure
    FROM fallback_states state
    WHERE jsonb_typeof(state.snapshot)<>'object' OR pg_column_size(state.snapshot)>65536
      OR (state.snapshot ? 'segments' AND jsonb_typeof(state.snapshot->'segments')<>'array')
      OR (state.snapshot ? 'additional_units_json'
        AND jsonb_typeof(state.snapshot->'additional_units_json')<>'object')
      OR (state.snapshot ? 'adjustments' AND jsonb_typeof(state.snapshot->'adjustments')<>'array')
    UNION ALL
    SELECT state.timesheet_id,state.last_settled_signature,segment.ordinality,
      '30:'||p_projected_timesheet_id::text||':'||state.timesheet_id::text||':10:SEGMENT:'||
        LPAD(segment.ordinality::text,12,'0'),NULL,NULL,NULL,NULL,
      CASE WHEN jsonb_typeof(segment.value)<>'object' THEN 'FALLBACK_SEGMENT_NOT_OBJECT'
        WHEN NULLIF(BTRIM(COALESCE(segment.value->>'segment_id','')),'') IS NULL
          THEN 'FALLBACK_SEGMENT_ID_MISSING'
        WHEN NULLIF(segment.value->>'exclude_from_pay','') IS NOT NULL
          AND lower(segment.value->>'exclude_from_pay') NOT IN ('true','false')
          THEN 'FALLBACK_SEGMENT_EXCLUDE_INVALID'
        WHEN lower(COALESCE(NULLIF(segment.value->>'exclude_from_pay',''),'false'))='false'
          AND COALESCE(segment.value->>'pay_amount','') !~ '^-?\d+(\.\d+)?$'
          THEN 'FALLBACK_SEGMENT_AMOUNT_INVALID'
        WHEN NULLIF(BTRIM(COALESCE(segment.value->>'date','')),'') IS NOT NULL
          AND NOT (segment.value->>'date' ~ '^\d{4}-\d{2}-\d{2}$'
            AND pg_input_is_valid(segment.value->>'date','date')
            AND CASE WHEN pg_input_is_valid(segment.value->>'date','date')
              THEN ((segment.value->>'date')::date)::text=segment.value->>'date' ELSE false END)
          THEN 'FALLBACK_SEGMENT_DATE_INVALID' END
    FROM fallback_states state
    CROSS JOIN LATERAL jsonb_array_elements(CASE
      WHEN jsonb_typeof(state.snapshot->'segments')='array' AND pg_column_size(state.snapshot)<=65536
        THEN state.snapshot->'segments' ELSE '[]'::jsonb END)
      WITH ORDINALITY segment(value,ordinality)
    WHERE jsonb_typeof(segment.value)<>'object'
      OR NULLIF(BTRIM(COALESCE(segment.value->>'segment_id','')),'') IS NULL
      OR (NULLIF(segment.value->>'exclude_from_pay','') IS NOT NULL
        AND lower(segment.value->>'exclude_from_pay') NOT IN ('true','false'))
      OR (lower(COALESCE(NULLIF(segment.value->>'exclude_from_pay',''),'false'))='false'
        AND COALESCE(segment.value->>'pay_amount','') !~ '^-?\d+(\.\d+)?$')
      OR (NULLIF(BTRIM(COALESCE(segment.value->>'date','')),'') IS NOT NULL
        AND NOT (segment.value->>'date' ~ '^\d{4}-\d{2}-\d{2}$'
          AND pg_input_is_valid(segment.value->>'date','date')
          AND CASE WHEN pg_input_is_valid(segment.value->>'date','date')
            THEN ((segment.value->>'date')::date)::text=segment.value->>'date' ELSE false END))
    UNION ALL
    SELECT state.timesheet_id,state.last_settled_signature,0,
      '30:'||p_projected_timesheet_id::text||':'||state.timesheet_id::text||':20:ADDITIONAL:'||
        LPAD(octet_length(entry.key)::text,10,'0')||':'||
        encode(convert_to(entry.key,'UTF8'),'hex'),NULL,NULL,NULL,NULL,
      CASE WHEN NULLIF(BTRIM(entry.key),'') IS NULL THEN 'FALLBACK_ADDITIONAL_CODE_MISSING'
        WHEN jsonb_typeof(entry.value)<>'object' THEN 'FALLBACK_ADDITIONAL_VALUE_NOT_OBJECT'
        WHEN NULLIF(COALESCE(entry.value->>'pay_ex_vat',entry.value->>'amount_ex_vat',''),'') IS NOT NULL
          AND COALESCE(entry.value->>'pay_ex_vat',entry.value->>'amount_ex_vat','') !~ '^-?\d+(\.\d+)?$'
          THEN 'FALLBACK_ADDITIONAL_AMOUNT_INVALID'
        WHEN EXISTS(SELECT 1 FROM unnest(ARRAY['unit_count','units_week','pay_rate','rate']) field_name
          WHERE NULLIF(entry.value->>field_name,'') IS NOT NULL
            AND entry.value->>field_name !~ '^-?\d+(\.\d+)?$')
          THEN 'FALLBACK_ADDITIONAL_RATE_INPUT_INVALID' END
    FROM fallback_states state
    CROSS JOIN LATERAL jsonb_each(CASE
      WHEN jsonb_typeof(state.snapshot->'additional_units_json')='object'
       AND pg_column_size(state.snapshot)<=65536
        THEN state.snapshot->'additional_units_json' ELSE '{}'::jsonb END) entry
    WHERE NULLIF(BTRIM(entry.key),'') IS NULL
      OR jsonb_typeof(entry.value)<>'object'
      OR (NULLIF(COALESCE(entry.value->>'pay_ex_vat',entry.value->>'amount_ex_vat',''),'') IS NOT NULL
        AND COALESCE(entry.value->>'pay_ex_vat',entry.value->>'amount_ex_vat','') !~ '^-?\d+(\.\d+)?$')
      OR EXISTS(SELECT 1 FROM unnest(ARRAY['unit_count','units_week','pay_rate','rate']) field_name
        WHERE NULLIF(entry.value->>field_name,'') IS NOT NULL
          AND entry.value->>field_name !~ '^-?\d+(\.\d+)?$')
    UNION ALL
    SELECT state.timesheet_id,state.last_settled_signature,0,
      '30:'||p_projected_timesheet_id::text||':'||state.timesheet_id::text||':30:NUMERIC',
      NULL,NULL,NULL,NULL,'FALLBACK_NUMERIC_INPUT_INVALID'
    FROM fallback_states state
    WHERE (NULLIF(state.snapshot->>'additional_pay_ex_vat','') IS NOT NULL
        AND state.snapshot->>'additional_pay_ex_vat' !~ '^-?\d+(\.\d+)?$')
      OR EXISTS(
        SELECT 1 FROM (VALUES
          (state.snapshot #>> '{expenses,travel_pay_ex_vat}'),
          (state.snapshot #>> '{expenses,accommodation_pay_ex_vat}'),
          (state.snapshot #>> '{expenses,other_pay_ex_vat}'),
          (state.snapshot #>> '{expenses,mileage_pay_ex_vat}'),
          (state.snapshot #>> '{expenses,expenses_pay_ex_vat}')
        ) numeric_value(value)
        WHERE NULLIF(numeric_value.value,'') IS NOT NULL
          AND numeric_value.value !~ '^-?\d+(\.\d+)?$')
    UNION ALL
    SELECT state.timesheet_id,state.last_settled_signature,adjustment.ordinality,
      '30:'||p_projected_timesheet_id::text||':'||state.timesheet_id::text||':40:ADJUSTMENT:'||
        LPAD(adjustment.ordinality::text,12,'0'),NULL,NULL,NULL,NULL,
      CASE WHEN jsonb_typeof(adjustment.value)<>'object' THEN 'FALLBACK_ADJUSTMENT_NOT_OBJECT'
        WHEN NULLIF(BTRIM(COALESCE(adjustment.value->>'id','')),'') IS NULL
          THEN 'FALLBACK_ADJUSTMENT_ID_MISSING'
        WHEN COALESCE(adjustment.value->>'delta_pay_ex_vat','') !~ '^-?\d+(\.\d+)?$'
          THEN 'FALLBACK_ADJUSTMENT_AMOUNT_INVALID' END
    FROM fallback_states state
    CROSS JOIN LATERAL jsonb_array_elements(CASE
      WHEN jsonb_typeof(state.snapshot->'adjustments')='array' AND pg_column_size(state.snapshot)<=65536
        THEN state.snapshot->'adjustments' ELSE '[]'::jsonb END)
      WITH ORDINALITY adjustment(value,ordinality)
    WHERE jsonb_typeof(adjustment.value)<>'object'
      OR NULLIF(BTRIM(COALESCE(adjustment.value->>'id','')),'') IS NULL
      OR COALESCE(adjustment.value->>'delta_pay_ex_vat','') !~ '^-?\d+(\.\d+)?$'
  ), segment_occurrence AS (
    SELECT state.timesheet_id AS source_timesheet_id,state.last_settled_signature,
      segment.ordinality::bigint AS source_ordinal,
      '30:'||p_projected_timesheet_id::text||':'||state.timesheet_id::text||':10:SEGMENT:'||
        LPAD(segment.ordinality::text,12,'0') AS source_key,
      CASE WHEN NULLIF(BTRIM(COALESCE(segment.value->>'date','')),'') IS NOT NULL
        THEN 'TS_DAY' ELSE 'TS_TOTAL' END AS raw_key_type,
      CASE WHEN NULLIF(BTRIM(COALESCE(segment.value->>'date','')),'') IS NOT NULL
        THEN BTRIM(segment.value->>'date') ELSE 'TOTAL' END AS raw_key_value,
      ROUND(CASE WHEN lower(COALESCE(NULLIF(segment.value->>'exclude_from_pay',''),'false'))='true'
        THEN 0::numeric ELSE (segment.value->>'pay_amount')::numeric END,2) AS amount_ex_vat,
      ROUND(CASE WHEN lower(COALESCE(NULLIF(segment.value->>'exclude_from_pay',''),'false'))='true'
        THEN 0::numeric ELSE (segment.value->>'pay_amount')::numeric END,2) AS amount_inc_vat,
      NULL::text AS raw_failure,false AS evidence_only,'SEGMENT'::text AS source_kind
    FROM fallback_states state
    CROSS JOIN LATERAL jsonb_array_elements(CASE
      WHEN jsonb_typeof(state.snapshot->'segments')='array' AND pg_column_size(state.snapshot)<=65536
        THEN state.snapshot->'segments' ELSE '[]'::jsonb END)
      WITH ORDINALITY segment(value,ordinality)
    WHERE jsonb_typeof(segment.value)='object'
      AND NULLIF(BTRIM(COALESCE(segment.value->>'segment_id','')),'') IS NOT NULL
      AND lower(COALESCE(NULLIF(segment.value->>'exclude_from_pay',''),'false')) IN ('true','false')
      AND (lower(COALESCE(NULLIF(segment.value->>'exclude_from_pay',''),'false'))='true'
        OR COALESCE(segment.value->>'pay_amount','') ~ '^-?\d+(\.\d+)?$')
      AND (NULLIF(BTRIM(COALESCE(segment.value->>'date','')),'') IS NULL OR (
        segment.value->>'date' ~ '^\d{4}-\d{2}-\d{2}$'
        AND pg_input_is_valid(segment.value->>'date','date')
        AND CASE WHEN pg_input_is_valid(segment.value->>'date','date')
          THEN ((segment.value->>'date')::date)::text=segment.value->>'date' ELSE false END))
  ), additional_occurrence AS (
    SELECT state.timesheet_id AS source_timesheet_id,state.last_settled_signature,0::bigint,
      '30:'||p_projected_timesheet_id::text||':'||state.timesheet_id::text||':20:ADDITIONAL:'||
        LPAD(octet_length(entry.key)::text,10,'0')||':'||
        encode(convert_to(entry.key,'UTF8'),'hex'),
      'ADDITIONAL_CODE'::text,UPPER(BTRIM(entry.key)),
      amount.amount_ex_vat AS amount_ex_vat,amount.amount_ex_vat AS amount_inc_vat,
      NULL::text,false,'ADDITIONAL'::text
    FROM fallback_states state
    CROSS JOIN LATERAL jsonb_each(CASE
      WHEN jsonb_typeof(state.snapshot->'additional_units_json')='object'
       AND pg_column_size(state.snapshot)<=65536
        THEN state.snapshot->'additional_units_json' ELSE '{}'::jsonb END) entry
    CROSS JOIN LATERAL (SELECT ROUND(COALESCE(
      CASE WHEN COALESCE(entry.value->>'pay_ex_vat','') ~ '^-?\d+(\.\d+)?$'
        THEN (entry.value->>'pay_ex_vat')::numeric END,
      CASE WHEN COALESCE(entry.value->>'amount_ex_vat','') ~ '^-?\d+(\.\d+)?$'
        THEN (entry.value->>'amount_ex_vat')::numeric END,
      COALESCE(CASE WHEN COALESCE(entry.value->>'unit_count','') ~ '^-?\d+(\.\d+)?$'
        THEN (entry.value->>'unit_count')::numeric END,
        CASE WHEN COALESCE(entry.value->>'units_week','') ~ '^-?\d+(\.\d+)?$'
          THEN (entry.value->>'units_week')::numeric END,0)
      * COALESCE(CASE WHEN COALESCE(entry.value->>'pay_rate','') ~ '^-?\d+(\.\d+)?$'
        THEN (entry.value->>'pay_rate')::numeric END,
        CASE WHEN COALESCE(entry.value->>'rate','') ~ '^-?\d+(\.\d+)?$'
          THEN (entry.value->>'rate')::numeric END,0),0),2) AS amount_ex_vat) amount
    WHERE jsonb_typeof(entry.value)='object' AND NULLIF(BTRIM(entry.key),'') IS NOT NULL
      AND (NULLIF(COALESCE(entry.value->>'pay_ex_vat',entry.value->>'amount_ex_vat',''),'') IS NULL
        OR COALESCE(entry.value->>'pay_ex_vat',entry.value->>'amount_ex_vat','') ~ '^-?\d+(\.\d+)?$')
      AND NOT EXISTS(SELECT 1 FROM unnest(ARRAY['unit_count','units_week','pay_rate','rate']) field_name
        WHERE NULLIF(entry.value->>field_name,'') IS NOT NULL
          AND entry.value->>field_name !~ '^-?\d+(\.\d+)?$')
      AND amount.amount_ex_vat<>0
  ), additional_total_occurrence AS (
    SELECT state.timesheet_id AS source_timesheet_id,state.last_settled_signature,0::bigint,
      '30:'||p_projected_timesheet_id::text||':'||state.timesheet_id::text||':25:ADDITIONAL_TOTAL',
      'ADDITIONAL_CODE'::text,'TOTAL'::text,
      ROUND((state.snapshot->>'additional_pay_ex_vat')::numeric,2) AS amount_ex_vat,
      ROUND((state.snapshot->>'additional_pay_ex_vat')::numeric,2) AS amount_inc_vat,
      NULL::text,false,'ADDITIONAL_TOTAL'::text
    FROM fallback_states state
    WHERE COALESCE(state.snapshot->>'additional_pay_ex_vat','') ~ '^-?\d+(\.\d+)?$'
      AND ROUND((state.snapshot->>'additional_pay_ex_vat')::numeric,2)<>0
      AND COALESCE((SELECT ROUND(SUM(existing.amount_ex_vat),2)
        FROM additional_occurrence existing
        WHERE existing.source_timesheet_id=state.timesheet_id),0)=0
  ), expense_occurrence AS (
    SELECT state.timesheet_id AS source_timesheet_id,state.last_settled_signature,0::bigint,
      '30:'||p_projected_timesheet_id::text||':'||state.timesheet_id::text||':30:EXPENSE:'||expense.key_value,
      'EXPENSE_CODE'::text,expense.key_value,
      expense.amount_ex_vat AS amount_ex_vat,expense.amount_ex_vat AS amount_inc_vat,
      NULL::text,false,'EXPENSE'::text
    FROM fallback_states state
    CROSS JOIN LATERAL (SELECT
      ROUND(CASE WHEN COALESCE(state.snapshot#>>'{expenses,travel_pay_ex_vat}','') ~ '^-?\d+(\.\d+)?$'
        THEN (state.snapshot#>>'{expenses,travel_pay_ex_vat}')::numeric ELSE 0 END,2) AS travel_ex,
      ROUND(CASE WHEN COALESCE(state.snapshot#>>'{expenses,accommodation_pay_ex_vat}','') ~ '^-?\d+(\.\d+)?$'
        THEN (state.snapshot#>>'{expenses,accommodation_pay_ex_vat}')::numeric ELSE 0 END,2) AS accommodation_ex,
      ROUND(CASE WHEN COALESCE(state.snapshot#>>'{expenses,other_pay_ex_vat}','') ~ '^-?\d+(\.\d+)?$'
        THEN (state.snapshot#>>'{expenses,other_pay_ex_vat}')::numeric ELSE 0 END,2) AS other_ex,
      ROUND(CASE WHEN COALESCE(state.snapshot#>>'{expenses,mileage_pay_ex_vat}','') ~ '^-?\d+(\.\d+)?$'
        THEN (state.snapshot#>>'{expenses,mileage_pay_ex_vat}')::numeric ELSE 0 END,2) AS mileage_ex,
      ROUND(CASE WHEN COALESCE(state.snapshot#>>'{expenses,expenses_pay_ex_vat}','') ~ '^-?\d+(\.\d+)?$'
        THEN (state.snapshot#>>'{expenses,expenses_pay_ex_vat}')::numeric ELSE 0 END,2) AS expenses_ex
    ) totals
    CROSS JOIN LATERAL (VALUES
      ('TRAVEL'::text,totals.travel_ex),('ACCOMMODATION'::text,totals.accommodation_ex),
      ('OTHER'::text,totals.other_ex),('MILEAGE'::text,totals.mileage_ex),
      ('EXPENSES'::text,CASE WHEN totals.travel_ex=0 AND totals.accommodation_ex=0
        AND totals.other_ex=0 AND totals.mileage_ex=0 THEN totals.expenses_ex ELSE 0 END)
    ) expense(key_value,amount_ex_vat)
    WHERE expense.amount_ex_vat<>0
  ), adjustment_occurrence AS (
    SELECT state.timesheet_id AS source_timesheet_id,state.last_settled_signature,
      adjustment.ordinality::bigint,
      '30:'||p_projected_timesheet_id::text||':'||state.timesheet_id::text||':40:ADJUSTMENT:'||
        LPAD(adjustment.ordinality::text,12,'0'),
      'ADJUSTMENT_CODE'::text,BTRIM(adjustment.value->>'id'),
      ROUND((adjustment.value->>'delta_pay_ex_vat')::numeric,2) AS amount_ex_vat,
      ROUND((adjustment.value->>'delta_pay_ex_vat')::numeric,2) AS amount_inc_vat,
      NULL::text,false,'ADJUSTMENT'::text
    FROM fallback_states state
    CROSS JOIN LATERAL jsonb_array_elements(CASE
      WHEN jsonb_typeof(state.snapshot->'adjustments')='array' AND pg_column_size(state.snapshot)<=65536
        THEN state.snapshot->'adjustments' ELSE '[]'::jsonb END)
      WITH ORDINALITY adjustment(value,ordinality)
    WHERE jsonb_typeof(adjustment.value)='object'
      AND NULLIF(BTRIM(COALESCE(adjustment.value->>'id','')),'') IS NOT NULL
      AND COALESCE(adjustment.value->>'delta_pay_ex_vat','') ~ '^-?\d+(\.\d+)?$'
      AND ROUND((adjustment.value->>'delta_pay_ex_vat')::numeric,2)<>0
  ), valid_occurrence AS (
    SELECT * FROM segment_occurrence
    UNION ALL SELECT * FROM additional_occurrence
    UNION ALL SELECT * FROM additional_total_occurrence
    UNION ALL SELECT * FROM expense_occurrence
    UNION ALL SELECT * FROM adjustment_occurrence
  ), evidence_occurrence AS (
    SELECT state.timesheet_id AS source_timesheet_id,state.last_settled_signature,0::bigint,
      '30:'||p_projected_timesheet_id::text||':'||state.timesheet_id::text||':99:STATE_EVIDENCE',
      'TS_TOTAL'::text,'TOTAL'::text,0::numeric,0::numeric,NULL::text,true,'STATE_EVIDENCE'::text
    FROM fallback_states state
    WHERE NOT EXISTS(SELECT 1 FROM valid_occurrence valid
        WHERE valid.source_timesheet_id=state.timesheet_id)
      AND NOT EXISTS(SELECT 1 FROM validation_failure failure
        WHERE failure.source_timesheet_id=state.timesheet_id)
  ), raw_occurrence AS (
    SELECT valid.* FROM valid_occurrence valid
    UNION ALL
    SELECT failure.source_timesheet_id,failure.last_settled_signature,failure.source_ordinal,
      failure.source_key,failure.raw_key_type,failure.raw_key_value,
      failure.amount_ex_vat,failure.amount_inc_vat,failure.raw_failure,false,'VALIDATION_FAILURE'::text
    FROM validation_failure failure
    UNION ALL SELECT evidence.* FROM evidence_occurrence evidence
  ), paged_occurrence AS MATERIALIZED (
    SELECT occurrence.* FROM raw_occurrence occurrence
    WHERE p_last_source_key IS NULL OR occurrence.source_key>p_last_source_key
    ORDER BY occurrence.source_key LIMIT v_limit
  ), resolved AS (
    SELECT occurrence.*,resolved_key.key_type,resolved_key.key_value,
      resolved_key.key_resolution_source,resolved_key.key_resolution_failure_reason
    FROM paged_occurrence occurrence
    LEFT JOIN LATERAL public._pay_policy_x_resolve_pre_draft_economic_key(
      p_timesheet_id=>p_projected_timesheet_id,
      p_live_source_json=>jsonb_build_object('timesheet_id',p_projected_timesheet_id,
        'component_key_type',occurrence.raw_key_type,'component_key_value',occurrence.raw_key_value,
        'work_date',CASE WHEN occurrence.raw_key_type='TS_DAY' THEN occurrence.raw_key_value END),
      p_item_type=>CASE WHEN occurrence.raw_key_type IN ('TS_DAY','TS_TOTAL') THEN 'SEGMENT_DELTA'
        WHEN occurrence.raw_key_type='ADJUSTMENT_CODE' THEN 'ADJUSTMENT_DELTA'
        WHEN occurrence.raw_key_type='EXPENSE_CODE' AND UPPER(occurrence.raw_key_value)='MILEAGE'
          THEN 'MILEAGE_DELTA'
        WHEN occurrence.raw_key_type IN ('ADDITIONAL_CODE','EXPENSE_CODE') THEN 'EXPENSE_DELTA' END,
      p_key_type_hint=>occurrence.raw_key_type,p_key_value_hint=>occurrence.raw_key_value,
      p_work_date=>NULL::date
    ) resolved_key ON occurrence.raw_failure IS NULL
  )
  SELECT resolved.source_key,md5('FALLBACK:'||resolved.source_key),p_projected_timesheet_id,
    ARRAY[p_projected_timesheet_id],'timesheet_pay_state'::text,resolved.source_timesheet_id,
    resolved.key_type,resolved.key_value,resolved.amount_ex_vat,resolved.amount_inc_vat,
    NULL::numeric,NULL::numeric,NULL::numeric,NULL::numeric,
    jsonb_build_object('role','PAY_STATE_FALLBACK','projected_timesheet_id',p_projected_timesheet_id,
      'source_timesheet_id',resolved.source_timesheet_id,'source_ordinal',resolved.source_ordinal,
      'source_kind',resolved.source_kind,'evidence_only',resolved.evidence_only,
      'last_settled_signature',resolved.last_settled_signature,'raw_key_type',resolved.raw_key_type,
      'raw_key_value',resolved.raw_key_value,'key_resolution_source',resolved.key_resolution_source,
      'resolution_failure',COALESCE(resolved.raw_failure,resolved.key_resolution_failure_reason)),
    md5(jsonb_build_object('source_key',resolved.source_key,'timesheet_id',p_projected_timesheet_id,
      'key_type',resolved.key_type,'key_value',resolved.key_value,
      'amount_ex_vat',resolved.amount_ex_vat,'amount_inc_vat',resolved.amount_inc_vat)::text),
    COALESCE(resolved.raw_failure,resolved.key_resolution_failure_reason,
      CASE WHEN resolved.key_type IS NULL OR resolved.key_value IS NULL THEN 'ECONOMIC_KEY_MISSING' END)
  FROM resolved
  WHERE p_last_source_key IS NULL OR resolved.source_key>p_last_source_key
  ORDER BY resolved.source_key
  LIMIT v_limit;
END;
$function$;

-- private.pay_workbench_unit_projection_v1(uuid,text)
CREATE OR REPLACE FUNCTION private.pay_workbench_unit_projection_v1(p_build_id uuid, p_dependency_unit_key text DEFAULT NULL::text)
 RETURNS TABLE(dependency_unit_key text, scope_family_key text, family_timesheet_id uuid, canonical_timesheet_id uuid, projected_timesheet_id uuid)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
WITH members AS (
  SELECT
    scope_row.dependency_unit_key,
    COALESCE(NULLIF(BTRIM(timesheet_row.booking_id),''),scope_row.timesheet_id::text) AS scope_family_key,
    scope_row.timesheet_id AS family_timesheet_id,
    scope_row.stable_ordinal,
    timesheet_row.is_current,
    timesheet_row.version,
    timesheet_row.updated_at,
    timesheet_row.created_at
  FROM private.banking_pay_workbench_economic_build_scope AS scope_row
  JOIN public.timesheets AS timesheet_row
    ON timesheet_row.timesheet_id=scope_row.timesheet_id
  WHERE scope_row.build_id=p_build_id
    AND scope_row.closure_status='SEALED'
    AND (p_dependency_unit_key IS NULL
      OR scope_row.dependency_unit_key=p_dependency_unit_key)
), canonical AS (
  SELECT DISTINCT ON (member.dependency_unit_key,member.scope_family_key)
    member.dependency_unit_key,
    member.scope_family_key,
    member.family_timesheet_id AS canonical_timesheet_id
  FROM members AS member
  WHERE member.is_current IS TRUE
  ORDER BY member.dependency_unit_key,member.scope_family_key,
    member.version DESC NULLS LAST,member.updated_at DESC NULLS LAST,
    member.created_at DESC NULLS LAST,member.family_timesheet_id
), fallback_member AS (
  SELECT DISTINCT ON (member.dependency_unit_key,member.scope_family_key)
    member.dependency_unit_key,
    member.scope_family_key,
    member.family_timesheet_id AS fallback_timesheet_id
  FROM members AS member
  ORDER BY member.dependency_unit_key,member.scope_family_key,
    member.stable_ordinal,member.family_timesheet_id
)
SELECT
  member.dependency_unit_key,
  member.scope_family_key,
  member.family_timesheet_id,
  COALESCE(canonical.canonical_timesheet_id,fallback_member.fallback_timesheet_id),
  COALESCE(canonical.canonical_timesheet_id,fallback_member.fallback_timesheet_id) AS projected_timesheet_id
FROM members AS member
LEFT JOIN canonical
  ON canonical.dependency_unit_key=member.dependency_unit_key
 AND canonical.scope_family_key=member.scope_family_key
JOIN fallback_member
  ON fallback_member.dependency_unit_key=member.dependency_unit_key
 AND fallback_member.scope_family_key=member.scope_family_key
ORDER BY member.dependency_unit_key,member.scope_family_key,
  member.family_timesheet_id;
$function$;

-- private.pay_workbench_unsent_execution_overlay_proof_page_v1(uuid,uuid[],text,uuid,jsonb)
CREATE OR REPLACE FUNCTION private.pay_workbench_unsent_execution_overlay_proof_page_v1(p_pay_batch_id uuid, p_candidate_ids uuid[], p_mode text DEFAULT 'PRE_REQUEST'::text, p_correction_request_id uuid DEFAULT NULL::uuid, p_options_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE PARALLEL RESTRICTED
 SET search_path TO ''
AS $function$
DECLARE
  v_mode text:=pg_catalog.upper(pg_catalog.btrim(COALESCE(p_mode,'PRE_REQUEST')));
  v_results jsonb:='[]'::jsonb;
  v_count integer:=0;
  v_refresh_owner_execution_operation_id uuid:=NULL::uuid;
  v_refresh_owner_proof jsonb:=pg_catalog.jsonb_build_object(
    'ok',true,'contract_version','EXECUTION_REFRESH_OWNER_PROOF_PAGE_V1',
    'candidate_count',0,'admitted_count',0,'candidate_results','[]'::jsonb
  );
  v_refresh_owner_bridge_observe_enabled boolean:=false;
  v_refresh_owner_bridge_publish_enabled boolean:=false;
BEGIN
  IF p_pay_batch_id IS NULL OR p_candidate_ids IS NULL
     OR pg_catalog.cardinality(p_candidate_ids)<1
     OR pg_catalog.cardinality(p_candidate_ids)>100
     OR v_mode NOT IN ('PRE_REQUEST','REQUEST_OWNED_CONTINUITY','OBSERVE_ONLY')
     OR (v_mode='REQUEST_OWNED_CONTINUITY' AND p_correction_request_id IS NULL)
     OR pg_catalog.jsonb_typeof(COALESCE(p_options_json,'{}'::jsonb))<>'object'
     OR p_options_json<>'{}'::jsonb THEN
    RAISE EXCEPTION 'EXECUTION_UNSENT_OVERLAY_PROOF_ARGUMENT_INVALID'
      USING ERRCODE='P0001',DETAIL=pg_catalog.jsonb_build_object(
        'code','EXECUTION_UNSENT_OVERLAY_PROOF_ARGUMENT_INVALID','mode',v_mode
      )::text;
  END IF;

  SELECT
    COALESCE((pg_catalog.to_jsonb(settings_row)
      ->>'banking_pay_execution_refresh_owner_bridge_v1_observe_enabled')::boolean,false),
    COALESCE((pg_catalog.to_jsonb(settings_row)
      ->>'banking_pay_execution_refresh_owner_bridge_v1_publish_enabled')::boolean,false)
  INTO v_refresh_owner_bridge_observe_enabled,v_refresh_owner_bridge_publish_enabled
  FROM public.settings_defaults AS settings_row
  WHERE settings_row.id=1
  LIMIT 1;

  v_refresh_owner_bridge_publish_enabled:=
    v_refresh_owner_bridge_observe_enabled
    AND v_refresh_owner_bridge_publish_enabled
    AND v_mode='PRE_REQUEST';

  IF v_refresh_owner_bridge_observe_enabled AND v_mode IN ('PRE_REQUEST','OBSERVE_ONLY') THEN
    SELECT operation_row.id
    INTO v_refresh_owner_execution_operation_id
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.operation_type='PAYMENT_EXECUTE'
      AND operation_row.status='COMPLETE'
      AND operation_row.phase='COMPLETE'
      AND operation_row.pay_batch_id=p_pay_batch_id
      AND EXISTS (
        SELECT 1
        FROM pg_catalog.unnest(p_candidate_ids) AS requested_candidate(candidate_id)
        WHERE COALESCE(
          operation_row.progress_json->'execution_unsent_overlay_chain_v2'->'candidates'
            ->requested_candidate.candidate_id::text,
          operation_row.result_json->'execution_unsent_overlay_chain_v2'->'candidates'
            ->requested_candidate.candidate_id::text
        ) IS NOT NULL
      )
    ORDER BY operation_row.completed_at_utc DESC NULLS LAST,operation_row.created_at_utc DESC,
             operation_row.id DESC
    LIMIT 1;

    IF v_refresh_owner_execution_operation_id IS NOT NULL THEN
      v_refresh_owner_proof:=private.pay_workbench_execution_refresh_owner_proof_page_v1(
        v_refresh_owner_execution_operation_id,p_pay_batch_id,p_candidate_ids,
        CASE WHEN v_mode='PRE_REQUEST' THEN 'PRE_REQUEST' ELSE 'OBSERVE_ONLY' END,
        '{}'::jsonb
      );
    END IF;
  END IF;

  WITH requested AS (
    SELECT candidate_scope.candidate_id,pg_catalog.min(candidate_scope.ordinality)::bigint AS ordinality
    FROM pg_catalog.unnest(p_candidate_ids) WITH ORDINALITY AS candidate_scope(candidate_id,ordinality)
    WHERE candidate_scope.candidate_id IS NOT NULL
    GROUP BY candidate_scope.candidate_id
  ), base AS (
    SELECT requested.ordinality,requested.candidate_id,
      batch_row.id AS pay_batch_id,batch_row.source_workbench_session_id AS session_id,
      batch_row.source_snapshot_run_id,batch_row.source_session_version,
      pg_catalog.upper(pg_catalog.btrim(COALESCE(batch_row.execution_commit_state,'NOT_SUBMITTED')))
        AS execution_commit_state,
      batch_candidate.id AS pay_batch_candidate_id,batch_candidate.settlement_status,
      batch_candidate.settled_at_utc,batch_candidate.remittance_sent_at_utc,
      draft_operation.id AS draft_operation_id,draft_scope.allocation_basis_json,
      draft_scope.allocation_basis_json->'source_publication_attestation' AS frozen_attestation,
      draft_scope.allocation_basis_json->>'source_publication_id' AS frozen_publication_id,
      current_scope.certified_preview_publication_source_publication_id AS current_publication_id,
      current_scope.certified_preview_publication_attestation_json AS current_attestation,
      current_scope.certified_preview_publication_parity_ok AS current_parity,
      COALESCE(change_counter.seq,0) AS live_source_change_seq,
      COALESCE(change_counter.scope_change_generation,0) AS live_dirty_generation,
      change_counter.scope_change_tx_token AS live_scope_change_tx_token,
      registry.dirty_generation AS registry_dirty_generation,
      registry.last_scope_change_tx_token AS registry_tx_token,
      execution_chain.operation_id AS execution_chain_operation_id,
      execution_chain.chain_receipt AS execution_chain_receipt,
      dirty_job.id AS dirty_job_id,dirty_job.status AS dirty_job_status,
      dirty_job.started_at_utc AS dirty_job_started_at_utc,
      dirty_job.scope_change_generation AS dirty_job_generation,
      dirty_job.payload_json AS dirty_payload,
      dirty_job.payload_json->'execution_overlay_contexts'->requested.candidate_id::text
        AS execution_context,
      refresh_owner_result.value AS refresh_owner_authority
    FROM requested
    JOIN public.pay_batches AS batch_row ON batch_row.id=p_pay_batch_id
    JOIN public.pay_batch_candidates AS batch_candidate
      ON batch_candidate.pay_batch_id=batch_row.id
     AND batch_candidate.candidate_id=requested.candidate_id
    LEFT JOIN LATERAL (
      SELECT operation_row.id
      FROM public.banking_pay_operations AS operation_row
      WHERE operation_row.operation_type='DRAFT_CREATE' AND operation_row.status='COMPLETE'
        AND (operation_row.pay_batch_id=batch_row.id OR EXISTS (
          SELECT 1 FROM public.banking_pay_operation_candidate_scope AS operation_scope
          WHERE operation_scope.operation_id=operation_row.id
            AND operation_scope.pay_batch_id=batch_row.id
            AND operation_scope.candidate_id=requested.candidate_id
            AND operation_scope.status NOT IN ('FAILED','CANCELLED','SUPERSEDED')
        ))
      ORDER BY operation_row.completed_at_utc DESC NULLS LAST,operation_row.created_at_utc DESC
      LIMIT 1
    ) AS draft_operation ON true
    LEFT JOIN public.banking_pay_operation_candidate_scope AS draft_scope
      ON draft_scope.operation_id=draft_operation.id
     AND draft_scope.pay_batch_id=batch_row.id
     AND draft_scope.candidate_id=requested.candidate_id
     AND draft_scope.status NOT IN ('FAILED','CANCELLED','SUPERSEDED')
    LEFT JOIN public.banking_pay_workbench_session_scope AS current_scope
      ON current_scope.session_id=batch_row.source_workbench_session_id
     AND current_scope.candidate_id=requested.candidate_id
    LEFT JOIN public.app_change_counters AS change_counter
      ON change_counter.entity_key='pay_candidate:'||requested.candidate_id::text
    LEFT JOIN private.banking_pay_workbench_candidate_scope_registry AS registry
      ON registry.candidate_id=requested.candidate_id
    LEFT JOIN LATERAL (
      SELECT operation_row.id AS operation_id,
        COALESCE(
          operation_row.progress_json->'execution_unsent_overlay_chain_v2'->'candidates'
            ->requested.candidate_id::text,
          operation_row.result_json->'execution_unsent_overlay_chain_v2'->'candidates'
            ->requested.candidate_id::text
        ) AS chain_receipt
      FROM public.banking_pay_operations AS operation_row
      WHERE operation_row.operation_type='PAYMENT_EXECUTE'
        AND operation_row.status='COMPLETE'
        AND operation_row.pay_batch_id=batch_row.id
        AND COALESCE(
          operation_row.progress_json->'execution_unsent_overlay_chain_v2'->'candidates'
            ->requested.candidate_id::text,
          operation_row.result_json->'execution_unsent_overlay_chain_v2'->'candidates'
            ->requested.candidate_id::text
        ) IS NOT NULL
      ORDER BY operation_row.completed_at_utc DESC NULLS LAST,operation_row.created_at_utc DESC
      LIMIT 1
    ) AS execution_chain ON true
    LEFT JOIN LATERAL (
      SELECT candidate_job.*
      FROM public.banking_pay_workbench_jobs AS candidate_job
      WHERE candidate_job.candidate_id=requested.candidate_id
        AND candidate_job.job_type='WORKBENCH_CANDIDATE_DIRTY_APPLY'
        AND candidate_job.status IN ('QUEUED','RUNNING','SUCCEEDED')
        AND COALESCE(candidate_job.payload_json->>'execution_overlay_causal_contract_version','')
              ='EXECUTION_UNSENT_OVERLAY_CAUSAL_V1'
        AND COALESCE(candidate_job.payload_json->'execution_overlay_contexts'
              ->requested.candidate_id::text->>'pay_batch_id','')=batch_row.id::text
      ORDER BY GREATEST(candidate_job.created_at_utc,
               COALESCE(candidate_job.updated_at_utc,candidate_job.created_at_utc)) DESC,
               candidate_job.id DESC
      LIMIT 1
    ) AS dirty_job ON true
    LEFT JOIN LATERAL (
      SELECT result_row.value
      FROM pg_catalog.jsonb_array_elements(
        COALESCE(v_refresh_owner_proof->'candidate_results','[]'::jsonb)
      ) AS result_row(value)
      WHERE result_row.value->>'candidate_id'=requested.candidate_id::text
      LIMIT 1
    ) AS refresh_owner_result ON true
  ), execution_authority AS (
    SELECT base.*,
      COALESCE(base.execution_chain_operation_id,
        CASE WHEN COALESCE(base.execution_context->>'execution_operation_id','')
        ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN (base.execution_context->>'execution_operation_id')::uuid END) AS execution_operation_id,
      COALESCE(
        CASE WHEN COALESCE(base.execution_chain_receipt->>'terminal_scope_change_tx_token','')
          ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN (base.execution_chain_receipt->>'terminal_scope_change_tx_token')::uuid END,
        CASE WHEN COALESCE(base.dirty_payload->>'execution_overlay_scope_change_tx_token','')
        ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN (base.dirty_payload->>'execution_overlay_scope_change_tx_token')::uuid END)
        AS execution_scope_change_tx_token,
      COALESCE(base.live_scope_change_tx_token,
        CASE WHEN COALESCE(base.dirty_payload->>'scope_change_tx_token','')
        ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN (base.dirty_payload->>'scope_change_tx_token')::uuid END) AS current_scope_change_tx_token
    FROM base
  ), proof AS (
    SELECT execution_authority.*,
      execution_operation.operation_type AS execution_operation_type,
      execution_operation.status AS execution_operation_status,
      execution_operation.phase AS execution_operation_phase,
      execution_operation.pay_batch_id AS execution_operation_batch_id,
      execution_tx.state AS execution_tx_state,
      execution_tx.allocated_generation AS execution_generation,
      current_tx.state AS current_tx_state,current_tx.allocated_generation AS current_generation,
      COALESCE(scope_proof.scope_count,0) AS scope_count,
      COALESCE(scope_proof.scope_item_count,0) AS scope_item_count,
      COALESCE(scope_proof.active_item_count,0) AS active_item_count,
      COALESCE(scope_proof.scope_amount,0) AS scope_amount,
      COALESCE(scope_proof.scope_item_amount,0) AS scope_item_amount,
      COALESCE(scope_proof.bad_scope_count,0) AS bad_scope_count,
      COALESCE(scope_proof.item_difference_count,0) AS item_difference_count,
      COALESCE(scope_proof.timesheet_difference_count,0) AS timesheet_difference_count,
      COALESCE(scope_proof.transfer_difference_count,0) AS transfer_difference_count,
      scope_proof.active_item_scope_digest,
      scope_proof.execution_transfer_scope_digest,
      COALESCE(scope_proof.provider_attempt_count,0) AS provider_attempt_count,
      COALESCE(scope_proof.transfer_event_count,0) AS transfer_event_count,
      COALESCE(scope_proof.unsafe_transfer_count,0) AS unsafe_transfer_count,
      COALESCE(scope_proof.timesheet_generation_mismatch_count,0)
        AS timesheet_generation_mismatch_count,
      correction_operation.id AS correction_operation_id
    FROM execution_authority
    LEFT JOIN public.banking_pay_operations AS execution_operation
      ON execution_operation.id=execution_authority.execution_operation_id
    LEFT JOIN public.banking_pay_scope_change_transactions AS execution_tx
      ON execution_tx.tx_token=execution_authority.execution_scope_change_tx_token
    LEFT JOIN public.banking_pay_scope_change_transactions AS current_tx
      ON current_tx.tx_token=execution_authority.current_scope_change_tx_token
    LEFT JOIN LATERAL (
      SELECT operation_row.id
      FROM public.banking_pay_operations AS operation_row
      WHERE p_correction_request_id IS NOT NULL
        AND operation_row.operation_type='PAYMENT_CORRECTION'
        AND operation_row.input_json->>'correction_request_id'=p_correction_request_id::text
      ORDER BY operation_row.created_at_utc,operation_row.id LIMIT 1
    ) AS correction_operation ON true
    LEFT JOIN LATERAL (
      WITH exact_scope AS (
        SELECT transfer_scope.*
        FROM public.banking_pay_operation_transfer_scope AS transfer_scope
        WHERE transfer_scope.operation_id=execution_authority.execution_operation_id
          AND transfer_scope.pay_batch_id=p_pay_batch_id
          AND EXISTS (
            SELECT 1 FROM public.banking_pay_operation_transfer_scope_items AS membership
            WHERE membership.operation_id=transfer_scope.operation_id
              AND membership.transfer_scope_id=transfer_scope.id
              AND membership.candidate_id=execution_authority.candidate_id
          )
      ), exact_membership AS (
        SELECT membership.*
        FROM public.banking_pay_operation_transfer_scope_items AS membership
        JOIN exact_scope ON exact_scope.id=membership.transfer_scope_id
        WHERE membership.operation_id=execution_authority.execution_operation_id
          AND membership.pay_batch_id=p_pay_batch_id
          AND membership.candidate_id=execution_authority.candidate_id
      ), active_items AS (
        SELECT item.id,item.timesheet_id,item.pay_bank_transfer_id,item.amount_inc_vat,
          item.item_type,item.finance_case_id,item.finance_component_id,item.reservation_id
        FROM public.pay_batch_items AS item
        JOIN public.pay_batch_candidates AS candidate_row
          ON candidate_row.id=item.pay_batch_candidate_id
        WHERE candidate_row.pay_batch_id=p_pay_batch_id
          AND candidate_row.candidate_id=execution_authority.candidate_id
          AND COALESCE(item.is_voided,false) IS NOT TRUE
      ), item_difference AS (
        (SELECT id FROM active_items EXCEPT SELECT pay_batch_item_id FROM exact_membership)
        UNION ALL
        (SELECT pay_batch_item_id FROM exact_membership EXCEPT SELECT id FROM active_items)
      ), timesheet_difference AS (
        (SELECT timesheet_id FROM active_items WHERE timesheet_id IS NOT NULL
          EXCEPT SELECT value::uuid FROM pg_catalog.jsonb_array_elements_text(
            COALESCE(execution_authority.execution_context->'timesheet_ids','[]'::jsonb)) AS x(value))
        UNION ALL
        (SELECT value::uuid FROM pg_catalog.jsonb_array_elements_text(
            COALESCE(execution_authority.execution_context->'timesheet_ids','[]'::jsonb)) AS x(value)
          EXCEPT SELECT timesheet_id FROM active_items WHERE timesheet_id IS NOT NULL)
      ), transfer_difference AS (
        (SELECT DISTINCT pay_bank_transfer_id FROM active_items WHERE pay_bank_transfer_id IS NOT NULL
          EXCEPT SELECT id::uuid FROM pg_catalog.jsonb_array_elements_text(
            COALESCE(execution_authority.execution_context->'pay_bank_transfer_ids','[]'::jsonb)) AS x(id))
        UNION ALL
        (SELECT id::uuid FROM pg_catalog.jsonb_array_elements_text(
            COALESCE(execution_authority.execution_context->'pay_bank_transfer_ids','[]'::jsonb)) AS x(id)
          EXCEPT SELECT DISTINCT pay_bank_transfer_id FROM active_items WHERE pay_bank_transfer_id IS NOT NULL)
      )
      SELECT
        (SELECT pg_catalog.count(*) FROM exact_scope)::integer AS scope_count,
        (SELECT pg_catalog.count(*) FROM exact_membership)::integer AS scope_item_count,
        (SELECT pg_catalog.count(*) FROM active_items)::integer AS active_item_count,
        (SELECT pg_catalog.round(COALESCE(pg_catalog.sum(amount),0),2) FROM exact_scope) AS scope_amount,
        (SELECT pg_catalog.round(COALESCE(pg_catalog.sum(item_amount),0),2) FROM exact_membership)
          AS scope_item_amount,
        (SELECT pg_catalog.count(*) FROM exact_scope WHERE status<>'PREPARED'
          OR provider_submit_ready IS NOT TRUE OR provider_submit_state<>'READY'
          OR provider_submit_attempt_count<>0 OR provider_submit_chunk_id IS NOT NULL
          OR provider_submit_claimed_at_utc IS NOT NULL
          OR provider_request_sending_at_utc IS NOT NULL OR provider_request_sent_at_utc IS NOT NULL
          OR provider_response_at_utc IS NOT NULL OR provider_transaction_id IS NOT NULL
          OR provider_submission_status IS NOT NULL OR provider_review_required
          OR pay_bank_transfer_id IS NULL OR prepared_item_count<=0
          OR prepared_item_count<>(SELECT pg_catalog.count(*) FROM exact_membership m
             WHERE m.transfer_scope_id=exact_scope.id)
          OR pg_catalog.round(prepared_amount_total,2)<>pg_catalog.round(amount,2)
          OR NULLIF(pg_catalog.btrim(COALESCE(prepared_scope_hash,'')),'') IS NULL
          OR NULLIF(pg_catalog.btrim(COALESCE(prepared_result_hash,'')),'') IS NULL)::integer
          AS bad_scope_count,
        (SELECT pg_catalog.count(*) FROM item_difference)::integer AS item_difference_count,
        (SELECT pg_catalog.count(*) FROM timesheet_difference)::integer AS timesheet_difference_count,
        (SELECT pg_catalog.count(*) FROM transfer_difference)::integer AS transfer_difference_count,
        pg_catalog.md5(COALESCE((SELECT pg_catalog.string_agg(
          active_items.id::text||':'||COALESCE(active_items.timesheet_id::text,'')||':'||
          COALESCE(active_items.pay_bank_transfer_id::text,'')||':'||
          COALESCE(active_items.amount_inc_vat::text,'')||':'||
          COALESCE(active_items.item_type,'')||':'||
          COALESCE(active_items.finance_case_id::text,'')||':'||
          COALESCE(active_items.finance_component_id::text,'')||':'||
          COALESCE(active_items.reservation_id::text,'')
          ,'|' ORDER BY active_items.id) FROM active_items),'')) AS active_item_scope_digest,
        pg_catalog.md5(COALESCE((SELECT pg_catalog.string_agg(
          exact_membership.transfer_scope_id::text||':'||
          exact_membership.pay_batch_item_id::text||':'||
          COALESCE(exact_scope.pay_bank_transfer_id::text,'')||':'||
          COALESCE(exact_membership.item_amount::text,'')
          ,'|' ORDER BY exact_membership.transfer_scope_id,exact_membership.pay_batch_item_id)
          FROM exact_membership
          JOIN exact_scope ON exact_scope.id=exact_membership.transfer_scope_id),''))
          AS execution_transfer_scope_digest,
        (SELECT pg_catalog.count(*) FROM public.banking_pay_operation_provider_attempts AS attempt
          WHERE attempt.operation_id=execution_authority.execution_operation_id
             OR attempt.pay_batch_id=p_pay_batch_id)::integer AS provider_attempt_count,
        (SELECT pg_catalog.count(*) FROM public.pay_bank_transfer_events AS event_row
          WHERE event_row.pay_batch_id=p_pay_batch_id)::integer AS transfer_event_count,
        (SELECT pg_catalog.count(*) FROM public.pay_bank_transfers AS transfer_row
          WHERE transfer_row.id IN (SELECT pay_bank_transfer_id FROM exact_scope)
            AND (pg_catalog.upper(pg_catalog.btrim(COALESCE(transfer_row.status,'')))<>'PENDING'
              OR transfer_row.rail_tx_id IS NOT NULL OR transfer_row.completed_at_utc IS NOT NULL
              OR pg_catalog.upper(pg_catalog.btrim(COALESCE(transfer_row.rail_state,'')))
                   NOT IN ('','LOCAL','PENDING')
              OR pg_catalog.upper(pg_catalog.btrim(COALESCE(transfer_row.failed_reason,'')))
                   IN ('PROVIDER_REJECTED','PROVIDER_UNKNOWN','PROVIDER_OUTCOME_UNKNOWN','REQUEST_SENT_LOCAL')
              OR pg_catalog.lower(pg_catalog.btrim(COALESCE(
                   transfer_row.rail_meta_json#>>'{provider_submit_diagnostic,provider_request_sent}',
                   ''
                 ))) IN ('true','t','1','yes','y','on')
              OR pg_catalog.lower(pg_catalog.btrim(COALESCE(
                   transfer_row.rail_meta_json#>>'{provider_submit_diagnostic,provider_called}',
                   ''
                 ))) IN ('true','t','1','yes','y','on')
              OR pg_catalog.lower(pg_catalog.btrim(COALESCE(
                   transfer_row.rail_meta_json#>>'{provider_submit_diagnostic,provider_response_present}',
                   ''
                 ))) IN ('true','t','1','yes','y','on')))::integer
          AS unsafe_transfer_count,
        (SELECT pg_catalog.count(*) FROM private.banking_pay_workbench_timesheet_scope_state AS state_row
          WHERE state_row.candidate_id=execution_authority.candidate_id
            AND state_row.timesheet_id IN (SELECT timesheet_id FROM active_items WHERE timesheet_id IS NOT NULL)
            AND (state_row.dirty_generation IS DISTINCT FROM execution_authority.live_dirty_generation
              OR state_row.last_scope_change_tx_token IS DISTINCT FROM execution_authority.current_scope_change_tx_token))::integer
          AS timesheet_generation_mismatch_count
    ) AS scope_proof ON true
  ), classified AS (
    SELECT proof.*,
      CASE
        WHEN proof.session_id IS NULL THEN 'EXECUTION_OVERLAY_NO_SOURCE_SESSION'
        WHEN proof.draft_operation_id IS NULL OR proof.allocation_basis_json IS NULL
          THEN 'EXECUTION_OVERLAY_DRAFT_SCOPE_MISMATCH'
        WHEN COALESCE(proof.frozen_attestation->>'attestation_version','')
              <>'CERTIFIED_SOURCE_PREVIEW_PUBLICATION_V3'
          OR COALESCE((proof.frozen_attestation->>'semantic_ready')::boolean,false) IS NOT TRUE
          OR COALESCE((proof.frozen_attestation->>'parity_complete')::boolean,false) IS NOT TRUE
          THEN 'EXECUTION_OVERLAY_PUBLICATION_MISMATCH'
        WHEN (
          proof.current_parity IS NOT TRUE
          OR proof.current_publication_id::text IS DISTINCT FROM proof.frozen_publication_id
          OR COALESCE(proof.current_attestation->>'economic_build_id','')
               IS DISTINCT FROM COALESCE(proof.frozen_attestation->>'economic_build_id','')
          OR COALESCE(proof.current_attestation->>'source_identity_digest','')
               IS DISTINCT FROM COALESCE(proof.frozen_attestation->>'source_identity_digest','')
          OR COALESCE(proof.current_attestation->>'semantic_proof_digest','')
               IS DISTINCT FROM COALESCE(proof.frozen_attestation->>'semantic_proof_digest','')
        ) AND NOT (
          v_refresh_owner_bridge_publish_enabled
          AND COALESCE((proof.refresh_owner_authority->>'admitted')::boolean,false)
          AND COALESCE(proof.refresh_owner_authority->>'currentness_basis','')
                ='EXACT_UNSENT_EXECUTION_REFRESH_OWNER'
        ) THEN 'EXECUTION_OVERLAY_PUBLICATION_MISMATCH'
        WHEN proof.execution_chain_receipt IS NOT NULL
          AND (COALESCE(proof.execution_chain_receipt->>'contract_version','')
                <>'EXECUTION_UNSENT_OVERLAY_CHAIN_V2'
            OR COALESCE((proof.execution_chain_receipt->>'closed')::boolean,false) IS NOT TRUE)
          THEN COALESCE(NULLIF(proof.execution_chain_receipt->>'rejection_reason',''),
            'EXECUTION_OVERLAY_CHAIN_NOT_CLOSED')
        WHEN proof.execution_chain_receipt IS NOT NULL
          AND (COALESCE(proof.execution_chain_receipt->>'execution_operation_id','')
                <>COALESCE(proof.execution_operation_id::text,'')
            OR COALESCE(proof.execution_chain_receipt->>'pay_batch_id','')<>p_pay_batch_id::text
            OR COALESCE(proof.execution_chain_receipt->>'candidate_id','')<>proof.candidate_id::text)
          THEN 'EXECUTION_OVERLAY_CHAIN_SCOPE_MISMATCH'
        WHEN proof.execution_chain_receipt IS NOT NULL
          AND (COALESCE(proof.execution_chain_receipt->>'draft_operation_id','')
                <>COALESCE(proof.draft_operation_id::text,'')
            OR COALESCE(proof.execution_chain_receipt->>'original_economic_build_id','')
                IS DISTINCT FROM COALESCE(proof.frozen_attestation->>'economic_build_id','')
            OR COALESCE(proof.execution_chain_receipt->>'original_source_build_run_id','')
                IS DISTINCT FROM COALESCE(
                  proof.frozen_attestation->>'original_source_build_run_id',
                  proof.allocation_basis_json->>'source_build_run_id','')
            OR COALESCE(proof.execution_chain_receipt->>'original_source_publication_id','')
                IS DISTINCT FROM COALESCE(proof.frozen_publication_id,'')
            OR COALESCE(proof.execution_chain_receipt->>'original_source_identity_digest','')
                IS DISTINCT FROM COALESCE(proof.allocation_basis_json->>'source_identity_digest','')
            OR COALESCE(proof.execution_chain_receipt->>'original_semantic_proof_digest','')
                IS DISTINCT FROM COALESCE(proof.allocation_basis_json->>'semantic_proof_digest',''))
          THEN 'EXECUTION_OVERLAY_CHAIN_DRAFT_AUTHORITY_MISMATCH'
        WHEN proof.execution_chain_receipt IS NOT NULL
          AND (COALESCE(proof.execution_chain_receipt->>'transition_count','') !~ '^\d+$'
            OR COALESCE(CASE
              WHEN COALESCE(proof.execution_chain_receipt->>'transition_count','') ~ '^\d+$'
                THEN (proof.execution_chain_receipt->>'transition_count')::integer
              END,0) NOT BETWEEN 1 AND 16)
          THEN 'EXECUTION_OVERLAY_CHAIN_TOO_LARGE'
        WHEN proof.execution_chain_receipt IS NULL AND proof.dirty_job_id IS NULL
          THEN 'EXECUTION_OVERLAY_DIRTY_JOB_MISSING'
        WHEN proof.execution_chain_receipt IS NULL AND proof.dirty_job_started_at_utc IS NOT NULL
          THEN 'EXECUTION_OVERLAY_DIRTY_JOB_ALREADY_STARTED'
        WHEN proof.execution_chain_receipt IS NULL
          AND (COALESCE(proof.dirty_payload->>'execution_overlay_causal_contract_version','')
              <>'EXECUTION_UNSENT_OVERLAY_CAUSAL_V1'
          OR COALESCE(proof.execution_context->>'contract_version','')
              <>'EXECUTION_UNSENT_OVERLAY_CONTEXT_V1')
          THEN 'EXECUTION_OVERLAY_CAUSAL_CONTEXT_MISSING'
        WHEN proof.execution_chain_receipt IS NULL AND (
          COALESCE(proof.execution_context->>'pay_batch_id','')<>p_pay_batch_id::text
          OR COALESCE(proof.execution_context->>'candidate_id','')<>proof.candidate_id::text
          OR proof.execution_operation_id IS NULL
          OR COALESCE(proof.execution_context->>'context_digest','')
               IS DISTINCT FROM pg_catalog.md5(
                 proof.execution_operation_id::text||'|'||p_pay_batch_id::text||'|'||
                 proof.candidate_id::text||'|'||
                 COALESCE((proof.execution_context->'pay_batch_candidate_ids')::text,'[]')||'|'||
                 COALESCE((proof.execution_context->'pay_batch_item_ids')::text,'[]')||'|'||
                 COALESCE((proof.execution_context->'timesheet_ids')::text,'[]')||'|'||
                 COALESCE((proof.execution_context->'transfer_scope_ids')::text,'[]')||'|'||
                 COALESCE((proof.execution_context->'pay_bank_transfer_ids')::text,'[]')||'|'||
                 COALESCE(proof.execution_context->>'source_workbench_session_id','')||'|'||
                 COALESCE(proof.execution_context->>'source_snapshot_run_id','')||'|'||
                 COALESCE(proof.execution_context->>'source_session_version','')||
                 '|EXECUTION_UNSENT_OVERLAY_CONTEXT_V1'))
          THEN 'EXECUTION_OVERLAY_CAUSAL_CONTEXT_MISMATCH'
        WHEN proof.execution_operation_type<>'PAYMENT_EXECUTE'
          OR proof.execution_operation_batch_id IS DISTINCT FROM p_pay_batch_id
          OR proof.execution_operation_phase<>'COMPLETE'
          OR proof.execution_operation_status NOT IN ('PREPARED','COMPLETE')
          THEN 'EXECUTION_OVERLAY_NOT_PRESENT'
        WHEN proof.execution_tx_state<>'FINALIZED' OR proof.execution_generation IS NULL
          THEN 'EXECUTION_OVERLAY_TRANSACTION_NOT_FINALIZED'
        WHEN proof.scope_count<1 OR proof.scope_item_count<1 OR proof.bad_scope_count<>0
          OR proof.item_difference_count<>0
          OR (proof.execution_chain_receipt IS NULL AND proof.timesheet_difference_count<>0)
          OR (proof.execution_chain_receipt IS NULL AND proof.transfer_difference_count<>0)
          OR (proof.execution_chain_receipt IS NOT NULL AND
            COALESCE(proof.execution_chain_receipt->>'active_item_scope_digest','')
              IS DISTINCT FROM COALESCE(proof.active_item_scope_digest,''))
          OR (proof.execution_chain_receipt IS NOT NULL AND
            COALESCE(proof.execution_chain_receipt->>'execution_transfer_scope_digest','')
              IS DISTINCT FROM COALESCE(proof.execution_transfer_scope_digest,''))
          THEN 'EXECUTION_OVERLAY_ITEM_SCOPE_MISMATCH'
        WHEN proof.scope_item_count<>proof.active_item_count
          OR pg_catalog.round(proof.scope_amount,2)<>pg_catalog.round(proof.scope_item_amount,2)
          THEN 'EXECUTION_OVERLAY_AMOUNT_MISMATCH'
        WHEN proof.execution_commit_state<>'NOT_SUBMITTED'
          OR proof.provider_attempt_count<>0 THEN 'EXECUTION_OVERLAY_PROVIDER_BOUNDARY_CROSSED'
        WHEN proof.unsafe_transfer_count<>0 OR proof.transfer_event_count<>0
          OR pg_catalog.upper(COALESCE(proof.settlement_status,''))='SETTLED'
          OR proof.settled_at_utc IS NOT NULL OR proof.remittance_sent_at_utc IS NOT NULL
          THEN 'EXECUTION_OVERLAY_RAIL_OR_SETTLEMENT_EVIDENCE'
        WHEN v_mode='PRE_REQUEST' AND (
          proof.current_scope_change_tx_token IS DISTINCT FROM proof.execution_scope_change_tx_token
          OR proof.current_tx_state<>'FINALIZED'
          OR proof.current_generation IS DISTINCT FROM proof.live_dirty_generation
          OR proof.execution_generation IS DISTINCT FROM proof.live_dirty_generation
          OR (proof.execution_chain_receipt IS NULL
            AND proof.dirty_job_generation IS DISTINCT FROM proof.live_dirty_generation)
          OR (proof.execution_chain_receipt IS NULL
            AND COALESCE(proof.dirty_payload->>'source_change_seq','')<>proof.live_source_change_seq::text)
          OR (proof.execution_chain_receipt IS NOT NULL
            AND COALESCE(proof.execution_chain_receipt->>'terminal_execution_generation','')
                  <>proof.live_dirty_generation::text)
          OR (proof.execution_chain_receipt IS NOT NULL
            AND COALESCE(proof.execution_chain_receipt->>'terminal_source_change_seq','')
                  <>proof.live_source_change_seq::text)
          OR proof.registry_dirty_generation IS DISTINCT FROM proof.live_dirty_generation
          OR proof.registry_tx_token IS DISTINCT FROM proof.current_scope_change_tx_token
          OR proof.timesheet_generation_mismatch_count<>0)
          THEN 'EXECUTION_OVERLAY_GENERATION_MISMATCH'
        WHEN v_mode='REQUEST_OWNED_CONTINUITY' AND (
          proof.correction_operation_id IS NULL
          OR COALESCE(proof.dirty_payload->>'correction_dirty_causal_contract_version','')
               <>'CORRECTION_OWNED_DIRTY_CAUSAL_V1'
          OR COALESCE(proof.dirty_payload->'correction_dirty_contexts'
               ->proof.candidate_id::text->>'correction_request_id','')
               <>p_correction_request_id::text
          OR COALESCE(proof.dirty_payload->'correction_dirty_contexts'
               ->proof.candidate_id::text->>'correction_operation_id','')
               <>proof.correction_operation_id::text
          OR COALESCE(proof.dirty_payload->>'request_owned_scope_change_tx_token','')
               <>COALESCE(proof.dirty_payload->>'scope_change_tx_token','')
          OR proof.current_tx_state<>'FINALIZED'
          OR proof.current_generation IS DISTINCT FROM proof.live_dirty_generation
          OR proof.dirty_job_generation IS DISTINCT FROM proof.live_dirty_generation
          OR COALESCE(proof.dirty_payload->>'source_change_seq','')<>proof.live_source_change_seq::text
          OR proof.registry_dirty_generation IS DISTINCT FROM proof.live_dirty_generation
          OR proof.registry_tx_token IS DISTINCT FROM proof.current_scope_change_tx_token
          OR proof.timesheet_generation_mismatch_count<>0)
          THEN 'EXECUTION_OVERLAY_CORRECTION_CONTINUITY_MISMATCH'
        ELSE NULL
      END AS rejection_reason
    FROM proof
  ), result_rows AS (
    SELECT classified.ordinality,pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
      'candidate_id',classified.candidate_id,
      'pay_batch_candidate_id',classified.pay_batch_candidate_id,
      'overlay_exact',classified.rejection_reason IS NULL,
      'admitted',classified.rejection_reason IS NULL,
      'currentness_basis',CASE
        WHEN v_refresh_owner_bridge_publish_enabled
          AND COALESCE((classified.refresh_owner_authority->>'admitted')::boolean,false)
          THEN 'EXACT_UNSENT_EXECUTION_REFRESH_OWNER'
        ELSE 'EXACT_UNSENT_EXECUTION_OVERLAY' END,
      'rejection_reason',classified.rejection_reason,
      'execution_operation_id',classified.execution_operation_id,
      'execution_overlay_dirty_job_id',classified.dirty_job_id,
      'execution_overlay_scope_change_tx_token',classified.execution_scope_change_tx_token,
      'execution_overlay_scope_change_generation',classified.execution_generation,
      'source_change_seq',classified.live_source_change_seq,
      'dirty_generation',classified.live_dirty_generation,
      'execution_overlay_context_digest',classified.execution_context->>'context_digest',
      'execution_overlay_chain_contract_version',classified.execution_chain_receipt->>'contract_version',
      'execution_overlay_chain_digest',classified.execution_chain_receipt->>'chain_digest',
      'execution_overlay_chain_transition_count',classified.execution_chain_receipt->'transition_count',
      'execution_refresh_owner_bridge_observed',
        v_refresh_owner_bridge_observe_enabled
          AND COALESCE((classified.refresh_owner_authority->>'admitted')::boolean,false),
      'execution_refresh_owner_bridge_published',
        v_refresh_owner_bridge_publish_enabled
          AND COALESCE((classified.refresh_owner_authority->>'admitted')::boolean,false),
      'execution_refresh_owner_authority',classified.refresh_owner_authority,
      'authority_digest',pg_catalog.md5(
        p_pay_batch_id::text||'|'||classified.candidate_id::text||'|'||
        COALESCE(classified.execution_operation_id::text,'')||'|'||
        COALESCE(classified.dirty_job_id::text,'')||'|'||
        COALESCE(classified.execution_scope_change_tx_token::text,'')||'|'||
        COALESCE(classified.execution_generation::text,'')||'|'||
        classified.live_source_change_seq::text||'|'||classified.live_dirty_generation::text||'|'||
        COALESCE(classified.execution_context->>'context_digest','')||'|'||
        COALESCE(classified.execution_chain_receipt->>'chain_digest','')||'|'||
        COALESCE(classified.refresh_owner_authority->>'proof_digest','')||'|'||
        CASE WHEN v_refresh_owner_bridge_publish_enabled
          AND COALESCE((classified.refresh_owner_authority->>'admitted')::boolean,false)
          THEN 'EXACT_UNSENT_EXECUTION_REFRESH_OWNER'
          ELSE 'EXACT_UNSENT_EXECUTION_OVERLAY' END||'|'||
        (classified.rejection_reason IS NULL)::text||'|EXECUTION_UNSENT_OVERLAY_PROOF_PAGE_V1')
    )) AS result_json
    FROM classified
  )
  SELECT COALESCE(pg_catalog.jsonb_agg(result_json ORDER BY ordinality),'[]'::jsonb),
         pg_catalog.count(*)::integer
  INTO v_results,v_count
  FROM result_rows;

  RETURN pg_catalog.jsonb_build_object(
    'ok',true,'contract_version','EXECUTION_UNSENT_OVERLAY_PROOF_PAGE_V1',
    'mode',v_mode,'pay_batch_id',p_pay_batch_id,'candidate_count',v_count,
    'admitted_count',(SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_array_elements(v_results) AS r(value)
      WHERE COALESCE((r.value->>'admitted')::boolean,false)),
    'candidate_results',v_results,
    'policy_x_authority_scope','POST_DRAFT_FROZEN_PAYMENT_PROOF_PLUS_EXACT_UNSENT_EXECUTION_OVERLAY'
  );
END;
$function$;

-- related_counts_v2(text,uuid)
CREATE OR REPLACE FUNCTION public.related_counts_v2(p_entity text, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_entity text := lower(coalesce(p_entity,''));
begin
  if p_id is null then
    raise exception 'related_counts_v2: p_id is required';
  end if;

  -- ------------------------------------------------------------
  -- CANDIDATE
  -- ------------------------------------------------------------
   if v_entity = 'candidate' then
    return (
      with tsfin_rows as (
        select tf.timesheet_id, tf.client_id
        from public.timesheets_financials tf
        where tf.is_current = true
          and tf.candidate_id = p_id
      ),
      contract_rows as (
        select c.id as contract_id, c.client_id
        from public.contracts c
        where c.candidate_id = p_id
      ),
          -- ✅ Timesheets count MUST match the related list source (v_timesheets_summary),
      -- otherwise contract_weeks can point at revoked/non-current timesheet_ids and overcount.
      ts_view as (
        select v.timesheet_id, v.client_id
        from public.v_timesheets_summary v
        where v.candidate_id = p_id
      ),

      timesheets_total as (
        select count(*)::int as total
        from public.v_timesheets_summary v2
        where v2.candidate_id = p_id
      ),

      clients_distinct as (
        select distinct tr.client_id
        from tsfin_rows tr
        where tr.client_id is not null
        union
        select distinct cr.client_id
        from contract_rows cr
        where cr.client_id is not null
      ),

      contracts_total as (
        select count(*)::int as total
        from contract_rows
      ),

      umbrella_count as (
        select
          case
            when upper(coalesce(c.pay_method::text, '')) = 'UMBRELLA' and c.umbrella_id is not null then 1
            else 0
          end::int as total
        from public.candidates c
        where c.id = p_id
        limit 1
      ),

      invoice_timesheet_ids as (
        select distinct tv.timesheet_id
        from ts_view tv
        where tv.timesheet_id is not null
      ),

      invoice_ids as (
        select distinct il.invoice_id
        from public.invoice_lines il
        where il.timesheet_id in (select iti.timesheet_id from invoice_timesheet_ids iti)
          and il.invoice_id is not null
      )

      select jsonb_build_object(
        'timesheets', coalesce((select total from timesheets_total), 0),
        'invoices',   coalesce((select count(*)::int from invoice_ids), 0),
        'clients',    coalesce((select count(*)::int from clients_distinct), 0),
        'contracts',  coalesce((select total from contracts_total), 0),
        'umbrella',   coalesce((select total from umbrella_count), 0)
      )
    );
  end if;


  -- ------------------------------------------------------------
  -- TIMESHEET (segment-safe invoice count)
  -- ------------------------------------------------------------
  if v_entity = 'timesheet' then
    return (
      with cur_tf as (
        select tf.candidate_id, tf.client_id
        from public.timesheets_financials tf
        where tf.is_current = true
          and tf.timesheet_id = p_id
        limit 1
      ),
      inv_ids as (
        select distinct il.invoice_id
        from public.invoice_lines il
        where il.timesheet_id = p_id
          and il.invoice_id is not null
      ),
      inv_count as (
        select count(*)::int as total
        from inv_ids
      ),
      contract_from_ts as (
        select ts.contract_id
        from public.timesheets ts
        where ts.timesheet_id = p_id
        limit 1
      ),
      contract_from_cw as (
        select cw.contract_id
        from public.contract_weeks cw
        where cw.id = p_id
        limit 1
      ),
      contract_id as (
        select contract_id from contract_from_ts
        union
        select contract_id from contract_from_cw
        limit 1
      ),
      cand_from_contract as (
        select c.candidate_id, c.client_id
        from public.contracts c
        where c.id in (select contract_id from contract_id)
        limit 1
      ),
      resolved_candidate as (
        select
          coalesce((select candidate_id from cur_tf),
                   (select candidate_id from cand_from_contract)) as candidate_id
      ),
      resolved_client as (
        select
          coalesce((select client_id from cur_tf),
                   (select client_id from cand_from_contract)) as client_id
      ),
      umbrella_count as (
        select
          case
            when upper(coalesce(c.pay_method::text, '')) = 'UMBRELLA' and c.umbrella_id is not null then 1
            else 0
          end::int as total
        from public.candidates c
        where c.id = (select candidate_id from resolved_candidate)
        limit 1
      ),
      series_count as (
        -- "series" = number of OTHER contract_week timesheets in same contract/week (adjustments)
        select
          case
            when cw.contract_id is null or cw.week_ending_date is null then 0
            else greatest(0,
              (select count(*)::int
               from public.contract_weeks cw2
               where cw2.contract_id = cw.contract_id
                 and cw2.week_ending_date = cw.week_ending_date
                 and cw2.timesheet_id is not null
              ) - 1
            )
          end::int as total
        from public.contract_weeks cw
        where cw.timesheet_id = p_id
        limit 1
      )
      select jsonb_build_object(
        'candidate', case when (select candidate_id from resolved_candidate) is null then 0 else 1 end,
        'client',    case when (select client_id from resolved_client) is null then 0 else 1 end,
        'invoice',   coalesce((select total from inv_count), 0),
        'umbrella',  coalesce((select total from umbrella_count), 0),
        'contract',  case when (select contract_id from contract_id) is null then 0 else 1 end,
        'series',    coalesce((select total from series_count), 0)
      )
    );
  end if;

  -- ------------------------------------------------------------
  -- INVOICE (segment-safe timesheets + candidates)
  -- ------------------------------------------------------------
  if v_entity = 'invoice' then
    return (
      with ts_ids as (
        select distinct il.timesheet_id
        from public.invoice_lines il
        where il.invoice_id = p_id
          and il.timesheet_id is not null
      ),
      ts_count as (
        select count(*)::int as total
        from ts_ids
      ),
      cand_ids as (
        select distinct tf.candidate_id
        from public.timesheets_financials tf
        where tf.is_current = true
          and tf.timesheet_id in (select timesheet_id from ts_ids)
          and tf.candidate_id is not null
      ),
      cand_count as (
        select count(*)::int as total
        from cand_ids
      ),
      umb_ids as (
        select distinct c.umbrella_id
        from public.candidates c
        where c.id in (select candidate_id from cand_ids)
          and upper(coalesce(c.pay_method::text,'')) = 'UMBRELLA'
          and c.umbrella_id is not null
      ),
      umb_count as (
        select count(*)::int as total
        from umb_ids
      )
      select jsonb_build_object(
        'timesheets', coalesce((select total from ts_count), 0),
        'candidates', coalesce((select total from cand_count), 0),
        'client',     1,
        'umbrellas',  coalesce((select total from umb_count), 0)
      )
    );
  end if;

  -- ------------------------------------------------------------
  -- CLIENT
  -- ------------------------------------------------------------
  if v_entity = 'client' then
    return (
      with tsfin_rows as (
        select tf.timesheet_id, tf.candidate_id
        from public.timesheets_financials tf
        where tf.is_current = true
          and tf.client_id = p_id
      ),
      contract_rows as (
        select c.id as contract_id, c.candidate_id
        from public.contracts c
        where c.client_id = p_id
      ),
           -- ✅ Timesheets count MUST match the related list source (v_timesheets_summary),
      -- otherwise contract_weeks can point at revoked/non-current timesheet_ids and overcount.
      timesheets_total as (
        select count(*)::int as total
        from public.v_timesheets_summary v
        where v.client_id = p_id
      ),

      cand_distinct as (
        select distinct tr.candidate_id
        from tsfin_rows tr
        where tr.candidate_id is not null
        union
        select distinct cr.candidate_id
        from contract_rows cr
        where cr.candidate_id is not null
      ),

      contracts_total as (
        select count(*)::int as total
        from contract_rows
      ),
      invoices_total as (
        select count(*)::int as total
        from public.invoices i
        where i.client_id = p_id
      )
      select jsonb_build_object(
        'timesheets', coalesce((select total from timesheets_total), 0),
        'invoices',   coalesce((select total from invoices_total), 0),
        'candidates', coalesce((select count(*)::int from cand_distinct), 0),
        'contracts',  coalesce((select total from contracts_total), 0)
      )
    );
  end if;


  -- ------------------------------------------------------------
  -- CONTRACT
  -- ------------------------------------------------------------
  if v_entity = 'contract' then
    return (
      with con as (
        select c.candidate_id, c.client_id
        from public.contracts c
        where c.id = p_id
        limit 1
      ),
      timesheets_total as (
        select count(*)::int as total
        from public.v_timesheets_summary s
        where s.contract_id = p_id
      ),
      umbrella_count as (
        select
          case
            when upper(coalesce(c.pay_method::text, '')) = 'UMBRELLA' and c.umbrella_id is not null then 1
            else 0
          end::int as total
        from public.candidates c
        where c.id = (select candidate_id from con)
        limit 1
      )
      select jsonb_build_object(
        'candidate', case when (select candidate_id from con) is null then 0 else 1 end,
        'client',    case when (select client_id from con) is null then 0 else 1 end,
        'timesheets', coalesce((select total from timesheets_total), 0),
        'umbrella',  coalesce((select total from umbrella_count), 0)
      )
    );
  end if;

  -- ------------------------------------------------------------
  -- UMBRELLA (segment-safe invoice count)
  -- ------------------------------------------------------------
   if v_entity = 'umbrella' then
    return (
      with cand_ids as (
        select distinct c.id as candidate_id
        from public.candidates c
        where c.umbrella_id = p_id
      ),
      cand_count as (
        select count(*)::int as total
        from cand_ids
      ),
      contract_rows as (
        select c.id as contract_id
        from public.contracts c
        where c.candidate_id in (select ci.candidate_id from cand_ids ci)
      ),
      contract_ids as (
        select cr.contract_id
        from contract_rows cr
      ),
      contract_weeks as (
        select cw.id as contract_week_id, cw.timesheet_id, cw.contract_id
        from public.contract_weeks cw
        where cw.contract_id in (select cd.contract_id from contract_ids cd)
      ),

        -- ✅ Timesheets count MUST match the related list source (v_timesheets_summary),
      -- otherwise contract_weeks can point at revoked/non-current timesheet_ids and overcount.
      timesheets_total as (
        select count(*)::int as total
        from public.v_timesheets_summary v
        where v.candidate_id in (select ci.candidate_id from cand_ids ci)
      ),

      invoice_timesheet_ids as (
        select distinct v2.timesheet_id
        from public.v_timesheets_summary v2
        where v2.candidate_id in (select ci2.candidate_id from cand_ids ci2)
          and v2.timesheet_id is not null
      ),

      inv_ids as (
        select distinct il.invoice_id
        from public.invoice_lines il
        where il.timesheet_id in (select iti.timesheet_id from invoice_timesheet_ids iti)
          and il.invoice_id is not null
      ),

      invoices_total as (
        select count(*)::int as total
        from inv_ids
      )
      select jsonb_build_object(
        'candidates', coalesce((select total from cand_count), 0),
        'timesheets', coalesce((select total from timesheets_total), 0),
        'invoices',   coalesce((select total from invoices_total), 0)
      )
    );
  end if;


  -- ------------------------------------------------------------
  -- REMITTANCE
  -- ------------------------------------------------------------
  if v_entity = 'remittance' then
    return (
      with ts_ids as (
        select distinct ae.object_id_text
        from public.audit_events ae
        where ae.correlation_id = p_id::text
          and ae.reason = 'REMITTANCE'
          and ae.object_type = 'timesheet'
          and ae.object_id_text is not null
      ),
      ts_count as (
        select count(*)::int as total
        from ts_ids
      ),
      cand_exists as (
        select exists(
          select 1
          from public.audit_events ae
          where ae.correlation_id = p_id::text
            and ae.reason = 'REMITTANCE'
            and ae.object_type = 'candidate'
        ) as ok
      )
      select jsonb_build_object(
        'timesheets', coalesce((select total from ts_count), 0),
        'candidate',  case when (select ok from cand_exists) then 1 else 0 end
      )
    );
  end if;

  raise exception 'related_counts_v2: unsupported entity=%', p_entity;
end;
$function$;

-- related_list_v2(text,uuid,text,integer,integer)
CREATE OR REPLACE FUNCTION public.related_list_v2(p_entity text, p_id uuid, p_type text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_entity text := lower(coalesce(p_entity,''));
  v_type text := lower(coalesce(p_type,''));
  v_limit int := greatest(1, least(coalesce(p_limit, 20), 100));
  v_offset int := greatest(0, coalesce(p_offset, 0));
  v_total int := 0;
  v_items jsonb := '[]'::jsonb;
begin
  if p_id is null then
    raise exception 'related_list_v2: p_id is required';
  end if;

  -- ------------------------------------------------------------
  -- TIMESHEET -> INVOICES (segment-safe + ref/issue summary)
  -- ------------------------------------------------------------
  if v_entity = 'timesheet' and (v_type = 'invoice' or v_type = 'invoices') then
    with inv_ids as (
      select distinct il.invoice_id
      from public.invoice_lines il
      where il.timesheet_id = p_id
        and il.invoice_id is not null
    ),
    inv_total as (
      select count(*)::int as total
      from inv_ids
    ),
    page as (
      select i.*
      from public.invoices i
      join inv_ids x on x.invoice_id = i.id
      order by i.issued_at_utc desc nulls last, i.id desc
      limit v_limit offset v_offset
    ),
    -- all timesheets on each invoice
    inv_ts_all as (
      select distinct il.invoice_id, il.timesheet_id
      from public.invoice_lines il
      where il.invoice_id in (select invoice_id from inv_ids)
        and il.timesheet_id is not null
    ),
    -- worked timesheets on each invoice (hours/additional only)
    inv_ts_worked as (
      select distinct il.invoice_id, il.timesheet_id
      from public.invoice_lines il
      where il.invoice_id in (select invoice_id from inv_ids)
        and il.timesheet_id is not null
        and upper(coalesce(il.meta_json->>'line_type','')) in (
          'HOURS_DAILY','HOURS_WEEKLY','ADDITIONAL_RATE','ADDITIONAL_RATE_DAILY'
        )
    ),
    inv_ref_stats as (
      select
        x.invoice_id,

        -- issue-time policy enabled for any worked TS (contract override aware)
        coalesce(bool_or(coalesce(pc.reference_number_required_to_issue_invoice,false)), false) as refs_required_to_issue,

        -- issue-time missing refs (contract override aware; uses LOCKED segment logic for SEGMENTS mode)
        coalesce(bool_or(coalesce(pc.issue_missing_reference,false)), false) as issue_blocked_missing_refs,
        coalesce(sum(case when coalesce(pc.issue_missing_reference,false) then coalesce(pc.issue_missing_reference_count,0) else 0 end),0)::int
          as issue_missing_reference_count,
        coalesce(
          jsonb_agg(distinct pc.timesheet_id::text) filter (where coalesce(pc.issue_missing_reference,false)),
          '[]'::jsonb
        ) as issue_missing_timesheet_ids,

        -- invoicing-time missing refs (precheck blocker; uses UNLOCKED segment logic for SEGMENTS mode)
        coalesce(bool_or(upper(coalesce(pc_all.precheck_status,'')) = 'BLOCK_NO_REFERENCE'), false) as invoicing_blocked_missing_refs,
        coalesce(
          jsonb_agg(distinct pc_all.timesheet_id::text) filter (where upper(coalesce(pc_all.precheck_status,'')) = 'BLOCK_NO_REFERENCE'),
          '[]'::jsonb
        ) as invoicing_missing_timesheet_ids

      from (select distinct invoice_id from inv_ids) x
      left join inv_ts_worked w
        on w.invoice_id = x.invoice_id
      left join public.v_ts_invoice_precheck pc
        on pc.timesheet_id = w.timesheet_id

      left join inv_ts_all a
        on a.invoice_id = x.invoice_id
      left join public.v_ts_invoice_precheck pc_all
        on pc_all.timesheet_id = a.timesheet_id

      group by x.invoice_id
    ),
    payload as (
      select
        (select total from inv_total) as total,
        coalesce(jsonb_agg(
          jsonb_build_object(
            'id', p.id,
            'invoice_no', p.invoice_no,
            'client_id', p.client_id,
            'issued_at_utc', p.issued_at_utc,
            'due_at_utc', p.due_at_utc,
            'status', p.status,
            'subtotal_ex_vat', p.subtotal_ex_vat,
            'vat_amount', p.vat_amount,
            'total_inc_vat', p.total_inc_vat,
            'invoice_pdf_r2_key', p.invoice_pdf_r2_key,
            'header_snapshot_json', p.header_snapshot_json,
            'on_hold_reason', p.on_hold_reason,
            'paid_at_utc', p.paid_at_utc,

            -- ✅ new summary flags for UI consistency (segment-safe)
            'refs_required_to_issue', coalesce(s.refs_required_to_issue,false),
            'issue_blocked_missing_refs', coalesce(s.issue_blocked_missing_refs,false),
            'issue_missing_reference_count', coalesce(s.issue_missing_reference_count,0),
            'issue_missing_timesheet_ids', coalesce(s.issue_missing_timesheet_ids,'[]'::jsonb),
            'invoicing_blocked_missing_refs', coalesce(s.invoicing_blocked_missing_refs,false),
            'invoicing_missing_timesheet_ids', coalesce(s.invoicing_missing_timesheet_ids,'[]'::jsonb)
          )
        ), '[]'::jsonb) as items
      from page p
      left join inv_ref_stats s
        on s.invoice_id = p.id
    )
    select payload.total, payload.items
    into v_total, v_items
    from payload;

    return jsonb_build_object('items', v_items, 'total', coalesce(v_total, 0));
  end if;

  -- ------------------------------------------------------------
  -- INVOICE -> TIMESHEETS (segment-safe)
  -- ------------------------------------------------------------
  if v_entity = 'invoice' and v_type = 'timesheets' then
    with ts_ids as (
      select distinct il.timesheet_id
      from public.invoice_lines il
      where il.invoice_id = p_id
        and il.timesheet_id is not null
    ),
    ts_total as (
      select count(*)::int as total
      from ts_ids
    ),
    page as (
      select s.*
      from public.v_timesheets_summary s
      join ts_ids x on x.timesheet_id = s.timesheet_id
      order by s.week_ending_date desc nulls last, s.client_name asc nulls last, s.candidate_name asc nulls last, s.timesheet_id::text
      limit v_limit offset v_offset
    )
    select
      (select total from ts_total) as total,
      coalesce(jsonb_agg(to_jsonb(page.*)), '[]'::jsonb) as items
    into v_total, v_items
    from page;

    return jsonb_build_object('items', v_items, 'total', coalesce(v_total, 0));
  end if;

  -- ------------------------------------------------------------
  -- CANDIDATE -> INVOICES (segment-safe + ref/issue summary)
  -- ------------------------------------------------------------
  if v_entity = 'candidate' and v_type = 'invoices' then
    with ts_ids as (
      -- Current TSFIN timesheets for candidate
      select distinct tf.timesheet_id
      from public.timesheets_financials tf
      where tf.is_current = true
        and tf.candidate_id = p_id
        and tf.timesheet_id is not null

      union

      -- Any timesheets linked via contracts for candidate (covers stale/non-current TSFIN)
      select distinct ts.timesheet_id
      from public.timesheets ts
      join public.contracts c on c.id = ts.contract_id
      where c.candidate_id = p_id
        and ts.timesheet_id is not null
    ),
    inv_ids as (
      select distinct il.invoice_id
      from public.invoice_lines il
      where il.timesheet_id in (select timesheet_id from ts_ids)
        and il.invoice_id is not null
    ),
    inv_total as (
      select count(*)::int as total
      from inv_ids
    ),
    page as (
      select i.*
      from public.invoices i
      join inv_ids x on x.invoice_id = i.id
      order by i.issued_at_utc desc nulls last, i.id desc
      limit v_limit offset v_offset
    ),
    inv_ts_all as (
      select distinct il.invoice_id, il.timesheet_id
      from public.invoice_lines il
      where il.invoice_id in (select invoice_id from inv_ids)
        and il.timesheet_id is not null
    ),
    inv_ts_worked as (
      select distinct il.invoice_id, il.timesheet_id
      from public.invoice_lines il
      where il.invoice_id in (select invoice_id from inv_ids)
        and il.timesheet_id is not null
        and upper(coalesce(il.meta_json->>'line_type','')) in (
          'HOURS_DAILY','HOURS_WEEKLY','ADDITIONAL_RATE','ADDITIONAL_RATE_DAILY'
        )
    ),
    inv_ref_stats as (
      select
        x.invoice_id,

        coalesce(bool_or(coalesce(pc.reference_number_required_to_issue_invoice,false)), false) as refs_required_to_issue,
        coalesce(bool_or(coalesce(pc.issue_missing_reference,false)), false) as issue_blocked_missing_refs,
        coalesce(sum(case when coalesce(pc.issue_missing_reference,false) then coalesce(pc.issue_missing_reference_count,0) else 0 end),0)::int
          as issue_missing_reference_count,
        coalesce(
          jsonb_agg(distinct pc.timesheet_id::text) filter (where coalesce(pc.issue_missing_reference,false)),
          '[]'::jsonb
        ) as issue_missing_timesheet_ids,

        coalesce(bool_or(upper(coalesce(pc_all.precheck_status,'')) = 'BLOCK_NO_REFERENCE'), false) as invoicing_blocked_missing_refs,
        coalesce(
          jsonb_agg(distinct pc_all.timesheet_id::text) filter (where upper(coalesce(pc_all.precheck_status,'')) = 'BLOCK_NO_REFERENCE'),
          '[]'::jsonb
        ) as invoicing_missing_timesheet_ids

      from (select distinct invoice_id from inv_ids) x
      left join inv_ts_worked w
        on w.invoice_id = x.invoice_id
      left join public.v_ts_invoice_precheck pc
        on pc.timesheet_id = w.timesheet_id

      left join inv_ts_all a
        on a.invoice_id = x.invoice_id
      left join public.v_ts_invoice_precheck pc_all
        on pc_all.timesheet_id = a.timesheet_id

      group by x.invoice_id
    )
    select
      (select total from inv_total) as total,
      coalesce(jsonb_agg(
        jsonb_build_object(
          'id', p.id,
          'invoice_no', p.invoice_no,
          'client_id', p.client_id,
          'issued_at_utc', p.issued_at_utc,
          'due_at_utc', p.due_at_utc,
          'status', p.status,
          'subtotal_ex_vat', p.subtotal_ex_vat,
          'vat_amount', p.vat_amount,
          'total_inc_vat', p.total_inc_vat,
          'invoice_pdf_r2_key', p.invoice_pdf_r2_key,
          'header_snapshot_json', p.header_snapshot_json,
          'on_hold_reason', p.on_hold_reason,
          'paid_at_utc', p.paid_at_utc,

          'refs_required_to_issue', coalesce(s.refs_required_to_issue,false),
          'issue_blocked_missing_refs', coalesce(s.issue_blocked_missing_refs,false),
          'issue_missing_reference_count', coalesce(s.issue_missing_reference_count,0),
          'issue_missing_timesheet_ids', coalesce(s.issue_missing_timesheet_ids,'[]'::jsonb),
          'invoicing_blocked_missing_refs', coalesce(s.invoicing_blocked_missing_refs,false),
          'invoicing_missing_timesheet_ids', coalesce(s.invoicing_missing_timesheet_ids,'[]'::jsonb)
        )
      ), '[]'::jsonb) as items
    into v_total, v_items
    from page p
    left join inv_ref_stats s
      on s.invoice_id = p.id;

    return jsonb_build_object('items', v_items, 'total', coalesce(v_total, 0));
  end if;

  -- ------------------------------------------------------------
  -- UMBRELLA -> INVOICES (segment-safe + ref/issue summary)
  -- ------------------------------------------------------------
  if v_entity = 'umbrella' and v_type = 'invoices' then
    with cand_ids as (
      select distinct c.id as candidate_id
      from public.candidates c
      where c.umbrella_id = p_id
        and upper(coalesce(c.pay_method::text, '')) = 'UMBRELLA'
    ),
    ts_ids as (
      select distinct tf.timesheet_id
      from public.timesheets_financials tf
      where tf.is_current = true
        and tf.candidate_id in (select candidate_id from cand_ids)
        and tf.timesheet_id is not null
    ),
    inv_ids as (
      select distinct il.invoice_id
      from public.invoice_lines il
      where il.timesheet_id in (select timesheet_id from ts_ids)
        and il.invoice_id is not null
    ),
    inv_total as (
      select count(*)::int as total
      from inv_ids
    ),
    page as (
      select i.*
      from public.invoices i
      join inv_ids x on x.invoice_id = i.id
      order by i.issued_at_utc desc nulls last, i.id desc
      limit v_limit offset v_offset
    ),
    inv_ts_all as (
      select distinct il.invoice_id, il.timesheet_id
      from public.invoice_lines il
      where il.invoice_id in (select invoice_id from inv_ids)
        and il.timesheet_id is not null
    ),
    inv_ts_worked as (
      select distinct il.invoice_id, il.timesheet_id
      from public.invoice_lines il
      where il.invoice_id in (select invoice_id from inv_ids)
        and il.timesheet_id is not null
        and upper(coalesce(il.meta_json->>'line_type','')) in (
          'HOURS_DAILY','HOURS_WEEKLY','ADDITIONAL_RATE','ADDITIONAL_RATE_DAILY'
        )
    ),
    inv_ref_stats as (
      select
        x.invoice_id,

        coalesce(bool_or(coalesce(pc.reference_number_required_to_issue_invoice,false)), false) as refs_required_to_issue,
        coalesce(bool_or(coalesce(pc.issue_missing_reference,false)), false) as issue_blocked_missing_refs,
        coalesce(sum(case when coalesce(pc.issue_missing_reference,false) then coalesce(pc.issue_missing_reference_count,0) else 0 end),0)::int
          as issue_missing_reference_count,
        coalesce(
          jsonb_agg(distinct pc.timesheet_id::text) filter (where coalesce(pc.issue_missing_reference,false)),
          '[]'::jsonb
        ) as issue_missing_timesheet_ids,

        coalesce(bool_or(upper(coalesce(pc_all.precheck_status,'')) = 'BLOCK_NO_REFERENCE'), false) as invoicing_blocked_missing_refs,
        coalesce(
          jsonb_agg(distinct pc_all.timesheet_id::text) filter (where upper(coalesce(pc_all.precheck_status,'')) = 'BLOCK_NO_REFERENCE'),
          '[]'::jsonb
        ) as invoicing_missing_timesheet_ids

      from (select distinct invoice_id from inv_ids) x
      left join inv_ts_worked w
        on w.invoice_id = x.invoice_id
      left join public.v_ts_invoice_precheck pc
        on pc.timesheet_id = w.timesheet_id

      left join inv_ts_all a
        on a.invoice_id = x.invoice_id
      left join public.v_ts_invoice_precheck pc_all
        on pc_all.timesheet_id = a.timesheet_id

      group by x.invoice_id
    )
    select
      (select total from inv_total) as total,
      coalesce(jsonb_agg(
        jsonb_build_object(
          'id', p.id,
          'invoice_no', p.invoice_no,
          'client_id', p.client_id,
          'issued_at_utc', p.issued_at_utc,
          'due_at_utc', p.due_at_utc,
          'status', p.status,
          'subtotal_ex_vat', p.subtotal_ex_vat,
          'vat_amount', p.vat_amount,
          'total_inc_vat', p.total_inc_vat,
          'invoice_pdf_r2_key', p.invoice_pdf_r2_key,
          'header_snapshot_json', p.header_snapshot_json,
          'on_hold_reason', p.on_hold_reason,
          'paid_at_utc', p.paid_at_utc,

          'refs_required_to_issue', coalesce(s.refs_required_to_issue,false),
          'issue_blocked_missing_refs', coalesce(s.issue_blocked_missing_refs,false),
          'issue_missing_reference_count', coalesce(s.issue_missing_reference_count,0),
          'issue_missing_timesheet_ids', coalesce(s.issue_missing_timesheet_ids,'[]'::jsonb),
          'invoicing_blocked_missing_refs', coalesce(s.invoicing_blocked_missing_refs,false),
          'invoicing_missing_timesheet_ids', coalesce(s.invoicing_missing_timesheet_ids,'[]'::jsonb)
        )
      ), '[]'::jsonb) as items
    into v_total, v_items
    from page p
    left join inv_ref_stats s
      on s.invoice_id = p.id;

    return jsonb_build_object('items', v_items, 'total', coalesce(v_total, 0));
  end if;

  raise exception 'related_list_v2: unsupported (entity=%, type=%)', p_entity, p_type;
end;
$function$;

-- rpc_changes_ping(jsonb)
CREATE OR REPLACE FUNCTION public.rpc_changes_ping(p_last_seen jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_last_seen jsonb := COALESCE(p_last_seen, '{}'::jsonb);
  v_seqs jsonb := '{}'::jsonb;
  v_changed text[] := ARRAY[]::text[];
  v_prev bigint := 0;
  v_cur bigint := 0;
  v_counter_record record;
  v_actor_user_id uuid := NULL::uuid;
  v_last_alert_hash text := NULL::text;
  v_cached_alert_hash text := 'banking_alert_signal:v3:' || MD5('');
  v_cached_summary_hash text := 'banking_alert_summary:v3:' || MD5('');
  v_cached_unacknowledged_count integer := 0;
  v_cached_highest_severity text := NULL::text;
  v_cached_highest_label text := NULL::text;
  v_watched_batch_ids jsonb := '[]'::jsonb;
  v_watched_batch_signals jsonb := '[]'::jsonb;
  v_explicit_entity_keys jsonb := '[]'::jsonb;
  v_ping_context text := NULL::text;
  v_has_watched_batch_ids boolean := false;
  v_is_banking_pay_mode boolean := false;
  v_allow_generic_global_scan boolean := false;
  v_app_counter_mode text := 'SKIPPED';
  v_result jsonb := '{}'::jsonb;
  v_service boolean:=coalesce(auth.role(),'')='service_role';
BEGIN
  PERFORM public.banking_pay_hot_path_budget_apply('CHANGES_PING');

  IF COALESCE(jsonb_typeof(v_last_seen), 'null') <> 'object' THEN
    v_last_seen := '{}'::jsonb;
  END IF;

  v_ping_context := UPPER(NULLIF(BTRIM(COALESCE(
    v_last_seen ->> '__changes_ping_context',
    v_last_seen ->> '__route_context',
    v_last_seen ->> 'route_context',
    v_last_seen ->> '__context',
    v_last_seen ->> 'context',
    v_last_seen ->> '__mode',
    v_last_seen ->> 'mode',
    ''
  )), ''));

  IF v_ping_context IS NULL THEN
    v_ping_context := 'UNSPECIFIED';
  END IF;

  BEGIN
    v_actor_user_id := NULLIF(BTRIM(COALESCE(v_last_seen ->> '__banking_actor_user_id', '')), '')::uuid;
  EXCEPTION WHEN OTHERS THEN
    v_actor_user_id := NULL::uuid;
  END;

  IF NOT v_service THEN
    IF auth.uid() IS NULL THEN
      RAISE EXCEPTION USING ERRCODE='42501',
        MESSAGE='AUTHENTICATED_ACTOR_REQUIRED';
    END IF;
    IF v_actor_user_id IS NOT NULL
       AND v_actor_user_id IS DISTINCT FROM auth.uid() THEN
      RAISE EXCEPTION USING ERRCODE='42501',
        MESSAGE='AUTHENTICATED_ACTOR_MISMATCH';
    END IF;
    v_actor_user_id:=auth.uid();
    IF NOT EXISTS(
      SELECT 1 FROM public.tms_users u
      WHERE u.id=v_actor_user_id AND u.is_active
        AND lower(btrim(coalesce(u.role,'')))='admin') THEN
      RAISE EXCEPTION USING ERRCODE='42501',
        MESSAGE='ADMINISTRATOR_PERMISSION_REQUIRED';
    END IF;
  END IF;

  v_last_alert_hash := NULLIF(BTRIM(COALESCE(
    v_last_seen ->> '__banking_alert_hash',
    v_last_seen ->> 'banking_alert_hash',
    ''
  )), '');

  IF jsonb_typeof(v_last_seen -> '__watched_pay_batch_ids') = 'array' THEN
    v_watched_batch_ids := v_last_seen -> '__watched_pay_batch_ids';
  ELSIF jsonb_typeof(v_last_seen -> 'watched_pay_batch_ids') = 'array' THEN
    v_watched_batch_ids := v_last_seen -> 'watched_pay_batch_ids';
  ELSIF jsonb_typeof(v_last_seen -> 'watched_batches') = 'array' THEN
    v_watched_batch_ids := v_last_seen -> 'watched_batches';
  ELSE
    v_watched_batch_ids := '[]'::jsonb;
  END IF;

  IF COALESCE(jsonb_typeof(v_watched_batch_ids), 'null') = 'array' THEN
    v_has_watched_batch_ids := jsonb_array_length(v_watched_batch_ids) > 0;
  ELSE
    v_has_watched_batch_ids := false;
  END IF;

  IF jsonb_typeof(v_last_seen -> '__watched_entity_keys') = 'array' THEN
    v_explicit_entity_keys := v_last_seen -> '__watched_entity_keys';
  ELSIF jsonb_typeof(v_last_seen -> 'watched_entity_keys') = 'array' THEN
    v_explicit_entity_keys := v_last_seen -> 'watched_entity_keys';
  ELSIF jsonb_typeof(v_last_seen -> '__entity_keys') = 'array' THEN
    v_explicit_entity_keys := v_last_seen -> '__entity_keys';
  ELSIF jsonb_typeof(v_last_seen -> 'entity_keys') = 'array' THEN
    v_explicit_entity_keys := v_last_seen -> 'entity_keys';
  ELSE
    v_explicit_entity_keys := '[]'::jsonb;
  END IF;

  v_is_banking_pay_mode :=
       v_actor_user_id IS NOT NULL
    OR v_has_watched_batch_ids
    OR v_ping_context IN (
      'BANKING',
      'BANKING_PAY',
      'BANKING_PAY_LIST',
      'BANKING_PAY_MODAL',
      'BANKING_PAY_PREVIEW',
      'BANKING_PAY_WATCH',
      'BANKING_PAY_BATCH_WATCH',
      'BANKING_PAY_CHANGES_PING',
      'PAY_BATCH_WATCH',
      'PAY_BATCH_MODAL',
      'PAY_BATCH_LIST'
    );

  v_allow_generic_global_scan :=
       v_is_banking_pay_mode IS NOT TRUE
   AND v_ping_context IN ('GENERIC_APP_COUNTERS', 'APP_CHANGE_COUNTERS', 'GLOBAL_APP_CHANGES', 'NON_BANKING_APP_CHANGES')
   AND LOWER(BTRIM(COALESCE(
      v_last_seen ->> '__allow_global_app_change_counter_scan',
      v_last_seen ->> 'allow_global_app_change_counter_scan',
      'false'
   ))) IN ('true', '1', 'yes', 'y', 'on');


  IF COALESCE(jsonb_typeof(v_explicit_entity_keys), 'null') = 'array'
     AND jsonb_array_length(v_explicit_entity_keys) > 0 THEN
    v_app_counter_mode := 'EXPLICIT_CAPPED_KEYS';

    FOR v_counter_record IN
      WITH raw_entity_keys AS (
        SELECT entity_key_entry.value,
               entity_key_entry.ordinality
        FROM jsonb_array_elements(COALESCE(v_explicit_entity_keys, '[]'::jsonb)) WITH ORDINALITY AS entity_key_entry(value, ordinality)
        LIMIT 25
      ),
      parsed_entity_keys AS (
        SELECT
          CASE
            WHEN jsonb_typeof(raw_entity_keys.value) = 'string'
              THEN NULLIF(BTRIM(TRIM(BOTH '"' FROM raw_entity_keys.value::text)), '')
            WHEN jsonb_typeof(raw_entity_keys.value) = 'object'
              THEN NULLIF(BTRIM(COALESCE(raw_entity_keys.value->>'entity_key', raw_entity_keys.value->>'key', raw_entity_keys.value->>'name', '')), '')
            ELSE NULL::text
          END AS entity_key,
          CASE
            WHEN jsonb_typeof(raw_entity_keys.value) = 'object'
             AND COALESCE(raw_entity_keys.value->>'known_seq', raw_entity_keys.value->>'seq', raw_entity_keys.value->>'last_seen_seq', '') ~ '^[0-9]{1,18}$'
              THEN COALESCE(raw_entity_keys.value->>'known_seq', raw_entity_keys.value->>'seq', raw_entity_keys.value->>'last_seen_seq')::bigint
            ELSE NULL::bigint
          END AS known_seq,
          raw_entity_keys.ordinality
        FROM raw_entity_keys
      ),
      requested_entity_keys AS (
        SELECT DISTINCT ON (parsed_entity_keys.entity_key)
          parsed_entity_keys.entity_key,
          parsed_entity_keys.known_seq,
          parsed_entity_keys.ordinality
        FROM parsed_entity_keys
        WHERE parsed_entity_keys.entity_key IS NOT NULL
          AND LENGTH(parsed_entity_keys.entity_key) <= 200
        ORDER BY parsed_entity_keys.entity_key, parsed_entity_keys.ordinality
      )
      SELECT requested_entity_keys.entity_key,
             requested_entity_keys.known_seq,
             COALESCE(change_counter.seq, 0) AS seq
      FROM requested_entity_keys
      LEFT JOIN public.app_change_counters AS change_counter
        ON change_counter.entity_key = requested_entity_keys.entity_key
      ORDER BY requested_entity_keys.ordinality
    LOOP
      v_cur := COALESCE(v_counter_record.seq, 0);

      IF v_counter_record.known_seq IS NOT NULL THEN
        v_prev := COALESCE(v_counter_record.known_seq, 0);
      ELSE
        BEGIN
          v_prev := COALESCE((v_last_seen ->> v_counter_record.entity_key)::bigint, 0);
        EXCEPTION WHEN OTHERS THEN
          v_prev := 0;
        END;
      END IF;

      v_seqs := v_seqs || jsonb_build_object(v_counter_record.entity_key, v_cur);

      IF v_cur > v_prev THEN
        v_changed := array_append(v_changed, v_counter_record.entity_key);
      END IF;
    END LOOP;
  ELSIF v_allow_generic_global_scan THEN
    v_app_counter_mode := 'EXPLICIT_NON_BANKING_GLOBAL_SCAN';

    FOR v_counter_record IN
      SELECT change_counter.entity_key, change_counter.seq
      FROM public.app_change_counters AS change_counter
      ORDER BY change_counter.entity_key
    LOOP
      v_cur := COALESCE(v_counter_record.seq, 0);
      v_prev := 0;

      BEGIN
        v_prev := COALESCE((v_last_seen ->> v_counter_record.entity_key)::bigint, 0);
      EXCEPTION WHEN OTHERS THEN
        v_prev := 0;
      END;

      v_seqs := v_seqs || jsonb_build_object(v_counter_record.entity_key, v_cur);

      IF v_cur > v_prev THEN
        v_changed := array_append(v_changed, v_counter_record.entity_key);
      END IF;
    END LOOP;
  ELSE
    v_app_counter_mode := CASE
      WHEN v_is_banking_pay_mode THEN 'SKIPPED_FOR_BANKING_PAY'
      ELSE 'SKIPPED_NO_EXPLICIT_KEYS'
    END;
  END IF;

  v_result := jsonb_build_object(
    'server_utc', now(),
    'seqs', v_seqs,
    'changed', to_jsonb(v_changed),
    'changes_ping_context', v_ping_context,
    'banking_pay_mode', COALESCE(v_is_banking_pay_mode, false),
    'app_change_counter_mode', v_app_counter_mode,
    'app_change_counter_cap', CASE WHEN v_app_counter_mode = 'EXPLICIT_CAPPED_KEYS' THEN 25 ELSE NULL::integer END
  );

  IF v_actor_user_id IS NOT NULL THEN
    SELECT
      COALESCE(alert_summary.alert_hash, v_cached_alert_hash),
      COALESCE(alert_summary.summary_hash, v_cached_summary_hash),
      COALESCE(alert_summary.unacknowledged_count, 0),
      alert_summary.highest_severity,
      alert_summary.highest_label
    INTO
      v_cached_alert_hash,
      v_cached_summary_hash,
      v_cached_unacknowledged_count,
      v_cached_highest_severity,
      v_cached_highest_label
    FROM public.banking_alert_display_summary AS alert_summary
    WHERE alert_summary.actor_user_id = v_actor_user_id;

    IF NOT FOUND THEN
      v_cached_alert_hash := 'banking_alert_signal:v3:' || MD5('');
      v_cached_summary_hash := 'banking_alert_summary:v3:' || MD5('');
      v_cached_unacknowledged_count := 0;
      v_cached_highest_severity := NULL::text;
      v_cached_highest_label := NULL::text;
    END IF;

    v_result := v_result || jsonb_build_object(
      'banking_alert_hash', v_cached_alert_hash,
      'banking_alert_summary_signature', v_cached_summary_hash,
      'banking_alert_summary_changed', COALESCE(v_last_alert_hash IS DISTINCT FROM v_cached_alert_hash, true),
      'banking_unacknowledged_alert_count', COALESCE(v_cached_unacknowledged_count, 0),
      'grouped_banking_unacknowledged_alert_count', COALESCE(v_cached_unacknowledged_count, 0),
      'banking_highest_alert_severity', COALESCE(v_cached_highest_severity, ''),
      'banking_highest_alert_label', COALESCE(v_cached_highest_label, ''),
      'banking_alert_summary_included', false,
      'banking_alert_summary', NULL::jsonb
    );
  END IF;

  IF COALESCE(jsonb_typeof(v_watched_batch_ids), 'null') = 'array' THEN
    WITH raw_watched_batches AS (
      SELECT watched_batch.value,
             watched_batch.ordinality
      FROM jsonb_array_elements(COALESCE(v_watched_batch_ids, '[]'::jsonb)) WITH ORDINALITY AS watched_batch(value, ordinality)
      LIMIT 25
    ),
    parsed_watched_batches AS (
      SELECT
        CASE
          WHEN jsonb_typeof(raw_watched_batches.value) = 'string'
           AND TRIM(BOTH '"' FROM raw_watched_batches.value::text) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN TRIM(BOTH '"' FROM raw_watched_batches.value::text)::uuid
          WHEN jsonb_typeof(raw_watched_batches.value) = 'object'
           AND COALESCE(raw_watched_batches.value->>'pay_batch_id', raw_watched_batches.value->>'id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN COALESCE(raw_watched_batches.value->>'pay_batch_id', raw_watched_batches.value->>'id')::uuid
          ELSE NULL::uuid
        END AS pay_batch_id,
        CASE
          WHEN jsonb_typeof(raw_watched_batches.value) = 'object'
           AND COALESCE(raw_watched_batches.value->>'known_version', raw_watched_batches.value->>'live_signal_version', '') ~ '^[0-9]{1,18}$'
            THEN COALESCE(raw_watched_batches.value->>'known_version', raw_watched_batches.value->>'live_signal_version')::bigint
          ELSE NULL::bigint
        END AS known_version,
        raw_watched_batches.ordinality
      FROM raw_watched_batches
    ),
    requested_watched_batches AS (
      SELECT DISTINCT ON (parsed_watched_batches.pay_batch_id)
        parsed_watched_batches.pay_batch_id,
        parsed_watched_batches.known_version,
        parsed_watched_batches.ordinality
      FROM parsed_watched_batches
      WHERE parsed_watched_batches.pay_batch_id IS NOT NULL
      ORDER BY parsed_watched_batches.pay_batch_id, parsed_watched_batches.ordinality
      LIMIT 25
    )
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'pay_batch_id', requested_watched_batches.pay_batch_id::text,
      'known_version', requested_watched_batches.known_version,
      'live_signal_version', COALESCE(batch_signal.version, 0),
      'payment_status_version', COALESCE(batch_signal.payment_status_version, 0),
      'correction_progress_version', COALESCE(batch_signal.correction_progress_version, 0),
      'alert_version', COALESCE(batch_signal.alert_version, 0),
      'overview_version', COALESCE(batch_signal.overview_version, 0),
      'last_status_hash', batch_signal.last_status_hash,
      'last_alert_hash', batch_signal.last_alert_hash,
      'changed_since_version', requested_watched_batches.known_version IS NOT NULL AND COALESCE(batch_signal.version, 0) > requested_watched_batches.known_version
    ) ORDER BY requested_watched_batches.ordinality), '[]'::jsonb)
    INTO v_watched_batch_signals
    FROM requested_watched_batches
    LEFT JOIN public.banking_pay_batch_change_signals AS batch_signal
      ON batch_signal.pay_batch_id = requested_watched_batches.pay_batch_id;

    v_result := v_result || jsonb_build_object(
      'watched_batch_signals', COALESCE(v_watched_batch_signals, '[]'::jsonb),
      'watched_batch_signal_hash', 'watched_batch_signals:v2:' || MD5(COALESCE(v_watched_batch_signals::text, '[]')),
      'watched_batch_cap', 25
    );
  END IF;

  -- Invoice operation watches are independent of Banking Pay and are resolved in one capped set query.
  WITH RECURSIVE raw_watch AS MATERIALIZED (
    SELECT value,ordinality
    FROM jsonb_array_elements(
      CASE
        WHEN jsonb_typeof(v_last_seen->'watched_invoice_operation_ids')='array'
          THEN v_last_seen->'watched_invoice_operation_ids'
        WHEN jsonb_typeof(v_last_seen->'__watched_invoice_operation_ids')='array'
          THEN v_last_seen->'__watched_invoice_operation_ids'
        ELSE '[]'::jsonb
      END
    ) WITH ORDINALITY x(value,ordinality)
    LIMIT 100
  ),
  parsed AS MATERIALIZED (
    SELECT CASE
      WHEN jsonb_typeof(value)='string'
       AND pg_input_is_valid(trim(both '"' from value::text),'uuid')
        THEN trim(both '"' from value::text)::uuid
      WHEN jsonb_typeof(value)='object'
       AND pg_input_is_valid(coalesce(value->>'operation_id',value->>'id',''),'uuid')
        THEN coalesce(value->>'operation_id',value->>'id')::uuid
      END operation_id,
      CASE WHEN jsonb_typeof(value)='object'
        AND pg_input_is_valid(coalesce(value->>'known_change_seq',value->>'change_seq',''),'bigint')
        THEN coalesce(value->>'known_change_seq',value->>'change_seq')::bigint
        WHEN pg_input_is_valid(coalesce(v_last_seen->>'invoice_operations_seq',''),'bigint')
          THEN(v_last_seen->>'invoice_operations_seq')::bigint
        ELSE 0 END known_seq,
      ordinality
    FROM raw_watch
  ),
  requested AS MATERIALIZED (
    SELECT DISTINCT ON (operation_id) operation_id,known_seq,ordinality
    FROM parsed WHERE operation_id IS NOT NULL ORDER BY operation_id,ordinality
  ),
  actor AS MATERIALIZED (
    SELECT coalesce(auth.role(),'')='service_role' is_service,auth.uid() actor_id,
      exists(select 1 from public.tms_users u
        where u.id=auth.uid() and u.is_active and lower(btrim(coalesce(u.role,'')))='admin') is_admin
  ),
  authorised_ops AS MATERIALIZED (
    SELECT r.ordinality,r.known_seq,o.*
    FROM requested r JOIN public.invoice_operations o ON o.id=r.operation_id
    CROSS JOIN actor a
    WHERE a.is_service or a.is_admin or o.actor_user_id=a.actor_id
  ),
  descendants(root_id,id,depth,path) AS MATERIALIZED (
    select o.id,ch.id,1,array[o.id,ch.id]::uuid[]
    from authorised_ops o
    join public.invoice_operations ch on ch.parent_operation_id=o.id
    union all
    select d.root_id,ch.id,d.depth+1,d.path||ch.id
    from descendants d
    join public.invoice_operations ch on ch.parent_operation_id=d.id
    where not ch.id=any(d.path)
  ),
  expected_purpose AS MATERIALIZED (
    select o.id operation_id,case
      when o.operation_type='ISSUE_INVOICES' then 'FINAL_ISSUE'
      when o.entity_type='TIMESHEET' then 'TIMESHEET'
      when upper(coalesce(o.input_json->>'purpose','')) in(
        'DRAFT_PREVIEW','FINAL_ISSUE','TIMESHEET')
        then upper(o.input_json->>'purpose')
      when o.entity_type='INVOICE' and exists(
        select 1 from public.invoices i
        where i.id=o.entity_id and i.status in('ISSUED','PAID'))
        then 'FINAL_ISSUE'
      else 'DRAFT_PREVIEW' end purpose
    from authorised_ops o
  ),
  document_candidates AS MATERIALIZED (
    select o.id operation_id,v.id,v.purpose,v.r2_key,v.status,v.created_at_utc
    from authorised_ops o join public.invoice_document_versions v on v.operation_id=o.id
    union all
    select d.root_id,v.id,v.purpose,v.r2_key,v.status,v.created_at_utc
    from descendants d
    join public.invoice_document_versions v on v.operation_id=d.id
    union all
    select o.id,v.id,v.purpose,v.r2_key,v.status,v.created_at_utc
    from authorised_ops o
    join public.invoice_operation_chunks c on c.operation_id=o.id and c.chunk_type='ISSUE_INVOICE'
    join public.invoice_document_versions v on v.id=case
      when coalesce(c.payload_json->>'final_document_version_id','') ~*
        '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        then(c.payload_json->>'final_document_version_id')::uuid end
    union all
    select o.id,v.id,v.purpose,v.r2_key,v.status,v.created_at_utc
    from authorised_ops o join public.invoices i
      on o.entity_type='INVOICE' and i.id=o.entity_id
    join public.invoice_document_versions v
      on v.id in(i.preview_document_version_id,i.issued_document_version_id)
    union all
    select o.id,v.id,v.purpose,v.r2_key,v.status,v.created_at_utc
    from authorised_ops o join public.timesheets t
      on o.entity_type='TIMESHEET' and t.timesheet_id=o.entity_id and t.is_current
    join public.invoice_document_versions v on v.id=t.current_document_version_id
  ),
  selected_documents AS MATERIALIZED (
    select distinct on(c.operation_id) c.*
    from document_candidates c
    join expected_purpose p on p.operation_id=c.operation_id and p.purpose=c.purpose
    order by c.operation_id,case c.status when 'READY' then 0 else 1 end,
      c.created_at_utc desc,c.id desc
  ),
  descendant_change AS MATERIALIZED (
    select d.root_id,
      greatest(max(ch.change_seq),0)::bigint descendant_change_seq,
      bool_or(ch.status in(
        'COMPLETE','FAILED','DEAD_LETTER','BLOCKED','CANCELLED','SUPERSEDED'))
        descendant_terminal
    from descendants d
    join public.invoice_operations ch on ch.id=d.id
    group by d.root_id
  ),
  effective_ops AS MATERIALIZED (
    select o.*,greatest(o.change_seq,coalesce(dc.descendant_change_seq,0))
        effective_change_seq,
      coalesce(dc.descendant_terminal,false) descendant_terminal
    from authorised_ops o
    left join descendant_change dc on dc.root_id=o.id
  ),
  changed_ops AS (
    SELECT o.*,d.id document_version_id,d.r2_key,d.status document_status
    FROM effective_ops o
    LEFT JOIN selected_documents d ON d.operation_id=o.id
    WHERE o.effective_change_seq>o.known_seq
  )
  SELECT v_result||jsonb_build_object(
    'invoice_operations_seq',
      coalesce((select max(effective_change_seq) from effective_ops),0),
    'watched_invoice_operations',coalesce(jsonb_agg(jsonb_build_object(
      'operation_id',o.id,'change_seq',o.effective_change_seq,
      'root_change_seq',o.change_seq,'status',o.status,'phase',o.phase,
      'progress',o.progress_json,'entity_type',o.entity_type,'entity_id',o.entity_id,
      'document_version_id',o.document_version_id,
      'ready_key',case when o.document_status='READY' then o.r2_key end,
      'error_code',o.error_json->>'code',
      'error_summary',coalesce(o.error_json->>'summary',o.error_json->>'message'),
      'notify',o.status in(
        'COMPLETE','FAILED','DEAD_LETTER','BLOCKED','CANCELLED','SUPERSEDED')
        or o.descendant_terminal or o.document_status='READY'
    ) order by o.ordinality),'[]'::jsonb),
    'watched_invoice_operation_cap',100
  ) INTO v_result
  FROM changed_ops o;

  RETURN v_result;
END;
$function$;

-- rpc_smoke_test()
CREATE OR REPLACE FUNCTION public.rpc_smoke_test()
 RETURNS text
 LANGUAGE sql
AS $function$
  select 'SMOKE_V1'::text;
$function$;

-- set_candidate_job_titles_updated_at()
CREATE OR REPLACE FUNCTION public.set_candidate_job_titles_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
